CREATE OR REPLACE FUNCTION public.dpdi_get_published_page(_tenant_id uuid, _setup_id uuid, _dataset_id uuid, _after_page integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.dataset.read',_request_context_id);d private.dpdi_published_datasets%ROWTYPE;p private.dpdi_job_pages%ROWTYPE;
BEGIN
 SELECT * INTO d FROM private.dpdi_published_datasets WHERE id=_dataset_id AND tenant_id=_tenant_id AND setup_id=_setup_id;
 IF d.id IS NULL OR _after_page<0 OR private.data_prep_pipeline_scope_allows(actor,_tenant_id,d.pipeline_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,d.data_source_id,'view') IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=d.job_id AND private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dpdi.current_published_page_source_reader_required' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=d.job_id AND NOT private.dpd_original_viewable(i.original_file_id)) THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset_id',d.id,'state','unavailable','wire',NULL,'rows',NULL,'content_sha256',d.content_sha256);END IF;
 SELECT * INTO p FROM private.dpdi_job_pages WHERE job_id=d.job_id AND sequence>_after_page ORDER BY sequence LIMIT 1;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset_id',d.id,'state','available','wire',p.wire,'rows',d.rows::text,'page_rows',p.row_count,'sequence',p.sequence,'sha256',p.sha256,'content_sha256',d.content_sha256,'manifest_id',d.manifest_id,'representation','dpdi_approved_prepare_v1','upload_id',NULL);
END $function$

CREATE OR REPLACE FUNCTION public.tg_reference_data_row_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  table_tenant uuid;
  keys text[];
  key_payload jsonb;
BEGIN
  SELECT tenant_id, key_columns INTO table_tenant, keys
  FROM public.reference_data_tables
  WHERE id = NEW.table_id;
  IF table_tenant IS NULL OR table_tenant <> NEW.tenant_id THEN
    RAISE EXCEPTION 'Reference row table must belong to the same tenant';
  END IF;
  IF coalesce(array_length(keys, 1), 0) = 0 THEN
    RAISE EXCEPTION 'Reference table must define at least one key column';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(keys) AS key_name
    WHERE NOT (NEW.row_data ? key_name)
       OR NEW.row_data -> key_name IS NULL
       OR btrim(NEW.row_data ->> key_name) = ''
  ) THEN
    RAISE EXCEPTION 'Reference row is missing a required key value';
  END IF;
  SELECT jsonb_agg(NEW.row_data -> key_name ORDER BY ordinal)
  INTO key_payload
  FROM unnest(keys) WITH ORDINALITY AS ordered_keys(key_name, ordinal);
  NEW.key_hash := encode(digest(key_payload::text, 'sha256'), 'hex');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_copilot_dispatch_binding(_provider_id uuid, _tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid(); l public.llm_providers%ROWTYPE; c public.ai_model_catalog%ROWTYPE; i public.ai_provider_instances%ROWTYPE;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 IF _tenant_id IS NULL THEN
   IF NOT coalesce(private.is_platform_admin(actor),false) AND NOT coalesce(private.is_platform_super_admin(actor),false) THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active) THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 SELECT * INTO l FROM public.llm_providers WHERE id=_provider_id;
 IF NOT FOUND OR l.is_active IS DISTINCT FROM true OR l.tenant_id IS DISTINCT FROM _tenant_id
   OR l.scope::text IS DISTINCT FROM (CASE WHEN _tenant_id IS NULL THEN 'platform' ELSE 'tenant' END)
   OR l.provider_instance_id IS NULL OR l.model_catalog_id IS NULL THEN RAISE EXCEPTION 'copilot.binding_required'; END IF;
 SELECT * INTO c FROM public.ai_model_catalog WHERE id=l.model_catalog_id;
 IF NOT FOUND OR c.provider_instance_id IS DISTINCT FROM l.provider_instance_id OR c.model_key IS DISTINCT FROM l.model
   OR c.approval_status IS DISTINCT FROM 'approved' OR c.availability_status IS NULL
   OR c.availability_status NOT IN ('available','limited') THEN RAISE EXCEPTION 'copilot.binding_required'; END IF;
 SELECT * INTO i FROM public.ai_provider_instances WHERE id=l.provider_instance_id;
 IF NOT FOUND OR i.tenant_id IS DISTINCT FROM _tenant_id OR i.status IS DISTINCT FROM 'active'
   OR NOT EXISTS(SELECT 1 FROM public.ai_provider_registry WHERE code=i.provider_code AND enabled) THEN RAISE EXCEPTION 'copilot.binding_required'; END IF;
 RETURN jsonb_build_object('llm_provider_id',l.id,'provider_instance_id',i.id,'model_catalog_id',c.id,'model_key',c.model_key);
END $function$

CREATE OR REPLACE FUNCTION private.ticket_message_commit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE t public.support_tickets%ROWTYPE;
BEGIN
 SELECT * INTO t FROM public.support_tickets WHERE id=NEW.ticket_id;
 IF NOT NEW.internal_note AND NEW.author_id<>t.created_by AND t.first_response_at IS NULL
    AND (private.ticket_manager(NEW.author_id,t.tenant_id) OR
      (t.assignee_id=NEW.author_id AND private.ticket_responder(NEW.author_id,t.tenant_id))) THEN
   UPDATE public.support_tickets SET first_response_at=NEW.created_at WHERE id=t.id AND first_response_at IS NULL;
 END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(auth.uid(),t.tenant_id,t.scope,CASE WHEN NEW.internal_note THEN 'ticket.internal_note' ELSE 'ticket.reply' END,
   'support_ticket',t.id::text,jsonb_build_object('message_id',NEW.id,'internal_note',NEW.internal_note));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.reserve_copilot_dispatch(_attempt_id uuid, _provider_id uuid, _tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
 actor uuid := auth.uid(); stamp timestamptz := clock_timestamp();
 p public.platform_ai_settings%ROWTYPE; t public.tenant_ai_settings%ROWTYPE;
 b public.ai_budgets%ROWTYPE; l public.llm_providers%ROWTYPE;
 c public.ai_model_catalog%ROWTYPE; i public.ai_provider_instances%ROWTYPE;
 price public.ai_model_pricing%ROWTYPE; q public.ai_quotas%ROWTYPE;
 bound_t numeric; bound_c numeric; w record; total_t numeric; total_c numeric;
 cap_t numeric; cap_c numeric; pct numeric; input_bound integer;
BEGIN
 IF actor IS NULL OR _attempt_id IS NULL OR _provider_id IS NULL THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 PERFORM pg_advisory_xact_lock(61000,1);
 IF _tenant_id IS NULL THEN
   IF NOT coalesce(private.is_platform_admin(actor),false) AND NOT coalesce(private.is_platform_super_admin(actor),false)
     THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active) THEN
   RAISE EXCEPTION 'copilot.forbidden';
 END IF;
 IF EXISTS(SELECT 1 FROM public.copilot_spend_reservations WHERE id=_attempt_id::text) THEN
   RAISE EXCEPTION 'copilot.already_dispatched';
 END IF;
 SELECT * INTO p FROM public.platform_ai_settings WHERE id=true FOR SHARE;
 IF NOT FOUND OR p.ai_enabled IS DISTINCT FROM true OR p.allow_copilot_global IS DISTINCT FROM true OR p.default_autonomy_ceiling NOT IN ('suggest','assist','auto')
   OR p.default_autonomy_ceiling IS NULL THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
 IF _tenant_id IS NOT NULL THEN
   SELECT * INTO t FROM public.tenant_ai_settings WHERE tenant_id=_tenant_id FOR SHARE;
   IF NOT FOUND OR t.ai_enabled IS DISTINCT FROM true OR t.allow_copilot IS DISTINCT FROM true OR t.default_autonomy IS NULL
     OR t.default_autonomy NOT IN ('read_only','supervised','autonomous') THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
   SELECT * INTO b FROM public.ai_budgets WHERE tenant_id=_tenant_id FOR SHARE;
   IF FOUND AND (b.daily_max_tokens IS NULL OR b.daily_max_tokens<0 OR b.daily_max_cost_usd IS NULL
     OR b.daily_max_cost_usd<0 OR b.monthly_max_cost_usd IS NULL OR b.monthly_max_cost_usd<0
     OR b.hard_stop_at_pct IS NULL OR b.hard_stop_at_pct NOT BETWEEN 1 AND 200
     OR b.daily_max_cost_usd::text IN ('NaN','Infinity','-Infinity')
     OR b.monthly_max_cost_usd::text IN ('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
   SELECT * INTO q FROM public.ai_quotas WHERE tenant_id=_tenant_id FOR SHARE;
 END IF;
 IF p.global_max_tokens_per_day IS NULL OR p.global_max_tokens_per_day<0
   OR p.global_max_cost_usd_per_day IS NULL OR p.global_max_cost_usd_per_day<0
   OR p.global_max_cost_usd_per_day::text IN ('NaN','Infinity','-Infinity')
   OR (_tenant_id IS NOT NULL AND (t.max_tokens_per_day IS NULL OR t.max_tokens_per_day<0)) THEN
   RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM public.ai_governance_kill_switches WHERE engaged
   AND (tenant_id IS NULL OR tenant_id=_tenant_id) AND scope IN ('global','copilot','copilot.chat')) THEN
   RAISE EXCEPTION 'copilot.kill_switch'; END IF;
 -- Actor + tenant sliding windows are from stored settings, never supplied caps.
 IF p.llm_rl_per_user_max IS NULL OR p.llm_rl_per_user_max<1
   OR p.llm_rl_per_user_window_seconds IS NULL OR p.llm_rl_per_user_window_seconds<1
   OR p.llm_rl_per_tenant_max IS NULL OR p.llm_rl_per_tenant_max<1
   OR p.llm_rl_per_tenant_window_seconds IS NULL OR p.llm_rl_per_tenant_window_seconds<1 THEN
   RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM (VALUES
   (true,p.llm_rl_per_user_max,p.llm_rl_per_user_window_seconds),
   (false,p.llm_rl_per_tenant_max,p.llm_rl_per_tenant_window_seconds),
   (true,t.llm_rl_per_user_max,t.llm_rl_per_user_window_seconds),
   (false,t.llm_rl_per_tenant_max,t.llm_rl_per_tenant_window_seconds)
 ) caps(own,lim,seconds) WHERE (lim IS NOT NULL OR seconds IS NOT NULL) AND
   (coalesce(lim,CASE WHEN own THEN p.llm_rl_per_user_max ELSE p.llm_rl_per_tenant_max END)<1
    OR coalesce(seconds,CASE WHEN own THEN p.llm_rl_per_user_window_seconds ELSE p.llm_rl_per_tenant_window_seconds END)<1
    OR (SELECT count(*) FROM public.copilot_spend_reservations r
      WHERE r.created_at>=stamp-make_interval(secs=>coalesce(seconds,CASE WHEN own THEN p.llm_rl_per_user_window_seconds ELSE p.llm_rl_per_tenant_window_seconds END))
      AND (CASE WHEN own THEN r.actor_id=actor ELSE r.tenant_id IS NOT DISTINCT FROM _tenant_id END))
      >=coalesce(lim,CASE WHEN own THEN p.llm_rl_per_user_max ELSE p.llm_rl_per_tenant_max END))) THEN
   RAISE EXCEPTION 'copilot.rate_limit'; END IF;
 SELECT * INTO l FROM public.llm_providers WHERE id=_provider_id FOR SHARE;
 IF NOT FOUND OR l.is_active IS DISTINCT FROM true OR l.tenant_id IS DISTINCT FROM _tenant_id
   OR l.scope::text IS DISTINCT FROM (CASE WHEN _tenant_id IS NULL THEN 'platform' ELSE 'tenant' END)
   OR l.provider_instance_id IS NULL OR l.model_catalog_id IS NULL THEN RAISE EXCEPTION 'copilot.binding_required'; END IF;
 SELECT * INTO c FROM public.ai_model_catalog WHERE id=l.model_catalog_id FOR SHARE;
 IF NOT FOUND OR c.provider_instance_id<>l.provider_instance_id OR c.model_key<>l.model
   OR c.approval_status IS DISTINCT FROM 'approved' OR c.availability_status IS NULL OR c.availability_status NOT IN ('available','limited')
   OR c.max_input_tokens IS NULL OR c.max_input_tokens<=0 OR c.max_output_tokens IS NULL OR c.max_output_tokens<=0
   OR c.context_window IS NULL OR c.context_window<=c.max_output_tokens THEN
   RAISE EXCEPTION 'copilot.bounds_unavailable'; END IF;
 SELECT * INTO i FROM public.ai_provider_instances WHERE id=l.provider_instance_id FOR SHARE;
 IF NOT FOUND OR i.tenant_id IS DISTINCT FROM _tenant_id OR i.status IS DISTINCT FROM 'active'
   OR NOT EXISTS(SELECT 1 FROM public.ai_provider_registry WHERE code=i.provider_code AND enabled) THEN
   RAISE EXCEPTION 'copilot.binding_required'; END IF;
 SELECT * INTO price FROM public.ai_model_pricing WHERE provider_code=i.provider_code AND model_key=c.model_key
   AND active AND currency='USD' AND effective_at<=stamp AND (expires_at IS NULL OR expires_at>stamp)
   ORDER BY effective_at DESC,id LIMIT 1 FOR SHARE;
 IF NOT FOUND OR price.input_usd_per_1m IS NULL OR price.output_usd_per_1m IS NULL
   OR price.input_usd_per_1m<=0 OR price.output_usd_per_1m<=0
   OR price.input_usd_per_1m::text IN ('NaN','Infinity','-Infinity')
   OR price.output_usd_per_1m::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'copilot.pricing_unavailable'; END IF;
 input_bound:=least(c.max_input_tokens,c.context_window-c.max_output_tokens);
 bound_t:=input_bound::numeric+c.max_output_tokens;
 bound_c:=ceil(input_bound::numeric*price.input_usd_per_1m+c.max_output_tokens::numeric*price.output_usd_per_1m);
 IF EXISTS(SELECT 1 FROM public.ai_usage_events WHERE
   (created_at>=date_trunc('month',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' OR created_at IS NULL OR NOT isfinite(created_at))
   AND (created_at IS NULL OR NOT isfinite(created_at) OR tokens_in IS NULL OR tokens_out IS NULL OR tokens_in<0 OR tokens_out<0
     OR cost_usd IS NULL OR cost_usd<0 OR cost_usd::text IN ('NaN','Infinity','-Infinity')
     OR (tokens_in::numeric+tokens_out>0 AND cost_usd=0))) THEN RAISE EXCEPTION 'copilot.pricing_unavailable'; END IF;
 pct:=coalesce(b.hard_stop_at_pct,100)/100.0;
 FOR w IN SELECT 1 n,NULL::uuid tenant,date_trunc('day',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' since
   UNION ALL SELECT 2,_tenant_id,date_trunc('day',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' WHERE _tenant_id IS NOT NULL
   UNION ALL SELECT 3,_tenant_id,date_trunc('month',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' WHERE _tenant_id IS NOT NULL
 LOOP
   SELECT coalesce(sum(tokens_in::numeric+tokens_out),0),ceil(coalesce(sum(cost_usd),0)*1000000) INTO total_t,total_c
     FROM public.ai_usage_events u WHERE u.created_at>=w.since AND (w.n=1 OR u.tenant_id=w.tenant)
     AND NOT EXISTS(SELECT 1 FROM public.copilot_spend_reservations r WHERE r.id=u.meta->>'copilot_reservation_id' AND r.llm_provider_id IS NOT NULL);
   SELECT total_t+coalesce(sum(coalesce(accounted_tokens,bound_tokens)),0),total_c+coalesce(sum(coalesce(accounted_micro_usd,bound_micro_usd)),0)
     INTO total_t,total_c FROM public.copilot_spend_reservations r WHERE r.state<>'released'
       AND (r.state IN ('reserved','dispatched') OR r.created_at>=w.since) AND (w.n=1 OR r.tenant_id=w.tenant);
   cap_t:=CASE w.n WHEN 1 THEN p.global_max_tokens_per_day WHEN 2 THEN least(t.max_tokens_per_day,b.daily_max_tokens,q.daily_token_limit) ELSE q.monthly_token_limit END;
   cap_c:=floor(CASE w.n WHEN 1 THEN p.global_max_cost_usd_per_day WHEN 2 THEN coalesce(b.daily_max_cost_usd,50)*pct
     ELSE least(coalesce(b.monthly_max_cost_usd,1000)*pct,q.budget_limit_usd) END*1000000);
   IF (cap_t IS NOT NULL AND (cap_t<0 OR total_t>=cap_t OR total_t+bound_t>cap_t))
     OR cap_c IS NULL OR cap_c<0 OR cap_c::text IN ('NaN','Infinity','-Infinity') OR total_c>=cap_c OR total_c+bound_c>cap_c THEN
     RAISE EXCEPTION 'copilot.budget_reached'; END IF;
 END LOOP;
 -- No period/counter semantics are established for these optional dimensions.
 -- Do not silently treat them as per-request caps or unknown usage as zero.
 IF q.input_token_limit IS NOT NULL OR q.output_token_limit IS NOT NULL
   OR q.cached_token_limit IS NOT NULL OR q.api_request_limit IS NOT NULL THEN
   RAISE EXCEPTION 'copilot.quota_dimension_unavailable'; END IF;
 INSERT INTO public.copilot_spend_reservations(id,actor_id,tenant_id,pricing_basis,bound_tokens,bound_micro_usd,state,
   llm_provider_id,catalog_id,price_id,model_key,input_rate,output_rate,max_input_tokens,max_output_tokens,created_at)
 VALUES(_attempt_id::text,actor,_tenant_id,price.id::text,bound_t,bound_c,'dispatched',l.id,c.id,price.id,c.model_key,
   price.input_usd_per_1m,price.output_usd_per_1m,input_bound,c.max_output_tokens,stamp);
 RETURN jsonb_build_object('reservation_id',_attempt_id::text,'max_input_tokens',input_bound,'max_output_tokens',c.max_output_tokens,
   'provider',l.provider,'model_key',l.model,'base_url',l.base_url,'key_secret_name',l.key_secret_name);
END $function$

CREATE OR REPLACE FUNCTION public.bulk_import_reference_data(_tenant_id uuid, _table_id uuid, _rows jsonb, _replace boolean DEFAULT false)
 RETURNS TABLE(imported_count integer, total_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  actor uuid := auth.uid();
  incoming_count integer;
BEGIN
  IF actor IS NULL OR NOT (
    public.has_tenant_role(actor, _tenant_id, 'tenant_admin')
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_analyst')
    OR public.is_platform_admin(actor)
  ) THEN
    RAISE EXCEPTION 'Forbidden: analyst or admin required' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.reference_data_tables
    WHERE id = _table_id AND tenant_id = _tenant_id
  ) THEN
    RAISE EXCEPTION 'Reference table not found';
  END IF;
  IF jsonb_typeof(_rows) <> 'array' THEN
    RAISE EXCEPTION 'Reference rows must be a JSON array';
  END IF;
  incoming_count := jsonb_array_length(_rows);
  IF incoming_count < 1 OR incoming_count > 10000 THEN
    RAISE EXCEPTION 'Reference import must contain between 1 and 10000 rows';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_array_elements(_rows) AS item WHERE jsonb_typeof(item) <> 'object') THEN
    RAISE EXCEPTION 'Every reference row must be a JSON object';
  END IF;

  IF _replace THEN
    DELETE FROM public.reference_data_rows
    WHERE table_id = _table_id AND tenant_id = _tenant_id;
  END IF;

  INSERT INTO public.reference_data_rows(table_id, tenant_id, row_data)
  SELECT _table_id, _tenant_id, item
  FROM jsonb_array_elements(_rows) AS item;

  SELECT count(*)::integer INTO total_count
  FROM public.reference_data_rows
  WHERE table_id = _table_id AND tenant_id = _tenant_id;
  imported_count := incoming_count;

  UPDATE public.reference_data_tables
  SET row_count = total_count
  WHERE id = _table_id AND tenant_id = _tenant_id;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    actor, _tenant_id, 'tenant', 'reference_data.bulk_load',
    'reference_data_tables', _table_id::text,
    jsonb_build_object('rows', imported_count, 'total_rows', total_count, 'replace', _replace)
  );

  RETURN NEXT;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_reference_data_version_row_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  version_tenant uuid;
  version_table uuid;
  version_status text;
  keys text[];
  key_payload jsonb;
BEGIN
  SELECT tenant_id, table_id, status
  INTO version_tenant, version_table, version_status
  FROM public.reference_data_versions
  WHERE id = NEW.version_id;

  IF version_tenant IS NULL
     OR version_tenant <> NEW.tenant_id
     OR version_table <> NEW.table_id THEN
    RAISE EXCEPTION 'Reference version row must belong to the same tenant and table';
  END IF;
  IF version_status <> 'draft' THEN
    RAISE EXCEPTION 'Reference version rows are immutable after submission';
  END IF;

  SELECT key_columns INTO keys
  FROM public.reference_data_tables
  WHERE id = NEW.table_id AND tenant_id = NEW.tenant_id;
  IF coalesce(array_length(keys, 1), 0) = 0 THEN
    RAISE EXCEPTION 'Reference table must define at least one key column';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(keys) AS key_name
    WHERE NOT (NEW.row_data ? key_name)
       OR NEW.row_data -> key_name IS NULL
       OR btrim(NEW.row_data ->> key_name) = ''
  ) THEN
    RAISE EXCEPTION 'Reference version row is missing a required key value';
  END IF;

  SELECT jsonb_agg(NEW.row_data -> key_name ORDER BY ordinal)
  INTO key_payload
  FROM unnest(keys) WITH ORDINALITY AS ordered_keys(key_name, ordinal);
  NEW.key_hash := encode(digest(key_payload::text, 'sha256'), 'hex');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_reference_data_version_pre_scope(_tenant_id uuid, _table_id uuid, _as_of date DEFAULT CURRENT_DATE)
 RETURNS TABLE(resolved_version_id uuid, resolved_version_number integer, resolved_content_sha256 text, resolved_rows jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  matches integer;
BEGIN
  IF actor IS NULL OR NOT (
    public.is_tenant_member(actor, _tenant_id) OR public.is_platform_admin(actor)
  ) THEN
    RAISE EXCEPTION 'Forbidden: tenant membership required' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.reference_data_tables
    WHERE id = _table_id AND tenant_id = _tenant_id
  ) THEN
    RAISE EXCEPTION 'Reference table not found';
  END IF;

  SELECT count(*)::integer INTO matches
  FROM public.reference_data_versions rdv
  WHERE rdv.table_id = _table_id AND rdv.tenant_id = _tenant_id
    AND rdv.status IN ('published','superseded')
    AND rdv.effective_from <= _as_of
    AND (rdv.effective_to IS NULL OR rdv.effective_to >= _as_of);
  IF matches = 0 THEN RAISE EXCEPTION 'No published reference version for requested date'; END IF;
  IF matches > 1 THEN RAISE EXCEPTION 'Ambiguous published reference versions for requested date'; END IF;

  RETURN QUERY
  SELECT rdv.id, rdv.version_number, rdv.content_sha256,
         coalesce(jsonb_agg(r.row_data ORDER BY r.key_hash), '[]'::jsonb)
  FROM public.reference_data_versions rdv
  JOIN public.reference_data_version_rows r ON r.version_id = rdv.id
  WHERE rdv.table_id = _table_id AND rdv.tenant_id = _tenant_id
    AND rdv.status IN ('published','superseded')
    AND rdv.effective_from <= _as_of
    AND (rdv.effective_to IS NULL OR rdv.effective_to >= _as_of)
  GROUP BY rdv.id, rdv.version_number, rdv.content_sha256;
END;
$function$

CREATE OR REPLACE FUNCTION private.ticket_workflow(_operation text, _request_key uuid, _input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid:=auth.uid(); fingerprint text; previous private.ticket_workflow_requests%ROWTYPE;
 t public.support_tickets%ROWTYPE; message_id uuid; outcome jsonb; patch jsonb;
BEGIN
 IF actor IS NULL OR _request_key IS NULL OR _operation NOT IN ('create','update','reply','sla','escalate') THEN
   RAISE EXCEPTION 'Authenticated bounded ticket request required' USING ERRCODE='42501'; END IF;
 fingerprint:=encode(extensions.digest(convert_to(_operation||(_input-ARRAY['body','attachments','reason'])::text,'UTF8'),'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||_request_key::text,0));
 SELECT * INTO previous FROM private.ticket_workflow_requests WHERE actor_id=actor AND request_key=_request_key;
 IF FOUND THEN
   IF previous.operation<>_operation OR previous.fingerprint<>fingerprint THEN
     RAISE EXCEPTION 'Ticket request key already used with different payload' USING ERRCODE='22023'; END IF;
   SELECT * INTO t FROM public.support_tickets WHERE id=(previous.result->>'id')::uuid;
   IF t.id IS NULL OR NOT (private.ticket_manager(actor,t.tenant_id) OR
     (private.ticket_active_member(actor,t.tenant_id) AND
       (t.created_by=actor OR (_operation<>'create' AND private.ticket_responder(actor,t.tenant_id)))))
     OR (_operation IN ('sla','escalate') AND NOT private.ticket_manager(actor,t.tenant_id)) THEN
     RAISE EXCEPTION 'Current permission required for ticket replay' USING ERRCODE='42501';
   END IF;
   RETURN previous.result||jsonb_build_object('is_new',false);
 END IF;
 IF _operation='create' THEN
   IF jsonb_typeof(_input)<>'object' OR (_input-ARRAY['tenant_id','scope','subject','body','priority','category','attachments','content_hash','recon_id'])<>'{}' THEN RAISE EXCEPTION 'Unsupported ticket create field' USING ERRCODE='22023'; END IF;
   IF length(coalesce(_input->>'content_hash',''))<>64 THEN RAISE EXCEPTION 'Content fingerprint required' USING ERRCODE='22023'; END IF;
   INSERT INTO public.support_tickets(tenant_id,scope,created_by,subject,body,priority,category,attachments,queue,recon_id)
   VALUES((_input->>'tenant_id')::uuid,_input->>'scope',actor,_input->>'subject',_input->>'body',
    (_input->>'priority')::public.ticket_priority,_input->>'category',coalesce(_input->'attachments','[]'),
    CASE WHEN _input->>'scope'='platform' THEN 'platform'::public.ticket_queue ELSE 'tenant'::public.ticket_queue END,(_input->>'recon_id')::uuid)
   RETURNING * INTO t;
 ELSE
   SELECT * INTO t FROM public.support_tickets WHERE id=(_input->>'id')::uuid FOR UPDATE;
   IF t.id IS NULL OR NOT (private.ticket_manager(actor,t.tenant_id) OR private.ticket_active_member(actor,t.tenant_id)) THEN
     RAISE EXCEPTION 'Ticket unavailable in current scope' USING ERRCODE='42501'; END IF;
   IF _operation='reply' THEN
     IF length(coalesce(_input->>'content_hash',''))<>64 THEN RAISE EXCEPTION 'Content fingerprint required' USING ERRCODE='22023'; END IF;
     INSERT INTO public.ticket_messages(ticket_id,author_id,body,internal_note)
      VALUES(t.id,actor,_input->>'body',coalesce((_input->>'internal_note')::boolean,false)) RETURNING id INTO message_id;
     SELECT * INTO t FROM public.support_tickets WHERE id=t.id;
   ELSIF _operation='escalate' THEN
     IF NOT private.ticket_manager(actor,t.tenant_id) THEN RAISE EXCEPTION 'Manager escalation required' USING ERRCODE='42501'; END IF;
     IF length(coalesce(_input->>'reason','')) NOT BETWEEN 3 AND 3000 THEN RAISE EXCEPTION 'Bounded escalation reason required' USING ERRCODE='22023'; END IF;
     UPDATE public.support_tickets SET queue='platform',status='in_progress',escalated_at=statement_timestamp(),escalated_reason=_input->>'reason' WHERE id=t.id RETURNING * INTO t;
   ELSIF _operation='sla' THEN
     IF NOT private.ticket_manager(actor,t.tenant_id) THEN RAISE EXCEPTION 'Manager SLA decision required' USING ERRCODE='42501'; END IF;
     UPDATE public.support_tickets SET sla_policy_id=(_input->>'policy_id')::uuid,sla_revision=sla_revision+1 WHERE id=t.id RETURNING * INTO t;
   ELSE
     patch:=_input->'patch';
     IF patch IS NULL OR patch='{}' OR jsonb_typeof(patch)<>'object' OR patch-'status'-'priority'-'category'-'assignee_id'<>'{}' THEN
       RAISE EXCEPTION 'Unsupported ticket update field' USING ERRCODE='22023'; END IF;
     UPDATE public.support_tickets SET
      status=CASE WHEN patch?'status' THEN (patch->>'status')::public.ticket_status ELSE status END,
      priority=CASE WHEN patch?'priority' THEN (patch->>'priority')::public.ticket_priority ELSE priority END,
      category=CASE WHEN patch?'category' THEN patch->>'category' ELSE category END,
      assignee_id=CASE WHEN patch?'assignee_id' THEN (patch->>'assignee_id')::uuid ELSE assignee_id END
      WHERE id=t.id RETURNING * INTO t;
   END IF;
 END IF;
 outcome:=jsonb_build_object('id',t.id,'ref',t.ref,'tenant_id',t.tenant_id,'scope',t.scope,'status',t.status,
    'first_response_at',t.first_response_at,'sla_snapshot',t.sla_snapshot,'first_response_due_at',t.first_response_due_at,
    'resolution_due_at',t.resolution_due_at,'message_id',message_id,'is_new',true);
 INSERT INTO private.ticket_workflow_requests(actor_id,request_key,operation,fingerprint,result)
 VALUES(actor,_request_key,_operation,fingerprint,outcome);
 RETURN outcome;
END $function$

CREATE OR REPLACE FUNCTION public.finalize_connector_background_v1(_worker_token text, _attempt_id uuid, _serialized_rows text, _sha256 text, _size_bytes bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a public.connector_worker_attempts_v1%ROWTYPE; g public.connector_worker_vault_grants_v1%ROWTYPE;
 s public.data_source_schedules%ROWTYPE; u uuid; r bigint; n integer; cols jsonb; samples jsonb; outcome jsonb; _rows jsonb;
BEGIN
 SELECT * INTO a FROM public.connector_worker_attempts_v1 WHERE id=_attempt_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'connector.attempt_denied'; END IF;
 SELECT * INTO g FROM public.connector_worker_vault_grants_v1 WHERE id=a.grant_id;
 g:=private.connector_worker_grant_v1(_worker_token,g.schedule_id);
 PERFORM pg_advisory_xact_lock(hashtextextended('connector.worker.v1:'||g.id::text,0));
 SELECT * INTO a FROM public.connector_worker_attempts_v1 WHERE id=_attempt_id FOR UPDATE;
 IF a.grant_id<>g.id THEN RAISE EXCEPTION 'connector.attempt_denied'; END IF;
 IF a.state='completed' THEN
   IF a.result->>'sha256' IS DISTINCT FROM _sha256 THEN RAISE EXCEPTION 'connector.replay_conflict'; END IF;
   RETURN a.result;
 END IF;
 IF a.job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.workflow_api_jobs job_check JOIN public.api_tokens token_check ON token_check.id=job_check.token_id
   JOIN public.tenant_members member_check ON member_check.user_id=job_check.actor_user_id AND member_check.tenant_id=job_check.tenant_id AND member_check.active
   WHERE job_check.id=a.job_id AND job_check.status='running' AND token_check.principal_kind='user_delegated' AND token_check.subject_user_id=job_check.actor_user_id
     AND job_check.tenant_id=g.tenant_id AND job_check.resource_id=g.schedule_id AND job_check.actor_user_id=a.actor_user_id
     AND token_check.revoked_at IS NULL AND (token_check.expires_at IS NULL OR token_check.expires_at>clock_timestamp()) AND coalesce('connectors.run'=ANY(token_check.scopes),false)
     AND coalesce(private.connector_worker_scope_allows_actor_v1(job_check.actor_user_id,g.schedule_id,'run'),false)) THEN RAISE EXCEPTION 'connector.job_denied'; END IF;
 _rows:=_serialized_rows::jsonb;
 IF _serialized_rows IS NULL OR octet_length(convert_to(_serialized_rows,'UTF8'))<>_size_bytes OR _size_bytes>20000000
   OR encode(extensions.digest(convert_to(_serialized_rows,'UTF8'),'sha256'),'hex') IS DISTINCT FROM _sha256
   OR jsonb_typeof(_rows)<>'array' OR jsonb_array_length(_rows)>50000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_rows) x WHERE jsonb_typeof(x)<>'object')
   OR length(_sha256)<>64 OR _size_bytes<0 THEN RAISE EXCEPTION 'connector.output_invalid'; END IF;
 SELECT * INTO s FROM public.data_source_schedules WHERE id=g.schedule_id FOR SHARE;
 n:=jsonb_array_length(_rows);
 SELECT coalesce(jsonb_agg(key ORDER BY key),'[]'::jsonb) INTO cols FROM (SELECT DISTINCT jsonb_object_keys(value) key FROM jsonb_array_elements(_rows)) k;
 SELECT coalesce(jsonb_agg(value),'[]'::jsonb) INTO samples FROM (SELECT value FROM jsonb_array_elements(_rows) LIMIT 10) sample;
 INSERT INTO public.workspace_data_source_uploads(data_source_id,tenant_id,filename,mime_type,size_bytes,row_count,columns,sample_rows,rows,content_sha256,uploaded_by)
 VALUES(s.data_source_id,g.tenant_id,'connector-worker-'||a.id::text||'.json','application/json',_size_bytes,n,cols,samples,_rows,_sha256,a.actor_user_id) RETURNING id INTO u;
 INSERT INTO public.data_source_runs(schedule_id,tenant_id,finished_at,status,rows_ingested,trigger)
 VALUES(s.id,g.tenant_id,clock_timestamp(),'success',n,CASE WHEN a.job_id IS NULL THEN 'cron' ELSE 'manual' END) RETURNING id INTO r;
 UPDATE public.data_source_schedules SET last_run_at=clock_timestamp(),last_status='success',last_rows_ingested=n,last_error=NULL WHERE id=s.id;
 outcome:=jsonb_build_object('workflow_status','success','schedule_id',s.id,'rows',n,'upload_id',u,'run_id',r,'attempt_id',a.id,'service_principal_id',g.service_principal_id,'sha256',_sha256);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(a.actor_user_id,g.tenant_id,'tenant',CASE WHEN a.actor_user_id IS NULL THEN 'cron.connector.worker.complete' ELSE 'connector.worker.complete' END,'connector_worker_attempt',a.id::text,a.grant_snapshot||outcome);
 UPDATE public.connector_worker_attempts_v1 SET state='completed',result=outcome WHERE id=a.id;
 RETURN outcome;
END $function$

CREATE OR REPLACE FUNCTION private.ticket_policy_guard_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NOT private.ticket_manager(auth.uid(),NEW.tenant_id) OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Current SLA policy manager required' USING ERRCODE='42501'; END IF;
 IF TG_OP='UPDATE' AND ROW(NEW.id,NEW.tenant_id) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id) THEN RAISE EXCEPTION 'SLA policy identity immutable' USING ERRCODE='42501'; END IF;
 IF NEW.first_response_mins<=0 OR NEW.resolution_mins<=0 THEN RAISE EXCEPTION 'Positive SLA durations required' USING ERRCODE='22023'; END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(auth.uid(),NEW.tenant_id,'tenant',CASE WHEN TG_OP='INSERT' THEN 'ticket.sla.policy.create' ELSE 'ticket.sla.policy.update' END,'sla_policy',NEW.id::text,
 jsonb_build_object('first_response_mins',NEW.first_response_mins,'resolution_mins',NEW.resolution_mins,'priority',NEW.priority));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.dpw_create_delivery(_tenant_id uuid, _pipeline_id uuid, _business_date date, _request_key uuid, _correction_of uuid, _mode text DEFAULT 'prepare'::text, _exclusion_approval_id uuid DEFAULT NULL::uuid, _execution_mode text DEFAULT 'manual'::text, _human_in_loop boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); p public.data_prep_pipelines%ROWTYPE;
 b public.data_prep_delivery_batches%ROWTYPE; snap jsonb; f jsonb; exclusion public.data_prep_exclusion_requests%ROWTYPE; prior_run public.data_prep_delivery_runs%ROWTYPE;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 IF _execution_mode IS NULL OR _execution_mode NOT IN('manual','assisted','agentic') OR _human_in_loop IS NULL
 OR private.dpw_mode_attest(actor,_tenant_id,_pipeline_id,_execution_mode,_human_in_loop) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.mode_denied'; END IF;
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
 IF _business_date IS NULL OR _request_key IS NULL OR _mode IS NULL OR _mode NOT IN('preview','prepare') OR NOT p.enabled
 OR (_mode='prepare' AND (p.status<>'approved' OR p.lifecycle_state<>'production'))
 OR (_mode='preview' AND (p.status NOT IN('draft','approved') OR p.lifecycle_state='archived'))
 THEN RAISE EXCEPTION 'dpw.approved_production_required'; END IF;
 SELECT * INTO b FROM public.data_prep_delivery_batches WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF FOUND THEN
  IF b.pipeline_id<>_pipeline_id OR b.business_date<>_business_date OR b.correction_of IS DISTINCT FROM _correction_of OR b.mode<>_mode
  OR b.exclusion_approval_id IS DISTINCT FROM _exclusion_approval_id
  OR b.execution_mode<>_execution_mode OR b.human_in_loop<>_human_in_loop
  THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'batch',to_jsonb(b),'is_new',false);
 END IF;
 IF _correction_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_batches
 WHERE id=_correction_of AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id AND business_date=_business_date)
 THEN RAISE EXCEPTION 'dpw.correction_predecessor_mismatch'; END IF;
 snap:=private.dpw_snapshot(_pipeline_id)||jsonb_build_object('quality_gate','strict');
 IF _correction_of IS NOT NULL THEN
  SELECT * INTO prior_run FROM public.data_prep_delivery_runs WHERE batch_id=_correction_of AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id ORDER BY started_at DESC,id LIMIT 1;
  IF FOUND THEN
   snap:=snap||jsonb_build_object('correction_source_run_id',prior_run.id,'correction_source_files',prior_run.snapshot->'files','correction_manifest_origin','persisted_predecessor_run_inputs');
  ELSE
   -- A correction may precede the predecessor's first preparation. Freeze the
   -- actual received cohort now, under the predecessor batch lock; never use
   -- today's profiles to manufacture a historical processing snapshot.
   PERFORM 1 FROM public.data_prep_delivery_batches WHERE id=_correction_of FOR UPDATE;
   snap:=snap||jsonb_build_object('correction_source_run_id',NULL,'correction_manifest_origin','persisted_predecessor_received_files',
   'correction_source_files',coalesce((SELECT jsonb_agg(jsonb_build_object('file_id',x.id,'upload_id',x.upload_id,
   'feed_key',x.feed_key,'data_source_id',x.data_source_id,'pipeline_version',x.pipeline_version,'content_sha256',x.content_sha256,
   'original_path',x.original_path,'rows_count',u.row_count,'filename',x.descriptor->>'filename','correction_of',x.correction_of) ORDER BY x.created_at,x.id)
   FROM public.data_prep_delivery_files x JOIN public.workspace_data_source_uploads u ON u.id=x.upload_id
   WHERE x.batch_id=_correction_of AND x.tenant_id=_tenant_id AND x.state='received'),'[]'::jsonb));
  END IF;
 END IF;
 IF jsonb_array_length(snap->'feeds')=0 THEN RAISE EXCEPTION 'dpw.no_input_configuration'; END IF;
 IF _exclusion_approval_id IS NOT NULL THEN
  SELECT e.* INTO exclusion FROM public.data_prep_exclusion_requests e JOIN public.data_prep_exclusion_decisions d ON d.request_id=e.id
  WHERE d.id=_exclusion_approval_id AND d.decision='approved' AND e.tenant_id=_tenant_id AND e.pipeline_id=_pipeline_id
  AND e.pipeline_version=p.version AND e.batch_id=_correction_of;
  IF NOT FOUND THEN RAISE EXCEPTION 'dpw.approved_exclusion_correction_required'; END IF;
  snap:=snap||jsonb_build_object('exclusion_approval_id',_exclusion_approval_id,'approved_exclusions',exclusion.entries,'exclusion_source_run_id',exclusion.run_id);
 END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(snap->'feeds') LOOP
  IF private.dpw_source_allows(actor,_tenant_id,(f->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'dpw.source_denied'; END IF;
 END LOOP;
 INSERT INTO public.data_prep_delivery_batches(tenant_id,pipeline_id,pipeline_version,business_date,mode,execution_mode,human_in_loop,request_key,created_by,correction_of,configuration_snapshot,exclusion_approval_id)
 VALUES(_tenant_id,_pipeline_id,p.version,_business_date,_mode,_execution_mode,_human_in_loop,_request_key,actor,_correction_of,snap,_exclusion_approval_id) RETURNING * INTO b;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.delivery.create',b.id,jsonb_build_object('version',p.version,'correction_of',_correction_of));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'batch',to_jsonb(b),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION private.governance_membership_lock_scope()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  LOCK TABLE public.tenant_members,public.business_units,public.tenant_groups,public.workspace_members,
    public.workspaces,public.tenant_environments,public.bu_user_assignments,public.bu_group_assignments,
    public.tenant_group_roles,public.rbac_roles,public.rbac_role_permissions,public.permissions,
    public.recon_definition_bu_grants,public.recon_definitions,public.data_resource_registry_grants,public.recon_permissions,public.data_resource_bu_grants IN SHARE MODE;
  LOCK TABLE public.tenant_group_members IN SHARE ROW EXCLUSIVE MODE;
END $function$

CREATE OR REPLACE FUNCTION public.list_governance_membership_options(_tenant_id uuid, _kind text, _page integer DEFAULT 1, _page_size integer DEFAULT 25, _search text DEFAULT ''::text, _bu_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid, _environment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); admin boolean; effective_env text; rows jsonb:='[]'::jsonb; page_rows jsonb; item record; snapshot jsonb;
BEGIN
  IF NOT private.governance_membership_active(_tenant_id,actor) THEN RAISE EXCEPTION 'Active tenant membership required' USING ERRCODE='42501'; END IF;
  IF _kind IS NULL OR _kind NOT IN ('bu','workspace','group','environment') OR _page IS NULL OR _page NOT BETWEEN 1 AND 100000
    OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 100 OR _search IS NULL OR length(_search)>200
  THEN RAISE EXCEPTION 'Invalid option scope or pagination' USING ERRCODE='22023'; END IF;
  admin:=private.governance_membership_active(_tenant_id,actor,true);
  IF _kind IN ('workspace','group') THEN
    IF _bu_id IS NULL THEN RAISE EXCEPTION 'Select a business unit first' USING ERRCODE='22023'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.business_units WHERE id=_bu_id AND tenant_id=_tenant_id AND NOT is_archived)
      OR NOT admin AND NOT EXISTS(SELECT 1 FROM public.user_bu_scope(actor,_tenant_id) s WHERE s=_bu_id)
    THEN RAISE EXCEPTION 'Current eligible business unit required' USING ERRCODE='42501'; END IF;
  END IF;
  IF _kind='environment' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'label',upper(env::text),'environment',env::text) ORDER BY env::text,id),'[]'::jsonb) INTO rows
      FROM public.tenant_environments WHERE tenant_id=_tenant_id AND is_active
      AND (_search='' OR strpos(lower(env::text),lower(_search))>0);
  ELSIF _kind='bu' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',b.id,'label',b.name,'bu_id',b.id) ORDER BY b.name,b.id),'[]'::jsonb) INTO rows
      FROM public.business_units b WHERE tenant_id=_tenant_id AND NOT is_archived
      AND (admin OR EXISTS(SELECT 1 FROM public.user_bu_scope(actor,_tenant_id) s WHERE s=b.id))
      AND (_search='' OR strpos(lower(b.name),lower(_search))>0);
  ELSIF _kind='workspace' THEN
    IF _bu_id IS NULL THEN RAISE EXCEPTION 'Select a business unit first' USING ERRCODE='22023'; END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('id',w.id,'label',w.name,'bu_id',w.business_unit_id) ORDER BY w.name,w.id),'[]'::jsonb) INTO rows
      FROM public.workspaces w JOIN public.business_units b ON b.id=w.business_unit_id AND b.tenant_id=w.tenant_id AND NOT b.is_archived
      WHERE w.tenant_id=_tenant_id AND w.business_unit_id=_bu_id AND w.status='active'
      AND (admin OR (EXISTS(SELECT 1 FROM public.user_bu_scope(actor,_tenant_id) s WHERE s=_bu_id)
        AND EXISTS(SELECT 1 FROM public.workspace_members wm WHERE wm.workspace_id=w.id AND wm.tenant_id=_tenant_id AND wm.user_id=actor)))
      AND (_search='' OR strpos(lower(w.name),lower(_search))>0);
  ELSE
    IF _workspace_id IS NULL THEN RAISE EXCEPTION 'Select a workspace first' USING ERRCODE='22023'; END IF;
    IF NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=_workspace_id AND tenant_id=_tenant_id AND business_unit_id=_bu_id AND status='active')
      OR NOT admin AND NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=_workspace_id AND tenant_id=_tenant_id AND user_id=actor)
    THEN RAISE EXCEPTION 'Current eligible workspace required' USING ERRCODE='42501'; END IF;
    SELECT min(env::text) INTO effective_env FROM public.tenant_environments WHERE tenant_id=_tenant_id AND is_active AND (_environment IS NULL OR env::text=_environment);
    IF effective_env IS NULL THEN RAISE EXCEPTION 'Current registered environment required' USING ERRCODE='42501'; END IF;
    -- Full eligibility means unsafe groups do not appear as selectable requests.
    FOR item IN SELECT g.id,g.name FROM public.tenant_groups g WHERE g.tenant_id=_tenant_id AND g.bu_id=_bu_id
      AND NOT EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=g.id AND gm.user_id=actor)
      AND (_search='' OR strpos(lower(g.name),lower(_search))>0) ORDER BY g.name,g.id
    LOOP
      BEGIN
        snapshot:=private.governance_membership_scope(_tenant_id,_bu_id,_workspace_id,item.id,effective_env,actor);
        rows:=rows||jsonb_build_array(jsonb_build_object('id',item.id,'label',item.name,'bu_id',_bu_id,
          'workspace_id',_workspace_id,'selectable',true,'requested_rights',snapshot->'requested_rights','scope_label',snapshot->>'scope_label','effective_scope',snapshot));
      EXCEPTION WHEN insufficient_privilege THEN CONTINUE;
      END;
    END LOOP;
  END IF;
  SELECT coalesce(jsonb_agg(value ORDER BY ordinality),'[]'::jsonb) INTO page_rows FROM jsonb_array_elements(rows) WITH ORDINALITY
    WHERE ordinality>((_page-1)*_page_size) AND ordinality<=(_page*_page_size);
  RETURN jsonb_build_object('rows',page_rows,'total',jsonb_array_length(rows),'page',_page,'page_size',_page_size,'has_more',(_page*_page_size)<jsonb_array_length(rows));
END $function$

CREATE OR REPLACE FUNCTION public.verify_audit_chain(_limit integer DEFAULT 10000)
 RETURNS TABLE(ok boolean, first_bad_id bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  r record;
  v_expected bytea;
  v_payload text;
begin
  if auth.uid() is null or not public.is_platform_admin(auth.uid()) then
    raise exception 'Forbidden: platform_admin required' using errcode = '42501';
  end if;

  for r in select * from public.audit_log order by id asc limit _limit loop
    if r.prev_hash is not null and not exists (
      select 1 from public.audit_log p where p.id <> r.id and p.row_hash = r.prev_hash
    ) then
      return query select false, r.id;
      return;
    end if;

    v_payload := coalesce(encode(r.prev_hash,'hex'),'') || '|' ||
                 coalesce(r.actor_user_id::text,'') || '|' ||
                 coalesce(r.tenant_id::text,'') || '|' || r.scope || '|' || r.action || '|' ||
                 coalesce(r.resource_type,'') || '|' || coalesce(r.resource_id,'') || '|' ||
                 coalesce(r.context::text,'{}') || '|' || r.occurred_at::text;
    v_expected := digest(v_payload, 'sha256');
    if v_expected <> r.row_hash then
      return query select false, r.id;
      return;
    end if;
  end loop;

  return query select true::boolean, null::bigint;
end
$function$

CREATE OR REPLACE FUNCTION public.stage_reference_data_version(_tenant_id uuid, _table_id uuid, _rows jsonb, _effective_from date, _effective_to date, _change_note text)
 RETURNS TABLE(version_id uuid, version_number integer, row_count integer, content_sha256 text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  actor uuid := auth.uid();
  v_version_id uuid;
  v_version_number integer;
  v_row_count integer;
  v_content_sha256 text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  IF actor IS NULL OR NOT (
    public.has_tenant_role(actor, _tenant_id, 'tenant_admin')
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_analyst')
    OR public.is_platform_admin(actor)
  ) THEN
    RAISE EXCEPTION 'Forbidden: analyst or admin required' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.reference_data_tables
    WHERE id = _table_id AND tenant_id = _tenant_id
  ) THEN
    RAISE EXCEPTION 'Reference table not found';
  END IF;
  IF _effective_from IS NULL OR (_effective_to IS NOT NULL AND _effective_to < _effective_from) THEN
    RAISE EXCEPTION 'Invalid effective date range';
  END IF;
  IF length(btrim(coalesce(_change_note, ''))) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'Change note must contain between 3 and 1000 characters';
  END IF;
  IF jsonb_typeof(_rows) <> 'array'
     OR jsonb_array_length(_rows) NOT BETWEEN 1 AND 10000 THEN
    RAISE EXCEPTION 'Reference version must contain between 1 and 10000 rows';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_rows) AS item
    WHERE jsonb_typeof(item) <> 'object'
  ) THEN
    RAISE EXCEPTION 'Every reference version row must be a JSON object';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(_table_id::text, 0));
  SELECT coalesce(max(rdv.version_number), 0) + 1
  INTO v_version_number
  FROM public.reference_data_versions rdv
  WHERE rdv.table_id = _table_id;

  INSERT INTO public.reference_data_versions(
    tenant_id, table_id, version_number, effective_from, effective_to,
    change_note, created_by
  ) VALUES (
    _tenant_id, _table_id, v_version_number, _effective_from, _effective_to,
    btrim(_change_note), actor
  ) RETURNING id INTO v_version_id;

  INSERT INTO public.reference_data_version_rows(
    version_id, tenant_id, table_id, row_data, key_hash
  )
  SELECT v_version_id, _tenant_id, _table_id, item, repeat('0', 64)
  FROM jsonb_array_elements(_rows) AS item;

  SELECT count(*)::integer,
         encode(digest(string_agg(r.key_hash || ':' || r.row_data::text, '|' ORDER BY r.key_hash), 'sha256'), 'hex')
  INTO v_row_count, v_content_sha256
  FROM public.reference_data_version_rows r
  WHERE r.version_id = v_version_id;

  UPDATE public.reference_data_versions rdv
  SET row_count = v_row_count, content_sha256 = v_content_sha256
  WHERE rdv.id = v_version_id;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    actor, _tenant_id, 'tenant', 'reference_data.version.stage',
    'reference_data_versions', v_version_id::text,
    jsonb_build_object('table_id', _table_id, 'version', v_version_number,
      'rows', v_row_count, 'content_sha256', v_content_sha256,
      'effective_from', _effective_from, 'effective_to', _effective_to)
  );

  version_id := v_version_id;
  version_number := v_version_number;
  row_count := v_row_count;
  content_sha256 := v_content_sha256;
  RETURN NEXT;
END;
$function$

