CREATE OR REPLACE FUNCTION public.tg_reference_data_table_version_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.reference_data_versions rdv WHERE rdv.table_id = OLD.id
  ) AND (
    NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
    OR NEW.key_columns IS DISTINCT FROM OLD.key_columns
    OR NEW.value_columns IS DISTINCT FROM OLD.value_columns
  ) THEN
    RAISE EXCEPTION 'Versioned reference table tenant and columns are immutable';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.dpdi_public_dataset_indexes(_dataset uuid, _logical_side text)
 RETURNS integer[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE link private.dpdi_public_output_links%ROWTYPE;d private.dpdi_published_datasets%ROWTYPE;p private.dpdi_job_pages%ROWTYPE;line text;v jsonb;ordinal integer:=0;answer integer[]:='{}';
BEGIN SELECT * INTO link FROM private.dpdi_public_output_links WHERE dataset_id=_dataset;SELECT * INTO d FROM private.dpdi_published_datasets WHERE id=link.private_dataset_id;
 IF d.id IS NULL THEN RAISE EXCEPTION 'dpdi.actual_public_output_link_required';END IF;
 FOR p IN SELECT * FROM private.dpdi_job_pages WHERE job_id=d.job_id ORDER BY sequence LOOP FOR line IN SELECT value FROM regexp_split_to_table(p.wire,E'\n') AS x(value) WHERE value<>'' LOOP v:=line::jsonb;IF _logical_side IS NULL OR v->>'business_side'=_logical_side THEN answer:=array_append(answer,ordinal);END IF;ordinal:=ordinal+1;END LOOP;END LOOP;
 IF ordinal<>d.rows THEN RAISE EXCEPTION 'dpdi.complete_public_output_index_coverage_required';END IF;RETURN answer;
END $function$

CREATE OR REPLACE FUNCTION public.dpds_checkpoint_parser(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _checkpoint jsonb, _expected_checkpoint_sha256 text, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'parser.progress',_request_context_id,_verified_subject);j private.dpd_parser_jobs%ROWTYPE;e private.dpd_parser_events%ROWTYPE;prior text;fingerprint text;offset_bytes bigint;
BEGIN SELECT * INTO j FROM private.dpd_parser_jobs WHERE id=_job_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;SELECT * INTO e FROM private.dpd_parser_events WHERE job_id=j.id ORDER BY created_at DESC,id DESC LIMIT 1;
 IF j.id IS NULL OR j.created_by<>actor OR e.phase<>'running' OR e.claim_key<>_claim_key OR e.lease_expires_at<=clock_timestamp() OR NOT private.dpd_original_viewable(j.file_id) OR jsonb_typeof(_checkpoint)IS DISTINCT FROM'object' OR octet_length(_checkpoint::text)>262144 OR _checkpoint->>'protocol'IS DISTINCT FROM'dpd-csv-slice-v1' OR _checkpoint->>'file_id'IS DISTINCT FROM j.file_id::text OR _checkpoint->>'original_sha256'IS DISTINCT FROM j.parser_binding->>'original_sha256' OR coalesce(_checkpoint->>'offset_bytes','')!~'^(0|[1-9][0-9]*)$' OR (_checkpoint->'sha'->>'bytes')::bigint IS DISTINCT FROM (_checkpoint->>'offset_bytes')::bigint THEN RAISE EXCEPTION 'dpds.actual_current_parser_checkpoint_required' USING ERRCODE='PT409';END IF;
 prior:=e.progress->>'checkpoint_sha256';IF prior IS DISTINCT FROM _expected_checkpoint_sha256 THEN RAISE EXCEPTION 'dpds.checkpoint_compare_exchange_conflict' USING ERRCODE='PT409';END IF;
 offset_bytes:=(_checkpoint->>'offset_bytes')::bigint;IF offset_bytes<=coalesce((e.progress->'checkpoint'->>'offset_bytes')::bigint,-1)OR offset_bytes>(SELECT verified_size_bytes FROM private.dpd_original_receipts WHERE file_id=j.file_id) THEN RAISE EXCEPTION 'dpds.contiguous_original_byte_checkpoint_required';END IF;
 IF (_checkpoint->>'raw_rows')::bigint IS DISTINCT FROM(SELECT coalesce(sum(row_count),0)FROM private.dpd_original_chunks WHERE file_id=j.file_id AND sheet_key='0')OR (_checkpoint->>'chunk_index')::integer IS DISTINCT FROM(SELECT count(*)FROM private.dpd_original_chunks WHERE file_id=j.file_id AND sheet_key='0') THEN RAISE EXCEPTION 'dpds.full_persisted_raw_chunk_checkpoint_required';END IF;
 fingerprint:=private.dpw_hash(_checkpoint);INSERT INTO private.dpd_parser_events(job_id,actor_id,phase,claim_key,lease_expires_at,progress)VALUES(j.id,actor,'running',_claim_key,clock_timestamp(),jsonb_build_object('checkpoint',_checkpoint,'checkpoint_sha256',fingerprint,'resume_required',true,'complete',false));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'file_id',j.file_id,'job_id',j.id,'state','running','checkpoint_sha256',fingerprint,'offset_bytes',offset_bytes::text,'raw_rows',_checkpoint->>'raw_rows','resume_required',true,'complete',false,'publish_allowed',false);
END$function$

CREATE OR REPLACE FUNCTION public.dpdi_register_public_output(_tenant_id uuid, _setup_id uuid, _private_dataset_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.perform',_request_context_id);d private.dpdi_published_datasets%ROWTYPE;j private.dpdi_jobs%ROWTYPE;e private.dpdi_job_events%ROWTYPE;link private.dpdi_public_output_links%ROWTYPE;upload public.workspace_data_source_uploads%ROWTYPE;dataset public.data_prep_prepared_datasets%ROWTYPE;rowarray jsonb;content text;wire_bytes bigint;qualification private.dpdi_output_registration_qualifications%ROWTYPE;
BEGIN
 SELECT * INTO d FROM private.dpdi_published_datasets WHERE id=_private_dataset_id AND tenant_id=_tenant_id AND setup_id=_setup_id FOR UPDATE;
 IF d.id IS NULL THEN RAISE EXCEPTION 'dpdi.actual_published_manifest_required';END IF;j:=private.dpdi_authorize(_tenant_id,_setup_id,d.job_id,actor,true);e:=private.dpdi_head(j.id);
 SELECT * INTO link FROM private.dpdi_public_output_links WHERE private_dataset_id=d.id;
 IF FOUND THEN SELECT * INTO dataset FROM public.data_prep_prepared_datasets WHERE id=link.dataset_id;IF private.dpdi_public_dataset_current(_tenant_id,dataset.id,actor) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.current_public_output_replay_evidence_denied' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset',to_jsonb(dataset),'output_upload_id',link.upload_id,'original_input_upload_id',NULL,'request_replay',true);END IF;
 IF j.snapshot->>'mode'<>'prepare' OR e.phase<>'success' OR e.blocking_records<>0 OR NOT EXISTS(SELECT 1 FROM private.dpdi_publication_decisions WHERE id=d.publication_decision_id AND decision='approved' AND output_root_sha256=e.output_root_sha256) THEN RAISE EXCEPTION 'dpdi.final_human_approved_output_required';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.id=d.pipeline_id AND p.tenant_id=_tenant_id AND p.version=d.pipeline_version AND p.status='approved' AND p.lifecycle_state='production' AND p.output_data_source_id=d.data_source_id) OR NOT EXISTS(SELECT 1 FROM public.data_prep_approved_configurations ac WHERE ac.tenant_id=_tenant_id AND ac.pipeline_id=d.pipeline_id AND ac.pipeline_version=d.pipeline_version AND ac.configuration_id=d.configuration_id AND ac.approved_by<>actor) THEN RAISE EXCEPTION 'dpdi.actual_governed_approved_production_transition_required_no_private_approval_waiver' USING ERRCODE='42501';END IF;
 SELECT coalesce(sum(octet_length(p.wire)),0) INTO wire_bytes FROM private.dpdi_job_pages p WHERE p.job_id=j.id;
 SELECT * INTO qualification FROM private.dpdi_output_registration_qualifications q WHERE q.tenant_id=_tenant_id AND q.configuration_id=d.configuration_id AND q.expires_at>clock_timestamp() AND q.qualified_at<=clock_timestamp() AND q.max_rows>=d.rows AND q.max_wire_bytes>=wire_bytes AND q.source_body_sha256=encode(sha256(convert_to(pg_get_functiondef('public.dpdi_register_public_output(uuid,uuid,uuid,uuid)'::regprocedure),'UTF8')),'hex') AND NOT EXISTS(SELECT 1 FROM private.dpdi_exact_output_capacity_certificates scoped WHERE scoped.qualification_id=q.id AND (scoped.tenant_id=_tenant_id AND scoped.setup_id=_setup_id AND scoped.private_dataset_id=d.id AND scoped.source_fingerprint=private.dpdi_capacity_source_fingerprint() AND scoped.configuration_sha256=j.snapshot->>'configuration_sha256' AND scoped.output_root_sha256=d.content_sha256 AND scoped.exact_wire_bytes=wire_bytes AND q.max_rows=2) IS DISTINCT FROM true) ORDER BY q.qualified_at DESC LIMIT 1;
 IF NOT FOUND AND private.dpdi_capacity_probe_allowed(_tenant_id,_setup_id,d.id,actor,_request_context_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.public_output_capacity_unqualified_preserve_published_manifest_no_fake_registration' USING ERRCODE='55000';END IF;
 -- One ordered aggregation, never per-row/per-page growing JSON copies.
 -- It still materializes the genuine legacy output array, so a real provider
 -- qualification matching exact configuration/source is mandatory above.
 WITH records AS MATERIALIZED(SELECT p.sequence,x.ordinality,x.value::jsonb record FROM private.dpdi_job_pages p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY AS x(value,ordinality) WHERE p.job_id=j.id AND x.value<>'')
 SELECT CASE WHEN bool_or(record->'blocking' IS DISTINCT FROM 'false'::jsonb OR record->'excluded' IS DISTINCT FROM 'false'::jsonb) THEN NULL ELSE coalesce(jsonb_agg((record->'payload')||jsonb_build_object('extras_json',record->'extras_json') ORDER BY sequence,ordinality),'[]') END INTO rowarray FROM records;
 IF rowarray IS NULL THEN RAISE EXCEPTION 'dpdi.no_blocked_or_unapproved_excluded_output_registration';END IF;
 IF jsonb_array_length(rowarray)<>d.rows THEN RAISE EXCEPTION 'dpdi.complete_output_registration_count_required';END IF;content:=private.dpw_hash(rowarray);PERFORM private.dpdi_capacity_capture_memory(_tenant_id,_setup_id,d.id,actor,_request_context_id);
 INSERT INTO public.workspace_data_source_uploads(tenant_id,data_source_id,filename,mime_type,size_bytes,row_count,columns,sample_rows,content_sha256,uploaded_by,rows)
 VALUES(_tenant_id,d.data_source_id,'prepared-'||d.id::text||'.json','application/json',octet_length(rowarray::text),jsonb_array_length(rowarray),j.snapshot->'confirmed_mapping'->'output_schema','[]',content,actor,rowarray) RETURNING * INTO upload;
 INSERT INTO public.data_prep_prepared_datasets(tenant_id,pipeline_id,pipeline_version,batch_id,run_id,business_date,data_source_id,upload_id,rows,content_sha256,request_key,published_by)
 VALUES(_tenant_id,d.pipeline_id,d.pipeline_version,(j.snapshot->>'batch_id')::uuid,d.run_id,d.business_date,d.data_source_id,upload.id,d.rows::integer,content,d.request_key,actor) RETURNING * INTO dataset;
 INSERT INTO private.dpdi_public_output_links(dataset_id,private_dataset_id,upload_id,original_inputs_have_no_legacy_upload) VALUES(dataset.id,d.id,upload.id,true);
 UPDATE public.data_prep_delivery_batches SET state='published' WHERE id=dataset.batch_id AND state='prepared';
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'public.output.registered',dataset.id,jsonb_build_object('actual_output_upload_id',upload.id,'original_input_upload_id',NULL,'rows',dataset.rows,'content_sha256',content,'hash_kind','native_jsonb_rows_sha256','source_manifest_hash_kind','immutable_page_prefix_sha256'));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset',to_jsonb(dataset),'output_upload_id',upload.id,'original_input_upload_id',NULL,'request_replay',false);
END $function$

CREATE OR REPLACE FUNCTION public.approve_data_prep_pipeline_as(_tenant_id uuid, _pipeline_id uuid, _actor_user_id uuid)
 RETURNS TABLE(pipeline_id uuid, public_uid text, pipeline_name text, pipeline_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target public.data_prep_pipelines%ROWTYPE;
  prior_lifecycle_setting text;
BEGIN
  PERFORM public.assert_data_prep_actor(_tenant_id, _actor_user_id, true);
  SELECT * INTO target FROM public.data_prep_pipelines
  WHERE id = _pipeline_id AND tenant_id = _tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Data Prep pipeline not found'; END IF;
  IF target.status <> 'draft' THEN RAISE EXCEPTION 'Only a draft Data Prep pipeline can be approved'; END IF;
  IF target.created_by IS NOT DISTINCT FROM _actor_user_id THEN
    RAISE EXCEPTION 'Four-eyes: pipeline maker cannot approve';
  END IF;
  prior_lifecycle_setting := current_setting('app.data_prep_lifecycle', true);
  PERFORM set_config('app.data_prep_lifecycle', 'on', true);
  UPDATE public.data_prep_pipelines
  SET status = 'approved', approved_at = now(), approved_by = _actor_user_id
  WHERE id = _pipeline_id AND tenant_id = _tenant_id;
  PERFORM set_config('app.data_prep_lifecycle', coalesce(prior_lifecycle_setting,''), true);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,_tenant_id,'workspace','data_prep.approve','data_prep_pipeline',_pipeline_id,
    jsonb_build_object('public_uid',target.public_uid,'name',target.name,'four_eyes',true));
  RETURN QUERY SELECT target.id, target.public_uid, target.name, 'approved'::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.clone_data_prep_staging_as(_tenant_id uuid, _pipeline_id uuid, _actor_user_id uuid)
 RETURNS TABLE(staging_pipeline_id uuid, staging_public_uid text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  source public.data_prep_pipelines%ROWTYPE;
  created public.data_prep_pipelines%ROWTYPE;
BEGIN
  PERFORM public.assert_data_prep_actor(_tenant_id, _actor_user_id, false);
  SELECT * INTO source FROM public.data_prep_pipelines
  WHERE id = _pipeline_id AND tenant_id = _tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Data Prep pipeline not found'; END IF;
  IF source.lifecycle_state <> 'production' OR source.status <> 'approved' THEN
    RAISE EXCEPTION 'Only an approved production pipeline can be cloned as staging';
  END IF;
  IF EXISTS (SELECT 1 FROM public.data_prep_pipelines
    WHERE tenant_id=_tenant_id AND parent_pipeline_id=_pipeline_id AND lifecycle_state='staging') THEN
    RAISE EXCEPTION 'A staging copy already exists for this pipeline';
  END IF;
  INSERT INTO public.data_prep_pipelines(
    tenant_id,name,description,source_data_source_id,output_data_source_id,steps,dq_rules,
    on_failure,enabled,status,version,lifecycle_state,parent_pipeline_id,bu_id,created_by
  ) VALUES (
    source.tenant_id,left(source.name || ' (staging)',120),source.description,
    source.source_data_source_id,NULL,source.steps,source.dq_rules,source.on_failure,true,
    'draft',1,'staging',source.id,source.bu_id,_actor_user_id
  ) RETURNING * INTO created;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,_tenant_id,'workspace','data_prep.clone_as_staging','data_prep_pipeline',created.id,
    jsonb_build_object('parent_id',source.id,'parent_name',source.name));
  RETURN QUERY SELECT created.id, created.public_uid;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_data_prep_promotion_as(_tenant_id uuid, _staging_id uuid, _note text, _actor_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target public.data_prep_pipelines%ROWTYPE;
  prior_lifecycle_setting text;
BEGIN
  PERFORM public.assert_data_prep_actor(_tenant_id, _actor_user_id, false);
  SELECT * INTO target FROM public.data_prep_pipelines
  WHERE id=_staging_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND OR target.lifecycle_state <> 'staging' OR target.parent_pipeline_id IS NULL THEN
    RAISE EXCEPTION 'Staging Data Prep pipeline not found';
  END IF;
  IF target.status <> 'approved' THEN RAISE EXCEPTION 'Approve the staging pipeline before promotion'; END IF;
  IF target.promotion_status = 'pending' THEN RAISE EXCEPTION 'Data Prep promotion is already pending'; END IF;
  IF length(coalesce(_note,'')) > 500 THEN RAISE EXCEPTION 'Promotion note exceeds 500 characters'; END IF;
  prior_lifecycle_setting := current_setting('app.data_prep_lifecycle', true);
  PERFORM set_config('app.data_prep_lifecycle', 'on', true);
  UPDATE public.data_prep_pipelines SET promotion_status='pending',
    promotion_requested_by=_actor_user_id,promotion_requested_at=now(),promotion_note=nullif(trim(_note),'')
  WHERE id=_staging_id AND tenant_id=_tenant_id;
  PERFORM set_config('app.data_prep_lifecycle', coalesce(prior_lifecycle_setting,''), true);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,_tenant_id,'workspace','data_prep.request_promotion','data_prep_pipeline',_staging_id,
    jsonb_build_object('note',nullif(trim(_note),''),'four_eyes_required',true));
  RETURN 'pending';
END;
$function$

CREATE OR REPLACE FUNCTION public.decide_data_prep_promotion_as(_tenant_id uuid, _staging_id uuid, _approve boolean, _comment text, _actor_user_id uuid)
 RETURNS TABLE(decision text, production_pipeline_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  staging public.data_prep_pipelines%ROWTYPE;
  production public.data_prep_pipelines%ROWTYPE;
  prior_lifecycle_setting text;
BEGIN
  PERFORM public.assert_data_prep_actor(_tenant_id, _actor_user_id, true);
  SELECT * INTO staging FROM public.data_prep_pipelines
  WHERE id=_staging_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND OR staging.lifecycle_state <> 'staging' OR staging.promotion_status <> 'pending' THEN
    RAISE EXCEPTION 'Data Prep pipeline is not pending promotion';
  END IF;
  IF staging.promotion_requested_by IS NOT DISTINCT FROM _actor_user_id THEN
    RAISE EXCEPTION 'Four-eyes: promotion requester cannot decide';
  END IF;
  IF length(coalesce(_comment,'')) > 500 THEN RAISE EXCEPTION 'Promotion comment exceeds 500 characters'; END IF;
  INSERT INTO public.dp_promotion_approvals(staging_pipeline_id,tenant_id,approver_id,decision,comment)
  VALUES (_staging_id,_tenant_id,_actor_user_id,CASE WHEN _approve THEN 'approve' ELSE 'reject' END,
    nullif(trim(_comment),''));
  prior_lifecycle_setting := current_setting('app.data_prep_lifecycle', true);
  PERFORM set_config('app.data_prep_lifecycle', 'on', true);
  IF NOT _approve THEN
    UPDATE public.data_prep_pipelines SET promotion_status='rejected'
    WHERE id=_staging_id AND tenant_id=_tenant_id;
    PERFORM set_config('app.data_prep_lifecycle', coalesce(prior_lifecycle_setting,''), true);
    INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (_actor_user_id,_tenant_id,'workspace','data_prep.reject_promotion','data_prep_pipeline',_staging_id,
      jsonb_build_object('comment',nullif(trim(_comment),''),'four_eyes',true));
    RETURN QUERY SELECT 'rejected'::text, staging.parent_pipeline_id;
    RETURN;
  END IF;
  SELECT * INTO production FROM public.data_prep_pipelines
  WHERE id=staging.parent_pipeline_id AND tenant_id=_tenant_id AND lifecycle_state='production' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Production Data Prep pipeline not found'; END IF;
  UPDATE public.data_prep_pipelines SET
    steps=staging.steps,dq_rules=staging.dq_rules,on_failure=staging.on_failure,
    description=staging.description,version=coalesce(production.version,1)+1,status='approved',
    approved_at=now(),approved_by=_actor_user_id,promoted_from_id=staging.id,
    promoted_at=now(),promoted_by=_actor_user_id
  WHERE id=production.id AND tenant_id=_tenant_id;
  UPDATE public.data_prep_pipelines SET lifecycle_state='archived',promotion_status='approved',
    status='archived',enabled=false WHERE id=staging.id AND tenant_id=_tenant_id;
  PERFORM set_config('app.data_prep_lifecycle', coalesce(prior_lifecycle_setting,''), true);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,_tenant_id,'workspace','data_prep.promote','data_prep_pipeline',production.id,
    jsonb_build_object('staging_id',staging.id,'comment',nullif(trim(_comment),''),'four_eyes',true));
  RETURN QUERY SELECT 'approved'::text, production.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.archive_data_prep_pipeline_as(_tenant_id uuid, _pipeline_id uuid, _reason text, _actor_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target public.data_prep_pipelines%ROWTYPE;
  prior_lifecycle_setting text;
BEGIN
  PERFORM public.assert_data_prep_actor(_tenant_id, _actor_user_id, true);
  SELECT * INTO target FROM public.data_prep_pipelines
  WHERE id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Data Prep pipeline not found'; END IF;
  IF target.lifecycle_state='archived' THEN RETURN 'archived'; END IF;
  IF target.promotion_status='pending' THEN RAISE EXCEPTION 'Pending promotion must be decided before archival'; END IF;
  IF length(trim(coalesce(_reason,''))) < 3 OR length(_reason) > 500 THEN
    RAISE EXCEPTION 'Archival reason must contain between 3 and 500 characters';
  END IF;
  prior_lifecycle_setting := current_setting('app.data_prep_lifecycle', true);
  PERFORM set_config('app.data_prep_lifecycle', 'on', true);
  UPDATE public.data_prep_pipelines SET lifecycle_state='archived',status='archived',enabled=false
  WHERE id=_pipeline_id AND tenant_id=_tenant_id;
  PERFORM set_config('app.data_prep_lifecycle', coalesce(prior_lifecycle_setting,''), true);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,_tenant_id,'workspace','data_prep.archive','data_prep_pipeline',_pipeline_id,
    jsonb_build_object('reason',trim(_reason),'prior_lifecycle',target.lifecycle_state,'prior_status',target.status));
  RETURN 'archived';
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_data_prep_actor(_tenant_id uuid, _actor_user_id uuid, _admin_only boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF _tenant_id IS NULL OR _actor_user_id IS NULL THEN
    RAISE EXCEPTION 'Accountable Data Prep actor is required';
  END IF;
  IF public.is_platform_admin(_actor_user_id) THEN RETURN; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tenant_members tm
    WHERE tm.tenant_id = _tenant_id AND tm.user_id = _actor_user_id
      AND tm.active = true
      AND ((_admin_only AND tm.role = 'tenant_admin')
        OR (NOT _admin_only AND tm.role IN ('tenant_admin','tenant_analyst')))
  ) THEN
    RAISE EXCEPTION 'Forbidden: active Data Prep % role required',
      CASE WHEN _admin_only THEN 'administrator' ELSE 'writer' END;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_seed_email text;
begin
  insert into public.profiles (id, email, full_name, avatar_url)
  values (new.id, new.email,
    coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name'),
    new.raw_user_meta_data->>'avatar_url')
  on conflict (id) do nothing;

  begin v_seed_email := current_setting('app.platform_admin_seed_email', true);
  exception when others then v_seed_email := null; end;

  if v_seed_email is not null and lower(v_seed_email) = lower(new.email) then
    insert into public.platform_roles (user_id, role) values (new.id, 'platform_admin')
    on conflict do nothing;
  end if;
  return new;
end; $function$

CREATE OR REPLACE FUNCTION public.cutover_assurance_synthetic_recon_mapping(_tenant_id uuid, _recon_id uuid, _owner_bu_ids uuid[], _maker_user_id uuid, _checker_user_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE v_code text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.tenants t WHERE t.id=_tenant_id
      AND t.slug::text='falcon-veritas-assurance-lab-prod') THEN
    RAISE EXCEPTION 'definition is outside the approved synthetic Assurance tenant' USING ERRCODE='42501';
  END IF;
  SELECT d.recon_code INTO v_code FROM public.recon_definitions d
  WHERE d.id=_recon_id AND d.tenant_id=_tenant_id FOR UPDATE;
  IF v_code IS NULL OR v_code NOT IN (
    'FVI-GEN-2WAY-000008','FVI-GEN-2WAY-000007','FVI-GEN-1WAY-000003','FVI-GEN-2WAY-000006',
    'FVI-GEN-1WAY-000004','FVI-GEN-1WAY-000002','FVI-GEN-3WAY-000006','FVI-GEN-1WAY-000001',
    'FVI-GEN-2WAY-000005','FVI-GEN-2WAY-000001','FVI-GEN-2WAY-000002','FVI-GEN-2WAY-000003',
    'FVI-GEN-3WAY-000001','FVI-GEN-3WAY-000002','FVI-GEN-2WAY-000004','FVI-GEN-3WAY-000003',
    'FVI-GEN-3WAY-000004','FVI-GEN-3WAY-000005','FVI-GEN-2WAY-000009','FVI-GEN-2WAY-000010'
  ) THEN
    RAISE EXCEPTION 'definition is outside the approved synthetic Assurance mapping list' USING ERRCODE='42501';
  END IF;
  RETURN public.cutover_legacy_recon_definition_mapping(
    _tenant_id,_recon_id,_owner_bu_ids,_maker_user_id,_checker_user_id,_reason
  );
END
$function$

CREATE OR REPLACE FUNCTION public.dpdi_lookup_prepare_request(_tenant_id uuid, _setup_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.status',_request_context_id);j private.dpdi_jobs%ROWTYPE;
BEGIN SELECT * INTO j FROM private.dpdi_jobs WHERE tenant_id=_tenant_id AND setup_id=_setup_id AND actor_id=actor AND request_key=_request_key AND snapshot->>'mode'='prepare';
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'mode','prepare','publish_allowed',false,'found',false,'job_id',NULL);END IF;
 PERFORM private.dpdi_authorize(_tenant_id,_setup_id,j.id,actor,false);RETURN private.dpdi_dto(j)||jsonb_build_object('found',true,'setup_review_decision_id',j.snapshot->>'setup_review_decision_id','business_date',j.snapshot->>'business_date');
END$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION private.dpw_feeds(_pipeline uuid, _version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v jsonb; p public.data_prep_pipelines%ROWTYPE;
 BEGIN
 SELECT coalesce(jsonb_agg(jsonb_build_object('key',f.feed_key,'name',f.name,'vendor',f.vendor,'layout_id',f.layout_id,
 'business_side',f.business_side,'record_type',f.record_type,'data_source_id',f.data_source_id,'required',f.required,
 'allow_empty',f.allow_empty,'mappings',f.mappings,'steps',f.steps,'pipeline_version',f.pipeline_version) ORDER BY f.feed_key),'[]') INTO v
 FROM public.data_prep_input_profiles f JOIN private.dpw_configuration_heads h ON h.configuration_id=f.configuration_id
 WHERE h.pipeline_id=_pipeline AND f.pipeline_version=_version;
 IF jsonb_array_length(v)>0 THEN RETURN v; END IF;
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=_pipeline AND version=_version;
 IF p.source_data_source_id IS NULL THEN RETURN '[]'::jsonb; END IF;
 RETURN jsonb_build_array(jsonb_build_object('key','legacy:'||p.source_data_source_id::text,'name','Legacy single input',
 'vendor','Legacy','layout_id','legacy','business_side','legacy','record_type','legacy','data_source_id',p.source_data_source_id,
 'required',true,'allow_empty',false,'mappings','{}'::jsonb,'steps','[]'::jsonb,'pipeline_version',_version,'virtual',true));
END $function$

CREATE OR REPLACE FUNCTION public.dpw_finish_preparation(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _run_id uuid, _request_key uuid, _verified_subject jsonb, _snapshot_sha256 text, _result jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid; b public.data_prep_delivery_batches%ROWTYPE; r public.data_prep_delivery_runs%ROWTYPE;
 status text:=_result->>'status'; expected_status text; has_failure boolean; has_critical boolean;
 eligible boolean; item jsonb; ref jsonb; u public.workspace_data_source_uploads%ROWTYPE; n integer; allinputs integer;
BEGIN
 actor:=private.dpw_processor_actor(_tenant_id,_pipeline_id,_verified_subject,'run');
 b:=private.dpw_lock_batch(_tenant_id,_pipeline_id,_batch_id,actor,false);
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run_id AND batch_id=b.id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR r.started_by<>actor OR r.request_key<>_request_key
 OR r.snapshot_sha256 IS DISTINCT FROM _snapshot_sha256
 OR jsonb_typeof(_result->'acceptedRows') IS DISTINCT FROM 'array' OR jsonb_array_length(_result->'acceptedRows')>50000
 OR jsonb_typeof(_result->'rejectedRecords') IS DISTINCT FROM 'array' OR jsonb_typeof(_result->'dqResults') IS DISTINCT FROM 'array'
 OR jsonb_typeof(_result->'outputLineage') IS DISTINCT FROM 'array' OR jsonb_typeof(_result->'countsPerFeed') IS DISTINCT FROM 'array'
 OR status IS NULL OR status NOT IN('success','warn','failed')
 THEN RAISE EXCEPTION 'dpw.processor_snapshot_result_mismatch'; END IF;
 _result:=(_result-ARRAY['content_sha256','lineage_sha256','snapshot_sha256'])||jsonb_build_object(
 'structured_data_sha256',private.dpw_hash(_result->'acceptedRows'),'structured_lineage_sha256',private.dpw_hash(_result->'outputLineage'),
 'native_snapshot_sha256',r.snapshot_sha256);
 FOR item IN SELECT value FROM jsonb_array_elements(r.snapshot->'feeds') LOOP
  IF private.dpw_source_allows(actor,_tenant_id,(item->>'data_source_id')::uuid,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.source_revoked'; END IF;
 END LOOP;
 IF r.finished_at IS NOT NULL THEN
  IF r.result IS DISTINCT FROM _result THEN RAISE EXCEPTION 'dpw.completion_conflict'; END IF;
  RETURN jsonb_build_object('tenant_id',_tenant_id,'run',to_jsonb(r),'processor_actor_id',actor,'transport_role','service_role','is_new',false);
 END IF;
 IF r.state<>'running' OR b.state<>'processing' THEN RAISE EXCEPTION 'dpw.processor_run_closed'; END IF;
 -- The server computes transforms. Native rejects inconsistent declared DQ,
 -- all input totals and references, and never infers ready from output presence.
 IF jsonb_array_length(_result->'dqResults')<>jsonb_array_length(r.snapshot->'dq_rules')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_result->'dqResults') WITH ORDINALITY d(value,ord)
 WHERE jsonb_typeof(value->'failures') IS DISTINCT FROM 'number' OR jsonb_typeof(value->'total') IS DISTINCT FROM 'number'
 OR (value->>'failures')::integer<0 OR (value->>'failures')::integer>(value->>'total')::integer
 OR value->>'rule_id' IS DISTINCT FROM r.snapshot->'dq_rules'->(ord::integer-1)->>'id'
 OR value->>'field' IS DISTINCT FROM r.snapshot->'dq_rules'->(ord::integer-1)->>'field'
 OR value->>'kind' IS DISTINCT FROM r.snapshot->'dq_rules'->(ord::integer-1)->>'kind'
 OR value->>'severity' IS DISTINCT FROM coalesce(r.snapshot->'dq_rules'->(ord::integer-1)->>'severity','warning'))
 THEN RAISE EXCEPTION 'dpw.dq_evidence_incomplete'; END IF;
 SELECT coalesce(bool_or((value->>'failures')::integer>0),false),
 coalesce(bool_or((value->>'failures')::integer>0 AND value->>'severity'<>'info'),false)
 INTO has_failure,has_critical FROM jsonb_array_elements(_result->'dqResults');
 expected_status:=CASE WHEN has_critical OR (_result->>'blocking_failure')::boolean IS TRUE THEN 'failed'
 WHEN has_failure THEN 'warn' ELSE 'success' END;
 IF status IS DISTINCT FROM expected_status THEN RAISE EXCEPTION 'dpw.dq_status_mismatch'; END IF;
 eligible:=b.mode='prepare' AND status<>'failed';
 IF status<>'failed' AND EXISTS(SELECT 1 FROM jsonb_array_elements(_result->'rejectedRecords') WHERE value->>'disposition'='blocked')
 THEN RAISE EXCEPTION 'dpw.blocked_rows_cannot_release'; END IF;
 IF (_result->>'publication_eligible')::boolean IS DISTINCT FROM eligible OR (status='failed' AND jsonb_array_length(_result->'acceptedRows')<>0)
 THEN RAISE EXCEPTION 'dpw.dq_disposition_mismatch'; END IF;
 SELECT sum(row_count) INTO allinputs FROM public.data_prep_run_inputs WHERE run_id=r.id;
 IF (SELECT sum((value->>'input')::integer) FROM jsonb_array_elements(_result->'countsPerFeed')) IS DISTINCT FROM allinputs
 OR (SELECT sum((value->>'accepted')::integer) FROM jsonb_array_elements(_result->'countsPerFeed')) IS DISTINCT FROM jsonb_array_length(_result->'acceptedRows')
 THEN RAISE EXCEPTION 'dpw.full_input_totals_mismatch'; END IF;
 IF jsonb_array_length(_result->'outputLineage')<>jsonb_array_length(_result->'acceptedRows') THEN RAISE EXCEPTION 'dpw.output_lineage_incomplete'; END IF;
 n:=0;
 FOR item IN SELECT value FROM jsonb_array_elements(_result->'outputLineage') LOOP
  IF (item->>'output_index')::integer IS DISTINCT FROM n OR item->>'pipeline_id' IS DISTINCT FROM _pipeline_id::text
  OR (item->>'pipeline_version')::integer IS DISTINCT FROM r.pipeline_version OR item->>'batch_id' IS DISTINCT FROM b.id::text
  OR item->>'business_date' IS DISTINCT FROM b.business_date::text OR jsonb_typeof(item->'sources') IS DISTINCT FROM 'array'
  OR jsonb_array_length(item->'sources')=0 THEN RAISE EXCEPTION 'dpw.lineage_binding_mismatch'; END IF;
  IF (SELECT count(DISTINCT value->>'business_side') FROM jsonb_array_elements(item->'sources'))<>1
  OR (SELECT count(DISTINCT value->>'record_type') FROM jsonb_array_elements(item->'sources'))<>1
  THEN RAISE EXCEPTION 'dpw.opposing_logical_sides_or_record_types_cannot_merge'; END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(item->'sources') LOOP
   u:=private.dpw_input_reference(r.id,ref);
   INSERT INTO public.data_prep_record_lineage VALUES(r.id,n,(ref->>'file_id')::uuid,(ref->>'record_index')::integer);
  END LOOP;
  n:=n+1;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(_result->'rejectedRecords') LOOP
  ref:=item->'source';
  u:=private.dpw_input_reference(r.id,ref);
  IF u.rows->((ref->>'record_index')::integer) IS DISTINCT FROM item->'original_row' THEN RAISE EXCEPTION 'dpw.reject_source_mismatch'; END IF;
  IF item->>'disposition'='dropped' AND NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_files f,
  jsonb_array_elements(coalesce(r.snapshot->'approved_exclusions','[]'::jsonb)) e
  WHERE f.id=(ref->>'file_id')::uuid AND f.correction_of=(e.value->>'file_id')::uuid
  AND f.content_sha256=e.value->>'content_sha256' AND (ref->>'record_index')::integer=(e.value->>'record_index')::integer
  AND b.exclusion_approval_id IS NOT NULL)
  THEN RAISE EXCEPTION 'dpw.exclusion_requires_independent_approval_and_complete_rerun'; END IF;
  INSERT INTO public.data_prep_reject_lineage(tenant_id,run_id,file_id,source_index,disposition,original_row,prepared_row,reasons)
  VALUES(_tenant_id,r.id,(ref->>'file_id')::uuid,(ref->>'record_index')::integer,item->>'disposition',item->'original_row',item->'prepared_row',item->'reasons');
 END LOOP;
 IF (SELECT count(*) FROM (SELECT file_id,source_index FROM public.data_prep_record_lineage WHERE run_id=r.id
 UNION SELECT file_id,source_index FROM public.data_prep_reject_lineage WHERE run_id=r.id) covered)<>allinputs
 THEN RAISE EXCEPTION 'dpw.full_input_lineage_coverage_required'; END IF;
 UPDATE public.data_prep_delivery_runs SET state=status,result=_result,result_sha256=private.dpw_hash(_result),finished_at=now() WHERE id=r.id RETURNING * INTO r;
 UPDATE public.data_prep_delivery_batches SET state=CASE WHEN eligible THEN 'prepared' ELSE 'failed' END WHERE id=b.id;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.preparation.finish',r.id,jsonb_build_object('status',status,'result_sha256',r.result_sha256,'transport','closed_service_processor'));
 RETURN jsonb_build_object('tenant_id',_tenant_id,'run',to_jsonb(r),'processor_actor_id',actor,'transport_role','service_role','is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.guard_environment_change_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_setting('app.environment_change_lifecycle',true) <> 'on' THEN
    RAISE EXCEPTION 'Use governed environment change functions';
  END IF;
  IF TG_TABLE_NAME='environment_change_requests' AND TG_OP='UPDATE' THEN
    IF NEW.status='executing' AND OLD.status<>'executing' AND NEW.approval_stage<>'target_review' THEN
      RAISE EXCEPTION 'Only a target-approved package can execute';
    END IF;
    IF NEW.status='succeeded' AND OLD.status='executing' AND NEW.approval_stage='target_review' THEN
      NEW.activation_status := CASE
        WHEN coalesce((NEW.access_mapping_preview->>'missing')::integer,0)=0
         AND coalesce((NEW.access_mapping_preview->>'ambiguous')::integer,0)=0
        THEN 'active'
        ELSE 'pending_access'
      END;
    END IF;
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION pgmq.format_table_name(queue_name text, prefix text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF queue_name ~ '\$|;|--|'''
    THEN
        RAISE EXCEPTION 'queue name contains invalid characters: $, ;, --, or \''';
    END IF;
    RETURN lower(prefix || '_' || queue_name);
END;
$function$

CREATE OR REPLACE FUNCTION pgmq.read_with_poll(queue_name text, vt integer, qty integer, max_poll_seconds integer DEFAULT 5, poll_interval_ms integer DEFAULT 100, conditional jsonb DEFAULT '{}'::jsonb)
 RETURNS SETOF pgmq.message_record
 LANGUAGE plpgsql
AS $function$
DECLARE
    r pgmq.message_record;
    stop_at TIMESTAMP;
    sql TEXT;
    qtable TEXT := pgmq.format_table_name(queue_name, 'q');
BEGIN
    stop_at := clock_timestamp() + make_interval(secs => max_poll_seconds);
    LOOP
      IF (SELECT clock_timestamp() >= stop_at) THEN
        RETURN;
      END IF;

      sql := FORMAT(
          $QUERY$
          WITH cte AS
          (
              SELECT msg_id
              FROM pgmq.%I
              WHERE vt <= clock_timestamp() AND CASE
                  WHEN %L != '{}'::jsonb THEN (message @> %2$L)::integer
                  ELSE 1
              END = 1
              ORDER BY msg_id ASC
              LIMIT $1
              FOR UPDATE SKIP LOCKED
          )
          UPDATE pgmq.%I m
          SET
              vt = clock_timestamp() + %L,
              read_ct = read_ct + 1
          FROM cte
          WHERE m.msg_id = cte.msg_id
          RETURNING m.msg_id, m.read_ct, m.enqueued_at, m.vt, m.message, m.headers;
          $QUERY$,
          qtable, conditional, qtable, make_interval(secs => vt)
      );

      FOR r IN
        EXECUTE sql USING qty
      LOOP
        RETURN NEXT r;
      END LOOP;
      IF FOUND THEN
        RETURN;
      ELSE
        PERFORM pg_sleep(poll_interval_ms::numeric / 1000);
      END IF;
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION pgmq.archive(queue_name text, msg_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    sql TEXT;
    result BIGINT;
    qtable TEXT := pgmq.format_table_name(queue_name, 'q');
    atable TEXT := pgmq.format_table_name(queue_name, 'a');
BEGIN
    sql := FORMAT(
        $QUERY$
        WITH archived AS (
            DELETE FROM pgmq.%I
            WHERE msg_id = $1
            RETURNING msg_id, vt, read_ct, enqueued_at, message, headers
        )
        INSERT INTO pgmq.%I (msg_id, vt, read_ct, enqueued_at, message, headers)
        SELECT msg_id, vt, read_ct, enqueued_at, message, headers
        FROM archived
        RETURNING msg_id;
        $QUERY$,
        qtable, atable
    );
    EXECUTE sql USING msg_id INTO result;
    RETURN NOT (result IS NULL);
END;
$function$

