CREATE OR REPLACE FUNCTION public.complete_environment_change_execution_for_api(_request_id uuid, _outcome text, _component_results jsonb, _final_readback jsonb, _rollback_reason text, _actor_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target public.environment_change_requests%ROWTYPE;
  prior_setting text;
  failed text[];
  readback_digest text;
  final_status text;
  final_event text;
BEGIN
  SELECT * INTO target FROM public.environment_change_requests WHERE id=_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Environment change request not found'; END IF;
  PERFORM public.assert_environment_change_actor(target.control_tenant_id,_actor_user_id);
  IF target.status<>'executing' OR target.executed_by IS DISTINCT FROM _actor_user_id THEN
    RAISE EXCEPTION 'Execution is not active for this actor';
  END IF;
  IF _outcome NOT IN ('succeeded','failed','rolled_back') THEN RAISE EXCEPTION 'Invalid execution outcome'; END IF;
  IF jsonb_typeof(_component_results)<>'array' OR jsonb_array_length(_component_results)<>3 THEN
    RAISE EXCEPTION 'Exactly three component results are required';
  END IF;
  PERFORM public.assert_environment_payload_safe(_component_results);
  PERFORM public.assert_environment_payload_safe(_final_readback);
  IF (SELECT count(distinct item->>'component') FROM jsonb_array_elements(_component_results) item
      WHERE item->>'component' IN ('package','configuration','settings'))<>3
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(_component_results) item
       WHERE item->>'status' NOT IN ('pass','fail','skipped')) THEN
    RAISE EXCEPTION 'Invalid component results';
  END IF;
  SELECT coalesce(array_agg(item->>'component' ORDER BY item->>'component'),ARRAY[]::text[]) INTO failed
  FROM jsonb_array_elements(_component_results) item WHERE item->>'status'='fail';
  IF _outcome='succeeded' AND cardinality(failed)>0 THEN RAISE EXCEPTION 'Successful outcome cannot contain failed components'; END IF;
  IF _outcome='succeeded' AND (_final_readback IS NULL OR jsonb_typeof(_final_readback)<>'object') THEN
    RAISE EXCEPTION 'Successful outcome requires final readback';
  END IF;
  IF _outcome='failed' AND cardinality(failed)=0 THEN RAISE EXCEPTION 'Failed outcome requires a failed component'; END IF;
  IF _outcome='rolled_back' AND length(trim(coalesce(_rollback_reason,'')))<10 THEN
    RAISE EXCEPTION 'Rollback requires a reason';
  END IF;
  readback_digest := CASE WHEN _final_readback IS NULL THEN NULL
    ELSE encode(extensions.digest(convert_to(_final_readback::text,'UTF8'),'sha256'),'hex') END;
  final_status := _outcome;
  final_event := CASE _outcome WHEN 'succeeded' THEN 'execution_succeeded'
    WHEN 'failed' THEN 'execution_failed' ELSE 'execution_rolled_back' END;
  prior_setting := current_setting('app.environment_change_lifecycle',true);
  PERFORM set_config('app.environment_change_lifecycle','on',true);
  UPDATE public.environment_change_requests SET status=final_status,component_results=_component_results,
    failed_components=failed,execution_completed_at=now(),deployment_outcome=_outcome,
    rollback_reason=nullif(trim(_rollback_reason),''),final_readback=_final_readback,
    final_readback_hash=readback_digest WHERE id=_request_id;
  PERFORM set_config('app.environment_change_lifecycle',coalesce(prior_setting,''),true);
  PERFORM public.append_environment_change_event(_request_id,final_event,_actor_user_id,
    jsonb_build_object('execution_id',target.execution_id,'outcome',_outcome,
      'component_results',_component_results,'failed_components',failed,
      'rollback_reason',nullif(trim(_rollback_reason),''),'final_readback_hash',readback_digest));
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,target.control_tenant_id,'platform','environment_change.'||_outcome,
    'environment_change_request',_request_id::text,
    jsonb_build_object('execution_id',target.execution_id,'manifest_hash',target.manifest_hash,
      'failed_components',failed,'final_readback_hash',readback_digest,'rollback_reason',nullif(trim(_rollback_reason),'')));
  RETURN final_status;
END;
$function$

CREATE OR REPLACE FUNCTION private.dpw_lock_batch(_tenant uuid, _pipeline uuid, _batch uuid, _actor uuid, _collecting boolean)
 RETURNS data_prep_delivery_batches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE b public.data_prep_delivery_batches%ROWTYPE; p public.data_prep_pipelines%ROWTYPE;
BEGIN
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=_pipeline AND tenant_id=_tenant FOR UPDATE;
 SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=_batch AND tenant_id=_tenant AND pipeline_id=_pipeline FOR UPDATE;
 IF private.dpw_mode_attest(_actor,_tenant,_pipeline,b.execution_mode,b.human_in_loop) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.mode_revoked'; END IF;
 IF NOT FOUND OR (_collecting AND b.state<>'collecting')
 OR p.version<>b.pipeline_version OR (b.mode='prepare' AND (p.status<>'approved' OR p.lifecycle_state<>'production'))
 OR (b.mode='preview' AND (p.status NOT IN('draft','approved') OR p.lifecycle_state='archived'))
 OR private.dpw_snapshot(_pipeline) IS DISTINCT FROM (b.configuration_snapshot-ARRAY['quality_gate','exclusion_approval_id','approved_exclusions','exclusion_source_run_id','correction_source_run_id','correction_source_files','correction_manifest_origin'])
 THEN RAISE EXCEPTION 'dpw.batch_binding_unavailable' USING ERRCODE='42501'; END IF;
 RETURN b;
END $function$

CREATE OR REPLACE FUNCTION public.move_to_dlq(source_queue text, dlq_name text, message_id bigint, payload jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE new_id BIGINT;
BEGIN
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  PERFORM pgmq.delete(source_queue, message_id);
  RETURN new_id;
EXCEPTION WHEN undefined_table THEN
  BEGIN
    PERFORM pgmq.create(dlq_name);
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;
  SELECT pgmq.send(dlq_name, payload) INTO new_id;
  BEGIN
    PERFORM pgmq.delete(source_queue, message_id);
  EXCEPTION WHEN undefined_table THEN
    NULL;
  END;
  RETURN new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_bu_set_path()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_parent_path ltree; v_parent_depth int; v_label text;
BEGIN
  v_label := replace(replace(NEW.id::text,'-','_'),'.','_');
  IF NEW.parent_id IS NULL THEN
    NEW.path := text2ltree(v_label);
    NEW.depth := 0;
  ELSE
    SELECT path, depth INTO v_parent_path, v_parent_depth FROM public.business_units WHERE id = NEW.parent_id;
    IF v_parent_path IS NULL THEN RAISE EXCEPTION 'Parent BU not found'; END IF;
    IF TG_OP = 'UPDATE' AND OLD.path IS NOT NULL AND v_parent_path <@ OLD.path THEN
      RAISE EXCEPTION 'BU reparent would create cycle';
    END IF;
    NEW.path := v_parent_path || v_label;
    NEW.depth := v_parent_depth + 1;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.request_source_environment_change_as(_request jsonb, _actor_user_id uuid)
 RETURNS TABLE(request_id uuid, change_request_uid text, request_status text, manifest_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  source_tenant uuid := nullif(_request->>'source_tenant_id','')::uuid;
  target_tenant uuid := nullif(_request->>'target_tenant_id','')::uuid;
  source_ref text := _request->>'source_project_ref';
  target_ref text := _request->>'target_project_ref';
  source_env text := _request->>'source_environment';
  target_env text := _request->>'target_environment';
  direction_value text := _request->>'direction';
  requested_manifest jsonb := _request->'manifest';
  validations jsonb := coalesce(_request->'validation_results','[]'::jsonb);
  request_key text := nullif(trim(_request->>'idempotency_key'),'');
  package_digest text;
  configuration_digest text;
  settings_digest text;
  aggregate_digest text;
  created public.environment_change_requests%ROWTYPE;
BEGIN
  PERFORM public.assert_environment_change_actor(source_tenant,_actor_user_id);
  PERFORM public.assert_environment_manifest_safe(requested_manifest);
  PERFORM public.assert_environment_payload_safe(validations);
  IF direction_value<>source_env||'_to_'||target_env THEN RAISE EXCEPTION 'Direction does not match source and target'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.environment_release_registry
    WHERE environment=source_env AND project_ref=source_ref AND enabled) THEN
    RAISE EXCEPTION 'Source environment is not registered and enabled';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.environment_release_registry
    WHERE environment=target_env AND project_ref=target_ref AND enabled) THEN
    RAISE EXCEPTION 'Target environment is not registered and enabled';
  END IF;
  IF source_tenant IS NULL OR target_tenant IS NULL THEN RAISE EXCEPTION 'Source and target tenants are required'; END IF;
  IF request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'Invalid idempotency key'; END IF;
  IF length(trim(coalesce(_request->>'title',''))) NOT BETWEEN 3 AND 120
     OR length(trim(coalesce(_request->>'reason',''))) NOT BETWEEN 10 AND 1000 THEN
    RAISE EXCEPTION 'Valid title and reason are required';
  END IF;
  IF jsonb_typeof(validations)<>'array' OR jsonb_array_length(validations)=0
     OR EXISTS (SELECT 1 FROM jsonb_array_elements(validations) item
       WHERE item->>'status' NOT IN ('pass','fail') OR nullif(item->>'check','') IS NULL) THEN
    RAISE EXCEPTION 'Valid source preflight results are required';
  END IF;
  package_digest := encode(extensions.digest(convert_to((requested_manifest->'package')::text,'UTF8'),'sha256'),'hex');
  configuration_digest := encode(extensions.digest(convert_to((requested_manifest->'configuration')::text,'UTF8'),'sha256'),'hex');
  settings_digest := encode(extensions.digest(convert_to((requested_manifest->'settings')::text,'UTF8'),'sha256'),'hex');
  aggregate_digest := encode(extensions.digest(convert_to(requested_manifest::text,'UTF8'),'sha256'),'hex');
  SELECT * INTO created FROM public.environment_change_requests
  WHERE control_tenant_id=source_tenant AND requested_by=_actor_user_id AND idempotency_key=request_key;
  IF FOUND THEN
    IF created.manifest_hash<>aggregate_digest OR created.direction<>direction_value THEN
      RAISE EXCEPTION 'Idempotency key is already bound to another package';
    END IF;
    RETURN QUERY SELECT created.id,created.change_request_uid,created.status,created.manifest_hash;
    RETURN;
  END IF;
  INSERT INTO public.environment_change_requests(
    change_request_uid,control_tenant_id,direction,source_project_ref,source_tenant_id,
    source_environment,target_project_ref,target_tenant_id,target_environment,title,reason,
    manifest,package_hash,configuration_hash,settings_hash,manifest_hash,requested_by,
    idempotency_key,validation_results,approval_stage,transport_status,activation_status
  ) VALUES (
    'FVI-CR-'||to_char(current_date,'YYYYMMDD')||'-'||upper(encode(extensions.gen_random_bytes(4),'hex')),
    source_tenant,direction_value,source_ref,source_tenant,source_env,target_ref,target_tenant,target_env,
    trim(_request->>'title'),trim(_request->>'reason'),requested_manifest,package_digest,
    configuration_digest,settings_digest,aggregate_digest,_actor_user_id,request_key,validations,
    'source_review','pending','not_applicable'
  ) RETURNING * INTO created;
  PERFORM public.append_environment_change_event(created.id,'request_created',_actor_user_id,
    jsonb_build_object('approval_stage','source_review','direction',direction_value,
      'source_project_ref',source_ref,'target_project_ref',target_ref,'manifest_hash',aggregate_digest));
  PERFORM public.append_environment_change_event(created.id,'preflight_recorded',_actor_user_id,
    jsonb_build_object('validation_results',validations));
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,source_tenant,'tenant','environment_change.source_requested',
    'environment_change_request',created.id::text,
    jsonb_build_object('direction',direction_value,'manifest_hash',aggregate_digest));
  RETURN QUERY SELECT created.id,created.change_request_uid,created.status,created.manifest_hash;
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_environment_change_unbound_for_api(_request jsonb, _requester_email text)
 RETURNS TABLE(request_id uuid, change_request_uid text, request_status text, manifest_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target_tenant uuid := nullif(_request->>'target_tenant_id','')::uuid;
  source_ref text := _request->>'source_project_ref';
  target_ref text := _request->>'target_project_ref';
  source_env text := _request->>'source_environment';
  target_env text := _request->>'target_environment';
  direction_value text := _request->>'direction';
  upstream_uid text := nullif(trim(_request->>'upstream_change_request_uid'),'');
  requested_manifest jsonb := _request->'manifest';
  validations jsonb := coalesce(_request->'validation_results','[]'::jsonb);
  mapping_preview jsonb := coalesce(_request->'access_mapping_preview','{}'::jsonb);
  mapped_requester_id uuid;
  mapped_requester_count integer;
  grant_item jsonb;
  matched_principal_id uuid;
  matched_principal_count integer;
  mapping_state text;
  computed_mappings jsonb := '[]'::jsonb;
  aggregate_digest text;
  created public.environment_change_requests%ROWTYPE;
BEGIN
  SELECT count(*),(array_agg(id ORDER BY id))[1] INTO mapped_requester_count,mapped_requester_id
  FROM auth.users WHERE lower(email)=lower(trim(_requester_email));
  IF mapped_requester_count<>1 THEN RAISE EXCEPTION 'Source requester does not map exactly once in target'; END IF;
  PERFORM public.assert_environment_change_actor(target_tenant,mapped_requester_id);
  PERFORM public.assert_environment_manifest_safe(requested_manifest);
  PERFORM public.assert_environment_payload_safe(validations);
  PERFORM public.assert_environment_payload_safe(mapping_preview);
  IF direction_value<>source_env||'_to_'||target_env THEN RAISE EXCEPTION 'Direction does not match source and target'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.environment_release_registry
    WHERE environment=target_env AND project_ref=target_ref AND enabled) THEN
    RAISE EXCEPTION 'Receiving environment is not registered and enabled';
  END IF;
  IF coalesce(_request->>'source_request_status','')<>'approved'
     OR upstream_uid IS NULL OR length(upstream_uid)>80 THEN
    RAISE EXCEPTION 'An approved source request is required';
  END IF;
  IF coalesce(_request->>'source_requester_email_hash','')=
     coalesce(_request->>'source_approver_email_hash','') THEN
    RAISE EXCEPTION 'Source maker/checker separation proof is invalid';
  END IF;
  IF jsonb_typeof(validations)<>'array' OR jsonb_array_length(validations)=0 THEN
    RAISE EXCEPTION 'Target preflight results are required';
  END IF;
  aggregate_digest := encode(extensions.digest(convert_to(requested_manifest::text,'UTF8'),'sha256'),'hex');
  IF aggregate_digest<>coalesce(_request->>'upstream_manifest_hash','') THEN
    RAISE EXCEPTION 'Transported manifest hash does not match source approval';
  END IF;
  IF jsonb_typeof(requested_manifest->'settings'->'access_grants')='array' THEN
    FOR grant_item IN SELECT value FROM jsonb_array_elements(requested_manifest->'settings'->'access_grants')
    LOOP
      matched_principal_id := NULL;
      matched_principal_count := 0;
      IF grant_item->>'principal_type'='group' THEN
        SELECT count(*),(array_agg(id ORDER BY id))[1] INTO matched_principal_count,matched_principal_id
        FROM public.tenant_groups
        WHERE tenant_id=target_tenant AND lower(name)=lower(grant_item->>'principal_name');
      ELSIF grant_item->>'principal_type'='user' THEN
        SELECT count(*),(array_agg(m.user_id ORDER BY m.user_id))[1] INTO matched_principal_count,matched_principal_id
        FROM public.tenant_members m JOIN auth.users u ON u.id=m.user_id
        WHERE m.tenant_id=target_tenant AND m.active
          AND lower(u.email)=lower(grant_item->>'principal_name');
      ELSE
        RAISE EXCEPTION 'Unsupported access principal type';
      END IF;
      mapping_state := CASE matched_principal_count WHEN 1 THEN 'exact'
        WHEN 0 THEN 'missing' ELSE 'ambiguous' END;
      computed_mappings := computed_mappings || jsonb_build_array(jsonb_build_object(
        'recon_source_id',grant_item->>'recon_source_id',
        'recon_name',grant_item->>'recon_name',
        'principal_type',grant_item->>'principal_type',
        'principal_name',grant_item->>'principal_name',
        'permission',grant_item->>'permission',
        'target_principal_id',matched_principal_id,
        'state',mapping_state
      ));
    END LOOP;
  END IF;
  mapping_preview := jsonb_build_object(
    'mappings',computed_mappings,
    'exact',(SELECT count(*) FROM jsonb_array_elements(computed_mappings) item WHERE item->>'state'='exact'),
    'missing',(SELECT count(*) FROM jsonb_array_elements(computed_mappings) item WHERE item->>'state'='missing'),
    'ambiguous',(SELECT count(*) FROM jsonb_array_elements(computed_mappings) item WHERE item->>'state'='ambiguous')
  );
  SELECT * INTO created FROM public.environment_change_requests
  WHERE approval_stage='target_review' AND upstream_change_request_uid=upstream_uid;
  IF FOUND THEN
    IF created.manifest_hash<>aggregate_digest THEN RAISE EXCEPTION 'Upstream request is bound to another manifest'; END IF;
    RETURN QUERY SELECT created.id,created.change_request_uid,created.status,created.manifest_hash;
    RETURN;
  END IF;
  INSERT INTO public.environment_change_requests(
    change_request_uid,control_tenant_id,direction,source_project_ref,source_tenant_id,
    source_environment,target_project_ref,target_tenant_id,target_environment,title,reason,
    manifest,package_hash,configuration_hash,settings_hash,manifest_hash,requested_by,
    idempotency_key,validation_results,approval_stage,upstream_change_request_uid,
    upstream_manifest_hash,transport_status,access_mapping_preview,activation_status
  ) VALUES (
    'FVI-CR-'||to_char(current_date,'YYYYMMDD')||'-'||upper(encode(extensions.gen_random_bytes(4),'hex')),
    target_tenant,direction_value,source_ref,nullif(_request->>'source_tenant_id','')::uuid,
    source_env,target_ref,target_tenant,target_env,trim(_request->>'title'),trim(_request->>'reason'),
    requested_manifest,
    encode(extensions.digest(convert_to((requested_manifest->'package')::text,'UTF8'),'sha256'),'hex'),
    encode(extensions.digest(convert_to((requested_manifest->'configuration')::text,'UTF8'),'sha256'),'hex'),
    encode(extensions.digest(convert_to((requested_manifest->'settings')::text,'UTF8'),'sha256'),'hex'),
    aggregate_digest,mapped_requester_id,'incoming:'||upstream_uid,validations,'target_review',
    upstream_uid,aggregate_digest,'not_required',mapping_preview,'pending_install'
  ) RETURNING * INTO created;
  PERFORM public.append_environment_change_event(created.id,'package_received',mapped_requester_id,
    jsonb_build_object('upstream_change_request_uid',upstream_uid,'manifest_hash',aggregate_digest,
      'source_maker_checker_separated',true));
  PERFORM public.append_environment_change_event(created.id,'preflight_recorded',mapped_requester_id,
    jsonb_build_object('validation_results',validations,'access_mapping_preview',mapping_preview));
  RETURN QUERY SELECT created.id,created.change_request_uid,created.status,created.manifest_hash;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_recon_run_uid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.run_uid IS NULL THEN
    NEW.run_uid := 'R-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(NEW.id::text, '-', ''), 1, 16));
  ELSE
    NEW.run_uid := upper(NEW.run_uid);
  END IF;
  IF NEW.run_uid !~ '^[A-Z0-9]+(-[A-Z0-9]+)*$' THEN
    RAISE EXCEPTION 'Run ID must use uppercase letters, numbers, and hyphen separators'
      USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.dpw_pipeline_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 DECLARE src public.data_prep_configuration_revisions%ROWTYPE; cid uuid; f record;
BEGIN
 IF TG_OP='INSERT' AND NEW.lifecycle_state='staging' AND NEW.parent_pipeline_id IS NOT NULL THEN
  SELECT c.* INTO src FROM public.data_prep_configuration_revisions c JOIN private.dpw_configuration_heads h ON h.configuration_id=c.id
  WHERE h.pipeline_id=NEW.parent_pipeline_id;
 ELSIF TG_OP='UPDATE' AND NEW.version IS DISTINCT FROM OLD.version AND NEW.promoted_from_id IS NOT NULL
 AND NEW.promoted_from_id IS DISTINCT FROM OLD.promoted_from_id THEN
  SELECT c.* INTO src FROM public.data_prep_configuration_revisions c JOIN private.dpw_configuration_heads h ON h.configuration_id=c.id
  WHERE h.pipeline_id=NEW.promoted_from_id;
  IF src.id IS NULL AND EXISTS(SELECT 1 FROM private.dpw_configuration_heads WHERE pipeline_id=NEW.id)
  THEN RAISE EXCEPTION 'dpw.promotion_profiles_missing'; END IF;
 END IF;
 IF src.id IS NOT NULL THEN
  INSERT INTO public.data_prep_configuration_revisions(tenant_id,pipeline_id,pipeline_version,request_key,created_by,payload,payload_sha256)
  VALUES(NEW.tenant_id,NEW.id,NEW.version,gen_random_uuid(),coalesce(NEW.promoted_by,NEW.created_by),
  src.payload||jsonb_build_object('source_data_source_id',NEW.source_data_source_id,'output_data_source_id',NEW.output_data_source_id),
  private.dpw_hash(src.payload||jsonb_build_object('source_data_source_id',NEW.source_data_source_id,'output_data_source_id',NEW.output_data_source_id))) RETURNING id INTO cid;
  INSERT INTO public.data_prep_input_profiles(configuration_id,tenant_id,pipeline_id,pipeline_version,feed_key,name,vendor,layout_id,business_side,record_type,data_source_id,required,allow_empty,mappings,steps)
  SELECT cid,NEW.tenant_id,NEW.id,NEW.version,feed_key,name,vendor,layout_id,business_side,record_type,data_source_id,required,allow_empty,mappings,steps
  FROM public.data_prep_input_profiles WHERE configuration_id=src.id;
  INSERT INTO private.dpw_configuration_heads VALUES(NEW.id,cid) ON CONFLICT(pipeline_id) DO UPDATE SET configuration_id=excluded.configuration_id;
 END IF;
 IF NEW.status='approved' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status OR OLD.version IS DISTINCT FROM NEW.version) THEN
  SELECT h.configuration_id INTO cid FROM private.dpw_configuration_heads h JOIN public.data_prep_configuration_revisions c ON c.id=h.configuration_id
  WHERE h.pipeline_id=NEW.id AND c.pipeline_version=NEW.version;
  IF cid IS NOT NULL THEN
   SELECT * INTO src FROM public.data_prep_configuration_revisions WHERE id=cid;
   IF src.payload->'steps' IS DISTINCT FROM NEW.steps OR src.payload->'dq_rules' IS DISTINCT FROM NEW.dq_rules
   OR src.payload->>'on_failure' IS DISTINCT FROM NEW.on_failure
   OR nullif(src.payload->>'output_data_source_id','')::uuid IS DISTINCT FROM NEW.output_data_source_id
   OR nullif(src.payload->>'source_data_source_id','')::uuid IS DISTINCT FROM NEW.source_data_source_id
   THEN RAISE EXCEPTION 'dpw.configuration_profile_snapshot_stale'; END IF;
   INSERT INTO public.data_prep_approved_configurations(tenant_id,pipeline_id,pipeline_version,configuration_id,snapshot,approved_by,approved_at)
   VALUES(NEW.tenant_id,NEW.id,NEW.version,cid,private.dpw_snapshot(NEW.id),NEW.approved_by,NEW.approved_at);
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.dpw_processor_actor(_tenant uuid, _pipeline uuid, _subject jsonb, _action text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role'
 OR _subject->>'role' IS DISTINCT FROM 'authenticated' OR _subject->>'sub' IS NULL OR _subject->>'exp' IS NULL
 OR to_timestamp((_subject->>'exp')::double precision)<=clock_timestamp()
 THEN RAISE EXCEPTION 'dpw.closed_processor_verified_subject_required' USING ERRCODE='42501'; END IF;
 actor:=(_subject->>'sub')::uuid;
 IF private.dpw_native_factor_attest(actor,_tenant,_subject->>'aal',to_timestamp((_subject->>'exp')::double precision)) IS DISTINCT FROM true
 OR private.dpw_workspace_feature_attest(actor,_tenant) IS DISTINCT FROM true
 OR private.data_prep_pipeline_scope_allows(actor,_tenant,_pipeline,_action) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dpw.processor_actor_denied' USING ERRCODE='42501'; END IF;
 PERFORM public.assert_data_prep_actor(_tenant,actor,false);
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.tenant_user_analytics(_tenant uuid, _window_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_is_platform boolean;
  v_is_tenant_admin boolean;
  v_window int := GREATEST(1, LEAST(_window_days, 365));
  v_cutoff timestamptz := now() - make_interval(days => v_window);
  v_total int; v_active int; v_inactive int; v_never int;
  v_mfa int; v_sso int;
  v_roles jsonb; v_groups jsonb; v_trend jsonb;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT public.is_platform_admin(v_caller) INTO v_is_platform;
  SELECT public.has_tenant_role(v_caller, _tenant, 'tenant_admin'::tenant_role) INTO v_is_tenant_admin;
  IF NOT (v_is_platform OR v_is_tenant_admin) THEN
    RAISE EXCEPTION 'Forbidden: tenant_admin or platform_admin required';
  END IF;

  WITH members AS (
    SELECT DISTINCT tm.user_id FROM public.tenant_members tm WHERE tm.tenant_id = _tenant
  ),
  users AS (
    SELECT u.id, u.last_sign_in_at FROM members m JOIN auth.users u ON u.id = m.user_id
  )
  SELECT
    COUNT(*)::int,
    COUNT(*) FILTER (WHERE last_sign_in_at >= v_cutoff)::int,
    COUNT(*) FILTER (WHERE last_sign_in_at IS NOT NULL AND last_sign_in_at < v_cutoff)::int,
    COUNT(*) FILTER (WHERE last_sign_in_at IS NULL)::int
  INTO v_total, v_active, v_inactive, v_never FROM users;

  SELECT COUNT(DISTINCT f.user_id)::int INTO v_mfa
  FROM auth.mfa_factors f
  WHERE f.status = 'verified'
    AND f.user_id IN (SELECT user_id FROM public.tenant_members WHERE tenant_id = _tenant);

  SELECT COUNT(DISTINCT i.user_id)::int INTO v_sso
  FROM auth.identities i
  WHERE i.provider <> 'email'
    AND i.user_id IN (SELECT user_id FROM public.tenant_members WHERE tenant_id = _tenant);

  SELECT COALESCE(jsonb_agg(jsonb_build_object('role', role, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
    INTO v_roles
  FROM (
    SELECT tm.role::text AS role, COUNT(DISTINCT tm.user_id)::int AS cnt
    FROM public.tenant_members tm WHERE tm.tenant_id = _tenant GROUP BY tm.role
  ) r;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('group_id', g.id, 'name', g.name, 'count', cnt) ORDER BY cnt DESC), '[]'::jsonb)
    INTO v_groups
  FROM public.tenant_groups g
  LEFT JOIN LATERAL (
    SELECT COUNT(DISTINCT gm.user_id)::int AS cnt
    FROM public.tenant_group_members gm WHERE gm.group_id = g.id
  ) c ON TRUE
  WHERE g.tenant_id = _tenant;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('day', day, 'signins', signins) ORDER BY day), '[]'::jsonb)
    INTO v_trend
  FROM (
    SELECT d::date AS day,
           (SELECT COUNT(*)::int FROM auth.users u
              JOIN public.tenant_members tm ON tm.user_id = u.id AND tm.tenant_id = _tenant
             WHERE u.last_sign_in_at::date = d::date) AS signins
    FROM generate_series(v_cutoff::date, now()::date, interval '1 day') d
  ) s;

  INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
  VALUES (v_caller, _tenant, 'tenant', 'analytics.users.viewed', 'tenant', _tenant::text,
          jsonb_build_object('window_days', v_window));

  RETURN jsonb_build_object(
    'tenant_id', _tenant,
    'window_days', v_window,
    'totals', jsonb_build_object(
      'total', v_total, 'active', v_active, 'inactive', v_inactive, 'never_signed_in', v_never,
      'mfa_enrolled', v_mfa, 'sso_users', v_sso
    ),
    'roles', v_roles, 'groups', v_groups, 'trend', v_trend, 'generated_at', now()
  );
END $function$

CREATE OR REPLACE FUNCTION public.approve_incoming_environment_change_as(_request_id uuid, _approve boolean, _comment text, _confirm_access_mapping boolean, _actor_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE target public.environment_change_requests%ROWTYPE; result text; prior_setting text;
BEGIN
  SELECT * INTO target FROM public.environment_change_requests WHERE id=_request_id FOR UPDATE;
  IF NOT FOUND OR target.approval_stage<>'target_review' THEN RAISE EXCEPTION 'Incoming target review is required'; END IF;
  IF _approve AND NOT _confirm_access_mapping THEN RAISE EXCEPTION 'Target approver must confirm user/group mappings'; END IF;
  result := public.decide_environment_change_as(_request_id,_approve,_comment,_actor_user_id);
  IF _approve THEN
    prior_setting := current_setting('app.environment_change_lifecycle',true);
    PERFORM set_config('app.environment_change_lifecycle','on',true);
    UPDATE public.environment_change_requests SET access_mapping_confirmed_by=_actor_user_id,
      access_mapping_confirmed_at=now() WHERE id=_request_id;
    PERFORM set_config('app.environment_change_lifecycle',coalesce(prior_setting,''),true);
    PERFORM public.append_environment_change_event(_request_id,'access_mapping_confirmed',_actor_user_id,
      jsonb_build_object('confirmed',true,'preview_hash',
        encode(extensions.digest(convert_to(target.access_mapping_preview::text,'UTF8'),'sha256'),'hex')));
  END IF;
  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_environment_change_transport_for_api(_request_id uuid, _succeeded boolean, _target_change_request_uid text, _actor_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE target public.environment_change_requests%ROWTYPE; prior_setting text;
BEGIN
  SELECT * INTO target FROM public.environment_change_requests WHERE id=_request_id FOR UPDATE;
  IF NOT FOUND OR target.approval_stage<>'source_review' OR target.status<>'approved' THEN
    RAISE EXCEPTION 'Approved source request is required';
  END IF;
  IF target.decided_by IS DISTINCT FROM _actor_user_id THEN RAISE EXCEPTION 'Only the source checker can record transport'; END IF;
  prior_setting := current_setting('app.environment_change_lifecycle',true);
  PERFORM set_config('app.environment_change_lifecycle','on',true);
  UPDATE public.environment_change_requests SET
    transport_status=CASE WHEN _succeeded THEN 'succeeded' ELSE 'failed' END,
    transport_attempted_at=now(),
    target_change_request_uid=CASE WHEN _succeeded THEN nullif(trim(_target_change_request_uid),'') ELSE NULL END
  WHERE id=_request_id;
  PERFORM set_config('app.environment_change_lifecycle',coalesce(prior_setting,''),true);
  PERFORM public.append_environment_change_event(_request_id,
    CASE WHEN _succeeded THEN 'package_transmitted' ELSE 'transport_failed' END,_actor_user_id,
    jsonb_build_object('target_change_request_uid',CASE WHEN _succeeded THEN nullif(trim(_target_change_request_uid),'') ELSE NULL END));
  RETURN CASE WHEN _succeeded THEN 'succeeded' ELSE 'failed' END;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_reference_version_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_mode text; v_action text;
BEGIN
  SELECT access_mode INTO v_mode FROM public.reference_data_tables
    WHERE id=NEW.table_id AND tenant_id=NEW.tenant_id;
  IF v_mode IS NULL THEN RAISE EXCEPTION 'reference_parent_missing' USING ERRCODE='23514'; END IF;
  IF v_mode='legacy_passthrough' THEN RETURN NEW; END IF;
  -- Service-role APIs cannot use an issuer-supplied actor to bypass the
  -- mapped resource boundary. They need the separate classified-principal
  -- cutover before mapped reference version writes are allowed.
  IF auth.uid() IS NULL OR auth.role()='service_role' THEN
    RAISE EXCEPTION 'reference_actor_required' USING ERRCODE='42501'; END IF;
  v_action := CASE WHEN TG_OP='INSERT' THEN 'ingest'
    WHEN OLD.status='pending_approval' AND NEW.status IN ('published','rejected') THEN 'approve'
    WHEN OLD.status='draft' AND NEW.status='pending_approval' THEN 'edit'
    ELSE 'edit' END;
  IF NOT public.reference_scope_allows(NEW.table_id,v_action) THEN
    RAISE EXCEPTION 'reference_scope_denied' USING ERRCODE='42501'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_environment_tenant_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE expected jsonb := NEW.manifest->'settings'->'tenant_identity'; actual jsonb;
BEGIN
  IF expected IS NULL OR jsonb_typeof(expected)<>'object' THEN
    RAISE EXCEPTION 'Environment package requires tenant identity proof';
  END IF;
  actual := public.environment_tenant_identity(NEW.control_tenant_id);
  IF actual IS NULL
     OR expected->>'release_identity_uid' IS DISTINCT FROM actual->>'release_identity_uid'
     OR expected->>'legal_identity_hash' IS DISTINCT FROM actual->>'legal_identity_hash'
     OR expected->>'verified_organization_domain' IS NULL
     OR expected->>'verified_organization_domain' IS DISTINCT FROM actual->>'verified_organization_domain'
     OR expected->>'domain_identity_hash' IS DISTINCT FROM actual->>'domain_identity_hash' THEN
    RAISE EXCEPTION 'Source and target tenants are not the same registered organization';
  END IF;
  IF NEW.approval_stage='source_review' AND NEW.source_tenant_id<>NEW.control_tenant_id THEN
    RAISE EXCEPTION 'Source review must be controlled by the source tenant';
  END IF;
  IF NEW.approval_stage='target_review' AND NEW.target_tenant_id<>NEW.control_tenant_id THEN
    RAISE EXCEPTION 'Target review must be controlled by the target tenant';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_data_resource_registry_root()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_root_tenant uuid; v_resource_uuid uuid;
BEGIN
  v_resource_uuid := CASE NEW.resource_type
    WHEN 'data_source' THEN NEW.data_source_id WHEN 'db_connection' THEN NEW.db_connection_id
    WHEN 'inline_api_source' THEN NEW.inline_api_source_id WHEN 'erp_connection' THEN NEW.erp_connection_id
    WHEN 'file_watcher' THEN NEW.file_watcher_id WHEN 'aidp_template' THEN NEW.aidp_template_id
    WHEN 'aidp_document' THEN NEW.aidp_document_id WHEN 'reference_table' THEN NEW.reference_table_id
    WHEN 'data_prep_pipeline' THEN NEW.data_prep_pipeline_id WHEN 'data_source_schedule' THEN NEW.data_source_schedule_id
    WHEN 'tenant_template' THEN NEW.tenant_template_id WHEN 'collateral_schedule' THEN NEW.collateral_schedule_id END;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fvi-resource:'||NEW.resource_type||':'||v_resource_uuid::text,0));
  CASE NEW.resource_type
    WHEN 'data_source' THEN SELECT tenant_id INTO v_root_tenant FROM public.workspace_data_sources WHERE id=NEW.data_source_id FOR SHARE;
    WHEN 'db_connection' THEN SELECT tenant_id INTO v_root_tenant FROM public.rekon_db_connections WHERE id=NEW.db_connection_id FOR SHARE;
    WHEN 'inline_api_source' THEN SELECT tenant_id INTO v_root_tenant FROM public.rekon_inline_api_sources WHERE id=NEW.inline_api_source_id FOR SHARE;
    WHEN 'erp_connection' THEN SELECT tenant_id INTO v_root_tenant FROM public.erp_connector_configs WHERE id=NEW.erp_connection_id FOR SHARE;
    WHEN 'file_watcher' THEN SELECT tenant_id INTO v_root_tenant FROM public.data_watchers WHERE id=NEW.file_watcher_id FOR SHARE;
    WHEN 'aidp_template' THEN SELECT tenant_id INTO v_root_tenant FROM public.aidp_templates WHERE id=NEW.aidp_template_id FOR SHARE;
    WHEN 'aidp_document' THEN SELECT tenant_id INTO v_root_tenant FROM public.aidp_documents WHERE id=NEW.aidp_document_id FOR SHARE;
    WHEN 'reference_table' THEN SELECT tenant_id INTO v_root_tenant FROM public.reference_data_tables WHERE id=NEW.reference_table_id FOR SHARE;
    WHEN 'data_prep_pipeline' THEN SELECT tenant_id INTO v_root_tenant FROM public.data_prep_pipelines WHERE id=NEW.data_prep_pipeline_id FOR SHARE;
    WHEN 'data_source_schedule' THEN
      SELECT s.tenant_id INTO v_root_tenant FROM public.data_source_schedules s
      JOIN public.workspace_data_sources d ON d.id=s.data_source_id AND d.tenant_id=s.tenant_id
      WHERE s.id=NEW.data_source_schedule_id FOR SHARE OF s,d;
    WHEN 'tenant_template' THEN SELECT tenant_id INTO v_root_tenant FROM public.tenant_templates WHERE id=NEW.tenant_template_id FOR SHARE;
    WHEN 'collateral_schedule' THEN SELECT tenant_id INTO v_root_tenant FROM public.collateral_schedules WHERE id=NEW.collateral_schedule_id FOR SHARE;
  END CASE;
  IF v_root_tenant IS NULL OR v_root_tenant<>NEW.tenant_id THEN RAISE EXCEPTION 'resource root must exist in the declared tenant'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.prevent_extended_registered_root_tenant_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_registered boolean;
BEGIN
  IF NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME='tenant_templates' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fvi-resource:tenant_template:'||OLD.id::text,0));
    SELECT EXISTS(SELECT 1 FROM public.data_resource_registry WHERE tenant_template_id=OLD.id) INTO v_registered;
  ELSIF TG_TABLE_NAME='collateral_schedules' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fvi-resource:collateral_schedule:'||OLD.id::text,0));
    SELECT EXISTS(SELECT 1 FROM public.data_resource_registry WHERE collateral_schedule_id=OLD.id) INTO v_registered;
  ELSE RAISE EXCEPTION 'unsupported typed root';
  END IF;
  IF v_registered THEN RAISE EXCEPTION 'tenant cannot change for a registered resource'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.record_environment_package_rejection_for_api(_target_tenant_id uuid, _actor_user_id uuid, _incident jsonb)
 RETURNS TABLE(security_event_id bigint, incident_id uuid, audit_id bigint, emails_queued integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  event_id bigint;
  rule_uid uuid;
  alert_uid uuid;
  audit_uid bigint;
  recipient record;
  queued integer := 0;
BEGIN
  PERFORM public.assert_environment_change_actor(_target_tenant_id,_actor_user_id);
  PERFORM public.assert_environment_payload_safe(coalesce(_incident,'{}'::jsonb));
  IF coalesce(_incident->>'reason_code','')<>'environment_package_tenant_mismatch'
     OR coalesce((_incident->>'package_rejected')::boolean,false) IS NOT TRUE THEN
    RAISE EXCEPTION 'Invalid environment package rejection incident';
  END IF;

  INSERT INTO public.security_events(tenant_id,user_id,event_type,severity,context)
  VALUES (_target_tenant_id,_actor_user_id,'environment_package_tenant_mismatch','critical',_incident)
  RETURNING id INTO event_id;

  INSERT INTO public.security_alert_rules(
    tenant_id,code,description,event_type_pattern,min_severity,window_minutes,
    threshold,cooldown_minutes,severity,notify_channels,enabled,created_by,updated_by
  ) VALUES (
    _target_tenant_id,'ENVIRONMENT_PACKAGE_TENANT_MISMATCH',
    'Reject and escalate a signed environment package addressed to another tenant.',
    'environment_package_tenant_mismatch','critical',60,1,1,'critical',
    '["in_app","email"]'::jsonb,true,_actor_user_id,_actor_user_id
  ) ON CONFLICT (coalesce(tenant_id,'00000000-0000-0000-0000-000000000000'::uuid),code)
    DO UPDATE SET enabled=true,updated_at=now(),updated_by=excluded.updated_by
  RETURNING id INTO rule_uid;

  INSERT INTO public.security_alert_incidents(
    rule_id,tenant_id,event_count,window_minutes,severity,sample_event_ids,context
  ) VALUES (
    rule_uid,_target_tenant_id,1,60,'critical',ARRAY[event_id],
    _incident||jsonb_build_object('rule_code','ENVIRONMENT_PACKAGE_TENANT_MISMATCH')
  ) RETURNING id INTO alert_uid;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (
    _actor_user_id,_target_tenant_id,'security','environment_change.cross_tenant_import_rejected',
    'environment_package',coalesce(_incident->>'source_request_uid','unknown'),
    _incident||jsonb_build_object('security_event_id',event_id,'incident_id',alert_uid)
  ) RETURNING id INTO audit_uid;

  FOR recipient IN
    SELECT DISTINCT candidates.email FROM (
      SELECT p.email
      FROM public.profiles p
      WHERE p.id=_actor_user_id AND p.email IS NOT NULL
      UNION
      SELECT p.email
      FROM public.tenant_members tm JOIN public.profiles p ON p.id=tm.user_id
      WHERE tm.tenant_id=_target_tenant_id AND tm.active
        AND tm.role='tenant_admin' AND p.email IS NOT NULL
    ) candidates
  LOOP
    PERFORM public.enqueue_email('transactional_emails',jsonb_build_object(
      'to',recipient.email,
      'subject','[FVI Security] Cross-tenant package import rejected',
      'template','environment_package_tenant_mismatch',
      'data',jsonb_build_object(
        'body','A signed package for another tenant or environment was rejected before installation.',
        'incident_id',alert_uid,
        'security_event_id',event_id,
        'source_request_uid',_incident->>'source_request_uid'
      )
    ));
    queued := queued+1;
  END LOOP;

  RETURN QUERY SELECT event_id,alert_uid,audit_uid,queued;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_github_sync_settings_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  -- Only service_role may UPDATE; authenticated users go through apply RPC.
  IF TG_OP = 'UPDATE' AND current_setting('role', true) <> 'service_role'
     AND (SELECT current_user) <> 'postgres' THEN
    -- allow when called by SECURITY DEFINER functions that elevate; check session_user
    IF session_user NOT IN ('postgres','supabase_admin','service_role') THEN
      RAISE EXCEPTION 'github_sync_settings can only be modified via apply_github_sync_change RPC';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_environment_change_for_api(_request jsonb, _requester_email text)
 RETURNS TABLE(request_id uuid, change_request_uid text, request_status text, manifest_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target_tenant uuid := nullif(_request->>'target_tenant_id','')::uuid;
  expected jsonb := _request->'manifest'->'settings'->'tenant_identity';
  actual jsonb;
BEGIN
  IF target_tenant IS NULL OR expected IS NULL OR jsonb_typeof(expected)<>'object' THEN
    RAISE EXCEPTION 'Environment package requires target tenant identity proof';
  END IF;
  actual := public.environment_tenant_identity(target_tenant);
  IF actual IS NULL
     OR expected->>'release_identity_uid' IS DISTINCT FROM actual->>'release_identity_uid'
     OR expected->>'legal_identity_hash' IS DISTINCT FROM actual->>'legal_identity_hash'
     OR expected->>'verified_organization_domain' IS NULL
     OR expected->>'verified_organization_domain' IS DISTINCT FROM actual->>'verified_organization_domain'
     OR expected->>'domain_identity_hash' IS DISTINCT FROM actual->>'domain_identity_hash' THEN
    RAISE EXCEPTION 'Source and target tenants are not the same registered organization';
  END IF;
  RETURN QUERY SELECT * FROM public.receive_environment_change_unbound_for_api(
    _request,_requester_email
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.dpw_start_preparation(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _file_ids uuid[], _request_key uuid, _mode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); b public.data_prep_delivery_batches%ROWTYPE;
 r public.data_prep_delivery_runs%ROWTYPE; snap jsonb; bindings jsonb; profile jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 b:=private.dpw_lock_batch(_tenant_id,_pipeline_id,_batch_id,actor,false);
 IF _mode IS NOT NULL AND _mode IS DISTINCT FROM b.mode THEN RAISE EXCEPTION 'dpw.delivery_mode_mismatch'; END IF;
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE batch_id=b.id AND request_key=_request_key;
 IF FOUND THEN
  IF r.started_by<>actor OR (SELECT array_agg(file_id ORDER BY file_id) FROM public.data_prep_run_inputs WHERE run_id=r.id)
  IS DISTINCT FROM (SELECT array_agg(DISTINCT x ORDER BY x) FROM unnest(_file_ids) x) THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
   RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'run',to_jsonb(r)-'result','snapshot',r.snapshot,'is_new',false)||private.dpw_run_readback_metadata(r.id,actor);
 END IF;
 IF b.state<>'collecting' OR _request_key IS NULL OR cardinality(_file_ids) IS NULL OR cardinality(_file_ids)=0
 OR cardinality(_file_ids)<>(SELECT count(DISTINCT x) FROM unnest(_file_ids) x)
 OR EXISTS(SELECT 1 FROM public.data_prep_delivery_files WHERE batch_id=b.id AND state<>'received')
 OR EXISTS(SELECT 1 FROM public.data_prep_delivery_files WHERE id=ANY(_file_ids) AND private.dpw_attachment_viewable(id) IS DISTINCT FROM true)
 OR (SELECT count(*) FROM public.data_prep_delivery_files WHERE id=ANY(_file_ids) AND batch_id=b.id AND state='received')<>cardinality(_file_ids)
 THEN RAISE EXCEPTION 'dpw.inputs_incomplete'; END IF;
 IF (SELECT sum((descriptor->>'row_count')::integer) FROM public.data_prep_delivery_files WHERE id=ANY(_file_ids))>50000
 THEN RAISE EXCEPTION 'dpw.delivery_row_limit_exceeded_no_truncation'; END IF;
 IF b.exclusion_approval_id IS NOT NULL AND (
 cardinality(_file_ids)<>(SELECT count(*) FROM public.data_prep_run_inputs WHERE run_id=(b.configuration_snapshot->>'exclusion_source_run_id')::uuid)
 OR EXISTS(SELECT 1 FROM public.data_prep_run_inputs oldinput
 WHERE oldinput.run_id=(b.configuration_snapshot->>'exclusion_source_run_id')::uuid AND NOT EXISTS(
 SELECT 1 FROM public.data_prep_delivery_files newfile JOIN public.workspace_data_source_uploads newupload ON newupload.id=newfile.upload_id
 WHERE newfile.id=ANY(_file_ids) AND newfile.correction_of=oldinput.file_id AND newfile.content_sha256=oldinput.content_sha256
 AND newupload.row_count=oldinput.row_count AND newfile.feed_key=oldinput.feed_key)))
 THEN RAISE EXCEPTION 'dpw.exclusion_requires_complete_original_file_delivery_rerun'; END IF;
 FOR profile IN SELECT value FROM jsonb_array_elements(b.configuration_snapshot->'feeds') LOOP
  IF private.dpw_source_allows(actor,_tenant_id,(profile->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'dpw.source_denied'; END IF;
  IF (profile->>'required')::boolean AND NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_files
  WHERE id=ANY(_file_ids) AND batch_id=b.id AND feed_key=profile->>'key' AND state='received') THEN RAISE EXCEPTION 'dpw.required_feed_missing'; END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('file_id',f.id,'upload_id',f.upload_id,'content_sha256',f.content_sha256,'original_path',f.original_path,'correction_of',f.correction_of,
 'feed_key',f.feed_key,'profile_version',f.pipeline_version,'data_source_id',f.data_source_id,
 'layout_id',(SELECT value->>'layout_id' FROM jsonb_array_elements(b.configuration_snapshot->'feeds') WHERE value->>'key'=f.feed_key),
 'business_date',b.business_date,'rows_count',u.row_count)) ORDER BY f.feed_key,f.id) INTO bindings
 FROM public.data_prep_delivery_files f JOIN public.workspace_data_source_uploads u ON u.id=f.upload_id
 WHERE f.id=ANY(_file_ids) AND f.batch_id=b.id AND f.state='received';
 snap:=b.configuration_snapshot||jsonb_build_object('batch_id',b.id,'business_date',b.business_date,'mode',b.mode,'files',bindings);
 IF b.correction_of IS NOT NULL THEN snap:=snap||jsonb_build_object('correction_of',b.correction_of); END IF;
 IF b.exclusion_approval_id IS NOT NULL THEN
  snap:=snap||jsonb_build_object('correction_source_files',(SELECT snapshot->'files' FROM public.data_prep_delivery_runs WHERE id=(b.configuration_snapshot->>'exclusion_source_run_id')::uuid));
 END IF;
 INSERT INTO public.data_prep_delivery_runs(tenant_id,pipeline_id,batch_id,pipeline_version,request_key,started_by,snapshot,snapshot_sha256)
 VALUES(_tenant_id,_pipeline_id,b.id,b.pipeline_version,_request_key,actor,snap,private.dpw_hash(snap)) RETURNING * INTO r;
 INSERT INTO public.data_prep_run_inputs(run_id,file_id,upload_id,tenant_id,feed_key,content_sha256,row_count)
 SELECT r.id,f.id,f.upload_id,_tenant_id,f.feed_key,f.content_sha256,u.row_count FROM public.data_prep_delivery_files f
 JOIN public.workspace_data_source_uploads u ON u.id=f.upload_id WHERE f.id=ANY(_file_ids);
 UPDATE public.data_prep_delivery_batches SET state='processing' WHERE id=b.id;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.preparation.start',r.id,jsonb_build_object('snapshot_sha256',r.snapshot_sha256,'batch_id',b.id));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'run',to_jsonb(r)-'result','snapshot',snap,'is_new',true)||private.dpw_run_readback_metadata(r.id,actor);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_authorize_file_intake(_tenant uuid, _pipeline uuid, _batch uuid, _feed_key text, _operation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant,_pipeline,'run'); b public.data_prep_delivery_batches%ROWTYPE; feed jsonb;
BEGIN
 IF _operation IS NULL OR _operation NOT IN('intake','original.read') THEN RAISE EXCEPTION 'dpw.invalid_intake_operation'; END IF;
 IF _operation='intake' AND public.user_has_permission(actor,_tenant,'data.upload',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.upload_permission_required'; END IF;
 IF _operation='intake' THEN PERFORM public.assert_data_prep_actor(_tenant,actor,false); END IF;
 SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=_batch AND tenant_id=_tenant AND pipeline_id=_pipeline;
 IF NOT FOUND THEN RAISE EXCEPTION 'dpw.batch_read_denied'; END IF;
 SELECT value INTO feed FROM jsonb_array_elements(b.configuration_snapshot->'feeds') WHERE value->>'key'=_feed_key;
 IF feed IS NULL OR private.dpw_source_allows(actor,_tenant,(feed->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
 OR (_operation='intake' AND private.dpw_source_allows(actor,_tenant,(feed->>'data_source_id')::uuid,'ingest') IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'dpw.file_source_denied'; END IF;
 RETURN jsonb_build_object('actor_id',actor,'auth_role',auth.role(),'tenant_id',_tenant,'pipeline_id',_pipeline,'batch_id',_batch,
 'feed_key',_feed_key,'data_source_id',(feed->>'data_source_id')::uuid,'pipeline_version',b.pipeline_version,'configuration_id',b.configuration_snapshot->'configuration_id',
 'storage_capability',jsonb_build_object('bucket_id','data-prep-inputs','public',false,'max_original_bytes',52428800,
 'max_expanded_bytes',52428800,'max_parsed_bytes',52428800,'max_rows',50000,'max_columns',500));
END $function$

CREATE OR REPLACE FUNCTION public.tg_signoff_status_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF current_setting('app.signoff_advance_ok', true) IS DISTINCT FROM 'on' THEN
      RAISE EXCEPTION 'eod_signoffs.status must be changed via advance_signoff() (got %->%)',
        OLD.status, NEW.status;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tdv_issue_token(_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE _plain text;
BEGIN
  IF NOT (public.has_tenant_role(auth.uid(), _tenant_id, 'tenant_admin')
       OR public.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  _plain := 'fvi_dv_' || encode(extensions.gen_random_bytes(24), 'hex');
  INSERT INTO public.tenant_domain_verification(tenant_id, token_hash, updated_at)
    VALUES (_tenant_id, sha256(convert_to(_plain,'UTF8')), now())
    ON CONFLICT (tenant_id) DO UPDATE
      SET token_hash = EXCLUDED.token_hash, updated_at = now();
  RETURN _plain;
END $function$

CREATE OR REPLACE FUNCTION public.exchange_mcp_oauth_code(_code_hash text, _client_id text, _redirect_uri text, _code_challenge text, _access_hash text, _access_prefix text, _refresh_hash text, _access_expires_at timestamp with time zone, _refresh_expires_at timestamp with time zone)
 RETURNS TABLE(access_token_id uuid, tenant_id uuid, user_id uuid, scopes text[], resource text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE c public.mcp_oauth_authorization_codes%ROWTYPE; new_api_id uuid;
BEGIN
  SELECT * INTO c FROM public.mcp_oauth_authorization_codes WHERE code_hash = _code_hash FOR UPDATE;
  IF NOT FOUND OR c.client_id <> _client_id OR c.redirect_uri <> _redirect_uri
     OR c.code_challenge <> _code_challenge OR c.consumed_at IS NOT NULL OR c.expires_at <= now() THEN
    RAISE EXCEPTION 'invalid_grant' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_members tm
    WHERE tm.tenant_id = c.tenant_id AND tm.user_id = c.user_id AND tm.active = true) THEN
    RAISE EXCEPTION 'invalid_grant' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.api_tokens(tenant_id,name,prefix,token_hash,scopes,expires_at,created_by)
  VALUES (c.tenant_id,'MCP OAuth '||left(c.client_id,24),_access_prefix,_access_hash,c.scopes,_access_expires_at,c.user_id)
  RETURNING id INTO new_api_id;
  INSERT INTO public.mcp_oauth_refresh_tokens(token_hash,api_token_id,client_id,tenant_id,user_id,scopes,resource,expires_at)
  VALUES (_refresh_hash,new_api_id,c.client_id,c.tenant_id,c.user_id,c.scopes,c.resource,_refresh_expires_at);
  UPDATE public.mcp_oauth_authorization_codes SET consumed_at = now() WHERE code_hash = c.code_hash;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (c.user_id,c.tenant_id,'tenant','mcp.oauth.token.issue','api_tokens',new_api_id,
    jsonb_build_object('client_id',c.client_id,'scopes',c.scopes));
  RETURN QUERY SELECT new_api_id,c.tenant_id,c.user_id,c.scopes,c.resource;
END;
$function$

CREATE OR REPLACE FUNCTION public.rotate_mcp_oauth_refresh_token(_refresh_hash text, _client_id text, _new_access_hash text, _new_access_prefix text, _new_refresh_hash text, _access_expires_at timestamp with time zone, _refresh_expires_at timestamp with time zone)
 RETURNS TABLE(access_token_id uuid, tenant_id uuid, user_id uuid, scopes text[], resource text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.mcp_oauth_refresh_tokens%ROWTYPE; new_api_id uuid;
BEGIN
  SELECT * INTO r FROM public.mcp_oauth_refresh_tokens WHERE token_hash = _refresh_hash FOR UPDATE;
  IF NOT FOUND OR r.client_id <> _client_id OR r.revoked_at IS NOT NULL
     OR r.rotated_at IS NOT NULL OR r.expires_at <= now() THEN
    RAISE EXCEPTION 'invalid_grant' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_members tm
    WHERE tm.tenant_id = r.tenant_id AND tm.user_id = r.user_id AND tm.active = true) THEN
    RAISE EXCEPTION 'invalid_grant' USING ERRCODE = '22023';
  END IF;
  UPDATE public.mcp_oauth_refresh_tokens SET rotated_at = now() WHERE token_hash = r.token_hash;
  UPDATE public.api_tokens SET revoked_at = now() WHERE id = r.api_token_id;
  INSERT INTO public.api_tokens(tenant_id,name,prefix,token_hash,scopes,expires_at,created_by)
  VALUES (r.tenant_id,'MCP OAuth '||left(r.client_id,24),_new_access_prefix,_new_access_hash,r.scopes,_access_expires_at,r.user_id)
  RETURNING id INTO new_api_id;
  INSERT INTO public.mcp_oauth_refresh_tokens(token_hash,api_token_id,client_id,tenant_id,user_id,scopes,resource,expires_at)
  VALUES (_new_refresh_hash,new_api_id,r.client_id,r.tenant_id,r.user_id,r.scopes,r.resource,_refresh_expires_at);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (r.user_id,r.tenant_id,'tenant','mcp.oauth.token.refresh','api_tokens',new_api_id,
    jsonb_build_object('client_id',r.client_id,'scopes',r.scopes,'prior_token_id',r.api_token_id));
  RETURN QUERY SELECT new_api_id,r.tenant_id,r.user_id,r.scopes,r.resource;
END;
$function$

CREATE OR REPLACE FUNCTION public.dpw_decide_exclusion(_tenant_id uuid, _pipeline_id uuid, _request_id uuid, _approve boolean, _comment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'manage'); e public.data_prep_exclusion_requests%ROWTYPE;
 d public.data_prep_exclusion_decisions%ROWTYPE; target_decision text:=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 SELECT * INTO e FROM public.data_prep_exclusion_requests WHERE id=_request_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id FOR UPDATE;
 IF public.user_has_permission(actor,_tenant_id,'data.prep.promote',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.independent_review_permission_required'; END IF;
 IF NOT FOUND OR _approve IS NULL OR length(coalesce(btrim(_comment),'')) NOT BETWEEN 3 AND 1000
 OR actor=e.requested_by OR EXISTS(SELECT 1 FROM public.data_prep_delivery_runs WHERE id=e.run_id AND started_by=actor)
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(e.entries) x JOIN public.data_prep_delivery_files f ON f.id=(x.value->>'file_id')::uuid WHERE f.created_by=actor)
 THEN RAISE EXCEPTION 'dpw.independent_human_exclusion_checker_required'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(e.entries) x JOIN public.data_prep_delivery_files f ON f.id=(x.value->>'file_id')::uuid
 WHERE private.dpw_source_allows(actor,_tenant_id,f.data_source_id,'view') IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'dpw.exclusion_source_denied'; END IF;
 SELECT * INTO d FROM public.data_prep_exclusion_decisions WHERE request_id=e.id;
 IF FOUND THEN
  IF d.decided_by<>actor OR d.decision<>target_decision OR d.comment<>btrim(_comment) THEN RAISE EXCEPTION 'dpw.immutable_exclusion_decision'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'decision',to_jsonb(d),'is_new',false);
 END IF;
 INSERT INTO public.data_prep_exclusion_decisions(request_id,decision,decided_by,comment) VALUES(e.id,target_decision,actor,btrim(_comment)) RETURNING * INTO d;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.exclusion.decide',d.id,jsonb_build_object('request_id',e.id,'decision',target_decision,'four_eyes',true,'complete_rerun_required',true));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'decision',to_jsonb(d),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_decide_release(_tenant_id uuid, _pipeline_id uuid, _request_id uuid, _approve boolean, _comment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'manage'); request public.data_prep_release_requests%ROWTYPE;
 decision public.data_prep_release_decisions%ROWTYPE; target text:=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 SELECT * INTO request FROM public.data_prep_release_requests WHERE id=_request_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id FOR UPDATE;
 IF public.user_has_permission(actor,_tenant_id,'data.prep.promote',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.independent_review_permission_required'; END IF;
 IF NOT FOUND OR _approve IS NULL OR length(coalesce(btrim(_comment),'')) NOT BETWEEN 3 AND 1000 OR request.requested_by=actor
 OR EXISTS(SELECT 1 FROM public.data_prep_delivery_runs WHERE id=request.run_id AND started_by=actor)
 OR EXISTS(SELECT 1 FROM public.data_prep_run_inputs i JOIN public.data_prep_delivery_files f ON f.id=i.file_id WHERE i.run_id=request.run_id AND f.created_by=actor)
 THEN RAISE EXCEPTION 'dpw.independent_human_release_checker_required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_runs WHERE id=request.run_id AND result_sha256=request.result_sha256
 AND pipeline_version=request.pipeline_version AND state IN('success','warn') AND (result->>'publication_eligible')::boolean IS TRUE)
 THEN RAISE EXCEPTION 'dpw.release_snapshot_stale'; END IF;
 SELECT * INTO decision FROM public.data_prep_release_decisions WHERE request_id=request.id;
 IF FOUND THEN
  IF decision.decided_by<>actor OR decision.decision<>target OR decision.comment<>btrim(_comment) THEN RAISE EXCEPTION 'dpw.immutable_release_decision'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'decision',to_jsonb(decision),'is_new',false);
 END IF;
 INSERT INTO public.data_prep_release_decisions(request_id,decision,decided_by,comment) VALUES(request.id,target,actor,btrim(_comment)) RETURNING * INTO decision;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.release.decide',decision.id,jsonb_build_object('request_id',request.id,'result_sha256',request.result_sha256,'decision',target,'four_eyes',true));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'decision',to_jsonb(decision),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_fail_preparation(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _run_id uuid, _request_key uuid, _verified_subject jsonb, _snapshot_sha256 text, _kind text, _error text, _phase text DEFAULT 'processing'::text, _interrupted boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_processor_actor(_tenant_id,_pipeline_id,_verified_subject,'run');
 b public.data_prep_delivery_batches%ROWTYPE; r public.data_prep_delivery_runs%ROWTYPE; failure jsonb; observed bigint;
BEGIN
 PERFORM 1 FROM public.data_prep_pipelines WHERE id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
 SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=_batch_id AND pipeline_id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run_id AND batch_id=_batch_id AND pipeline_id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR r.started_by<>actor OR r.request_key<>_request_key OR r.snapshot_sha256 IS DISTINCT FROM _snapshot_sha256
 OR _kind IS NULL OR _kind NOT IN('validation','transformation','precision','intake','processor') OR length(coalesce(_error,'')) NOT BETWEEN 1 AND 2000
 OR _phase IS NULL OR _phase NOT IN('processing','input_validation','transformation','data_quality','output_preparation') OR _interrupted IS NULL
 THEN RAISE EXCEPTION 'dpw.failure_binding_denied'; END IF;
 IF EXISTS(SELECT 1 FROM public.data_prep_run_inputs i JOIN public.data_prep_delivery_files f ON f.id=i.file_id WHERE i.run_id=r.id
 AND private.dpw_source_allows(actor,_tenant_id,f.data_source_id,'view') IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dpw.failure_source_revoked'; END IF;
 SELECT coalesce(sum(row_count),0) INTO observed FROM public.data_prep_run_inputs WHERE run_id=r.id;
 failure:=jsonb_build_object('status','failed','blocking_failure',true,'publication_eligible',false,'acceptedRows','[]'::jsonb,
 'outputLineage','[]'::jsonb,'dqResults',NULL,'dq_execution','unavailable_not_fabricated','error',jsonb_build_object('kind',_kind,'message',_error),
 'native_snapshot_sha256',r.snapshot_sha256,'phase',_phase,'interrupted',_interrupted,
 'rows_in_observed',observed,'input_processing_state','not_processed_or_interrupted','processed_row_count',NULL);
 IF r.finished_at IS NOT NULL THEN
  IF r.result IS DISTINCT FROM failure THEN RAISE EXCEPTION 'dpw.failure_history_immutable'; END IF;
  RETURN jsonb_build_object('tenant_id',_tenant_id,'processor_actor_id',actor,'transport_role','service_role','run',to_jsonb(r),'is_new',false);
 END IF;
 IF r.state<>'running' OR b.state<>'processing' THEN RAISE EXCEPTION 'dpw.failure_run_not_running'; END IF;
 UPDATE public.data_prep_delivery_runs SET state='failed',finished_at=now(),result=failure,result_sha256=private.dpw_hash(failure) WHERE id=r.id RETURNING * INTO r;
 UPDATE public.data_prep_delivery_batches SET state='failed' WHERE id=b.id;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.preparation.failure',r.id,jsonb_build_object('kind',_kind,'result_sha256',r.result_sha256,'snapshot_sha256',r.snapshot_sha256));
 RETURN jsonb_build_object('tenant_id',_tenant_id,'processor_actor_id',actor,'transport_role','service_role','run',to_jsonb(r),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_get_input_file(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _file_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); f public.data_prep_delivery_files%ROWTYPE; u public.workspace_data_source_uploads%ROWTYPE;
BEGIN
 SELECT * INTO f FROM public.data_prep_delivery_files WHERE id=_file_id AND batch_id=_batch_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id;
 IF NOT FOUND OR private.dpw_source_allows(actor,_tenant_id,f.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.input_read_denied'; END IF;
 IF private.dpw_attachment_viewable(f.id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.attachment_expired_or_purged_metadata_retained'; END IF;
 SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=f.upload_id AND tenant_id=_tenant_id AND data_source_id=f.data_source_id;
 IF f.state='received' AND (u.id IS NULL OR jsonb_typeof(u.rows) IS DISTINCT FROM 'array' OR u.row_count<>jsonb_array_length(u.rows)
 OR private.dpw_hash(u.rows) IS DISTINCT FROM f.structured_rows_sha256) THEN RAISE EXCEPTION 'dpw.immutable_input_rows_unavailable'; END IF;
 RETURN jsonb_build_object('actor_id',actor,'auth_role',auth.role(),'tenant_id',_tenant_id,'file',to_jsonb(f),
 'uploaded_by',f.created_by,'rows',u.rows,'rows_count',u.row_count,'columns',u.columns,'original_file_bytes_sha256',f.content_sha256,'structured_rows_sha256',f.structured_rows_sha256);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_get_preparation(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _run_id uuid, _page integer DEFAULT 1, _page_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'view'); r public.data_prep_delivery_runs%ROWTYPE;
 off integer:=private.dpw_page(_page,_page_size); payload_state jsonb;
BEGIN
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id AND batch_id=_batch_id;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.data_prep_run_inputs i JOIN public.data_prep_delivery_files f ON f.id=i.file_id WHERE i.run_id=r.id
 AND private.dpw_source_allows(actor,_tenant_id,f.data_source_id,'view') IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dpw.preparation_read_denied'; END IF;
 payload_state:=private.dpw_run_payload_state(r.id);
 IF (payload_state->>'available')::boolean IS DISTINCT FROM true THEN
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'run',to_jsonb(r)-'result','mode',r.snapshot->>'mode',
  'payload',payload_state,'rows',NULL,'lineage',NULL,'dq',NULL,'total',NULL,'page',_page,'page_size',_page_size)||private.dpw_run_readback_metadata(r.id,actor);
 END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'run',to_jsonb(r)-'result','mode',r.snapshot->>'mode',
 'rows',coalesce((SELECT jsonb_agg(x.value ORDER BY x.ord) FROM jsonb_array_elements(coalesce(r.result->'acceptedRows','[]'::jsonb)) WITH ORDINALITY x(value,ord)
 WHERE ord>off AND ord<=off+_page_size),'[]'::jsonb),'total',jsonb_array_length(coalesce(r.result->'acceptedRows','[]'::jsonb)),
 'lineage',coalesce((SELECT jsonb_agg(x.value ORDER BY x.ord) FROM jsonb_array_elements(coalesce(r.result->'outputLineage','[]'::jsonb)) WITH ORDINALITY x(value,ord)
 WHERE ord>off AND ord<=off+_page_size),'[]'::jsonb),'dq',r.result->'dqResults','counts_per_feed',r.result->'countsPerFeed',
 'payload',payload_state,'structured_data_sha256',r.result->>'structured_data_sha256','structured_lineage_sha256',r.result->>'structured_lineage_sha256','page',_page,'page_size',_page_size)||private.dpw_run_readback_metadata(r.id,actor);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_request_exclusion(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _run_id uuid, _entries jsonb, _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); r public.data_prep_delivery_runs%ROWTYPE;
 e public.data_prep_exclusion_requests%ROWTYPE; item jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id AND batch_id=_batch_id FOR SHARE;
 IF NOT FOUND OR r.finished_at IS NULL OR _request_key IS NULL OR length(coalesce(btrim(_reason),'')) NOT BETWEEN 3 AND 1000
 OR jsonb_typeof(_entries) IS DISTINCT FROM 'array' OR jsonb_array_length(_entries) NOT BETWEEN 1 AND 50000
 OR (SELECT count(DISTINCT (value->>'file_id',value->>'record_index')) FROM jsonb_array_elements(_entries))<>jsonb_array_length(_entries)
 THEN RAISE EXCEPTION 'dpw.invalid_exclusion_request'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||actor::text||_request_key::text,41));
 SELECT * INTO e FROM public.data_prep_exclusion_requests WHERE tenant_id=_tenant_id AND requested_by=actor AND request_key=_request_key;
 IF FOUND THEN
  IF e.run_id<>r.id OR e.entries IS DISTINCT FROM _entries OR e.reason<>btrim(_reason) THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'exclusion_request',to_jsonb(e),'is_new',false);
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(_entries) LOOP
  IF NOT EXISTS(SELECT 1 FROM public.data_prep_run_inputs i JOIN public.data_prep_delivery_files f ON f.id=i.file_id
  WHERE i.run_id=r.id AND i.file_id=(item->>'file_id')::uuid AND i.content_sha256=item->>'content_sha256'
  AND (item->>'record_index')::integer BETWEEN 0 AND i.row_count-1
  AND private.dpw_source_allows(actor,_tenant_id,f.data_source_id,'view') IS TRUE)
  THEN RAISE EXCEPTION 'dpw.exclusion_original_binding_mismatch'; END IF;
 END LOOP;
 INSERT INTO public.data_prep_exclusion_requests(tenant_id,pipeline_id,pipeline_version,batch_id,run_id,entries,reason,request_key,requested_by)
 VALUES(_tenant_id,_pipeline_id,r.pipeline_version,_batch_id,r.id,_entries,btrim(_reason),_request_key,actor) RETURNING * INTO e;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.exclusion.request',e.id,jsonb_build_object('run_id',r.id,'entries',_entries,'reason',btrim(_reason)));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'exclusion_request',to_jsonb(e),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_request_release(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _run_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); r public.data_prep_delivery_runs%ROWTYPE;
 b public.data_prep_delivery_batches%ROWTYPE; approval public.data_prep_release_requests%ROWTYPE;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 b:=private.dpw_lock_batch(_tenant_id,_pipeline_id,_batch_id,actor,false);
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run_id AND batch_id=b.id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND OR _request_key IS NULL OR b.mode<>'prepare' OR b.state<>'prepared' OR r.state NOT IN('success','warn')
 OR r.finished_at IS NULL OR (r.result->>'publication_eligible')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.release_success_required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||actor::text||_request_key::text,51));
 SELECT * INTO approval FROM public.data_prep_release_requests WHERE tenant_id=_tenant_id AND requested_by=actor AND request_key=_request_key;
 IF FOUND THEN
  IF approval.run_id<>r.id OR approval.result_sha256<>r.result_sha256 THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'release_request',to_jsonb(approval),'is_new',false);
 END IF;
 INSERT INTO public.data_prep_release_requests(tenant_id,pipeline_id,batch_id,run_id,pipeline_version,result_sha256,request_key,requested_by)
 VALUES(_tenant_id,_pipeline_id,b.id,r.id,r.pipeline_version,r.result_sha256,_request_key,actor) RETURNING * INTO approval;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.release.request',approval.id,jsonb_build_object('run_id',r.id,'result_sha256',r.result_sha256));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'release_request',to_jsonb(approval),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_save_configuration(_tenant_id uuid, _pipeline_id uuid, _payload jsonb, _owning_business_unit_ids uuid[], _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant_id); p public.data_prep_pipelines%ROWTYPE; oldcfg public.data_prep_configuration_revisions%ROWTYPE;
 cid uuid; rid uuid; f jsonb; src uuid; outsrc uuid; native jsonb; identity jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 IF _request_key IS NULL OR _payload IS NULL OR jsonb_typeof(_payload)<>'object' OR length(coalesce(_payload->>'name','')) NOT BETWEEN 1 AND 120
 OR jsonb_typeof(_payload->'feeds') IS DISTINCT FROM 'array' OR jsonb_array_length(_payload->'feeds') NOT BETWEEN 1 AND 50
 OR jsonb_typeof(_payload->'steps') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'dq_rules') IS DISTINCT FROM 'array'
 OR jsonb_typeof(_payload->'business_fields') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'required_fields') IS DISTINCT FROM 'array'
 OR _payload->>'on_failure' IS DISTINCT FROM 'block'
 OR jsonb_typeof(_payload->'policy'->'allow_warn') IS DISTINCT FROM 'boolean'
 OR jsonb_typeof(_payload->'policy'->'allow_drop_rows') IS DISTINCT FROM 'boolean'
 OR cardinality(_owning_business_unit_ids) IS NULL OR cardinality(_owning_business_unit_ids)=0
 THEN RAISE EXCEPTION 'dpw.invalid_configuration'; END IF;
 IF public.user_has_permission(actor,_tenant_id,'data.prep.author',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.configuration_author_permission_required'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(_payload->'business_fields') WHERE value ~ '^extras_json($|[.\[])')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_payload->'feeds') feed,jsonb_each_text(feed->'mappings') mapping
 WHERE mapping.value ~ '^extras_json($|[.\[])')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements((_payload->'steps')||(_payload->'dq_rules')) item WHERE item->>'field' ~ '^extras_json($|[.\[])')
 THEN RAISE EXCEPTION 'dpw.reserved_extras_namespace'; END IF;
 identity:=jsonb_build_object('payload',_payload,'pipeline_id',_pipeline_id,'owners',to_jsonb(_owning_business_unit_ids));
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||actor::text||_request_key::text,0));
 SELECT * INTO oldcfg FROM public.data_prep_configuration_revisions WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF FOUND THEN
  PERFORM private.dpw_authorize(_tenant_id,oldcfg.pipeline_id,'edit');
  IF oldcfg.payload->'_save_identity' IS DISTINCT FROM identity THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  SELECT * INTO p FROM public.data_prep_pipelines WHERE id=oldcfg.pipeline_id;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'pipeline',to_jsonb(p),'configuration_id',oldcfg.id,'is_new',false);
 END IF;
 IF _pipeline_id IS NOT NULL THEN
  SELECT * INTO p FROM public.data_prep_pipelines WHERE id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'dpw.pipeline_not_found'; END IF;
  IF p.created_by=actor AND NOT EXISTS(SELECT 1 FROM public.data_resource_registry WHERE tenant_id=_tenant_id AND data_prep_pipeline_id=p.id) THEN
   PERFORM public.register_typed_data_resource('data_prep_pipeline',p.id,_owning_business_unit_ids,'Reusable Data Prep staging ownership');
  END IF;
  PERFORM private.dpw_authorize(_tenant_id,_pipeline_id,'edit');
  IF p.status IS DISTINCT FROM 'draft' OR p.lifecycle_state='archived' OR p.promotion_status='pending' THEN RAISE EXCEPTION 'dpw.draft_required'; END IF;
 END IF;
 IF (SELECT count(DISTINCT value->>'key') FROM jsonb_array_elements(_payload->'feeds')) <> jsonb_array_length(_payload->'feeds')
 THEN RAISE EXCEPTION 'dpw.duplicate_feed_key'; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(_payload->'feeds') LOOP
  src:=(f->>'data_source_id')::uuid;
  IF private.dpw_source_allows(actor,_tenant_id,src,'view') IS DISTINCT FROM true
  OR private.dpw_source_allows(actor,_tenant_id,src,'ingest') IS DISTINCT FROM true
  OR jsonb_typeof(f->'mappings') IS DISTINCT FROM 'object' OR jsonb_typeof(f->'steps') IS DISTINCT FROM 'array'
  OR jsonb_typeof(f->'required') IS DISTINCT FROM 'boolean' OR jsonb_typeof(f->'allow_empty') IS DISTINCT FROM 'boolean'
  OR length(coalesce(f->>'key','')) NOT BETWEEN 1 AND 120 OR f->>'key' LIKE 'legacy:%'
  OR coalesce(f->>'layout_id','')='' OR coalesce(f->>'business_side','')='' OR coalesce(f->>'record_type','')=''
  THEN RAISE EXCEPTION 'dpw.feed_source_denied'; END IF;
 END LOOP;
 outsrc:=nullif(_payload->>'output_data_source_id','')::uuid;
 IF outsrc IS NULL THEN
  outsrc:=gen_random_uuid();
  INSERT INTO public.workspace_data_sources(id,tenant_id,name,source_type,created_by)
  VALUES(outsrc,_tenant_id,left(_payload->>'name',70)||' prepared '||outsrc::text,'json',actor);
  PERFORM public.register_typed_data_resource('data_source',outsrc,_owning_business_unit_ids,'Reusable Data Prep output ownership');
 ELSIF private.dpw_source_allows(actor,_tenant_id,outsrc,'ingest') IS DISTINCT FROM true
 OR private.dpw_source_allows(actor,_tenant_id,outsrc,'edit') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dpw.output_source_denied'; END IF;
 native:=_payload||jsonb_build_object('source_data_source_id',(_payload->'feeds'->0->>'data_source_id')::uuid,'output_data_source_id',outsrc);
 SELECT x.pipeline_id INTO rid FROM public.upsert_data_prep_pipeline(_tenant_id,_pipeline_id,native) x;
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=rid AND tenant_id=_tenant_id FOR UPDATE;
 SELECT id INTO cid FROM public.data_resource_registry WHERE tenant_id=_tenant_id AND data_prep_pipeline_id=rid;
 IF cid IS NULL THEN PERFORM public.register_typed_data_resource('data_prep_pipeline',rid,_owning_business_unit_ids,'Reusable Data Prep pipeline ownership');
 ELSE PERFORM public.set_typed_data_resource_owners(cid,_owning_business_unit_ids,'Reusable Data Prep configuration ownership'); END IF;
 native:=native||jsonb_build_object('_save_identity',identity);
 INSERT INTO public.data_prep_configuration_revisions(tenant_id,pipeline_id,pipeline_version,request_key,created_by,payload,payload_sha256)
 VALUES(_tenant_id,rid,p.version,_request_key,actor,native,private.dpw_hash(native)) RETURNING id INTO cid;
 FOR f IN SELECT value FROM jsonb_array_elements(_payload->'feeds') LOOP
  INSERT INTO public.data_prep_input_profiles(configuration_id,tenant_id,pipeline_id,pipeline_version,feed_key,name,vendor,layout_id,business_side,record_type,data_source_id,required,allow_empty,mappings,steps)
  VALUES(cid,_tenant_id,rid,p.version,f->>'key',f->>'name',f->>'vendor',f->>'layout_id',f->>'business_side',f->>'record_type',
  (f->>'data_source_id')::uuid,(f->>'required')::boolean,(f->>'allow_empty')::boolean,f->'mappings',f->'steps');
 END LOOP;
 INSERT INTO private.dpw_configuration_heads VALUES(rid,cid) ON CONFLICT(pipeline_id) DO UPDATE SET configuration_id=excluded.configuration_id;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.configuration.save',rid,jsonb_build_object('configuration_id',cid,'version',p.version));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'pipeline',to_jsonb(p),'configuration_id',cid,'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.tenants_check_reserved_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.reserved_slugs WHERE slug = lower(NEW.slug)) THEN
    RAISE EXCEPTION 'Slug "%" is reserved and cannot be used as a tenant slug', NEW.slug
      USING ERRCODE = '23514';
  END IF;
  IF lower(NEW.slug) !~ '^[a-z0-9](?:[a-z0-9-]{1,61}[a-z0-9])?$' THEN
    RAISE EXCEPTION 'Invalid slug: must be 2-63 chars, lowercase letters/digits/hyphens, no leading/trailing hyphen'
      USING ERRCODE = '23514';
  END IF;
  IF lower(NEW.slug) LIKE '%-dev' OR lower(NEW.slug) LIKE '%-sandbox'
     OR lower(NEW.slug) LIKE '%-uat' OR lower(NEW.slug) LIKE '%-staging' THEN
    RAISE EXCEPTION 'Slug cannot end with environment suffix (-dev/-sandbox/-uat/-staging)'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.assign_reconciliation_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  department_code text;
  process_code text;
  sequence_value bigint;
BEGIN
  IF NEW.recon_code IS NOT NULL THEN
    IF coalesce(auth.role(), current_user) NOT IN ('service_role', 'postgres') THEN
      RAISE EXCEPTION 'reconciliation identifier is system managed';
    END IF;
    RETURN NEW;
  END IF;

  SELECT CASE
    WHEN length(upper(regexp_replace(coalesce(nullif(bu.code, ''), 'GEN'), '[^A-Za-z0-9]', '', 'g'))) >= 2
      THEN left(upper(regexp_replace(coalesce(nullif(bu.code, ''), 'GEN'), '[^A-Za-z0-9]', '', 'g')), 12)
    ELSE 'GEN'
  END
  INTO department_code
  FROM (SELECT NEW.bu_id AS id) requested
  LEFT JOIN public.business_units bu
    ON bu.id = requested.id AND bu.tenant_id = NEW.tenant_id;

  department_code := coalesce(department_code, 'GEN');
  process_code := CASE NEW.recon_type
    WHEN 'one_sided' THEN '1WAY'
    WHEN 'two_sided' THEN '2WAY'
    WHEN 'three_sided' THEN '3WAY'
    ELSE '1WAY'
  END;

  PERFORM pg_advisory_xact_lock(
    hashtextextended(NEW.tenant_id::text || ':' || department_code || ':' || process_code, 0)
  );

  SELECT coalesce(max(split_part(recon_code, '-', 4)::bigint), 0) + 1
  INTO sequence_value
  FROM public.recon_definitions
  WHERE tenant_id = NEW.tenant_id
    AND recon_code LIKE 'FVI-' || department_code || '-' || process_code || '-%';

  NEW.recon_code := format(
    'FVI-%s-%s-%s', department_code, process_code, lpad(sequence_value::text, 6, '0')
  );
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prevent_reconciliation_identity_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.recon_code IS DISTINCT FROM OLD.recon_code THEN
    RAISE EXCEPTION 'reconciliation identifier is immutable';
  END IF;
  IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN
    RAISE EXCEPTION 'reconciliation tenant is immutable';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.advance_signoff(_signoff_id uuid, _to_status text, _comment text DEFAULT NULL::text, _evidence_hash text DEFAULT NULL::text)
 RETURNS eod_signoffs
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_row public.eod_signoffs%ROWTYPE;
  v_prior_status text;
  v_is_admin boolean := false;
  v_uid uuid := auth.uid();
  v_allowed boolean := false;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_row FROM public.eod_signoffs WHERE id = _signoff_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sign-off % not found', _signoff_id;
  END IF;
  v_prior_status := v_row.status;

  IF NOT EXISTS (SELECT 1 FROM public.tenant_members tm
                 WHERE tm.tenant_id = v_row.tenant_id AND tm.user_id = v_uid) THEN
    RAISE EXCEPTION 'Forbidden: not a tenant member';
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.tenant_members tm
                 WHERE tm.tenant_id = v_row.tenant_id
                   AND tm.user_id = v_uid
                   AND tm.role = 'tenant_admin') INTO v_is_admin;

  IF v_row.locked AND _to_status <> 'reopened' THEN
    RAISE EXCEPTION 'Sign-off is locked; only a reopen is permitted';
  END IF;

  IF v_row.status = 'draft' AND _to_status = 'prepared' THEN
    v_allowed := true;
    v_row.prepared_by := v_uid;
    v_row.prepared_at := now();
  ELSIF v_row.status = 'prepared' AND _to_status = 'reviewed' THEN
    IF v_row.prepared_by = v_uid THEN
      RAISE EXCEPTION 'Separation of duties: preparer cannot review';
    END IF;
    v_allowed := true;
    v_row.reviewed_by := v_uid;
    v_row.reviewed_at := now();
  ELSIF v_row.status = 'reviewed' AND _to_status = 'certified' THEN
    IF NOT v_is_admin THEN
      RAISE EXCEPTION 'Only tenant admins may certify';
    END IF;
    IF v_row.prepared_by = v_uid OR v_row.reviewed_by = v_uid THEN
      RAISE EXCEPTION 'Separation of duties: certifier must differ from preparer and reviewer';
    END IF;
    v_allowed := true;
    v_row.approved_by := v_uid;
    v_row.approved_at := now();
    v_row.certified_at := now();
    v_row.certified_hash := COALESCE(_evidence_hash, encode(digest(v_row.id::text || now()::text, 'sha256'), 'hex'));
    v_row.locked := true;
  ELSIF _to_status = 'rejected' AND v_row.status IN ('prepared','reviewed') THEN
    v_allowed := true;
    v_row.rejection_reason := _comment;
  ELSIF _to_status = 'reopened' AND v_row.status IN ('certified','rejected') THEN
    IF NOT v_is_admin THEN
      RAISE EXCEPTION 'Only tenant admins may reopen a sign-off';
    END IF;
    v_allowed := true;
    v_row.locked := false;
    v_row.reopened_count := COALESCE(v_row.reopened_count, 0) + 1;
    v_row.certified_at := NULL;
    v_row.certified_hash := NULL;
  END IF;

  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Illegal transition: % -> %', v_row.status, _to_status;
  END IF;

  PERFORM set_config('app.signoff_advance_ok', 'on', true);

  UPDATE public.eod_signoffs SET
    status            = _to_status,
    prepared_by       = v_row.prepared_by,
    prepared_at       = v_row.prepared_at,
    reviewed_by       = v_row.reviewed_by,
    reviewed_at       = v_row.reviewed_at,
    approved_by       = v_row.approved_by,
    approved_at       = v_row.approved_at,
    certified_at      = v_row.certified_at,
    certified_hash    = v_row.certified_hash,
    rejection_reason  = v_row.rejection_reason,
    reopened_count    = v_row.reopened_count,
    locked            = v_row.locked,
    version           = v_row.version + 1,
    updated_at        = now()
  WHERE id = _signoff_id
  RETURNING * INTO v_row;

  PERFORM set_config('app.signoff_advance_ok', 'off', true);

  INSERT INTO public.signoff_transitions
    (tenant_id, signoff_id, from_status, to_status, actor, comment, evidence_hash)
  VALUES
    (v_row.tenant_id, _signoff_id, v_prior_status, _to_status, v_uid, _comment, _evidence_hash);

  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_reconciled_environment_transport()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF OLD.transport_status='succeeded' AND EXISTS (
    SELECT 1 FROM public.environment_change_events e
    WHERE e.request_id=OLD.id AND e.event_type='transport_reconciled'
  ) THEN
    RAISE EXCEPTION 'Corrected environment transport is immutable';
  END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION public.mkt_chat_kpis()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  pii_reader boolean := public.has_mkt_pii_read_access();
  sessions_count bigint;
  escalated_count bigint;
  rated_count bigint;
  average_csat numeric;
  messages_count bigint;
  usage_count bigint;
  total_cost numeric;
  total_tokens bigint;
BEGIN
  IF auth.uid() IS NULL OR NOT (
    public.has_mkt_role(auth.uid(), 'super_admin'::public.mkt_admin_role)
    OR public.has_mkt_role(auth.uid(), 'sales_admin'::public.mkt_admin_role)
    OR public.has_mkt_role(auth.uid(), 'marketing_admin'::public.mkt_admin_role)
    OR public.has_mkt_role(auth.uid(), 'ai_admin'::public.mkt_admin_role)
  ) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT count(*), count(*) FILTER (WHERE escalated_to IS NOT NULL),
         count(*) FILTER (WHERE satisfaction IS NOT NULL), avg(satisfaction)
  INTO sessions_count, escalated_count, rated_count, average_csat
  FROM public.mkt_chat_sessions;

  SELECT count(*) INTO messages_count FROM public.mkt_chat_messages;
  SELECT count(*), coalesce(sum(cost_usd), 0), coalesce(sum(tokens_in + tokens_out), 0)
  INTO usage_count, total_cost, total_tokens
  FROM public.mkt_llm_usage;

  RETURN jsonb_build_object(
    'restricted', NOT pii_reader,
    'totalSessions', CASE WHEN pii_reader OR sessions_count >= 5 THEN sessions_count ELSE NULL END,
    'escalated', CASE WHEN pii_reader OR escalated_count >= 5 THEN escalated_count ELSE NULL END,
    'escalationRate', CASE
      WHEN pii_reader THEN CASE WHEN sessions_count = 0 THEN 0 ELSE escalated_count::numeric / sessions_count END
      WHEN sessions_count >= 10 AND escalated_count >= 5 AND sessions_count - escalated_count >= 5
        THEN escalated_count::numeric / sessions_count
      ELSE NULL
    END,
    'csat', CASE WHEN pii_reader OR rated_count >= 5 THEN average_csat ELSE NULL END,
    'totalCost', CASE WHEN pii_reader OR usage_count >= 5 THEN total_cost ELSE NULL END,
    'totalTokens', CASE WHEN pii_reader OR usage_count >= 5 THEN total_tokens ELSE NULL END,
    'totalMessages', CASE WHEN pii_reader OR messages_count >= 5 THEN messages_count ELSE NULL END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.review_proposed_matches_atomic(_tenant_id uuid, _match_ids uuid[], _decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE item_id uuid; processed integer := 0;
BEGIN
  FOREACH item_id IN ARRAY _match_ids LOOP
    PERFORM public.review_proposed_match_atomic(_tenant_id,item_id,_decision,NULL);
    processed := processed + 1;
  END LOOP;
  RETURN jsonb_build_object('ok',true,'count',processed);
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_status_subscribers_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_allowed boolean; v_count int; v_retry int;
BEGIN
  -- Email format validation (RFC 5322 simplified)
  IF NEW.email IS NULL OR NEW.email !~* '^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$' THEN
    RAISE EXCEPTION 'Invalid email address format' USING ERRCODE = '22023';
  END IF;
  IF length(NEW.email) > 254 THEN
    RAISE EXCEPTION 'Email too long' USING ERRCODE = '22023';
  END IF;

  -- Per-email rate limit: max 5 sign-up attempts per hour
  SELECT allowed, current_count, retry_after_seconds
    INTO v_allowed, v_count, v_retry
  FROM public.rate_limit_hit('status_sub:' || lower(NEW.email), 3600, 5);
  IF NOT v_allowed THEN
    RAISE EXCEPTION 'Too many subscription attempts for this email, please try again later'
      USING ERRCODE = '53400';
  END IF;

  NEW.email := lower(NEW.email);
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.set_environment_change_cutover_pause(_paused boolean, _reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_previous boolean;
BEGIN
  IF _paused IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 10 AND 500 THEN
    RAISE EXCEPTION 'A release reason is required' USING ERRCODE='22023';
  END IF;
  SELECT gate.paused INTO v_previous
  FROM public.environment_change_cutover_gate gate WHERE gate.singleton=true FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Environment change cutover gate is unavailable' USING ERRCODE='55000'; END IF;
  IF v_previous IS DISTINCT FROM _paused THEN
    UPDATE public.environment_change_cutover_gate
    SET paused=_paused,reason=btrim(_reason),changed_at=now()
    WHERE singleton=true;
    INSERT INTO public.audit_log(scope,action,resource_type,resource_id,context)
    VALUES ('system','system.environment_change_pause_changed','environment_change_cutover_gate','global',
      jsonb_build_object('previous_paused',v_previous,'new_paused',_paused,
        'reason',btrim(_reason),'executor','governed Management SQL'));
  END IF;
  RETURN _paused;
END
$function$

CREATE OR REPLACE FUNCTION private.ai_provider_nonsecret_custom_headers(_headers jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE item record; value_text text;
BEGIN
  IF jsonb_typeof(_headers) <> 'object' THEN RETURN false; END IF;
  FOR item IN SELECT key,value FROM jsonb_each(_headers) LOOP
    IF lower(item.key) NOT IN (
      'anthropic-version','muse-organization','muse-project',
      'x-api-version','x-region','x-request-id','x-client-id'
    ) OR jsonb_typeof(item.value) <> 'string' THEN RETURN false; END IF;
    value_text := item.value #>> '{}';
    IF length(value_text) > 200 OR value_text ~ '[[:cntrl:]]'
       OR value_text ~* '(^|[^a-z0-9])(bearer[[:space:]]+|basic[[:space:]]+|sb_secret_|sk-[a-z0-9])'
    THEN RETURN false; END IF;
  END LOOP;
  RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.pick_next_assignee(_rule_id uuid, _severity text DEFAULT NULL::text, _tags text[] DEFAULT NULL::text[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  rule_row public.exception_assignment_rules%ROWTYPE;
  candidate uuid;
  eligible_pool uuid[];
  cursor_index integer;
BEGIN
  SELECT * INTO rule_row
  FROM public.exception_assignment_rules
  WHERE id=_rule_id AND enabled=true
  FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  IF auth.uid() IS NULL OR NOT (
    public.has_tenant_role(auth.uid(), rule_row.tenant_id, 'tenant_admin')
    OR public.user_has_permission(auth.uid(), rule_row.tenant_id, 'break.assign', NULL)
  ) THEN
    RAISE EXCEPTION 'forbidden: break.assign permission required';
  END IF;

  SELECT array_agg(member.user_id ORDER BY array_position(rule_row.assignee_pool, member.user_id))
  INTO eligible_pool
  FROM public.tenant_members member
  WHERE member.tenant_id=rule_row.tenant_id
    AND member.active=true
    AND member.user_id=ANY(rule_row.assignee_pool);

  IF rule_row.strategy='by_severity' AND _severity IS NOT NULL
     AND rule_row.severity_routes ? _severity THEN
    candidate := (rule_row.severity_routes->>_severity)::uuid;
  ELSIF rule_row.strategy='by_tag' AND _tags IS NOT NULL THEN
    SELECT (rule_row.tag_routes->>tag)::uuid INTO candidate
    FROM unnest(_tags) tag
    WHERE rule_row.tag_routes ? tag
    LIMIT 1;
  ELSIF rule_row.strategy='load_balanced' THEN
    SELECT pool.user_id INTO candidate
    FROM unnest(eligible_pool) pool(user_id)
    LEFT JOIN public.recon_exceptions exception
      ON exception.tenant_id=rule_row.tenant_id
     AND exception.assignee=pool.user_id
     AND exception.status IN ('open','investigating')
    GROUP BY pool.user_id
    ORDER BY count(exception.id), array_position(eligible_pool,pool.user_id)
    LIMIT 1;
  ELSIF cardinality(eligible_pool) > 0 THEN
    cursor_index := (rule_row.last_assigned_index + 1) % cardinality(eligible_pool);
    candidate := eligible_pool[cursor_index + 1];
    UPDATE public.exception_assignment_rules
    SET last_assigned_index=cursor_index, updated_at=now()
    WHERE id=rule_row.id;
  END IF;

  IF candidate IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.tenant_members member
    WHERE member.tenant_id=rule_row.tenant_id
      AND member.user_id=candidate
      AND member.active=true
  ) THEN
    RETURN NULL;
  END IF;
  RETURN candidate;
END;
$function$

CREATE OR REPLACE FUNCTION public.review_proposed_match_atomic(_tenant_id uuid, _match_id uuid, _decision text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  proposal public.proposed_matches%ROWTYPE;
  created_match_id uuid;
BEGIN
  IF _decision NOT IN ('accepted','rejected') THEN RAISE EXCEPTION 'invalid decision'; END IF;
  IF actor_id IS NULL OR NOT (
    public.has_tenant_role(actor_id,_tenant_id,'tenant_admin')
    OR public.user_has_permission(actor_id,_tenant_id,'recon.match.approve',NULL)
  ) THEN RAISE EXCEPTION 'forbidden: recon.match.approve permission required'; END IF;
  SELECT * INTO proposal FROM public.proposed_matches
  WHERE id=_match_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'proposed match not found'; END IF;
  IF proposal.status<>'pending' THEN RAISE EXCEPTION 'proposed match already decided'; END IF;
  IF proposal.run_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.recon_runs run
    WHERE run.id=proposal.run_id AND run.tenant_id=_tenant_id
      AND (proposal.definition_id IS NULL OR run.definition_id=proposal.definition_id)
  ) THEN RAISE EXCEPTION 'proposed match scope mismatch'; END IF;

  IF _decision='accepted' AND proposal.run_id IS NOT NULL THEN
    INSERT INTO public.recon_matches(run_id,tenant_id,rule_id,cardinality,members,score,confidence,confidence_model,feature_vector)
    VALUES (proposal.run_id,_tenant_id,coalesce(proposal.rule_hint,'ml_proposed'),proposal.cardinality,
      proposal.members,proposal.ml_score,proposal.ml_score,'proposed_match',proposal.ml_features)
    RETURNING id INTO created_match_id;
  END IF;
  UPDATE public.proposed_matches SET status=_decision,reviewer_id=actor_id,reviewed_at=now(),review_note=_note
  WHERE id=_match_id AND tenant_id=_tenant_id;
  IF proposal.definition_id IS NOT NULL THEN
    INSERT INTO public.recon_match_feedback(tenant_id,recon_id,match_id,decision,feature_vector,predicted_confidence,notes,decided_by)
    VALUES (_tenant_id,proposal.definition_id,created_match_id,
      CASE WHEN _decision='accepted' THEN 'accept' ELSE 'reject' END,
      proposal.ml_features,proposal.ml_score,_note,actor_id);
  END IF;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (actor_id,_tenant_id,'workspace','proposed_match.'||_decision,'proposed_matches',_match_id::text,
    jsonb_build_object('created_match_id',created_match_id,'confidence',proposal.ml_score));
  RETURN jsonb_build_object('ok',true,'match_id',created_match_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.decide_manual_match_atomic(_tenant_id uuid, _approval_id uuid, _decision text, _reject_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor_id uuid:=auth.uid(); approval public.manual_match_approvals%ROWTYPE; r public.recon_runs%ROWTYPE; evidence jsonb; new_match_id uuid;
BEGIN
 IF _decision NOT IN ('approved','rejected') OR actor_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor_id AND active) OR NOT (public.has_tenant_role(actor_id,_tenant_id,'tenant_admin') OR public.user_has_permission(actor_id,_tenant_id,'recon.match.approve',NULL)) THEN RAISE EXCEPTION 'Independent checker capability required' USING ERRCODE='42501'; END IF;
 SELECT * INTO approval FROM public.manual_match_approvals WHERE id=_approval_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR approval.status<>'pending' OR approval.proposed_by=actor_id THEN RAISE EXCEPTION 'Current independent request required' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=approval.run_id AND tenant_id=_tenant_id FOR UPDATE;
 IF r.id IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=approval.proposed_by AND active AND role::text IN ('tenant_admin','tenant_analyst')) OR NOT public.recon_authoritative_access_decision(r.definition_id,'approve') OR NOT private.recon_authoritative_access_decision_as(approval.proposed_by,r.definition_id,'edit') THEN RAISE EXCEPTION 'Current Run and maker/checker scope required' USING ERRCODE='42501'; END IF;
 IF _decision='rejected' AND length(btrim(coalesce(_reject_reason,'')))<10 THEN RAISE EXCEPTION 'Explain rejection' USING ERRCODE='22023'; END IF;
 IF _decision='approved' THEN
  IF (SELECT count(*) FROM public.audit_log WHERE tenant_id=_tenant_id AND resource_id=_approval_id::text AND action='manual_match.propose' AND actor_user_id=approval.proposed_by)<>1 THEN RAISE EXCEPTION 'Retained maker request audit required' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.recon_exceptions WHERE tenant_id=_tenant_id AND run_id=approval.run_id AND id=ANY(approval.exception_ids) ORDER BY id FOR UPDATE;
  evidence:=private.manual_match_group_evidence(_tenant_id,approval.run_id,approval.exception_ids,'approve');
  IF NOT EXISTS(SELECT 1 FROM public.audit_log WHERE tenant_id=_tenant_id AND resource_id=_approval_id::text AND action='manual_match.propose' AND actor_user_id=approval.proposed_by AND context->>'source_hash'=evidence->>'source_hash' AND context->>'run_id'=approval.run_id::text) THEN RAISE EXCEPTION 'Source hash no longer matches the retained request' USING ERRCODE='22023'; END IF;
  IF approval.members IS DISTINCT FROM evidence->'members' OR approval.cardinality IS DISTINCT FROM evidence->>'cardinality' THEN RAISE EXCEPTION 'Source members changed; request a fresh review' USING ERRCODE='22023'; END IF;
  INSERT INTO public.recon_matches(run_id,tenant_id,rule_id,cardinality,members,score) VALUES(approval.run_id,_tenant_id,'manual_4eyes',approval.cardinality,approval.members,1) RETURNING id INTO new_match_id;
  UPDATE public.recon_exceptions SET status='resolved',lifecycle_state='resolved',resolved_by=actor_id,resolved_at=now(),resolution_note='Manual 4-eyes match approved: '||_approval_id::text WHERE tenant_id=_tenant_id AND run_id=approval.run_id AND id=ANY(approval.exception_ids);
 END IF;
 UPDATE public.manual_match_approvals SET status=_decision,approver_id=actor_id,approved_at=now(),reject_reason=_reject_reason,created_match_id=new_match_id WHERE id=_approval_id AND tenant_id=_tenant_id;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor_id,_tenant_id,'workspace','manual_match.'||_decision,'manual_match_approvals',_approval_id::text,jsonb_build_object('run_id',approval.run_id,'run_uid',r.run_uid,'definition_id',r.definition_id,'match_id',new_match_id,'exception_ids',approval.exception_ids,'reason',_reject_reason));
 RETURN jsonb_build_object('ok',true,'match_id',new_match_id,'run_id',approval.run_id,'resolved_exception_ids',CASE WHEN _decision='approved' THEN to_jsonb(approval.exception_ids) ELSE '[]'::jsonb END);
END $function$

CREATE OR REPLACE FUNCTION public.tg_signoff_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF OLD.locked = true AND NEW.locked = true AND NEW.status = OLD.status THEN
      RAISE EXCEPTION 'Sign-off % is certified and locked', OLD.id USING ERRCODE = '42501';
    END IF;
    IF NEW.reviewed_by IS NOT NULL AND NEW.reviewed_by = NEW.prepared_by THEN
      RAISE EXCEPTION 'Reviewer cannot be the preparer' USING ERRCODE = '42501';
    END IF;
    IF NEW.approved_by IS NOT NULL AND (NEW.approved_by = NEW.prepared_by OR NEW.approved_by = NEW.reviewed_by) THEN
      RAISE EXCEPTION 'Approver cannot be the preparer or reviewer' USING ERRCODE = '42501';
    END IF;
    IF NEW.status = 'certified' AND (OLD.status IS DISTINCT FROM 'certified') THEN
      NEW.locked := true;
      NEW.certified_at := COALESCE(NEW.certified_at, now());
      NEW.certified_hash := encode(digest(
        COALESCE(NEW.id::text,'') ||
        COALESCE(NEW.tenant_id::text,'') ||
        COALESCE(NEW.period_date::text,'') ||
        COALESCE(NEW.prepared_by::text,'') ||
        COALESCE(NEW.reviewed_by::text,'') ||
        COALESCE(NEW.approved_by::text,'') ||
        COALESCE(NEW.certified_at::text,''), 'sha256'), 'hex');
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_collateral_csa_access(_tenant_id uuid, _agreement_id uuid, _owner_bu_ids uuid[], _group_ids uuid[], _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_registry uuid; v_bu_ids uuid[]; v_group_ids uuid[];
  v_group uuid; v_bu uuid; v_grant record;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'collateral');

  IF v_actor IS NULL OR _tenant_id IS NULL OR _agreement_id IS NULL
    OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000
    OR NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant_id
      AND m.user_id=v_actor AND m.active AND m.role='tenant_admin'::public.tenant_role)
  THEN RAISE EXCEPTION 'not authorized' USING ERRCODE='42501'; END IF;
  PERFORM a.id FROM public.collateral_csa_agreements a
    WHERE a.id=_agreement_id AND a.tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CSA agreement is outside this tenant' USING ERRCODE='42501'; END IF;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_bu_ids
    FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) x;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_group_ids
    FROM unnest(coalesce(_group_ids,ARRAY[]::uuid[])) x;
  IF cardinality(v_bu_ids)=0 OR cardinality(v_bu_ids)>50 OR cardinality(v_group_ids)>100
    OR EXISTS(SELECT 1 FROM unnest(v_bu_ids) x LEFT JOIN public.business_units b
      ON b.id=x AND b.tenant_id=_tenant_id AND NOT b.is_archived WHERE b.id IS NULL)
    OR EXISTS(SELECT 1 FROM unnest(v_group_ids) x LEFT JOIN public.tenant_groups g
      ON g.id=x AND g.tenant_id=_tenant_id WHERE g.id IS NULL)
  THEN RAISE EXCEPTION 'invalid CSA business unit or group selection' USING ERRCODE='22023'; END IF;
  SELECT r.id INTO v_registry FROM public.data_resource_registry r
    WHERE r.tenant_id=_tenant_id AND r.resource_type='collateral_csa_agreement'
      AND r.collateral_csa_agreement_id=_agreement_id FOR UPDATE;
  IF v_registry IS NULL THEN
    INSERT INTO public.data_resource_registry(
      tenant_id,resource_type,collateral_csa_agreement_id,created_by)
    VALUES(_tenant_id,'collateral_csa_agreement',_agreement_id,v_actor)
    RETURNING id INTO v_registry;
    INSERT INTO public.data_resource_registry_owner_bu(tenant_id,registry_id,bu_id,created_by)
      SELECT _tenant_id,v_registry,x,v_actor FROM unnest(v_bu_ids) x;
    INSERT INTO public.data_resource_registry_admin_audit(
      tenant_id,registry_id,operation,actor_id,reason,details)
    VALUES(_tenant_id,v_registry,'REGISTER',v_actor,btrim(_reason),
      jsonb_build_object('resource_type','collateral_csa_agreement',
        'resource_id',_agreement_id,'owner_bu_ids',v_bu_ids));
  ELSE
    FOR v_grant IN SELECT g.id FROM public.data_resource_registry_grants g
      WHERE g.registry_id=v_registry AND g.tenant_id=_tenant_id
        AND g.principal_type='group' AND g.action='view'
    LOOP PERFORM public.revoke_typed_data_resource_action(v_grant.id,_reason); END LOOP;
    PERFORM public.set_typed_data_resource_owners(v_registry,v_bu_ids,_reason);
  END IF;
  FOREACH v_group IN ARRAY v_group_ids LOOP
    v_bu:=NULL;
    SELECT owner.id INTO v_bu FROM public.business_units owner
      JOIN public.bu_group_assignments ga ON ga.tenant_id=_tenant_id AND ga.group_id=v_group
      JOIN public.business_units assigned ON assigned.id=ga.bu_id
        AND assigned.tenant_id=ga.tenant_id AND NOT assigned.is_archived
      WHERE owner.tenant_id=_tenant_id AND owner.id=ANY(v_bu_ids) AND NOT owner.is_archived
        AND (assigned.id=owner.id OR (ga.inherit_descendants AND owner.path <@ assigned.path))
      ORDER BY owner.id LIMIT 1;
    IF v_bu IS NULL THEN RAISE EXCEPTION 'CSA group is not assigned to an owning BU'
      USING ERRCODE='42501'; END IF;
    PERFORM public.grant_typed_data_resource_action(v_registry,v_bu,'group',v_group,'view',_reason);
  END LOOP;
  RETURN jsonb_build_object('registered',true,'owner_bu_count',cardinality(v_bu_ids),
    'group_count',cardinality(v_group_ids));
END $function$

CREATE OR REPLACE FUNCTION public.append_environment_change_event(_request_id uuid, _event_type text, _actor_user_id uuid, _context jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  next_sequence integer;
  previous_hash text;
  event_time timestamptz := clock_timestamp();
  calculated_hash text;
  event_id bigint;
BEGIN
  IF _event_type NOT IN (
    'request_created','preflight_recorded','approved','rejected',
    'package_exported','package_transmitted','transport_failed','transport_reconciled','package_received',
    'target_importer_bound','access_mapping_confirmed',
    'execution_started','execution_succeeded','execution_failed','execution_rolled_back'
  ) THEN RAISE EXCEPTION 'Unsupported environment-change event'; END IF;
  PERFORM public.assert_environment_payload_safe(coalesce(_context,'{}'::jsonb));
  PERFORM pg_advisory_xact_lock(hashtextextended(_request_id::text,0));
  SELECT event_sequence+1,row_hash INTO next_sequence,previous_hash
  FROM public.environment_change_events WHERE request_id=_request_id
  ORDER BY event_sequence DESC LIMIT 1;
  next_sequence := coalesce(next_sequence,1);
  calculated_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'request_id',_request_id,'sequence',next_sequence,'event_type',_event_type,
    'actor_user_id',_actor_user_id,'context',coalesce(_context,'{}'::jsonb),
    'occurred_at',event_time,'prev_hash',previous_hash
  )::text,'UTF8'),'sha256'),'hex');
  INSERT INTO public.environment_change_events(
    request_id,event_sequence,event_type,actor_user_id,context,occurred_at,prev_hash,row_hash
  ) VALUES (
    _request_id,next_sequence,_event_type,_actor_user_id,coalesce(_context,'{}'::jsonb),
    event_time,previous_hash,calculated_hash
  ) RETURNING id INTO event_id;
  RETURN event_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.receive_environment_change_for_api(_request jsonb, _requester_email text, _target_importer_id uuid)
 RETURNS TABLE(request_id uuid, change_request_uid text, request_status text, manifest_hash text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  received record;
  target public.environment_change_requests%ROWTYPE;
  source_hash text;
  prior_setting text;
  importer_email text;
  importer_email_count integer;
BEGIN
  IF _target_importer_id IS NULL OR
     lower(trim(coalesce(_request->>'source_requester_email','')))
       IS DISTINCT FROM lower(trim(coalesce(_requester_email,''))) THEN
    RAISE EXCEPTION 'Signed source requester and target importer are required';
  END IF;
  PERFORM public.assert_environment_change_actor(
    nullif(_request->>'target_tenant_id','')::uuid,_target_importer_id);
  source_hash := encode(extensions.digest(
    convert_to(lower(trim(_requester_email)),'UTF8'),'sha256'),'hex');
  IF _request->>'source_requester_email_hash' IS DISTINCT FROM source_hash THEN
    RAISE EXCEPTION 'Signed source requester hash is inconsistent';
  END IF;
  SELECT count(*),min(email) INTO importer_email_count,importer_email
  FROM auth.users WHERE id=_target_importer_id;
  IF importer_email_count<>1 OR nullif(trim(importer_email),'') IS NULL THEN
    RAISE EXCEPTION 'Target importer identity is unavailable';
  END IF;
  -- The legacy receiver uses its email argument only to resolve and authorize
  -- the target-stage actor. The signed source identity stays in _request and
  -- source_hash; it need not exist or hold privileges in this project.
  SELECT * INTO received FROM public.receive_environment_change_for_api(
    _request,importer_email);
  SELECT * INTO target FROM public.environment_change_requests
    WHERE id=received.request_id FOR UPDATE;
  IF target.approval_stage<>'target_review' OR target.status<>'pending_approval'
     OR target.control_tenant_id IS DISTINCT FROM nullif(_request->>'target_tenant_id','')::uuid
     OR target.source_tenant_id IS DISTINCT FROM nullif(_request->>'source_tenant_id','')::uuid
     OR target.source_project_ref IS DISTINCT FROM _request->>'source_project_ref'
     OR target.target_project_ref IS DISTINCT FROM _request->>'target_project_ref'
     OR target.direction IS DISTINCT FROM _request->>'direction'
     OR target.manifest_hash IS DISTINCT FROM received.manifest_hash THEN
    RAISE EXCEPTION 'Imported target request is inconsistent';
  END IF;
  IF target.source_requester_email_hash IS NOT NULL THEN
    IF target.requested_by IS DISTINCT FROM _target_importer_id
       OR target.source_requester_email_hash IS DISTINCT FROM source_hash THEN
      RAISE EXCEPTION 'Incoming package is already bound to another importer or source requester';
    END IF;
  ELSE
    -- New rows already name the target importer. A legacy unbound row can
    -- still name the old source requester until this governed reimport binds it.
    IF target.requested_by IS DISTINCT FROM _target_importer_id
       AND target.requested_by IS DISTINCT FROM (
         SELECT id FROM auth.users WHERE lower(email)=lower(trim(_requester_email))) THEN
      RAISE EXCEPTION 'Incoming package requester attribution is inconsistent';
    END IF;
    prior_setting := current_setting('app.environment_change_lifecycle',true);
    PERFORM set_config('app.environment_change_lifecycle','on',true);
    UPDATE public.environment_change_requests
      SET requested_by=_target_importer_id,source_requester_email_hash=source_hash
      WHERE id=target.id;
    PERFORM set_config('app.environment_change_lifecycle',coalesce(prior_setting,''),true);
    PERFORM public.append_environment_change_event(target.id,'target_importer_bound',
      _target_importer_id,jsonb_build_object(
        'source_requester_email_hash',source_hash,
        'upstream_change_request_uid',target.upstream_change_request_uid,
        'manifest_hash',target.manifest_hash));
    INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (_target_importer_id,target.control_tenant_id,'tenant',
      'environment_change.package_imported','environment_change_request',target.id::text,
      jsonb_build_object('source_request_uid',target.upstream_change_request_uid,
        'source_requester_email_hash',source_hash,'manifest_hash',target.manifest_hash,
        'tenant_binding_enforced',true));
  END IF;
  RETURN QUERY SELECT received.request_id,received.change_request_uid,
    received.request_status,received.manifest_hash;
END;
$function$

CREATE OR REPLACE FUNCTION private.qualified_user_delegated_api_token(_token_id uuid, _tenant_id uuid, _required_scope text)
 RETURNS TABLE(token_id uuid, tenant_id uuid, actor_user_id uuid, principal_kind text, expires_at timestamp with time zone, scopes text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE token_row public.api_tokens%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role'
   OR _required_scope IS NULL OR _required_scope NOT IN ('recons.read','ai.inference') THEN
   RAISE EXCEPTION 'not permitted' USING ERRCODE='42501';
 END IF;
 SELECT t.* INTO token_row FROM public.api_tokens t WHERE t.id=_token_id AND t.tenant_id=_tenant_id
   AND t.principal_kind='user_delegated' AND t.subject_user_id=t.created_by AND t.issuer_user_id=t.created_by
   AND t.service_principal_id IS NULL AND t.revoked_at IS NULL AND t.created_by IS NOT NULL
   AND (t.expires_at IS NULL OR t.expires_at>clock_timestamp()) AND _required_scope=ANY(t.scopes) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant_id AND m.user_id=token_row.subject_user_id AND m.active=true FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT token_row.id,token_row.tenant_id,token_row.subject_user_id,token_row.principal_kind,token_row.expires_at,token_row.scopes;
END $function$

CREATE OR REPLACE FUNCTION private.dpdi_certify_exact_two_row_output(_tenant_id uuid, _setup_id uuid, _probe_id uuid, _request_key uuid, _request_context_id uuid, _readback_evidence_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c private.dpd_request_contexts%ROWTYPE;p private.dpdi_capacity_probes%ROWTYPE;j private.dpdi_jobs%ROWTYPE;
 d private.dpdi_published_datasets%ROWTYPE;q private.dpdi_output_registration_qualifications%ROWTYPE;
 cert private.dpdi_exact_output_capacity_certificates%ROWTYPE;actor uuid;network_enabled boolean;fp text;
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('role',true) IS DISTINCT FROM 'none'
 OR _request_key IS NULL OR coalesce(_readback_evidence_sha256,'')!~'^[a-f0-9]{64}$' OR _readback_evidence_sha256=repeat('0',64)
 THEN RAISE EXCEPTION 'dpdi.exact_capacity_closed_main_operator_and_readback_required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM private.dpd_request_contexts WHERE id=_request_context_id AND tenant_id=_tenant_id AND setup_id=_setup_id AND operation='publication.perform';
 IF c.id IS NULL OR c.expires_at<=clock_timestamp() OR c.transport_kind IS DISTINCT FROM 'main_fixed_service_verified_middleware_CF_transport' THEN RAISE EXCEPTION 'dpdi.exact_capacity_current_fixed_context_required' USING ERRCODE='42501';END IF;
 actor:=private.dpd_peer_actor(_tenant_id,c.verified_subject);PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 SELECT ip_allowlist_enabled INTO network_enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;
 IF actor IS DISTINCT FROM c.actor_id OR network_enabled IS NULL OR(network_enabled AND(c.request_ip IS NULL OR public.ip_in_tenant_allowlist(_tenant_id,host(c.request_ip)) IS DISTINCT FROM true))
 OR public.user_has_permission(actor,_tenant_id,'data.prep.author',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.exact_capacity_current_actor_network_grants_required' USING ERRCODE='42501';END IF;
 SELECT * INTO p FROM private.dpdi_capacity_probes WHERE id=_probe_id AND tenant_id=_tenant_id AND setup_id=_setup_id AND actor_id=actor;
 IF p.id IS NULL THEN RAISE EXCEPTION 'dpdi.exact_capacity_actual_owned_native_probe_required' USING ERRCODE='42501';END IF;
 j:=private.dpdi_authorize(_tenant_id,_setup_id,p.job_id,actor,true);SELECT * INTO d FROM private.dpdi_published_datasets WHERE id=p.dataset_id;fp:=private.dpdi_capacity_source_fingerprint();
 IF p.rows_count<>2 OR d.rows<>2 OR p.wire_bytes NOT BETWEEN 1 AND 2097152 OR p.elapsed_ms NOT BETWEEN 0 AND 15000
 OR p.allocated_context_snapshot_bytes NOT BETWEEN 1 AND 67108864
 OR p.finished_at<clock_timestamp()-interval '15 minutes' OR p.finished_at>clock_timestamp()
 OR p.configuration_id IS DISTINCT FROM d.configuration_id OR p.configuration_sha256 IS DISTINCT FROM j.snapshot->>'configuration_sha256'
 OR p.source_fingerprint IS DISTINCT FROM fp OR p.output_root_sha256 IS DISTINCT FROM d.content_sha256
 OR d.content_sha256 IS DISTINCT FROM(private.dpdi_head(j.id)).output_root_sha256
 OR EXISTS(SELECT 1 FROM private.dpdi_public_output_links WHERE private_dataset_id=d.id)
 THEN RAISE EXCEPTION 'dpdi.exact_two_row_current_source_resource_envelope_required' USING ERRCODE='54000';END IF;
 SELECT * INTO cert FROM private.dpdi_exact_output_capacity_certificates WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF cert.probe_id<>p.id OR cert.evidence_sha256<>_readback_evidence_sha256 THEN RAISE EXCEPTION 'dpdi.exact_capacity_immutable_request_conflict' USING ERRCODE='PT409';END IF;
  SELECT * INTO q FROM private.dpdi_output_registration_qualifications WHERE id=cert.qualification_id;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'qualification',to_jsonb(q),'certificate',to_jsonb(cert),'request_replay',true,'currently_available',q.expires_at>clock_timestamp());END IF;
 INSERT INTO private.dpdi_output_registration_qualifications(tenant_id,configuration_id,max_rows,max_wire_bytes,provider_evidence_sha256,source_body_sha256,qualified_by,qualified_at,expires_at)
 VALUES(_tenant_id,d.configuration_id,2,p.wire_bytes,_readback_evidence_sha256,encode(sha256(convert_to(pg_get_functiondef('public.dpdi_register_public_output(uuid,uuid,uuid,uuid)'::regprocedure),'UTF8')),'hex'),actor,clock_timestamp(),clock_timestamp()+interval '1 hour') RETURNING * INTO q;
 INSERT INTO private.dpdi_exact_output_capacity_certificates(qualification_id,probe_id,tenant_id,setup_id,actor_id,request_key,private_dataset_id,configuration_sha256,source_fingerprint,output_root_sha256,output_sha256,exact_wire_bytes,allocated_context_snapshot_bytes,elapsed_ms,evidence_sha256)
 VALUES(q.id,p.id,_tenant_id,_setup_id,actor,_request_key,d.id,p.configuration_sha256,fp,p.output_root_sha256,p.output_sha256,p.wire_bytes,p.allocated_context_snapshot_bytes,p.elapsed_ms,_readback_evidence_sha256) RETURNING * INTO cert;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'capacity.exact_two_row.qualified',q.id,jsonb_build_object('dataset_id',d.id,'native_probe_id',p.id,'max_rows','2','exact_wire_bytes',p.wire_bytes::text,'source_fingerprint',fp,'measurement_kind','allocated_context_snapshot_and_guarded_exact_registration','peak_rss_proved',false,'larger_population_qualified',false,'expires_at',q.expires_at));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'qualification',to_jsonb(q),'certificate',to_jsonb(cert),'request_replay',false,'currently_available',true,'peak_rss_proved',false,'larger_population_qualified',false);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_probe_output_capacity(_tenant_id uuid, _setup_id uuid, _private_dataset_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.perform',_request_context_id);d private.dpdi_published_datasets%ROWTYPE;j private.dpdi_jobs%ROWTYPE;p private.dpdi_capacity_probes%ROWTYPE;started timestamptz;finished timestamptz;result jsonb;receipt jsonb;memory_bytes bigint;wire_bytes bigint;fingerprint text;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 IF _request_key IS NULL THEN RAISE EXCEPTION 'dpdi.capacity_request_key_required' USING ERRCODE='22023';END IF;
 SELECT * INTO d FROM private.dpdi_published_datasets WHERE id=_private_dataset_id AND tenant_id=_tenant_id AND setup_id=_setup_id FOR UPDATE;
 IF d.id IS NULL THEN RAISE EXCEPTION 'dpdi.capacity_actual_manifest_required' USING ERRCODE='42501';END IF;j:=private.dpdi_authorize(_tenant_id,_setup_id,d.job_id,actor,true);fingerprint:=private.dpdi_capacity_source_fingerprint();
 SELECT * INTO p FROM private.dpdi_capacity_probes WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF p.dataset_id<>d.id THEN RAISE EXCEPTION 'dpdi.capacity_request_conflict' USING ERRCODE='PT409';END IF;RETURN to_jsonb(p)||jsonb_build_object('state','probe_recorded','request_replay',true,'qualification_created',false,'memory_metric','allocated_context_snapshot_not_peak_rss','full_registration_writes_rolled_back',true);END IF;
 IF EXISTS(SELECT 1 FROM private.dpdi_public_output_links WHERE private_dataset_id=d.id) THEN RAISE EXCEPTION 'dpdi.capacity_probe_requires_not_yet_registered_output_no_cached_measurement' USING ERRCODE='PT409';END IF;
 SELECT coalesce(sum(octet_length(wire)),0) INTO wire_bytes FROM private.dpdi_job_pages WHERE job_id=j.id;
 IF d.rows NOT BETWEEN 1 AND 1000000 OR wire_bytes NOT BETWEEN 1 AND 268435456 THEN RAISE EXCEPTION 'dpdi.capacity_probe_bounded_actual_population_required' USING ERRCODE='54000';END IF;
 IF d.rows=2 AND wire_bytes<=2097152 THEN PERFORM set_config('work_mem','4MB',true); -- Managed PostgreSQL retains its existing temporary-file policy; no SET/grant/superuser change.
END IF;
 started:=clock_timestamp();
 BEGIN
  INSERT INTO private.dpdi_capacity_probe_permits VALUES(pg_backend_pid(),txid_current(),_tenant_id,_setup_id,d.id,actor,_request_context_id,fingerprint,NULL);
  -- Exact current production registration, including integrity/RLP/governance,
  -- output inserts, batch state and audit. Every row write below rolls back.
  result:=public.dpdi_register_public_output(_tenant_id,_setup_id,d.id,_request_context_id);
  IF (result->>'request_replay')::boolean IS DISTINCT FROM false OR (result->'dataset'->>'rows')::bigint IS DISTINCT FROM d.rows THEN RAISE EXCEPTION 'dpdi.capacity_actual_full_registration_required';END IF;
  SELECT memory_snapshot_bytes INTO memory_bytes FROM private.dpdi_capacity_probe_permits WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current();
  IF memory_bytes IS NULL THEN RAISE EXCEPTION 'dpdi.capacity_native_memory_snapshot_missing';END IF;
  RAISE EXCEPTION 'dpdi.capacity_probe_intentional_subtransaction_rollback' USING ERRCODE='PZ001';
 EXCEPTION WHEN SQLSTATE 'PZ001' THEN NULL;
 END;
 finished:=clock_timestamp();
 IF EXISTS(SELECT 1 FROM private.dpdi_public_output_links WHERE private_dataset_id=d.id) OR EXISTS(SELECT 1 FROM public.data_prep_prepared_datasets WHERE id=(result->'dataset'->>'id')::uuid) OR EXISTS(SELECT 1 FROM public.workspace_data_source_uploads WHERE id=(result->>'output_upload_id')::uuid) OR EXISTS(SELECT 1 FROM private.dpdi_capacity_probe_permits WHERE backend_pid=pg_backend_pid() AND transaction_id=txid_current()) THEN RAISE EXCEPTION 'dpdi.capacity_probe_rollback_not_complete';END IF;
 receipt:=jsonb_build_object('tenant_id',_tenant_id,'setup_id',_setup_id,'dataset_id',d.id,'job_id',j.id,'configuration_id',d.configuration_id,'actor_id',actor,'backend_pid',pg_backend_pid(),'source_fingerprint',fingerprint,'configuration_sha256',j.snapshot->>'configuration_sha256','output_root_sha256',(private.dpdi_head(j.id)).output_root_sha256,'rows_count',d.rows::text,'wire_bytes',wire_bytes::text,'output_sha256',result->'dataset'->>'content_sha256','elapsed_ms',(extract(epoch FROM finished-started)*1000)::text,'allocated_context_snapshot_bytes',memory_bytes::text,'started_at',started,'finished_at',finished,'coverage','exact_native_registration_with_rolled_back_output_audit_and_batch_writes','memory_metric','allocated_context_snapshot_not_peak_rss');
 INSERT INTO private.dpdi_capacity_probes(tenant_id,setup_id,dataset_id,job_id,configuration_id,actor_id,request_key,backend_pid,source_fingerprint,configuration_sha256,output_root_sha256,rows_count,wire_bytes,output_sha256,elapsed_ms,allocated_context_snapshot_bytes,started_at,finished_at,receipt_sha256) VALUES(_tenant_id,_setup_id,d.id,j.id,d.configuration_id,actor,_request_key,pg_backend_pid(),fingerprint,j.snapshot->>'configuration_sha256',(private.dpdi_head(j.id)).output_root_sha256,d.rows,wire_bytes,result->'dataset'->>'content_sha256',extract(epoch FROM finished-started)*1000,memory_bytes,started,finished,private.dpw_hash(receipt)) RETURNING * INTO p;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'capacity.probe.recorded',p.id,jsonb_build_object('receipt_sha256',p.receipt_sha256,'rows',p.rows_count::text,'qualification_created',false,'rolled_back_output_writes',true,'audit_sequence_values_may_advance',true,'observed_work_mem',current_setting('work_mem'),'observed_temp_file_limit',current_setting('temp_file_limit'),'temp_file_policy_changed',false));
 RETURN to_jsonb(p)||jsonb_build_object('state','probe_recorded','request_replay',false,'qualification_created',false,'memory_metric','allocated_context_snapshot_not_peak_rss','full_registration_writes_rolled_back',true,'audit_sequence_values_may_advance',true);
END $function$

CREATE OR REPLACE FUNCTION public.guard_tenant_template_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF current_user NOT IN ('postgres','service_role') AND (
    TG_OP <> 'INSERT' OR NEW.status <> 'draft' OR NEW.created_by IS DISTINCT FROM auth.uid()
    OR NEW.submitted_by IS NOT NULL OR NEW.submitted_at IS NOT NULL
    OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL
    OR NEW.source_recon_definition_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'tenant template lifecycle requires governed action' USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.dpdi_certify_output_capacity(_tenant_id uuid, _setup_id uuid, _probe_id uuid, _request_key uuid, _request_context_id uuid, _evidence jsonb, _max_rows bigint, _max_wire_bytes bigint, _max_elapsed_ms bigint, _max_peak_rss_bytes bigint, _ttl_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c private.dpd_request_contexts%ROWTYPE;p private.dpdi_capacity_probes%ROWTYPE;j private.dpdi_jobs%ROWTYPE;q private.dpdi_output_registration_qualifications%ROWTYPE;cert private.dpdi_capacity_certificates%ROWTYPE;actor uuid;request_sha text;network_enabled boolean;observed_from timestamptz;observed_to timestamptz;current_source text;
BEGIN
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('role',true) IS DISTINCT FROM 'none' OR _request_key IS NULL THEN RAISE EXCEPTION 'dpdi.capacity_closed_native_operator_required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM private.dpd_request_contexts WHERE id=_request_context_id AND tenant_id=_tenant_id AND setup_id=_setup_id AND operation='publication.perform';
 IF c.id IS NULL OR c.expires_at<=clock_timestamp() OR c.transport_kind IS DISTINCT FROM 'main_fixed_service_verified_middleware_CF_transport' THEN RAISE EXCEPTION 'dpdi.capacity_fresh_actual_context_required' USING ERRCODE='42501';END IF;
 actor:=private.dpd_peer_actor(_tenant_id,c.verified_subject);PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 SELECT ip_allowlist_enabled INTO network_enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;
 IF actor IS DISTINCT FROM c.actor_id OR network_enabled IS NULL OR (network_enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(_tenant_id,host(c.request_ip)) IS DISTINCT FROM true)) OR public.user_has_permission(actor,_tenant_id,'data.prep.author',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.capacity_current_actor_network_grants_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO p FROM private.dpdi_capacity_probes WHERE id=_probe_id AND tenant_id=_tenant_id AND setup_id=_setup_id AND actor_id=actor;
 IF NOT FOUND THEN RAISE EXCEPTION 'dpdi.capacity_actual_owned_probe_required' USING ERRCODE='42501';END IF;j:=private.dpdi_authorize(_tenant_id,_setup_id,p.job_id,actor,true);current_source:=private.dpdi_capacity_source_fingerprint();
 IF p.source_fingerprint IS DISTINCT FROM current_source OR p.configuration_sha256 IS DISTINCT FROM j.snapshot->>'configuration_sha256' OR p.output_root_sha256 IS DISTINCT FROM (private.dpdi_head(j.id)).output_root_sha256 OR p.finished_at<clock_timestamp()-interval '24 hours' THEN RAISE EXCEPTION 'dpdi.capacity_current_probe_source_and_configuration_required' USING ERRCODE='PT409';END IF;
 IF _max_rows IS NULL OR _max_rows NOT BETWEEN 1 AND p.rows_count OR _max_wire_bytes IS NULL OR _max_wire_bytes NOT BETWEEN 1 AND p.wire_bytes OR _max_elapsed_ms IS NULL OR _max_elapsed_ms NOT BETWEEN 1 AND 60000 OR _max_peak_rss_bytes IS NULL OR _max_peak_rss_bytes NOT BETWEEN 1 AND 1073741824 OR _ttl_seconds IS NULL OR _ttl_seconds NOT BETWEEN 60 AND 86400 OR jsonb_typeof(_evidence) IS DISTINCT FROM 'object' OR octet_length(_evidence::text)>16384 THEN RAISE EXCEPTION 'dpdi.capacity_explicit_bounded_budget_required' USING ERRCODE='22023';END IF;
 -- This gate intentionally cannot turn a SQL allocation snapshot into peak RSS.
 -- Main must independently review the authenticated provider telemetry artifact.
 IF _evidence->>'protocol' IS DISTINCT FROM 'fvi_dpdi_provider_capacity_v1' OR _evidence->>'native_probe_id' IS DISTINCT FROM p.id::text OR _evidence->>'native_receipt_sha256' IS DISTINCT FROM p.receipt_sha256 OR _evidence->>'source_fingerprint' IS DISTINCT FROM current_source OR _evidence->>'backend_pid' IS DISTINCT FROM p.backend_pid::text OR _evidence->>'measurement_kind' IS DISTINCT FROM 'provider_process_peak_rss' OR _evidence->>'measurement_source' IS DISTINCT FROM 'parent_verified_provider_telemetry' OR _evidence->>'full_registration_path' IS DISTINCT FROM 'true' OR coalesce(_evidence->>'peak_rss_bytes','')!~'^[1-9][0-9]{0,15}$' OR coalesce(_evidence->>'whole_registration_ms','')!~'^[1-9][0-9]{0,8}$' OR coalesce(_evidence->>'artifact_sha256','')!~'^[a-f0-9]{64}$' OR _evidence->>'artifact_sha256'=repeat('0',64) OR coalesce(_evidence->>'observed_from','')!~'^\d{4}-\d{2}-\d{2}T.*(Z|[+-]\d{2}:\d{2})$' OR coalesce(_evidence->>'observed_to','')!~'^\d{4}-\d{2}-\d{2}T.*(Z|[+-]\d{2}:\d{2})$' THEN RAISE EXCEPTION 'dpdi.capacity_independent_full_provider_measurement_required' USING ERRCODE='22023';END IF;
 observed_from:=(_evidence->>'observed_from')::timestamptz;observed_to:=(_evidence->>'observed_to')::timestamptz;
 IF observed_from>p.started_at OR observed_to<p.finished_at OR observed_to<=observed_from OR observed_to>clock_timestamp()+interval '5 seconds' OR (_evidence->>'whole_registration_ms')::bigint<p.elapsed_ms OR (_evidence->>'whole_registration_ms')::bigint>_max_elapsed_ms OR p.elapsed_ms>_max_elapsed_ms OR (_evidence->>'peak_rss_bytes')::bigint>_max_peak_rss_bytes THEN RAISE EXCEPTION 'dpdi.capacity_actual_measurement_exceeds_explicit_budget_or_interval' USING ERRCODE='54000';END IF;
 request_sha:=private.dpw_hash(jsonb_build_object('probe_id',_probe_id,'evidence',_evidence,'max_rows',_max_rows::text,'max_wire_bytes',_max_wire_bytes::text,'max_elapsed_ms',_max_elapsed_ms::text,'max_peak_rss_bytes',_max_peak_rss_bytes::text,'ttl_seconds',_ttl_seconds));
 SELECT * INTO cert FROM private.dpdi_capacity_certificates WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF cert.request_sha256 IS DISTINCT FROM request_sha THEN RAISE EXCEPTION 'dpdi.capacity_immutable_certificate_request_conflict' USING ERRCODE='PT409';END IF;SELECT * INTO q FROM private.dpdi_output_registration_qualifications WHERE id=cert.qualification_id;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'qualification',to_jsonb(q),'certificate',to_jsonb(cert),'request_replay',true,'currently_available',q.expires_at>clock_timestamp());END IF;
 INSERT INTO private.dpdi_output_registration_qualifications(tenant_id,configuration_id,max_rows,max_wire_bytes,provider_evidence_sha256,source_body_sha256,qualified_by,qualified_at,expires_at) VALUES(_tenant_id,p.configuration_id,_max_rows,_max_wire_bytes,_evidence->>'artifact_sha256',encode(sha256(convert_to(pg_get_functiondef('public.dpdi_register_public_output(uuid,uuid,uuid,uuid)'::regprocedure),'UTF8')),'hex'),actor,clock_timestamp(),clock_timestamp()+_ttl_seconds*interval '1 second') RETURNING * INTO q;
 INSERT INTO private.dpdi_capacity_certificates(qualification_id,probe_id,tenant_id,actor_id,request_key,source_fingerprint,configuration_sha256,evidence,evidence_sha256,request_sha256) VALUES(q.id,p.id,_tenant_id,actor,_request_key,current_source,p.configuration_sha256,_evidence,private.dpw_hash(_evidence),request_sha) RETURNING * INTO cert;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'capacity.qualification.recorded',q.id,jsonb_build_object('native_probe_id',p.id,'artifact_sha256',q.provider_evidence_sha256,'source_fingerprint',current_source,'max_rows',q.max_rows::text,'max_wire_bytes',q.max_wire_bytes::text,'expires_at',q.expires_at,'measurement_kind','provider_process_peak_rss'));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'qualification',to_jsonb(q),'certificate',to_jsonb(cert),'request_replay',false,'currently_available',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_finish_attachment_purge(_file_id uuid, _job_id uuid, _object_absence_verified boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a public.data_prep_attachment_retention%ROWTYPE; t public.data_prep_attachment_tombstones%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role'
 OR _object_absence_verified IS DISTINCT FROM true OR private.dpw_retention_attest() IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.closed_retention_processor_required'; END IF;
 SELECT * INTO a FROM public.data_prep_attachment_retention WHERE file_id=_file_id FOR UPDATE;
 IF NOT FOUND OR a.expires_at>clock_timestamp() OR private.dpw_attachment_has_hold(_file_id) OR private.dpw_attachment_has_canonical_reference(_file_id) THEN RAISE EXCEPTION 'dpw.attachment_not_purge_eligible'; END IF;
 SELECT * INTO t FROM public.data_prep_attachment_tombstones WHERE file_id=_file_id;
 IF FOUND THEN
  IF t.job_id<>_job_id THEN RAISE EXCEPTION 'dpw.purge_job_conflict'; END IF;
  RETURN to_jsonb(t);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM private.dpw_attachment_purge_claims WHERE file_id=_file_id AND job_id=_job_id AND state='claimed' AND expires_at>clock_timestamp())
 OR EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id=a.bucket_id AND name=a.original_path)
 THEN RAISE EXCEPTION 'dpw.purge_absence_and_fresh_claim_required'; END IF;
 INSERT INTO public.data_prep_attachment_tombstones(file_id,job_id,transport_role,object_absence_verified,original_file_bytes_sha256,original_size_bytes)
 VALUES(_file_id,_job_id,'service_role',true,a.original_file_bytes_sha256,a.original_size_bytes) RETURNING * INTO t;
 UPDATE private.dpw_attachment_purge_claims SET state='completed' WHERE file_id=_file_id;
 -- Only storage bytes are attested here. Shared workspace upload JSON is NOT
 -- deleted by an unqualified generic path. Main must qualify attached parsed
 -- data-only clearing and legal-hold/object-delete race before activation.
 RETURN to_jsonb(t);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_get_file_retention(_tenant_id uuid, _pipeline_id uuid, _file_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'view'); a public.data_prep_attachment_retention%ROWTYPE;
BEGIN
 SELECT * INTO a FROM public.data_prep_attachment_retention WHERE file_id=_file_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'dpw.attachment_unknown'; END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'retention',to_jsonb(a),'view_available',private.dpw_attachment_viewable(_file_id),
 'legal_hold',private.dpw_attachment_has_hold(_file_id),'tombstone',(SELECT to_jsonb(t) FROM public.data_prep_attachment_tombstones t WHERE file_id=_file_id));
END $function$

CREATE OR REPLACE FUNCTION public.seed_default_platform_groups()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE p record; g_id uuid; r public.platform_role; created int := 0;
BEGIN
  FOR p IN SELECT * FROM public.platform_group_presets WHERE is_default ORDER BY sort_order LOOP
    INSERT INTO public.platform_groups (name, description, is_system, preset_key)
    VALUES (p.name, p.description, true, p.preset_key)
    ON CONFLICT (preset_key) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description
    RETURNING id INTO g_id;
    created := created + 1;
    FOREACH r IN ARRAY p.roles LOOP
      INSERT INTO public.platform_group_roles(group_id, role) VALUES (g_id, r) ON CONFLICT DO NOTHING;
    END LOOP;
  END LOOP;
  RETURN created;
END $function$

CREATE OR REPLACE FUNCTION public.save_tenant_template_from_recon_atomic(_tenant_id uuid, _recon_definition_id uuid, _title text, _description text DEFAULT NULL::text, _tenant_template_id uuid DEFAULT NULL::uuid, _semver text DEFAULT '1.0.0'::text, _changelog text DEFAULT NULL::text)
 RETURNS TABLE(tenant_template_id uuid, version_id uuid, saved_semver text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid:=auth.uid();
  recon_row public.recon_definitions%ROWTYPE;
  template_row public.tenant_templates%ROWTYPE;
  version_row public.tenant_template_versions%ROWTYPE;
  snapshot jsonb;
BEGIN
  IF actor IS NULL OR NOT public.mkt_is_tenant_admin(_tenant_id) THEN
    RAISE EXCEPTION 'active tenant administrator required' USING ERRCODE='42501';
  END IF;
  IF length(btrim(COALESCE(_title,''))) NOT BETWEEN 2 AND 120
     OR _semver !~ '^[0-9]+\.[0-9]+\.[0-9]+$' THEN
    RAISE EXCEPTION 'invalid template title or semantic version' USING ERRCODE='22023';
  END IF;
  SELECT * INTO recon_row FROM public.recon_definitions
  WHERE id=_recon_definition_id AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'tenant reconciliation not found' USING ERRCODE='P0002'; END IF;
  snapshot:=jsonb_build_object(
    'kind','reconciliation','schema_version',1,'source_recon_definition_id',recon_row.id,
    'source_recon_code',recon_row.recon_code,'recon_type',recon_row.recon_type,
    'description',recon_row.description,'sides',recon_row.sides,'rules',recon_row.rules
  );

  IF _tenant_template_id IS NULL THEN
    INSERT INTO public.tenant_templates(
      tenant_id,title,description,spec,current_semver,status,created_by,source_recon_definition_id
    ) VALUES (_tenant_id,btrim(_title),_description,snapshot,_semver,'draft',actor,recon_row.id)
    RETURNING * INTO template_row;
  ELSE
    SELECT * INTO template_row FROM public.tenant_templates
    WHERE id=_tenant_template_id AND tenant_id=_tenant_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'tenant template not found' USING ERRCODE='P0002'; END IF;
    UPDATE public.tenant_templates SET
      title=btrim(_title),description=_description,spec=snapshot,current_semver=_semver,status='draft',
      source_recon_definition_id=recon_row.id,submitted_by=NULL,submitted_at=NULL,approved_by=NULL,approved_at=NULL
    WHERE id=template_row.id RETURNING * INTO template_row;
  END IF;

  INSERT INTO public.tenant_template_versions(
    tenant_template_id,tenant_id,semver,spec,changelog,created_by,status,source_recon_definition_id
  ) VALUES (template_row.id,_tenant_id,_semver,snapshot,_changelog,actor,'draft',recon_row.id)
  RETURNING * INTO version_row;
  INSERT INTO public.mkt_audit_log(actor_id,tenant_id,entity_type,entity_id,action,after)
  VALUES (actor,_tenant_id,'tenant_template',template_row.id,
    CASE WHEN _tenant_template_id IS NULL THEN 'create' ELSE 'version' END,
    jsonb_build_object('semver',_semver,'version_id',version_row.id,'source_recon_id',recon_row.id));
  RETURN QUERY SELECT template_row.id,version_row.id,_semver;
END;
$function$

CREATE OR REPLACE FUNCTION public.clone_tenant_template_atomic(_tenant_id uuid, _source_template_id uuid, _title text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE actor uuid:=auth.uid(); source_row public.tenant_templates%ROWTYPE; clone_row public.tenant_templates%ROWTYPE;
BEGIN
  IF actor IS NULL OR NOT public.mkt_is_tenant_admin(_tenant_id) THEN RAISE EXCEPTION 'active tenant administrator required' USING ERRCODE='42501'; END IF;
  IF length(btrim(COALESCE(_title,''))) NOT BETWEEN 2 AND 120 THEN RAISE EXCEPTION 'invalid template title' USING ERRCODE='22023'; END IF;
  SELECT * INTO source_row FROM public.tenant_templates WHERE id=_source_template_id AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'tenant template not found' USING ERRCODE='P0002'; END IF;
  INSERT INTO public.tenant_templates(tenant_id,title,description,spec,current_semver,status,created_by,source_recon_definition_id)
  VALUES (_tenant_id,btrim(_title),source_row.description,source_row.spec,'1.0.0','draft',actor,source_row.source_recon_definition_id)
  RETURNING * INTO clone_row;
  INSERT INTO public.tenant_template_versions(tenant_template_id,tenant_id,semver,spec,changelog,created_by,status,source_recon_definition_id)
  VALUES (clone_row.id,_tenant_id,'1.0.0',source_row.spec,'Cloned from tenant template '||source_row.id::text,actor,'draft',source_row.source_recon_definition_id);
  INSERT INTO public.mkt_audit_log(actor_id,tenant_id,entity_type,entity_id,action,after)
  VALUES (actor,_tenant_id,'tenant_template',clone_row.id,'clone',jsonb_build_object('source_template_id',source_row.id));
  RETURN clone_row.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.dpw_set_attachment_hold(_tenant_id uuid, _pipeline_id uuid, _file_id uuid, _hold boolean, _hold_id uuid, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'manage'); entry public.data_prep_attachment_holds%ROWTYPE;
BEGIN
 IF _hold IS NULL OR length(coalesce(btrim(_reason),'')) NOT BETWEEN 3 AND 1000 OR private.dpw_legal_hold_attest(actor,_tenant_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.hold_authority_denied'; END IF;
 PERFORM 1 FROM public.data_prep_attachment_retention WHERE file_id=_file_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id FOR UPDATE;
 IF NOT FOUND OR EXISTS(SELECT 1 FROM public.data_prep_attachment_tombstones WHERE file_id=_file_id) THEN RAISE EXCEPTION 'dpw.attachment_already_purged_or_unknown'; END IF;
 IF NOT _hold AND NOT EXISTS(SELECT 1 FROM public.data_prep_attachment_holds h WHERE h.id=_hold_id AND h.file_id=_file_id AND h.operation='hold'
 AND NOT EXISTS(SELECT 1 FROM public.data_prep_attachment_holds r WHERE r.hold_id=h.id)) THEN RAISE EXCEPTION 'dpw.active_hold_required'; END IF;
 INSERT INTO public.data_prep_attachment_holds(file_id,operation,hold_id,actor_id,reason)
 VALUES(_file_id,CASE WHEN _hold THEN 'hold' ELSE 'release' END,CASE WHEN _hold THEN NULL ELSE _hold_id END,actor,btrim(_reason)) RETURNING * INTO entry;
 IF _hold THEN UPDATE private.dpw_attachment_purge_claims SET state='cancelled' WHERE file_id=_file_id AND state='claimed'; END IF;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.attachment.hold',entry.id,jsonb_build_object('file_id',_file_id,'operation',entry.operation,'reason',entry.reason));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'hold',to_jsonb(entry));
END $function$

CREATE OR REPLACE FUNCTION public.decide_source_environment_change_for_api(_request_id uuid, _approve boolean, _comment text, _actor_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE target public.environment_change_requests%ROWTYPE;
BEGIN
  SELECT * INTO target FROM public.environment_change_requests WHERE id=_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Environment change request not found'; END IF;
  IF target.approval_stage<>'source_review' OR
     target.control_tenant_id IS DISTINCT FROM target.source_tenant_id THEN
    RAISE EXCEPTION 'Source review is required';
  END IF;
  RETURN public.decide_environment_change_as(_request_id,_approve,_comment,_actor_user_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_incoming_environment_change_for_api(_request_id uuid, _approve boolean, _comment text, _confirm_access_mapping boolean, _actor_user_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE target public.environment_change_requests%ROWTYPE;
BEGIN
  SELECT * INTO target FROM public.environment_change_requests WHERE id=_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Environment change request not found'; END IF;
  IF target.approval_stage<>'target_review' OR
     target.control_tenant_id IS DISTINCT FROM target.target_tenant_id OR
     target.source_requester_email_hash IS NULL THEN
    RAISE EXCEPTION 'Bound incoming target review is required';
  END IF;
  RETURN public.approve_incoming_environment_change_as(
    _request_id,_approve,_comment,_confirm_access_mapping,_actor_user_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.read_reconciliation_runs_for_api(_token_id uuid, _tenant_id uuid, _tenant_slug text, _recon_id uuid, _mode text, _run_id uuid, _page integer, _days integer, _status text, _request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid; token_row public.api_tokens%ROWTYPE; payload jsonb; rows_json jsonb;
 run_json jsonb; page_json jsonb; counts_json jsonb; total bigint; audit_id bigint; since_time timestamptz;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' THEN
   RAISE EXCEPTION 'not permitted' USING ERRCODE='42501';
 END IF;
 IF _token_id IS NULL OR _tenant_id IS NULL OR _tenant_slug IS NULL OR _recon_id IS NULL
   OR _page IS NULL OR _page NOT BETWEEN 1 AND 10000 OR _mode IS NULL OR _mode NOT IN ('history','results')
   OR _days IS NULL OR _days NOT IN (1,7,14,30,90)
   OR _status IS NULL OR _status NOT IN ('all','match','partial','missing','duplicate','invalid_key','other','unavailable')
   OR (_mode='results' AND _run_id IS NULL) OR (_mode='history' AND (_run_id IS NOT NULL OR _status<>'all')) THEN
   RAISE EXCEPTION 'invalid read input' USING ERRCODE='22023';
 END IF;
 SELECT p.actor_user_id INTO actor FROM private.qualified_user_delegated_api_token(_token_id,_tenant_id,'recons.read') p;
 SELECT t.* INTO token_row FROM public.api_tokens t WHERE t.id=_token_id;
 -- Locks serialize read-before-revoke. Revocation committed first is denied.
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active=true FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.tenants WHERE id=_tenant_id AND slug=_tenant_slug FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'read not found' USING ERRCODE='P0002'; END IF;
 PERFORM 1 FROM public.recon_definitions WHERE id=_recon_id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'read not found' USING ERRCODE='P0002'; END IF;
 -- Lock current authorization inputs, always by token actor/target. No table lock,
 -- caller-selected actor, JWT override, role switch or general privileged proxy.
 PERFORM 1 FROM public.recon_definition_business_units WHERE recon_id=_recon_id FOR SHARE;
 PERFORM 1 FROM public.recon_definition_bu_grants WHERE recon_id=_recon_id FOR SHARE;
 PERFORM 1 FROM public.recon_permissions WHERE recon_id=_recon_id FOR SHARE;
 PERFORM 1 FROM public.tenant_group_members gm JOIN public.tenant_groups g ON g.id=gm.group_id
   WHERE gm.user_id=actor AND g.tenant_id=_tenant_id FOR SHARE OF gm,g;
 PERFORM 1 FROM public.bu_user_assignments WHERE tenant_id=_tenant_id AND user_id=actor FOR SHARE;
 PERFORM 1 FROM public.bu_group_assignments ga JOIN public.tenant_group_members gm ON gm.group_id=ga.group_id
   WHERE ga.tenant_id=_tenant_id AND gm.user_id=actor FOR SHARE OF ga;
 PERFORM 1 FROM public.business_units WHERE tenant_id=_tenant_id AND id IN (
   SELECT bu_id FROM public.recon_definition_business_units WHERE recon_id=_recon_id
   UNION SELECT bu_id FROM public.bu_user_assignments WHERE tenant_id=_tenant_id AND user_id=actor
   UNION SELECT ga.bu_id FROM public.bu_group_assignments ga JOIN public.tenant_group_members gm ON gm.group_id=ga.group_id
     WHERE ga.tenant_id=_tenant_id AND gm.user_id=actor) FOR SHARE;
 PERFORM 1 FROM public.platform_roles WHERE user_id=actor FOR SHARE;
 PERFORM 1 FROM public.platform_support_grants WHERE actor_id=actor AND tenant_id=_tenant_id FOR SHARE;
 IF public.recon_authoritative_access_decision_as(actor,_recon_id,'view') IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'not permitted' USING ERRCODE='42501';
 END IF;
 IF _mode='history' THEN
   since_time := statement_timestamp()-make_interval(days=>_days);
   -- One statement/snapshot for total AND page so concurrent new runs cannot
   -- disagree with has_next or total. All projections remain tenant/recon scoped.
   WITH scoped AS MATERIALIZED (
     SELECT id,run_uid,definition_id,status,matched_count,exception_count,total_rows,started_at,completed_at,
       CASE WHEN jsonb_typeof(stats->'matched_records')='number' THEN stats->'matched_records' ELSE 'null'::jsonb END AS matched_input_memberships
     FROM public.recon_runs WHERE tenant_id=_tenant_id AND definition_id=_recon_id AND started_at>=since_time
   ), page_rows AS (SELECT * FROM scoped ORDER BY started_at DESC,id ASC OFFSET ((_page-1)*50) LIMIT 50)
   SELECT (SELECT count(*) FROM scoped),coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.started_at DESC,p.id ASC),'[]')
     INTO total,rows_json FROM page_rows p;
   payload := jsonb_build_object('rows',rows_json,'total',total,'page',_page,'page_size',50,'has_next',_page::bigint*50<total);
 ELSE
   PERFORM 1 FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND definition_id=_recon_id FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'read not found' USING ERRCODE='P0002'; END IF;
   -- Same statement snapshot for stored run metadata, result parents and counts.
   SELECT to_jsonb(r),private.recon_api_persisted_result_page(_tenant_id,_run_id,_page-1,_status),
     private.recon_api_persisted_result_counts(_tenant_id,_run_id)
   INTO run_json,page_json,counts_json FROM (
     SELECT id,run_uid,definition_id,status,matched_count,exception_count,total_rows,started_at,completed_at,
       CASE WHEN jsonb_typeof(stats->'matched_records')='number' THEN stats->'matched_records' ELSE 'null'::jsonb END AS matched_input_memberships
     FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND definition_id=_recon_id) r;
   IF page_json IS NULL OR (page_json->>'page_size')::integer IS DISTINCT FROM 50 THEN
     RAISE EXCEPTION 'result paging contract drift';
   END IF;
   payload := jsonb_build_object('run',run_json,'results',page_json->'rows','field_names',page_json->'field_names',
     'parent_count',page_json->'parent_count','page',_page,'page_size',50,'has_next',page_json->'has_next','status_counts',counts_json);
 END IF;
 IF (token_row.expires_at IS NOT NULL AND token_row.expires_at<=clock_timestamp())
   OR public.recon_authoritative_access_decision_as(actor,_recon_id,'view') IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'not permitted' USING ERRCODE='42501';
 END IF;
 INSERT INTO public.audit_log(tenant_id,tenant_slug,actor_user_id,scope,action,resource_type,resource_id,context)
 VALUES(_tenant_id,_tenant_slug,actor,'api',
   CASE WHEN _mode='history' THEN 'api.reconciliation.run_history.read' ELSE 'api.reconciliation.run_results.read' END,
   CASE WHEN _mode='history' THEN 'recon_definition' ELSE 'recon_run' END,coalesce(_run_id,_recon_id)::text,
   jsonb_build_object('api_token_id',_token_id,'principal_kind','user_delegated','recon_id',_recon_id,
     'page',_page,'days',_days,'status',_status,'api_request_id',_request_id)) RETURNING id INTO audit_id;
 -- Insert returning includes AFTER-trigger completion. Require positive int8 receipt.
 IF audit_id IS NULL OR audit_id<=0 OR NOT EXISTS(SELECT 1 FROM public.audit_log a
   JOIN public.audit_chain_head h ON h.singleton=true AND h.last_audit_id=a.id AND h.last_hash=a.row_hash
   WHERE a.id=audit_id AND a.actor_user_id=actor AND a.tenant_id=_tenant_id
     AND a.resource_id=coalesce(_run_id,_recon_id)::text AND a.context->>'api_token_id'=_token_id::text
     AND octet_length(a.row_hash)=32)
   OR (token_row.expires_at IS NOT NULL AND token_row.expires_at<=clock_timestamp()) THEN
   RAISE EXCEPTION 'read audit receipt absent';
 END IF;
 RETURN payload||jsonb_build_object('audit_id',audit_id::text);
END $function$

CREATE OR REPLACE FUNCTION public.prepare_public_ai_inference(_token_hash text, _tenant_id uuid, _request_class text, _model text, _max_tokens integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET row_security TO 'on'
AS $function$
DECLARE
 tok public.api_tokens%ROWTYPE; actor uuid; request_id uuid; llm_provider uuid; reservation jsonb;
 pol public.ai_routing_policies%ROWTYPE; model_row public.ai_model_catalog%ROWTYPE;
 provider_row public.ai_provider_instances%ROWTYPE; vault_row public.app_vault_secrets%ROWTYPE;
 entry jsonb; idx integer; have_tenant_policy boolean; tenant_admin boolean; platform_admin boolean;
 output_bound integer; rate record; envelope jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Permission denied' USING ERRCODE='42501'; END IF;
 IF _token_hash IS NULL OR _token_hash !~ '^[a-f0-9]{64}$' THEN RETURN jsonb_build_object('error','invalid_token'); END IF;
 IF _request_class IS NULL OR _request_class NOT IN ('chat','embedding','image','tool','agent','other')
 OR _max_tokens IS NULL OR _max_tokens NOT BETWEEN 1 AND 4096 OR (_model IS NOT NULL AND length(_model) NOT BETWEEN 1 AND 256)
 THEN RETURN jsonb_build_object('error','invalid_request'); END IF;
 -- Same lock order as the existing spend writers, before taking token locks.
 PERFORM pg_advisory_xact_lock(61000,1);
 -- Do not choose among ambiguous verifiers (the existing index is not UNIQUE).
 IF (SELECT count(*) FROM public.api_tokens WHERE token_hash=_token_hash)<>1 THEN RETURN jsonb_build_object('error','invalid_token'); END IF;
 SELECT * INTO tok FROM public.api_tokens WHERE token_hash=_token_hash FOR SHARE;
 IF tok.revoked_at IS NOT NULL THEN RETURN jsonb_build_object('error','token_revoked'); END IF;
 IF tok.expires_at IS NOT NULL AND tok.expires_at<=clock_timestamp() THEN RETURN jsonb_build_object('error','token_expired'); END IF;
 IF NOT ('ai.inference'=ANY(tok.scopes)) THEN RETURN jsonb_build_object('error','missing_scope'); END IF;
 IF _tenant_id IS NOT NULL AND _tenant_id<>tok.tenant_id THEN RETURN jsonb_build_object('error','tenant_scope_mismatch'); END IF;
 BEGIN
  SELECT actor_user_id INTO actor FROM private.qualified_user_delegated_api_token(tok.id,tok.tenant_id,'ai.inference');
 EXCEPTION WHEN insufficient_privilege THEN RETURN jsonb_build_object('error','principal_denied'); END;
 IF actor IS NULL OR actor IS DISTINCT FROM tok.subject_user_id OR tok.principal_kind<>'user_delegated'
 THEN RETURN jsonb_build_object('error','principal_denied'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=tok.tenant_id AND tm.user_id=actor AND tm.active AND tm.deactivated_at IS NULL)
 THEN RETURN jsonb_build_object('error','principal_denied'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.tenants t WHERE t.id=tok.tenant_id AND t.ai_enabled)
 THEN RETURN jsonb_build_object('error','ai_policy_denied'); END IF;
 IF EXISTS(SELECT 1 FROM public.ai_governance_kill_switches k WHERE k.engaged AND (k.tenant_id IS NULL OR k.tenant_id=tok.tenant_id))
 THEN RETURN jsonb_build_object('error','ai_paused'); END IF;
 SELECT * INTO rate FROM public.rate_limit_hit('public-ai:'||tok.id::text,60,60);
 IF rate.allowed IS DISTINCT FROM true THEN RETURN jsonb_build_object('error','rate_limit_exceeded'); END IF;
 tenant_admin:=EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=tok.tenant_id AND tm.user_id=actor AND tm.active AND tm.deactivated_at IS NULL AND tm.role='tenant_admin');
 platform_admin:=public.is_platform_admin(actor);
 -- Actor-aware equivalents of the captured SELECT policies, intersected with
 -- the token tenant. No cross-tenant route/provider/vault access, even for admin.
 have_tenant_policy:=EXISTS(SELECT 1 FROM public.ai_routing_policies p WHERE p.enabled AND p.scope='tenant' AND p.tenant_id=tok.tenant_id AND (tenant_admin OR platform_admin));
 FOR pol IN SELECT * FROM public.ai_routing_policies p WHERE p.enabled
  AND ((have_tenant_policy AND p.scope='tenant' AND p.tenant_id=tok.tenant_id AND (tenant_admin OR platform_admin))
    OR (NOT have_tenant_policy AND p.scope='platform' AND p.tenant_id IS NULL)) ORDER BY p.priority,p.id
 LOOP
  IF pol.conditions->>'request_class' IS NOT NULL AND pol.conditions->>'request_class'<>_request_class THEN CONTINUE; END IF;
  IF pol.conditions->>'model_key' IS NOT NULL AND _model IS NOT NULL AND pol.conditions->>'model_key'<>_model THEN CONTINUE; END IF;
  IF jsonb_typeof(pol.chain)<>'array' OR jsonb_array_length(pol.chain)>64 THEN RETURN jsonb_build_object('error','route_unavailable'); END IF;
  idx:=-1;
  FOR entry IN SELECT value FROM jsonb_array_elements(pol.chain)
  LOOP
   idx:=idx+1;
   IF coalesce(entry->>'model_catalog_id','') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' THEN CONTINUE; END IF;
   SELECT * INTO model_row FROM public.ai_model_catalog m WHERE m.id=(entry->>'model_catalog_id')::uuid AND m.approval_status='approved'
    AND m.availability_status NOT IN ('unavailable','deprecated') AND (_model IS NULL OR m.model_key=_model);
   IF NOT FOUND THEN CONTINUE; END IF;
   SELECT * INTO provider_row FROM public.ai_provider_instances p WHERE p.id=model_row.provider_instance_id AND p.status='active'
    AND ((p.tenant_id IS NULL AND platform_admin) OR (p.tenant_id=tok.tenant_id AND (tenant_admin OR platform_admin)));
   IF NOT FOUND THEN CONTINUE; END IF;
   envelope:=NULL;
   IF provider_row.vault_secret_id IS NOT NULL THEN
    SELECT * INTO vault_row FROM public.app_vault_secrets v WHERE v.id=provider_row.vault_secret_id
     AND ((v.scope='tenant' AND v.tenant_id=tok.tenant_id AND tenant_admin)
       OR (v.scope='platform' AND v.tenant_id IS NULL AND platform_admin));
    IF NOT FOUND THEN CONTINUE; END IF;
    envelope:=jsonb_build_object('ciphertext',vault_row.ciphertext,'iv',vault_row.iv,'auth_tag',vault_row.auth_tag,
     'wrapped_dek',vault_row.wrapped_dek,'kek_provider',vault_row.kek_provider,'kek_ref',vault_row.kek_ref);
   END IF;
   IF coalesce(provider_row.endpoint,'')='' THEN RETURN jsonb_build_object('error','route_unavailable'); END IF;
   -- Use only an existing explicit operator binding. This never creates or
   -- infers a provider mapping and never admits a second, unreserved spend path.
   SELECT l.id INTO llm_provider FROM public.llm_providers l WHERE l.is_active AND l.tenant_id=tok.tenant_id
    AND l.scope::text='tenant' AND l.model_catalog_id=model_row.id AND l.provider_instance_id=provider_row.id
    AND l.model=model_row.model_key;
   IF NOT FOUND THEN CONTINUE; END IF;
   request_id:=gen_random_uuid();
   reservation:=private.reserve_public_ai_dispatch(tok.id,request_id,llm_provider,tok.tenant_id);
   -- The copied current budget contract serializes on (61000,1). Recheck
   -- wall-clock expiry after that wait while token/membership locks still hold.
   PERFORM * FROM private.qualified_user_delegated_api_token(tok.id,tok.tenant_id,'ai.inference');
   output_bound:=least(_max_tokens,coalesce(model_row.max_output_tokens,4096));
   IF output_bound<1 THEN CONTINUE; END IF;
   INSERT INTO private.public_ai_inference_requests(id,token_id,tenant_id,subject_user_id,policy_id,provider_instance_id,model_catalog_id,model,provider_code,chain_index,request_class,max_tokens)
    VALUES(request_id,tok.id,tok.tenant_id,actor,pol.id,provider_row.id,model_row.id,model_row.model_key,provider_row.provider_code,idx,_request_class,output_bound);
   -- Do not upgrade shared token locks for a cosmetic last-used touch. The
   -- attributable prepared receipt is the durable usage record for this path.
   INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(actor,tok.tenant_id,'tenant','api.ai.inference.prepare','public_ai_inference_request',request_id::text,
     jsonb_build_object('token_id',tok.id,'principal_kind',tok.principal_kind,'policy_id',pol.id,'provider_instance_id',provider_row.id,'model_catalog_id',model_row.id));
   IF tok.expires_at IS NOT NULL AND tok.expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION 'token_expired' USING ERRCODE='42501';
   END IF;
   RETURN jsonb_build_object('request_id',request_id,'token_id',tok.id,'tenant_id',tok.tenant_id,'subject_user_id',actor,'principal_kind',tok.principal_kind,'max_tokens',output_bound,'max_input_tokens',(reservation->>'max_input_tokens')::integer,
    'route',jsonb_build_object('policy_id',pol.id,'policy_name',pol.name,'chain_index',idx,'provider_instance_id',provider_row.id,
     'provider_code',provider_row.provider_code,'provider_display',provider_row.display_name,'model_catalog_id',model_row.id,'model_key',model_row.model_key,
     'endpoint',provider_row.endpoint,'auth_method',provider_row.auth_method,'custom_headers',provider_row.custom_headers,'api_version',provider_row.api_version,'vault_secret_id',provider_row.vault_secret_id),
    'vault',envelope);
  END LOOP;
 END LOOP;
 RETURN jsonb_build_object('error','route_unavailable');
END $function$

CREATE OR REPLACE FUNCTION public.record_public_ai_inference_usage(_request_id uuid, _tokens_in bigint, _tokens_out bigint, _upstream_status integer, _latency_ms integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET row_security TO 'on'
AS $function$
DECLARE
 r private.public_ai_inference_requests%ROWTYPE;
 reservation public.copilot_spend_reservations%ROWTYPE; meta jsonb; next_state text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Permission denied' USING ERRCODE='42501'; END IF;
 IF _upstream_status IS NULL OR (_upstream_status<>0 AND _upstream_status NOT BETWEEN 100 AND 599)
 OR _latency_ms IS NULL OR _latency_ms<0 OR (_tokens_in IS NOT NULL AND _tokens_in NOT BETWEEN 0 AND 2147483647)
 OR (_tokens_out IS NOT NULL AND _tokens_out NOT BETWEEN 0 AND 2147483647) THEN RAISE EXCEPTION 'Invalid usage' USING ERRCODE='22023'; END IF;
 -- Same lock order as every existing reservation/accounting writer.
 PERFORM pg_advisory_xact_lock(61000,1);
 SELECT * INTO r FROM private.public_ai_inference_requests WHERE id=_request_id FOR UPDATE;
 IF NOT FOUND THEN RETURN false; END IF;
 IF r.state<>'prepared' THEN
  RETURN r.tokens_in IS NOT DISTINCT FROM _tokens_in AND r.tokens_out IS NOT DISTINCT FROM _tokens_out AND r.upstream_status=_upstream_status;
 END IF;
 -- Settlement uses the dispatch subject even if it has since been revoked;
 -- revocation prevents future dispatch but cannot erase paid/unknown usage.
 SELECT * INTO reservation FROM public.copilot_spend_reservations WHERE id=r.id::text FOR UPDATE;
 IF NOT FOUND OR reservation.actor_id<>r.subject_user_id OR reservation.tenant_id<>r.tenant_id OR reservation.catalog_id<>r.model_catalog_id
 THEN RETURN false; END IF;
 IF _tokens_in IS NULL OR _tokens_out IS NULL OR (_tokens_in=0 AND _tokens_out=0) THEN next_state:='usage_unknown';
 ELSE next_state:='recorded'; END IF;
 meta:=jsonb_build_object('source','ai_inference_router.http','public_request_id',r.id,'token_id',r.token_id,'principal_kind','user_delegated',
  'policy_id',r.policy_id,'chain_index',r.chain_index,'provider_instance_id',r.provider_instance_id,'model_catalog_id',r.model_catalog_id,
  'latency_ms',_latency_ms,'upstream_status',_upstream_status,'accounting_state',next_state);
 UPDATE private.public_ai_inference_requests SET tokens_in=_tokens_in,tokens_out=_tokens_out,
  upstream_status=_upstream_status,latency_ms=_latency_ms,state=next_state,recorded_at=clock_timestamp() WHERE id=r.id;
 -- Unknown/error/cancellation retains the original DISPATCHED reservation and
 -- its full budget floor. No timeout release, fresh-price repricing or zero row.
 IF next_state='recorded' THEN
  PERFORM private.settle_public_ai_dispatch(r.id,_tokens_in::integer,_tokens_out::integer);
  SELECT * INTO reservation FROM public.copilot_spend_reservations WHERE id=r.id::text;
  UPDATE private.public_ai_inference_requests SET cost_usd=reservation.actual_micro_usd/1000000 WHERE id=r.id;
  IF reservation.actual_micro_usd>1000000 THEN
   INSERT INTO public.security_events(tenant_id,user_id,event_type,severity,context)
    VALUES(r.tenant_id,r.subject_user_id,'ai.high_cost_request','warning',jsonb_build_object('cost_usd',reservation.actual_micro_usd/1000000,'model',r.provider_code||'/'||r.model,'tokens_in',_tokens_in,'tokens_out',_tokens_out));
  END IF;
 END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(r.subject_user_id,r.tenant_id,'tenant','api.ai.inference.record','public_ai_inference_request',r.id::text,meta);
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION private.reserve_public_ai_dispatch(_token_id uuid, _attempt_id uuid, _provider_id uuid, _tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE
 actor uuid := (SELECT actor_user_id FROM private.qualified_user_delegated_api_token(_token_id,_tenant_id,'ai.inference')); stamp timestamptz := clock_timestamp();
 p public.platform_ai_settings%ROWTYPE; t public.tenant_ai_settings%ROWTYPE;
 b public.ai_budgets%ROWTYPE; l public.llm_providers%ROWTYPE;
 c public.ai_model_catalog%ROWTYPE; i public.ai_provider_instances%ROWTYPE;
 price public.ai_model_pricing%ROWTYPE; q public.ai_quotas%ROWTYPE;
 bound_t numeric; bound_c numeric; w record; total_t numeric; total_c numeric;
 cap_t numeric; cap_c numeric; pct numeric; input_bound integer;
BEGIN
 IF actor IS NULL OR _attempt_id IS NULL OR _provider_id IS NULL THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 PERFORM pg_advisory_xact_lock(61000,1);
 IF _tenant_id IS NULL THEN
   IF NOT coalesce(private.is_platform_admin(actor),false) AND NOT coalesce(private.is_platform_super_admin(actor),false)
     THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active) THEN
   RAISE EXCEPTION 'copilot.forbidden';
 END IF;
 IF EXISTS(SELECT 1 FROM public.copilot_spend_reservations WHERE id=_attempt_id::text) THEN
   RAISE EXCEPTION 'copilot.already_dispatched';
 END IF;
 SELECT * INTO p FROM public.platform_ai_settings WHERE id=true FOR SHARE;
 IF NOT FOUND OR p.ai_enabled IS DISTINCT FROM true OR p.allow_copilot_global IS DISTINCT FROM true OR p.default_autonomy_ceiling NOT IN ('suggest','assist','auto')
   OR p.default_autonomy_ceiling IS NULL THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
 IF _tenant_id IS NOT NULL THEN
   SELECT * INTO t FROM public.tenant_ai_settings WHERE tenant_id=_tenant_id FOR SHARE;
   IF NOT FOUND OR t.ai_enabled IS DISTINCT FROM true OR t.allow_copilot IS DISTINCT FROM true OR t.default_autonomy IS NULL
     OR t.default_autonomy NOT IN ('read_only','supervised','autonomous') THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
   SELECT * INTO b FROM public.ai_budgets WHERE tenant_id=_tenant_id FOR SHARE;
   IF FOUND AND (b.daily_max_tokens IS NULL OR b.daily_max_tokens<0 OR b.daily_max_cost_usd IS NULL
     OR b.daily_max_cost_usd<0 OR b.monthly_max_cost_usd IS NULL OR b.monthly_max_cost_usd<0
     OR b.hard_stop_at_pct IS NULL OR b.hard_stop_at_pct NOT BETWEEN 1 AND 200
     OR b.daily_max_cost_usd::text IN ('NaN','Infinity','-Infinity')
     OR b.monthly_max_cost_usd::text IN ('NaN','Infinity','-Infinity')) THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
   SELECT * INTO q FROM public.ai_quotas WHERE tenant_id=_tenant_id FOR SHARE;
 END IF;
 IF p.global_max_tokens_per_day IS NULL OR p.global_max_tokens_per_day<0
   OR p.global_max_cost_usd_per_day IS NULL OR p.global_max_cost_usd_per_day<0
   OR p.global_max_cost_usd_per_day::text IN ('NaN','Infinity','-Infinity')
   OR (_tenant_id IS NOT NULL AND (t.max_tokens_per_day IS NULL OR t.max_tokens_per_day<0)) THEN
   RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM public.ai_governance_kill_switches WHERE engaged
   AND (tenant_id IS NULL OR tenant_id=_tenant_id) AND scope IN ('global','copilot','copilot.chat')) THEN
   RAISE EXCEPTION 'copilot.kill_switch'; END IF;
 -- Actor + tenant sliding windows are from stored settings, never supplied caps.
 IF p.llm_rl_per_user_max IS NULL OR p.llm_rl_per_user_max<1
   OR p.llm_rl_per_user_window_seconds IS NULL OR p.llm_rl_per_user_window_seconds<1
   OR p.llm_rl_per_tenant_max IS NULL OR p.llm_rl_per_tenant_max<1
   OR p.llm_rl_per_tenant_window_seconds IS NULL OR p.llm_rl_per_tenant_window_seconds<1 THEN
   RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
 IF EXISTS(SELECT 1 FROM (VALUES
   (true,p.llm_rl_per_user_max,p.llm_rl_per_user_window_seconds),
   (false,p.llm_rl_per_tenant_max,p.llm_rl_per_tenant_window_seconds),
   (true,t.llm_rl_per_user_max,t.llm_rl_per_user_window_seconds),
   (false,t.llm_rl_per_tenant_max,t.llm_rl_per_tenant_window_seconds)
 ) caps(own,lim,seconds) WHERE (lim IS NOT NULL OR seconds IS NOT NULL) AND
   (coalesce(lim,CASE WHEN own THEN p.llm_rl_per_user_max ELSE p.llm_rl_per_tenant_max END)<1
    OR coalesce(seconds,CASE WHEN own THEN p.llm_rl_per_user_window_seconds ELSE p.llm_rl_per_tenant_window_seconds END)<1
    OR (SELECT count(*) FROM public.copilot_spend_reservations r
      WHERE r.created_at>=stamp-make_interval(secs=>coalesce(seconds,CASE WHEN own THEN p.llm_rl_per_user_window_seconds ELSE p.llm_rl_per_tenant_window_seconds END))
      AND (CASE WHEN own THEN r.actor_id=actor ELSE r.tenant_id IS NOT DISTINCT FROM _tenant_id END))
      >=coalesce(lim,CASE WHEN own THEN p.llm_rl_per_user_max ELSE p.llm_rl_per_tenant_max END))) THEN
   RAISE EXCEPTION 'copilot.rate_limit'; END IF;
 SELECT * INTO l FROM public.llm_providers WHERE id=_provider_id FOR SHARE;
 IF NOT FOUND OR l.is_active IS DISTINCT FROM true OR l.tenant_id IS DISTINCT FROM _tenant_id
   OR l.scope::text IS DISTINCT FROM (CASE WHEN _tenant_id IS NULL THEN 'platform' ELSE 'tenant' END)
   OR l.provider_instance_id IS NULL OR l.model_catalog_id IS NULL THEN RAISE EXCEPTION 'copilot.binding_required'; END IF;
 SELECT * INTO c FROM public.ai_model_catalog WHERE id=l.model_catalog_id FOR SHARE;
 IF NOT FOUND OR c.provider_instance_id<>l.provider_instance_id OR c.model_key<>l.model
   OR c.approval_status IS DISTINCT FROM 'approved' OR c.availability_status IS NULL OR c.availability_status NOT IN ('available','limited')
   OR c.max_input_tokens IS NULL OR c.max_input_tokens<=0 OR c.max_output_tokens IS NULL OR c.max_output_tokens<=0
   OR c.context_window IS NULL OR c.context_window<=c.max_output_tokens THEN
   RAISE EXCEPTION 'copilot.bounds_unavailable'; END IF;
 SELECT * INTO i FROM public.ai_provider_instances WHERE id=l.provider_instance_id FOR SHARE;
 IF NOT FOUND OR i.tenant_id IS DISTINCT FROM _tenant_id OR i.status IS DISTINCT FROM 'active'
   OR NOT EXISTS(SELECT 1 FROM public.ai_provider_registry WHERE code=i.provider_code AND enabled) THEN
   RAISE EXCEPTION 'copilot.binding_required'; END IF;
 SELECT * INTO price FROM public.ai_model_pricing WHERE provider_code=i.provider_code AND model_key=c.model_key
   AND active AND currency='USD' AND effective_at<=stamp AND (expires_at IS NULL OR expires_at>stamp)
   ORDER BY effective_at DESC,id LIMIT 1 FOR SHARE;
 IF NOT FOUND OR price.input_usd_per_1m IS NULL OR price.output_usd_per_1m IS NULL
   OR price.input_usd_per_1m<=0 OR price.output_usd_per_1m<=0
   OR price.input_usd_per_1m::text IN ('NaN','Infinity','-Infinity')
   OR price.output_usd_per_1m::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'copilot.pricing_unavailable'; END IF;
 input_bound:=least(c.max_input_tokens,c.context_window-c.max_output_tokens);
 bound_t:=input_bound::numeric+c.max_output_tokens;
 bound_c:=ceil(input_bound::numeric*price.input_usd_per_1m+c.max_output_tokens::numeric*price.output_usd_per_1m);
 IF EXISTS(SELECT 1 FROM public.ai_usage_events WHERE
   (created_at>=date_trunc('month',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' OR created_at IS NULL OR NOT isfinite(created_at))
   AND (created_at IS NULL OR NOT isfinite(created_at) OR tokens_in IS NULL OR tokens_out IS NULL OR tokens_in<0 OR tokens_out<0
     OR cost_usd IS NULL OR cost_usd<0 OR cost_usd::text IN ('NaN','Infinity','-Infinity')
     OR (tokens_in::numeric+tokens_out>0 AND cost_usd=0))) THEN RAISE EXCEPTION 'copilot.pricing_unavailable'; END IF;
 pct:=coalesce(b.hard_stop_at_pct,100)/100.0;
 FOR w IN SELECT 1 n,NULL::uuid tenant,date_trunc('day',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' since
   UNION ALL SELECT 2,_tenant_id,date_trunc('day',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' WHERE _tenant_id IS NOT NULL
   UNION ALL SELECT 3,_tenant_id,date_trunc('month',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' WHERE _tenant_id IS NOT NULL
 LOOP
   SELECT coalesce(sum(tokens_in::numeric+tokens_out),0),ceil(coalesce(sum(cost_usd),0)*1000000) INTO total_t,total_c
     FROM public.ai_usage_events u WHERE u.created_at>=w.since AND (w.n=1 OR u.tenant_id=w.tenant)
     AND NOT EXISTS(SELECT 1 FROM public.copilot_spend_reservations r WHERE r.id=u.meta->>'copilot_reservation_id' AND r.llm_provider_id IS NOT NULL);
   SELECT total_t+coalesce(sum(coalesce(accounted_tokens,bound_tokens)),0),total_c+coalesce(sum(coalesce(accounted_micro_usd,bound_micro_usd)),0)
     INTO total_t,total_c FROM public.copilot_spend_reservations r WHERE r.state<>'released'
       AND (r.state IN ('reserved','dispatched') OR r.created_at>=w.since) AND (w.n=1 OR r.tenant_id=w.tenant);
   cap_t:=CASE w.n WHEN 1 THEN p.global_max_tokens_per_day WHEN 2 THEN least(t.max_tokens_per_day,b.daily_max_tokens,q.daily_token_limit) ELSE q.monthly_token_limit END;
   cap_c:=floor(CASE w.n WHEN 1 THEN p.global_max_cost_usd_per_day WHEN 2 THEN coalesce(b.daily_max_cost_usd,50)*pct
     ELSE least(coalesce(b.monthly_max_cost_usd,1000)*pct,q.budget_limit_usd) END*1000000);
   IF (cap_t IS NOT NULL AND (cap_t<0 OR total_t>=cap_t OR total_t+bound_t>cap_t))
     OR cap_c IS NULL OR cap_c<0 OR cap_c::text IN ('NaN','Infinity','-Infinity') OR total_c>=cap_c OR total_c+bound_c>cap_c THEN
     RAISE EXCEPTION 'copilot.budget_reached'; END IF;
 END LOOP;
 -- No period/counter semantics are established for these optional dimensions.
 -- Do not silently treat them as per-request caps or unknown usage as zero.
 IF q.input_token_limit IS NOT NULL OR q.output_token_limit IS NOT NULL
   OR q.cached_token_limit IS NOT NULL OR q.api_request_limit IS NOT NULL THEN
   RAISE EXCEPTION 'copilot.quota_dimension_unavailable'; END IF;
 INSERT INTO public.copilot_spend_reservations(id,actor_id,tenant_id,pricing_basis,bound_tokens,bound_micro_usd,state,
   llm_provider_id,catalog_id,price_id,model_key,input_rate,output_rate,max_input_tokens,max_output_tokens,created_at)
 VALUES(_attempt_id::text,actor,_tenant_id,price.id::text,bound_t,bound_c,'dispatched',l.id,c.id,price.id,c.model_key,
   price.input_usd_per_1m,price.output_usd_per_1m,input_bound,c.max_output_tokens,stamp);
 RETURN jsonb_build_object('reservation_id',_attempt_id::text,'max_input_tokens',input_bound,'max_output_tokens',c.max_output_tokens,
   'provider',l.provider,'model_key',l.model,'base_url',l.base_url,'key_secret_name',l.key_secret_name);
END $function$

CREATE OR REPLACE FUNCTION private.exception_dashboard_rate_limit_hit(_tenant_id uuid)
 RETURNS TABLE(allowed boolean, current_count integer, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
BEGIN
  IF actor_id IS NULL THEN
    RAISE EXCEPTION 'forbidden: authenticated identity required' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.tenant_members membership
    WHERE membership.tenant_id = _tenant_id
      AND membership.user_id = actor_id
      AND membership.active
  ) THEN
    RAISE EXCEPTION 'forbidden: active tenant membership required' USING ERRCODE = '42501';
  END IF;
  IF NOT (
    public.is_platform_admin(actor_id)
    OR public.user_has_permission(actor_id, _tenant_id, 'break.read', NULL)
  ) THEN
    RAISE EXCEPTION 'forbidden: break.read permission required' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT limiter.allowed, limiter.current_count, limiter.retry_after_seconds
  FROM public.rate_limit_hit(
    'exception.dashboard.db:' || _tenant_id::text || ':' || actor_id::text,
    60,
    60
  ) limiter;
END;
$function$

CREATE OR REPLACE FUNCTION public.dpw_claim_attachment_purge(_file_id uuid, _job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a public.data_prep_attachment_retention%ROWTYPE; claim private.dpw_attachment_purge_claims%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' OR _job_id IS NULL
 OR private.dpw_retention_attest() IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.closed_retention_processor_required'; END IF;
 SELECT * INTO a FROM public.data_prep_attachment_retention WHERE file_id=_file_id FOR UPDATE;
 IF NOT FOUND OR a.expires_at>clock_timestamp() OR private.dpw_attachment_has_hold(_file_id) OR private.dpw_attachment_has_canonical_reference(_file_id)
 OR EXISTS(SELECT 1 FROM public.data_prep_attachment_tombstones WHERE file_id=_file_id) THEN RAISE EXCEPTION 'dpw.attachment_not_purge_eligible'; END IF;
 SELECT * INTO claim FROM private.dpw_attachment_purge_claims WHERE file_id=_file_id;
 IF FOUND AND claim.job_id<>_job_id THEN RAISE EXCEPTION 'dpw.purge_unknown_previous_outcome_requires_readback'; END IF;
 INSERT INTO private.dpw_attachment_purge_claims(file_id,job_id,expires_at,state) VALUES(_file_id,_job_id,clock_timestamp()+interval '5 minutes','claimed') ON CONFLICT(file_id) DO NOTHING;
 RETURN jsonb_build_object('file_id',a.file_id,'bucket_id',a.bucket_id,'original_path',a.original_path,'original_file_bytes_sha256',a.original_file_bytes_sha256,
 'job_id',_job_id,'expires_at',a.expires_at,'main_must_recheck_legal_hold_immediately_before_object_delete',true);
END $function$

CREATE OR REPLACE FUNCTION public.compute_recon_risk(p_recon_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_score numeric; v_tier text;
BEGIN
  SELECT LEAST(100, COALESCE(SUM(weight * value), 0))
    INTO v_score FROM public.recon_risk_factors WHERE recon_id = p_recon_id;
  v_tier := CASE WHEN v_score >= 75 THEN 'critical' WHEN v_score >= 50 THEN 'high' WHEN v_score >= 25 THEN 'medium' ELSE 'low' END;
  UPDATE public.recon_schedules
     SET risk_score = v_score, risk_tier = v_tier, last_risk_eval_at = now()
   WHERE definition_id = p_recon_id;
  RETURN v_score;
END;
$function$

CREATE OR REPLACE FUNCTION private.dpw_run_readback_metadata(_run uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r public.data_prep_delivery_runs%ROWTYPE; b public.data_prep_delivery_batches%ROWTYPE; p public.data_prep_pipelines%ROWTYPE;
 eligible boolean; hash_valid boolean; human_approved boolean;
BEGIN
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run;
 SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=r.batch_id;
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=r.pipeline_id;
 hash_valid:=r.finished_at IS NOT NULL AND private.dpw_hash(r.result) IS NOT DISTINCT FROM r.result_sha256;
 eligible:=hash_valid AND private.dpw_run_payload_available(r.id) AND b.mode='prepare' AND r.state IN('success','warn')
 AND (r.result->>'publication_eligible')::boolean IS TRUE AND p.status='approved' AND p.lifecycle_state='production' AND p.enabled
 AND p.version=r.pipeline_version AND private.dpw_snapshot(p.id) IS NOT DISTINCT FROM (b.configuration_snapshot-ARRAY['quality_gate','exclusion_approval_id','approved_exclusions','exclusion_source_run_id','correction_source_run_id','correction_source_files','correction_manifest_origin'])
 AND private.data_prep_pipeline_scope_allows(_actor,r.tenant_id,p.id,'run') IS TRUE
 AND private.dpw_source_allows(_actor,r.tenant_id,p.output_data_source_id,'ingest') IS TRUE
 AND private.dpw_source_allows(_actor,r.tenant_id,p.output_data_source_id,'edit') IS TRUE
 AND (public.is_platform_admin(_actor) OR EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=_actor AND tenant_id=r.tenant_id AND active AND role::text IN('tenant_admin','tenant_analyst')));
 human_approved:=EXISTS(SELECT 1 FROM public.data_prep_release_requests q JOIN public.data_prep_release_decisions d ON d.request_id=q.id
 WHERE q.run_id=r.id AND q.result_sha256=r.result_sha256 AND q.pipeline_version=r.pipeline_version AND d.decision='approved');
 RETURN jsonb_build_object('publication_eligible',coalesce(eligible,false),'production_publishable',coalesce(eligible,false) AND human_approved,
 'human_release_approved',human_approved,'result_sha256',r.result_sha256,'result_hash_valid',coalesce(hash_valid,false),'snapshot_sha256',r.snapshot_sha256,
 'dq_execution',CASE WHEN r.finished_at IS NULL THEN 'pending' ELSE coalesce(r.result->>'dq_execution','executed') END,
 'rows_in_observed',(SELECT coalesce(sum(row_count),0) FROM public.data_prep_run_inputs WHERE run_id=r.id),
 'processed_row_count',CASE WHEN r.result->>'dq_execution'='unavailable_not_fabricated' OR r.finished_at IS NULL THEN NULL
 ELSE jsonb_array_length(coalesce(r.result->'acceptedRows','[]'::jsonb)) END);
END $function$

CREATE OR REPLACE FUNCTION public.mkt_domain_scaffold(p_domain text, p_spec jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  base jsonb;
  dom jsonb;
BEGIN
  SELECT preset INTO base FROM public.mkt_domain_presets WHERE domain_key='default';
  SELECT preset INTO dom FROM public.mkt_domain_presets WHERE domain_key = p_domain;
  IF base IS NULL THEN base := '{}'::jsonb; END IF;
  IF dom IS NOT NULL THEN base := public.jsonb_deep_merge(dom, base); END IF;
  RETURN public.jsonb_deep_merge(COALESCE(p_spec,'{}'::jsonb), base);
END $function$

CREATE OR REPLACE FUNCTION public.failed_login_begin(_id uuid, _binding text, _stage text, _email text DEFAULT NULL::text, _user_id uuid DEFAULT NULL::uuid, _request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'public', 'pg_temp'
AS $function$
DECLARE a private.failed_login_attempts; actor uuid; recipient text;
BEGIN
  IF _binding IS NULL OR _binding !~ '^[0-9a-f]{64}$' OR _stage NOT IN ('password','mfa','policy') OR _stage IS NULL THEN RAISE EXCEPTION 'Invalid attempt' USING ERRCODE='22023'; END IF;
  IF _stage='password' THEN
    SELECT u.id,u.email INTO actor,recipient FROM auth.users u WHERE lower(u.email)=lower(trim(_email)) AND u.email_confirmed_at IS NOT NULL AND u.deleted_at IS NULL AND NOT coalesce(u.is_anonymous,false) LIMIT 1;
  ELSE
    SELECT u.id,u.email INTO actor,recipient FROM auth.users u WHERE u.id=_user_id AND u.email_confirmed_at IS NOT NULL AND u.deleted_at IS NULL AND NOT coalesce(u.is_anonymous,false);
  END IF;
  INSERT INTO private.failed_login_attempts(id,request_id,binding,stage,user_id,recipient_email) VALUES (_id,coalesce(_request_id,gen_random_uuid()),_binding,_stage,actor,recipient) ON CONFLICT(id) DO NOTHING;
  IF FOUND THEN RETURN jsonb_build_object('acquired',true,'outcome','pending','requestId',(SELECT request_id FROM private.failed_login_attempts WHERE id=_id)); END IF;
  SELECT * INTO a FROM private.failed_login_attempts WHERE id=_id FOR UPDATE;
  IF a.binding<>_binding OR a.stage<>_stage THEN RAISE EXCEPTION 'Attempt conflict' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('acquired',false,'outcome',a.outcome,'requestId',a.request_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.failed_login_finish(_id uuid, _binding text, _outcome text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'public', 'pg_temp'
AS $function$
DECLARE a private.failed_login_attempts; q bigint;
BEGIN
  IF _outcome NOT IN ('success','invalid_credentials','mfa_invalid','mfa_expired','account_locked','rate_limited','policy_blocked','provider_unavailable','verification_failed') OR _outcome IS NULL THEN RAISE EXCEPTION 'Invalid outcome' USING ERRCODE='22023'; END IF;
  SELECT * INTO a FROM private.failed_login_attempts WHERE id=_id FOR UPDATE;
  IF NOT FOUND OR a.binding<>_binding THEN RAISE EXCEPTION 'Attempt conflict' USING ERRCODE='22023'; END IF;
  IF (_outcome='invalid_credentials' AND a.stage<>'password') OR (_outcome IN ('mfa_invalid','mfa_expired') AND a.stage<>'mfa') OR (_outcome='policy_blocked' AND a.stage<>'policy') THEN RAISE EXCEPTION 'Outcome stage conflict' USING ERRCODE='22023'; END IF;
  IF a.outcome<>'pending' THEN
    IF a.outcome<>_outcome THEN RAISE EXCEPTION 'Outcome conflict' USING ERRCODE='22023'; END IF;
    RETURN true;
  END IF;
  UPDATE private.failed_login_attempts SET outcome=_outcome,finished_at=clock_timestamp(),updated_at=clock_timestamp() WHERE id=_id;
  IF _outcome='success' THEN RETURN true; END IF;
  -- Canonical trusted event; browser security-events do not feed this pipeline.
  INSERT INTO public.security_events(user_id,event_type,severity,context) VALUES (a.user_id,'auth.failed_login.verified','warning',jsonb_build_object('attempt_id',_id,'request_id',a.request_id,'stage',a.stage,'outcome',_outcome,'source','server_authentication'));
  IF a.user_id IS NULL OR a.recipient_email IS NULL THEN
    UPDATE private.failed_login_attempts SET delivery_state='no_verified_recipient' WHERE id=_id;
    INSERT INTO private.failed_login_delivery_audit(attempt_id,state) VALUES(_id,'no_verified_recipient');
    RETURN true;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=a.user_id AND u.email=a.recipient_email AND u.email_confirmed_at IS NOT NULL AND u.deleted_at IS NULL AND NOT coalesce(u.is_anonymous,false)) THEN
    UPDATE private.failed_login_attempts SET delivery_state='recipient_changed',diagnostic_code='recipient_changed' WHERE id=_id;
    INSERT INTO private.failed_login_delivery_audit(attempt_id,state,diagnostic_code) VALUES(_id,'recipient_changed','recipient_changed');
    RETURN true;
  END IF;
  UPDATE private.failed_login_attempts SET delivery_state='recorded' WHERE id=_id;
  INSERT INTO private.failed_login_delivery_audit(attempt_id,state) VALUES(_id,'recorded');
  BEGIN
    q:=public.enqueue_email('transactional_emails',jsonb_build_object('template','auth.failed_login.verified','attempt_id',_id));
    UPDATE private.failed_login_attempts SET delivery_state='queued',queue_message_id=q WHERE id=_id;
    INSERT INTO private.failed_login_delivery_audit(attempt_id,state) VALUES(_id,'queued');
  EXCEPTION WHEN OTHERS THEN
    UPDATE private.failed_login_attempts SET diagnostic_code='queue_unavailable' WHERE id=_id;
    INSERT INTO private.failed_login_delivery_audit(attempt_id,state,diagnostic_code) VALUES(_id,'recorded','queue_unavailable');
  END;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.failed_login_requeue_recorded()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'public', 'pg_temp'
AS $function$
DECLARE a private.failed_login_attempts; q bigint; count_queued integer:=0;
BEGIN
  FOR a IN SELECT * FROM private.failed_login_attempts WHERE delivery_state='recorded' ORDER BY created_at LIMIT 20 FOR UPDATE SKIP LOCKED LOOP
    BEGIN
      q:=public.enqueue_email('transactional_emails',jsonb_build_object('template','auth.failed_login.verified','attempt_id',a.id));
      UPDATE private.failed_login_attempts SET delivery_state='queued',queue_message_id=q,diagnostic_code=NULL,updated_at=clock_timestamp() WHERE id=a.id;
      INSERT INTO private.failed_login_delivery_audit(attempt_id,state) VALUES(a.id,'queued'); count_queued:=count_queued+1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE private.failed_login_attempts SET diagnostic_code='queue_unavailable',updated_at=clock_timestamp() WHERE id=a.id;
    END;
  END LOOP;
  RETURN count_queued;
END;
$function$

CREATE OR REPLACE FUNCTION public.failed_login_claim(_id uuid, _queue_message_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'public', 'pg_temp'
AS $function$
DECLARE a private.failed_login_attempts; lease uuid;
BEGIN
  SELECT * INTO a FROM private.failed_login_attempts WHERE id=_id FOR UPDATE;
  IF NOT FOUND OR a.queue_message_id IS DISTINCT FROM _queue_message_id THEN RETURN jsonb_build_object('send',false,'state','unattributed'); END IF;
  IF a.delivery_state IN ('provider_accepted','delivered','bounced') THEN PERFORM public.delete_email('transactional_emails',_queue_message_id); RETURN jsonb_build_object('send',false,'state',a.delivery_state); END IF;
  IF a.delivery_state='sending' AND a.dispatch_started_at<clock_timestamp()-interval '5 minutes' THEN
    UPDATE private.failed_login_attempts SET delivery_state='uncertain',diagnostic_code='dispatch_interrupted',updated_at=clock_timestamp() WHERE id=_id;
    INSERT INTO private.failed_login_delivery_audit(attempt_id,state,diagnostic_code) VALUES(_id,'uncertain','dispatch_interrupted');
    RETURN jsonb_build_object('send',false,'state','uncertain');
  END IF;
  IF a.delivery_state NOT IN ('queued','retry') THEN RETURN jsonb_build_object('send',false,'state',a.delivery_state); END IF;
  IF NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=a.user_id AND u.email=a.recipient_email AND u.email_confirmed_at IS NOT NULL AND u.deleted_at IS NULL AND NOT coalesce(u.is_anonymous,false)) THEN
    UPDATE private.failed_login_attempts SET delivery_state='recipient_changed',diagnostic_code='recipient_changed',updated_at=clock_timestamp() WHERE id=_id;
    INSERT INTO private.failed_login_delivery_audit(attempt_id,state,diagnostic_code) VALUES(_id,'recipient_changed','recipient_changed');
    RETURN jsonb_build_object('send',false,'state','recipient_changed');
  END IF;
  lease:=gen_random_uuid();
  UPDATE private.failed_login_attempts SET delivery_state='sending',lease_id=lease,dispatch_started_at=clock_timestamp(),dispatch_count=dispatch_count+1,updated_at=clock_timestamp() WHERE id=_id;
  INSERT INTO private.failed_login_delivery_audit(attempt_id,state) VALUES(_id,'sending');
  RETURN jsonb_build_object('send',true,'lease_id',lease,'to',a.recipient_email,'occurred_at',a.created_at,'outcome',a.outcome,'attempt_id',a.id,'request_id',a.request_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.failed_login_settle(_id uuid, _lease_id uuid, _state text, _provider_message_id text DEFAULT NULL::text, _diagnostic_code text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'public', 'pg_temp'
AS $function$
DECLARE a private.failed_login_attempts; final_state text;
BEGIN
  IF _state NOT IN ('provider_accepted','retry','uncertain') OR _state IS NULL OR (_provider_message_id IS NOT NULL AND (length(_provider_message_id)>200 OR _provider_message_id !~ '^[A-Za-z0-9_.:-]+$' OR _provider_message_id ~ '^(request:)?[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$' OR _provider_message_id ~* '^(request:)?(sb_secret_|sb_publishable_|sbp_|Zoho-enczapikey)')) OR (_diagnostic_code IS NOT NULL AND _diagnostic_code NOT IN ('provider_rejected','provider_rate_limited','provider_timeout','provider_response_unknown','provider_unavailable')) THEN RAISE EXCEPTION 'Invalid delivery receipt' USING ERRCODE='22023'; END IF;
  IF _state='provider_accepted' AND _provider_message_id IS NULL THEN RAISE EXCEPTION 'Acceptance receipt required' USING ERRCODE='22023'; END IF;
  SELECT * INTO a FROM private.failed_login_attempts WHERE id=_id FOR UPDATE;
  IF NOT FOUND OR a.lease_id IS DISTINCT FROM _lease_id OR _lease_id IS NULL THEN RETURN false; END IF;
  IF (a.delivery_state=_state OR (_state='provider_accepted' AND a.delivery_state IN ('delivered','bounced'))) AND a.provider_message_id IS NOT DISTINCT FROM _provider_message_id THEN RETURN true; END IF;
  IF a.delivery_state NOT IN ('sending','uncertain') THEN RETURN false; END IF;
  -- An interrupted/ambiguous HTTP send is never automatically replayed.
  IF a.delivery_state='uncertain' AND _state='retry' THEN RETURN false; END IF;
  final_state:=CASE WHEN _state='retry' AND a.dispatch_count>=5 THEN 'dead_letter' ELSE _state END;
  UPDATE private.failed_login_attempts SET delivery_state=final_state,provider_message_id=_provider_message_id,diagnostic_code=_diagnostic_code,updated_at=clock_timestamp() WHERE id=_id;
  INSERT INTO private.failed_login_delivery_audit(attempt_id,state,diagnostic_code,provider_message_id) VALUES(_id,final_state,_diagnostic_code,_provider_message_id);
  IF _state='provider_accepted' THEN
    INSERT INTO public.email_send_log(message_id,template_name,recipient_email,status,metadata) VALUES(_provider_message_id,'auth.failed_login.verified',a.recipient_email,'sent',jsonb_build_object('attempt_id',_id,'queue_message_id',a.queue_message_id,'delivery_state','provider_accepted'));
    PERFORM public.delete_email('transactional_emails',a.queue_message_id);
  ELSIF final_state='dead_letter' THEN
    PERFORM public.move_to_dlq('transactional_emails','transactional_emails_dlq',a.queue_message_id,jsonb_build_object('template','auth.failed_login.verified','attempt_id',_id));
  END IF;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_recon_run_evidence_pack(_run_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_run RECORD;
  v_def RECORD;
  v_payload JSONB;
  v_exceptions JSONB;
  v_matches JSONB;
  v_lineage JSONB;
  v_prev BYTEA;
  v_hash BYTEA;
  v_id UUID;
  v_version INTEGER;
  v_audit_id BIGINT;
  v_exc_count INTEGER;
  v_match_count INTEGER;
  v_close_count INTEGER;
BEGIN
  SELECT * INTO v_run FROM public.recon_runs WHERE id = _run_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'recon_run % not found', _run_id; END IF;

  SELECT * INTO v_def FROM public.recon_definitions WHERE id = v_run.definition_id;

  -- Matches summary (capped detail; full export available via separate endpoint)
  SELECT
    COUNT(*),
    COALESCE(jsonb_agg(jsonb_build_object(
      'id', id, 'rule_id', rule_id, 'cardinality', cardinality,
      'score', score, 'confidence', confidence, 'match_type', match_type
    ) ORDER BY created_at) FILTER (WHERE rn <= 500), '[]'::jsonb)
  INTO v_match_count, v_matches
  FROM (
    SELECT *, ROW_NUMBER() OVER (ORDER BY created_at) AS rn
    FROM public.recon_matches WHERE run_id = _run_id
  ) m;

  -- Exceptions with closure rationale + state transitions
  SELECT
    COUNT(*),
    COUNT(*) FILTER (WHERE status IN ('closed','resolved','written_off')),
    COALESCE(jsonb_agg(jsonb_build_object(
      'id', e.id,
      'side', e.side,
      'reason', e.reason,
      'severity', e.severity,
      'status', e.status,
      'lifecycle_state', e.lifecycle_state,
      'root_cause', e.root_cause,
      'close_reason', e.close_reason,
      'resolution_note', e.resolution_note,
      'resolved_by', e.resolved_by,
      'resolved_at', e.resolved_at,
      'write_off_amount', e.write_off_amount,
      'write_off_currency', e.write_off_currency,
      'write_off_gl_account', e.write_off_gl_account,
      'write_off_approved_by', e.write_off_approved_by,
      'transitions', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'from', t.from_state, 'to', t.to_state, 'type', t.transition_type,
          'reason', t.reason, 'actor', t.actor_user_id, 'at', t.occurred_at
        ) ORDER BY t.occurred_at)
        FROM public.recon_exception_transitions t WHERE t.exception_id = e.id
      ), '[]'::jsonb)
    ) ORDER BY e.created_at), '[]'::jsonb)
  INTO v_exc_count, v_close_count, v_exceptions
  FROM public.recon_exceptions e WHERE e.run_id = _run_id;

  -- Lineage edges touching this run
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'source_kind', source_kind, 'source_ref', source_ref, 'source_label', source_label,
    'target_kind', target_kind, 'target_ref', target_ref, 'target_label', target_label,
    'transform', transform, 'evidence_hash', evidence_hash
  )), '[]'::jsonb)
  INTO v_lineage
  FROM public.data_lineage_edges
  WHERE tenant_id = v_run.tenant_id
    AND (source_ref = _run_id::text OR target_ref = _run_id::text);

  -- Next version number
  SELECT COALESCE(MAX(pack_version), 0) + 1 INTO v_version
  FROM public.recon_run_evidence_packs WHERE run_id = _run_id;

  v_payload := jsonb_build_object(
    'pack_kind', 'recon_run_evidence',
    'pack_spec', '1.0',
    'generated_at', now(),
    'run', jsonb_build_object(
      'id', v_run.id, 'tenant_id', v_run.tenant_id, 'status', v_run.status,
      'started_at', v_run.started_at, 'completed_at', v_run.completed_at,
      'matched_count', v_run.matched_count, 'exception_count', v_run.exception_count,
      'total_rows', v_run.total_rows, 'stats', v_run.stats,
      'run_by', v_run.run_by, 'run_uid', v_run.run_uid
    ),
    'definition', CASE WHEN v_def.id IS NULL THEN NULL ELSE jsonb_build_object(
      'id', v_def.id, 'name', v_def.name, 'recon_type', v_def.recon_type,
      'version', COALESCE((SELECT MAX(version_number) FROM public.recon_definition_versions WHERE recon_definition_id = v_def.id), 1),
      'rules_hash', md5(coalesce(v_def.rules::text,'')),
      'sides', v_def.sides,
      'environment', v_def.environment
    ) END,
    'matches', jsonb_build_object('total', v_match_count, 'sample', v_matches),
    'exceptions', jsonb_build_object(
      'total', v_exc_count,
      'closed', v_close_count,
      'items', v_exceptions
    ),
    'lineage', v_lineage
  );

  SELECT row_hash INTO v_prev
  FROM public.recon_run_evidence_packs
  WHERE tenant_id = v_run.tenant_id
  ORDER BY generated_at DESC LIMIT 1;

  v_hash := digest(coalesce(encode(v_prev,'hex'),'') || v_payload::text, 'sha256');

  -- Append to audit_log (hash-chain anchor)
  INSERT INTO public.audit_log (
    tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    v_run.tenant_id, 'tenant', 'recon.evidence_pack.generated',
    'recon_run', _run_id::text,
    jsonb_build_object('pack_version', v_version, 'row_hash', encode(v_hash,'hex'))
  ) RETURNING id INTO v_audit_id;

  INSERT INTO public.recon_run_evidence_packs (
    tenant_id, run_id, definition_id, definition_version, pack_version,
    payload, prev_hash, row_hash, audit_anchor_id,
    exception_count, match_count, closure_count
  ) VALUES (
    v_run.tenant_id, _run_id, v_run.definition_id,
    (v_payload #>> '{definition,version}')::int,
    v_version, v_payload, v_prev, v_hash, v_audit_id,
    v_exc_count, v_match_count, v_close_count
  ) RETURNING id INTO v_id;

  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.failed_login_delivery_receipt(_id uuid, _provider_message_id text, _state text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'private', 'public', 'pg_temp'
AS $function$
DECLARE a private.failed_login_attempts;
BEGIN
  IF _state NOT IN ('delivered','bounced') OR _state IS NULL THEN RAISE EXCEPTION 'Invalid delivery state' USING ERRCODE='22023'; END IF;
  SELECT * INTO a FROM private.failed_login_attempts WHERE id=_id FOR UPDATE;
  IF NOT FOUND OR a.provider_message_id IS DISTINCT FROM _provider_message_id OR _provider_message_id IS NULL OR a.delivery_state NOT IN ('provider_accepted','delivered','bounced') THEN RETURN false; END IF;
  IF a.delivery_state=_state THEN RETURN true; END IF;
  IF a.delivery_state IN ('delivered','bounced') THEN RETURN false; END IF;
  UPDATE private.failed_login_attempts SET delivery_state=_state,updated_at=clock_timestamp() WHERE id=_id;
  INSERT INTO private.failed_login_delivery_audit(attempt_id,state,provider_message_id) VALUES(_id,_state,_provider_message_id);
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.release_ai_kill_switch(p_tenant uuid, p_scope text)
 RETURNS ai_governance_kill_switches
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.ai_governance_kill_switches;
BEGIN
  IF NOT (has_tenant_role(auth.uid(), p_tenant, 'tenant_admin') OR is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  UPDATE public.ai_governance_kill_switches
    SET engaged = false, released_by = auth.uid(), released_at = now(), updated_at = now()
    WHERE tenant_id = p_tenant AND scope = p_scope
    RETURNING * INTO r;
  INSERT INTO public.audit_log(tenant_id, actor_user_id, scope, action, resource_type, resource_id, context)
  VALUES (p_tenant, auth.uid(), 'tenant', 'ai.kill_switch.released', 'ai_governance_kill_switches', r.id::text,
          jsonb_build_object('scope', p_scope));
  RETURN r;
END $function$

CREATE OR REPLACE FUNCTION private.dpw_attachment_register()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE policy jsonb; days integer; input public.data_prep_delivery_files%ROWTYPE;
BEGIN
 IF NEW.finished_at IS NULL OR OLD.finished_at IS NOT NULL THEN RETURN NEW; END IF;
 policy:=private.dpw_effective_attachment_policy(NEW.tenant_id);days:=(policy->>'period_days')::integer;
 IF days IS NULL OR days<1 OR policy->>'source' NOT IN('platform','tenant') OR policy->>'policy_id' IS NULL OR policy->>'version' IS NULL THEN RAISE EXCEPTION 'dpw.retention_policy_unavailable'; END IF;
 FOR input IN SELECT f.* FROM public.data_prep_delivery_files f JOIN public.data_prep_run_inputs i ON i.file_id=f.id WHERE i.run_id=NEW.id LOOP
 INSERT INTO public.data_prep_attachment_retention(file_id,tenant_id,pipeline_id,bucket_id,original_path,original_file_bytes_sha256,original_size_bytes,run_id,attached_at,expires_at,
 policy_id,policy_version,period_days,policy_source,notice_30_at,notice_10_at,notice)
 VALUES(input.id,input.tenant_id,input.pipeline_id,'data-prep-inputs',input.original_path,input.content_sha256,(input.descriptor->>'size_bytes')::bigint,
 NEW.id,NEW.finished_at,NEW.finished_at+days*interval '1 day',(policy->>'policy_id')::uuid,policy->>'version',days,policy->>'source',
 NEW.finished_at+greatest(days-30,0)*interval '1 day',NEW.finished_at+greatest(days-10,0)*interval '1 day',
 'Data Prep attachment data is available for '||days::text||' days under its snapshotted policy. Run, configuration, count, hash and audit metadata are retained. Legal holds stop purge.');
 END LOOP;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_guard_recon_definition_retirement()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE authorized_request uuid;
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.status<>'draft' OR OLD.retired_at IS NOT NULL
       OR EXISTS (SELECT 1 FROM public.recon_runs r WHERE r.definition_id=OLD.id) THEN
      RAISE EXCEPTION 'reconciliation with history or non-draft status cannot be physically deleted'
        USING ERRCODE='23514';
    END IF;
    RETURN OLD;
  END IF;

  IF OLD.retired_at IS NOT NULL AND
     (NEW.status IS DISTINCT FROM OLD.status OR NEW.retired_at IS DISTINCT FROM OLD.retired_at
      OR NEW.retirement_request_id IS DISTINCT FROM OLD.retirement_request_id) THEN
    RAISE EXCEPTION 'retired reconciliation state is immutable' USING ERRCODE='23514';
  END IF;

  IF NEW.retired_at IS DISTINCT FROM OLD.retired_at
     OR NEW.retirement_request_id IS DISTINCT FROM OLD.retirement_request_id
     OR NEW.status IS DISTINCT FROM OLD.status THEN
    authorized_request := nullif(current_setting('fvi.recon_retirement_request_id',true),'')::uuid;
    IF NEW.status IS DISTINCT FROM OLD.status AND OLD.status='draft' AND NEW.status='active'
       AND NEW.retired_at IS NOT DISTINCT FROM OLD.retired_at
       AND NEW.retirement_request_id IS NOT DISTINCT FROM OLD.retirement_request_id THEN
      RETURN NEW;
    END IF;
    IF current_user<>'postgres' OR authorized_request IS NULL
       OR NEW.retirement_request_id IS DISTINCT FROM authorized_request
       OR NEW.retired_at IS NULL OR NEW.status<>'archived'
       OR NOT EXISTS (
         SELECT 1 FROM public.recon_retirement_requests q
         WHERE q.id=authorized_request AND q.recon_id=OLD.id AND q.tenant_id=OLD.tenant_id
           AND q.status='approved' AND q.decided_by IS NOT NULL AND q.decided_at IS NOT NULL
       ) THEN
      RAISE EXCEPTION 'reconciliation retirement requires a governed approved request'
        USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.scan_tenant_isolation_violations()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t record;
  null_count bigint;
  total_violations integer := 0;
BEGIN
  FOR t IN
    SELECT c.relname AS table_name
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    JOIN pg_attribute a ON a.attrelid = c.oid
    WHERE n.nspname = 'public' AND c.relkind = 'r'
      AND a.attname = 'tenant_id' AND NOT a.attisdropped
  LOOP
    BEGIN
      EXECUTE format('SELECT count(*) FROM public.%I WHERE tenant_id IS NULL', t.table_name)
        INTO null_count;
      IF null_count > 0 THEN
        INSERT INTO public.tenant_isolation_violations (table_name, violation_type, details)
        VALUES (t.table_name, 'null_tenant_id',
                jsonb_build_object('row_count', null_count, 'scanned_at', now()));
        total_violations := total_violations + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      INSERT INTO public.tenant_isolation_violations (table_name, violation_type, details)
      VALUES (t.table_name, 'scan_error',
              jsonb_build_object('error', SQLERRM, 'scanned_at', now()));
    END;
  END LOOP;
  RETURN total_violations;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_pii_policy_change(_previous text, _new text, _summary text, _initiated_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF _new IS NULL OR length(_new) = 0 THEN
    RAISE EXCEPTION 'new_version required';
  END IF;

  -- Idempotent: if this exact new_version is already recorded, return the
  -- existing id and do not duplicate.
  SELECT id INTO v_id FROM public.pii_policy_changes WHERE new_version = _new LIMIT 1;
  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO public.pii_policy_changes (previous_version, new_version, diff_summary, initiated_by)
  VALUES (_previous, _new, _summary, _initiated_by)
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION private.dpw_recon_preflight(_tenant uuid, _definition uuid, _business_date date, _bindings jsonb, _expected_definition_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant); approved jsonb; side jsonb; input jsonb;
 d public.data_prep_prepared_datasets%ROWTYPE; u public.workspace_data_source_uploads%ROWTYPE; contract jsonb; field jsonb; indexes integer[]; row_value jsonb;resolved_logical_side text;
BEGIN
 approved:=private.dpw_recon_approved_attest(actor,_tenant,_definition);
 IF (approved->>'reconciliation_feature_enabled')::boolean IS DISTINCT FROM true
 OR _business_date IS NULL OR approved->>'snapshot_sha256' IS DISTINCT FROM _expected_definition_sha256
 OR jsonb_typeof(approved->'snapshot'->'sides') IS DISTINCT FROM 'array' OR jsonb_typeof(_bindings) IS DISTINCT FROM 'array'
 OR jsonb_array_length(_bindings)<>jsonb_array_length(approved->'snapshot'->'sides')
 OR (SELECT count(DISTINCT value->>'side_id') FROM jsonb_array_elements(_bindings))<>jsonb_array_length(_bindings)
 THEN RAISE EXCEPTION 'dpw.recon_approved_input_mismatch'; END IF;
 FOR side IN SELECT value FROM jsonb_array_elements(approved->'snapshot'->'sides') LOOP
  SELECT value INTO input FROM jsonb_array_elements(_bindings) WHERE value->>'side_id'=side->>'side_id';
  IF input IS NULL OR input->>'data_source_id' IS DISTINCT FROM side->>'data_source_id'
  OR private.dpw_source_allows(actor,_tenant,(side->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'dpw.recon_source_binding_denied'; END IF;
  IF nullif(side->>'upload_id','') IS NOT NULL THEN
   IF input->>'kind' IS DISTINCT FROM 'fixed_upload' OR input->>'upload_id' IS DISTINCT FROM side->>'upload_id'
   OR input ? 'dataset_id' THEN RAISE EXCEPTION 'dpw.fixed_definition_pin_cannot_be_overridden'; END IF;
   SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(input->>'upload_id')::uuid
   AND tenant_id=_tenant AND data_source_id=(side->>'data_source_id')::uuid;
   IF NOT FOUND OR jsonb_typeof(u.rows)<>'array' OR u.row_count<>jsonb_array_length(u.rows) THEN RAISE EXCEPTION 'dpw.fixed_input_unavailable'; END IF;
  ELSE
   SELECT value INTO contract FROM jsonb_array_elements(coalesce(approved->'input_contracts','[]'::jsonb)) WHERE value->>'side_id'=side->>'side_id';
   IF contract IS NULL OR (contract->>'logical_side' IS NOT NULL AND contract->>'logical_side' IS DISTINCT FROM input->>'logical_side')
   OR jsonb_typeof(contract->'fields') IS DISTINCT FROM 'array' OR jsonb_array_length(contract->'fields')=0
   THEN RAISE EXCEPTION 'dpw.recon_authoritative_schema_missing_governed_revision_required'; END IF;
   SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=(input->>'dataset_id')::uuid AND tenant_id=_tenant;
   IF NOT FOUND THEN RAISE EXCEPTION 'dpw.current_ready_dataset_required';END IF;
   resolved_logical_side:=coalesce(contract->>'logical_side',private.rs_select_compatible_logical_side(_tenant,d.id,contract));
   IF resolved_logical_side IS DISTINCT FROM input->>'logical_side' THEN RAISE EXCEPTION 'dpw.unique_approved_rule_compatible_cohort_required';END IF;
   IF NOT FOUND OR input->>'kind' IS DISTINCT FROM 'prepared_dataset' OR d.business_date<>_business_date
   OR input->>'pipeline_id' IS DISTINCT FROM d.pipeline_id::text OR (input->>'pipeline_version')::integer IS DISTINCT FROM d.pipeline_version
   OR input->>'upload_id' IS DISTINCT FROM d.upload_id::text OR d.data_source_id::text IS DISTINCT FROM side->>'data_source_id'
   OR private.data_prep_pipeline_scope_allows(actor,_tenant,d.pipeline_id,'view') IS DISTINCT FROM true
   OR private.dpw_run_payload_available(d.run_id) IS DISTINCT FROM true
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.id=d.pipeline_id AND p.tenant_id=_tenant AND p.status='approved'
   AND p.lifecycle_state='production' AND p.version=d.pipeline_version AND p.output_data_source_id=d.data_source_id)
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_runs r,jsonb_array_elements(r.snapshot->'feeds') f
   WHERE r.id=d.run_id AND f.value->>'business_side'=resolved_logical_side)
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_batches b JOIN public.data_prep_delivery_runs r ON r.id=d.run_id AND r.batch_id=b.id
   WHERE b.id=d.batch_id AND b.mode='prepare' AND b.state='published' AND r.pipeline_version=d.pipeline_version
   AND r.finished_at IS NOT NULL AND r.state IN('success','warn') AND (r.result->>'publication_eligible')::boolean IS TRUE)
   THEN RAISE EXCEPTION 'dpw.current_ready_dataset_required'; END IF;
   SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=d.upload_id AND tenant_id=_tenant AND data_source_id=d.data_source_id;
   IF NOT FOUND OR u.content_sha256 IS DISTINCT FROM d.content_sha256 OR u.row_count<>d.rows
   OR jsonb_typeof(u.rows)<>'array' OR jsonb_array_length(u.rows)<>d.rows OR private.dpw_hash(u.rows) IS DISTINCT FROM d.content_sha256
   THEN RAISE EXCEPTION 'dpw.prepared_upload_lineage_mismatch'; END IF;
   indexes:=private.dpw_dataset_indexes(d.id,resolved_logical_side);
   FOR row_value IN SELECT u.rows->x FROM unnest(indexes) x LOOP
    IF private.rs_contract_row_allowed(row_value,contract) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.recon_approved_field_domain_incompatible';END IF;
   END LOOP;
  END IF;
 END LOOP;
 RETURN approved;
END $function$

