CREATE OR REPLACE FUNCTION public.assert_tenant_access(_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'tenant_isolation: unauthenticated caller' USING ERRCODE = '42501';
  END IF;
  IF _tenant_id IS NULL THEN
    RAISE EXCEPTION 'tenant_isolation: tenant_id is required' USING ERRCODE = '22023';
  END IF;

  IF public.is_platform_admin(_uid) THEN
    RETURN;
  END IF;

  IF NOT public.is_tenant_member(_uid, _tenant_id) THEN
    BEGIN
      INSERT INTO public.security_events (event_type, severity, user_id, tenant_id, context)
      VALUES ('tenant_isolation.assert_denied', 'high', _uid, _tenant_id,
              jsonb_build_object('reason', 'not_a_member'));
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RAISE EXCEPTION 'tenant_isolation: caller % is not a member of tenant %', _uid, _tenant_id
      USING ERRCODE = '42501';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_platform_invitations_on_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inv record;
  seeded_name text;
BEGIN
  IF NEW.email IS NULL THEN
    RETURN NEW;
  END IF;

  FOR inv IN
    SELECT id, role, invited_by, full_name
    FROM public.platform_invitations
    WHERE lower(email::text) = lower(NEW.email)
      AND accepted_at IS NULL
      AND revoked_at IS NULL
      AND expires_at > now()
  LOOP
    BEGIN
      INSERT INTO public.platform_roles (user_id, role, granted_by)
      VALUES (NEW.id, inv.role::platform_role, inv.invited_by);
    EXCEPTION WHEN unique_violation THEN
      NULL;
    END;

    UPDATE public.platform_invitations
       SET accepted_at = now(), accepted_by = NEW.id
     WHERE id = inv.id;

    IF seeded_name IS NULL AND inv.full_name IS NOT NULL AND btrim(inv.full_name) <> '' THEN
      seeded_name := btrim(inv.full_name);
    END IF;

    INSERT INTO public.audit_log (actor_user_id, scope, action, resource_type, resource_id, context)
    VALUES (inv.invited_by, 'platform', 'platform_invitation.accept', 'platform_invitation', inv.id,
            jsonb_build_object('email', NEW.email, 'role', inv.role));
  END LOOP;

  IF seeded_name IS NOT NULL AND (NEW.full_name IS NULL OR btrim(NEW.full_name) = '') THEN
    NEW.full_name := seeded_name;
  END IF;

  RETURN NEW;
END;
$function$

