CREATE OR REPLACE FUNCTION public.transition_tenant_template_atomic(_tenant_id uuid, _tenant_template_id uuid, _action text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE actor uuid:=auth.uid(); row public.tenant_templates%ROWTYPE; version_row public.tenant_template_versions%ROWTYPE; next_status public.mkt_tpl_version_status;
BEGIN
  IF actor IS NULL OR NOT public.mkt_is_tenant_admin(_tenant_id) THEN RAISE EXCEPTION 'active tenant administrator required' USING ERRCODE='42501'; END IF;
  SELECT * INTO row FROM public.tenant_templates WHERE id=_tenant_template_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'tenant template not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO version_row FROM public.tenant_template_versions
  WHERE tenant_template_id=row.id AND tenant_id=_tenant_id AND semver=row.current_semver AND spec=row.spec;
  IF NOT FOUND OR version_row.created_by IS NULL THEN
    RAISE EXCEPTION 'save a governed reconciliation version before review' USING ERRCODE='22023';
  END IF;
  IF _action='submit' AND row.status='draft' THEN next_status:='review';
  ELSIF _action='approve' AND row.status='review' AND actor<>row.submitted_by AND actor<>version_row.created_by THEN next_status:='approved';
  ELSIF _action='reject' AND row.status='review' AND actor<>row.submitted_by THEN next_status:='draft';
  ELSIF _action='publish' AND row.status='approved' AND row.approved_by IS NOT NULL
    AND row.approved_by<>version_row.created_by AND row.approved_by<>row.submitted_by THEN next_status:='published';
  ELSIF _action='unpublish' AND row.status='published' THEN next_status:='approved';
  ELSE RAISE EXCEPTION 'invalid lifecycle transition or dual-control violation' USING ERRCODE='P0001';
  END IF;
  UPDATE public.tenant_templates SET status=next_status,
    submitted_by=CASE WHEN _action='submit' THEN actor WHEN _action='reject' THEN NULL ELSE submitted_by END,
    submitted_at=CASE WHEN _action='submit' THEN now() WHEN _action='reject' THEN NULL ELSE submitted_at END,
    approved_by=CASE WHEN _action='approve' THEN actor WHEN _action IN ('reject','submit') THEN NULL ELSE approved_by END,
    approved_at=CASE WHEN _action='approve' THEN now() WHEN _action IN ('reject','submit') THEN NULL ELSE approved_at END
  WHERE id=row.id;
  INSERT INTO public.mkt_audit_log(actor_id,tenant_id,entity_type,entity_id,action,before,after)
  VALUES (actor,_tenant_id,'tenant_template',row.id,_action,
    jsonb_build_object('status',row.status,'version_id',version_row.id,'semver',version_row.semver,'source_recon_definition_id',version_row.source_recon_definition_id),
    jsonb_build_object('status',next_status,'version_id',version_row.id,'semver',version_row.semver,'source_recon_definition_id',version_row.source_recon_definition_id));
  RETURN next_status::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_copilot_confirmation_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF OLD.confirmation_token IS NULL THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'agent.action_immutable';
  END IF;
  IF OLD.confirmed_at IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'agent.action_immutable';
  END IF;
  IF (NEW.tenant_id,NEW.run_id,NEW.tool,NEW.action_kind,NEW.input,NEW.confirmation_expires_at)
    IS DISTINCT FROM (OLD.tenant_id,OLD.run_id,OLD.tool,OLD.action_kind,OLD.input,OLD.confirmation_expires_at)
    OR (NEW.confirmation_token IS DISTINCT FROM OLD.confirmation_token
      AND NOT (OLD.status='pending' AND NEW.status='rejected' AND NEW.confirmation_token IS NULL))
    OR (OLD.status<>'pending' AND NEW.status='pending') THEN
    RAISE EXCEPTION 'agent.action_immutable';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_tenant_sandbox(_tenant_id uuid, _enabled boolean, _expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid uuid := auth.uid();
  _slug text;
BEGIN
  IF NOT public.is_platform_admin(_uid) THEN
    RAISE EXCEPTION 'forbidden: platform admin required';
  END IF;

  SELECT slug INTO _slug FROM public.tenants WHERE id = _tenant_id;
  IF _slug IS NULL THEN RAISE EXCEPTION 'tenant not found'; END IF;

  UPDATE public.tenants
     SET sandbox_enabled = _enabled,
         sandbox_enabled_at = CASE WHEN _enabled THEN now() ELSE sandbox_enabled_at END,
         sandbox_enabled_by = CASE WHEN _enabled THEN _uid ELSE sandbox_enabled_by END,
         sandbox_expires_at = CASE WHEN _enabled THEN _expires_at ELSE NULL END,
         sandbox_notes = _notes,
         updated_at = now()
   WHERE id = _tenant_id;

  IF _enabled THEN
    INSERT INTO public.tenant_environments (tenant_id, env, host, is_active)
    VALUES (_tenant_id, 'sandbox'::public.tenant_env,
            _slug || '-sandbox.recon-spark.example', true)
    ON CONFLICT DO NOTHING;
  ELSE
    UPDATE public.tenant_environments
       SET is_active = false, updated_at = now()
     WHERE tenant_id = _tenant_id AND env = 'sandbox'::public.tenant_env;
  END IF;

  INSERT INTO public.audit_log (actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
  VALUES (_uid, _tenant_id, 'tenant',
          CASE WHEN _enabled THEN 'tenant.sandbox_enabled' ELSE 'tenant.sandbox_disabled' END,
          'tenant', _tenant_id::text,
          jsonb_build_object('expires_at', _expires_at, 'notes', _notes));
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_copilot_confirmation(_tenant_id uuid, _action_id uuid, _confirmation_token text, _approver_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  actor uuid := auth.uid();
  act public.agent_actions%ROWTYPE;
  maker uuid;
  plat public.platform_ai_settings%ROWTYPE;
  ten public.tenant_ai_settings%ROWTYPE;
  budget public.ai_budgets%ROWTYPE;
  article public.kb_articles%ROWTYPE;
  definition public.recon_definitions%ROWTYPE;
  ids uuid[];
  recon_id uuid;
  row_id uuid;
  grant_id uuid;
  changed integer;
  hourly_cap integer;
  used bigint;
  global_tokens numeric;
  tenant_tokens numeric;
  global_cost numeric;
  tenant_cost numeric;
  month_cost numeric;
  result jsonb;
  patch jsonb;
BEGIN
  IF auth.role() IS DISTINCT FROM 'authenticated' OR actor IS NULL
    OR actor IS DISTINCT FROM _approver_id OR _tenant_id IS NULL THEN
    RAISE EXCEPTION 'agent.forbidden' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.tenant_members
    WHERE tenant_id=_tenant_id AND user_id=actor AND active) THEN
    RAISE EXCEPTION 'agent.forbidden' USING ERRCODE='42501';
  END IF;
  SELECT * INTO act FROM public.agent_actions
    WHERE id=_action_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
  -- Check ownership of the token before revealing action state.
  IF _confirmation_token IS NULL OR act.confirmation_token IS DISTINCT FROM _confirmation_token THEN
    RAISE EXCEPTION 'agent.token_invalid';
  END IF;
  IF act.confirmed_at IS NOT NULL THEN RAISE EXCEPTION 'agent.token_already_used'; END IF;
  IF act.status<>'pending' THEN RAISE EXCEPTION 'agent.action_not_pending'; END IF;
  IF act.confirmation_expires_at IS NULL OR act.confirmation_expires_at<=clock_timestamp() THEN
    RAISE EXCEPTION 'agent.token_expired';
  END IF;
  SELECT user_id INTO maker FROM public.agent_runs WHERE id=act.run_id AND tenant_id=_tenant_id;
  IF maker IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members
    WHERE tenant_id=_tenant_id AND user_id=maker AND active) THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
  IF maker=actor THEN RAISE EXCEPTION 'agent.self_approve_blocked'; END IF;

  -- Recheck policy at the mutation boundary. SQL errors abort the transaction.
  SELECT * INTO plat FROM public.platform_ai_settings WHERE id=true FOR SHARE;
  IF NOT FOUND OR plat.allow_copilot_global IS DISTINCT FROM true OR coalesce(plat.default_autonomy_ceiling,'') NOT IN ('assist','auto') THEN
    RAISE EXCEPTION 'agent.governance_denied';
  END IF;
  SELECT * INTO ten FROM public.tenant_ai_settings WHERE tenant_id=_tenant_id FOR SHARE;
  IF NOT FOUND OR ten.allow_copilot IS DISTINCT FROM true OR coalesce(ten.default_autonomy,'') NOT IN ('supervised','autonomous') THEN
    RAISE EXCEPTION 'agent.governance_denied';
  END IF;
  IF EXISTS(SELECT 1 FROM public.ai_governance_kill_switches WHERE engaged
    AND (tenant_id IS NULL OR tenant_id=_tenant_id) AND scope IN ('global','copilot','copilot.chat')) THEN
    RAISE EXCEPTION 'agent.governance_denied';
  END IF;
  IF plat.global_max_tokens_per_day IS NULL OR plat.global_max_tokens_per_day<0
    OR plat.global_max_cost_usd_per_day IS NULL OR plat.global_max_cost_usd_per_day<0
    OR plat.global_max_cost_usd_per_day::text IN ('NaN','Infinity','-Infinity')
    OR ten.max_tokens_per_day IS NULL OR ten.max_tokens_per_day<0 THEN RAISE EXCEPTION 'agent.governance_denied'; END IF;
  SELECT * INTO budget FROM public.ai_budgets WHERE tenant_id=_tenant_id FOR SHARE;
  IF FOUND AND (budget.daily_max_tokens IS NULL OR budget.daily_max_tokens<0
    OR budget.daily_max_cost_usd IS NULL OR budget.daily_max_cost_usd<0
    OR budget.daily_max_cost_usd::text IN ('NaN','Infinity','-Infinity')
    OR budget.monthly_max_cost_usd IS NULL OR budget.monthly_max_cost_usd<0
    OR budget.monthly_max_cost_usd::text IN ('NaN','Infinity','-Infinity')
    OR budget.hard_stop_at_pct IS NULL OR budget.hard_stop_at_pct NOT BETWEEN 1 AND 200) THEN RAISE EXCEPTION 'agent.governance_denied'; END IF;
  IF EXISTS(SELECT 1 FROM public.ai_usage_events WHERE
    (created_at>=date_trunc('month',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' OR created_at IS NULL OR NOT isfinite(created_at))
    AND (created_at IS NULL OR NOT isfinite(created_at) OR tokens_in IS NULL OR tokens_out IS NULL
      OR tokens_in<0 OR tokens_out<0 OR cost_usd<0 OR cost_usd::text IN ('NaN','Infinity','-Infinity')
      OR (tokens_in::numeric+tokens_out>0 AND (cost_usd IS NULL OR cost_usd=0)))) THEN RAISE EXCEPTION 'agent.governance_denied'; END IF;
  SELECT coalesce(sum(tokens_in::numeric+tokens_out) FILTER(WHERE created_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),
    coalesce(sum(tokens_in::numeric+tokens_out) FILTER(WHERE tenant_id=_tenant_id AND created_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),
    coalesce(sum(cost_usd) FILTER(WHERE created_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),
    coalesce(sum(cost_usd) FILTER(WHERE tenant_id=_tenant_id AND created_at>=date_trunc('day',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC'),0),
    coalesce(sum(cost_usd) FILTER(WHERE tenant_id=_tenant_id),0)
    INTO global_tokens,tenant_tokens,global_cost,tenant_cost,month_cost
    FROM public.ai_usage_events WHERE created_at>=date_trunc('month',now() AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
  IF global_tokens>=plat.global_max_tokens_per_day OR tenant_tokens>=ten.max_tokens_per_day
    OR tenant_tokens>=coalesce(budget.daily_max_tokens,1000000000000000)
    OR global_cost>=plat.global_max_cost_usd_per_day
    OR tenant_cost>=coalesce(budget.daily_max_cost_usd,50)*coalesce(budget.hard_stop_at_pct,100)/100.0
    OR month_cost>=coalesce(budget.monthly_max_cost_usd,1000)*coalesce(budget.hard_stop_at_pct,100)/100.0 THEN
    RAISE EXCEPTION 'agent.governance_denied';
  END IF;

  IF act.action_kind IS NOT NULL AND act.action_kind IS DISTINCT FROM act.tool THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':'||act.tool,0));
  SELECT limit_per_hour INTO hourly_cap FROM public.agent_action_hourly_limits
    WHERE (tenant_id=_tenant_id OR tenant_id IS NULL) AND agent_key='default'
      AND action_kind=coalesce(act.action_kind,act.tool)
    ORDER BY tenant_id NULLS LAST LIMIT 1;
  SELECT count(*) INTO used FROM public.agent_actions WHERE tenant_id=_tenant_id
    AND coalesce(action_kind,tool)=coalesce(act.action_kind,act.tool) AND status='completed'
    AND coalesce(confirmed_at,created_at)>now()-interval '1 hour';
  IF hourly_cap IS NOT NULL AND used>=hourly_cap THEN RAISE EXCEPTION 'agent.rate_limit_exceeded'; END IF;

  IF act.tool IN ('assign_breaks','resolve_breaks') THEN
    IF jsonb_typeof(act.input->'break_ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
    SELECT array_agg(value::uuid ORDER BY value) INTO ids FROM jsonb_array_elements_text(act.input->'break_ids');
    IF coalesce(cardinality(ids),0) NOT BETWEEN 1 AND 50
      OR cardinality(ids)<>(SELECT count(DISTINCT x) FROM unnest(ids) x) THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
    -- Lock all targets in deterministic order and require every requested row.
    PERFORM 1 FROM public.recon_exceptions WHERE tenant_id=_tenant_id AND id=ANY(ids) ORDER BY id FOR UPDATE;
    SELECT count(*) INTO changed FROM public.recon_exceptions WHERE tenant_id=_tenant_id AND id=ANY(ids);
    IF changed<>cardinality(ids) THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
    FOR recon_id IN SELECT DISTINCT r.definition_id FROM public.recon_exceptions e
      JOIN public.recon_runs r ON r.id=e.run_id AND r.tenant_id=e.tenant_id
      WHERE e.tenant_id=_tenant_id AND e.id=ANY(ids)
    LOOP
      IF NOT private.recon_authoritative_access_decision_as(actor,recon_id,'approve')
        OR NOT private.recon_authoritative_access_decision_as(actor,recon_id,'edit') THEN
        RAISE EXCEPTION 'agent.forbidden';
      END IF;
    END LOOP;
    IF EXISTS(SELECT 1 FROM public.recon_exceptions e WHERE e.id=ANY(ids) AND NOT EXISTS(
      SELECT 1 FROM public.recon_runs r WHERE r.id=e.run_id AND r.tenant_id=_tenant_id)) THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
    IF act.tool='assign_breaks' THEN
      IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id
        AND user_id=(act.input->>'assignee_user_id')::uuid AND active) THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
      UPDATE public.recon_exceptions SET assignee=(act.input->>'assignee_user_id')::uuid,
        assigned_by=actor,assigned_at=now() WHERE tenant_id=_tenant_id AND id=ANY(ids);
      result:=jsonb_build_object('assigned',cardinality(ids));
    ELSE
      IF act.input->>'resolution_code'='written_off' THEN RAISE EXCEPTION 'agent.write_off_workflow_required'; END IF;
      IF coalesce(act.input->>'resolution_code','') NOT IN ('matched','timing','duplicate')
        OR coalesce(length(act.input->>'note'),0) NOT BETWEEN 4 AND 2000 THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
      UPDATE public.recon_exceptions SET lifecycle_state='resolved',status='resolved',
        resolution_note='[Agent/'||(act.input->>'resolution_code')||'] '||(act.input->>'note'),
        resolved_by=actor,resolved_at=now() WHERE tenant_id=_tenant_id AND id=ANY(ids);
      result:=jsonb_build_object('resolved',cardinality(ids),'code',act.input->>'resolution_code');
    END IF;
    GET DIAGNOSTICS changed=ROW_COUNT;
    IF changed<>cardinality(ids) THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
  ELSIF act.tool='trigger_reconciliation_run' THEN
    recon_id:=(act.input->>'recon_definition_id')::uuid;
    SELECT * INTO definition FROM public.recon_definitions WHERE id=recon_id AND tenant_id=_tenant_id FOR SHARE;
    IF NOT FOUND OR NOT private.recon_authoritative_access_decision_as(actor,recon_id,'run')
      OR NOT private.recon_authoritative_access_decision_as(actor,recon_id,'approve') THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
    IF definition.environment='production' THEN
      SELECT id INTO grant_id FROM public.step_up_grants WHERE user_id=actor AND tenant_id=_tenant_id
        AND action_key='recon.run.execute.production' AND consumed_at IS NULL AND expires_at>now()
        ORDER BY granted_at DESC LIMIT 1 FOR UPDATE;
      IF NOT FOUND OR NOT public.consume_step_up_grant(grant_id) THEN RAISE EXCEPTION 'agent.step_up_required'; END IF;
    END IF;
    INSERT INTO public.recon_runs(tenant_id,definition_id,status,started_at,run_by,stats)
      VALUES(_tenant_id,recon_id,'queued',now(),actor,jsonb_build_object('triggered_by','agent','agent_action_id',act.id)) RETURNING id INTO row_id;
    IF row_id IS NULL THEN RAISE EXCEPTION 'agent.confirmation_unavailable'; END IF;
    result:=jsonb_build_object('recon_run_id',row_id);
  ELSIF act.tool IN ('kb_article_create','kb_article_update','kb_article_publish','kb_article_archive') THEN
    IF act.tool='kb_article_create' THEN
      IF coalesce(act.input->>'scope','') NOT IN ('tenant','platform')
        OR coalesce(length(act.input->>'title'),0) NOT BETWEEN 2 AND 200
        OR coalesce(length(act.input->>'body_md'),0)>50000 THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
      IF (act.input->>'scope'='platform' AND NOT public.is_platform_admin(actor))
        OR (act.input->>'scope'='tenant' AND NOT public.has_tenant_role(actor,_tenant_id,'tenant_admin')) THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
      INSERT INTO public.kb_articles(scope,tenant_id,title,summary,body_md,category_id,status,slug,author_id)
        VALUES((act.input->>'scope')::public.kb_scope,CASE WHEN act.input->>'scope'='tenant' THEN _tenant_id ELSE NULL END,
          act.input->>'title',act.input->>'summary',coalesce(act.input->>'body_md',''),nullif(act.input->>'category_id','')::uuid,
          (CASE WHEN coalesce((act.input->>'publish_immediately')::boolean,false) THEN 'published' ELSE 'draft' END)::public.kb_status,
          'copilot-'||act.id::text,actor) RETURNING id INTO row_id;
      IF row_id IS NULL THEN RAISE EXCEPTION 'agent.confirmation_unavailable'; END IF;
      result:=jsonb_build_object('article_id',row_id,'slug','copilot-'||act.id::text,'status',CASE WHEN coalesce((act.input->>'publish_immediately')::boolean,false) THEN 'published' ELSE 'draft' END);
    ELSE
      SELECT * INTO article FROM public.kb_articles WHERE id=(act.input->>'article_id')::uuid FOR UPDATE;
      IF NOT FOUND OR (article.scope='tenant' AND (article.tenant_id IS DISTINCT FROM _tenant_id
        OR NOT public.has_tenant_role(actor,_tenant_id,'tenant_admin')))
        OR (article.scope='platform' AND NOT public.is_platform_admin(actor))
        OR article.scope NOT IN ('tenant','platform') THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
      IF act.tool='kb_article_update' THEN
        patch:=act.input-'article_id';
        IF patch='{}'::jsonb OR EXISTS(SELECT 1 FROM jsonb_object_keys(patch) key WHERE key NOT IN ('title','summary','body_md','category_id'))
          OR (patch ? 'title' AND coalesce(length(patch->>'title'),0) NOT BETWEEN 2 AND 200)
          OR coalesce(length(patch->>'body_md'),0)>50000 OR coalesce(length(patch->>'summary'),0)>500 THEN RAISE EXCEPTION 'agent.forbidden'; END IF;
        UPDATE public.kb_articles SET title=CASE WHEN patch ? 'title' THEN patch->>'title' ELSE title END,
          summary=CASE WHEN patch ? 'summary' THEN patch->>'summary' ELSE summary END,
          body_md=CASE WHEN patch ? 'body_md' THEN patch->>'body_md' ELSE body_md END,
          category_id=CASE WHEN patch ? 'category_id' THEN (patch->>'category_id')::uuid ELSE category_id END,author_id=actor WHERE id=article.id;
        GET DIAGNOSTICS changed=ROW_COUNT;
        IF changed<>1 THEN RAISE EXCEPTION 'agent.confirmation_unavailable'; END IF;
        result:=jsonb_build_object('article_id',article.id,'updated_fields',(SELECT jsonb_agg(key) FROM jsonb_object_keys(patch) key));
      ELSE
        UPDATE public.kb_articles SET status=(CASE WHEN act.tool='kb_article_archive' THEN 'archived'
          WHEN (act.input->>'publish')::boolean THEN 'published' ELSE 'draft' END)::public.kb_status,author_id=actor WHERE id=article.id;
        GET DIAGNOSTICS changed=ROW_COUNT;
        IF changed<>1 THEN RAISE EXCEPTION 'agent.confirmation_unavailable'; END IF;
        result:=jsonb_build_object('article_id',article.id,'status',CASE WHEN act.tool='kb_article_archive' THEN 'archived'
          WHEN (act.input->>'publish')::boolean THEN 'published' ELSE 'draft' END);
      END IF;
    END IF;
  ELSE RAISE EXCEPTION 'agent.forbidden';
  END IF;
  UPDATE public.agent_actions SET status='completed',approved_by=actor,confirmed_at=now(),output=result WHERE id=act.id;
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'agent.confirmation_unavailable'; END IF;
  IF act.tool IN ('assign_breaks','resolve_breaks','trigger_reconciliation_run') THEN
    INSERT INTO public.security_events(tenant_id,user_id,event_type,severity,context)
      VALUES(_tenant_id,actor,CASE act.tool WHEN 'assign_breaks' THEN 'agent.break_assigned'
        WHEN 'resolve_breaks' THEN 'agent.break_resolved' ELSE 'agent.run_triggered' END,'info',
        jsonb_build_object('action_id',act.id,'result',result));
    GET DIAGNOSTICS changed=ROW_COUNT;
    IF changed<>1 THEN RAISE EXCEPTION 'agent.confirmation_unavailable'; END IF;
  END IF;
  INSERT INTO public.audit_log(tenant_id,actor_user_id,scope,action,resource_type,resource_id,context)
    VALUES(_tenant_id,actor,'workspace','agent.'||act.tool||'.executed','agent_action',act.id::text,
      jsonb_build_object('result',result,'maker_user_id',maker,'approver_user_id',actor));
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'agent.confirmation_unavailable'; END IF;
  RETURN jsonb_build_object('ok',true,'action_id',act.id,'tool',act.tool,'result',result);
END;
$function$

