CREATE OR REPLACE FUNCTION public.decide_recon_retirement(_request_id uuid, _approve boolean, _reason text)
 RETURNS TABLE(request_id uuid, status text, tenant_id uuid, recon_id uuid, retired_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid(); request_row public.recon_retirement_requests%ROWTYPE;
  definition_row public.recon_definitions%ROWTYPE; next_status text; retired_timestamp timestamptz;
BEGIN
  IF actor IS NULL OR _request_id IS NULL OR _approve IS NULL
     OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION 'valid authenticated actor, decision, and reason required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO request_row FROM public.recon_retirement_requests q
    WHERE q.id=_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'retirement request not found' USING ERRCODE='P0002'; END IF;
  SELECT * INTO definition_row FROM public.recon_definitions d
    WHERE d.id=request_row.recon_id AND d.tenant_id=request_row.tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'reconciliation scope mismatch' USING ERRCODE='P0002'; END IF;
  IF request_row.status<>'pending' THEN RAISE EXCEPTION 'retirement request already decided' USING ERRCODE='23505'; END IF;
  IF actor=request_row.requested_by THEN RAISE EXCEPTION 'requester cannot approve own retirement' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_members m
    WHERE m.tenant_id=request_row.tenant_id AND m.user_id=actor AND m.active=true)
     OR NOT private.user_can_govern_recon_retirement(actor,request_row.recon_id,'approve') THEN
    RAISE EXCEPTION 'active tenant reconciliation edit and approval access required' USING ERRCODE='42501';
  END IF;
  IF definition_row.status='draft' OR definition_row.retired_at IS NOT NULL THEN
    RAISE EXCEPTION 'reconciliation is not eligible for retirement decision' USING ERRCODE='23514';
  END IF;

  next_status:=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END;
  UPDATE public.recon_retirement_requests q
    SET status=next_status,decision_reason=btrim(_reason),decided_by=actor,decided_at=now()
    WHERE q.id=request_row.id;
  IF _approve THEN
    retired_timestamp:=now();
    PERFORM set_config('fvi.recon_retirement_request_id',request_row.id::text,true);
    UPDATE public.recon_definitions d SET status='archived',retired_at=retired_timestamp,retirement_request_id=request_row.id
      WHERE d.id=request_row.recon_id AND d.tenant_id=request_row.tenant_id;
  END IF;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (actor,request_row.tenant_id,'workspace','recon.retirement.'||next_status,
      'recon_retirement_request',request_row.id::text,
      jsonb_build_object('recon_id',request_row.recon_id,'requested_by',request_row.requested_by,
        'decided_by',actor,'request_reason',request_row.reason,'decision_reason',btrim(_reason),
        'decided_at',now(),'retired_at',CASE WHEN _approve THEN now() ELSE NULL END));
  RETURN QUERY SELECT request_row.id,next_status,request_row.tenant_id,request_row.recon_id,
    retired_timestamp;
END $function$

CREATE OR REPLACE FUNCTION public.status_prune_probe_runs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  DELETE FROM public.status_probe_runs p WHERE p.created_at < now() - INTERVAL '7 days'
    AND EXISTS (SELECT 1 FROM public.status_component_history h
      WHERE h.component_id = p.component_id AND h.day = (p.created_at AT TIME ZONE 'UTC')::date
        AND h.probe_count IS NOT NULL AND h.last_probe_at >= p.created_at);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$

CREATE OR REPLACE FUNCTION private.dpw_recon_approved_attest(_actor uuid, _tenant uuid, _definition uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE; v public.recon_definition_approved_versions%ROWTYPE; sources jsonb; runtime_snapshot jsonb; contracts jsonb;
BEGIN
 IF _actor IS DISTINCT FROM auth.uid() OR auth.role() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'dpw.real_recon_actor_required'; END IF;
 -- Reuse actual bound-version producer including independent-run-actor,
 -- approved promotion request, exact full configuration SHA and native scope.
 v:=private.recon_run_bound_approved_version(_tenant,_definition,_actor);
 IF v.id IS NULL OR private.recon_root_write_allowed(_definition,_tenant,'run') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.actual_approved_recon_required'; END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 SELECT jsonb_agg(jsonb_build_object('side_id',side.value->>'side_id','data_source_id',side.value->>'data_source_id',
 'name',ds.name,'source_type',ds.source_type) ORDER BY side.ordinality) INTO sources
 FROM jsonb_array_elements(d.sides) WITH ORDINALITY side(value,ordinality)
 LEFT JOIN public.workspace_data_sources ds ON ds.id::text=side.value->>'data_source_id' AND ds.tenant_id=_tenant;
 -- Exact runtime snapshot shape of captured tg_snapshot_recon_run_definition,
 -- distinct from the approved configuration snapshot (description/extension).
 runtime_snapshot:=jsonb_build_object('name',d.name,'recon_type',d.recon_type,'sides',d.sides,'rules',d.rules,
 'sources',coalesce(sources,'[]'::jsonb),'governance_state',d.governance_state,'access_mode',d.access_mode,
 'approved_version',v.version_number,'approved_sha256',v.snapshot_sha256);
 contracts:=private.dpw_recon_schema_contract(_tenant,_definition,v.id);
 RETURN jsonb_build_object('snapshot',runtime_snapshot,'approved_configuration_snapshot',v.snapshot,'snapshot_sha256',v.snapshot_sha256,
 'revision_id',v.id,'revision_number',v.version_number,'input_contracts',contracts->'input_contracts',
 'reconciliation_feature_enabled',contracts->'reconciliation_feature_enabled');
END $function$

CREATE OR REPLACE FUNCTION public.validate_recon_definition_bu_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.principal_type = 'user' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.tenant_members tm
      WHERE tm.tenant_id = NEW.tenant_id AND tm.user_id = NEW.principal_id AND tm.active
    ) THEN
      RAISE EXCEPTION 'reconciliation grant user must be an active member of the same tenant';
    END IF;
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM public.tenant_groups g WHERE g.id = NEW.principal_id AND g.tenant_id = NEW.tenant_id
    ) THEN
      RAISE EXCEPTION 'reconciliation grant group must belong to the same tenant';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.dpw_persist_recon_binding(_tenant uuid, _definition uuid, _run uuid, _business_date date, _bindings jsonb, _request_key uuid, _expected_definition_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant); approved jsonb; r public.recon_runs%ROWTYPE; input jsonb;
 d public.data_prep_prepared_datasets%ROWTYPE; u public.workspace_data_source_uploads%ROWTYPE; indexes integer[]; selected_rows jsonb;
BEGIN
 -- No adoption of old/failed/partial runs and no status rewrite to hide errors.
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND definition_id=_definition FOR UPDATE;
 IF NOT FOUND OR r.run_by IS DISTINCT FROM actor OR r.status<>'queued' OR r.completed_at IS NOT NULL
 OR r.started_at<transaction_timestamp() OR r.matched_count<>0 OR r.exception_count<>0
 OR EXISTS(SELECT 1 FROM public.recon_matches WHERE run_id=r.id) OR EXISTS(SELECT 1 FROM public.recon_exceptions WHERE run_id=r.id)
 THEN RAISE EXCEPTION 'dpw.new_owned_recon_run_required'; END IF;
 approved:=private.dpw_recon_preflight(_tenant,_definition,_business_date,_bindings,_expected_definition_sha256);
 IF r.definition_snapshot IS DISTINCT FROM approved->'snapshot'
 OR r.approved_revision_id IS DISTINCT FROM (approved->>'revision_id')::uuid
 OR r.approved_revision_number IS DISTINCT FROM (approved->>'revision_number')::integer
 OR r.approved_revision_sha256 IS DISTINCT FROM approved->>'snapshot_sha256'
 THEN RAISE EXCEPTION 'dpw.recon_native_approval_snapshot_mismatch'; END IF;
 INSERT INTO public.data_prep_recon_run_requests(recon_run_id,tenant_id,definition_id,created_by,request_key,approved_snapshot,approved_snapshot_sha256,approved_revision_id,approved_revision_number,input_bindings,business_date)
 VALUES(r.id,_tenant,_definition,actor,_request_key,approved->'snapshot',approved->>'snapshot_sha256',(approved->>'revision_id')::uuid,
 (approved->>'revision_number')::integer,_bindings,_business_date);
 FOR input IN SELECT value FROM jsonb_array_elements(_bindings) LOOP
  SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(input->>'upload_id')::uuid;
  IF input->>'kind'='prepared_dataset' THEN
   SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=(input->>'dataset_id')::uuid;
   indexes:=private.dpw_dataset_indexes(d.id,input->>'logical_side');
   SELECT coalesce(jsonb_agg(u.rows->i ORDER BY i),'[]'::jsonb) INTO selected_rows FROM unnest(indexes) i;
   INSERT INTO public.data_prep_recon_run_inputs VALUES(r.id,input->>'side_id',_tenant,_definition,d.data_source_id,d.upload_id,
   d.id,d.batch_id,d.run_id,d.pipeline_id,d.pipeline_version,d.business_date,'prepared_dataset',d.content_sha256,cardinality(indexes),input->>'logical_side',indexes,private.dpw_hash(selected_rows));
  ELSE
   INSERT INTO public.data_prep_recon_run_inputs VALUES(r.id,input->>'side_id',_tenant,_definition,u.data_source_id,u.id,
   NULL,NULL,NULL,NULL,NULL,NULL,'fixed_upload',u.content_sha256,u.row_count,NULL,NULL,private.dpw_hash(u.rows));
  END IF;
 END LOOP;
 PERFORM private.dpw_audit(actor,_tenant,'dpw.recon.inputs.bind',r.id,jsonb_build_object('definition_id',_definition,'bindings',_bindings,'approved_sha256',_expected_definition_sha256));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'run_id',r.id,'run_uid',r.run_uid,'input_bindings',_bindings,'approved_snapshot',approved->'snapshot','is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.guard_recon_multi_bu_owner_mapping()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_recon uuid; v_bu uuid;
BEGIN
  v_tenant := COALESCE(NEW.tenant_id, OLD.tenant_id);
  v_recon := COALESCE(NEW.recon_id, OLD.recon_id);
  v_bu := COALESCE(NEW.bu_id, OLD.bu_id);
  IF TG_OP = 'DELETE' AND EXISTS (
    SELECT 1 FROM public.recon_definitions d
    WHERE d.id = OLD.recon_id AND d.tenant_id = OLD.tenant_id AND d.multi_bu_governed
      AND (SELECT count(*) FROM public.recon_definition_business_units m
           WHERE m.tenant_id = OLD.tenant_id AND m.recon_id = OLD.recon_id) = 0
  ) THEN
    RAISE EXCEPTION 'governed reconciliation must retain at least one owning business unit';
  END IF;
  INSERT INTO public.recon_definition_business_unit_audit
    (tenant_id, recon_id, bu_id, operation, changed_by)
  VALUES (v_tenant, v_recon, v_bu, TG_OP, auth.uid());
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_admin(_tenant uuid, _command jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid; action text:=_command->>'action'; a private.rlnext_accounts; row_id uuid; ids uuid[]; vers integer[];
 result jsonb; rows jsonb; counts jsonb; off integer:=greatest(0,coalesce((_command->>'offset')::integer,0)); search text:=left(coalesce(_command->>'search',''),120);
 reason text:=_command->>'reason'; operation text:=_command->>'operation'; n integer; bu uuid; groups uuid[]; scope jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('rlnext:'||_tenant::text,0));
 actor:=private.rlnext_admin_current(_tenant);
 IF _command->>'tenantId' IS DISTINCT FROM _tenant::text THEN RAISE EXCEPTION 'Tenant mismatch' USING ERRCODE='42501'; END IF;
 IF action='list' THEN
   WITH users AS (
     SELECT coalesce(ac.id,u.id) id,u.id user_id,u.email,coalesce(ac.first_name,u.raw_user_meta_data->>'first_name',u.raw_user_meta_data->>'full_name','') first_name,coalesce(ac.last_name,'') last_name,
       coalesce(ac.department,'') department,coalesce(ac.employee_id,'') employee_id,coalesce(ac.job_title,'') job_title,CASE WHEN u.banned_until>clock_timestamp() THEN 'locked' ELSE coalesce(ac.status,'active') END status,coalesce(ac.version,1) version,
       coalesce(ac.requested_at,u.created_at) requested_at,ac.verified_at,u.last_sign_in_at last_login,coalesce(ac.lock_reason,CASE WHEN u.banned_until>clock_timestamp() THEN 'Supabase account restriction' END) lock_reason,coalesce(ac.locked_at,CASE WHEN u.banned_until>clock_timestamp() THEN u.updated_at END) locked_at,coalesce(ac.assigned,true) assigned
     FROM auth.users u JOIN public.tenant_members m ON m.user_id=u.id AND m.tenant_id=_tenant LEFT JOIN private.rlnext_accounts ac ON ac.user_id=u.id AND ac.tenant_id=_tenant
     UNION ALL
     SELECT ac.id,ac.user_id,ac.email,ac.first_name,ac.last_name,ac.department,ac.employee_id,ac.job_title,ac.status,ac.version,ac.requested_at,ac.verified_at,u.last_sign_in_at,ac.lock_reason,ac.locked_at,ac.assigned
     FROM private.rlnext_accounts ac LEFT JOIN auth.users u ON u.id=ac.user_id WHERE ac.tenant_id=_tenant AND NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant AND m.user_id=ac.user_id)
   ), filtered AS(SELECT * FROM users WHERE (coalesce(_command->>'status','all')='all' OR status=_command->>'status') AND position(lower(search) IN lower(email||' '||first_name||' '||last_name))>0)
   SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(to_jsonb(f)) FROM(SELECT * FROM filtered ORDER BY requested_at DESC,id LIMIT 50 OFFSET off) f),'[]'::jsonb),
     'total',(SELECT count(*) FROM filtered),'counts',coalesce((SELECT jsonb_object_agg(status,num) FROM(SELECT status,count(*) num FROM users GROUP BY status) c),'{}'::jsonb)) INTO result;
   RETURN result;
 ELSIF action='audit' THEN
   SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) INTO rows FROM(SELECT id,account_id,actor_id,event,occurred_at,reason,context FROM private.rlnext_audit WHERE tenant_id=_tenant AND (_command->>'accountId' IS NULL OR account_id=(_command->>'accountId')::uuid) ORDER BY occurred_at DESC,id LIMIT 50 OFFSET off) r;
   RETURN jsonb_build_object('rows',rows);
 ELSIF action='invite_meta' THEN
   RETURN jsonb_build_object('slug',(SELECT slug FROM public.tenants WHERE id=_tenant));
 ELSIF action='domains' THEN
   RETURN jsonb_build_object('domains',coalesce((SELECT jsonb_agg(jsonb_build_object('domain',domain::text,'status',status,'verified_at',verified_at)) FROM public.tenant_email_domains WHERE tenant_id=_tenant),'[]'::jsonb),
     'policy',coalesce((SELECT to_jsonb(p) FROM private.rlnext_policy p WHERE tenant_id=_tenant),jsonb_build_object('enabled',false,'allowed_domains','[]'::jsonb,'blocked_domains',ARRAY['gmail.com','yahoo.com','outlook.com'],'ttl_seconds',600,'max_resends',3,'max_attempts',5,'failed_login_limit',5)));
 ELSIF action='options' THEN
   IF _command->>'kind'='bu' THEN
     SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) INTO rows FROM(SELECT id,name FROM public.business_units WHERE tenant_id=_tenant AND NOT is_archived AND position(lower(search) IN lower(name))>0 ORDER BY name,id LIMIT 50 OFFSET off) r;
   ELSIF _command->>'kind'='group' THEN
     SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) INTO rows FROM(SELECT id,name FROM public.tenant_groups WHERE tenant_id=_tenant AND bu_id=(_command->>'buId')::uuid AND position(lower(search) IN lower(name))>0 ORDER BY name,id LIMIT 50 OFFSET off) r;
   ELSE RAISE EXCEPTION 'Invalid selector' USING ERRCODE='22023'; END IF;
   RETURN jsonb_build_object('rows',rows);
 ELSIF action='scope' THEN
   SELECT array_agg(x::uuid) INTO groups FROM jsonb_array_elements_text(_command->'groupIds') x;
   RETURN private.rlnext_scope(_tenant,(_command->>'buId')::uuid,groups);
 END IF;
 IF _command->>'confirmation' IS DISTINCT FROM 'true' OR reason IS NULL OR length(trim(reason)) NOT BETWEEN 3 AND 800 THEN RAISE EXCEPTION 'Confirmation and reason required' USING ERRCODE='22023'; END IF;
 -- Lock dependencies in a single stable order, before decision or assignment.
 LOCK TABLE public.tenant_members,public.tenant_email_domains,public.business_units,public.tenant_groups IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.tenant_group_members,public.tenant_group_roles,public.rbac_roles,public.rbac_role_permissions,public.permissions,public.bu_group_assignments,
   public.recon_definition_bu_grants,public.recon_permissions,public.recon_definitions,public.data_resource_registry_grants,public.data_resource_bu_grants IN SHARE ROW EXCLUSIVE MODE;
 PERFORM pg_advisory_xact_lock(hashtextextended('rlnext:'||_tenant::text,0));
 actor:=private.rlnext_admin_current(_tenant);
 IF action='invite' THEN
   IF NOT private.rlnext_domain(_tenant,_command->>'email') OR _command->>'tokenHash' !~ '^[a-f0-9]{64}$' OR (_command->>'expires')::bigint IS NULL OR to_timestamp((_command->>'expires')::double precision/1000)<=clock_timestamp() OR to_timestamp((_command->>'expires')::double precision/1000)>clock_timestamp()+interval '24 hours 5 seconds' THEN RAISE EXCEPTION 'Invalid enrollment permit' USING ERRCODE='22023'; END IF;
   INSERT INTO private.rlnext_invitations(token_hash,tenant_id,email,expires_at,created_by) VALUES(_command->>'tokenHash',_tenant,lower(_command->>'email'),to_timestamp((_command->>'expires')::double precision/1000),actor);
   PERFORM private.rlnext_record(_tenant,NULL,actor,'enrollment_permit_created',reason);
   RETURN jsonb_build_object('created',true);
 END IF;
 IF action='policy' THEN
   IF (_command->>'ttlSeconds')::integer NOT BETWEEN 120 AND 1800 OR (_command->>'maxResends')::integer NOT BETWEEN 0 AND 5 OR (_command->>'maxAttempts')::integer NOT BETWEEN 1 AND 10 OR (_command->>'failedLoginLimit')::integer NOT BETWEEN 3 AND 20 THEN RAISE EXCEPTION 'Invalid policy' USING ERRCODE='22023'; END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(_command->'allowedDomains','[]'::jsonb)) x WHERE NOT EXISTS(SELECT 1 FROM public.tenant_email_domains WHERE tenant_id=_tenant AND domain::text=x AND status='verified')) THEN RAISE EXCEPTION 'Only current verified tenant domains may be allowed' USING ERRCODE='42501'; END IF;
   INSERT INTO private.rlnext_policy(tenant_id,enabled,allowed_domains,blocked_domains,ttl_seconds,max_resends,max_attempts,failed_login_limit)
   VALUES(_tenant,(_command->>'enabled')::boolean,ARRAY(SELECT lower(x) FROM jsonb_array_elements_text(coalesce(_command->'allowedDomains','[]'::jsonb)) x),ARRAY(SELECT lower(x) FROM jsonb_array_elements_text(_command->'blockedDomains') x),(_command->>'ttlSeconds')::integer,(_command->>'maxResends')::integer,(_command->>'maxAttempts')::integer,(_command->>'failedLoginLimit')::integer)
   ON CONFLICT(tenant_id) DO UPDATE SET enabled=excluded.enabled,allowed_domains=excluded.allowed_domains,blocked_domains=excluded.blocked_domains,ttl_seconds=excluded.ttl_seconds,max_resends=excluded.max_resends,max_attempts=excluded.max_attempts,failed_login_limit=excluded.failed_login_limit;
   PERFORM private.rlnext_record(_tenant,NULL,actor,'domain_policy_changed',reason);
   RETURN jsonb_build_object('saved',true);
 END IF;
 IF action='decide' THEN
   SELECT array_agg(x::uuid) INTO ids FROM jsonb_array_elements_text(_command->'accountIds') x;
   SELECT array_agg(x::integer) INTO vers FROM jsonb_array_elements_text(_command->'versions') x;
   IF cardinality(ids) NOT BETWEEN 1 AND 20 OR cardinality(ids)<>cardinality(vers) OR cardinality(ids)<>(SELECT count(DISTINCT x) FROM unnest(ids) x) OR _command->>'decision' NOT IN('approve','reject') THEN RAISE EXCEPTION 'Invalid decision' USING ERRCODE='22023'; END IF;
   -- Atomic bounded bulk; one stale/revoked/wrong-tenant row refuses the entire packet.
   PERFORM 1 FROM private.rlnext_accounts WHERE id=ANY(ids) ORDER BY id FOR UPDATE;
   FOR n IN 1..cardinality(ids) LOOP
     SELECT * INTO a FROM private.rlnext_accounts WHERE id=ids[n] AND tenant_id=_tenant;
     IF a.id IS NULL OR a.status<>'pending_approval' OR a.version IS DISTINCT FROM vers[n] OR a.user_id=actor OR public.is_platform_admin(a.user_id) OR NOT private.rlnext_domain(_tenant,a.email)
       OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=a.user_id AND email_confirmed_at IS NOT NULL AND lower(email)=a.email)
       OR EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=a.user_id) THEN RAISE EXCEPTION 'Approval changed or unavailable' USING ERRCODE='PT409'; END IF;
     UPDATE private.rlnext_accounts SET status=CASE WHEN _command->>'decision'='approve' THEN 'active' ELSE 'rejected' END,version=version+1,decided_at=clock_timestamp(),decided_by=actor WHERE id=a.id;
     PERFORM private.rlnext_record(_tenant,a.id,actor,CASE WHEN _command->>'decision'='approve' THEN 'approved' ELSE 'rejected' END,reason);
     PERFORM private.rlnext_notice(a.id,CASE WHEN _command->>'decision'='approve' THEN 'approved' ELSE 'rejected' END,reason);
     PERFORM private.rlnext_notice(a.id,CASE WHEN _command->>'decision'='approve' THEN 'admin_approved' ELSE 'admin_rejected' END,NULL,true);
   END LOOP;
   RETURN jsonb_build_object('changed',cardinality(ids));
 END IF;
 row_id:=(_command->>'accountId')::uuid;
 SELECT * INTO a FROM private.rlnext_accounts WHERE id=row_id AND tenant_id=_tenant FOR UPDATE;
 IF a.id IS NULL AND action='manage' THEN
   INSERT INTO private.rlnext_accounts(id,tenant_id,user_id,email,status,verified_at,assigned)
   SELECT u.id,_tenant,u.id,lower(u.email),CASE WHEN u.banned_until>clock_timestamp() THEN 'locked' ELSE 'active' END,u.email_confirmed_at,true FROM auth.users u JOIN public.tenant_members m ON m.user_id=u.id AND m.tenant_id=_tenant WHERE u.id=row_id AND m.active
   RETURNING * INTO a;
 END IF;
 IF a.id IS NOT NULL AND a.status='active' AND EXISTS(SELECT 1 FROM auth.users WHERE id=a.user_id AND banned_until>clock_timestamp()) THEN UPDATE private.rlnext_accounts SET status='locked',provider_locked=true WHERE id=a.id RETURNING * INTO a; END IF;
 IF a.id IS NULL OR a.user_id IS NULL OR a.user_id=actor OR public.is_platform_admin(a.user_id) OR a.version IS DISTINCT FROM (_command->>'version')::integer
   OR EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=a.user_id AND tenant_id<>_tenant)
 THEN RAISE EXCEPTION 'Account changed or unavailable' USING ERRCODE='PT409'; END IF;
 IF action='assign' THEN
   bu:=(_command->>'buId')::uuid; SELECT array_agg(x::uuid) INTO groups FROM jsonb_array_elements_text(_command->'groupIds') x;
   IF a.status<>'active' OR a.assigned OR NOT private.rlnext_domain(_tenant,a.email) OR EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=a.user_id) THEN RAISE EXCEPTION 'Assignment unavailable' USING ERRCODE='PT409'; END IF;
   scope:=private.rlnext_scope(_tenant,bu,groups);
   IF scope->>'hash' IS DISTINCT FROM _command->>'scopeHash' THEN RAISE EXCEPTION 'Group scope changed; review again' USING ERRCODE='PT409'; END IF;
   INSERT INTO public.tenant_members(tenant_id,user_id,role,invited_by) VALUES(_tenant,a.user_id,'tenant_viewer',actor);
   INSERT INTO public.tenant_group_members(group_id,user_id,added_by) SELECT unnest(groups),a.user_id,actor;
   UPDATE private.rlnext_accounts SET assigned=true,version=version+1 WHERE id=a.id;
   PERFORM private.rlnext_record(_tenant,a.id,actor,'assigned',reason,scope->'snapshot'); PERFORM private.rlnext_notice(a.id,'assigned');
   RETURN jsonb_build_object('assigned',true);
 ELSIF action='manage' THEN
   IF operation IN('unlock','reactivate','reset_password') AND (NOT private.rlnext_domain(_tenant,a.email) OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=a.user_id AND lower(email)=a.email AND email_confirmed_at IS NOT NULL)) THEN RAISE EXCEPTION 'Current tenant email verification required' USING ERRCODE='PT409'; END IF;
   IF operation='reset_password' THEN
     IF a.status NOT IN('active','locked') THEN RAISE EXCEPTION 'Reset unavailable' USING ERRCODE='PT409'; END IF;
     -- Administrator asks the user to complete proof, never sets or sees their password.
     PERFORM private.rlnext_notice(a.id,'password_reset',reason); PERFORM private.rlnext_record(_tenant,a.id,actor,'reset_requested_by_admin',reason);
     RETURN jsonb_build_object('requested',true);
   END IF;
   IF NOT((a.status='active' AND operation IN('lock','disable','suspend')) OR (a.status='locked' AND operation IN('unlock','disable','suspend')) OR (a.status IN('disabled','suspended') AND operation='reactivate')) THEN RAISE EXCEPTION 'Account state changed' USING ERRCODE='PT409'; END IF;
   UPDATE private.rlnext_accounts SET status=CASE operation WHEN 'lock' THEN 'locked' WHEN 'disable' THEN 'disabled' WHEN 'suspend' THEN 'suspended' ELSE 'active' END,
     lock_reason=CASE WHEN operation='lock' THEN reason ELSE NULL END,locked_at=CASE WHEN operation='lock' THEN clock_timestamp() ELSE NULL END,reset_required=false,version=version+1 WHERE id=a.id;
   IF operation IN('unlock','reactivate') THEN UPDATE auth.users SET banned_until=NULL WHERE id=a.user_id AND banned_until>clock_timestamp(); END IF;
   -- Any admin state change invalidates outstanding recovery proof.
   UPDATE private.rlnext_challenges SET verify_state='exhausted',reset_state='none',reset_hash=NULL WHERE account_id=a.id AND reset_state<>'complete';
   PERFORM private.rlnext_record(_tenant,a.id,actor,operation,reason);
   PERFORM private.rlnext_notice(a.id,CASE operation WHEN 'lock' THEN 'locked' WHEN 'unlock' THEN 'unlocked' WHEN 'disable' THEN 'disabled' WHEN 'suspend' THEN 'suspended' ELSE 'approved' END,reason);
   IF operation='lock' THEN PERFORM private.rlnext_notice(a.id,'locked',NULL,true); END IF;
   RETURN jsonb_build_object('changed',true);
 END IF;
 RAISE EXCEPTION 'Invalid action' USING ERRCODE='22023';
END $function$

CREATE OR REPLACE FUNCTION public.require_recon_multi_bu_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='INSERT' AND NEW.access_mode='mapped_exact' AND NEW.governance_state='staging_copy' THEN
    PERFORM private.mapped_recon_governance_stage_insert(NEW);
    RETURN NEW;
  END IF;
  IF NEW.multi_bu_governed AND NOT EXISTS (
    SELECT 1 FROM public.recon_definition_business_units m
    WHERE m.tenant_id = NEW.tenant_id AND m.recon_id = NEW.id
  ) THEN
    RAISE EXCEPTION 'governed reconciliation requires at least one owning business unit';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.dpw_create_recon_run(_tenant_id uuid, _definition_id uuid, _business_date date, _bindings jsonb, _request_key uuid, _expected_definition_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant_id); approved jsonb; runrow public.recon_runs%ROWTYPE; replay jsonb;
BEGIN
 IF _request_key IS NULL THEN RAISE EXCEPTION 'dpw.recon_request_key_required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||actor::text||_request_key::text,23));
 -- Preflight before INSERT, persist rechecks after native run triggers, all in
 -- this one authenticated transaction. Matching begins only after commit ACK.
 approved:=private.dpw_recon_preflight(_tenant_id,_definition_id,_business_date,_bindings,_expected_definition_sha256);
 replay:=public.dpw_get_recon_binding(_tenant_id,_request_key);
 IF replay->>'run_id' IS NOT NULL THEN
  IF replay->>'definition_id' IS DISTINCT FROM _definition_id::text OR replay->'input_bindings' IS DISTINCT FROM _bindings
  OR replay->>'business_date' IS DISTINCT FROM _business_date::text OR replay->>'approved_snapshot_sha256' IS DISTINCT FROM _expected_definition_sha256
  THEN RAISE EXCEPTION 'dpw.recon_request_conflict'; END IF;
  RETURN replay||jsonb_build_object('is_new',false);
 END IF;
 INSERT INTO public.recon_runs(tenant_id,definition_id,status,run_by) VALUES(_tenant_id,_definition_id,'queued',actor) RETURNING * INTO runrow;
 RETURN private.dpw_persist_recon_binding(_tenant_id,_definition_id,runrow.id,_business_date,_bindings,_request_key,_expected_definition_sha256);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_get_recon_binding(_tenant_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant_id); r public.data_prep_recon_run_requests%ROWTYPE;
BEGIN
 SELECT * INTO r FROM public.data_prep_recon_run_requests WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'state','absent'); END IF;
 PERFORM private.dpw_recon_approved_attest(actor,_tenant_id,r.definition_id);
 IF EXISTS(SELECT 1 FROM public.data_prep_recon_run_inputs i WHERE i.recon_run_id=r.recon_run_id AND private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'dpw.recon_binding_read_denied'; END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'run_id',r.recon_run_id,'definition_id',r.definition_id,'business_date',r.business_date,
 'approved_snapshot_sha256',r.approved_snapshot_sha256,'approved_snapshot',r.approved_snapshot,'input_bindings',r.input_bindings,'state','recorded');
END $function$

CREATE OR REPLACE FUNCTION public.assign_exception_public_case_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.public_case_id IS NOT NULL THEN
      RAISE EXCEPTION 'exception case identifier is system managed';
    END IF;
    NEW.public_case_id := 'FVI-EXC-' || upper(replace(gen_random_uuid()::text, '-', ''));
    RETURN NEW;
  END IF;

  IF NEW.public_case_id IS DISTINCT FROM OLD.public_case_id THEN
    RAISE EXCEPTION 'exception case identifier is immutable';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dpw_get_recon_input_rows(_tenant_id uuid, _run_id uuid, _side_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant_id); binding public.data_prep_recon_run_inputs%ROWTYPE;
 u public.workspace_data_source_uploads%ROWTYPE; rows_value jsonb;
BEGIN
 SELECT * INTO binding FROM public.data_prep_recon_run_inputs WHERE recon_run_id=_run_id AND tenant_id=_tenant_id AND side_id=_side_id;
 IF NOT FOUND OR private.dpw_source_allows(actor,_tenant_id,binding.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.recon_input_read_denied'; END IF;
 PERFORM private.dpw_recon_approved_attest(actor,_tenant_id,binding.definition_id);
 SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=binding.upload_id AND tenant_id=_tenant_id AND data_source_id=binding.data_source_id;
 IF binding.binding_kind='fixed_upload' THEN rows_value:=u.rows;
 ELSE
  PERFORM private.dps_assert_preparation_source_scope(_tenant_id,binding.preparation_run_id,actor);
  IF private.dpw_run_payload_available(binding.preparation_run_id) IS DISTINCT FROM true THEN
   RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'side_id',_side_id,'binding',to_jsonb(binding),
   'payload',CASE WHEN EXISTS(SELECT 1 FROM public.data_prep_prepared_datasets d JOIN private.dpdi_public_output_links l ON l.dataset_id=d.id WHERE d.run_id=binding.preparation_run_id) THEN private.dpdi_public_payload_state(_tenant_id,binding.preparation_run_id,actor) ELSE private.dpw_run_payload_state(binding.preparation_run_id) END,'rows',NULL,'rows_count',binding.row_count,'structured_data_sha256',binding.selected_structured_sha256);
  END IF;
  IF private.data_prep_pipeline_scope_allows(actor,_tenant_id,binding.pipeline_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.recon_pipeline_read_denied'; END IF;
  SELECT coalesce(jsonb_agg(u.rows->i ORDER BY i),'[]'::jsonb) INTO rows_value FROM unnest(binding.output_indexes) i;
 END IF;
 IF jsonb_typeof(rows_value) IS DISTINCT FROM 'array' OR jsonb_array_length(rows_value)<>binding.row_count
 OR private.dpw_hash(rows_value) IS DISTINCT FROM binding.selected_structured_sha256 THEN RAISE EXCEPTION 'dpw.recon_input_hash_mismatch'; END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'side_id',_side_id,'binding',to_jsonb(binding),
 'rows',rows_value,'rows_count',binding.row_count,'structured_data_sha256',binding.selected_structured_sha256);
END $function$

CREATE OR REPLACE FUNCTION private.rlnext_password_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a private.rlnext_accounts;
BEGIN
 IF NEW.encrypted_password IS NOT DISTINCT FROM OLD.encrypted_password THEN RETURN NEW; END IF;
 SELECT * INTO a FROM private.rlnext_accounts WHERE user_id=NEW.id FOR UPDATE;
 IF a.id IS NULL THEN RETURN NEW; END IF;
 IF a.status IN('disabled','suspended','rejected','pending_approval') OR (a.status='locked' AND NOT EXISTS(SELECT 1 FROM private.rlnext_challenges WHERE account_id=a.id AND reset_state='claimed' AND reset_expires_at>clock_timestamp()))
 THEN RAISE EXCEPTION 'Password update is unavailable' USING ERRCODE='42501'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.set_recon_owners(_recon_id uuid, _bu_ids uuid[], _reason text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant uuid;
  v_old uuid[];
  v_new uuid[];
  v_governed boolean;
BEGIN
  IF v_actor IS NULL OR _recon_id IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid access setup request';
  END IF;
  SELECT d.tenant_id, d.multi_bu_governed INTO v_tenant, v_governed
  FROM public.recon_definitions d WHERE d.id = _recon_id FOR UPDATE;
  IF v_tenant IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id = v_tenant AND tm.user_id = v_actor
      AND tm.active AND tm.role = 'tenant_admin'::public.tenant_role
  ) THEN RAISE EXCEPTION 'not authorized'; END IF;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_new
  FROM unnest(coalesce(_bu_ids, ARRAY[]::uuid[])) x;
  IF v_governed AND cardinality(v_new) = 0 THEN RAISE EXCEPTION 'governed reconciliation requires an owner'; END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_new) x
    LEFT JOIN public.business_units b ON b.id = x AND b.tenant_id = v_tenant
    WHERE b.id IS NULL
  ) THEN RAISE EXCEPTION 'owners must be business units in the reconciliation tenant'; END IF;
  SELECT coalesce(array_agg(m.bu_id ORDER BY m.bu_id), ARRAY[]::uuid[]) INTO v_old
  FROM public.recon_definition_business_units m WHERE m.tenant_id = v_tenant AND m.recon_id = _recon_id;
  IF EXISTS (
    SELECT 1 FROM public.recon_definition_bu_grants g
    WHERE g.tenant_id = v_tenant AND g.recon_id = _recon_id AND NOT (g.bu_id = ANY(v_new))
  ) THEN
    RAISE EXCEPTION 'revoke grants for removed owner business units before replacing ownership';
  END IF;
  DELETE FROM public.recon_definition_business_units m
  WHERE m.tenant_id = v_tenant AND m.recon_id = _recon_id AND NOT (m.bu_id = ANY(v_new));
  INSERT INTO public.recon_definition_business_units(tenant_id, recon_id, bu_id, created_by)
  SELECT v_tenant, _recon_id, x, v_actor FROM unnest(v_new) x
  ON CONFLICT (tenant_id, recon_id, bu_id) DO NOTHING;
  INSERT INTO public.recon_definition_bu_admin_audit(tenant_id, recon_id, operation, actor_id, reason, details)
  VALUES (v_tenant, _recon_id, 'replace_owners', v_actor, btrim(_reason),
          jsonb_build_object('previous_bu_ids', v_old, 'new_bu_ids', v_new));
  RETURN v_new;
END
$function$

CREATE OR REPLACE FUNCTION public.set_resource_actor_attribution()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_actor uuid;
  v_actor_status text;
BEGIN
  -- Only a signed authenticated-user request is attributable to a person.
  -- Service-role, anon, SQL maintenance, and missing-claim writes are explicit
  -- unattributed events; never trust actor values supplied by the caller.
  IF coalesce(auth.role(), '') = 'authenticated' THEN
    v_actor := auth.uid();
  ELSE
    v_actor := NULL;
  END IF;
  v_actor_status := CASE WHEN v_actor IS NULL THEN 'unattributed' ELSE 'authenticated_user' END;

  IF TG_OP = 'INSERT' THEN
    NEW.created_by_actor_id := v_actor;
    NEW.created_by_actor_status := v_actor_status;
  ELSE
    -- Preserve creation provenance from the stored row, never from UPDATE input.
    NEW.created_by_actor_id := OLD.created_by_actor_id;
    NEW.created_by_actor_status := OLD.created_by_actor_status;
  END IF;

  NEW.updated_by_actor_id := v_actor;
  NEW.updated_by_actor_status := v_actor_status;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_recon_access_setup(_recon_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant uuid;
  v_admin boolean;
  v_owners jsonb;
  v_grants jsonb;
  v_effective jsonb;
  v_bu_choices jsonb;
  v_principal_choices jsonb;
BEGIN
  IF v_actor IS NULL OR _recon_id IS NULL THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  SELECT d.tenant_id INTO v_tenant
  FROM public.recon_definitions d WHERE d.id = _recon_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not authorized'; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_members tm
    WHERE tm.tenant_id = v_tenant AND tm.user_id = v_actor AND tm.active
      AND tm.role = 'tenant_admin'::public.tenant_role
  ) INTO v_admin;
  IF NOT v_admin AND NOT private.recon_multi_bu_shadow_allows_actor(v_actor, _recon_id, 'view') THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object('bu_id', m.bu_id, 'created_at', m.created_at)
                            ORDER BY m.bu_id), '[]'::jsonb)
    INTO v_owners
  FROM public.recon_definition_business_units m
  WHERE m.tenant_id = v_tenant AND m.recon_id = _recon_id;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
             'grant_id', g.id, 'bu_id', g.bu_id, 'principal_type', g.principal_type,
             'principal_id', g.principal_id, 'action', g.action, 'granted_at', g.granted_at
           ) ORDER BY g.bu_id, g.principal_type, g.principal_id, g.action), '[]'::jsonb)
    INTO v_grants
  FROM public.recon_definition_bu_grants g
  WHERE g.tenant_id = v_tenant AND g.recon_id = _recon_id;
  SELECT jsonb_build_object(
    'view', private.recon_multi_bu_shadow_allows_actor(v_actor, _recon_id, 'view'),
    'run', private.recon_multi_bu_shadow_allows_actor(v_actor, _recon_id, 'run'),
    'edit', private.recon_multi_bu_shadow_allows_actor(v_actor, _recon_id, 'edit'),
    'approve', private.recon_multi_bu_shadow_allows_actor(v_actor, _recon_id, 'approve')
  ) INTO v_effective;
  IF v_admin THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('bu_id', b.id, 'name', b.name, 'code', b.code)
                              ORDER BY b.name, b.id), '[]'::jsonb)
      INTO v_bu_choices
    FROM public.business_units b WHERE b.tenant_id = v_tenant AND NOT b.is_archived;
    SELECT coalesce(jsonb_agg(choice ORDER BY choice->>'principal_type', choice->>'label'), '[]'::jsonb)
      INTO v_principal_choices
    FROM (
      SELECT jsonb_build_object('principal_type', 'user', 'principal_id', tm.user_id,
             'label', coalesce(nullif(u.email, ''), tm.user_id::text), 'bu_ids',
             coalesce((SELECT jsonb_agg(DISTINCT a.bu_id ORDER BY a.bu_id)
                       FROM public.bu_user_assignments a
                       WHERE a.tenant_id = v_tenant AND a.user_id = tm.user_id), '[]'::jsonb)) AS choice
      FROM public.tenant_members tm JOIN auth.users u ON u.id = tm.user_id
      WHERE tm.tenant_id = v_tenant AND tm.active
      UNION ALL
      SELECT jsonb_build_object('principal_type', 'group', 'principal_id', g.id,
             'label', g.name, 'bu_ids',
             coalesce((SELECT jsonb_agg(DISTINCT a.bu_id ORDER BY a.bu_id)
                       FROM public.bu_group_assignments a
                       WHERE a.tenant_id = v_tenant AND a.group_id = g.id), '[]'::jsonb)) AS choice
      FROM public.tenant_groups g WHERE g.tenant_id = v_tenant
    ) choices;
  ELSE
    v_bu_choices := '[]'::jsonb;
    v_principal_choices := '[]'::jsonb;
  END IF;
  RETURN jsonb_build_object('recon_id', _recon_id, 'tenant_id', v_tenant,
    'multi_bu_governed', (SELECT d.multi_bu_governed FROM public.recon_definitions d WHERE d.id = _recon_id),
    'is_tenant_admin', v_admin, 'owners', v_owners, 'grants', v_grants, 'effective_access', v_effective,
    'available_business_units', v_bu_choices, 'available_principals', v_principal_choices);
END
$function$

CREATE OR REPLACE FUNCTION public.grant_recon_bu_action(_recon_id uuid, _bu_id uuid, _principal_type text, _principal_id uuid, _action text, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant uuid;
  v_grant_id uuid;
  v_created boolean := false;
BEGIN
  IF v_actor IS NULL OR _recon_id IS NULL OR _bu_id IS NULL OR _principal_id IS NULL
     OR _principal_type IS NULL OR _principal_type NOT IN ('user', 'group')
     OR _action IS NULL OR _action NOT IN ('view', 'read', 'run', 'edit', 'approve')
     OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid access setup request';
  END IF;
  SELECT d.tenant_id INTO v_tenant FROM public.recon_definitions d
  WHERE d.id = _recon_id;
  IF v_tenant IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id = v_tenant AND tm.user_id = v_actor
      AND tm.active AND tm.role = 'tenant_admin'::public.tenant_role
  ) THEN RAISE EXCEPTION 'not authorized'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.recon_definition_business_units m
                 WHERE m.tenant_id = v_tenant AND m.recon_id = _recon_id AND m.bu_id = _bu_id) THEN
    RAISE EXCEPTION 'grant business unit must own this governed reconciliation';
  END IF;
  IF _principal_type = 'user' THEN
    IF NOT EXISTS (SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id = v_tenant
                   AND tm.user_id = _principal_id AND tm.active)
       OR NOT EXISTS (
         SELECT 1 FROM public.business_units target_bu
         JOIN public.bu_user_assignments a ON a.tenant_id = target_bu.tenant_id AND a.user_id = _principal_id
         JOIN public.business_units assigned_bu ON assigned_bu.id = a.bu_id AND assigned_bu.tenant_id = a.tenant_id
         WHERE target_bu.id = _bu_id AND target_bu.tenant_id = v_tenant
           AND (target_bu.id = assigned_bu.id OR (a.inherit_descendants AND target_bu.path <@ assigned_bu.path))
       ) THEN
      RAISE EXCEPTION 'grant user must be active and assigned to the owner business unit';
    END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.tenant_groups g WHERE g.id = _principal_id AND g.tenant_id = v_tenant)
       OR NOT EXISTS (
         SELECT 1 FROM public.business_units target_bu
         JOIN public.bu_group_assignments a ON a.tenant_id = target_bu.tenant_id AND a.group_id = _principal_id
         JOIN public.business_units assigned_bu ON assigned_bu.id = a.bu_id AND assigned_bu.tenant_id = a.tenant_id
         WHERE target_bu.id = _bu_id AND target_bu.tenant_id = v_tenant
           AND (target_bu.id = assigned_bu.id OR (a.inherit_descendants AND target_bu.path <@ assigned_bu.path))
       ) THEN
      RAISE EXCEPTION 'grant group must be in the tenant and assigned to the owner business unit';
    END IF;
  END IF;
  INSERT INTO public.recon_definition_bu_grants(tenant_id, recon_id, bu_id, principal_type, principal_id, action, granted_by)
  VALUES (v_tenant, _recon_id, _bu_id, _principal_type, _principal_id,
          CASE WHEN _action = 'read' THEN 'view' ELSE _action END, v_actor)
  ON CONFLICT (tenant_id, recon_id, bu_id, principal_type, principal_id, action) DO NOTHING
  RETURNING id INTO v_grant_id;
  v_created := v_grant_id IS NOT NULL;
  IF NOT v_created THEN
    SELECT g.id INTO v_grant_id FROM public.recon_definition_bu_grants g
    WHERE g.tenant_id = v_tenant AND g.recon_id = _recon_id AND g.bu_id = _bu_id
      AND g.principal_type = _principal_type AND g.principal_id = _principal_id
      AND g.action = CASE WHEN _action = 'read' THEN 'view' ELSE _action END;
  ELSE
    INSERT INTO public.recon_definition_bu_admin_audit(tenant_id, recon_id, operation, target_id, actor_id, reason, details)
    VALUES (v_tenant, _recon_id, 'grant_action', v_grant_id, v_actor, btrim(_reason),
      jsonb_build_object('bu_id', _bu_id, 'principal_type', _principal_type,
                         'principal_id', _principal_id, 'action', CASE WHEN _action = 'read' THEN 'view' ELSE _action END));
  END IF;
  RETURN v_grant_id;
END
$function$

CREATE OR REPLACE FUNCTION private.rlnext_verified_login_event(_request_id uuid, _user_id uuid, _outcome text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a private.rlnext_accounts; threshold integer; total integer;
BEGIN
 PERFORM private.rlnext_service();
 IF _outcome NOT IN('success','invalid_credentials','mfa_invalid','account_locked') THEN RETURN false; END IF;
 SELECT * INTO a FROM private.rlnext_accounts WHERE user_id=_user_id FOR UPDATE;
 IF a.id IS NULL THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM private.rlnext_audit WHERE account_id=a.id AND context->>'request_id'=_request_id::text) THEN RETURN true; END IF;
 PERFORM private.rlnext_record(a.tenant_id,a.id,a.user_id,CASE WHEN _outcome='success' THEN 'login' ELSE 'failed_login' END,NULL,jsonb_build_object('request_id',_request_id));
 SELECT failed_login_limit INTO threshold FROM private.rlnext_policy WHERE tenant_id=a.tenant_id;
 SELECT count(*) INTO total FROM private.rlnext_audit WHERE account_id=a.id AND event='failed_login' AND occurred_at>clock_timestamp()-interval '15 minutes' AND occurred_at>coalesce((SELECT max(occurred_at) FROM private.rlnext_audit WHERE account_id=a.id AND event='login'),'-infinity'::timestamptz);
 IF total>=coalesce(threshold,5) AND a.status='active' AND NOT public.is_platform_admin(a.user_id) AND NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=a.user_id AND tenant_id<>a.tenant_id) THEN
   UPDATE private.rlnext_accounts SET status='locked',locked_at=clock_timestamp(),lock_reason='Multiple unsuccessful sign-in attempts',version=version+1 WHERE id=a.id;
   PERFORM private.rlnext_record(a.tenant_id,a.id,NULL,'locked'); PERFORM private.rlnext_notice(a.id,'locked'); PERFORM private.rlnext_notice(a.id,'failed_login',NULL,true);
 END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.revoke_recon_bu_action(_grant_id uuid, _reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_grant public.recon_definition_bu_grants%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR _grant_id IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid access setup request';
  END IF;
  SELECT g.* INTO v_grant FROM public.recon_definition_bu_grants g WHERE g.id = _grant_id FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (
    SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id = v_grant.tenant_id AND tm.user_id = v_actor
      AND tm.active AND tm.role = 'tenant_admin'::public.tenant_role
  ) THEN RAISE EXCEPTION 'not authorized'; END IF;
  DELETE FROM public.recon_definition_bu_grants WHERE id = _grant_id;
  INSERT INTO public.recon_definition_bu_admin_audit(tenant_id, recon_id, operation, target_id, actor_id, reason, details)
  VALUES (v_grant.tenant_id, v_grant.recon_id, 'revoke_action', _grant_id, v_actor, btrim(_reason),
    jsonb_build_object('bu_id', v_grant.bu_id, 'principal_type', v_grant.principal_type,
                       'principal_id', v_grant.principal_id, 'action', v_grant.action));
  RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.seed_default_sla_policy(_tenant uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT public.has_tenant_role(auth.uid(), _tenant, 'tenant_admin'::tenant_role)
     AND NOT public.is_platform_admin(auth.uid()) THEN
    RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501';
  END IF;
  SELECT id INTO v_id FROM public.break_sla_policies
    WHERE tenant_id = _tenant AND name = 'Default — Falcon Bank' LIMIT 1;
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  INSERT INTO public.break_sla_policies(
    tenant_id, name, description, first_response_mins, resolution_mins, breach_action,
    escalation_chain, priority
  ) VALUES (
    _tenant, 'Default — Falcon Bank', 'Baseline SLA: 1h first response, 8h resolution, 2-tier escalation',
    60, 480, 'escalate',
    '[{"level":1,"after_mins":30,"notify_role":"tenant_admin"},{"level":2,"after_mins":120,"notify_role":"tenant_admin"}]'::jsonb,
    100
  ) RETURNING id INTO v_id;
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_auth_settle(_id uuid, _user_id uuid, _state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.rlnext_challenges; a private.rlnext_accounts; u auth.users;
BEGIN
 PERFORM private.rlnext_service(); PERFORM pg_advisory_xact_lock(hashtextextended('rlnext:'||coalesce((SELECT tenant_id::text FROM private.rlnext_challenges WHERE id=_id),'unknown'),0)); SELECT * INTO STRICT c FROM private.rlnext_challenges WHERE id=_id FOR UPDATE;
 SELECT * INTO STRICT a FROM private.rlnext_accounts WHERE id=c.account_id FOR UPDATE;
 IF c.create_state<>'claimed' OR c.purpose<>'verify' THEN RETURN jsonb_build_object('ready',false); END IF;
 SELECT * INTO u FROM auth.users WHERE id=_user_id AND lower(email)=a.email AND email_confirmed_at IS NULL AND raw_user_meta_data->>'fvi_lifecycle_request'=_id::text;
 IF _state='created' AND u.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=u.id) THEN
   UPDATE private.rlnext_accounts SET user_id=u.id WHERE id=a.id;
   UPDATE private.rlnext_challenges SET create_state='created' WHERE id=c.id;
   RETURN jsonb_build_object('ready',true);
 END IF;
 UPDATE private.rlnext_challenges SET create_state='uncertain' WHERE id=c.id;
 PERFORM private.rlnext_record(a.tenant_id,a.id,NULL,'signup_held');
 RETURN jsonb_build_object('ready',false);
END $function$

CREATE OR REPLACE FUNCTION public.mkt_put_llm_secret(_provider_id uuid, _secret text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  _name text := 'fvi_mkt_llm_' || _provider_id::text;
  _existing text;
  _vault_id uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF _secret IS NULL OR length(btrim(_secret)) < 8 OR length(_secret) > 8192 THEN
    RAISE EXCEPTION 'invalid secret';
  END IF;
  SELECT api_key_ref INTO _existing FROM public.mkt_llm_providers
    WHERE id = _provider_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'marketing provider not found'; END IF;
  IF _existing IS NOT NULL AND _existing <> _name THEN
    RAISE EXCEPTION 'invalid marketing secret reference';
  END IF;
  SELECT id INTO _vault_id FROM vault.secrets WHERE name = _name;
  IF _vault_id IS NULL THEN
    _vault_id := vault.create_secret(_secret, _name, 'Recon Spark marketing AI provider');
  ELSE
    PERFORM vault.update_secret(_vault_id, _secret, _name, 'Recon Spark marketing AI provider');
  END IF;
  UPDATE public.mkt_llm_providers SET api_key_ref = _name WHERE id = _provider_id;
  RETURN _name;
END;
$function$

CREATE OR REPLACE FUNCTION public.rlnext_begin(_slug text, _email text, _purpose text, _id uuid, _receipt_hash text, _otp_hash text, _profile jsonb, _invitation_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE tenant uuid; a private.rlnext_accounts; p private.rlnext_policy; u auth.users; rate record;
BEGIN
 PERFORM private.rlnext_service();
 IF _purpose NOT IN('verify','unlock','password_reset') OR _email<>lower(trim(_email)) OR _email !~ '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$' OR length(_email)>254
 OR _receipt_hash !~ '^[a-f0-9]{64}$' OR _otp_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid request' USING ERRCODE='22023'; END IF;
 SELECT id INTO tenant FROM public.tenants WHERE slug=_slug;
 PERFORM pg_advisory_xact_lock(hashtextextended('rlnext:'||coalesce(tenant::text,'unknown'),0));
 -- Serialize all challenges for one tenant/email, including different request IDs.
 PERFORM pg_advisory_xact_lock(hashtextextended(coalesce(tenant::text,'')||':'||_email,0));
 IF EXISTS(SELECT 1 FROM private.rlnext_challenges WHERE id=_id) THEN RETURN jsonb_build_object('eligible',false); END IF;
 SELECT * INTO p FROM private.rlnext_policy WHERE tenant_id=tenant;
 SELECT * INTO u FROM auth.users WHERE lower(email)=_email;
 SELECT * INTO a FROM private.rlnext_accounts WHERE tenant_id=tenant AND email=_email FOR UPDATE;
 IF tenant IS NULL OR p.tenant_id IS NULL OR NOT p.enabled OR NOT private.rlnext_domain(tenant,_email) THEN RETURN jsonb_build_object('eligible',false); END IF;
 IF EXISTS(SELECT 1 FROM private.rlnext_challenges c JOIN private.rlnext_accounts q ON q.id=c.account_id
   WHERE q.tenant_id=tenant AND q.email=_email AND c.created_at>clock_timestamp()-interval '1 hour' HAVING count(*)>=3)
 THEN RETURN jsonb_build_object('eligible',false); END IF;
 IF _purpose='verify' THEN
   IF u.id IS NOT NULL OR a.id IS NOT NULL THEN RETURN jsonb_build_object('eligible',false); END IF;
   IF _invitation_hash IS NOT NULL THEN
     UPDATE private.rlnext_invitations SET used_at=clock_timestamp() WHERE token_hash=_invitation_hash AND tenant_id=tenant AND email=_email AND expires_at>clock_timestamp() AND used_at IS NULL;
     IF NOT FOUND THEN RETURN jsonb_build_object('eligible',false); END IF;
   END IF;
   INSERT INTO private.rlnext_accounts(id,tenant_id,email,first_name,last_name,department,employee_id,job_title,status)
   VALUES(_id,tenant,_email,left(coalesce(_profile->>'firstName',''),80),left(coalesce(_profile->>'lastName',''),80),left(coalesce(_profile->>'department',''),120),left(coalesce(_profile->>'employeeId',''),80),left(coalesce(_profile->>'jobTitle',''),120),'pending_verification') RETURNING * INTO a;
 ELSIF u.id IS NULL OR u.email_confirmed_at IS NULL OR public.is_platform_admin(u.id)
   OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=tenant AND user_id=u.id AND active)
   OR EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=u.id AND tenant_id<>tenant)
 THEN RETURN jsonb_build_object('eligible',false);
 ELSE
   IF a.id IS NULL THEN
     INSERT INTO private.rlnext_accounts(id,tenant_id,user_id,email,status,verified_at,assigned)
     VALUES(u.id,tenant,u.id,_email,CASE WHEN u.banned_until>clock_timestamp() THEN 'locked' ELSE 'active' END,u.email_confirmed_at,true) RETURNING * INTO a;
   END IF;
   IF u.banned_until>clock_timestamp() AND a.status='active' THEN UPDATE private.rlnext_accounts SET status='locked',provider_locked=true,lock_reason='Supabase account restriction',locked_at=u.updated_at WHERE id=a.id RETURNING * INTO a; END IF;
   IF (_purpose='unlock' AND a.status<>'locked') OR (_purpose='password_reset' AND a.status NOT IN('active','locked')) THEN RETURN jsonb_build_object('eligible',false); END IF;
   IF a.user_id IS DISTINCT FROM u.id THEN RETURN jsonb_build_object('eligible',false); END IF;
 END IF;
 -- A still-outstanding challenge cannot be bypassed by another tab/key.
 IF EXISTS(SELECT 1 FROM private.rlnext_challenges WHERE account_id=a.id AND used_at IS NULL AND (expires_at>clock_timestamp() OR create_state='uncertain' OR send_state IN('claimed','uncertain') OR reset_state IN('claimed','uncertain')))
 THEN RETURN jsonb_build_object('eligible',false); END IF;
 INSERT INTO private.rlnext_challenges(id,account_id,tenant_id,purpose,receipt_hash,otp_hash,expires_at,max_attempts,max_resends,ttl_seconds,create_state)
 VALUES(_id,a.id,tenant,_purpose,_receipt_hash,_otp_hash,clock_timestamp()+make_interval(secs=>p.ttl_seconds),p.max_attempts,p.max_resends,p.ttl_seconds,CASE WHEN _purpose='verify' THEN 'claimed' ELSE 'none' END);
 PERFORM private.rlnext_record(tenant,a.id,NULL,CASE WHEN _purpose='verify' THEN 'signup' ELSE _purpose||'_requested' END);
 RETURN jsonb_build_object('eligible',true,'create',_purpose='verify');
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_login_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE a private.rlnext_accounts; actor uuid:=auth.uid();
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 SELECT * INTO a FROM private.rlnext_accounts WHERE user_id=actor;
 IF a.id IS NULL THEN RETURN jsonb_build_object('allowed',true,'status','active','reset_required',false,'message',''); END IF;
 IF a.status='active' AND NOT a.reset_required THEN
   PERFORM private.rlnext_record(a.tenant_id,a.id,actor,'login');
 ELSE PERFORM private.rlnext_record(a.tenant_id,a.id,actor,'login_blocked'); END IF;
 RETURN jsonb_build_object('allowed',a.status='active' AND NOT a.reset_required,'status',a.status,'reset_required',a.reset_required,
 'tenant',(SELECT slug FROM public.tenants WHERE id=a.tenant_id),'message',CASE a.status WHEN 'pending_approval' THEN 'Your account is awaiting administrator approval.' WHEN 'pending_verification' THEN 'Verify your email before signing in.' WHEN 'locked' THEN 'Account locked. Use Unlock Account to verify your email and reset your password.' WHEN 'active' THEN CASE WHEN a.reset_required THEN 'Complete your password reset before signing in.' ELSE '' END ELSE 'Your account is unavailable. Contact your tenant administrator.' END);
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_notice_claim(_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE item private.rlnext_notices; output jsonb:='[]'::jsonb; recipient text; slug text;
BEGIN
 PERFORM private.rlnext_service();
 FOR item IN SELECT * FROM private.rlnext_notices WHERE state='ready' ORDER BY created_at,id LIMIT least(10,greatest(1,_limit)) FOR UPDATE SKIP LOCKED LOOP
   SELECT lower(email) INTO recipient FROM auth.users WHERE id=item.recipient_id AND email_confirmed_at IS NOT NULL;
   IF recipient IS NULL OR (item.event IN('pending_approval','failed_login','admin_approved','admin_rejected') AND NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=item.tenant_id AND user_id=item.recipient_id AND active AND role::text='tenant_admin')) OR (item.event NOT IN('pending_approval','failed_login','admin_approved','admin_rejected') AND NOT EXISTS(SELECT 1 FROM private.rlnext_accounts ac WHERE ac.id=item.account_id AND ac.email=recipient AND ac.user_id=item.recipient_id AND private.rlnext_domain(ac.tenant_id,recipient))) THEN
     UPDATE private.rlnext_notices SET state='rejected' WHERE id=item.id; CONTINUE;
   END IF;
   SELECT t.slug INTO slug FROM public.tenants t WHERE id=item.tenant_id;
   item.lease:=gen_random_uuid(); UPDATE private.rlnext_notices SET state='claimed',lease=item.lease,claimed_at=clock_timestamp() WHERE id=item.id;
   output:=output||jsonb_build_array(jsonb_build_object('id',item.id,'lease',item.lease,'to',recipient,'slug',slug,'event',item.event,'reason',item.reason));
 END LOOP;
 RETURN output;
END $function$

CREATE OR REPLACE FUNCTION public.calculate_collateral_vm_call(_tenant_id uuid, _version_id uuid, _valuation_date date, _gross_exposure numeric, _eligible_collateral_held numeric, _idempotency_key text)
 RETURNS TABLE(call_id uuid, call_amount numeric, direction text, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor uuid := auth.uid(); v public.collateral_csa_versions%ROWTYPE; existing public.collateral_csa_calls%ROWTYPE;
  net numeric; raw_call numeric; amount numeric; call_direction text; request_hash text;
BEGIN
  IF NOT public.csa_assurance_actor(_tenant_id,actor) THEN
    RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';
  END IF;
  IF _gross_exposure IS NULL OR _eligible_collateral_held IS NULL OR _eligible_collateral_held < 0 OR _valuation_date IS NULL OR _idempotency_key IS NULL THEN
    RAISE EXCEPTION 'Exposure, collateral, valuation date and idempotency key are required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v FROM public.collateral_csa_versions WHERE tenant_id=_tenant_id AND id=_version_id AND status IN ('active','superseded')
    AND _valuation_date BETWEEN effective_from AND coalesce(effective_to,'infinity'::date);
  IF NOT FOUND THEN RAISE EXCEPTION 'An active agreement version for the valuation date is required' USING ERRCODE='22023'; END IF;
  request_hash := encode(digest(jsonb_build_object('version_id',_version_id,'valuation_date',_valuation_date,
    'gross_exposure',_gross_exposure,'eligible_collateral_held',_eligible_collateral_held)::text,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':'||actor::text||':'||_idempotency_key,0));
  SELECT * INTO existing FROM public.collateral_csa_calls WHERE tenant_id=_tenant_id AND calculated_by=actor AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF existing.request_hash<>request_hash THEN RAISE EXCEPTION 'Idempotency key reused with different call inputs' USING ERRCODE='22023'; END IF;
    RETURN QUERY SELECT existing.id,existing.call_amount,existing.direction,true; RETURN;
  END IF;
  net := _gross_exposure - _eligible_collateral_held;
  raw_call := greatest(abs(net)-v.threshold_amount,0);
  IF raw_call < v.minimum_transfer THEN raw_call := 0; END IF;
  amount := CASE WHEN v.rounding_increment=0 THEN raw_call ELSE round(raw_call/v.rounding_increment)*v.rounding_increment END;
  call_direction := CASE WHEN amount=0 THEN 'none' WHEN net>0 THEN 'counterparty_to_us' ELSE 'us_to_counterparty' END;
  INSERT INTO public.collateral_csa_calls(tenant_id,agreement_id,version_id,idempotency_key,request_hash,valuation_date,
    calculated_by,gross_exposure,eligible_collateral_held,net_exposure,threshold_snapshot,minimum_transfer_snapshot,
    rounding_increment_snapshot,call_amount,direction)
  VALUES(_tenant_id,v.agreement_id,_version_id,_idempotency_key,request_hash,_valuation_date,actor,_gross_exposure,
    _eligible_collateral_held,net,v.threshold_amount,v.minimum_transfer,v.rounding_increment,amount,call_direction)
  RETURNING * INTO existing;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(actor,_tenant_id,'tenant','collateral.vm.call.calculate','collateral_csa_call',existing.id::text,
    jsonb_build_object('version_id',_version_id,'valuation_date',_valuation_date,'gross_exposure',_gross_exposure,
      'eligible_collateral_held',_eligible_collateral_held,'net_exposure',net,'call_amount',amount,'direction',call_direction));
  RETURN QUERY SELECT existing.id,amount,call_direction,false;
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_notice_settle(_id uuid, _lease uuid, _state text, _provider_ref text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 PERFORM private.rlnext_service();
 IF _state NOT IN('accepted','rejected','uncertain') OR (_provider_ref IS NOT NULL AND (_provider_ref !~ '^[A-Za-z0-9_.:-]{1,200}$' OR _provider_ref ~* '(sb_secret_|sb_publishable_|zoho-enczapikey)' OR _provider_ref ~ '^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$')) THEN RAISE EXCEPTION 'Invalid receipt' USING ERRCODE='22023'; END IF;
 UPDATE private.rlnext_notices SET state=_state,provider_ref=_provider_ref WHERE id=_id AND lease=_lease AND state='claimed';
 RETURN FOUND;
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_resend(_id uuid, _receipt_hash text, _otp_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.rlnext_challenges; a private.rlnext_accounts;
BEGIN
 PERFORM private.rlnext_service(); SELECT * INTO c FROM private.rlnext_challenges WHERE id=_id AND receipt_hash=_receipt_hash FOR UPDATE;
 IF c.id IS NULL THEN RETURN jsonb_build_object('ready',false); END IF;
 SELECT * INTO STRICT a FROM private.rlnext_accounts WHERE id=c.account_id;
 IF c.verify_state<>'ready' OR c.used_at IS NOT NULL OR c.send_state IN('claimed','uncertain') OR c.resends>=c.max_resends OR c.created_at<clock_timestamp()-interval '24 hours' OR c.attempts>=c.max_attempts OR NOT private.rlnext_domain(a.tenant_id,a.email) OR (c.purpose='verify' AND a.status<>'pending_verification') OR (c.purpose='unlock' AND a.status<>'locked') OR (c.purpose='password_reset' AND a.status NOT IN('active','locked'))
 THEN RETURN jsonb_build_object('ready',false); END IF;
 IF c.last_sent_at>clock_timestamp()-interval '60 seconds' THEN RETURN jsonb_build_object('ready',false,'retry_after',60); END IF;
 UPDATE private.rlnext_challenges SET otp_hash=_otp_hash,expires_at=clock_timestamp()+make_interval(secs=>ttl_seconds),resends=resends+1,send_state='ready' WHERE id=c.id;
 PERFORM private.rlnext_record(a.tenant_id,a.id,NULL,'code_resent');
 RETURN jsonb_build_object('ready',true);
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_reset_claim(_id uuid, _receipt_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.rlnext_challenges; a private.rlnext_accounts; pw text;
BEGIN
 PERFORM private.rlnext_service(); SELECT * INTO c FROM private.rlnext_challenges WHERE id=_id AND reset_hash=_receipt_hash FOR UPDATE;
 IF c.id IS NULL THEN RETURN '{}'::jsonb; END IF;
 IF c.reset_state='complete' THEN RETURN jsonb_build_object('completed',true); END IF;
 SELECT * INTO STRICT a FROM private.rlnext_accounts WHERE id=c.account_id FOR UPDATE;
 IF c.reset_state<>'ready' OR c.reset_expires_at<=clock_timestamp() OR a.status NOT IN('active','locked') OR NOT a.reset_required OR NOT private.rlnext_domain(a.tenant_id,a.email)
 OR public.is_platform_admin(a.user_id) OR EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=a.user_id AND tenant_id<>a.tenant_id)
 THEN RETURN '{}'::jsonb; END IF;
 SELECT md5(encrypted_password) INTO pw FROM auth.users WHERE id=a.user_id AND lower(email)=a.email AND email_confirmed_at IS NOT NULL;
 IF pw IS NULL THEN RETURN '{}'::jsonb; END IF;
 UPDATE private.rlnext_challenges SET reset_state='claimed',password_before=pw WHERE id=c.id;
 RETURN jsonb_build_object('user_id',a.user_id);
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_reset_finish(_id uuid, _provider_ok boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.rlnext_challenges; a private.rlnext_accounts;
BEGIN
 PERFORM private.rlnext_service(); SELECT * INTO STRICT c FROM private.rlnext_challenges WHERE id=_id FOR UPDATE;
 SELECT * INTO STRICT a FROM private.rlnext_accounts WHERE id=c.account_id FOR UPDATE;
 IF c.reset_state='complete' THEN RETURN jsonb_build_object('completed',true); END IF;
 IF c.reset_state NOT IN('claimed','uncertain') OR a.status NOT IN('active','locked') OR NOT private.rlnext_domain(a.tenant_id,a.email) THEN RETURN jsonb_build_object('completed',false); END IF;
 -- No password hash returned. A changed provider-owned password is required even on lost response.
 IF EXISTS(SELECT 1 FROM auth.users WHERE id=a.user_id AND lower(email)=a.email AND md5(encrypted_password) IS DISTINCT FROM c.password_before AND encrypted_password IS NOT NULL)
 THEN
   UPDATE auth.users SET banned_until=NULL WHERE id=a.user_id AND banned_until>clock_timestamp();
   UPDATE private.rlnext_accounts SET status='active',reset_required=false,provider_locked=false,lock_reason=NULL,locked_at=NULL,version=version+1 WHERE id=a.id;
   UPDATE private.rlnext_challenges SET reset_state='complete',password_before=NULL WHERE id=c.id;
   PERFORM private.rlnext_record(a.tenant_id,a.id,NULL,'password_reset');
   PERFORM private.rlnext_notice(a.id,'reset_completed');
   IF c.purpose='unlock' THEN PERFORM private.rlnext_notice(a.id,'unlocked'); END IF;
   RETURN jsonb_build_object('completed',true);
 END IF;
 UPDATE private.rlnext_challenges SET reset_state='uncertain' WHERE id=c.id;
 RETURN jsonb_build_object('completed',false);
END $function$

CREATE OR REPLACE FUNCTION public.tg_snapshot_recon_run_definition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE definition_row public.recon_definitions%ROWTYPE; source_rows jsonb;
  approved_version integer; approved_hash text;
BEGIN
  IF TG_OP='UPDATE' THEN
    IF NEW.definition_snapshot IS DISTINCT FROM OLD.definition_snapshot THEN
      RAISE EXCEPTION 'reconciliation run definition snapshot is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.tenant_id IS DISTINCT FROM OLD.tenant_id OR NEW.definition_id IS DISTINCT FROM OLD.definition_id THEN
      RAISE EXCEPTION 'reconciliation run scope is immutable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
  END IF;
  SELECT * INTO definition_row FROM public.recon_definitions WHERE id=NEW.definition_id AND tenant_id=NEW.tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'reconciliation definition does not belong to run tenant' USING ERRCODE='23503'; END IF;
  SELECT jsonb_agg(jsonb_build_object('side_id',side.value->>'side_id','data_source_id',side.value->>'data_source_id',
      'name',ds.name,'source_type',ds.source_type) ORDER BY side.ordinality)
    INTO source_rows FROM jsonb_array_elements(definition_row.sides) WITH ORDINALITY AS side(value,ordinality)
    LEFT JOIN public.workspace_data_sources ds ON ds.id::text=side.value->>'data_source_id' AND ds.tenant_id=NEW.tenant_id;
  IF definition_row.governance_state IN ('approved_locked','edit_request_pending') THEN
    SELECT version_number,snapshot_sha256 INTO approved_version,approved_hash
      FROM public.recon_definition_approved_versions WHERE tenant_id=NEW.tenant_id
        AND parent_definition_id=definition_row.id
      ORDER BY version_number DESC LIMIT 1;
  END IF;
  NEW.definition_snapshot:=jsonb_build_object(
    'name',definition_row.name,'recon_type',definition_row.recon_type,'sides',definition_row.sides,
    'rules',definition_row.rules,'sources',COALESCE(source_rows,'[]'::jsonb),
    'governance_state',definition_row.governance_state,'access_mode',definition_row.access_mode,
    'approved_version',approved_version,'approved_sha256',approved_hash
  );
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_resolve(_domain text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE slug text;
BEGIN
 PERFORM private.rlnext_service();
 SELECT t.slug INTO slug FROM public.tenant_email_domains d JOIN public.tenants t ON t.id=d.tenant_id JOIN private.rlnext_policy p ON p.tenant_id=t.id
 WHERE d.domain::text=lower(_domain) AND d.status='verified' AND p.enabled AND private.rlnext_domain(t.id,'resolve@'||lower(_domain));
 RETURN jsonb_build_object('slug',slug);
END $function$

CREATE OR REPLACE FUNCTION private.resource_actor_display_label(_tenant_id uuid, _actor_id uuid, _actor_status text)
 RETURNS TABLE(label text, status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_active boolean;
  v_full_name text;
BEGIN
  IF _actor_id IS NULL AND _actor_status = 'unattributed' THEN
    RETURN QUERY SELECT 'Unattributed'::text, 'unattributed'::text;
    RETURN;
  END IF;
  IF _actor_id IS NULL AND _actor_status IS NULL THEN
    RETURN QUERY SELECT 'Unknown'::text, 'unknown'::text;
    RETURN;
  END IF;
  IF _actor_status <> 'authenticated_user' OR _actor_id IS NULL THEN
    IF _actor_status = 'authenticated_user' THEN
      RETURN QUERY SELECT 'Unavailable'::text, 'removed'::text;
    ELSE
      RETURN QUERY SELECT 'Unknown'::text, 'unknown'::text;
    END IF;
    RETURN;
  END IF;

  -- Profiles are global rows; expose a name only through an active membership
  -- in the resource tenant. Never select or return the profile email.
  SELECT tm.active, p.full_name
  INTO v_active, v_full_name
  FROM public.tenant_members tm
  LEFT JOIN public.profiles p ON p.id = tm.user_id
  WHERE tm.tenant_id = _tenant_id AND tm.user_id = _actor_id
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 'Unavailable'::text, 'removed'::text;
  ELSIF NOT coalesce(v_active, false) THEN
    RETURN QUERY SELECT 'Inactive user'::text, 'inactive'::text;
  ELSE
    v_full_name := left(nullif(btrim(regexp_replace(coalesce(v_full_name, ''), '[[:cntrl:]]', '', 'g')), ''), 120);
    IF v_full_name IS NULL
       OR v_full_name ~* '(^|[[:space:]])[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+($|[[:space:]])'
       OR v_full_name ~* '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}' THEN
      RETURN QUERY SELECT 'Unknown'::text, 'unknown'::text;
    ELSE
      RETURN QUERY SELECT v_full_name, 'known'::text;
    END IF;
  END IF;
END
$function$

CREATE OR REPLACE FUNCTION public.rlnext_send(_id uuid, _action text, _state text, _provider_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.rlnext_challenges; a private.rlnext_accounts;
BEGIN
 PERFORM private.rlnext_service(); SELECT * INTO STRICT c FROM private.rlnext_challenges WHERE id=_id FOR UPDATE;
 SELECT * INTO STRICT a FROM private.rlnext_accounts WHERE id=c.account_id;
 IF _action='claim' THEN
   IF c.send_state<>'ready' OR c.verify_state<>'ready' OR c.expires_at<=clock_timestamp() OR NOT private.rlnext_domain(a.tenant_id,a.email) OR (c.purpose='verify' AND c.create_state<>'created') THEN RETURN jsonb_build_object('send',false); END IF;
   UPDATE private.rlnext_challenges SET send_state='claimed',last_sent_at=clock_timestamp() WHERE id=c.id;
   RETURN jsonb_build_object('send',true,'to',a.email);
 ELSIF _action='settle' AND c.send_state='claimed' AND _state IN('accepted','rejected','uncertain') THEN
   IF _provider_ref IS NOT NULL AND (_provider_ref !~ '^[A-Za-z0-9_.:-]{1,200}$' OR _provider_ref ~* '(sb_secret_|sb_publishable_|zoho-enczapikey)' OR _provider_ref ~ '^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$') THEN RAISE EXCEPTION 'Invalid receipt' USING ERRCODE='22023'; END IF;
   UPDATE private.rlnext_challenges SET send_state=_state,provider_ref=_provider_ref WHERE id=c.id;
   PERFORM private.rlnext_record(a.tenant_id,a.id,NULL,'email_'||_state,NULL,jsonb_build_object('request_id',c.id));
   RETURN jsonb_build_object('settled',true);
 END IF;
 RETURN jsonb_build_object('settled',false);
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_verify(_id uuid, _receipt_hash text, _otp_hash text, _reset_hash text, _reset_expires bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.rlnext_challenges; a private.rlnext_accounts;
BEGIN
 PERFORM private.rlnext_service(); SELECT * INTO c FROM private.rlnext_challenges WHERE id=_id AND receipt_hash=_receipt_hash FOR UPDATE;
 IF c.id IS NULL THEN RETURN jsonb_build_object('valid',false); END IF;
 SELECT * INTO STRICT a FROM private.rlnext_accounts WHERE id=c.account_id FOR UPDATE;
 IF c.verify_state<>'ready' OR c.used_at IS NOT NULL OR c.expires_at<=clock_timestamp() OR c.attempts>=c.max_attempts OR c.send_state NOT IN('accepted','uncertain') OR NOT private.rlnext_domain(a.tenant_id,a.email)
 OR NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=a.user_id AND lower(u.email)=a.email AND (c.purpose='verify' OR u.email_confirmed_at IS NOT NULL))
 OR (c.purpose='verify' AND (a.status<>'pending_verification' OR a.user_id IS NULL)) OR (c.purpose='unlock' AND a.status<>'locked') OR (c.purpose='password_reset' AND a.status NOT IN('active','locked'))
 THEN RETURN jsonb_build_object('valid',false); END IF;
 UPDATE private.rlnext_challenges SET attempts=attempts+1 WHERE id=c.id;
 IF c.otp_hash<>_otp_hash THEN
   UPDATE private.rlnext_challenges SET verify_state=CASE WHEN attempts>=max_attempts THEN 'exhausted' ELSE 'ready' END WHERE id=c.id;
   PERFORM private.rlnext_record(a.tenant_id,a.id,NULL,'code_rejected'); RETURN jsonb_build_object('valid',false);
 END IF;
 UPDATE private.rlnext_challenges SET used_at=clock_timestamp(),verify_state=CASE WHEN purpose='verify' THEN 'claimed' ELSE 'complete' END,
   reset_hash=CASE WHEN purpose='verify' THEN NULL ELSE _reset_hash END,reset_state=CASE WHEN purpose='verify' THEN 'none' ELSE 'ready' END,reset_expires_at=CASE WHEN _reset_expires IS NULL THEN clock_timestamp()+interval '15 minutes' ELSE to_timestamp(_reset_expires::double precision/1000) END WHERE id=c.id;
 IF c.purpose<>'verify' THEN
   UPDATE private.rlnext_accounts SET reset_required=true,version=version+1 WHERE id=a.id;
   PERFORM private.rlnext_record(a.tenant_id,a.id,NULL,'email_proof_accepted');
 END IF;
 RETURN jsonb_build_object('valid',true,'user_id',a.user_id);
END $function$

CREATE OR REPLACE FUNCTION public.validate_data_resource_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.principal_type = 'user' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.tenant_members tm
      WHERE tm.tenant_id = NEW.tenant_id AND tm.user_id = NEW.principal_id AND tm.active
    ) THEN RAISE EXCEPTION 'grant user must be an active member of the same tenant'; END IF;
  ELSIF NOT EXISTS (
    SELECT 1 FROM public.tenant_groups g
    WHERE g.tenant_id = NEW.tenant_id AND g.id = NEW.principal_id
  ) THEN RAISE EXCEPTION 'grant group must belong to the same tenant';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.audit_data_resource_owner_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r public.data_resource_business_unit_owners%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN r := OLD; ELSE r := NEW; END IF;
  INSERT INTO public.data_resource_owner_audit
    (tenant_id, resource_type, resource_id, bu_id, operation, changed_by)
  VALUES (r.tenant_id, r.resource_type, r.resource_id, r.bu_id, TG_OP, auth.uid());
