CREATE OR REPLACE FUNCTION public.seed_profile_name_from_tenant_invites()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  seeded text;
BEGIN
  IF NEW.email IS NULL THEN RETURN NEW; END IF;
  IF NEW.full_name IS NOT NULL AND btrim(NEW.full_name) <> '' THEN RETURN NEW; END IF;

  SELECT btrim(full_name) INTO seeded
  FROM public.tenant_invitations
  WHERE lower(email::text) = lower(NEW.email)
    AND accepted_at IS NULL
    AND expires_at > now()
    AND full_name IS NOT NULL
    AND btrim(full_name) <> ''
  ORDER BY created_at DESC
  LIMIT 1;

  IF seeded IS NOT NULL THEN
    NEW.full_name := seeded;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_erts(p_spec jsonb, p_domain text DEFAULT 'default'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  errors jsonb := '[]'::jsonb;
  recon_pts int := 0;
  ai_pts int := 0;
  gov_pts int := 0;
  has_sources bool; has_targets bool; has_rules bool; has_workflows bool; has_dash bool; has_reg bool;
  ai_keys text[] := ARRAY['mapping','matching','reconciliation','exceptions','insights','recommendations'];
  k text; ai_count int := 0;
BEGIN
  IF p_spec IS NULL OR jsonb_typeof(p_spec) <> 'object' THEN
    RETURN jsonb_build_object('valid',false,'errors',jsonb_build_array('spec_missing_or_not_object'),
      'scores', jsonb_build_object('recon',0,'ai',0,'governance',0,'certification',0));
  END IF;

  has_sources := jsonb_typeof(p_spec #> '{data_model,sources}') = 'array' AND jsonb_array_length(p_spec #> '{data_model,sources}') > 0;
  has_targets := jsonb_typeof(p_spec #> '{data_model,targets}') = 'array' AND jsonb_array_length(p_spec #> '{data_model,targets}') > 0;
  has_rules := jsonb_typeof(p_spec #> '{matching,rules}') = 'array' AND jsonb_array_length(p_spec #> '{matching,rules}') > 0;
  has_workflows := jsonb_typeof(p_spec #> '{exceptions,workflows}') = 'array' AND jsonb_array_length(p_spec #> '{exceptions,workflows}') > 0;
  has_dash := jsonb_typeof(p_spec #> '{reporting,dashboards}') = 'array' AND jsonb_array_length(p_spec #> '{reporting,dashboards}') > 0;
  has_reg := (p_spec #> '{reporting,regulatory_reports}') IS NOT NULL;

  IF NOT has_sources THEN errors := errors || to_jsonb('missing:data_model.sources'::text); END IF;
  IF NOT has_targets THEN errors := errors || to_jsonb('missing:data_model.targets'::text); END IF;
  IF NOT has_rules THEN errors := errors || to_jsonb('missing:matching.rules'::text); END IF;
  IF NOT has_workflows THEN errors := errors || to_jsonb('missing:exceptions.workflows'::text); END IF;
  IF NOT has_dash THEN errors := errors || to_jsonb('missing:reporting.dashboards'::text); END IF;

  recon_pts := (CASE WHEN has_sources THEN 20 ELSE 0 END)
             + (CASE WHEN has_targets THEN 15 ELSE 0 END)
             + (CASE WHEN has_rules THEN 30 ELSE 0 END)
             + (CASE WHEN has_workflows THEN 20 ELSE 0 END)
             + (CASE WHEN has_dash THEN 15 ELSE 0 END);

  FOREACH k IN ARRAY ai_keys LOOP
    IF (p_spec #> ARRAY['ai',k]) IS NOT NULL AND jsonb_typeof(p_spec #> ARRAY['ai',k]) = 'object' THEN
      ai_count := ai_count + 1;
    END IF;
  END LOOP;
  ai_pts := LEAST(100, (ai_count * 100) / 6);

  gov_pts := (CASE WHEN (p_spec #> '{governance,rbac_roles_required}') IS NOT NULL THEN 25 ELSE 0 END)
           + (CASE WHEN (p_spec #> '{governance,rls_scope}') IS NOT NULL THEN 25 ELSE 0 END)
           + (CASE WHEN (p_spec #> '{governance,audit_binding}')::text = 'true' THEN 25 ELSE 0 END)
           + (CASE WHEN (p_spec #> '{reconciliation,risk_controls}') IS NOT NULL THEN 25 ELSE 0 END);

  RETURN jsonb_build_object(
    'valid', has_sources AND has_targets AND has_rules AND has_workflows AND has_dash,
    'errors', errors,
    'scores', jsonb_build_object(
      'recon', recon_pts,
      'ai', ai_pts,
      'governance', gov_pts,
      'certification', ((recon_pts * 5) + (ai_pts * 3) + (gov_pts * 2)) / 10
    )
  );
END $function$

CREATE OR REPLACE FUNCTION public.trg_mkt_version_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v jsonb; s jsonb;
  dom text;
BEGIN
  SELECT COALESCE(t.domain_key, 'default') INTO dom FROM public.mkt_templates t WHERE t.id = NEW.template_id;
  s := public.validate_erts(NEW.spec, dom);
  NEW.spec_valid := (s->>'valid')::boolean;
  NEW.spec_errors := s->'errors';
  NEW.recon_score := (s#>>'{scores,recon}')::int;
  NEW.ai_score := (s#>>'{scores,ai}')::int;
  NEW.governance_score := (s#>>'{scores,governance}')::int;
  NEW.certification_score := (s#>>'{scores,certification}')::int;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.prevent_registered_resource_tenant_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_resource_type text; v_column text; v_lock_key bigint; v_registered boolean;
BEGIN
  IF NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id THEN RETURN NEW; END IF;
  CASE TG_TABLE_NAME
    WHEN 'workspace_data_sources' THEN v_resource_type := 'data_source'; v_column := 'data_source_id';
    WHEN 'rekon_db_connections' THEN v_resource_type := 'db_connection'; v_column := 'db_connection_id';
    WHEN 'rekon_inline_api_sources' THEN v_resource_type := 'inline_api_source'; v_column := 'inline_api_source_id';
    WHEN 'erp_connector_configs' THEN v_resource_type := 'erp_connection'; v_column := 'erp_connection_id';
    WHEN 'data_watchers' THEN v_resource_type := 'file_watcher'; v_column := 'file_watcher_id';
    WHEN 'aidp_templates' THEN v_resource_type := 'aidp_template'; v_column := 'aidp_template_id';
    WHEN 'aidp_documents' THEN v_resource_type := 'aidp_document'; v_column := 'aidp_document_id';
    WHEN 'reference_data_tables' THEN v_resource_type := 'reference_table'; v_column := 'reference_table_id';
    WHEN 'data_prep_pipelines' THEN v_resource_type := 'data_prep_pipeline'; v_column := 'data_prep_pipeline_id';
    WHEN 'tenant_groups' THEN v_resource_type := 'principal_group'; v_column := NULL;
  END CASE;
  IF v_resource_type = 'principal_group' THEN
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fvi-principal-group:' || OLD.id::text, 0));
    IF EXISTS (SELECT 1 FROM public.data_resource_registry_grants WHERE principal_group_id = OLD.id) THEN
      RAISE EXCEPTION 'tenant cannot change while the group has retained resource grants';
    END IF;
    RETURN NEW;
  END IF;
  v_lock_key := pg_catalog.hashtextextended('fvi-resource:' || v_resource_type || ':' || OLD.id::text, 0);
  PERFORM pg_catalog.pg_advisory_xact_lock(v_lock_key);
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.data_resource_registry WHERE %I = $1)', v_column)
    INTO v_registered USING OLD.id;
  IF v_registered THEN RAISE EXCEPTION 'tenant cannot change for a registered resource'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.tg_github_sync_cr_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
BEGIN
  -- Terminal states are immutable
  IF TG_OP = 'UPDATE' AND OLD.status IN ('applied','rejected','cancelled') THEN
    RAISE EXCEPTION 'github_sync change request % is terminal (status=%) and cannot be modified',
      OLD.id, OLD.status;
  END IF;

  -- Self-approval and duplicate-approver prevention
  IF NEW.approver_1 IS NOT NULL AND NEW.approver_1 = NEW.requested_by THEN
    RAISE EXCEPTION 'requester cannot be approver_1 (4-eyes violation)';
  END IF;
  IF NEW.approver_2 IS NOT NULL AND NEW.approver_2 = NEW.requested_by THEN
    RAISE EXCEPTION 'requester cannot be approver_2 (4-eyes violation)';
  END IF;
  IF NEW.approver_1 IS NOT NULL AND NEW.approver_2 IS NOT NULL
     AND NEW.approver_1 = NEW.approver_2 THEN
    RAISE EXCEPTION 'approver_1 and approver_2 must be distinct (4-eyes violation)';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_last_tenant_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_remaining int;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_tenant := OLD.tenant_id;
    IF OLD.role::text <> 'tenant_admin' THEN RETURN OLD; END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    v_tenant := NEW.tenant_id;
    -- Only fire if losing admin status or being deactivated
    IF NEW.active = OLD.active AND NEW.role = OLD.role THEN RETURN NEW; END IF;
    IF OLD.role::text <> 'tenant_admin' THEN RETURN NEW; END IF;
  END IF;

  SELECT count(*) INTO v_remaining
  FROM public.tenant_members
  WHERE tenant_id = v_tenant
    AND role::text = 'tenant_admin'
    AND active = true
    AND id <> COALESCE(NEW.id, OLD.id);

  IF v_remaining = 0 THEN
    RAISE EXCEPTION 'Cannot remove last active tenant_admin for tenant %', v_tenant
      USING ERRCODE = '23514', HINT = 'Promote another member to tenant_admin first.';
  END IF;

  RETURN COALESCE(NEW, OLD);
END $function$

CREATE OR REPLACE FUNCTION public.audit_data_resource_registry_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.data_resource_registry_owner_bu%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN r := OLD; ELSE r := NEW; END IF;
  INSERT INTO public.data_resource_registry_owner_audit(tenant_id, registry_id, bu_id, operation, changed_by)
  VALUES (r.tenant_id, r.registry_id, r.bu_id, TG_OP, auth.uid());
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.validate_data_resource_registry_grant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_group_tenant uuid;
BEGIN
  IF NEW.principal_type = 'user' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.tenant_members tm
      WHERE tm.tenant_id = NEW.tenant_id AND tm.user_id = NEW.principal_user_id AND tm.active
    ) THEN RAISE EXCEPTION 'grant user must be an active member of the same tenant'; END IF;
  ELSE
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended('fvi-principal-group:' || NEW.principal_group_id::text, 0)
    );
    SELECT g.tenant_id INTO v_group_tenant
    FROM public.tenant_groups g WHERE g.id = NEW.principal_group_id FOR SHARE;
    IF v_group_tenant IS NULL OR v_group_tenant <> NEW.tenant_id THEN
      RAISE EXCEPTION 'grant group must belong to the same tenant';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.purge_test_tenant(_tenant_id uuid, _spec_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _slug text;
BEGIN
  SELECT slug INTO _slug
  FROM public.tenants
  WHERE id = _tenant_id AND slug ~ '-[0-9]{13}$';

  IF _slug IS NULL THEN
    INSERT INTO public.test_tenant_lifecycle_audit (tenant_id, tenant_slug, event, spec_name, notes)
    VALUES (_tenant_id, NULL, 'purge_failed', _spec_name,
            jsonb_build_object('reason','non-test slug or not found'));
    RAISE EXCEPTION 'purge_test_tenant: refusing to delete non-test tenant %', _tenant_id
      USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.test_tenant_lifecycle_audit (tenant_id, tenant_slug, event, spec_name, notes)
  VALUES (_tenant_id, _slug, 'purge', _spec_name, '{}'::jsonb);

  ALTER TABLE public.tenant_members DISABLE TRIGGER USER;
  DELETE FROM public.tenants WHERE id = _tenant_id;
  ALTER TABLE public.tenant_members ENABLE TRIGGER USER;
END $function$

CREATE OR REPLACE FUNCTION public.evaluate_ai_drift(p_model_id uuid, p_window_hours integer DEFAULT 24)
 RETURNS ai_governance_drift_baselines
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_baseline public.ai_governance_drift_baselines;
  v_observed public.ai_governance_drift_baselines;
  v_now timestamptz := now();
  v_avg numeric(5,4); v_p05 numeric(5,4); v_hitl numeric(5,4); v_n integer;
BEGIN
  SELECT tenant_id INTO v_tenant FROM public.ai_governance_models WHERE id = p_model_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'model not found'; END IF;

  SELECT count(*)::int,
         avg(confidence)::numeric(5,4),
         percentile_cont(0.05) WITHIN GROUP (ORDER BY confidence)::numeric(5,4),
         (count(*) FILTER (WHERE hitl_required) :: numeric / GREATEST(count(*),1))::numeric(5,4)
  INTO v_n, v_avg, v_p05, v_hitl
  FROM public.ai_governance_prompt_log
  WHERE model_id = p_model_id
    AND created_at >= v_now - make_interval(hours => p_window_hours);

  INSERT INTO public.ai_governance_drift_baselines(tenant_id, model_id, window_start, window_end,
    sample_count, avg_confidence, p05_confidence, hitl_rate, is_baseline)
  VALUES (v_tenant, p_model_id, v_now - make_interval(hours => p_window_hours), v_now,
    COALESCE(v_n,0), v_avg, v_p05, v_hitl, false)
  RETURNING * INTO v_observed;

  SELECT * INTO v_baseline FROM public.ai_governance_drift_baselines
    WHERE model_id = p_model_id AND is_baseline = true
    ORDER BY created_at DESC LIMIT 1;

  IF v_baseline.id IS NOT NULL AND v_baseline.avg_confidence IS NOT NULL AND v_observed.avg_confidence IS NOT NULL THEN
    IF abs(v_observed.avg_confidence - v_baseline.avg_confidence) / NULLIF(v_baseline.avg_confidence, 0) > 0.15 THEN
      INSERT INTO public.ai_governance_drift_alerts(tenant_id, model_id, baseline_id, severity, metric,
        baseline_value, observed_value, delta_pct)
      VALUES (v_tenant, p_model_id, v_baseline.id,
        CASE WHEN abs(v_observed.avg_confidence - v_baseline.avg_confidence) / v_baseline.avg_confidence > 0.30 THEN 'high' ELSE 'medium' END,
        'avg_confidence', v_baseline.avg_confidence, v_observed.avg_confidence,
        (v_observed.avg_confidence - v_baseline.avg_confidence) / v_baseline.avg_confidence * 100);
    END IF;
  END IF;

  RETURN v_observed;
END $function$

CREATE OR REPLACE FUNCTION public.tg_retention_override_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE pol record;
BEGIN
  SELECT retention_days, floor_days, configurable
    INTO pol
    FROM public.retention_policies
   WHERE table_name = NEW.table_name;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'retention_policies has no row for %', NEW.table_name USING ERRCODE = '23514';
  END IF;
  IF pol.configurable = false THEN
    RAISE EXCEPTION 'retention for % is not tenant-configurable', NEW.table_name USING ERRCODE = '42501';
  END IF;
  IF pol.floor_days IS NOT NULL AND NEW.retention_days < pol.floor_days THEN
    RAISE EXCEPTION 'retention_days % is below floor of % for %', NEW.retention_days, pol.floor_days, NEW.table_name USING ERRCODE = '23514';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.claim_regulatory_install(_install_id uuid)
 RETURNS TABLE(claimed boolean, install_row jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r jsonb;
  v_old_status text;
  v_tenant uuid;
  v_actor uuid;
BEGIN
  SELECT status, tenant_id, installed_by
    INTO v_old_status, v_tenant, v_actor
    FROM public.regulatory_pack_installs
   WHERE id = _install_id
   FOR UPDATE;

  UPDATE public.regulatory_pack_installs
     SET status = 'materializing'
   WHERE id = _install_id
     AND status IN ('installing','pending','materializing')
  RETURNING to_jsonb(regulatory_pack_installs.*) INTO r;

  IF r IS NOT NULL AND v_old_status IS DISTINCT FROM 'materializing' THEN
    INSERT INTO public.audit_log(
      actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
    ) VALUES (
      v_actor, v_tenant, 'tenant',
      'regulatory.install.transition',
      'regulatory_pack_installs', _install_id::text,
      jsonb_build_object(
        'from', v_old_status, 'to', 'materializing',
        'transitioned_at', now(), 'worker', 'regulatory-install-worker'
      )
    );
  END IF;

  RETURN QUERY SELECT (r IS NOT NULL), r;
END $function$

CREATE OR REPLACE FUNCTION public.resolve_entitlement(_tenant_id uuid, _catalog_key text, _user_id uuid DEFAULT NULL::uuid, _workspace_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _row public.entitlement_catalog%ROWTYPE;
  _dep text;
  _platform boolean;
  _tenant boolean;
  _ws boolean;
  _user boolean;
  _group boolean;
BEGIN
  SELECT * INTO _row FROM public.entitlement_catalog WHERE key = _catalog_key AND is_active = true;
  IF NOT FOUND THEN RETURN false; END IF;
  FOREACH _dep IN ARRAY _row.requires LOOP
    IF NOT public.resolve_entitlement(_tenant_id, _dep, _user_id, _workspace_id) THEN RETURN false; END IF;
  END LOOP;
  IF _row.parent_key IS NOT NULL THEN
    IF NOT public.resolve_entitlement(_tenant_id, _row.parent_key, _user_id, _workspace_id) THEN RETURN false; END IF;
  END IF;
  SELECT allowed INTO _platform FROM public.tenant_feature_entitlements
    WHERE tenant_id = _tenant_id AND feature_key = _catalog_key LIMIT 1;
  IF _platform IS NULL THEN _platform := _row.default_enabled; END IF;
  IF NOT _platform THEN RETURN false; END IF;
  SELECT enabled INTO _tenant FROM public.entitlement_scope_grants
    WHERE tenant_id = _tenant_id AND catalog_key = _catalog_key AND scope_type='tenant' LIMIT 1;
  IF _tenant IS NOT NULL AND NOT _tenant THEN RETURN false; END IF;
  IF _workspace_id IS NOT NULL THEN
    SELECT enabled INTO _ws FROM public.entitlement_scope_grants
      WHERE tenant_id = _tenant_id AND catalog_key = _catalog_key AND scope_type='workspace' AND scope_id = _workspace_id LIMIT 1;
    IF _ws IS NOT NULL AND NOT _ws THEN RETURN false; END IF;
  END IF;
  IF _user_id IS NOT NULL THEN
    SELECT enabled INTO _user FROM public.entitlement_scope_grants
      WHERE tenant_id = _tenant_id AND catalog_key = _catalog_key AND scope_type='user' AND scope_id = _user_id LIMIT 1;
    IF _user IS NOT NULL THEN RETURN _user; END IF;
    SELECT bool_and(g.enabled) INTO _group FROM public.entitlement_scope_grants g
      JOIN public.tenant_group_members tgm ON tgm.group_id = g.scope_id
      WHERE g.tenant_id = _tenant_id AND g.catalog_key = _catalog_key AND g.scope_type='group' AND tgm.user_id = _user_id;
    IF _group IS NOT NULL AND NOT _group THEN RETURN false; END IF;
  END IF;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_log_chain()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_prev bytea;
  v_payload text;
  v_session_role text;
  v_system_action boolean;
begin
  select last_hash into v_prev
  from public.audit_chain_head
  where singleton = true
  for update;

  new.prev_hash := v_prev;
  v_session_role := current_setting('role', true);

  if v_session_role = 'authenticated' then
    if auth.uid() is null then
      raise exception 'audit_log: authenticated actor is missing'
        using errcode = 'check_violation';
    end if;
    new.actor_user_id := auth.uid();
    if new.tenant_id is not null
       and not public.is_tenant_member(auth.uid(), new.tenant_id)
       and not public.is_platform_admin(auth.uid()) then
      raise exception 'audit_log: tenant attribution is not authorized'
        using errcode = 'insufficient_privilege';
    end if;
  else
    new.actor_user_id := coalesce(new.actor_user_id, auth.uid());
  end if;

  v_system_action := (
    new.actor_user_id is not null
    or v_session_role in ('service_role', 'postgres')
    or new.scope = 'system'
    or new.action like 'cron.%'
    or new.action like 'webhook.%'
    or new.action like 'system.%'
    or new.action like 'scim.%'
    or new.action like 'retention.%'
    or new.action like 'backup.%'
    or new.action like 'recon.evidence_pack.%'
  );
  if not v_system_action then
    raise exception 'audit_log: actor_user_id required for non-system action "%" (scope=%)', new.action, new.scope
      using errcode = 'check_violation';
  end if;

  v_payload := coalesce(encode(v_prev,'hex'),'') || '|' ||
               coalesce(new.actor_user_id::text,'') || '|' ||
               coalesce(new.tenant_id::text,'') || '|' || new.scope || '|' || new.action || '|' ||
               coalesce(new.resource_type,'') || '|' || coalesce(new.resource_id,'') || '|' ||
               coalesce(new.context::text,'{}') || '|' || new.occurred_at::text;
  new.row_hash := digest(v_payload, 'sha256');

  update public.audit_chain_head
  set last_audit_id = new.id,
      last_hash = new.row_hash,
      updated_at = now()
  where singleton = true;

  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.worm_append(_tenant_id uuid, _evidence_type text, _resource_type text, _resource_id text, _sha256 text, _size_bytes bigint, _object_url text, _bucket_name text, _retention_days integer)
 RETURNS worm_evidence_ledger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  _prev text;
  _chain text;
  _row public.worm_evidence_ledger;
begin
  if not (public.has_tenant_role(auth.uid(), _tenant_id, 'tenant_admin')
       or public.is_platform_admin(auth.uid())) then
    raise exception 'Forbidden: tenant_admin required';
  end if;
  select chain_hash into _prev
    from public.worm_evidence_ledger
   where tenant_id = _tenant_id
   order by recorded_at desc, id desc
   limit 1;
  _chain := encode(
    digest(coalesce(_prev,'') || '|' || _sha256 || '|' || _evidence_type
           || '|' || coalesce(_resource_id,''), 'sha256'),
    'hex');
  insert into public.worm_evidence_ledger
    (tenant_id, evidence_type, resource_type, resource_id, sha256, size_bytes,
     object_url, bucket_name, object_lock_until, prev_hash, chain_hash, recorded_by)
  values
    (_tenant_id, _evidence_type, _resource_type, _resource_id, _sha256, _size_bytes,
     _object_url, _bucket_name,
     case when _retention_days is null then null
          else now() + make_interval(days => _retention_days) end,
     _prev, _chain, auth.uid())
  returning * into _row;
  return _row;
end $function$

CREATE OR REPLACE FUNCTION public.agent_actions_no_self_approve()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  requester_id uuid;
BEGIN
  IF NEW.approved_by IS NULL THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.approved_by IS NOT DISTINCT FROM NEW.approved_by THEN
    RETURN NEW;
  END IF;
  SELECT user_id INTO requester_id FROM public.agent_runs WHERE id = NEW.run_id;
  IF requester_id IS NOT NULL AND requester_id = NEW.approved_by THEN
    RAISE EXCEPTION 'agent.self_approve_blocked'
      USING HINT = 'Approver must differ from the user who started the agent run.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.recon_matches_audit_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_by uuid;
  v_reason text;
BEGIN
  BEGIN
    v_deleted_by := NULLIF(current_setting('app.deleted_by', true), '')::uuid;
  EXCEPTION WHEN others THEN
    v_deleted_by := NULL;
  END;
  BEGIN
    v_reason := NULLIF(current_setting('app.delete_reason', true), '');
  EXCEPTION WHEN others THEN
    v_reason := NULL;
  END;

  INSERT INTO public.recon_match_deletions (
    match_id, tenant_id, run_id, deleted_by, reason, snapshot
  )
  VALUES (
    OLD.id, OLD.tenant_id, OLD.run_id, v_deleted_by, v_reason,
    to_jsonb(OLD)
  );
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.worker_check_breaker(_tenant uuid, _scope worker_breaker_scope, _target uuid)
 RETURNS TABLE(allow boolean, state worker_breaker_state, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.worker_circuit_breakers%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.worker_circuit_breakers
   WHERE tenant_id = _tenant AND scope = _scope AND target_id = _target FOR UPDATE;
  IF NOT FOUND THEN RETURN QUERY SELECT true, 'closed'::public.worker_breaker_state, 0; RETURN; END IF;
  IF v_row.state = 'closed' THEN RETURN QUERY SELECT true, v_row.state, 0; RETURN; END IF;
  IF v_row.state = 'open' AND v_row.next_probe_at IS NOT NULL AND now() >= v_row.next_probe_at THEN
    UPDATE public.worker_circuit_breakers SET state = 'half_open', updated_at = now() WHERE id = v_row.id;
    INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (NULL, _tenant, 'tenant', 'worker.breaker.half_open', _scope::text, _target::text, '{}'::jsonb);
    RETURN QUERY SELECT true, 'half_open'::public.worker_breaker_state, 0; RETURN;
  END IF;
  IF v_row.state = 'open' THEN
    RETURN QUERY SELECT false, v_row.state,
      GREATEST(0, EXTRACT(EPOCH FROM (COALESCE(v_row.next_probe_at, now()) - now()))::int);
    RETURN;
  END IF;
  RETURN QUERY SELECT true, v_row.state, 0;
END $function$

CREATE OR REPLACE FUNCTION public.purge_expired_data()
 RETURNS TABLE(t_name text, t_tenant uuid, t_deleted bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; d bigint;
BEGIN
  FOR r IN SELECT id FROM public.tenants LOOP
    WITH del AS (DELETE FROM public.ai_usage_events
       WHERE tenant_id = r.id AND created_at < now() - make_interval(days => public.effective_retention_days(r.id,'ai_usage_events'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'ai_usage_events'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.security_events
       WHERE tenant_id = r.id AND occurred_at < now() - make_interval(days => public.effective_retention_days(r.id,'security_events'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'security_events'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.recon_runs
       WHERE tenant_id = r.id AND started_at < now() - make_interval(days => public.effective_retention_days(r.id,'recon_runs'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'recon_runs'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.recon_exceptions
       WHERE tenant_id = r.id AND created_at < now() - make_interval(days => public.effective_retention_days(r.id,'recon_exceptions'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'recon_exceptions'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.recon_matches
       WHERE tenant_id = r.id AND created_at < now() - make_interval(days => public.effective_retention_days(r.id,'recon_matches'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'recon_matches'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.aidp_pages p USING public.aidp_documents dd
       WHERE p.document_id = dd.id AND dd.tenant_id = r.id
         AND p.created_at < now() - make_interval(days => public.effective_retention_days(r.id,'aidp_pages'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'aidp_pages'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;

    WITH del AS (DELETE FROM public.aidp_output_recon_invalidations
       WHERE tenant_id = r.id AND created_at < now() - make_interval(days => public.effective_retention_days(r.id,'aidp_output_recon_invalidations'))
      RETURNING 1) SELECT count(*) INTO d FROM del;
    IF d > 0 THEN t_name := 'aidp_output_recon_invalidations'; t_tenant := r.id; t_deleted := d; RETURN NEXT; END IF;
  END LOOP;

  WITH del AS (DELETE FROM public.email_send_log
     WHERE created_at < now() - make_interval(days => COALESCE((SELECT retention_days FROM public.retention_policies WHERE table_name='email_send_log'), 365))
    RETURNING 1) SELECT count(*) INTO d FROM del;
  IF d > 0 THEN t_name := 'email_send_log'; t_tenant := NULL; t_deleted := d; RETURN NEXT; END IF;

  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.status_subscribe(_email text, _component_keys text[], _confirm_token text, _unsub_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  _bucket_key text;
  _window timestamptz := date_trunc('hour', now());
  _cur int;
BEGIN
  IF _email IS NULL OR length(_email) > 254
     OR _email !~* '^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$' THEN
    RAISE EXCEPTION 'invalid email';
  END IF;
  IF _confirm_token IS NULL OR length(_confirm_token) < 32
     OR _unsub_token IS NULL OR length(_unsub_token) < 32 THEN
    RAISE EXCEPTION 'invalid token';
  END IF;

  -- Rate-limit: max 3 subscription attempts per email per hour.
  _bucket_key := 'status_subscribe:' || lower(_email);
  INSERT INTO public.rate_limit_buckets(bucket_key, window_start, count)
  VALUES (_bucket_key, _window, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET count = public.rate_limit_buckets.count + 1
  RETURNING count INTO _cur;
  IF _cur > 3 THEN
    RAISE EXCEPTION 'rate_limited' USING ERRCODE = '42901';
  END IF;

  INSERT INTO public.status_subscribers(
    email, component_keys, confirm_token_hash, unsubscribe_token_hash
  ) VALUES (
    lower(_email),
    COALESCE(_component_keys, '{}'::text[]),
    extensions.digest(convert_to(_confirm_token,'UTF8'),'sha256'),
    extensions.digest(convert_to(_unsub_token,'UTF8'),'sha256')
  )
  ON CONFLICT (email) DO NOTHING;
  RETURN FOUND;
END $function$

CREATE OR REPLACE FUNCTION public.status_unsubscribe(_token text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE deleted int;
BEGIN
  DELETE FROM public.status_subscribers
   WHERE unsubscribe_token_hash = sha256(convert_to(_token,'UTF8'));
  GET DIAGNOSTICS deleted = ROW_COUNT;
  RETURN deleted > 0;
END $function$

CREATE OR REPLACE FUNCTION public.platform_user_analytics(_window_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_window int := GREATEST(1, LEAST(_window_days, 365));
  v_cutoff timestamptz := now() - make_interval(days => v_window);
  v_total int; v_active int; v_inactive int; v_never int;
  v_mfa int; v_sso int;
  v_per_tenant jsonb; v_trend jsonb;
BEGIN
  IF v_caller IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT public.is_platform_admin(v_caller) THEN
    RAISE EXCEPTION 'Forbidden: platform_admin required';
  END IF;

  SELECT
    COUNT(*)::int,
    COUNT(*) FILTER (WHERE last_sign_in_at >= v_cutoff)::int,
    COUNT(*) FILTER (WHERE last_sign_in_at IS NOT NULL AND last_sign_in_at < v_cutoff)::int,
    COUNT(*) FILTER (WHERE last_sign_in_at IS NULL)::int
  INTO v_total, v_active, v_inactive, v_never FROM auth.users;

  SELECT COUNT(DISTINCT user_id)::int INTO v_mfa FROM auth.mfa_factors WHERE status = 'verified';
  SELECT COUNT(DISTINCT user_id)::int INTO v_sso FROM auth.identities WHERE provider <> 'email';

  SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.active_users DESC NULLS LAST), '[]'::jsonb)
    INTO v_per_tenant
  FROM (
    SELECT
      t.id AS tenant_id, t.name, t.slug,
      COUNT(DISTINCT tm.user_id)::int AS total_users,
      COUNT(DISTINCT tm.user_id) FILTER (WHERE u.last_sign_in_at >= v_cutoff)::int AS active_users,
      COUNT(DISTINCT tm.user_id) FILTER (WHERE u.last_sign_in_at IS NULL)::int AS never_signed_in,
      COUNT(DISTINCT tm.user_id) FILTER (WHERE u.id IN (SELECT user_id FROM auth.mfa_factors WHERE status='verified'))::int AS mfa_users,
      COUNT(DISTINCT tm.user_id) FILTER (WHERE u.id IN (SELECT user_id FROM auth.identities WHERE provider <> 'email'))::int AS sso_users
    FROM public.tenants t
    LEFT JOIN public.tenant_members tm ON tm.tenant_id = t.id
    LEFT JOIN auth.users u ON u.id = tm.user_id
    GROUP BY t.id, t.name, t.slug
  ) x;

  SELECT COALESCE(jsonb_agg(jsonb_build_object('day', day, 'signins', signins) ORDER BY day), '[]'::jsonb)
    INTO v_trend
  FROM (
    SELECT d::date AS day,
           (SELECT COUNT(*)::int FROM auth.users WHERE last_sign_in_at::date = d::date) AS signins
    FROM generate_series(v_cutoff::date, now()::date, interval '1 day') d
  ) s;

  INSERT INTO public.audit_log(actor_user_id, scope, action, resource_type, resource_id, context)
  VALUES (v_caller, 'platform', 'analytics.users.viewed', 'platform', 'platform',
          jsonb_build_object('window_days', v_window));

  RETURN jsonb_build_object(
    'window_days', v_window,
    'totals', jsonb_build_object(
      'total', v_total, 'active', v_active, 'inactive', v_inactive, 'never_signed_in', v_never,
      'mfa_enrolled', v_mfa, 'sso_users', v_sso
    ),
    'per_tenant', v_per_tenant, 'trend', v_trend, 'generated_at', now()
  );
END $function$

CREATE OR REPLACE FUNCTION private.rlnext_base_public_has_permission_abac(_user_id uuid, _permission text, _tenant_id uuid, _attributes jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_pred record; v_attr_val text;
BEGIN
  IF NOT public.has_permission(_user_id, _permission, _tenant_id, 'tenant', NULL) THEN RETURN false; END IF;
  FOR v_pred IN
    SELECT attribute, operator, values FROM public.rbac_abac_predicates
    WHERE tenant_id = _tenant_id AND permission_id = _permission AND enabled = true
  LOOP
    v_attr_val := _attributes ->> v_pred.attribute;
    IF v_pred.operator = 'in' THEN
      IF v_attr_val IS NULL OR NOT (v_pred.values ? v_attr_val) THEN RETURN false; END IF;
    ELSIF v_pred.operator = 'not_in' THEN
      IF v_attr_val IS NOT NULL AND (v_pred.values ? v_attr_val) THEN RETURN false; END IF;
    ELSIF v_pred.operator = 'equals' THEN
      IF v_attr_val IS DISTINCT FROM (v_pred.values ->> 0) THEN RETURN false; END IF;
    END IF;
  END LOOP;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.worker_breaker_reset(_breaker_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_row public.worker_circuit_breakers%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM public.worker_circuit_breakers WHERE id = _breaker_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF NOT (public.has_tenant_role(auth.uid(), v_row.tenant_id, 'tenant_admin') OR public.is_platform_admin(auth.uid())) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  UPDATE public.worker_circuit_breakers
     SET state = 'closed', consecutive_failures = 0, opened_at = NULL,
         next_probe_at = NULL, updated_at = now()
   WHERE id = _breaker_id;
  INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
  VALUES (auth.uid(), v_row.tenant_id, 'tenant', 'worker.breaker.manual_reset',
          v_row.scope::text, v_row.target_id::text, '{}'::jsonb);
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.sla_evaluate_breaches()
 RETURNS TABLE(exception_id uuid, action text, level integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r record; v_policy public.break_sla_policies%ROWTYPE; v_step jsonb; v_next_level int; v_after_mins int;
BEGIN
  FOR r IN
    SELECT t.* FROM public.break_sla_timers t
    JOIN public.recon_exceptions e ON e.id = t.exception_id
    WHERE t.resolved_at IS NULL AND t.paused_at IS NULL
      AND e.status NOT IN ('resolved','closed','written_off')
  LOOP
    SELECT * INTO v_policy FROM public.break_sla_policies WHERE id = r.policy_id;
    IF NOT FOUND THEN CONTINUE; END IF;

    IF NOT r.breached AND now() > r.due_resolution_at THEN
      UPDATE public.break_sla_timers SET breached = true, breached_at = now() WHERE id = r.id;
      INSERT INTO public.break_sla_events(tenant_id, exception_id, timer_id, event_type, context)
        VALUES (r.tenant_id, r.exception_id, r.id, 'breached',
                jsonb_build_object('due_resolution_at', r.due_resolution_at));
      exception_id := r.exception_id; action := 'breached'; level := r.escalation_level; RETURN NEXT;
    END IF;

    v_next_level := r.escalation_level + 1;
    v_step := (SELECT s FROM jsonb_array_elements(v_policy.escalation_chain) s
                WHERE (s->>'level')::int = v_next_level LIMIT 1);
    IF v_step IS NOT NULL THEN
      v_after_mins := COALESCE((v_step->>'after_mins')::int, 0);
      IF now() >= r.started_at + make_interval(mins => v_after_mins) THEN
        UPDATE public.break_sla_timers
           SET escalation_level = v_next_level, last_escalated_at = now()
         WHERE id = r.id;
        INSERT INTO public.break_sla_events(tenant_id, exception_id, timer_id, event_type, level, context)
          VALUES (r.tenant_id, r.exception_id, r.id, 'escalated', v_next_level, v_step);

        IF (v_step ? 'notify_user_id') THEN
          INSERT INTO public.notifications(user_id, tenant_id, kind, title, body, link_to, severity, context)
          VALUES ((v_step->>'notify_user_id')::uuid, r.tenant_id, 'sla_escalated',
                  'SLA escalation L' || v_next_level,
                  'Exception ' || r.exception_id::text || ' escalated to level ' || v_next_level,
                  '/exceptions/' || r.exception_id::text, 'high',
                  jsonb_build_object('exception_id', r.exception_id, 'level', v_next_level));
        END IF;

        exception_id := r.exception_id; action := 'escalated'; level := v_next_level; RETURN NEXT;
      END IF;
    END IF;
  END LOOP;
  RETURN;
END $function$

CREATE OR REPLACE FUNCTION public.sla_business_due_at(_start timestamp with time zone, _sla_minutes integer, _mic_code text DEFAULT 'XNYS'::text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_remaining integer := _sla_minutes;
  v_cursor timestamptz := _start;
  v_step integer; v_dow integer; v_is_holiday boolean;
  v_cal_id uuid;
BEGIN
  SELECT id INTO v_cal_id FROM public.market_calendars
   WHERE mic_code = _mic_code AND tenant_id IS NULL
   ORDER BY id LIMIT 1;
  WHILE v_remaining > 0 LOOP
    v_dow := EXTRACT(ISODOW FROM v_cursor)::int;
    v_is_holiday := false;
    IF v_cal_id IS NOT NULL THEN
      SELECT EXISTS(SELECT 1 FROM public.market_holidays
        WHERE calendar_id = v_cal_id AND holiday_date = v_cursor::date) INTO v_is_holiday;
    END IF;
    IF v_dow >= 6 OR v_is_holiday THEN
      v_cursor := date_trunc('day', v_cursor) + interval '1 day';
      CONTINUE;
    END IF;
    v_step := LEAST(v_remaining, 60);
    v_cursor := v_cursor + (v_step || ' minutes')::interval;
    v_remaining := v_remaining - v_step;
  END LOOP;
  RETURN v_cursor;
END $function$

CREATE OR REPLACE FUNCTION public.try_llm_test_rate_limit(_user_id uuid, _scope text, _max integer, _window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  bkey text;
  wstart timestamptz;
  cur integer;
BEGIN
  wstart := date_trunc('minute', now()) - ((extract(epoch FROM now())::int % _window_seconds) * interval '1 second');
  bkey := 'llm.test:' || _scope || ':' || _user_id::text;
  INSERT INTO public.rate_limit_buckets (bucket_key, window_start, count)
  VALUES (bkey, wstart, 1)
  ON CONFLICT (bucket_key, window_start) DO UPDATE SET count = public.rate_limit_buckets.count + 1
  RETURNING count INTO cur;
  RETURN cur <= _max;
END;
$function$

CREATE OR REPLACE FUNCTION public.try_llm_rate_limit_pair(_user_id uuid, _tenant_id uuid, _scope text, _user_max integer, _user_window_seconds integer, _tenant_max integer, _tenant_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private'
AS $function$
DECLARE
  user_key text;
  tenant_key text;
  user_row private.llm_test_rate_bucket%ROWTYPE;
  tenant_row private.llm_test_rate_bucket%ROWTYPE;
  now_ts timestamptz := now();
BEGIN
  IF _user_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'exceeded', 'user', 'reason', 'missing user');
  END IF;

  user_key := 'u:' || _user_id::text || ':' || coalesce(_scope, 'platform') || ':' || coalesce(_tenant_id::text, '-');
  tenant_key := 't:' || coalesce(_scope, 'platform') || ':' || coalesce(_tenant_id::text, 'platform');

  -- USER BUCKET
  SELECT * INTO user_row FROM private.llm_test_rate_bucket WHERE bucket_key = user_key FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO private.llm_test_rate_bucket(bucket_key, window_started_at, count)
      VALUES (user_key, now_ts, 0)
      RETURNING * INTO user_row;
  END IF;
  IF now_ts - user_row.window_started_at >= make_interval(secs => _user_window_seconds) THEN
    UPDATE private.llm_test_rate_bucket
      SET window_started_at = now_ts, count = 0
      WHERE bucket_key = user_key
      RETURNING * INTO user_row;
  END IF;
  IF user_row.count >= _user_max THEN
    RETURN jsonb_build_object(
      'ok', false, 'exceeded', 'user',
      'user_max', _user_max, 'user_window_seconds', _user_window_seconds,
      'tenant_max', _tenant_max, 'tenant_window_seconds', _tenant_window_seconds
    );
  END IF;

  -- TENANT/GLOBAL BUCKET
  SELECT * INTO tenant_row FROM private.llm_test_rate_bucket WHERE bucket_key = tenant_key FOR UPDATE;
  IF NOT FOUND THEN
    INSERT INTO private.llm_test_rate_bucket(bucket_key, window_started_at, count)
      VALUES (tenant_key, now_ts, 0)
      RETURNING * INTO tenant_row;
  END IF;
  IF now_ts - tenant_row.window_started_at >= make_interval(secs => _tenant_window_seconds) THEN
    UPDATE private.llm_test_rate_bucket
      SET window_started_at = now_ts, count = 0
      WHERE bucket_key = tenant_key
      RETURNING * INTO tenant_row;
  END IF;
  IF tenant_row.count >= _tenant_max THEN
    RETURN jsonb_build_object(
      'ok', false, 'exceeded', 'tenant',
      'user_max', _user_max, 'user_window_seconds', _user_window_seconds,
      'tenant_max', _tenant_max, 'tenant_window_seconds', _tenant_window_seconds
    );
  END IF;

  -- Both buckets have room — increment atomically.
  UPDATE private.llm_test_rate_bucket SET count = count + 1 WHERE bucket_key = user_key;
  UPDATE private.llm_test_rate_bucket SET count = count + 1 WHERE bucket_key = tenant_key;

  RETURN jsonb_build_object('ok', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.rlnext_verify_finish(_id uuid, _confirmed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.rlnext_challenges; a private.rlnext_accounts;
BEGIN
 PERFORM private.rlnext_service();
 PERFORM pg_advisory_xact_lock(hashtextextended('rlnext:'||coalesce((SELECT tenant_id::text FROM private.rlnext_challenges WHERE id=_id),'unknown'),0));
 SELECT * INTO STRICT c FROM private.rlnext_challenges WHERE id=_id FOR UPDATE;
 SELECT * INTO STRICT a FROM private.rlnext_accounts WHERE id=c.account_id FOR UPDATE;
 IF c.purpose<>'verify' OR c.verify_state<>'claimed' THEN RETURN jsonb_build_object('held',true); END IF;
 IF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=a.user_id AND lower(email)=a.email AND email_confirmed_at IS NOT NULL) OR NOT private.rlnext_domain(a.tenant_id,a.email) THEN RETURN jsonb_build_object('held',true); END IF;
 UPDATE private.rlnext_accounts SET verified_at=clock_timestamp(),status='pending_verification',mfa_required=true,version=version+1 WHERE id=a.id;
 UPDATE private.rlnext_challenges SET verify_state='complete' WHERE id=c.id;
 PERFORM private.rlnext_record(a.tenant_id,a.id,a.user_id,'email_verified');
 -- No approval queue notification or membership before genuine provider MFA.
 RETURN jsonb_build_object('onboarding_required',true,'onboarding_user_id',a.user_id);
END $function$

CREATE OR REPLACE FUNCTION public.set_typed_data_resource_owners(_registry_id uuid, _owner_bu_ids uuid[], _reason text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_tenant uuid; v_new uuid[]; v_old uuid[];
BEGIN
  IF v_actor IS NULL OR _registry_id IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid typed resource owner request';
  END IF;
  SELECT tenant_id INTO v_tenant FROM public.data_resource_registry WHERE id=_registry_id FOR UPDATE;
  IF v_tenant IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=v_tenant AND tm.user_id=v_actor
      AND tm.active AND tm.role='tenant_admin'::public.tenant_role
  ) THEN RAISE EXCEPTION 'not authorized'; END IF;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_new
    FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) x;
  IF EXISTS (SELECT 1 FROM unnest(v_new) x LEFT JOIN public.business_units b
      ON b.id=x AND b.tenant_id=v_tenant AND NOT b.is_archived WHERE b.id IS NULL) THEN
    RAISE EXCEPTION 'owner business units must be active in the resource tenant';
  END IF;
  SELECT coalesce(array_agg(bu_id ORDER BY bu_id),ARRAY[]::uuid[]) INTO v_old
    FROM public.data_resource_registry_owner_bu WHERE tenant_id=v_tenant AND registry_id=_registry_id;
  IF EXISTS (SELECT 1 FROM public.data_resource_registry_grants g WHERE g.tenant_id=v_tenant
      AND g.registry_id=_registry_id AND NOT (g.bu_id=ANY(v_new))) THEN
    RAISE EXCEPTION 'revoke grants for removed owner business units first';
  END IF;
  DELETE FROM public.data_resource_registry_owner_bu o WHERE o.tenant_id=v_tenant AND o.registry_id=_registry_id
    AND NOT (o.bu_id=ANY(v_new));
  INSERT INTO public.data_resource_registry_owner_bu(tenant_id,registry_id,bu_id,created_by)
  SELECT v_tenant,_registry_id,x,v_actor FROM unnest(v_new) x
  ON CONFLICT (tenant_id,registry_id,bu_id) DO NOTHING;
  INSERT INTO public.data_resource_registry_admin_audit(tenant_id,registry_id,operation,actor_id,reason,details)
  VALUES(v_tenant,_registry_id,'REPLACE_OWNERS',v_actor,btrim(_reason),jsonb_build_object('previous_owner_bu_ids',v_old,'new_owner_bu_ids',v_new));
  RETURN v_new;
END
$function$

CREATE OR REPLACE FUNCTION public.register_typed_data_resource(_resource_type text, _resource_id uuid, _owner_bu_ids uuid[], _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant uuid;
  v_registry_id uuid;
  v_bu_ids uuid[];
BEGIN
  IF v_actor IS NULL OR _resource_id IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid typed resource registration request';
  END IF;
  IF _resource_type NOT IN ('data_source','db_connection','inline_api_source','erp_connection',
      'file_watcher','aidp_template','aidp_document','reference_table','data_prep_pipeline','tenant_template','collateral_schedule') THEN
    RAISE EXCEPTION 'unsupported typed resource';
  END IF;
  v_bu_ids := (SELECT coalesce(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) FROM unnest(coalesce(_owner_bu_ids, ARRAY[]::uuid[])) x);
  IF cardinality(v_bu_ids) = 0 THEN RAISE EXCEPTION 'at least one explicit owner business unit is required'; END IF;

  CASE _resource_type
    WHEN 'data_source' THEN SELECT tenant_id INTO v_tenant FROM public.workspace_data_sources WHERE id = _resource_id FOR SHARE;
    WHEN 'db_connection' THEN SELECT tenant_id INTO v_tenant FROM public.rekon_db_connections WHERE id = _resource_id FOR SHARE;
    WHEN 'inline_api_source' THEN SELECT tenant_id INTO v_tenant FROM public.rekon_inline_api_sources WHERE id = _resource_id FOR SHARE;
    WHEN 'erp_connection' THEN SELECT tenant_id INTO v_tenant FROM public.erp_connector_configs WHERE id = _resource_id FOR SHARE;
    WHEN 'file_watcher' THEN SELECT tenant_id INTO v_tenant FROM public.data_watchers WHERE id = _resource_id FOR SHARE;
    WHEN 'aidp_template' THEN SELECT tenant_id INTO v_tenant FROM public.aidp_templates WHERE id = _resource_id FOR SHARE;
    WHEN 'aidp_document' THEN SELECT tenant_id INTO v_tenant FROM public.aidp_documents WHERE id = _resource_id FOR SHARE;
    WHEN 'reference_table' THEN SELECT tenant_id INTO v_tenant FROM public.reference_data_tables WHERE id = _resource_id FOR SHARE;
    WHEN 'data_prep_pipeline' THEN SELECT tenant_id INTO v_tenant FROM public.data_prep_pipelines WHERE id = _resource_id FOR SHARE;
    WHEN 'tenant_template' THEN SELECT tenant_id INTO v_tenant FROM public.tenant_templates WHERE id = _resource_id FOR SHARE;
    WHEN 'collateral_schedule' THEN SELECT tenant_id INTO v_tenant FROM public.collateral_schedules WHERE id = _resource_id FOR SHARE;
  END CASE;
  IF v_tenant IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id = v_tenant AND tm.user_id = v_actor
      AND tm.active AND tm.role = 'tenant_admin'::public.tenant_role
  ) THEN RAISE EXCEPTION 'not authorized'; END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_bu_ids) x LEFT JOIN public.business_units b
      ON b.id = x AND b.tenant_id = v_tenant AND NOT b.is_archived
    WHERE b.id IS NULL
  ) THEN RAISE EXCEPTION 'owner business units must be active in the resource tenant'; END IF;

  -- Use exact typed FK columns; no caller-supplied table or column name is interpolated.
  IF _resource_type = 'data_source' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,data_source_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'db_connection' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,db_connection_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'inline_api_source' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,inline_api_source_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'erp_connection' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,erp_connection_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'file_watcher' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,file_watcher_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'aidp_template' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,aidp_template_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'aidp_document' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,aidp_document_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'reference_table' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,reference_table_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'data_prep_pipeline' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,data_prep_pipeline_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'tenant_template' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,tenant_template_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  ELSIF _resource_type = 'collateral_schedule' THEN
    INSERT INTO public.data_resource_registry(tenant_id,resource_type,collateral_schedule_id,created_by) VALUES(v_tenant,_resource_type,_resource_id,v_actor) RETURNING id INTO v_registry_id;
  END IF;
  IF v_registry_id IS NULL THEN RAISE EXCEPTION 'resource already registered or could not be registered'; END IF;
  INSERT INTO public.data_resource_registry_owner_bu(tenant_id,registry_id,bu_id,created_by)
  SELECT v_tenant,v_registry_id,x,v_actor FROM unnest(v_bu_ids) x;
  INSERT INTO public.data_resource_registry_admin_audit(tenant_id,registry_id,operation,actor_id,reason,details)
  VALUES(v_tenant,v_registry_id,'REGISTER',v_actor,btrim(_reason),jsonb_build_object('resource_type',_resource_type,'resource_id',_resource_id,'owner_bu_ids',v_bu_ids));
  RETURN v_registry_id;
END
$function$

CREATE OR REPLACE FUNCTION public.grant_typed_data_resource_action(_registry_id uuid, _bu_id uuid, _principal_type text, _principal_id uuid, _action text, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_tenant uuid; v_grant_id uuid;
BEGIN
  IF v_actor IS NULL OR _registry_id IS NULL OR _bu_id IS NULL OR _principal_id IS NULL
    OR _principal_type IS NULL OR _principal_type NOT IN ('user','group')
    OR _action IS NULL OR _action NOT IN ('view','ingest','run','edit','manage','approve')
    OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid typed resource grant request';
  END IF;
  SELECT tenant_id INTO v_tenant FROM public.data_resource_registry WHERE id=_registry_id;
  IF v_tenant IS NULL OR NOT EXISTS (SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=v_tenant
      AND tm.user_id=v_actor AND tm.active AND tm.role='tenant_admin'::public.tenant_role) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.data_resource_registry_owner_bu o JOIN public.business_units b
      ON b.id=o.bu_id AND b.tenant_id=o.tenant_id AND NOT b.is_archived
      WHERE o.tenant_id=v_tenant AND o.registry_id=_registry_id AND o.bu_id=_bu_id) THEN
    RAISE EXCEPTION 'grant business unit must actively own the typed resource';
  END IF;
  IF _principal_type='user' THEN
    IF NOT EXISTS (SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=v_tenant AND tm.user_id=_principal_id AND tm.active)
      OR NOT EXISTS (SELECT 1 FROM public.bu_user_assignments a JOIN public.business_units assigned
        ON assigned.id=a.bu_id AND assigned.tenant_id=a.tenant_id AND NOT assigned.is_archived
        JOIN public.business_units target ON target.id=_bu_id AND target.tenant_id=v_tenant AND NOT target.is_archived
        WHERE a.tenant_id=v_tenant AND a.user_id=_principal_id
          AND (assigned.id=target.id OR (a.inherit_descendants AND target.path <@ assigned.path))) THEN
      RAISE EXCEPTION 'grant user must be active and assigned to the owner business unit';
    END IF;
    IF _action='approve' AND _principal_id=v_actor THEN RAISE EXCEPTION 'self-approval grant is forbidden'; END IF;
  ELSE
    IF NOT EXISTS (SELECT 1 FROM public.tenant_groups g WHERE g.id=_principal_id AND g.tenant_id=v_tenant)
      OR NOT EXISTS (SELECT 1 FROM public.bu_group_assignments a JOIN public.business_units assigned
        ON assigned.id=a.bu_id AND assigned.tenant_id=a.tenant_id AND NOT assigned.is_archived
        JOIN public.business_units target ON target.id=_bu_id AND target.tenant_id=v_tenant AND NOT target.is_archived
        WHERE a.tenant_id=v_tenant AND a.group_id=_principal_id
          AND (assigned.id=target.id OR (a.inherit_descendants AND target.path <@ assigned.path))) THEN
      RAISE EXCEPTION 'grant group must be active in the tenant and assigned to the owner business unit';
    END IF;
    IF _action='approve' AND EXISTS (SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=_principal_id AND gm.user_id=v_actor) THEN
      RAISE EXCEPTION 'self-approval group grant is forbidden';
    END IF;
  END IF;
  INSERT INTO public.data_resource_registry_grants(tenant_id,registry_id,bu_id,principal_type,principal_user_id,principal_group_id,action,granted_by)
  VALUES(v_tenant,_registry_id,_bu_id,_principal_type,
    CASE WHEN _principal_type='user' THEN _principal_id END,
    CASE WHEN _principal_type='group' THEN _principal_id END,_action,v_actor)
  ON CONFLICT DO NOTHING RETURNING id INTO v_grant_id;
  IF v_grant_id IS NULL THEN
    SELECT id INTO v_grant_id FROM public.data_resource_registry_grants WHERE tenant_id=v_tenant AND registry_id=_registry_id
      AND bu_id=_bu_id AND principal_type=_principal_type AND action=_action
      AND ((_principal_type='user' AND principal_user_id=_principal_id) OR (_principal_type='group' AND principal_group_id=_principal_id));
  END IF;
  INSERT INTO public.data_resource_registry_admin_audit(tenant_id,registry_id,operation,actor_id,reason,details)
  VALUES(v_tenant,_registry_id,'GRANT_ACTION',v_actor,btrim(_reason),jsonb_build_object('grant_id',v_grant_id,'bu_id',_bu_id,'principal_type',_principal_type,'principal_id',_principal_id,'action',_action));
  RETURN v_grant_id;
END
$function$

CREATE OR REPLACE FUNCTION public.revoke_typed_data_resource_action(_grant_id uuid, _reason text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_actor uuid := auth.uid(); v_grant public.data_resource_registry_grants%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR _grant_id IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid typed resource revoke request';
  END IF;
  SELECT * INTO v_grant FROM public.data_resource_registry_grants WHERE id=_grant_id FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=v_grant.tenant_id
      AND tm.user_id=v_actor AND tm.active AND tm.role='tenant_admin'::public.tenant_role) THEN RAISE EXCEPTION 'not authorized'; END IF;
  DELETE FROM public.data_resource_registry_grants WHERE id=_grant_id;
  INSERT INTO public.data_resource_registry_admin_audit(tenant_id,registry_id,operation,actor_id,reason,details)
  VALUES(v_grant.tenant_id,v_grant.registry_id,'REVOKE_ACTION',v_actor,btrim(_reason),jsonb_build_object('grant_id',v_grant.id,'bu_id',v_grant.bu_id,'principal_type',v_grant.principal_type,'principal_id',coalesce(v_grant.principal_user_id,v_grant.principal_group_id),'action',v_grant.action));
  RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.prevent_registered_schedule_tenant_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF NEW.tenant_id IS NOT DISTINCT FROM OLD.tenant_id THEN RETURN NEW; END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('fvi-resource:data_source_schedule:'||OLD.id::text,0));
  IF EXISTS(SELECT 1 FROM public.data_resource_registry r WHERE r.data_source_schedule_id=OLD.id) THEN
    RAISE EXCEPTION 'tenant cannot change for a registered resource';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.get_data_resource_access_summary(_resource_type text, _resource_ids uuid[])
 RETURNS TABLE(resource_type text, resource_id uuid, public_id text, access_state text, business_unit_names text[], business_unit_count integer, user_group_names text[], user_group_count integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_ids uuid[]; v_id uuid; v_tenant uuid; v_admin boolean; v_registry uuid;
  v_public text; v_owners text[]; v_groups text[];
BEGIN
  IF v_actor IS NULL OR _resource_type NOT IN ('data_source','data_source_schedule','db_connection','inline_api_source','erp_connection','file_watcher','aidp_template','aidp_document','reference_table','data_prep_pipeline','tenant_template','collateral_schedule','reconciliation') THEN RAISE EXCEPTION 'invalid access summary request'; END IF;
  IF _resource_ids IS NULL OR cardinality(_resource_ids)>100 OR cardinality(_resource_ids)=0 OR array_position(_resource_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'between 1 and 100 resource IDs are required'; END IF;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_ids FROM unnest(_resource_ids) x;
  IF cardinality(v_ids)>100 THEN RAISE EXCEPTION 'at most 100 unique resource IDs are allowed'; END IF;
  FOREACH v_id IN ARRAY v_ids LOOP
    v_tenant:=NULL; v_public:=NULL; v_registry:=NULL; v_owners:=ARRAY[]::text[]; v_groups:=ARRAY[]::text[];
    CASE _resource_type
      WHEN 'data_source' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.workspace_data_sources s WHERE s.id=v_id;
      WHEN 'data_source_schedule' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.data_source_schedules s WHERE s.id=v_id;
      WHEN 'db_connection' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.rekon_db_connections s WHERE s.id=v_id;
      WHEN 'inline_api_source' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.rekon_inline_api_sources s WHERE s.id=v_id;
      WHEN 'erp_connection' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.erp_connector_configs s WHERE s.id=v_id;
      WHEN 'file_watcher' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.data_watchers s WHERE s.id=v_id;
      WHEN 'aidp_template' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.aidp_templates s WHERE s.id=v_id;
      WHEN 'aidp_document' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.aidp_documents s WHERE s.id=v_id;
      WHEN 'reference_table' THEN SELECT s.tenant_id,s.public_id INTO v_tenant,v_public FROM public.reference_data_tables s WHERE s.id=v_id;
      WHEN 'data_prep_pipeline' THEN SELECT s.tenant_id,s.public_uid::text INTO v_tenant,v_public FROM public.data_prep_pipelines s WHERE s.id=v_id;
      WHEN 'tenant_template' THEN SELECT s.tenant_id,NULL::text INTO v_tenant,v_public FROM public.tenant_templates s WHERE s.id=v_id;
      WHEN 'collateral_schedule' THEN SELECT s.tenant_id,NULL::text INTO v_tenant,v_public FROM public.collateral_schedules s WHERE s.id=v_id;
      WHEN 'reconciliation' THEN SELECT s.tenant_id,s.recon_code INTO v_tenant,v_public FROM public.recon_definitions s WHERE s.id=v_id;
    END CASE;
    IF v_tenant IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=v_tenant AND tm.user_id=v_actor AND tm.active) THEN CONTINUE; END IF;
    SELECT tm.role='tenant_admin' INTO v_admin FROM public.tenant_members tm WHERE tm.tenant_id=v_tenant AND tm.user_id=v_actor AND tm.active;
    IF _resource_type='reconciliation' THEN
      IF NOT EXISTS(SELECT 1 FROM public.recon_definition_business_units o WHERE o.tenant_id=v_tenant AND o.recon_id=v_id) THEN access_state:='unmapped';
      ELSE access_state:='mapped'; END IF;
      IF v_admin THEN
        SELECT coalesce(array_agg(DISTINCT b.name ORDER BY b.name),ARRAY[]::text[]) INTO v_owners FROM public.recon_definition_business_units o JOIN public.business_units b ON b.id=o.bu_id AND b.tenant_id=o.tenant_id AND NOT b.is_archived WHERE o.tenant_id=v_tenant AND o.recon_id=v_id;
        SELECT coalesce(array_agg(DISTINCT g.name ORDER BY g.name),ARRAY[]::text[]) INTO v_groups FROM public.recon_definition_bu_grants x JOIN public.tenant_groups g ON g.id=x.principal_id AND g.tenant_id=x.tenant_id WHERE x.tenant_id=v_tenant AND x.recon_id=v_id AND x.principal_type='group';
      ELSE
        IF access_state='mapped' AND NOT (
          EXISTS(SELECT 1 FROM public.recon_definition_bu_grants g JOIN public.recon_definition_business_units o USING(tenant_id,recon_id,bu_id)
            WHERE g.tenant_id=v_tenant AND g.recon_id=v_id AND g.action IN ('view','read') AND g.principal_type='user' AND g.principal_id=v_actor
              AND EXISTS(SELECT 1 FROM public.bu_user_assignments ua JOIN public.business_units assigned ON assigned.id=ua.bu_id AND assigned.tenant_id=ua.tenant_id
                JOIN public.business_units owner ON owner.id=o.bu_id AND owner.tenant_id=o.tenant_id
                WHERE ua.tenant_id=v_tenant AND ua.user_id=v_actor AND (ua.bu_id=o.bu_id OR (ua.inherit_descendants AND owner.path <@ assigned.path))))
          OR EXISTS(SELECT 1 FROM public.recon_definition_bu_grants g JOIN public.recon_definition_business_units o USING(tenant_id,recon_id,bu_id)
            WHERE g.tenant_id=v_tenant AND g.recon_id=v_id AND g.action IN ('view','read') AND g.principal_type='group'
              AND EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=g.principal_id AND gm.user_id=v_actor)
              AND EXISTS(SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned ON assigned.id=ga.bu_id AND assigned.tenant_id=ga.tenant_id
                JOIN public.business_units owner ON owner.id=o.bu_id AND owner.tenant_id=o.tenant_id
                WHERE ga.tenant_id=v_tenant AND ga.group_id=g.principal_id AND (ga.bu_id=o.bu_id OR (ga.inherit_descendants AND owner.path <@ assigned.path))))
        ) THEN CONTINUE; END IF;
        SELECT coalesce(array_agg(DISTINCT b.name ORDER BY b.name),ARRAY[]::text[]) INTO v_owners FROM public.recon_definition_business_units o JOIN public.business_units b ON b.id=o.bu_id AND b.tenant_id=o.tenant_id AND NOT b.is_archived JOIN public.recon_definition_bu_grants g ON g.tenant_id=o.tenant_id AND g.recon_id=o.recon_id AND g.bu_id=o.bu_id WHERE o.tenant_id=v_tenant AND o.recon_id=v_id AND g.action IN ('view','read') AND ((g.principal_type='user' AND g.principal_id=v_actor AND EXISTS(SELECT 1 FROM public.bu_user_assignments ua JOIN public.business_units assigned ON assigned.id=ua.bu_id AND assigned.tenant_id=ua.tenant_id WHERE ua.tenant_id=v_tenant AND ua.user_id=v_actor AND (ua.bu_id=o.bu_id OR (ua.inherit_descendants AND b.path <@ assigned.path)))) OR (g.principal_type='group' AND EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=g.principal_id AND gm.user_id=v_actor) AND EXISTS(SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned ON assigned.id=ga.bu_id AND assigned.tenant_id=ga.tenant_id WHERE ga.tenant_id=v_tenant AND ga.group_id=g.principal_id AND (ga.bu_id=o.bu_id OR (ga.inherit_descendants AND b.path <@ assigned.path)))));
        SELECT coalesce(array_agg(DISTINCT tg.name ORDER BY tg.name),ARRAY[]::text[]) INTO v_groups FROM public.recon_definition_bu_grants g JOIN public.tenant_groups tg ON tg.id=g.principal_id AND tg.tenant_id=g.tenant_id JOIN public.recon_definition_business_units o ON o.tenant_id=g.tenant_id AND o.recon_id=g.recon_id AND o.bu_id=g.bu_id JOIN public.business_units b ON b.id=o.bu_id AND b.tenant_id=o.tenant_id AND NOT b.is_archived WHERE g.tenant_id=v_tenant AND g.recon_id=v_id AND g.principal_type='group' AND g.action IN ('view','read') AND EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=tg.id AND gm.user_id=v_actor) AND EXISTS(SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned ON assigned.id=ga.bu_id AND assigned.tenant_id=ga.tenant_id WHERE ga.tenant_id=v_tenant AND ga.group_id=tg.id AND (ga.bu_id=o.bu_id OR (ga.inherit_descendants AND b.path <@ assigned.path)));
      END IF;
    ELSE
      SELECT r.id INTO v_registry FROM public.data_resource_registry r WHERE r.tenant_id=v_tenant AND r.resource_type=_resource_type AND CASE _resource_type
        WHEN 'data_source' THEN r.data_source_id WHEN 'data_source_schedule' THEN r.data_source_schedule_id WHEN 'db_connection' THEN r.db_connection_id WHEN 'inline_api_source' THEN r.inline_api_source_id WHEN 'erp_connection' THEN r.erp_connection_id WHEN 'file_watcher' THEN r.file_watcher_id WHEN 'aidp_template' THEN r.aidp_template_id WHEN 'aidp_document' THEN r.aidp_document_id WHEN 'reference_table' THEN r.reference_table_id WHEN 'data_prep_pipeline' THEN r.data_prep_pipeline_id WHEN 'tenant_template' THEN r.tenant_template_id WHEN 'collateral_schedule' THEN r.collateral_schedule_id END=v_id;
      IF v_registry IS NULL OR NOT EXISTS(SELECT 1 FROM public.data_resource_registry_owner_bu o WHERE o.tenant_id=v_tenant AND o.registry_id=v_registry) THEN access_state:='unmapped';
      ELSE access_state:='mapped'; END IF;
      IF v_admin THEN
        SELECT coalesce(array_agg(DISTINCT b.name ORDER BY b.name),ARRAY[]::text[]) INTO v_owners FROM public.data_resource_registry_owner_bu o JOIN public.business_units b ON b.id=o.bu_id AND b.tenant_id=o.tenant_id AND NOT b.is_archived WHERE o.tenant_id=v_tenant AND o.registry_id=v_registry;
        SELECT coalesce(array_agg(DISTINCT g.name ORDER BY g.name),ARRAY[]::text[]) INTO v_groups FROM public.data_resource_registry_grants x JOIN public.tenant_groups g ON g.id=x.principal_group_id AND g.tenant_id=x.tenant_id WHERE x.tenant_id=v_tenant AND x.registry_id=v_registry AND x.principal_type='group';
      ELSIF access_state='mapped' THEN
        IF NOT private.data_resource_shadow_allows_actor(v_actor,v_registry,'view'::text) THEN CONTINUE; END IF;
        SELECT coalesce(array_agg(DISTINCT b.name ORDER BY b.name),ARRAY[]::text[]) INTO v_owners FROM public.data_resource_registry_owner_bu o JOIN public.business_units b ON b.id=o.bu_id AND b.tenant_id=o.tenant_id AND NOT b.is_archived JOIN public.data_resource_registry_grants g ON g.tenant_id=o.tenant_id AND g.registry_id=o.registry_id AND g.bu_id=o.bu_id AND g.action='view' WHERE o.tenant_id=v_tenant AND o.registry_id=v_registry AND ((g.principal_type='user' AND g.principal_user_id=v_actor AND EXISTS(SELECT 1 FROM public.bu_user_assignments ua JOIN public.business_units assigned ON assigned.id=ua.bu_id AND assigned.tenant_id=ua.tenant_id WHERE ua.tenant_id=v_tenant AND ua.user_id=v_actor AND (ua.bu_id=o.bu_id OR (ua.inherit_descendants AND b.path <@ assigned.path)))) OR (g.principal_type='group' AND EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=g.principal_group_id AND gm.user_id=v_actor) AND EXISTS(SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned ON assigned.id=ga.bu_id AND assigned.tenant_id=ga.tenant_id WHERE ga.tenant_id=v_tenant AND ga.group_id=g.principal_group_id AND (ga.bu_id=o.bu_id OR (ga.inherit_descendants AND b.path <@ assigned.path)))));
        SELECT coalesce(array_agg(DISTINCT tg.name ORDER BY tg.name),ARRAY[]::text[]) INTO v_groups FROM public.data_resource_registry_grants g JOIN public.tenant_groups tg ON tg.id=g.principal_group_id AND tg.tenant_id=g.tenant_id JOIN public.data_resource_registry_owner_bu o ON o.tenant_id=g.tenant_id AND o.registry_id=g.registry_id AND o.bu_id=g.bu_id JOIN public.business_units b ON b.id=o.bu_id AND b.tenant_id=o.tenant_id AND NOT b.is_archived WHERE g.tenant_id=v_tenant AND g.registry_id=v_registry AND g.action='view' AND g.principal_type='group' AND EXISTS(SELECT 1 FROM public.tenant_group_members gm WHERE gm.group_id=tg.id AND gm.user_id=v_actor) AND EXISTS(SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned ON assigned.id=ga.bu_id AND assigned.tenant_id=ga.tenant_id WHERE ga.tenant_id=v_tenant AND ga.group_id=tg.id AND (ga.bu_id=o.bu_id OR (ga.inherit_descendants AND b.path <@ assigned.path)));
      END IF;
    END IF;
    resource_type:=_resource_type; resource_id:=v_id; public_id:=v_public; business_unit_names:=v_owners; business_unit_count:=cardinality(v_owners); user_group_names:=v_groups; user_group_count:=cardinality(v_groups); RETURN NEXT;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.register_typed_data_source_schedule(_schedule_id uuid, _owner_bu_ids uuid[], _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_tenant uuid; v_registry uuid; v_bu_ids uuid[];
BEGIN
  IF v_actor IS NULL OR _schedule_id IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'invalid schedule registration request'; END IF;
  SELECT tenant_id INTO v_tenant FROM public.data_source_schedules WHERE id=_schedule_id FOR SHARE;
  IF v_tenant IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=v_tenant AND tm.user_id=v_actor AND tm.active AND tm.role='tenant_admin'::public.tenant_role) THEN RAISE EXCEPTION 'not authorized'; END IF;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_bu_ids FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) x;
  IF cardinality(v_bu_ids)=0 OR EXISTS(SELECT 1 FROM unnest(v_bu_ids) x LEFT JOIN public.business_units b ON b.id=x AND b.tenant_id=v_tenant AND NOT b.is_archived WHERE b.id IS NULL) THEN RAISE EXCEPTION 'active owner business units in the schedule tenant are required'; END IF;
  INSERT INTO public.data_resource_registry(tenant_id,resource_type,data_source_schedule_id,created_by) VALUES(v_tenant,'data_source_schedule',_schedule_id,v_actor) RETURNING id INTO v_registry;
  INSERT INTO public.data_resource_registry_owner_bu(tenant_id,registry_id,bu_id,created_by) SELECT v_tenant,v_registry,x,v_actor FROM unnest(v_bu_ids) x;
  INSERT INTO public.data_resource_registry_admin_audit(tenant_id,registry_id,operation,actor_id,reason,details) VALUES(v_tenant,v_registry,'REGISTER',v_actor,btrim(_reason),jsonb_build_object('resource_type','data_source_schedule','resource_id',_schedule_id,'owner_bu_ids',v_bu_ids));
  RETURN v_registry;
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_complete_mfa(_slug text, _id uuid, _receipt_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); c private.rlnext_challenges; a private.rlnext_accounts; session_id uuid;
BEGIN
 IF actor IS NULL OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' OR NOT private.rlnext_has_verified_mfa(actor) THEN RAISE EXCEPTION 'Genuine provider MFA required' USING ERRCODE='42501'; END IF;
 IF coalesce(auth.jwt()->>'session_id','') !~ '^[a-f0-9-]{36}$' THEN RAISE EXCEPTION 'Current provider session required' USING ERRCODE='42501'; END IF;
 session_id:=(auth.jwt()->>'session_id')::uuid;
 IF NOT EXISTS(SELECT 1 FROM auth.sessions s WHERE s.id=session_id AND s.user_id=actor) THEN RAISE EXCEPTION 'Current provider session required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rlnext:'||coalesce((SELECT tenant_id::text FROM private.rlnext_challenges WHERE id=_id),'unknown'),0));
 SELECT * INTO c FROM private.rlnext_challenges WHERE id=_id AND receipt_hash=_receipt_hash AND purpose='verify' AND verify_state='complete' FOR UPDATE;
 IF c.id IS NULL THEN RAISE EXCEPTION 'Verified email receipt required' USING ERRCODE='42501'; END IF;
 SELECT * INTO a FROM private.rlnext_accounts WHERE id=c.account_id AND user_id=actor FOR UPDATE;
 IF a.id IS NULL OR a.verified_at IS NULL OR NOT a.mfa_required OR NOT EXISTS(SELECT 1 FROM public.tenants WHERE id=a.tenant_id AND slug=_slug) OR NOT private.rlnext_domain(a.tenant_id,a.email)
 OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=actor AND lower(email)=a.email AND email_confirmed_at IS NOT NULL)
 OR EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=actor) OR public.is_platform_admin(actor)
 THEN RAISE EXCEPTION 'Current applicant scope required' USING ERRCODE='42501'; END IF;
 IF a.status='pending_approval' AND a.mfa_verified_at IS NOT NULL THEN RETURN jsonb_build_object('accepted',true,'idempotent',true); END IF;
 IF a.status<>'pending_verification' THEN RAISE EXCEPTION 'Applicant state changed' USING ERRCODE='PT409'; END IF;
 UPDATE private.rlnext_accounts SET status='pending_approval',mfa_verified_at=clock_timestamp(),mfa_session_id=session_id,version=version+1 WHERE id=a.id;
 PERFORM private.rlnext_record(a.tenant_id,a.id,actor,'mfa_admission_verified',NULL,jsonb_build_object('assurance','provider_aal2'));
 PERFORM private.rlnext_notice(a.id,'pending_approval',NULL,true);
 RETURN jsonb_build_object('accepted',true);
END $function$

CREATE OR REPLACE FUNCTION private.wfm_enabled(_tenant uuid, _key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE p private.wfm_page_catalog%ROWTYPE;k text;
BEGIN
 SELECT * INTO p FROM private.wfm_page_catalog WHERE key=_key;IF NOT FOUND THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM public.tenant_workspace_page_visibility WHERE tenant_id=_tenant AND page_key=_key AND enabled IS NOT TRUE) THEN RETURN false;END IF;
 FOREACH k IN ARRAY p.parents LOOP IF private.wfm_enabled(_tenant,k) IS DISTINCT FROM true THEN RETURN false;END IF; END LOOP;
 FOREACH k IN ARRAY p.feature_keys LOOP IF private.wfm_feature_enabled(_tenant,k) IS DISTINCT FROM true THEN RETURN false;END IF; END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.signup_mfa_admission_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=auth.uid(); email text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
 IF public.is_platform_admin(actor) OR EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=actor) THEN RETURN jsonb_build_object('state','existing_access','user_id',actor); END IF;
 SELECT lower(u.email) INTO email FROM auth.users u WHERE u.id=actor AND u.email_confirmed_at IS NOT NULL;
 IF email IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_email_domains WHERE domain::text=split_part(email,'@',2) AND status='verified') THEN RETURN jsonb_build_object('state','email_verification_required','user_id',actor); END IF;
 RETURN jsonb_build_object('state',CASE WHEN auth.jwt()->>'aal'='aal2' AND private.rlnext_has_verified_mfa(actor) THEN 'mfa_ready' ELSE 'mfa_required' END,'user_id',actor);
END $function$

CREATE OR REPLACE FUNCTION private.typed_resource_root_tenant(_type text, _id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_tenant uuid;
BEGIN
  CASE _type
    WHEN 'data_source' THEN SELECT tenant_id INTO v_tenant FROM public.workspace_data_sources WHERE id=_id;
    WHEN 'data_source_schedule' THEN SELECT tenant_id INTO v_tenant FROM public.data_source_schedules WHERE id=_id;
    WHEN 'db_connection' THEN SELECT tenant_id INTO v_tenant FROM public.rekon_db_connections WHERE id=_id;
    WHEN 'inline_api_source' THEN SELECT tenant_id INTO v_tenant FROM public.rekon_inline_api_sources WHERE id=_id;
    WHEN 'erp_connection' THEN SELECT tenant_id INTO v_tenant FROM public.erp_connector_configs WHERE id=_id;
    WHEN 'file_watcher' THEN SELECT tenant_id INTO v_tenant FROM public.data_watchers WHERE id=_id;
    WHEN 'aidp_template' THEN SELECT tenant_id INTO v_tenant FROM public.aidp_templates WHERE id=_id;
    WHEN 'aidp_document' THEN SELECT tenant_id INTO v_tenant FROM public.aidp_documents WHERE id=_id;
    WHEN 'reference_table' THEN SELECT tenant_id INTO v_tenant FROM public.reference_data_tables WHERE id=_id;
    WHEN 'data_prep_pipeline' THEN SELECT tenant_id INTO v_tenant FROM public.data_prep_pipelines WHERE id=_id;
    WHEN 'tenant_template' THEN SELECT tenant_id INTO v_tenant FROM public.tenant_templates WHERE id=_id;
    WHEN 'collateral_schedule' THEN SELECT tenant_id INTO v_tenant FROM public.collateral_schedules WHERE id=_id;
    ELSE RETURN NULL;
  END CASE;
  RETURN v_tenant;
END $function$

CREATE OR REPLACE FUNCTION public.rlnext_status(_id uuid, _receipt_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE c private.rlnext_challenges; a private.rlnext_accounts;
BEGIN
 PERFORM private.rlnext_service(); SELECT * INTO c FROM private.rlnext_challenges WHERE id=_id AND (receipt_hash=_receipt_hash OR reset_hash=_receipt_hash) AND created_at>clock_timestamp()-interval '24 hours';
 IF c.id IS NULL THEN RETURN '{}'::jsonb; END IF;
 SELECT * INTO STRICT a FROM private.rlnext_accounts WHERE id=c.account_id;
 IF a.mfa_required AND a.status='pending_verification' AND a.verified_at IS NOT NULL AND c.purpose='verify' AND c.verify_state='complete' THEN RETURN jsonb_build_object('onboarding_required',true,'onboarding_user_id',a.user_id); END IF;
 IF c.create_state='uncertain' THEN
   UPDATE private.rlnext_accounts ac SET user_id=u.id FROM auth.users u WHERE ac.id=a.id AND ac.user_id IS NULL AND lower(u.email)=ac.email AND u.email_confirmed_at IS NULL AND u.raw_user_meta_data->>'fvi_lifecycle_request'=c.id::text AND NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.user_id=u.id);
   IF FOUND THEN UPDATE private.rlnext_challenges SET create_state='created' WHERE id=c.id; c.create_state:='created'; END IF;
 END IF;
 IF c.verify_state='claimed' AND c.purpose='verify' THEN RETURN public.rlnext_verify_finish(c.id,false); END IF;
 IF c.reset_state IN('claimed','uncertain') THEN
   IF (public.rlnext_reset_finish(c.id,false)->>'completed')::boolean THEN RETURN jsonb_build_object('status','active','assigned',a.assigned,'completed',true); END IF;
 END IF;
 RETURN jsonb_build_object('status',a.status,'assigned',a.assigned,'reset_required',c.reset_state IN('ready','claimed','uncertain'),'reset_expires',floor(extract(epoch FROM c.reset_expires_at)*1000)::bigint,'held',c.create_state='uncertain' OR c.send_state IN('claimed','uncertain') OR c.verify_state='claimed' OR c.reset_state IN('claimed','uncertain'));
END $function$

CREATE OR REPLACE FUNCTION private.wfm_mode_allowed(_tenant uuid, _mode text, _bu uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant);p public.platform_ai_settings%ROWTYPE;t public.tenant_ai_settings%ROWTYPE;cfg jsonb;
BEGIN
 IF private.wfm_enabled(_tenant,'prep') IS DISTINCT FROM true OR public.user_has_permission(actor,_tenant,'data.prep.read',_bu) IS DISTINCT FROM true THEN RETURN false;END IF;
 IF _mode='manual' THEN RETURN true;END IF;
 IF _mode NOT IN('assisted','agentic') THEN RETURN false;END IF;
 SELECT * INTO p FROM public.platform_ai_settings WHERE id=true;IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO t FROM public.tenant_ai_settings WHERE tenant_id=_tenant;IF NOT FOUND THEN RETURN false;END IF;
 SELECT config INTO cfg FROM public.tenant_feature_flags WHERE tenant_id=_tenant AND feature_key='data_prep';
 IF p.ai_enabled IS DISTINCT FROM true OR t.ai_enabled IS DISTINCT FROM true OR cfg->'ai_enabled' IS DISTINCT FROM 'true'::jsonb
 OR NOT EXISTS(SELECT 1 FROM public.tenants WHERE id=_tenant AND ai_enabled IS TRUE)
 OR EXISTS(SELECT 1 FROM public.ai_governance_kill_switches WHERE tenant_id=_tenant AND engaged IS TRUE) THEN RETURN false;END IF;
 IF _mode='assisted' THEN RETURN cfg->'assisted_enabled'='true'::jsonb AND p.allow_copilot_global AND t.allow_copilot
 AND private.wfm_feature_enabled(_tenant,'copilot') AND public.user_has_permission(actor,_tenant,'ai.copilot.use',_bu) IS TRUE;END IF;
 RETURN cfg->'agentic_enabled'='true'::jsonb AND p.allow_agent_global AND t.allow_agent AND private.wfm_feature_enabled(_tenant,'agent')
 AND p.default_autonomy_ceiling IN('assist','auto') AND t.default_autonomy IN('supervised','autonomous')
 AND public.user_has_permission(actor,_tenant,'ai.agent.run',_bu) IS TRUE;
END $function$

CREATE OR REPLACE FUNCTION public.approve_collateral_vm_call(_tenant_id uuid, _call_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid := auth.uid(); c public.collateral_csa_calls%ROWTYPE;
BEGIN
  IF NOT public.csa_assurance_actor(_tenant_id,actor) THEN RAISE EXCEPTION 'Active synthetic Assurance tenant administrator required' USING ERRCODE='42501'; END IF;
  SELECT * INTO c FROM public.collateral_csa_calls WHERE tenant_id=_tenant_id AND id=_call_id FOR UPDATE;
  IF NOT FOUND OR c.status<>'pending_approval' THEN RAISE EXCEPTION 'Call is not awaiting approval' USING ERRCODE='22023'; END IF;
  IF actor=c.calculated_by THEN RAISE EXCEPTION 'Call maker cannot approve own calculation' USING ERRCODE='42501'; END IF;
  UPDATE public.collateral_csa_calls SET status='approved',approved_by=actor,approved_at=now() WHERE id=_call_id;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(actor,_tenant_id,'tenant','collateral.vm.call.approve','collateral_csa_call',_call_id::text,jsonb_build_object('amount',c.call_amount));
  RETURN 'approved';
END $function$

CREATE OR REPLACE FUNCTION private.wfm_record(_tenant uuid, _kind text, _key text, _before jsonb, _after jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid();eid uuid;ep bigint;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR actor IS NULL THEN RAISE EXCEPTION 'wfm.real_actor_required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('wfm:'||_tenant::text,0));
 INSERT INTO private.wfm_epoch(tenant_id,epoch) VALUES(_tenant,1) ON CONFLICT(tenant_id) DO UPDATE SET epoch=wfm_epoch.epoch+1 RETURNING epoch INTO ep;
 INSERT INTO private.wfm_events(tenant_id,actor_id,kind,key,before_value,after_value,epoch) VALUES(_tenant,actor,_kind,_key,_before,_after,ep) RETURNING id INTO eid;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,_tenant,'tenant','workspace.control.change','workspace_controls',eid::text,jsonb_build_object('kind',_kind,'key',_key,'before',_before,'after',_after,'epoch',ep::text));
 INSERT INTO private.wfm_plan_events(plan_id,actor_id,event,control_event_id)
 SELECT id,actor,'cancelled',eid FROM private.wfm_draft_plans p WHERE p.tenant_id=_tenant AND NOT EXISTS(SELECT 1 FROM private.wfm_plan_events e WHERE e.plan_id=p.id AND e.event='cancelled');
 RETURN eid;
END $function$

CREATE OR REPLACE FUNCTION private.wfm_toggle_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE tid uuid;key text;isai boolean:=false;beforev jsonb:='{}';afterv jsonb;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'wfm.disable_instead_of_delete' USING ERRCODE='42501';END IF;
 tid:=NEW.tenant_id;
 IF TG_OP='UPDATE' AND NEW.tenant_id IS DISTINCT FROM OLD.tenant_id THEN RAISE EXCEPTION 'wfm.identity_immutable' USING ERRCODE='42501';END IF;
 IF TG_TABLE_NAME='tenant_workspace_page_visibility' THEN
  key:=NEW.page_key;IF NOT EXISTS(SELECT 1 FROM private.wfm_page_catalog WHERE wfm_page_catalog.key=NEW.page_key) THEN RAISE EXCEPTION 'wfm.unknown_page' USING ERRCODE='22023';END IF;
  IF TG_OP='UPDATE' AND NEW.page_key IS DISTINCT FROM OLD.page_key THEN RAISE EXCEPTION 'wfm.identity_immutable' USING ERRCODE='42501';END IF;
 ELSIF TG_TABLE_NAME='tenant_workspace_features' THEN
  key:=NEW.feature_key;IF NOT EXISTS(SELECT 1 FROM private.wfm_ux_catalog WHERE wfm_ux_catalog.key=NEW.feature_key) THEN RAISE EXCEPTION 'wfm.unknown_feature' USING ERRCODE='22023';END IF;
  IF TG_OP='UPDATE' AND NEW.feature_key IS DISTINCT FROM OLD.feature_key THEN RAISE EXCEPTION 'wfm.identity_immutable' USING ERRCODE='42501';END IF;
 ELSE
  key:=NEW.feature_key;SELECT category='AI' INTO isai FROM private.wfm_feature_catalog WHERE wfm_feature_catalog.key=NEW.feature_key;
  IF NOT FOUND THEN RAISE EXCEPTION 'wfm.unknown_feature' USING ERRCODE='22023';END IF;
  isai:=isai OR (key='data_prep' AND (TG_OP='INSERT' AND (NEW.config ?| ARRAY['ai_enabled','assisted_enabled','agentic_enabled']) OR TG_OP='UPDATE' AND (NEW.config->'ai_enabled' IS DISTINCT FROM OLD.config->'ai_enabled' OR NEW.config->'assisted_enabled' IS DISTINCT FROM OLD.config->'assisted_enabled' OR NEW.config->'agentic_enabled' IS DISTINCT FROM OLD.config->'agentic_enabled')));
  IF TG_OP='UPDATE' AND NEW.feature_key IS DISTINCT FROM OLD.feature_key THEN RAISE EXCEPTION 'wfm.identity_immutable' USING ERRCODE='42501';END IF;
  IF NEW.enabled IS TRUE AND EXISTS(SELECT 1 FROM public.tenant_feature_entitlements WHERE tenant_id=tid AND feature_key=key AND allowed IS NOT TRUE)
  THEN RAISE EXCEPTION 'wfm.platform_entitlement_denied' USING ERRCODE='42501';END IF;
 END IF;
 IF private.wfm_can_manage(tid,isai) IS DISTINCT FROM true THEN RAISE EXCEPTION 'wfm.admin_permission_denied' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('wfm:'||tid::text,0));
 NEW.updated_by:=auth.uid();NEW.updated_at:=clock_timestamp();
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.complete_onboarding(_tenant_id uuid)
 RETURNS onboarding_progress
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_row public.onboarding_progress;
begin
  if v_user is null then
    raise exception 'Unauthorized';
  end if;

  update public.onboarding_progress
  set completed_at = now(), last_resumed_at = now(), current_step = 6
  where tenant_id = _tenant_id and user_id = v_user and completed_at is null
  returning * into v_row;

  if not found then
    raise exception 'No onboarding in progress for this tenant';
  end if;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.tg_validate_data_prep_pipeline_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  source_tenant uuid;
  output_tenant uuid;
BEGIN
  IF NEW.source_data_source_id IS NOT NULL THEN
    SELECT ds.tenant_id INTO source_tenant
    FROM public.workspace_data_sources ds
    WHERE ds.id = NEW.source_data_source_id;

    IF source_tenant IS NULL OR source_tenant <> NEW.tenant_id THEN
      RAISE EXCEPTION 'Data Prep source must belong to the pipeline tenant';
    END IF;
  END IF;

  IF NEW.output_data_source_id IS NOT NULL THEN
    SELECT ds.tenant_id INTO output_tenant
    FROM public.workspace_data_sources ds
    WHERE ds.id = NEW.output_data_source_id;

    IF output_tenant IS NULL OR output_tenant <> NEW.tenant_id THEN
      RAISE EXCEPTION 'Data Prep output must belong to the pipeline tenant';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.tg_bind_data_prep_run_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  parent_tenant uuid;
BEGIN
  SELECT pipeline.tenant_id INTO parent_tenant
  FROM public.data_prep_pipelines pipeline
  WHERE pipeline.id = NEW.pipeline_id;

  IF parent_tenant IS NULL THEN
    RAISE EXCEPTION 'Data Prep pipeline not found';
  END IF;

  NEW.tenant_id := parent_tenant;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rlnext_capture_login_event(_attempt uuid, _binding text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE recorded record;
BEGIN
 PERFORM private.rlnext_service();
 SELECT request_id,user_id,outcome INTO recorded FROM private.failed_login_attempts
 WHERE id=_attempt AND binding=_binding AND finished_at IS NOT NULL AND stage IN('password','mfa');
 IF NOT FOUND OR recorded.user_id IS NULL THEN RETURN false; END IF;
