CREATE OR REPLACE FUNCTION public.dpw_get_attachment_retention(_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;p jsonb;t jsonb;cv text:='0';canwrite boolean;
BEGIN
 IF _tenant_id IS NULL THEN actor:=private.wfm_platform_actor();canwrite:=true;
 ELSE actor:=private.wfm_actor(_tenant_id);canwrite:=private.wfm_can_manage(_tenant_id,false) AND public.user_has_permission(actor,_tenant_id,'compliance.retention.manage',NULL) IS TRUE;END IF;
 SELECT jsonb_build_object('policy_id',policy_id,'version',version::text,'period_days',period_days,'source','platform','effective_at',effective_at) INTO p FROM private.dpw_attachment_retention_defaults WHERE singleton=true;
 IF p IS NULL THEN RAISE EXCEPTION 'dpw.retention_default_unqualified' USING ERRCODE='42501';END IF;
 IF _tenant_id IS NOT NULL THEN
  SELECT version::text,CASE WHEN period_days IS NULL THEN NULL ELSE jsonb_build_object('policy_id',policy_id,'version',version::text,'period_days',period_days,'source','tenant','effective_at',effective_at) END INTO cv,t FROM private.dpw_attachment_retention_overrides WHERE tenant_id=_tenant_id;
 ELSE cv:=p->>'version';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'platform',p,'override',t,'effective',CASE WHEN t IS NOT NULL AND (t->>'period_days')::integer>=(p->>'period_days')::integer THEN t ELSE p END,'control_version',coalesce(cv,'0'),'can_write',canwrite);
END $function$

CREATE OR REPLACE FUNCTION public.simulate_cascade_policy(_tenant_id uuid, _policy_id uuid, _recon_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_policy public.recon_cascade_policies%ROWTYPE;
  v_breakdown jsonb := '[]'::jsonb;
  v_candidates int;
  v_matches int;
  v_carry int;
  v_ordinal int := 0;
BEGIN
  SELECT * INTO v_policy FROM public.recon_cascade_policies
    WHERE id = _policy_id AND tenant_id = _tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cascade policy % not found for tenant %', _policy_id, _tenant_id;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.tenant_members tm
                 WHERE tm.tenant_id = _tenant_id AND tm.user_id = auth.uid()) THEN
    RAISE EXCEPTION 'Forbidden: not a tenant member';
  END IF;

  SELECT COUNT(*) INTO v_candidates
    FROM public.recon_match_allocations a
    JOIN public.recon_matches m ON m.id = a.match_id
    WHERE a.tenant_id = _tenant_id
      AND m.run_id = _recon_run_id;

  FOR v_ordinal IN 1 .. LEAST(v_policy.max_passes, GREATEST(jsonb_array_length(v_policy.pass_order), 1)) LOOP
    v_matches := GREATEST(0, (v_candidates * 30) / 100);
    v_carry := v_candidates - v_matches;

    v_breakdown := v_breakdown || jsonb_build_object(
      'ordinal', v_ordinal,
      'pass_key', v_policy.pass_order -> (v_ordinal - 1),
      'candidates_in', v_candidates,
      'matches_out', v_matches,
      'carry_forward_out', CASE WHEN v_policy.carry_forward_unmatched THEN v_carry ELSE 0 END
    );

    IF v_policy.carry_forward_unmatched THEN
      v_candidates := v_carry;
    ELSE
      v_candidates := 0;
    END IF;

    EXIT WHEN v_candidates = 0;
  END LOOP;

  RETURN v_breakdown;
END;
$function$

CREATE OR REPLACE FUNCTION public.list_allowed_signoff_transitions(_signoff_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.eod_signoffs%ROWTYPE;
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
  v_out text[] := ARRAY[]::text[];
BEGIN
  SELECT * INTO v_row FROM public.eod_signoffs WHERE id = _signoff_id;
  IF NOT FOUND THEN RETURN v_out; END IF;

  IF NOT EXISTS (SELECT 1 FROM public.tenant_members tm
                 WHERE tm.tenant_id = v_row.tenant_id AND tm.user_id = v_uid) THEN
    RETURN v_out;
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.tenant_members tm
                 WHERE tm.tenant_id = v_row.tenant_id
                   AND tm.user_id = v_uid
                   AND tm.role = 'tenant_admin') INTO v_is_admin;

  IF v_row.locked THEN
    IF v_is_admin THEN v_out := array_append(v_out, 'reopened'); END IF;
    RETURN v_out;
  END IF;

  IF v_row.status = 'draft' THEN
    v_out := array_append(v_out, 'prepared');
  ELSIF v_row.status = 'prepared' THEN
    IF v_row.prepared_by IS DISTINCT FROM v_uid THEN
      v_out := array_append(v_out, 'reviewed');
    END IF;
    v_out := array_append(v_out, 'rejected');
  ELSIF v_row.status = 'reviewed' THEN
    IF v_is_admin AND v_row.prepared_by IS DISTINCT FROM v_uid AND v_row.reviewed_by IS DISTINCT FROM v_uid THEN
      v_out := array_append(v_out, 'certified');
    END IF;
    v_out := array_append(v_out, 'rejected');
  ELSIF v_row.status = 'rejected' THEN
    IF v_is_admin THEN v_out := array_append(v_out, 'reopened'); END IF;
  END IF;

  RETURN v_out;
END;
$function$

CREATE OR REPLACE FUNCTION public.mkt_book_appointment(_type_slug text, _start_at timestamp with time zone, _attendee_name text, _attendee_email text, _notes text DEFAULT NULL::text, _lead_id uuid DEFAULT NULL::uuid, _source text DEFAULT 'public'::text)
 RETURNS TABLE(id uuid, status text, start_at timestamp with time zone, end_at timestamp with time zone, type_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_type public.mkt_appointment_types%ROWTYPE;
  v_end timestamptz;
  v_status text;
  v_count int;
  v_email text;
BEGIN
  IF _attendee_email IS NULL OR position('@' in _attendee_email) < 2 THEN
    RAISE EXCEPTION 'invalid_email';
  END IF;
  v_email := lower(trim(_attendee_email));

  SELECT * INTO v_type FROM public.mkt_appointment_types
   WHERE slug = _type_slug AND is_active = true LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'unknown_or_inactive_type'; END IF;

  v_end := _start_at + make_interval(mins => v_type.duration_min);

  -- Rules: min notice + max advance
  IF _start_at < now() + make_interval(hours => v_type.min_notice_hours) THEN
    RAISE EXCEPTION 'too_soon';
  END IF;
  IF _start_at > now() + make_interval(days => v_type.max_advance_days) THEN
    RAISE EXCEPTION 'too_far_out';
  END IF;

  -- Daily cap
  SELECT count(*) INTO v_count FROM public.mkt_appointments a
    WHERE a.type_id = v_type.id
      AND a.status IN ('confirmed','pending')
      AND a.start_at::date = _start_at::date;
  IF v_count >= v_type.daily_cap THEN RAISE EXCEPTION 'day_full'; END IF;

  -- Overlap guard (any confirmed/pending booking on the same slot)
  IF EXISTS (
    SELECT 1 FROM public.mkt_appointments a
     WHERE a.type_id = v_type.id
       AND a.status IN ('confirmed','pending')
       AND tstzrange(a.start_at, a.end_at, '[)') && tstzrange(_start_at, v_end, '[)')
  ) THEN RAISE EXCEPTION 'slot_taken'; END IF;

  v_status := CASE WHEN v_type.requires_approval THEN 'pending' ELSE 'confirmed' END;

  RETURN QUERY
    INSERT INTO public.mkt_appointments AS appointment
      (lead_id, type_id, start_at, end_at, status,
       attendee_email, attendee_name, notes, external_provider)
    VALUES
      (_lead_id, v_type.id, _start_at, v_end, v_status,
       v_email, _attendee_name, _notes, _source)
    RETURNING appointment.id, appointment.status, appointment.start_at, appointment.end_at, v_type.name;
END; $function$

CREATE OR REPLACE FUNCTION public.webhook_outbox_replay(p_outbox_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM public.webhook_outbox WHERE id = p_outbox_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_found'; END IF;
  IF NOT public.has_tenant_role(auth.uid(), v_tenant, 'tenant_admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  UPDATE public.webhook_outbox
     SET status = 'pending',
         attempts = 0,
         next_attempt_at = now(),
         last_error = NULL
   WHERE id = p_outbox_id;

  INSERT INTO public.audit_log(tenant_id, actor_user_id, scope, action, resource_type, resource_id, context)
  VALUES (v_tenant, auth.uid(), 'tenant', 'webhook.replay', 'webhook_outbox', p_outbox_id::text, jsonb_build_object('source','manual'));
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.watcher_scope_allows(_watcher uuid, _action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE v_watcher public.data_watchers%ROWTYPE; v_actor uuid:=auth.uid(); v_role text;
  v_registry uuid; v_source_registry uuid;
BEGIN
  IF v_actor IS NULL OR _watcher IS NULL OR _action NOT IN ('view','edit','run','manage') THEN RETURN false; END IF;
  SELECT * INTO v_watcher FROM public.data_watchers WHERE id=_watcher;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT tm.role::text INTO v_role FROM public.tenant_members tm
    WHERE tm.tenant_id=v_watcher.tenant_id AND tm.user_id=v_actor AND tm.active;
  IF v_role IS NULL THEN RETURN false; END IF;
  IF v_watcher.access_mode='legacy_passthrough' THEN
    RETURN _action='view' OR (_action IN ('edit','run') AND v_role IN ('tenant_admin','tenant_analyst'))
      OR (_action='manage' AND v_role='tenant_admin');
  END IF;
  IF v_watcher.access_mode='unmapped_pending' THEN RETURN v_role='tenant_admin'; END IF;
  SELECT id INTO v_registry FROM public.data_resource_registry
    WHERE tenant_id=v_watcher.tenant_id AND resource_type='file_watcher' AND file_watcher_id=_watcher;
  SELECT id INTO v_source_registry FROM public.data_resource_registry
    WHERE tenant_id=v_watcher.tenant_id AND resource_type='data_source'
      AND data_source_id=v_watcher.data_source_id;
  IF v_registry IS NULL OR v_source_registry IS NULL THEN RETURN false; END IF;
  RETURN private.data_resource_shadow_allows_actor(v_actor,v_registry,_action)
    AND private.data_resource_shadow_allows_actor(v_actor,v_source_registry,'view');
END $function$

CREATE OR REPLACE FUNCTION public.dpw_set_attachment_retention(_tenant_id uuid, _period_days integer, _expected_version text, _request_key uuid, _effect text, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;oldv jsonb;newv jsonb;cv text;payload jsonb;prior private.dpw_attachment_retention_events%ROWTYPE;eid uuid;
BEGIN
 IF _request_key IS NULL OR _expected_version IS NULL OR _effect IS DISTINCT FROM 'new_scoped_attachments' OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 500
 OR _period_days<=0 OR (_tenant_id IS NULL AND _period_days IS NULL) THEN RAISE EXCEPTION 'dpw.invalid_retention_parameter' USING ERRCODE='22023';END IF;
 IF _tenant_id IS NULL THEN actor:=private.wfm_platform_actor();
 ELSE actor:=private.wfm_actor(_tenant_id);IF private.wfm_can_manage(_tenant_id,false) IS DISTINCT FROM true OR public.user_has_permission(actor,_tenant_id,'compliance.retention.manage',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.retention_authority_denied' USING ERRCODE='42501';END IF;END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('dpw_attachment_retention:platform',0));
 payload:=jsonb_build_object('tenant_id',_tenant_id,'period_days',_period_days,'expected_version',_expected_version,'effect',_effect,'reason',_reason);
 SELECT * INTO prior FROM private.dpw_attachment_retention_events WHERE tenant_id IS NOT DISTINCT FROM _tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF prior.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'dpw.retention_request_conflict' USING ERRCODE='PT409';END IF;RETURN public.dpw_get_attachment_retention(_tenant_id);END IF;
 IF _tenant_id IS NOT NULL AND _period_days IS NOT NULL AND _period_days<(SELECT period_days FROM private.dpw_attachment_retention_defaults WHERE singleton=true) THEN RAISE EXCEPTION 'dpw.tenant_retention_below_platform_default' USING ERRCODE='22023';END IF;
 oldv:=public.dpw_get_attachment_retention(_tenant_id);cv:=oldv->>'control_version';
 IF cv<>_expected_version THEN RAISE EXCEPTION 'dpw.retention_version_conflict' USING ERRCODE='PT409';END IF;
 IF _tenant_id IS NULL THEN UPDATE private.dpw_attachment_retention_defaults SET version=version+1,period_days=_period_days,effective_at=clock_timestamp() WHERE singleton=true;
 ELSE INSERT INTO private.dpw_attachment_retention_overrides(tenant_id,version,period_days) VALUES(_tenant_id,1,_period_days) ON CONFLICT(tenant_id) DO UPDATE SET version=dpw_attachment_retention_overrides.version+1,period_days=EXCLUDED.period_days,effective_at=clock_timestamp();END IF;
 newv:=public.dpw_get_attachment_retention(_tenant_id);
 INSERT INTO private.dpw_attachment_retention_events(tenant_id,actor_id,request_key,payload,before_value,after_value) VALUES(_tenant_id,actor,_request_key,payload,oldv,newv) RETURNING id INTO eid;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,_tenant_id,CASE WHEN _tenant_id IS NULL THEN 'platform' ELSE 'tenant' END,'dataprep.attachment_retention.change','attachment_byte_policy',eid::text,
 jsonb_build_object('before',oldv,'after',newv,'effect',_effect,'physical_purge_enabled',false));
 RETURN newv;
END $function$

CREATE OR REPLACE FUNCTION public.ack_tenant_signup_event(_event_id uuid, _lease_token uuid, _provider_message_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_event public.tenant_signup_events;
BEGIN
  IF _provider_message_id IS NULL OR length(_provider_message_id) NOT BETWEEN 1 AND 200 THEN
    RAISE EXCEPTION 'Invalid provider correlation' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_event FROM public.tenant_signup_events WHERE id=_event_id FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;
  IF v_event.notified_at IS NOT NULL THEN
    RETURN v_event.provider_message_id=_provider_message_id;
  END IF;
  IF _lease_token IS NULL OR v_event.lease_until IS NULL
     OR v_event.lease_token IS DISTINCT FROM _lease_token OR v_event.lease_until <= now() THEN
    RETURN false;
  END IF;
  UPDATE public.tenant_signup_events
    SET notified_at=now(),provider_message_id=_provider_message_id,
        lease_token=NULL,lease_until=NULL,last_error_code=NULL
    WHERE id=_event_id;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.claim_public_api_idempotency(_tenant_id uuid, _token_id uuid, _operation text, _idempotency_key text, _request_hash text)
 RETURNS TABLE(claim_state text, stored_status integer, stored_body jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
                          DECLARE existing public.public_api_idempotency%ROWTYPE;
                          BEGIN
                            IF length(_operation) NOT BETWEEN 1 AND 120 OR length(_idempotency_key) NOT BETWEEN 1 AND 128 OR _request_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'Invalid idempotency claim'; END IF;
                              INSERT INTO public.public_api_idempotency (tenant_id,token_id,operation,idempotency_key,request_hash) VALUES (_tenant_id,_token_id,_operation,_idempotency_key,_request_hash) ON CONFLICT (tenant_id,token_id,operation,idempotency_key) DO NOTHING;
                                IF FOUND THEN RETURN QUERY SELECT 'claimed'::text,NULL::integer,NULL::jsonb; RETURN; END IF;
                                  SELECT * INTO existing FROM public.public_api_idempotency WHERE tenant_id=_tenant_id AND token_id=_token_id AND operation=_operation AND idempotency_key=_idempotency_key FOR UPDATE;
                                    IF existing.request_hash <> _request_hash THEN RETURN QUERY SELECT 'conflict'::text,NULL::integer,NULL::jsonb;
                                      ELSIF existing.state='completed' THEN RETURN QUERY SELECT 'replay'::text,existing.response_status,existing.response_body;
                                        ELSIF existing.updated_at < now()-interval '5 minutes' THEN UPDATE public.public_api_idempotency SET request_hash=_request_hash,updated_at=now(),expires_at=now()+interval '24 hours' WHERE id=existing.id; RETURN QUERY SELECT 'claimed'::text,NULL::integer,NULL::jsonb;
                                          ELSE RETURN QUERY SELECT 'in_progress'::text,NULL::integer,NULL::jsonb; END IF;
                                          END; $function$

CREATE OR REPLACE FUNCTION public.watcher_scope_allows_as(_actor uuid, _watcher uuid, _action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE v_watcher public.data_watchers%ROWTYPE; v_role text; v_registry uuid; v_source_registry uuid;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' OR _actor IS NULL OR _watcher IS NULL
     OR _action NOT IN ('view','run') THEN RETURN false; END IF;
  SELECT * INTO v_watcher FROM public.data_watchers WHERE id=_watcher;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT tm.role::text INTO v_role FROM public.tenant_members tm
    WHERE tm.tenant_id=v_watcher.tenant_id AND tm.user_id=_actor AND tm.active;
  IF v_role IS NULL THEN RETURN false; END IF;
  IF v_watcher.access_mode='legacy_passthrough' THEN
    RETURN _action='view' OR v_role IN ('tenant_admin','tenant_analyst');
  END IF;
  IF v_watcher.access_mode='unmapped_pending' THEN RETURN v_role='tenant_admin'; END IF;
  SELECT id INTO v_registry FROM public.data_resource_registry
    WHERE tenant_id=v_watcher.tenant_id AND resource_type='file_watcher' AND file_watcher_id=_watcher;
  SELECT id INTO v_source_registry FROM public.data_resource_registry
    WHERE tenant_id=v_watcher.tenant_id AND resource_type='data_source'
      AND data_source_id=v_watcher.data_source_id;
  RETURN v_registry IS NOT NULL AND v_source_registry IS NOT NULL
    AND private.data_resource_shadow_allows_actor(_actor,v_registry,_action)
    AND private.data_resource_shadow_allows_actor(_actor,v_source_registry,'view');
END $function$

CREATE OR REPLACE FUNCTION public.wfm_get_control_request(_tenant_id uuid, _request_key uuid, _bu_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);r private.wfm_requests%ROWTYPE;ep bigint;
BEGIN
 IF _request_key IS NULL THEN RAISE EXCEPTION 'wfm.invalid_request' USING ERRCODE='22023';END IF;
 IF private.wfm_can_manage(_tenant_id,false) IS DISTINCT FROM true THEN RAISE EXCEPTION 'wfm.admin_permission_denied' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('wfm:'||_tenant_id::text,0));
 SELECT * INTO r FROM private.wfm_requests WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND AND (r.result->>'bu_id')::uuid IS DISTINCT FROM _bu_id THEN RAISE EXCEPTION 'wfm.request_scope_denied' USING ERRCODE='42501';END IF;
 SELECT coalesce((SELECT epoch FROM private.wfm_epoch WHERE tenant_id=_tenant_id),0) INTO ep;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'bu_id',_bu_id,'request_key',_request_key,'current_epoch',ep::text,
 'outcome',CASE WHEN r.request_key IS NULL THEN 'absent' ELSE 'recorded' END,'receipt',r.result);
END $function$

CREATE OR REPLACE FUNCTION public.manage_file_watcher_access(_tenant_id uuid, _watcher_id uuid, _owner_bu_ids uuid[], _group_ids uuid[], _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_registry uuid; v_group uuid; v_bu uuid; v_grant uuid;
  v_owners uuid[]; v_groups uuid[]; v_matched boolean;
BEGIN
  IF _tenant_id IS NULL OR _watcher_id IS NULL OR v_actor IS NULL OR _reason IS NULL
    OR length(btrim(_reason)) NOT BETWEEN 3 AND 500 THEN RAISE EXCEPTION 'invalid watcher access request'; END IF;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_owners
    FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) x;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x),ARRAY[]::uuid[]) INTO v_groups
    FROM unnest(coalesce(_group_ids,ARRAY[]::uuid[])) x;
  IF cardinality(v_owners) NOT BETWEEN 1 AND 20 OR cardinality(v_groups) NOT BETWEEN 1 AND 50
    OR NOT EXISTS (SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=_tenant_id
      AND tm.user_id=v_actor AND tm.active AND tm.role='tenant_admin'::public.tenant_role)
    OR NOT EXISTS (SELECT 1 FROM public.data_watchers w WHERE w.id=_watcher_id AND w.tenant_id=_tenant_id)
  THEN RAISE EXCEPTION 'not authorized or access tags incomplete' USING ERRCODE='42501'; END IF;
  SELECT r.id INTO v_registry FROM public.data_resource_registry r
    WHERE r.tenant_id=_tenant_id AND r.resource_type='file_watcher' AND r.file_watcher_id=_watcher_id FOR UPDATE;
  IF v_registry IS NULL THEN
    SELECT public.register_typed_data_resource('file_watcher',_watcher_id,v_owners,btrim(_reason)) INTO v_registry;
  ELSE
    FOR v_grant IN SELECT g.id FROM public.data_resource_registry_grants g
      WHERE g.tenant_id=_tenant_id AND g.registry_id=v_registry
        AND g.principal_type='group' AND g.action='view'
    LOOP PERFORM public.revoke_typed_data_resource_action(v_grant,btrim(_reason)); END LOOP;
    PERFORM public.set_typed_data_resource_owners(v_registry,v_owners,btrim(_reason));
  END IF;
  FOREACH v_group IN ARRAY v_groups LOOP
    v_matched:=false;
    FOREACH v_bu IN ARRAY v_owners LOOP
      IF EXISTS (SELECT 1 FROM public.bu_group_assignments a
        WHERE a.tenant_id=_tenant_id AND a.group_id=v_group
          AND (a.bu_id=v_bu OR (a.inherit_descendants AND EXISTS (
            SELECT 1 FROM public.business_units assigned JOIN public.business_units target
              ON target.id=v_bu AND target.tenant_id=_tenant_id
            WHERE assigned.id=a.bu_id AND assigned.tenant_id=_tenant_id AND target.path <@ assigned.path))))
      THEN
        PERFORM public.grant_typed_data_resource_action(v_registry,v_bu,'group',v_group,'view',btrim(_reason));
        v_matched:=true;
      END IF;
    END LOOP;
    IF NOT v_matched THEN RAISE EXCEPTION 'group is not assigned to any selected owner BU'; END IF;
  END LOOP;
  RETURN v_registry;
END $function$

CREATE OR REPLACE FUNCTION public.guard_collateral_csa_typed_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_tenant uuid; v_agreement uuid; v_call uuid;
  v_action text;
BEGIN
  IF TG_OP='DELETE' THEN v_tenant:=OLD.tenant_id; ELSE v_tenant:=NEW.tenant_id; END IF;
  IF TG_TABLE_NAME='collateral_csa_agreements' THEN
    IF TG_OP='INSERT' THEN
      IF v_actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members m
        WHERE m.tenant_id=v_tenant AND m.user_id=v_actor AND m.active
          AND m.role='tenant_admin'::public.tenant_role) THEN
        RAISE EXCEPTION 'active tenant administrator required for CSA creation' USING ERRCODE='42501';
      END IF;
      RETURN NEW;
    END IF;
    v_agreement:=OLD.id;
  ELSIF TG_TABLE_NAME='collateral_csa_versions' OR TG_TABLE_NAME='collateral_csa_calls' THEN
    v_agreement:=CASE WHEN TG_OP='DELETE' THEN OLD.agreement_id ELSE NEW.agreement_id END;
  ELSE
    v_call:=CASE WHEN TG_OP='DELETE' THEN OLD.call_id ELSE NEW.call_id END;
    SELECT c.agreement_id INTO v_agreement FROM public.collateral_csa_calls c
      WHERE c.id=v_call AND c.tenant_id=v_tenant;
  END IF;
  v_action:=CASE WHEN TG_OP='DELETE' THEN 'manage'
    WHEN TG_TABLE_NAME='collateral_csa_calls' AND TG_OP='INSERT' THEN 'run'
    ELSE 'edit' END;
  IF v_agreement IS NULL OR NOT private.collateral_csa_typed_allows(
      v_actor,v_tenant,v_agreement,v_action) THEN
    RAISE EXCEPTION 'CSA action is outside the current agreement BU/group access'
      USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.enqueue_workflow_api_job(_tenant_id uuid, _token_id uuid, _actor_user_id uuid, _job_kind text, _resource_id uuid, _idempotency_key text)
 RETURNS TABLE(job_id uuid, job_status text, idempotent_replay boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  inserted_id uuid;
  existing_status text;
  stored_kind text := _job_kind;
  schedule_type text;
BEGIN
  IF _actor_user_id IS NULL THEN
    RAISE EXCEPTION 'API token must have an accountable creator';
  END IF;
  IF _job_kind NOT IN ('data_prep_run', 'recon_run', 'connector_run') THEN
    RAISE EXCEPTION 'Unsupported workflow job kind';
  END IF;
  IF length(_idempotency_key) < 1 OR length(_idempotency_key) > 128 THEN
    RAISE EXCEPTION 'Invalid idempotency key';
  END IF;
  IF _job_kind = 'data_prep_run' AND NOT EXISTS (
    SELECT 1 FROM public.data_prep_pipelines
    WHERE id = _resource_id AND tenant_id = _tenant_id AND enabled
  ) THEN
    RAISE EXCEPTION 'Data Prep pipeline not found';
  END IF;
  IF _job_kind = 'recon_run' AND NOT EXISTS (
    SELECT 1 FROM public.recon_definitions
    WHERE id = _resource_id AND tenant_id = _tenant_id AND status <> 'archived'
  ) THEN
    RAISE EXCEPTION 'Reconciliation not found';
  END IF;
  IF _job_kind = 'connector_run' THEN
    SELECT connector_type INTO schedule_type
    FROM public.data_source_schedules
    WHERE id = _resource_id
      AND tenant_id = _tenant_id
      AND connector_type IN (
        'http', 'https', 'rest', 's3', 'azure_blob', 'gcs', 'bigquery', 'snowflake',
        'databricks', 'sftp', 'ftp', 'local', 'network_drive'
      );
    IF schedule_type IS NULL THEN
      RAISE EXCEPTION 'Executable connector schedule not found';
    END IF;
    IF schedule_type IN ('sftp', 'ftp', 'local', 'network_drive') THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.data_source_schedules
        WHERE id = _resource_id
          AND tenant_id = _tenant_id
          AND config->>'agent_id' ~ '^[A-Za-z0-9][A-Za-z0-9._-]{2,63}$'
      ) THEN
        RAISE EXCEPTION 'Approved connector agent identifier is required';
      END IF;
      stored_kind := 'connector_agent_run';
    END IF;
  END IF;

  INSERT INTO public.workflow_api_jobs(
    tenant_id, token_id, actor_user_id, job_kind, resource_id, idempotency_key
  ) VALUES (
    _tenant_id, _token_id, _actor_user_id, stored_kind, _resource_id, _idempotency_key
  )
  ON CONFLICT (tenant_id, job_kind, resource_id, idempotency_key) DO NOTHING
  RETURNING id INTO inserted_id;

  IF inserted_id IS NULL THEN
    SELECT id, status INTO inserted_id, existing_status
    FROM public.workflow_api_jobs
    WHERE tenant_id = _tenant_id
      AND job_kind = stored_kind
      AND resource_id = _resource_id
      AND idempotency_key = _idempotency_key;
    RETURN QUERY SELECT inserted_id, existing_status, true;
    RETURN;
  END IF;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    _actor_user_id, _tenant_id, 'workspace', 'api.workflow.enqueue',
    'workflow_api_job', inserted_id::text,
    jsonb_build_object('job_kind', stored_kind, 'resource_id', _resource_id, 'token_id', _token_id)
  );

  RETURN QUERY SELECT inserted_id, 'queued'::text, false;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_connector_agent_job(_tenant_id uuid, _token_id uuid, _agent_id text, _job_id uuid, _rows jsonb, _columns jsonb, _filename text, _content_sha256 text, _size_bytes bigint)
 RETURNS TABLE(job_status text, upload_id uuid, row_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  job public.workflow_api_jobs%ROWTYPE;
  schedule public.data_source_schedules%ROWTYPE;
  created_upload uuid;
  rows_count integer;
  run_id bigint;
BEGIN
  IF jsonb_typeof(_rows) <> 'array' OR jsonb_typeof(_columns) <> 'array' THEN
    RAISE EXCEPTION 'Invalid connector rows';
  END IF;
  rows_count := jsonb_array_length(_rows);
  IF rows_count > 50000 OR jsonb_array_length(_columns) > 500 OR _size_bytes < 0
     OR _size_bytes > 10485760 OR length(_filename) < 1 OR length(_filename) > 255
     OR _content_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Connector result exceeds limits';
  END IF;

  SELECT * INTO job FROM public.workflow_api_jobs
  WHERE id = _job_id AND tenant_id = _tenant_id AND job_kind = 'connector_agent_run'
  FOR UPDATE;
  IF job.id IS NULL OR job.status <> 'running' OR job.lease_token_id <> _token_id
     OR job.lease_agent_id <> _agent_id OR job.lease_expires_at < now() THEN
    RAISE EXCEPTION 'Connector agent lease is not valid';
  END IF;

  SELECT * INTO schedule FROM public.data_source_schedules
  WHERE id = job.resource_id AND tenant_id = _tenant_id
    AND connector_type IN ('sftp', 'ftp', 'local', 'network_drive');
  IF schedule.id IS NULL THEN RAISE EXCEPTION 'Connector schedule not found'; END IF;

  INSERT INTO public.workspace_data_source_uploads(
    data_source_id, tenant_id, filename, mime_type, size_bytes, row_count,
    columns, sample_rows, rows, content_sha256, uploaded_by
  ) VALUES (
    schedule.data_source_id, _tenant_id, _filename, 'application/json', _size_bytes, rows_count,
    _columns, (SELECT COALESCE(jsonb_agg(value), '[]'::jsonb)
      FROM (SELECT value FROM jsonb_array_elements(_rows) LIMIT 10) sample),
    _rows, _content_sha256, job.actor_user_id
  ) RETURNING id INTO created_upload;

  INSERT INTO public.data_source_runs(
    schedule_id, tenant_id, finished_at, status, rows_ingested, trigger
  ) VALUES (
    schedule.id, _tenant_id, now(), 'success', rows_count, 'agent'
  ) RETURNING id INTO run_id;

  UPDATE public.workspace_data_sources SET
    inferred_schema = _columns,
    sample_rows = (SELECT COALESCE(jsonb_agg(value), '[]'::jsonb)
      FROM (SELECT value FROM jsonb_array_elements(_rows) LIMIT 10) sample),
    row_count = rows_count,
    status = 'ready',
    last_error = NULL
  WHERE id = schedule.data_source_id AND tenant_id = _tenant_id;

  UPDATE public.data_source_schedules SET
    last_run_at = now(), last_status = 'success', last_rows_ingested = rows_count, last_error = NULL
  WHERE id = schedule.id;

  UPDATE public.workflow_api_jobs SET
    status = 'succeeded', completed_at = now(), error_code = NULL,
    result = jsonb_build_object('workflow_status', 'success', 'schedule_id', schedule.id,
      'rows', rows_count, 'upload_id', created_upload, 'run_id', run_id,
      'agent_id', _agent_id, 'connector_type', schedule.connector_type),
    lease_expires_at = NULL
  WHERE id = job.id;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    job.actor_user_id, _tenant_id, 'workspace', 'connector.agent.complete',
    'workflow_api_job', job.id::text,
    jsonb_build_object('agent_id', _agent_id, 'connector_type', schedule.connector_type,
      'schedule_id', schedule.id, 'rows', rows_count, 'upload_id', created_upload,
      'run_id', run_id, 'lease_token_id', _token_id)
  );

  RETURN QUERY SELECT 'succeeded'::text, created_upload, rows_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.activate_mapped_reference_after_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_table uuid;
BEGIN
  SELECT r.reference_table_id INTO v_table FROM public.data_resource_registry r
    WHERE r.id=NEW.registry_id AND r.tenant_id=NEW.tenant_id AND r.resource_type='reference_table';
  IF v_table IS NOT NULL THEN
    UPDATE public.reference_data_tables SET access_mode='mapped_exact'
      WHERE id=v_table AND tenant_id=NEW.tenant_id AND access_mode='unmapped_pending';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.wfm_save_draft_plan(_tenant_id uuid, _pipeline_id uuid, _mode text, _epoch text, _draft jsonb, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);p private.wfm_draft_plans%ROWTYPE;ep bigint;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('wfm:'||_tenant_id::text,0));
 IF _mode IS NULL OR _mode NOT IN('assisted','agentic') OR _request_key IS NULL OR _epoch IS NULL
 OR jsonb_typeof(_draft) IS DISTINCT FROM 'object' OR jsonb_typeof(_draft->'proposals') IS DISTINCT FROM 'array' OR jsonb_array_length(_draft->'proposals') NOT BETWEEN 1 AND 100
 OR _draft->>'draft_sha256' IS NULL OR _draft->>'draft_sha256'!~'^[a-f0-9]{64}$'
 OR _draft->>'configuration_version' IS NULL OR _draft->>'configuration_version'!~'^[1-9][0-9]{0,8}$'
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(_draft) k WHERE k NOT IN('proposals','draft_sha256','configuration_version'))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_draft->'proposals') a WHERE jsonb_typeof(a) IS DISTINCT FROM 'object' OR a->>'key' IS NULL OR length(a->>'key') NOT BETWEEN 1 AND 120
 OR a->>'action' IS NULL OR a->>'action' NOT IN('draft_map','draft_transform','draft_dq','sandbox_test','sandbox_self_repair') OR (_mode='assisted' AND a->>'action'='sandbox_self_repair')
 OR a->>'content_sha256' IS NULL OR a->>'content_sha256'!~'^[a-f0-9]{64}$')
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_draft->'proposals') a CROSS JOIN LATERAL jsonb_object_keys(a) k WHERE k NOT IN('key','action','content_sha256'))
 OR (SELECT count(*) FROM jsonb_array_elements(_draft->'proposals'))<>(SELECT count(DISTINCT a->>'key') FROM jsonb_array_elements(_draft->'proposals') a)
 THEN RAISE EXCEPTION 'wfm.invalid_draft_plan' USING ERRCODE='22023';END IF;
 IF private.wfm_mode_allowed(_tenant_id,_mode,NULL) IS DISTINCT FROM true OR public.user_has_permission(actor,_tenant_id,'data.prep.author',NULL) IS DISTINCT FROM true
 OR private.data_prep_pipeline_scope_allows(actor,_tenant_id,_pipeline_id,'edit') IS DISTINCT FROM true
 OR NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines WHERE id=_pipeline_id AND tenant_id=_tenant_id AND version=(_draft->>'configuration_version')::integer)
 OR coalesce((SELECT mode FROM private.wfm_pipeline_modes WHERE tenant_id=_tenant_id AND pipeline_id=_pipeline_id),'manual')<>_mode THEN RAISE EXCEPTION 'wfm.draft_plan_denied' USING ERRCODE='42501';END IF;
 SELECT coalesce((SELECT epoch FROM private.wfm_epoch WHERE tenant_id=_tenant_id),0) INTO ep;
 IF ep::text<>_epoch THEN RAISE EXCEPTION 'wfm.epoch_conflict' USING ERRCODE='PT409';END IF;
 SELECT * INTO p FROM private.wfm_draft_plans WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF p.draft IS DISTINCT FROM _draft OR p.pipeline_id IS DISTINCT FROM _pipeline_id OR p.mode IS DISTINCT FROM _mode THEN RAISE EXCEPTION 'wfm.request_conflict' USING ERRCODE='PT409';END IF;
 ELSE INSERT INTO private.wfm_draft_plans(tenant_id,pipeline_id,actor_id,mode,epoch,request_key,draft) VALUES(_tenant_id,_pipeline_id,actor,_mode,ep,_request_key,_draft) RETURNING * INTO p;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','dataprep.draft_plan.created','draft_plan',p.id::text,jsonb_build_object('mode',_mode,'epoch',ep::text,'draft_sha256',encode(sha256(convert_to(_draft::text,'UTF8')),'hex')));END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'plan_id',p.id,'epoch',ep::text,'draft_only',true);
END $function$

CREATE OR REPLACE FUNCTION public.wfm_decide_proposal(_tenant_id uuid, _pipeline_id uuid, _plan_id uuid, _proposal_key text, _accept boolean, _epoch text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);p private.wfm_draft_plans%ROWTYPE;e private.wfm_plan_events%ROWTYPE;ep bigint;decision text:=CASE WHEN _accept THEN 'accepted' ELSE 'rejected' END;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('wfm:'||_tenant_id::text,0));
 SELECT * INTO p FROM private.wfm_draft_plans WHERE id=_plan_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id FOR UPDATE;
 IF NOT FOUND OR _accept IS NULL OR _epoch IS NULL OR private.wfm_mode_allowed(_tenant_id,p.mode,NULL) IS DISTINCT FROM true
 OR public.user_has_permission(actor,_tenant_id,'data.prep.author',NULL) IS DISTINCT FROM true OR private.data_prep_pipeline_scope_allows(actor,_tenant_id,_pipeline_id,'edit') IS DISTINCT FROM true
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p.draft->'proposals') a WHERE a->>'key'=_proposal_key)
 OR EXISTS(SELECT 1 FROM private.wfm_plan_events WHERE plan_id=_plan_id AND event='cancelled') THEN RAISE EXCEPTION 'wfm.proposal_denied' USING ERRCODE='42501';END IF;
 SELECT coalesce((SELECT epoch FROM private.wfm_epoch WHERE tenant_id=_tenant_id),0) INTO ep;
 IF ep::text<>_epoch OR p.epoch<>ep THEN RAISE EXCEPTION 'wfm.epoch_conflict' USING ERRCODE='PT409';END IF;
 SELECT * INTO e FROM private.wfm_plan_events WHERE plan_id=_plan_id AND proposal_key=_proposal_key AND event IN('accepted','rejected');
 IF FOUND THEN IF e.event<>decision OR e.actor_id<>actor THEN RAISE EXCEPTION 'wfm.decision_immutable' USING ERRCODE='PT409';END IF;
 ELSE INSERT INTO private.wfm_plan_events(plan_id,actor_id,event,proposal_key) VALUES(_plan_id,actor,decision,_proposal_key) RETURNING * INTO e;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','dataprep.proposal.decision','draft_plan',_plan_id::text,jsonb_build_object('proposal_key',_proposal_key,'decision',decision,'epoch',ep::text,'publication_authorized',false));END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'event_id',e.id,'decision',decision,'draft_only',true,'publication_authorized',false);
END $function$

CREATE OR REPLACE FUNCTION public.fail_connector_agent_job(_tenant_id uuid, _token_id uuid, _agent_id text, _job_id uuid, _error_code text)
 RETURNS TABLE(job_status text, retry_after_seconds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  job public.workflow_api_jobs%ROWTYPE;
  schedule public.data_source_schedules%ROWTYPE;
  retryable boolean;
  delay_seconds integer;
BEGIN
  IF _error_code !~ '^connector_agent_[a-z0-9_]{1,80}$' THEN
    RAISE EXCEPTION 'Invalid connector agent error code';
  END IF;
  SELECT * INTO job FROM public.workflow_api_jobs
  WHERE id = _job_id AND tenant_id = _tenant_id AND job_kind = 'connector_agent_run'
  FOR UPDATE;
  IF job.id IS NULL OR job.status <> 'running' OR job.lease_token_id <> _token_id
     OR job.lease_agent_id <> _agent_id OR job.lease_expires_at < now() THEN
    RAISE EXCEPTION 'Connector agent lease is not valid';
  END IF;
  SELECT * INTO schedule FROM public.data_source_schedules
  WHERE id = job.resource_id AND tenant_id = _tenant_id;
  retryable := job.attempts < job.max_attempts;
  delay_seconds := LEAST(900, 30 * (2 ^ GREATEST(0, job.attempts - 1))::integer);

  UPDATE public.workflow_api_jobs SET
    status = CASE WHEN retryable THEN 'failed' ELSE 'dead' END,
    available_at = CASE WHEN retryable THEN now() + make_interval(secs => delay_seconds) ELSE now() END,
    completed_at = CASE WHEN retryable THEN NULL ELSE now() END,
    error_code = _error_code, lease_expires_at = NULL
  WHERE id = job.id;

  INSERT INTO public.data_source_runs(
    schedule_id, tenant_id, finished_at, status, error, trigger
  ) VALUES (schedule.id, _tenant_id, now(), 'failed', _error_code, 'agent');
  UPDATE public.data_source_schedules SET
    last_run_at = now(), last_status = 'failed', last_error = _error_code
  WHERE id = schedule.id;
  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    job.actor_user_id, _tenant_id, 'workspace',
    CASE WHEN retryable THEN 'connector.agent.retry_scheduled' ELSE 'connector.agent.dead' END,
    'workflow_api_job', job.id::text,
    jsonb_build_object('agent_id', _agent_id, 'connector_type', schedule.connector_type,
      'schedule_id', schedule.id, 'attempt', job.attempts, 'error_code', _error_code,
      'retry_after_seconds', CASE WHEN retryable THEN delay_seconds ELSE 0 END,
      'lease_token_id', _token_id)
  );
  RETURN QUERY SELECT CASE WHEN retryable THEN 'failed' ELSE 'dead' END,
    CASE WHEN retryable THEN delay_seconds ELSE 0 END;
END;
$function$

