CREATE OR REPLACE FUNCTION public.record_data_watcher_evaluation(_tenant_id uuid, _watcher_id uuid, _new_state text, _outcome_code text, _detail jsonb, _trigger text, _actor_user_id uuid, _reminder_hours numeric, _quarantine_on_alert boolean, _checked_at timestamp with time zone)
 RETURNS TABLE(event_id uuid, previous_state text, notification_created boolean, source_quarantined boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
                                                                                        DECLARE
                                                                                          w public.data_watchers%ROWTYPE;
                                                                                            event_uuid uuid;
                                                                                              should_notify boolean := false;
                                                                                                notification_kind text;
                                                                                                  notification_title text;
                                                                                                    quarantined boolean := false;
                                                                                                    BEGIN
                                                                                                      IF _new_state NOT IN ('ok', 'alert', 'insufficient_data') THEN
                                                                                                          RAISE EXCEPTION 'Invalid watcher state';
                                                                                                            END IF;
                                                                                                              IF _trigger NOT IN ('browser', 'api', 'schedule') THEN
                                                                                                                  RAISE EXCEPTION 'Invalid watcher trigger';
                                                                                                                    END IF;
                                                                                                                      IF _outcome_code !~ '^[a-z][a-z0-9_]{1,63}$' THEN
                                                                                                                          RAISE EXCEPTION 'Invalid watcher outcome';
                                                                                                                            END IF;
                                                                                                                              IF _reminder_hours < 1 OR _reminder_hours > 720 THEN
                                                                                                                                  RAISE EXCEPTION 'Invalid watcher reminder interval';
                                                                                                                                    END IF;

                                                                                                                                      SELECT * INTO w
                                                                                                                                        FROM public.data_watchers
                                                                                                                                          WHERE id = _watcher_id AND tenant_id = _tenant_id AND enabled
                                                                                                                                            FOR UPDATE;
                                                                                                                                              IF NOT FOUND THEN RAISE EXCEPTION 'Watcher not found or disabled'; END IF;

                                                                                                                                                IF _new_state = 'alert' AND (
                                                                                                                                                    w.last_state IS DISTINCT FROM 'alert'
                                                                                                                                                        OR w.last_alerted_at IS NULL
                                                                                                                                                            OR w.last_alerted_at + make_interval(secs => (_reminder_hours * 3600)::double precision) <= _checked_at
                                                                                                                                                              ) THEN
                                                                                                                                                                  should_notify := true;
                                                                                                                                                                      notification_kind := 'watcher.alert';
                                                                                                                                                                          notification_title := 'Watcher alert: ' || w.name;
                                                                                                                                                                            ELSIF _new_state = 'ok' AND w.last_state = 'alert' THEN
                                                                                                                                                                                should_notify := true;
                                                                                                                                                                                    notification_kind := 'watcher.recovered';
                                                                                                                                                                                        notification_title := 'Watcher recovered: ' || w.name;
                                                                                                                                                                                          END IF;

                                                                                                                                                                                            UPDATE public.data_watchers SET
                                                                                                                                                                                                last_checked_at = _checked_at,
                                                                                                                                                                                                    last_state = _new_state,
                                                                                                                                                                                                        last_alerted_at = CASE WHEN should_notify AND _new_state = 'alert' THEN _checked_at ELSE last_alerted_at END
                                                                                                                                                                                                          WHERE id = _watcher_id AND tenant_id = _tenant_id;

                                                                                                                                                                                                            IF _new_state = 'alert' AND _quarantine_on_alert THEN
                                                                                                                                                                                                                UPDATE public.workspace_data_sources
                                                                                                                                                                                                                    SET status = 'error', last_error = 'Watcher quarantine: ' || _outcome_code
                                                                                                                                                                                                                        WHERE id = w.data_source_id AND tenant_id = _tenant_id AND status <> 'archived'
                                                                                                                                                                                                                              AND (status <> 'error' OR last_error IS DISTINCT FROM 'Watcher quarantine: ' || _outcome_code);
                                                                                                                                                                                                                                  quarantined := FOUND;
                                                                                                                                                                                                                                    END IF;

                                                                                                                                                                                                                                      INSERT INTO public.data_watcher_events(
                                                                                                                                                                                                                                          tenant_id, watcher_id, previous_state, new_state, outcome_code, detail,
                                                                                                                                                                                                                                              trigger, actor_user_id, notification_created, occurred_at
                                                                                                                                                                                                                                                ) VALUES (
                                                                                                                                                                                                                                                    _tenant_id, _watcher_id, w.last_state, _new_state, _outcome_code,
                                                                                                                                                                                                                                                        COALESCE(_detail, '{}'::jsonb), _trigger, _actor_user_id, should_notify, _checked_at
                                                                                                                                                                                                                                                          ) RETURNING id INTO event_uuid;

                                                                                                                                                                                                                                                            IF should_notify AND w.created_by IS NOT NULL THEN
                                                                                                                                                                                                                                                                INSERT INTO public.notifications(user_id, tenant_id, kind, severity, title, body, context)
                                                                                                                                                                                                                                                                    VALUES (
                                                                                                                                                                                                                                                                          w.created_by, _tenant_id, notification_kind,
                                                                                                                                                                                                                                                                                CASE WHEN _new_state = 'alert' AND w.severity = 'critical' THEN 'error'
                                                                                                                                                                                                                                                                                           WHEN _new_state = 'alert' THEN w.severity ELSE 'info' END,
                                                                                                                                                                                                                                                                                                 notification_title, _outcome_code,
                                                                                                                                                                                                                                                                                                       jsonb_build_object('watcher_id', _watcher_id, 'event_id', event_uuid, 'outcome_code', _outcome_code)
                                                                                                                                                                                                                                                                                                           );
                                                                                                                                                                                                                                                                                                             ELSE
                                                                                                                                                                                                                                                                                                                 should_notify := false;
                                                                                                                                                                                                                                                                                                                   END IF;

                                                                                                                                                                                                                                                                                                                     INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
                                                                                                                                                                                                                                                                                                                       VALUES (
                                                                                                                                                                                                                                                                                                                           _actor_user_id, _tenant_id,
                                                                                                                                                                                                                                                                                                                               CASE WHEN _trigger = 'schedule' THEN 'system' ELSE 'workspace' END,
                                                                                                                                                                                                                                                                                                                                   'watcher.evaluated', 'data_watcher', _watcher_id::text,
                                                                                                                                                                                                                                                                                                                                       jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                             'event_id', event_uuid, 'previous_state', w.last_state, 'new_state', _new_state,
                                                                                                                                                                                                                                                                                                                                                   'outcome_code', _outcome_code, 'trigger', _trigger, 'notification_created', should_notify,
                                                                                                                                                                                                                                                                                                                                                         'source_quarantined', quarantined
                                                                                                                                                                                                                                                                                                                                                             )
                                                                                                                                                                                                                                                                                                                                                               );

                                                                                                                                                                                                                                                                                                                                                                 RETURN QUERY SELECT event_uuid, w.last_state, should_notify, quarantined;
                                                                                                                                                                                                                                                                                                                                                                 END;
                                                                                                                                                                                                                                                                                                                                                                 $function$

CREATE OR REPLACE FUNCTION public.reference_scope_allows(_table uuid, _action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE v_table public.reference_data_tables%ROWTYPE; v_actor uuid:=auth.uid(); v_role text; v_registry uuid;
BEGIN
  IF v_actor IS NULL OR _table IS NULL OR _action NOT IN ('view','ingest','edit','approve','manage') THEN RETURN false; END IF;
  SELECT * INTO v_table FROM public.reference_data_tables WHERE id=_table;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT tm.role::text INTO v_role FROM public.tenant_members tm
    WHERE tm.tenant_id=v_table.tenant_id AND tm.user_id=v_actor AND tm.active=true;
  IF v_role IS NULL THEN RETURN false; END IF;
  IF v_table.access_mode='legacy_passthrough' THEN
    RETURN _action='view' OR v_role IN ('tenant_admin','tenant_analyst'); END IF;
  IF v_table.access_mode='unmapped_pending' THEN RETURN v_role='tenant_admin'; END IF;
  IF v_table.access_mode<>'mapped_exact' THEN RETURN false; END IF;
  SELECT id INTO v_registry FROM public.data_resource_registry
    WHERE tenant_id=v_table.tenant_id AND resource_type='reference_table' AND reference_table_id=_table;
  IF v_registry IS NULL THEN RETURN false; END IF;
  -- The version RPC independently enforces maker/checker separation. The
  -- generic evaluator deliberately denies approve, so active tenant-admin
  -- override is explicit here and cannot grant self-approval by itself.
  IF _action='approve' THEN RETURN v_role='tenant_admin'; END IF;
  RETURN private.data_resource_shadow_allows_actor(v_actor,v_registry,_action);
END $function$

CREATE OR REPLACE FUNCTION public.request_recon_definition_edit(_tenant_id uuid, _recon_id uuid, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE actor uuid; d public.recon_definitions%ROWTYPE; v_id uuid; v_version integer; v_hash text; mapping jsonb;
BEGIN
 -- Registered availability at the actual native tenant scope; original mapped authority/independent checker/audit program follows unchanged.
 PERFORM private.wfm_actor(_tenant_id);
 PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

 IF _tenant_id IS NULL OR _recon_id IS NULL OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'invalid governance request' USING ERRCODE='22023'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('mapped-recon:'||_tenant_id::text||':'||_recon_id::text,0));
 PERFORM private.mapped_recon_governance_lock_scope(_tenant_id,_recon_id);
 SELECT * INTO d FROM public.recon_definitions WHERE id=_recon_id AND tenant_id=_tenant_id;
 IF NOT FOUND OR d.access_mode<>'mapped_exact' OR d.governance_state<>'approved_locked' OR d.environment<>'production'
 OR d.status<>'active' OR d.retired_at IS NOT NULL THEN PERFORM private.mapped_recon_governance_conflict('edit_parent_not_eligible'); END IF;
 actor:=private.mapped_recon_governance_actor(_tenant_id,d.id,'edit',false);
 IF EXISTS(SELECT 1 FROM public.recon_retirement_requests WHERE tenant_id=_tenant_id AND recon_id=d.id AND status='pending')
 OR EXISTS(SELECT 1 FROM public.recon_definition_governance_requests WHERE tenant_id=_tenant_id AND parent_definition_id=d.id AND status='pending')
 OR EXISTS(SELECT 1 FROM public.recon_definitions WHERE tenant_id=_tenant_id AND governance_parent_id=d.id AND governance_state IN ('staging_copy','promotion_request_pending')) THEN PERFORM private.mapped_recon_governance_conflict('pending_workflow_exists'); END IF;
 SELECT version_number,snapshot_sha256 INTO v_version,v_hash FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=d.id ORDER BY version_number DESC LIMIT 1;
 IF v_version IS NULL OR v_hash IS DISTINCT FROM private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(d))
 OR NOT EXISTS(SELECT 1 FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=d.id
  AND version_number=v_version AND snapshot=private.recon_definition_config_snapshot(d)
  AND snapshot_sha256=private.mapped_recon_governance_hash(snapshot)
  AND EXISTS(SELECT 1 FROM public.recon_definition_governance_requests evidence_request
   JOIN public.recon_definition_governance_audit evidence_audit ON evidence_audit.request_id=evidence_request.id
   WHERE evidence_request.id=recon_definition_approved_versions.request_id AND evidence_request.tenant_id=_tenant_id
    AND evidence_request.parent_definition_id=d.id AND evidence_request.request_kind='promotion' AND evidence_request.status='approved'
    AND evidence_request.decided_by=recon_definition_approved_versions.approved_by
    AND evidence_request.snapshot=recon_definition_approved_versions.snapshot AND evidence_request.snapshot_sha256=v_hash
    AND evidence_audit.tenant_id=_tenant_id AND evidence_audit.parent_definition_id=d.id
    AND evidence_audit.event_type='version_approved' AND evidence_audit.actor_id=recon_definition_approved_versions.approved_by
    AND evidence_audit.snapshot_sha256=v_hash)) THEN
  PERFORM private.mapped_recon_governance_conflict('approved_version_evidence_required');
 END IF;
 mapping:=private.mapped_recon_governance_mapping(_tenant_id,d.id);
 INSERT INTO public.recon_definition_governance_requests(tenant_id,parent_definition_id,request_kind,requested_by,reason,source_version,source_sha256,mapped_governance_version,parent_config_fingerprint,parent_mapping_snapshot,parent_mapping_fingerprint)
 VALUES(_tenant_id,d.id,'edit',actor,btrim(_reason),v_version,v_hash,1,private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(d)),mapping,private.mapped_recon_governance_hash(mapping)) RETURNING id INTO v_id;
 INSERT INTO private.mapped_recon_governance_transitions(request_id,actor_id,purpose) VALUES(v_id,actor,'edit_request');
 PERFORM set_config('fvi.recon_governance_request_id',v_id::text,true);
 UPDATE public.recon_definitions SET governance_state='edit_request_pending' WHERE id=d.id;
 INSERT INTO public.recon_definition_governance_audit(tenant_id,request_id,parent_definition_id,event_type,actor_id,reason,snapshot_sha256) VALUES(_tenant_id,v_id,d.id,'edit_requested',actor,btrim(_reason),v_hash);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','recon.definition.edit_requested','recon_definition',d.id::text,jsonb_build_object('request_id',v_id,'approved_version',v_version,'snapshot_sha256',v_hash,'mapping_fingerprint',private.mapped_recon_governance_hash(mapping)));
 RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_tenant_email_domain_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_email text; v_domain text;
BEGIN
  IF public.is_platform_admin(NEW.user_id) THEN RETURN NEW; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_email_domains WHERE tenant_id=NEW.tenant_id) THEN RETURN NEW; END IF;
  SELECT lower(u.email) INTO v_email FROM auth.users u
    WHERE u.id=NEW.user_id AND u.email_confirmed_at IS NOT NULL;
  v_domain := split_part(coalesce(v_email,''),'@',2);
  IF NOT EXISTS (SELECT 1 FROM public.tenant_email_domains d
                 WHERE d.tenant_id=NEW.tenant_id AND d.domain=v_domain AND d.status='verified')
     OR EXISTS (SELECT 1 FROM public.tenant_members m
                WHERE m.user_id=NEW.user_id AND m.tenant_id<>NEW.tenant_id) THEN
    RAISE EXCEPTION 'Membership is unavailable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.copilot_broker_authorize(_verified_actor uuid, _verified_aal text, _verified_expires_at timestamp with time zone, _tenant_id uuid, _scope copilot_scope, _thread_id uuid, _request_ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE p public.platform_ai_settings%ROWTYPE; t public.tenant_ai_settings%ROWTYPE;
  s public.tenant_security_settings%ROWTYPE; th public.copilot_threads%ROWTYPE;
  entitled boolean; entitlement_count bigint; mode_write boolean := false; permitted_models text[];
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role'
   OR _verified_actor IS NULL OR _verified_aal IS NULL OR _verified_aal NOT IN ('aal1','aal2')
   OR _verified_expires_at IS NULL OR _verified_expires_at<=clock_timestamp()
   THEN RAISE EXCEPTION 'copilot.verified_subject_required'; END IF;
 -- Service identity remains explicit. Use the native peer-safe lifecycle predicate
 -- with the verified real actor; never set auth.uid/JWT claims to impersonate it.
 IF private.rlnext_account_allowed(_verified_actor,NULL) IS DISTINCT FROM true
   OR private.rlnext_account_allowed(_verified_actor,_tenant_id) IS DISTINCT FROM true
   THEN RAISE EXCEPTION 'copilot.account_denied'; END IF;
 -- The native peer predicate deliberately does not read a peer's JWT AAL.
 -- Preserve the real upstream verified claim separately for managed MFA requirements.
 IF _verified_aal<>'aal2' AND EXISTS(SELECT 1 FROM private.rlnext_accounts a
   WHERE a.user_id=_verified_actor AND a.mfa_required)
   THEN RAISE EXCEPTION 'copilot.mfa_required'; END IF;
 IF _scope IS NULL OR ((_scope='platform') IS DISTINCT FROM (_tenant_id IS NULL))
   THEN RAISE EXCEPTION 'copilot.scope_denied'; END IF;
 IF _tenant_id IS NULL THEN
   IF _verified_aal<>'aal2' OR (NOT coalesce(private.is_platform_admin(_verified_actor),false)
      AND NOT coalesce(private.is_platform_super_admin(_verified_actor),false))
     THEN RAISE EXCEPTION 'copilot.scope_denied'; END IF;
 ELSE
   IF NOT EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=_tenant_id
      AND tm.user_id=_verified_actor AND tm.active)
      OR NOT EXISTS(SELECT 1 FROM public.tenants tn WHERE tn.id=_tenant_id AND tn.ai_enabled)
      THEN RAISE EXCEPTION 'copilot.scope_denied'; END IF;
   SELECT * INTO s FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
   IF s.mfa_required AND _verified_aal<>'aal2' THEN RAISE EXCEPTION 'copilot.mfa_required'; END IF;
   IF s.ip_allowlist_enabled AND NOT coalesce(public.ip_in_tenant_allowlist(_tenant_id,_request_ip),false)
      THEN RAISE EXCEPTION 'copilot.ip_denied'; END IF;
   SELECT count(*),bool_and(allowed) INTO entitlement_count,entitled FROM public.tenant_feature_entitlements
     WHERE tenant_id=_tenant_id AND feature_key='copilot';
   IF entitlement_count<>1 OR entitled IS DISTINCT FROM true THEN RAISE EXCEPTION 'copilot.entitlement_denied'; END IF;
 END IF;
 IF _thread_id IS NOT NULL THEN
   SELECT * INTO th FROM public.copilot_threads WHERE id=_thread_id;
   IF NOT FOUND OR th.user_id IS DISTINCT FROM _verified_actor OR th.tenant_id IS DISTINCT FROM _tenant_id
      OR th.scope IS DISTINCT FROM _scope THEN RAISE EXCEPTION 'copilot.owned_thread_required'; END IF;
 END IF;
 SELECT * INTO p FROM public.platform_ai_settings WHERE id=true;
 IF NOT FOUND OR p.ai_enabled IS DISTINCT FROM true OR p.allow_copilot_global IS DISTINCT FROM true
   OR p.default_autonomy_ceiling IS NULL OR p.default_autonomy_ceiling NOT IN ('suggest','assist','auto')
   THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
 IF _tenant_id IS NOT NULL THEN
   SELECT * INTO t FROM public.tenant_ai_settings WHERE tenant_id=_tenant_id;
   IF NOT FOUND OR t.ai_enabled IS DISTINCT FROM true OR t.allow_copilot IS DISTINCT FROM true
      OR t.default_autonomy IS NULL OR t.default_autonomy NOT IN ('read_only','supervised','autonomous')
      THEN RAISE EXCEPTION 'copilot.policy_unavailable'; END IF;
   mode_write:=p.default_autonomy_ceiling<>'suggest' AND t.default_autonomy<>'read_only';
 END IF;
 permitted_models:=CASE WHEN _tenant_id IS NOT NULL AND cardinality(t.allowed_models)>0 THEN t.allowed_models ELSE p.global_allowed_models END;
 IF EXISTS(SELECT 1 FROM public.ai_governance_kill_switches k WHERE k.engaged
   AND k.scope IN ('global','copilot','copilot.chat') AND (k.tenant_id IS NULL OR k.tenant_id=_tenant_id))
   THEN RAISE EXCEPTION 'copilot.kill_switch'; END IF;
 RETURN jsonb_build_object('write_proposals',mode_write,'allowed_models',coalesce(to_jsonb(permitted_models),'[]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION private.recon_atomic_admit(_tenant uuid, _run uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE r public.recon_runs%ROWTYPE; d public.recon_definitions%ROWTYPE;
  v public.recon_definition_approved_versions%ROWTYPE; actor uuid:=auth.uid();
BEGIN
  IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN
    RAISE EXCEPTION 'Authenticated reconciliation actor required' USING ERRCODE='42501';
  END IF;
  IF NOT (private.rlnext_account_allowed(actor,NULL) AND private.rlnext_account_allowed(actor,_tenant)) THEN
    RAISE EXCEPTION 'Current reconciliation account lifecycle denied' USING ERRCODE='42501';
  END IF;
  SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant;
  IF NOT FOUND OR r.run_by IS DISTINCT FROM actor THEN
    RAISE EXCEPTION 'Owned reconciliation run unavailable' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.tenant_members
      WHERE tenant_id=_tenant AND user_id=actor AND active=true) THEN
    RAISE EXCEPTION 'Active reconciliation membership required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO d FROM public.recon_definitions WHERE id=r.definition_id AND tenant_id=_tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation scope unavailable' USING ERRCODE='42501'; END IF;
  IF d.access_mode='legacy_passthrough' THEN
    IF NOT(public.has_tenant_role(actor,_tenant,'tenant_admin'::public.tenant_role)
       OR public.has_tenant_role(actor,_tenant,'tenant_analyst'::public.tenant_role)) THEN
      RAISE EXCEPTION 'Current reconciliation writer access required' USING ERRCODE='42501';
    END IF;
  ELSIF d.access_mode='mapped_exact' AND d.governance_state<>'legacy_mapped' THEN
    PERFORM private.mapped_recon_governance_run(r);
  ELSE
    IF NOT public.recon_authoritative_access_decision(d.id,'run') THEN
      RAISE EXCEPTION 'Current reconciliation run access required' USING ERRCODE='42501';
    END IF;
  END IF;
  -- Retain the selected caller's production-approved administrator admission.
  IF d.governance_state='approved_locked' AND d.environment='production'
     AND NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant
       AND user_id=actor AND active=true AND role='tenant_admin'::public.tenant_role) THEN
    RAISE EXCEPTION 'Active production administrator required' USING ERRCODE='42501';
  END IF;
  -- Delegate current approval integrity, configuration hash and independent
  -- runner checks to the exact existing authoritative helper, without new grants.
  v:=private.recon_run_bound_approved_version(_tenant,d.id,actor);
  IF r.approved_revision_id IS DISTINCT FROM v.id
     OR r.approved_revision_number IS DISTINCT FROM v.version_number
     OR r.approved_revision_sha256 IS DISTINCT FROM v.snapshot_sha256 THEN
    RAISE EXCEPTION 'Approved reconciliation binding changed' USING ERRCODE='PT409';
  END IF;
  IF v.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.recon_definition_run_version_snapshots s
      WHERE s.recon_run_id=r.id AND s.tenant_id=_tenant AND s.recon_definition_id=d.id
        AND s.approved_version_number=v.version_number AND s.approved_snapshot_sha256=v.snapshot_sha256
        AND s.approved_request_id=v.request_id AND s.approved_by=v.approved_by) THEN
    RAISE EXCEPTION 'Approved run audit binding differs from current approval' USING ERRCODE='23514';
  END IF;
END $function$

CREATE OR REPLACE FUNCTION public.complete_recon_run_atomic(_tenant_id uuid, _run_id uuid, _commit_id uuid, _expected_definition_snapshot jsonb, _expected_approved_revision_id uuid, _expected_approved_revision_number integer, _expected_approved_revision_sha256 text, _matches jsonb, _exceptions jsonb, _stats jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE r public.recon_runs%ROWTYPE; d public.recon_definitions%ROWTYPE;
  actor uuid:=auth.uid(); definition uuid; marker jsonb; digest text;
  matches integer; exceptions integer; total integer; matched_records bigint;
  actual_matched_records bigint:=0; m jsonb; member jsonb; member_row jsonb;
  expected_sides text[]; member_sides text[]; audit_id bigint; nid uuid; changed integer;
BEGIN
  IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
     OR _tenant_id IS NULL OR _run_id IS NULL OR _commit_id IS NULL THEN
    RAISE EXCEPTION 'Authenticated owned reconciliation commit required' USING ERRCODE='42501';
  END IF;
  IF _matches IS NULL OR jsonb_typeof(_matches)<>'array'
     OR _exceptions IS NULL OR jsonb_typeof(_exceptions)<>'array'
     OR _stats IS NULL OR jsonb_typeof(_stats)<>'object' OR _stats ? '_atomic_completion'
     OR _expected_definition_snapshot IS NULL OR jsonb_typeof(_expected_definition_snapshot)<>'object'
     OR jsonb_typeof(_stats->'total_rows') IS DISTINCT FROM 'number'
     OR jsonb_typeof(_stats->'matched_records') IS DISTINCT FROM 'number'
     OR jsonb_typeof(_stats->'exception_count') IS DISTINCT FROM 'number'
     OR (_stats->>'total_rows') !~ '^[0-9]+$'
     OR (_stats->>'matched_records') !~ '^[0-9]+$'
     OR (_stats->>'exception_count') !~ '^[0-9]+$' THEN
    RAISE EXCEPTION 'Complete reconciliation result arrays and counts required' USING ERRCODE='22023';
  END IF;
  matches:=jsonb_array_length(_matches);exceptions:=jsonb_array_length(_exceptions);
  total:=(_stats->>'total_rows')::integer;matched_records:=(_stats->>'matched_records')::bigint;
  IF (_stats->>'exception_count')::bigint<>exceptions OR matched_records>total THEN
    RAISE EXCEPTION 'Reconciliation result totals disagree' USING ERRCODE='22023';
  END IF;
  -- Read under current invoker RLS, then use definition-before-run lock order.
  SELECT definition_id INTO definition FROM public.recon_runs
    WHERE id=_run_id AND tenant_id=_tenant_id AND run_by=actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'Owned visible run required' USING ERRCODE='42501'; END IF;
  SELECT * INTO d FROM public.recon_definitions WHERE id=definition AND tenant_id=_tenant_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Visible reconciliation configuration required' USING ERRCODE='42501'; END IF;
  SELECT * INTO r FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND run_by=actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Current run update access required' USING ERRCODE='42501'; END IF;
  PERFORM private.recon_atomic_admit(_tenant_id,_run_id);
  IF r.definition_id IS DISTINCT FROM definition
     OR r.definition_snapshot IS DISTINCT FROM _expected_definition_snapshot
     OR r.approved_revision_id IS DISTINCT FROM _expected_approved_revision_id
     OR r.approved_revision_number IS DISTINCT FROM _expected_approved_revision_number
     OR r.approved_revision_sha256 IS DISTINCT FROM _expected_approved_revision_sha256
     OR d.recon_type IS DISTINCT FROM r.definition_snapshot->>'recon_type'
     OR d.sides IS DISTINCT FROM r.definition_snapshot->'sides'
     OR d.rules IS DISTINCT FROM r.definition_snapshot->'rules' THEN
    RAISE EXCEPTION 'Immutable execution configuration changed' USING ERRCODE='PT409';
  END IF;
  digest:=encode(sha256(convert_to(jsonb_build_object('tenant',_tenant_id,'run',_run_id,
    'snapshot',_expected_definition_snapshot,'revision_id',_expected_approved_revision_id,
    'revision_number',_expected_approved_revision_number,'revision_sha256',_expected_approved_revision_sha256,
    'matches',_matches,'exceptions',_exceptions,'stats',_stats)::text,'UTF8')),'hex');
  marker:=r.stats->'_atomic_completion';
  IF r.status='completed' THEN
    IF marker->>'commit_id' IS DISTINCT FROM _commit_id::text OR marker->>'result_sha256' IS DISTINCT FROM digest
       OR marker->>'audit_id' IS NULL OR marker->>'notification_id' IS NULL
       OR r.matched_count<>matches OR r.exception_count<>exceptions OR r.total_rows<>total THEN
      RAISE EXCEPTION 'Completed reconciliation commit conflicts' USING ERRCODE='PT409';
    END IF;
    RETURN marker||jsonb_build_object('status','completed','run_id',r.id,'tenant_id',r.tenant_id,
      'definition_id',r.definition_id,'matched_count',r.matched_count,'exception_count',r.exception_count,'total_rows',r.total_rows);
  END IF;
  IF r.status<>'running' OR EXISTS(SELECT 1 FROM public.recon_matches WHERE run_id=r.id)
     OR EXISTS(SELECT 1 FROM public.recon_exceptions WHERE run_id=r.id)
     OR EXISTS(SELECT 1 FROM public.recon_definition_run_version_snapshots s
       WHERE s.recon_run_id=r.id AND (s.tenant_id<>r.tenant_id OR s.recon_definition_id<>r.definition_id)) THEN
    RAISE EXCEPTION 'Run is not a clean current atomic execution' USING ERRCODE='PT409';
  END IF;
  IF r.approved_revision_id IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM public.recon_definition_run_version_snapshots s WHERE s.recon_run_id=r.id
        AND s.tenant_id=r.tenant_id AND s.recon_definition_id=r.definition_id
        AND s.approved_version_number=r.approved_revision_number
        AND s.approved_snapshot_sha256=r.approved_revision_sha256) THEN
    RAISE EXCEPTION 'Immutable run approval audit binding unavailable' USING ERRCODE='23514';
  END IF;
  SELECT array_agg(s->>'side_id' ORDER BY s->>'side_id') INTO expected_sides
    FROM jsonb_array_elements(r.definition_snapshot->'sides') s;
  IF expected_sides IS NULL OR cardinality(expected_sides) NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'Configured reconciliation sides unavailable' USING ERRCODE='23514';
  END IF;
  -- Source visibility is re-evaluated under current RLS at commit time.
  FOR m IN SELECT value FROM jsonb_array_elements(r.definition_snapshot->'sides') LOOP
    PERFORM 1 FROM public.workspace_data_sources WHERE id=(m->>'data_source_id')::uuid AND tenant_id=_tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Current source access required' USING ERRCODE='42501'; END IF;
  END LOOP;
  FOR m IN SELECT value FROM jsonb_array_elements(_matches) LOOP
    IF jsonb_typeof(m)<>'object' OR jsonb_typeof(m->'members') IS DISTINCT FROM 'object'
       OR jsonb_typeof(m->'cardinality') IS DISTINCT FROM 'string'
       OR (m ? 'score' AND jsonb_typeof(m->'score') NOT IN ('number','null')) THEN
      RAISE EXCEPTION 'Invalid match record shape' USING ERRCODE='22023';
    END IF;
    SELECT array_agg(key ORDER BY key) INTO member_sides FROM jsonb_object_keys(m->'members') key;
    IF member_sides IS DISTINCT FROM expected_sides THEN
      RAISE EXCEPTION 'Match members differ from configured sides' USING ERRCODE='22023';
    END IF;
    FOR member IN SELECT value FROM jsonb_each(m->'members') LOOP
      IF jsonb_typeof(member)<>'array' OR jsonb_array_length(member)=0 THEN
        RAISE EXCEPTION 'Every matched side must retain members' USING ERRCODE='22023';
      END IF;
      actual_matched_records:=actual_matched_records+jsonb_array_length(member);
      FOR member_row IN SELECT value FROM jsonb_array_elements(member) LOOP
        IF jsonb_typeof(member_row)<>'object' THEN
          RAISE EXCEPTION 'Invalid matched group member' USING ERRCODE='22023';
        END IF;
      END LOOP;
    END LOOP;
  END LOOP;
  IF actual_matched_records<>matched_records THEN
    RAISE EXCEPTION 'Matched member accounting disagrees' USING ERRCODE='22023';
  END IF;
  FOR m IN SELECT value FROM jsonb_array_elements(_exceptions) LOOP
    IF jsonb_typeof(m)<>'object' OR jsonb_typeof(m->'payload') IS DISTINCT FROM 'object'
       OR jsonb_typeof(m->'reason') IS DISTINCT FROM 'string'
       OR jsonb_typeof(m->'severity') IS DISTINCT FROM 'string' THEN
      RAISE EXCEPTION 'Invalid exception record shape' USING ERRCODE='22023';
    END IF;
  END LOOP;
  -- These invoker writes, RLS/constraint/trigger checks and audit are ONE statement
  -- transaction. No exception handler swallows failures or leaves partial rows.
  INSERT INTO public.recon_matches(run_id,tenant_id,rule_id,cardinality,members,score)
    SELECT r.id,_tenant_id,m.rule_id,m.cardinality,m.members,m.score
    FROM jsonb_to_recordset(_matches) AS m(rule_id text,cardinality text,members jsonb,score numeric);
  INSERT INTO public.recon_exceptions(run_id,tenant_id,side,reason,severity,status,payload)
    SELECT r.id,_tenant_id,e.side,e.reason,e.severity,'open',e.payload
    FROM jsonb_to_recordset(_exceptions) AS e(side text,reason text,severity text,payload jsonb);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(actor,_tenant_id,'workspace','recon.run.complete','recon_run',r.id::text,
      jsonb_build_object('definition_id',r.definition_id,'name',r.definition_snapshot->>'name','commit_id',_commit_id,'result_sha256',digest,
        'matched',matches,'exceptions',exceptions,'total_rows',total,
        'approved_revision_id',r.approved_revision_id,'approved_revision_number',r.approved_revision_number,
        'approved_revision_sha256',r.approved_revision_sha256,'reference_versions',_stats->'reference_versions'))
    RETURNING id INTO audit_id;
  marker:=jsonb_build_object('commit_id',_commit_id,'result_sha256',digest,'audit_id',audit_id::text,
    'status','completed','run_id',r.id,'tenant_id',_tenant_id,'definition_id',r.definition_id,
    'matched_count',matches,'exception_count',exceptions,'total_rows',total);
  UPDATE public.recon_runs SET status='completed',matched_count=matches,exception_count=exceptions,
    total_rows=total,stats=_stats||jsonb_build_object('_atomic_completion',marker),completed_at=clock_timestamp(),error=NULL
    WHERE id=r.id AND tenant_id=_tenant_id AND run_by=actor AND status='running';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'Run completion update not permitted' USING ERRCODE='42501'; END IF;
  nid:=private.recon_atomic_self_notification(_tenant_id,r.id,_commit_id);
  marker:=marker||jsonb_build_object('notification_id',nid);
  UPDATE public.recon_runs SET stats=_stats||jsonb_build_object('_atomic_completion',marker)
    WHERE id=r.id AND tenant_id=_tenant_id AND run_by=actor AND status='completed';
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'Commit receipt update not permitted' USING ERRCODE='42501'; END IF;
  RETURN marker;
END $function$

CREATE OR REPLACE FUNCTION public.decide_recon_definition_edit(_request_id uuid, _approve boolean, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE actor uuid; q public.recon_definition_governance_requests%ROWTYPE; parent public.recon_definitions%ROWTYPE;
 stage_id uuid; stage_name text; suffix text; mapping jsonb; version_now integer; hash_now text;
BEGIN
 IF _request_id IS NULL OR _approve IS NULL OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'invalid governance decision' USING ERRCODE='22023'; END IF;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=_request_id AND request_kind='edit';
 IF NOT FOUND THEN PERFORM private.mapped_recon_governance_conflict('request_missing_or_replayed'); END IF;
 -- Registered availability at the actual native tenant scope; original mapped authority/independent checker/audit program follows unchanged.
 PERFORM private.wfm_actor(q.tenant_id);
 PERFORM private.wfm_assert_enabled(q.tenant_id,'recons');

 PERFORM pg_advisory_xact_lock(hashtextextended('mapped-recon:'||q.tenant_id::text||':'||q.parent_definition_id::text,0));
 PERFORM private.mapped_recon_governance_lock_scope(q.tenant_id,q.parent_definition_id);
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=_request_id FOR UPDATE;
 SELECT * INTO parent FROM public.recon_definitions WHERE id=q.parent_definition_id AND tenant_id=q.tenant_id;
 actor:=private.mapped_recon_governance_actor(q.tenant_id,parent.id,'approve',true);
 IF actor=q.requested_by THEN PERFORM private.mapped_recon_governance_conflict('independent_checker_required'); END IF;
 IF q.status<>'pending' OR q.mapped_governance_version IS DISTINCT FROM 1 OR parent.governance_state<>'edit_request_pending'
 OR parent.environment<>'production' OR parent.status<>'active' OR parent.retired_at IS NOT NULL
 OR EXISTS(SELECT 1 FROM public.recon_retirement_requests WHERE tenant_id=q.tenant_id AND recon_id=parent.id AND status='pending') THEN PERFORM private.mapped_recon_governance_conflict('request_stale_or_replayed'); END IF;
 PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,parent.id,q.requested_by);
 mapping:=private.mapped_recon_governance_mapping(q.tenant_id,parent.id);
 SELECT version_number,snapshot_sha256 INTO version_now,hash_now FROM public.recon_definition_approved_versions WHERE tenant_id=q.tenant_id AND parent_definition_id=parent.id ORDER BY version_number DESC LIMIT 1;
 IF version_now IS DISTINCT FROM q.source_version OR hash_now IS DISTINCT FROM q.source_sha256
 OR private.mapped_recon_governance_hash(mapping) IS DISTINCT FROM q.parent_mapping_fingerprint
 OR mapping IS DISTINCT FROM q.parent_mapping_snapshot
 OR private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(parent)) IS DISTINCT FROM q.parent_config_fingerprint THEN PERFORM private.mapped_recon_governance_conflict('frozen_parent_changed'); END IF;
 INSERT INTO private.mapped_recon_governance_transitions(request_id,actor_id,purpose) VALUES(q.id,actor,'edit_decision');
 UPDATE public.recon_definition_governance_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,decision_reason=btrim(_reason),decided_by=actor,decided_at=clock_timestamp() WHERE id=q.id;
 PERFORM set_config('fvi.recon_governance_request_id',q.id::text,true);
 IF _approve THEN
  stage_id:=gen_random_uuid();suffix:=' [staging '||substr(stage_id::text,1,8)||']';stage_name:=left(parent.name,80-length(suffix))||suffix;
  INSERT INTO public.recon_definitions(id,tenant_id,name,description,recon_type,sides,rules,extension,status,environment,created_by,governance_state,access_mode,multi_bu_governed,bu_id,visibility,governance_parent_id,staging_original_name,staging_generated_name,starter_template_id,starter_template_code,starter_template_snapshot,tenant_template_id)
  VALUES(stage_id,parent.tenant_id,stage_name,parent.description,parent.recon_type,parent.sides,parent.rules,parent.extension,'draft','staging',q.requested_by,'staging_copy','mapped_exact',parent.multi_bu_governed,parent.bu_id,parent.visibility,parent.id,parent.name,stage_name,parent.starter_template_id,parent.starter_template_code,parent.starter_template_snapshot,parent.tenant_template_id);
  INSERT INTO public.recon_definition_business_units(tenant_id,recon_id,bu_id,created_by) SELECT tenant_id,stage_id,bu_id,actor FROM public.recon_definition_business_units WHERE tenant_id=q.tenant_id AND recon_id=parent.id;
  INSERT INTO public.recon_definition_bu_grants(tenant_id,recon_id,bu_id,principal_type,principal_id,action,granted_by) SELECT tenant_id,stage_id,bu_id,principal_type,principal_id,action,actor FROM public.recon_definition_bu_grants WHERE tenant_id=q.tenant_id AND recon_id=parent.id;
  PERFORM private.mapped_recon_governance_mapping(q.tenant_id,stage_id);
  IF private.mapped_recon_governance_scope_shape(q.tenant_id,stage_id) IS DISTINCT FROM private.mapped_recon_governance_scope_shape(q.tenant_id,parent.id) THEN
   PERFORM private.mapped_recon_governance_conflict('copied_scope_mismatch');
  END IF;
  IF NOT private.recon_authoritative_access_decision_as(q.requested_by,stage_id,'edit') THEN PERFORM private.mapped_recon_governance_conflict('copied_requester_edit_scope_required'); END IF;
  UPDATE public.recon_definition_governance_requests SET staging_definition_id=stage_id WHERE id=q.id;
 END IF;
 UPDATE public.recon_definitions SET governance_state='approved_locked' WHERE id=parent.id;
 INSERT INTO public.recon_definition_governance_audit(tenant_id,request_id,parent_definition_id,staging_definition_id,event_type,actor_id,reason,snapshot_sha256) VALUES(q.tenant_id,q.id,parent.id,stage_id,CASE WHEN _approve THEN 'edit_approved' ELSE 'edit_rejected' END,actor,btrim(_reason),q.source_sha256);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,q.tenant_id,'workspace',CASE WHEN _approve THEN 'recon.definition.edit_approved' ELSE 'recon.definition.edit_rejected' END,'recon_definition_governance_request',q.id::text,jsonb_build_object('parent_definition_id',parent.id,'staging_definition_id',stage_id,'mapping_fingerprint',q.parent_mapping_fingerprint));
 RETURN stage_id;
END $function$

CREATE OR REPLACE FUNCTION public.create_tenant_with_email_domain(_family_id uuid, _slug text, _name text, _environment env_tier, _ai_enabled boolean, _email_domain text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid := auth.uid(); v_tenant uuid; v_domain text := lower(trim(_email_domain));
BEGIN
  IF v_actor IS NULL OR NOT public.is_platform_admin(v_actor) THEN
    RAISE EXCEPTION 'Not authorized' USING ERRCODE = '42501';
  END IF;
  IF v_domain IS NULL OR v_domain !~ '^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?(?:\.[a-z0-9](?:[a-z0-9-]*[a-z0-9])?)+$'
     OR length(v_domain) > 253 THEN
    RAISE EXCEPTION 'Invalid email domain' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.tenants(family_id,slug,name,environment,ai_enabled,created_by)
  VALUES (_family_id,_slug,_name,_environment,_ai_enabled,v_actor) RETURNING id INTO v_tenant;
  INSERT INTO public.tenant_email_domains(tenant_id,domain,created_by)
  VALUES (v_tenant,v_domain,v_actor);
  INSERT INTO public.tenant_members(tenant_id,user_id,role,invited_by)
  VALUES (v_tenant,v_actor,'tenant_admin'::public.tenant_role,v_actor)
  ON CONFLICT (tenant_id,user_id) DO NOTHING;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=v_tenant
                 AND m.user_id=v_actor AND m.active AND m.role='tenant_admin'::public.tenant_role) THEN
    RAISE EXCEPTION 'Tenant administrator setup failed' USING ERRCODE='23514';
  END IF;
  RETURN v_tenant;
END $function$

CREATE OR REPLACE FUNCTION private.recon_atomic_self_notification(_tenant uuid, _run uuid, _commit uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE r public.recon_runs%ROWTYPE; marker jsonb; nid uuid; actor uuid:=auth.uid();
BEGIN
  IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' THEN
    RAISE EXCEPTION 'Authenticated notification actor required' USING ERRCODE='42501';
  END IF;
  PERFORM private.recon_atomic_admit(_tenant,_run);
  SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND run_by=actor;
  marker:=r.stats->'_atomic_completion';
  IF NOT FOUND OR r.status<>'completed' OR marker->>'commit_id' IS DISTINCT FROM _commit::text
     OR NOT EXISTS(SELECT 1 FROM public.audit_log WHERE id=(marker->>'audit_id')::bigint
        AND actor_user_id=actor AND tenant_id=_tenant AND scope='workspace'
        AND action='recon.run.complete' AND resource_type='recon_run'
        AND resource_id=_run::text AND context->>'commit_id'=_commit::text) THEN
    RAISE EXCEPTION 'Committed owned run audit required for self notification' USING ERRCODE='42501';
  END IF;
  IF marker->>'notification_id' IS NOT NULL THEN
    SELECT id INTO nid FROM public.notifications WHERE id=(marker->>'notification_id')::uuid
      AND user_id=actor AND tenant_id=_tenant AND context->>'commit_id'=_commit::text;
    IF NOT FOUND THEN RAISE EXCEPTION 'Notification receipt unavailable' USING ERRCODE='PT409'; END IF;
    RETURN nid;
  END IF;
  -- A caller cannot select another recipient, tenant, title or arbitrary payload.
  -- This narrow writer replaces the old broad service-role client, not a policy.
  INSERT INTO public.notifications(user_id,tenant_id,kind,severity,title,body,context)
  VALUES(actor,_tenant,'recon.completed',CASE WHEN r.exception_count>0 THEN 'warning' ELSE 'success' END,
    left(COALESCE(r.definition_snapshot->>'name','Reconciliation')||' — '||r.matched_count::text
      ||' matched, '||r.exception_count::text||' exceptions',512),
    r.total_rows::text||' rows processed',jsonb_build_object('recon_run_id',_run,'commit_id',_commit))
  RETURNING id INTO nid;
  RETURN nid;
END $function$

CREATE OR REPLACE FUNCTION public.copilot_broker_reserved_secret(_verified_actor uuid, _verified_aal text, _verified_expires_at timestamp with time zone, _tenant_id uuid, _scope copilot_scope, _thread_id uuid, _request_ip text, _reservation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE policy jsonb; r public.copilot_spend_reservations%ROWTYPE; l public.llm_providers%ROWTYPE;
 c public.ai_model_catalog%ROWTYPE; i public.ai_provider_instances%ROWTYPE; pr public.ai_model_pricing%ROWTYPE;
 v public.app_vault_secrets%ROWTYPE; leased text;
BEGIN
 IF _reservation_id IS NULL OR _thread_id IS NULL THEN RAISE EXCEPTION 'copilot.reservation_required'; END IF;
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role'
   THEN RAISE EXCEPTION 'copilot.verified_subject_required'; END IF;
 PERFORM pg_advisory_xact_lock(61000,1);
 SELECT * INTO r FROM public.copilot_spend_reservations WHERE id=_reservation_id::text FOR UPDATE;
 IF NOT FOUND OR r.actor_id IS DISTINCT FROM _verified_actor OR r.tenant_id IS DISTINCT FROM _tenant_id
   OR r.state IS DISTINCT FROM 'dispatched' OR r.llm_provider_id IS NULL OR r.catalog_id IS NULL OR r.price_id IS NULL
   OR r.created_at IS NULL OR r.created_at<clock_timestamp()-interval '5 minutes'
   THEN RAISE EXCEPTION 'copilot.reservation_denied'; END IF;
 policy:=private.copilot_broker_authorize(_verified_actor,_verified_aal,_verified_expires_at,_tenant_id,_scope,_thread_id,_request_ip);
 SELECT * INTO l FROM public.llm_providers WHERE id=r.llm_provider_id;
 IF NOT FOUND OR l.is_active IS DISTINCT FROM true OR l.tenant_id IS DISTINCT FROM _tenant_id
   OR l.model_catalog_id IS DISTINCT FROM r.catalog_id OR l.model IS DISTINCT FROM r.model_key
   OR l.scope::text IS DISTINCT FROM (CASE WHEN _tenant_id IS NULL THEN 'platform' ELSE 'tenant' END)
   THEN RAISE EXCEPTION 'copilot.binding_changed'; END IF;
 SELECT * INTO c FROM public.ai_model_catalog WHERE id=r.catalog_id;
 IF NOT FOUND OR c.model_key IS DISTINCT FROM r.model_key OR c.provider_instance_id IS DISTINCT FROM l.provider_instance_id
   OR c.approval_status IS DISTINCT FROM 'approved' OR c.availability_status NOT IN ('available','limited') OR c.availability_status IS NULL
   OR least(c.max_input_tokens,c.context_window-c.max_output_tokens) IS DISTINCT FROM r.max_input_tokens
   OR c.max_output_tokens IS DISTINCT FROM r.max_output_tokens THEN RAISE EXCEPTION 'copilot.binding_changed'; END IF;
 SELECT * INTO i FROM public.ai_provider_instances WHERE id=l.provider_instance_id;
 IF NOT FOUND OR i.status IS DISTINCT FROM 'active' OR i.tenant_id IS DISTINCT FROM _tenant_id OR i.vault_secret_id IS NULL
   OR NOT EXISTS(SELECT 1 FROM public.ai_provider_registry reg WHERE reg.code=i.provider_code AND reg.enabled)
   THEN RAISE EXCEPTION 'copilot.binding_changed'; END IF;
 IF jsonb_array_length(policy->'allowed_models')>0 AND NOT ((policy->'allowed_models') ? c.model_key OR (policy->'allowed_models') ? (i.provider_code||'/'||c.model_key))
   THEN RAISE EXCEPTION 'copilot.model_policy_denied'; END IF;
 SELECT * INTO pr FROM public.ai_model_pricing WHERE id=r.price_id;
 IF NOT FOUND OR pr.active IS DISTINCT FROM true OR pr.currency IS DISTINCT FROM 'USD'
   OR pr.provider_code IS DISTINCT FROM i.provider_code OR pr.model_key IS DISTINCT FROM r.model_key
   OR pr.effective_at IS NULL OR pr.effective_at>clock_timestamp() OR (pr.expires_at IS NOT NULL AND pr.expires_at<=clock_timestamp())
   OR pr.input_usd_per_1m IS DISTINCT FROM r.input_rate OR pr.output_usd_per_1m IS DISTINCT FROM r.output_rate
   OR pr.input_usd_per_1m IS NULL OR pr.output_usd_per_1m IS NULL OR pr.input_usd_per_1m<=0 OR pr.output_usd_per_1m<=0
   OR pr.input_usd_per_1m::text IN ('NaN','Infinity','-Infinity') OR pr.output_usd_per_1m::text IN ('NaN','Infinity','-Infinity')
   THEN RAISE EXCEPTION 'copilot.pricing_unavailable'; END IF;
 SELECT * INTO v FROM public.app_vault_secrets WHERE id=i.vault_secret_id;
 IF NOT FOUND OR v.tenant_id IS DISTINCT FROM _tenant_id OR v.scope IS DISTINCT FROM (CASE WHEN _tenant_id IS NULL THEN 'platform' ELSE 'tenant' END)
   OR v.secret_class::text IS DISTINCT FROM 'llm_api_key' OR v.name IS DISTINCT FROM upper(coalesce(nullif(l.key_secret_name,''),l.provider::text))
   OR v.ciphertext IS NULL OR v.iv IS NULL OR v.auth_tag IS NULL OR v.wrapped_dek IS NULL OR v.kek_ref IS NULL
   THEN RAISE EXCEPTION 'copilot.vault_binding_unavailable'; END IF;
 INSERT INTO private.copilot_broker_dispatch_receipts(reservation_id,actor_id,tenant_id,thread_id,provider_id,catalog_id,price_id,caller_kind,verified_aal,purpose)
 VALUES(r.id,r.actor_id,r.tenant_id,_thread_id,l.id,c.id,pr.id,'service_role',_verified_aal,'copilot_reserved_dispatch')
 ON CONFLICT(reservation_id) DO NOTHING RETURNING reservation_id INTO leased;
 IF leased IS NULL THEN RAISE EXCEPTION 'copilot.already_dispatched'; END IF;
 RETURN jsonb_build_object('reservation_id',_reservation_id,'actor_id',r.actor_id,'tenant_id',r.tenant_id,'thread_id',_thread_id,
   'provider_id',l.id,'model_catalog_id',c.id,'model_key',c.model_key,'provider',l.provider::text,'base_url',l.base_url,
   'key_secret_name',upper(coalesce(nullif(l.key_secret_name,''),l.provider::text)),
   'auth_method',i.auth_method,'api_version',i.api_version,'custom_headers',coalesce(i.custom_headers,'{}'::jsonb),
   'write_proposals',(policy->>'write_proposals')::boolean,
   'vault',jsonb_build_object('ciphertext',v.ciphertext,'iv',v.iv,'auth_tag',v.auth_tag,'wrapped_dek',v.wrapped_dek,'kek_provider',v.kek_provider,'kek_ref',v.kek_ref));
END $function$

CREATE OR REPLACE FUNCTION private.recon_child_read_allowed(_run_id uuid, _child_tenant_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_run public.recon_runs%ROWTYPE;
  v_definition public.recon_definitions%ROWTYPE;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL OR _run_id IS NULL OR _child_tenant_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT run_row.* INTO v_run
  FROM public.recon_runs run_row
  WHERE run_row.id = _run_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  SELECT definition_row.* INTO v_definition
  FROM public.recon_definitions definition_row
  WHERE definition_row.id = v_run.definition_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;

  -- Reject malformed cross-tenant ancestry for every access mode. The former
  -- child predicates trusted only the denormalized child tenant_id; preserving
  -- that behavior for legacy rows would let a child borrow another tenant's
  -- membership/platform-admin visibility through a mismatched run/root link.
  IF v_run.tenant_id IS DISTINCT FROM _child_tenant_id
     OR v_run.tenant_id IS DISTINCT FROM v_definition.tenant_id THEN
    RETURN false;
  END IF;

  -- Preserve tenant-wide legacy visibility for active members only. The
  -- platform-admin legacy branch remains separate; mapped roots use the
  -- authoritative actor-bound decision below.
  IF v_definition.access_mode = 'legacy_passthrough' THEN
    RETURN EXISTS (
      SELECT 1 FROM public.tenant_members member_row
      WHERE member_row.user_id = v_actor
        AND member_row.tenant_id = _child_tenant_id
        AND member_row.active
    )
      OR private.is_platform_admin(v_actor);
  END IF;

  -- A governed child must agree with both its run and root tenant, then pass
  -- the current root decision. Never trust a denormalized child tenant alone.
  RETURN private.recon_authoritative_access_decision(v_definition.id, 'read');
END
$function$

CREATE OR REPLACE FUNCTION public.copilot_check_current_ip_access(_tenant_id uuid, _ip text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE
  actor uuid := auth.uid();
  enabled boolean;
BEGIN
  IF auth.role() IS DISTINCT FROM 'authenticated'
    OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
    OR actor IS NULL OR _tenant_id IS NULL THEN RETURN false; END IF;
  IF private.rlnext_account_allowed(actor,NULL) IS DISTINCT FROM true
    OR private.rlnext_account_allowed(actor,_tenant_id) IS DISTINCT FROM true
    THEN RAISE EXCEPTION 'copilot.account_denied' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_members tm
    WHERE tm.tenant_id=_tenant_id AND tm.user_id=actor AND tm.active)
    THEN RETURN false; END IF;
  SELECT s.ip_allowlist_enabled INTO enabled
    FROM public.tenant_security_settings s WHERE s.tenant_id=_tenant_id;
  IF NOT FOUND OR enabled IS NULL THEN RETURN false; END IF;
  IF enabled=false THEN RETURN true; END IF;
  IF _ip IS NULL OR btrim(_ip)='' THEN RETURN false; END IF;
  RETURN coalesce(public.ip_in_tenant_allowlist(_tenant_id,_ip),false);
END
$function$

CREATE OR REPLACE FUNCTION public.request_tenant_admission()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_actor uuid := auth.uid(); v_email text; v_name text; v_tenant uuid; v_request uuid;
BEGIN
 IF auth.uid() IS NOT NULL AND NOT public.is_platform_admin(auth.uid()) AND NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE user_id=auth.uid()) AND (auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' OR NOT private.rlnext_has_verified_mfa(auth.uid())) THEN RAISE EXCEPTION 'Verify Supabase MFA before requesting approval' USING ERRCODE='42501'; END IF;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF;
  SELECT lower(u.email), left(coalesce(u.raw_user_meta_data->>'full_name',''),120)
    INTO v_email,v_name FROM auth.users u
    WHERE u.id=v_actor AND u.confirmed_at IS NOT NULL;
  IF v_email IS NULL OR v_email !~ '^[^@]+@[^@]+$' THEN RETURN true; END IF;
  SELECT d.tenant_id INTO v_tenant FROM public.tenant_email_domains d
    WHERE d.domain=split_part(v_email,'@',2) AND d.status='verified';
  IF v_tenant IS NULL THEN RETURN true; END IF;
  IF EXISTS (SELECT 1 FROM public.tenant_members m WHERE m.user_id=v_actor) THEN RETURN true; END IF;
  INSERT INTO public.tenant_signup_requests(tenant_id,user_id,email,full_name)
  VALUES (v_tenant,v_actor,v_email,nullif(v_name,''))
  ON CONFLICT (user_id) DO NOTHING RETURNING id INTO v_request;
  IF v_request IS NOT NULL THEN
    INSERT INTO public.tenant_signup_events(request_id,tenant_id,user_id,event_name)
    VALUES (v_request,v_tenant,v_actor,'signup.admission_requested');
    -- Applicant has no tenant membership yet, so audit attribution is user scope.
    INSERT INTO public.audit_log(actor_user_id,scope,action,resource_type,resource_id,context)
    VALUES (v_actor,'user','signup.admission_requested','tenant_signup_request',v_request::text,'{}'::jsonb);
  END IF;
  RETURN true;
END $function$

CREATE OR REPLACE FUNCTION private.recon_root_write_allowed(_definition_id uuid, _tenant_id uuid, _action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_definition public.recon_definitions%ROWTYPE;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL OR _definition_id IS NULL OR _tenant_id IS NULL OR _action IS NULL
     OR _action NOT IN ('run','edit') THEN
    RETURN false;
  END IF;

  SELECT d.* INTO v_definition
  FROM public.recon_definitions d
  WHERE d.id = _definition_id;
  IF NOT FOUND OR v_definition.tenant_id IS DISTINCT FROM _tenant_id THEN
    RETURN false;
  END IF;

  -- Legacy write policy was tenant_admin/tenant_analyst. Keep that behavior
  -- for valid legacy ancestry; platform-only read visibility is not write.
  IF v_definition.access_mode = 'legacy_passthrough' THEN
    RETURN private.has_tenant_role(v_actor, _tenant_id, 'tenant_admin'::tenant_role)
      OR private.has_tenant_role(v_actor, _tenant_id, 'tenant_analyst'::tenant_role);
  END IF;

  -- A mutation must be usable through the row's SELECT policy too. `run`
  -- inserts need read for RETURNING; `edit` changes need read to locate and
  -- operate on the existing row. Missing either capability fails closed.
  RETURN private.recon_authoritative_access_decision(v_definition.id, _action)
     AND private.recon_authoritative_access_decision(v_definition.id, 'read');
END
$function$

CREATE OR REPLACE FUNCTION private.recon_run_read_allowed(_definition_id uuid, _run_tenant_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_definition public.recon_definitions%ROWTYPE;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL OR _definition_id IS NULL OR _run_tenant_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT d.* INTO v_definition
  FROM public.recon_definitions d
  WHERE d.id = _definition_id;
  IF NOT FOUND OR v_definition.tenant_id IS DISTINCT FROM _run_tenant_id THEN
    RETURN false;
  END IF;

  IF v_definition.access_mode = 'legacy_passthrough' THEN
    RETURN private.is_tenant_member(v_actor, _run_tenant_id)
      OR private.is_platform_admin(v_actor);
  END IF;

  RETURN private.recon_authoritative_access_decision(v_definition.id, 'read');
END
$function$

CREATE OR REPLACE FUNCTION public.fail_tenant_signup_event(_event_id uuid, _lease_token uuid, _error_code text, _retry_after_seconds integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_event public.tenant_signup_events; v_delay integer;
BEGIN
  IF _error_code IS NULL OR _error_code !~ '^[a-z0-9_]{1,80}$'
     OR (_retry_after_seconds IS NOT NULL AND _retry_after_seconds NOT BETWEEN 30 AND 86400) THEN
    RAISE EXCEPTION 'Invalid retry metadata' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_event FROM public.tenant_signup_events WHERE id=_event_id FOR UPDATE;
  IF NOT FOUND OR v_event.notified_at IS NOT NULL OR _lease_token IS NULL
     OR v_event.lease_until IS NULL OR v_event.lease_token IS DISTINCT FROM _lease_token
     OR v_event.lease_until <= now() THEN
    RETURN 'lease_lost';
  END IF;
  IF v_event.attempt_count >= 8 THEN
    UPDATE public.tenant_signup_events
      SET dead_lettered_at=now(),lease_token=NULL,lease_until=NULL,last_error_code=_error_code
      WHERE id=_event_id;
    RETURN 'dead_lettered';
  END IF;
  v_delay := coalesce(_retry_after_seconds, least(3600,(power(2,least(v_event.attempt_count,7))::integer)*30));
  UPDATE public.tenant_signup_events
    SET next_attempt_at=now()+make_interval(secs=>v_delay),
        lease_token=NULL,lease_until=NULL,last_error_code=_error_code
    WHERE id=_event_id;
  RETURN 'retry_scheduled';
END $function$

CREATE OR REPLACE FUNCTION public.guard_governed_member_auth_email_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_domain text := split_part(lower(coalesce(NEW.email,'')),'@',2);
BEGIN
  IF NEW.email IS NOT DISTINCT FROM OLD.email
     AND NEW.email_confirmed_at IS NOT DISTINCT FROM OLD.email_confirmed_at THEN RETURN NEW; END IF;
  IF public.is_platform_admin(NEW.id) THEN RETURN NEW; END IF;
  IF EXISTS (
    SELECT 1 FROM public.tenant_members m
    JOIN public.tenant_email_domains d ON d.tenant_id=m.tenant_id
    WHERE m.user_id=NEW.id
      AND (NEW.email_confirmed_at IS NULL OR d.status<>'verified' OR d.domain<>v_domain)
  ) THEN
    RAISE EXCEPTION 'Remove tenant membership before changing account email'
      USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.map_recon_definition_owners(_recon_id uuid, _owner_bu_ids uuid[], _reason text)
 RETURNS uuid[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_tenant uuid;
  v_existing uuid[];
  v_bu_ids uuid[];
BEGIN
  IF v_actor IS NULL OR _recon_id IS NULL OR _reason IS NULL
     OR length(btrim(_reason)) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'invalid reconciliation owner mapping request' USING ERRCODE='22023';
  END IF;
  SELECT definition_row.tenant_id INTO v_tenant
  FROM public.recon_definitions definition_row
  WHERE definition_row.id=_recon_id FOR UPDATE;
  IF v_tenant IS NULL OR NOT private.recon_governance_is_active_admin(v_tenant,v_actor) THEN
    RAISE EXCEPTION 'active tenant administrator required' USING ERRCODE='42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.recon_definitions definition_row
    WHERE definition_row.id=_recon_id AND definition_row.tenant_id=v_tenant
      AND definition_row.access_mode='unmapped_pending'
      AND definition_row.governance_state='development_draft'
      AND definition_row.environment='development'
      AND NOT definition_row.multi_bu_governed
  ) THEN
    RAISE EXCEPTION 'only an unmapped development draft can receive its first owner mapping' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM public.recon_definition_bu_grants WHERE tenant_id=v_tenant AND recon_id=_recon_id) THEN
    RAISE EXCEPTION 'revoke unreviewed grants before the first owner mapping' USING ERRCODE='23514';
  END IF;
  SELECT coalesce(array_agg(DISTINCT bu_id ORDER BY bu_id),ARRAY[]::uuid[])
  INTO v_bu_ids FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) AS bu_id;
  IF cardinality(v_bu_ids)=0 OR EXISTS (
    SELECT 1 FROM unnest(v_bu_ids) requested(bu_id)
    LEFT JOIN public.business_units bu ON bu.id=requested.bu_id AND bu.tenant_id=v_tenant
    WHERE bu.id IS NULL OR bu.is_archived
  ) THEN
    RAISE EXCEPTION 'at least one active same-tenant owning business unit is required' USING ERRCODE='22023';
  END IF;
  SELECT coalesce(array_agg(owner_row.bu_id ORDER BY owner_row.bu_id),ARRAY[]::uuid[])
  INTO v_existing FROM public.recon_definition_business_units owner_row
  WHERE owner_row.tenant_id=v_tenant AND owner_row.recon_id=_recon_id;
  IF cardinality(v_existing)>0 THEN
    RAISE EXCEPTION 'definition already has shadow owner rows; review them before mapping' USING ERRCODE='23514';
  END IF;
  INSERT INTO public.recon_definition_business_units(tenant_id,recon_id,bu_id,created_by)
  SELECT v_tenant,_recon_id,owner_id,v_actor FROM unnest(v_bu_ids) owner_id;
  INSERT INTO public.recon_definition_bu_admin_audit(
    tenant_id,recon_id,operation,actor_id,reason,details
  ) VALUES (
    v_tenant,_recon_id,'replace_owners',v_actor,btrim(_reason),
    jsonb_build_object('previous_bu_ids',v_existing,'new_bu_ids',v_bu_ids,'source','first_owner_mapping')
  );
  UPDATE public.recon_definitions
  SET access_mode='mapped_exact',multi_bu_governed=true
  WHERE id=_recon_id AND tenant_id=v_tenant;
  RETURN v_bu_ids;
END
$function$

CREATE OR REPLACE FUNCTION public.propose_tenant_directory_change(_tenant_id uuid, _patch jsonb, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); t public.tenants%ROWTYPE; v public.tenants%ROWTYPE;
 req uuid; before_state jsonb:='{}'; diff jsonb:='{}'; k text; n integer;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR actor IS NULL OR NOT public.is_platform_admin(actor) THEN
   RAISE EXCEPTION 'Tenant change not authorized' USING ERRCODE='42501';
 END IF;
 IF _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 8 AND 2000 THEN
   RAISE EXCEPTION 'Reason required' USING ERRCODE='23514';
 END IF;
 SELECT * INTO t FROM public.tenants WHERE id=_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Tenant unavailable' USING ERRCODE='42501'; END IF;
 v:=private.validate_tenant_directory_patch(t,_patch);
 FOR k IN SELECT jsonb_object_keys(_patch) LOOP
   before_state:=before_state||jsonb_build_object(k,to_jsonb(t)->k);
   diff:=diff||jsonb_build_object(k,jsonb_build_object('from',to_jsonb(t)->k,'to',to_jsonb(v)->k));
 END LOOP;
 IF before_state=_patch THEN RAISE EXCEPTION 'Tenant change is empty' USING ERRCODE='23514'; END IF;
 INSERT INTO public.config_change_requests(tenant_id,resource_type,resource_id,change_type,before_state,after_state,diff,status,requested_by,decision_reason)
 VALUES(t.id,'tenant_directory_change',t.id,'update',before_state,_patch,diff,'pending',actor,btrim(_reason)) RETURNING id INTO req;
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Tenant request unavailable' USING ERRCODE='23514'; END IF;
 INSERT INTO private.tenant_directory_change_bindings(request_id,tenant_id,proposer,base_version,before_state,patch)
 VALUES(req,t.id,actor,t.directory_version,before_state,_patch);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,t.id,'platform','tenant.change.proposed','tenant_directory_change',t.id::text,
   jsonb_build_object('request_id',req,'base_version',t.directory_version,'diff',diff,'reason',btrim(_reason)));
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Tenant audit unavailable' USING ERRCODE='23514'; END IF;
 RETURN jsonb_build_object('request_id',req,'status','pending');
END $function$

CREATE OR REPLACE FUNCTION public.instantiate_tenant_template_atomic(_tenant_id uuid, _tenant_template_id uuid, _name text)
 RETURNS TABLE(recon_definition_id uuid, recon_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE actor uuid:=auth.uid(); template_row public.tenant_templates%ROWTYPE; definition_row public.recon_definitions%ROWTYPE; source_count integer; leg_count integer;
BEGIN
  IF actor IS NULL OR NOT (
    public.is_platform_admin(actor) OR public.has_tenant_role(actor,_tenant_id,'tenant_admin') OR public.has_tenant_role(actor,_tenant_id,'tenant_analyst')
  ) THEN RAISE EXCEPTION 'analyst or admin role required' USING ERRCODE='42501'; END IF;
  SELECT * INTO template_row FROM public.tenant_templates WHERE id=_tenant_template_id AND tenant_id=_tenant_id AND status='published' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'published tenant template not found' USING ERRCODE='P0002'; END IF;
  IF template_row.spec->>'kind'<>'reconciliation' OR jsonb_typeof(template_row.spec->'sides')<>'array' OR jsonb_typeof(template_row.spec->'rules')<>'array' THEN
    RAISE EXCEPTION 'tenant template is not runnable' USING ERRCODE='22023';
  END IF;
  leg_count:=jsonb_array_length(template_row.spec->'sides');
  SELECT count(*) INTO source_count FROM jsonb_array_elements(template_row.spec->'sides') side
  JOIN public.workspace_data_sources source ON source.id=(side->>'data_source_id')::uuid AND source.tenant_id=_tenant_id;
  IF source_count<>leg_count OR leg_count NOT BETWEEN 1 AND 3 THEN RAISE EXCEPTION 'template sources are unavailable in tenant' USING ERRCODE='42501'; END IF;
  INSERT INTO public.recon_definitions(tenant_id,name,description,recon_type,sides,rules,status,created_by,tenant_template_id)
  VALUES (_tenant_id,btrim(_name),template_row.description,template_row.spec->>'recon_type',template_row.spec->'sides',template_row.spec->'rules','draft',actor,template_row.id)
  RETURNING * INTO definition_row;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (actor,_tenant_id,'workspace','recon.tenant_template.instantiate','recon_definition',definition_row.id,
    jsonb_build_object('recon_code',definition_row.recon_code,'tenant_template_id',template_row.id,'semver',template_row.current_semver));
  INSERT INTO public.mkt_audit_log(actor_id,tenant_id,entity_type,entity_id,action,after)
  VALUES (actor,_tenant_id,'tenant_template',template_row.id,'instantiate',jsonb_build_object('recon_definition_id',definition_row.id,'recon_code',definition_row.recon_code));
  RETURN QUERY SELECT definition_row.id,definition_row.recon_code;
END;
$function$

CREATE OR REPLACE FUNCTION public.instantiate_tenant_template_atomic(_tenant_id uuid, _tenant_template_id uuid, _name text, _owner_bu_ids uuid[])
 RETURNS TABLE(recon_definition_id uuid, recon_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  actor uuid := auth.uid();
  template_row public.tenant_templates%ROWTYPE;
  definition_row public.recon_definitions%ROWTYPE;
  source_count integer;
  leg_count integer;
BEGIN
  IF actor IS NULL OR NOT (
    public.is_platform_admin(actor)
    OR public.has_tenant_role(actor,_tenant_id,'tenant_admin')
    OR public.has_tenant_role(actor,_tenant_id,'tenant_analyst')
  ) THEN
    RAISE EXCEPTION 'analyst or admin role required' USING ERRCODE='42501';
  END IF;
  IF length(btrim(COALESCE(_name,''))) NOT BETWEEN 2 AND 80 THEN
    RAISE EXCEPTION 'invalid reconciliation name' USING ERRCODE='22023';
  END IF;
  IF coalesce(cardinality(_owner_bu_ids), 0) = 0 THEN
    RAISE EXCEPTION 'select at least one owning business unit' USING ERRCODE='22023';
  END IF;

  SELECT * INTO template_row FROM public.tenant_templates
  WHERE id=_tenant_template_id AND tenant_id=_tenant_id AND status='published'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'published tenant template not found' USING ERRCODE='P0002'; END IF;
  IF template_row.spec->>'kind' <> 'reconciliation'
     OR jsonb_typeof(template_row.spec->'sides') <> 'array'
     OR jsonb_typeof(template_row.spec->'rules') <> 'array' THEN
    RAISE EXCEPTION 'tenant template is not runnable' USING ERRCODE='22023';
  END IF;

  leg_count := jsonb_array_length(template_row.spec->'sides');
  SELECT count(*) INTO source_count FROM jsonb_array_elements(template_row.spec->'sides') side
  JOIN public.workspace_data_sources source
    ON source.id=(side->>'data_source_id')::uuid AND source.tenant_id=_tenant_id;
  IF source_count<>leg_count OR leg_count NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'template sources are unavailable in tenant' USING ERRCODE='42501';
  END IF;
  IF (SELECT count(DISTINCT side->>'data_source_id') FROM jsonb_array_elements(template_row.spec->'sides') side) <> leg_count THEN
    RAISE EXCEPTION 'template source bindings must be distinct' USING ERRCODE='22023';
  END IF;

  SELECT created.id,created.recon_code INTO definition_row.id,definition_row.recon_code
  FROM public.create_recon_definition_with_owners(
    _tenant_id,btrim(_name),template_row.description,template_row.spec->>'recon_type',
    template_row.spec->'sides',template_row.spec->'rules',_owner_bu_ids
  ) AS created;
  IF definition_row.id IS NULL THEN RAISE EXCEPTION 'owner-bound creation returned no reconciliation'; END IF;

  UPDATE public.recon_definitions SET tenant_template_id=template_row.id
  WHERE id=definition_row.id AND tenant_id=_tenant_id
  RETURNING * INTO definition_row;
  IF NOT FOUND THEN RAISE EXCEPTION 'created reconciliation was not readable in tenant'; END IF;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (actor,_tenant_id,'workspace','recon.tenant_template.instantiate','recon_definition',definition_row.id::text,
    jsonb_build_object('recon_code',definition_row.recon_code,'tenant_template_id',template_row.id,
      'semver',template_row.current_semver,'owner_bu_ids',_owner_bu_ids));
  INSERT INTO public.mkt_audit_log(actor_id,tenant_id,entity_type,entity_id,action,after)
  VALUES (actor,_tenant_id,'tenant_template',template_row.id,'instantiate',
    jsonb_build_object('recon_definition_id',definition_row.id,'recon_code',definition_row.recon_code,
      'owner_bu_ids',_owner_bu_ids));
  RETURN QUERY SELECT definition_row.id,definition_row.recon_code;
END
$function$

CREATE OR REPLACE FUNCTION public.finalize_data_prep_run(_tenant_id uuid, _run_id uuid, _config jsonb, _rows_in integer, _rows jsonb, _profile jsonb, _status text, _dq_results jsonb, _content_sha256 text, _size_bytes bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pipeline public.data_prep_pipelines%ROWTYPE;
  v_run public.data_prep_runs%ROWTYPE;
  v_output public.workspace_data_sources%ROWTYPE;
  v_rows_out integer;
  v_actor uuid := auth.uid();
BEGIN
  IF v_actor IS NULL OR _status IS NULL OR _status NOT IN ('success','warn','failed')
    OR _rows_in IS NULL OR _rows_in < 0
    OR jsonb_typeof(_rows) IS DISTINCT FROM 'array'
    OR jsonb_typeof(_dq_results) IS DISTINCT FROM 'array'
    OR jsonb_typeof(_profile->'columns') IS DISTINCT FROM 'array'
    OR jsonb_typeof(_profile->'sample_rows') IS DISTINCT FROM 'array'
    OR _content_sha256 IS NULL OR _content_sha256 !~ '^[a-f0-9]{64}$'
    OR _size_bytes IS NULL OR _size_bytes < 0
  THEN RAISE EXCEPTION 'Pipeline completion is unavailable.' USING ERRCODE='22023'; END IF;

  SELECT p.* INTO v_pipeline FROM public.data_prep_pipelines p
    JOIN public.data_prep_runs r ON r.pipeline_id=p.id AND r.tenant_id=p.tenant_id
    WHERE r.id=_run_id AND r.tenant_id=_tenant_id
    FOR UPDATE OF p;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pipeline completion access is unavailable.' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_run FROM public.data_prep_runs
    WHERE id=_run_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND OR v_run.triggered_by IS DISTINCT FROM v_actor
    OR public.can_start_data_prep_run(_tenant_id,v_pipeline.id) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'Pipeline completion access is unavailable.' USING ERRCODE='42501'; END IF;

  -- A retry of a committed completion returns its retained result without new effects.
  IF v_run.finished_at IS NOT NULL THEN
    RETURN jsonb_build_object('run_id',v_run.id,'run_uid',v_run.run_uid,
      'status',v_run.status,'rows_in',v_run.rows_in,'rows_out',v_run.rows_out,'dq',v_run.dq_results);
  END IF;
  IF v_run.status IS DISTINCT FROM 'running'
    OR jsonb_build_object('source_data_source_id',v_pipeline.source_data_source_id,
      'output_data_source_id',v_pipeline.output_data_source_id,'steps',v_pipeline.steps,
      'dq_rules',v_pipeline.dq_rules,'on_failure',v_pipeline.on_failure)
      IS DISTINCT FROM _config
  THEN RAISE EXCEPTION 'Pipeline configuration changed. Start a new run.' USING ERRCODE='40001'; END IF;
  IF v_run.execution_protocol = 'atomic_v1' AND _config IS DISTINCT FROM v_run.execution_snapshot THEN
    RAISE EXCEPTION 'Pipeline configuration changed. Start a new run.' USING ERRCODE='40001';
  END IF;
  v_rows_out := jsonb_array_length(_rows);

  IF _status <> 'failed' AND v_pipeline.output_data_source_id IS NOT NULL THEN
    SELECT * INTO v_output FROM public.workspace_data_sources
      WHERE id=v_pipeline.output_data_source_id AND tenant_id=_tenant_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pipeline output access is unavailable.' USING ERRCODE='42501'; END IF;
    INSERT INTO public.workspace_data_source_uploads(
      data_source_id,tenant_id,rows,uploaded_by,filename,mime_type,size_bytes,
      row_count,columns,sample_rows,content_sha256
    ) VALUES (
      v_output.id,_tenant_id,_rows,v_actor,
      'pipeline-'||coalesce(v_pipeline.public_uid,v_pipeline.id::text)||'-'||v_run.run_uid||'.json',
      'application/json',_size_bytes,v_rows_out,_profile->'columns',
      _profile->'sample_rows',_content_sha256
    );
    UPDATE public.workspace_data_sources SET inferred_schema=_profile->'columns',
      sample_rows=_profile->'sample_rows',row_count=v_rows_out,status='ready',last_error=NULL
      WHERE id=v_output.id AND tenant_id=_tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pipeline output update is unavailable.' USING ERRCODE='42501'; END IF;
  END IF;

  PERFORM set_config('fvi.data_prep_finish',v_run.id::text,true);
  UPDATE public.data_prep_runs SET status=_status,rows_in=_rows_in,rows_out=v_rows_out,
    dq_results=_dq_results,finished_at=now(),error=NULL WHERE id=v_run.id AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pipeline run update is unavailable.' USING ERRCODE='42501'; END IF;
  PERFORM set_config('fvi.data_prep_finish','',true);
  UPDATE public.data_prep_pipelines SET last_run_at=now(),last_status=_status,last_error=NULL
    WHERE id=v_pipeline.id AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pipeline state update is unavailable.' USING ERRCODE='42501'; END IF;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(v_actor,_tenant_id,'workspace','data_prep.run','data_prep_run',v_run.id::text,
      jsonb_build_object('pipeline',v_pipeline.name,'status',_status,'rows_in',_rows_in,
        'rows_out',v_rows_out,'run_uid',v_run.run_uid));
  RETURN jsonb_build_object('run_id',v_run.id,'run_uid',v_run.run_uid,
    'status',_status,'rows_in',_rows_in,'rows_out',v_rows_out,'dq',_dq_results);
END $function$

CREATE OR REPLACE FUNCTION public.claim_recon_schedule_run_for_definition(_tenant_id uuid, _definition_id uuid, _schedule_id uuid, _trigger text, _scheduled_for timestamp with time zone, _occurrence_key text, _attempt integer, _actor_user_id uuid, _parent_run_id bigint)
 RETURNS TABLE(schedule_run_id bigint, disposition text, run_attempt integer, allowed_attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  bound_schedule public.recon_schedules%ROWTYPE;
BEGIN
  IF _tenant_id IS NULL OR _definition_id IS NULL OR _actor_user_id IS NULL THEN
    RAISE EXCEPTION 'tenant, definition, and accountable actor are required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO bound_schedule
  FROM public.recon_schedules schedule_row
  WHERE schedule_row.id = _schedule_id
    AND schedule_row.tenant_id = _tenant_id
    AND schedule_row.definition_id = _definition_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'schedule scope changed or not found' USING ERRCODE='P0002'; END IF;
  IF NOT public.service_recon_actor_access_decision(_actor_user_id, _definition_id, 'run') THEN
    RAISE EXCEPTION 'reconciliation run is not authorized' USING ERRCODE='42501';
  END IF;

  RETURN QUERY
  SELECT * FROM public.claim_recon_schedule_run(
    _schedule_id, _trigger, _scheduled_for, _occurrence_key,
    _attempt, _actor_user_id, _parent_run_id
  );
END
$function$

CREATE OR REPLACE FUNCTION public.create_recon_run_for_actor(_tenant_id uuid, _definition_id uuid, _actor_user_id uuid)
 RETURNS TABLE(id uuid, run_uid text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  previous_sub text := current_setting('request.jwt.claim.sub', true);
  created_id uuid;
  created_run_uid text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     OR _tenant_id IS NULL OR _definition_id IS NULL OR _actor_user_id IS NULL THEN
    RAISE EXCEPTION 'tenant, definition, and accountable service actor are required' USING ERRCODE='42501';
  END IF;
  PERFORM set_config('request.jwt.claim.sub', _actor_user_id::text, true);
  IF NOT private.recon_authoritative_access_decision(_definition_id, 'run')
     OR NOT EXISTS (
       SELECT 1 FROM public.recon_definitions definition_row
       WHERE definition_row.id = _definition_id AND definition_row.tenant_id = _tenant_id
     ) THEN
    RAISE EXCEPTION 'reconciliation run is not authorized' USING ERRCODE='42501';
  END IF;

  INSERT INTO public.recon_runs(tenant_id, definition_id, status, run_by)
  VALUES (_tenant_id, _definition_id, 'running', _actor_user_id)
  RETURNING recon_runs.id, recon_runs.run_uid INTO created_id, created_run_uid;
  PERFORM set_config('request.jwt.claim.sub', coalesce(previous_sub, ''), true);
  RETURN QUERY SELECT created_id, created_run_uid;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('request.jwt.claim.sub', coalesce(previous_sub, ''), true);
  RAISE;
END
$function$

CREATE OR REPLACE FUNCTION private.rs_store(_tenant uuid, _run uuid, _key uuid, _intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE r public.recon_runs%ROWTYPE;a uuid;p jsonb;qualified jsonb;pin jsonb;s jsonb;u public.workspace_data_source_uploads%ROWTYPE;
 manifest jsonb:='[]';attachments jsonb:='[]';selected jsonb;field text;row_item jsonb;ordinal bigint;row_date date;
 receipt jsonb;retention jsonb;fingerprint text;arrival timestamptz;opens timestamptz;closes timestamptz;cutoff timestamptz;population jsonb;effective_rows jsonb;prepared jsonb;selected_indexes integer[];
 intrinsic boolean:=false;ordinary boolean:=false;native_binding jsonb;contract jsonb;input_proof jsonb;current_definition public.recon_definitions%ROWTYPE;configuration_sha text;
BEGIN
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND run_by=auth.uid();
 IF NOT FOUND OR r.status<>'queued' THEN RAISE EXCEPTION 'rs.owned_queued_run_required' USING ERRCODE='42501';END IF;
 a:=private.rs_actor(_tenant,r.definition_id,'run');PERFORM private.recon_atomic_admit(_tenant,_run);
 SELECT policy,qualification INTO p,qualified FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=r.definition_id
 AND policy_id=(_intent->>'policy_id')::uuid AND version=_intent->>'policy_version';
 IF NOT FOUND AND _intent->>'input_kind'='prepared_bound' THEN
  native_binding:=public.dpw_get_recon_binding(_tenant,_key);
  IF native_binding->>'run_id' IS DISTINCT FROM _run::text OR native_binding->>'actor_id' IS DISTINCT FROM a::text
   OR native_binding->>'approved_snapshot_sha256' IS DISTINCT FROM r.approved_revision_sha256
   OR r.approved_revision_sha256 IS DISTINCT FROM _intent->>'expected_definition_sha256'
   OR r.approved_revision_id::text IS DISTINCT FROM _intent->>'policy_id'
   OR r.approved_revision_number::text IS DISTINCT FROM _intent->>'policy_version'
   OR native_binding->>'business_date' IS DISTINCT FROM _intent->>'business_date'
  THEN RAISE EXCEPTION 'rs.actual_approved_prepared_cohort_required' USING ERRCODE='42501';END IF;
  intrinsic:=true;
  p:=jsonb_build_object('policy_id',r.approved_revision_id,'version',r.approved_revision_number::text,'policy_kind','approved_native_input_binding',
   'business_date',native_binding->>'business_date','date_basis','prepared_delivery_metadata','as_of',(native_binding->>'business_date')||'T00:00:00Z',
   'market_calendar_available',false,'feed_timing_available',false,'no_market_cutoff_inferred',true,'approved_definition_sha256',r.approved_revision_sha256);
  qualified:=jsonb_build_object('state','native_qualified','kind','approved_native_input_binding','approved_revision_id',r.approved_revision_id,
   'approved_definition_sha256',r.approved_revision_sha256,'binding_producer','dpw_get_recon_binding');
 END IF;
 IF p->>'policy_kind'='ordinary_native_snapshot' THEN
  SELECT * INTO current_definition FROM public.recon_definitions WHERE id=r.definition_id AND tenant_id=_tenant;
  configuration_sha:=encode(sha256(convert_to(private.recon_definition_config_snapshot(current_definition)::text,'UTF8')),'hex');
  IF qualified->>'state' IS DISTINCT FROM 'native_qualified' OR qualified->>'kind' IS DISTINCT FROM 'ordinary_native_snapshot'
  OR qualified->>'producer' IS DISTINCT FROM 'resolve_recon_ordinary_cohort'
  OR p->>'configuration_sha256' IS DISTINCT FROM configuration_sha
  OR p->>'approved_revision_id' IS DISTINCT FROM r.approved_revision_id::text
  OR (p->>'configuration_authority'='native_approved_revision' AND p->>'configuration_sha256' IS DISTINCT FROM r.approved_revision_sha256)
  OR (p->>'configuration_authority' IN('native_approved_revision','native_current_configuration')) IS DISTINCT FROM true
  OR p->'pins' IS DISTINCT FROM _intent->'pins' OR p->>'cohort_mode' IS DISTINCT FROM 'explicit_snapshot_selection'
  THEN RAISE EXCEPTION 'rs.actual_approved_ordinary_cohort_required' USING ERRCODE='42501';END IF;
  ordinary:=true;intrinsic:=true;
 END IF;
 IF NOT intrinsic AND (qualified->>'state' IS DISTINCT FROM 'native_qualified' OR (qualified->>'source_sha256' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM true
 OR (qualified->>'calendar_sha256' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM true OR p->>'policy_id' IS DISTINCT FROM _intent->>'policy_id'
 OR p->>'version' IS DISTINCT FROM _intent->>'policy_version' OR p->'calendar'->>'id' IS NULL OR p->'calendar'->>'version' IS NULL
 OR p->'calendar'->>'time_zone' IS NULL OR jsonb_typeof(p->'calendar'->'open_weekdays') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p->'calendar'->'closed_dates') IS DISTINCT FROM 'array'
 OR (p->>'date_basis' IN('business_date','value_date')) IS DISTINCT FROM true OR (p->>'early_policy' IN('include','defer')) IS DISTINCT FROM true
 OR (p->>'late_policy' IN('include_until_cutoff','reject')) IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'rs.native_calendar_source_policy_unqualified' USING ERRCODE='42501';END IF;
 IF NOT intrinsic THEN
 IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=p->'calendar'->>'time_zone')
 OR p->>'business_date' !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'rs.invalid_qualified_calendar' USING ERRCODE='22023';END IF;
 PERFORM (p->>'business_date')::date;
 opens:=(p->>'expected_window_opens_at')::timestamptz;closes:=(p->>'expected_window_closes_at')::timestamptz;cutoff:=(p->>'arrival_cutoff')::timestamptz;
 IF opens IS NULL OR closes IS NULL OR cutoff IS NULL OR closes<opens OR cutoff<closes THEN RAISE EXCEPTION 'rs.invalid_qualified_window' USING ERRCODE='22023';END IF;
 END IF;
 IF jsonb_typeof(_intent->'pins') IS DISTINCT FROM 'array' OR jsonb_array_length(_intent->'pins')<>jsonb_array_length(r.definition_snapshot->'sides')
 OR (SELECT count(DISTINCT x->>'side_id') FROM jsonb_array_elements(_intent->'pins') x)<>jsonb_array_length(_intent->'pins')
 THEN RAISE EXCEPTION 'rs.complete_distinct_pins_required' USING ERRCODE='22023';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(r.definition_snapshot->'sides') LOOP
  SELECT value INTO pin FROM jsonb_array_elements(_intent->'pins') WHERE value->>'side_id'=s->>'side_id';
  IF NOT FOUND OR (s->>'upload_id' IS NOT NULL AND s->>'upload_id' IS DISTINCT FROM pin->>'upload_id')
  OR private.data_source_child_allows(a,_tenant,(s->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  OR NOT has_table_privilege('authenticated','public.workspace_data_source_uploads','SELECT')
  THEN RAISE EXCEPTION 'rs.current_source_or_pin_denied' USING ERRCODE='42501';END IF;
  SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(pin->>'upload_id')::uuid AND tenant_id=_tenant AND data_source_id=(s->>'data_source_id')::uuid;
  IF NOT FOUND OR jsonb_typeof(u.rows) IS DISTINCT FROM 'array' OR u.row_count<>jsonb_array_length(u.rows) THEN RAISE EXCEPTION 'rs.observed_upload_unavailable' USING ERRCODE='42501';END IF;
  arrival:=u.created_at;
  IF NOT intrinsic AND (arrival>cutoff OR (arrival<opens AND p->>'early_policy'='defer') OR (arrival>closes AND p->>'late_policy'='reject'))
  THEN RAISE EXCEPTION 'rs.feed_timing_refused_no_fallback' USING ERRCODE='PT409';END IF;
  field:=p->'date_fields'->(s->>'side_id')->>(p->>'date_basis');
  IF NOT intrinsic AND (field IS NULL OR field='') THEN RAISE EXCEPTION 'rs.explicit_date_basis_required' USING ERRCODE='22023';END IF;
  selected_indexes:=NULL;prepared:=NULL;
  IF _intent->>'input_kind'='prepared_bound' THEN
   prepared:=public.dpw_get_recon_input_rows(_tenant,_run,s->>'side_id');
   IF prepared->>'tenant_id' IS DISTINCT FROM _tenant::text OR prepared->>'actor_id' IS DISTINCT FROM a::text
    OR prepared->'binding'->>'upload_id' IS DISTINCT FROM u.id::text OR prepared->'binding'->>'data_source_id' IS DISTINCT FROM u.data_source_id::text
    OR jsonb_typeof(prepared->'rows') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'rs.actual_prepared_logical_side_binding_required' USING ERRCODE='42501';END IF;
   IF prepared->'binding'->'output_indexes' IS NOT NULL AND prepared->'binding'->'output_indexes'<>'null'::jsonb THEN
    SELECT array_agg(x.value::integer ORDER BY x.ordinal) INTO selected_indexes FROM jsonb_array_elements_text(prepared->'binding'->'output_indexes') WITH ORDINALITY x(value,ordinal);
   END IF;
  END IF;
  IF ordinary THEN
   IF s->>'upload_id' IS NULL AND (EXISTS(SELECT 1 FROM public.data_prep_prepared_datasets x WHERE x.tenant_id=_tenant AND x.upload_id=u.id)
    OR EXISTS(SELECT 1 FROM public.data_prep_pipelines dp WHERE dp.tenant_id=_tenant AND dp.output_data_source_id=u.data_source_id))
   THEN RAISE EXCEPTION 'rs.prepared_source_requires_native_per_run_binding' USING ERRCODE='42501';END IF;
   SELECT x.value INTO input_proof FROM jsonb_array_elements(p->'input_proofs') x WHERE x.value->>'side_id'=s->>'side_id';
   IF input_proof->>'upload_id' IS DISTINCT FROM u.id::text
   OR input_proof->>'rows_sha256' IS DISTINCT FROM encode(sha256(convert_to(u.rows::text,'UTF8')),'hex')
   THEN RAISE EXCEPTION 'rs.selected_input_changed_requires_new_intent' USING ERRCODE='PT409';END IF;
   effective_rows:=u.rows;
   SELECT jsonb_build_object('rows',effective_rows,'submitted_rows',jsonb_array_length(effective_rows),'carried_rows',0,
    'row_lineage',coalesce(jsonb_agg(jsonb_build_object('upload_id',u.id,'ordinal',ordinality-1,'first_seen_at',u.created_at) ORDER BY ordinality),'[]')) INTO population
    FROM jsonb_array_elements(effective_rows) WITH ORDINALITY;
  ELSIF intrinsic THEN
   IF prepared IS NULL OR prepared->'binding'->>'binding_kind'='prepared_dataset' AND prepared->'binding'->>'business_date' IS DISTINCT FROM p->>'business_date'
   THEN RAISE EXCEPTION 'rs.prepared_native_business_cohort_mismatch' USING ERRCODE='42501';END IF;
   effective_rows:=prepared->'rows';
   SELECT jsonb_build_object('rows',effective_rows,'submitted_rows',jsonb_array_length(effective_rows),'carried_rows',0,
    'row_lineage',coalesce(jsonb_agg(jsonb_build_object('upload_id',u.id,'ordinal',CASE WHEN selected_indexes IS NULL THEN ordinality-1 ELSE selected_indexes[ordinality::integer] END,'first_seen_at',u.created_at) ORDER BY ordinality),'[]')) INTO population
    FROM jsonb_array_elements(effective_rows) WITH ORDINALITY;
  ELSE population:=private.rs_population(_tenant,r.definition_id,s->>'side_id',u.data_source_id,u.id,p,selected_indexes);effective_rows:=population->'rows';END IF;
  IF prepared IS NOT NULL AND effective_rows IS DISTINCT FROM prepared->'rows' AND p->'feed_policies'->(s->>'side_id')->>'mode'='full_snapshot'
  THEN RAISE EXCEPTION 'rs.prepared_native_row_projection_mismatch' USING ERRCODE='PT409';END IF;
  selected:='[]';
  FOR row_item,ordinal IN SELECT value,ordinality-1 FROM jsonb_array_elements(effective_rows) WITH ORDINALITY LOOP
   IF jsonb_typeof(row_item) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'rs.invalid_prepared_record' USING ERRCODE='22023';END IF;
   IF intrinsic THEN selected:=selected||to_jsonb(ordinal);CONTINUE;END IF;
   IF jsonb_typeof(row_item->field) IS DISTINCT FROM 'string'
   OR row_item->>field !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'rs.invalid_source_date' USING ERRCODE='22023';END IF;
   row_date:=(row_item->>field)::date;
   IF row_date::text IS DISTINCT FROM row_item->>field THEN RAISE EXCEPTION 'rs.invalid_source_calendar_date' USING ERRCODE='22023';END IF;
   IF row_date=(p->>'business_date')::date THEN selected:=selected||to_jsonb(ordinal);END IF;
  END LOOP;
  IF jsonb_array_length(selected)=0 THEN RAISE EXCEPTION 'rs.required_cohort_empty_no_fallback' USING ERRCODE='PT409';END IF;
  manifest:=manifest||jsonb_build_array(jsonb_build_object('side_id',s->>'side_id','data_source_id',u.data_source_id,'upload_id',u.id,
    'arrival_at',u.created_at,'input_rows',jsonb_array_length(effective_rows),'selected_ordinals',selected,
    'submitted_rows',population->'submitted_rows','carried_rows',population->'carried_rows','amended_rows',population->'amended_rows','cancelled_rows',population->'cancelled_rows',
    'feed_policy',p->'feed_policies'->(s->>'side_id'),'prepared_binding',prepared->'binding','rows_sha256',encode(sha256(convert_to(effective_rows::text,'UTF8')),'hex'),
    'submitted_rows_sha256',encode(sha256(convert_to(u.rows::text,'UTF8')),'hex'),
    'timing',CASE WHEN intrinsic THEN 'unclassified' WHEN arrival<opens THEN 'early' WHEN arrival>closes THEN 'late' ELSE 'on_time' END));
  attachments:=attachments||jsonb_build_array(jsonb_build_object('side_id',s->>'side_id','data_source_id',u.data_source_id,'upload_id',u.id,
    'arrival_at',u.created_at,'rows',effective_rows,'row_lineage',population->'row_lineage','submitted_rows',population->'submitted_rows','carried_rows',population->'carried_rows','selected_ordinals',selected));
 END LOOP;
 retention:=public.dpw_get_attachment_retention(_tenant)->'effective';
 IF retention IS NULL OR retention->>'policy_id' IS NULL OR retention->>'version' !~ '^[0-9]+$'
 OR (retention->>'period_days')::integer<1 OR retention->>'source' NOT IN('platform','tenant') THEN RAISE EXCEPTION 'rs.retention_unqualified' USING ERRCODE='42501';END IF;
 receipt:=jsonb_build_object('created_at',clock_timestamp(),'policy_id',retention->>'policy_id','policy_version',retention->>'version',
   'period_days',(retention->>'period_days')::integer,'policy_source',retention->>'source','physical_purge_enabled',false,'metadata_retained',true);
 receipt:=receipt||jsonb_build_object('expires_at',(receipt->>'created_at')::timestamptz+((retention->>'period_days')::integer*interval '1 day'));
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('definition_snapshot',r.definition_snapshot,'approved_revision_id',r.approved_revision_id,
   'approved_revision_sha256',r.approved_revision_sha256,'policy',p,'manifest',manifest)::text,'UTF8')),'hex');
 INSERT INTO private.rs_requests(run_id,tenant_id,definition_id,actor_id,request_key,intent,manifest,input_fingerprint,attachment_receipt)
 VALUES(_run,_tenant,r.definition_id,a,_key,_intent,manifest,fingerprint,receipt);
 INSERT INTO private.rs_attachments(run_id,side_id,data_source_id,upload_id,arrival_at,rows,selected_ordinals,row_lineage,submitted_rows,carried_rows)
 SELECT _run,x.side_id,x.data_source_id,x.upload_id,x.arrival_at,x.rows,x.selected_ordinals,x.row_lineage,x.submitted_rows,x.carried_rows
 FROM jsonb_to_recordset(attachments) x(side_id text,data_source_id uuid,upload_id uuid,arrival_at timestamptz,rows jsonb,selected_ordinals jsonb,row_lineage jsonb,submitted_rows integer,carried_rows integer);
 INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,a,'request_admitted',jsonb_build_object('request_key',_key,'manifest',manifest,'input_fingerprint',fingerprint,'policy',p,'qualification',qualified,'attachment_receipt',receipt));
 RETURN (private.rs_prior(_tenant,r.definition_id,_key,_intent)-'execution_kind')||jsonb_build_object('execution_kind','fresh');
END $function$

CREATE OR REPLACE FUNCTION public.cutover_assurance_synthetic_recons_atomic()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_tenant uuid := 'aa5ed999-69eb-41a0-a9c6-fbb439efcffb';
  v_executor uuid := '35c27858-e96d-48e3-8bad-1861826a33a7';
  v_maker uuid := '85d57a0a-846d-4a7e-ba94-e5452b9db66c';
  v_checker uuid := '2849df7a-f63c-4b3b-9b5f-1c01c3ae8a43';
  v_mapping jsonb;
  v_code text;
  v_bu_code text;
  v_recon uuid;
  v_bu uuid;
  v_result jsonb;
  v_receipts jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS DISTINCT FROM v_executor
    OR NOT EXISTS (SELECT 1 FROM public.tenants
      WHERE id=v_tenant AND slug::text='falcon-veritas-assurance-lab-prod')
    OR NOT EXISTS (SELECT 1 FROM public.tenant_members
      WHERE tenant_id=v_tenant AND user_id=v_executor AND active
        AND role='tenant_admin'::public.tenant_role)
  THEN RAISE EXCEPTION 'exact active Assurance executor required' USING ERRCODE='42501'; END IF;

  SELECT mapping INTO v_mapping FROM private.assurance_recon_shadow_owner_receipts
  WHERE tenant_id=v_tenant AND owner_count=20 AND grant_count=120;
  IF v_mapping IS NULL OR (SELECT count(*) FROM jsonb_object_keys(v_mapping))<>20
    OR (SELECT count(*) FROM private.assurance_recon_shadow_owner_receipts
      WHERE tenant_id=v_tenant AND owner_count=20 AND grant_count=120)<>1
    OR (SELECT count(*) FROM public.recon_definitions WHERE tenant_id=v_tenant)<>20
    OR (SELECT count(*) FROM public.recon_definition_business_units WHERE tenant_id=v_tenant)<>20
    OR (SELECT count(*) FROM public.recon_definition_bu_grants WHERE tenant_id=v_tenant)<>120
    OR EXISTS (SELECT 1 FROM public.recon_definitions
      WHERE tenant_id=v_tenant AND (access_mode<>'legacy_passthrough'
        OR governance_state<>'legacy_unreviewed' OR multi_bu_governed))
  THEN RAISE EXCEPTION 'exact synthetic Assurance shadow baseline changed' USING ERRCODE='55000'; END IF;

  PERFORM d.id FROM public.recon_definitions d
  WHERE d.tenant_id=v_tenant ORDER BY d.recon_code FOR UPDATE;
  FOR v_code,v_bu_code IN SELECT key,value FROM jsonb_each_text(v_mapping) ORDER BY key LOOP
    SELECT d.id INTO v_recon FROM public.recon_definitions d
      WHERE d.tenant_id=v_tenant AND d.recon_code=v_code;
    SELECT b.id INTO v_bu FROM public.business_units b
      WHERE b.tenant_id=v_tenant AND b.code=v_bu_code AND NOT b.is_archived;
    IF v_recon IS NULL OR v_bu IS NULL OR
      (SELECT count(*) FROM public.recon_definition_business_units o
        WHERE o.tenant_id=v_tenant AND o.recon_id=v_recon AND o.bu_id=v_bu)<>1
    THEN RAISE EXCEPTION 'approved synthetic owner mapping differs' USING ERRCODE='55000'; END IF;
    v_result := public.cutover_assurance_synthetic_recon_mapping(
      v_tenant,v_recon,ARRAY[v_bu],v_maker,v_checker,
      'Owner-authorized exact twenty synthetic Assurance cutover');
    v_receipts := v_receipts || jsonb_build_array(jsonb_build_object(
      'public_id',v_code,'receipt_id',v_result->>'audit_receipt_id'));
  END LOOP;
  IF (SELECT count(*) FROM public.recon_definitions
      WHERE tenant_id=v_tenant AND access_mode='mapped_exact'
        AND governance_state='legacy_mapped' AND multi_bu_governed)<>20
    OR jsonb_array_length(v_receipts)<>20
  THEN RAISE EXCEPTION 'synthetic Assurance atomic cutover readback failed' USING ERRCODE='55000'; END IF;
  RETURN jsonb_build_object('tenant_id',v_tenant,'mapped_count',20,'receipts',v_receipts);
END
$function$

CREATE OR REPLACE FUNCTION private.recon_run_effective_read_allowed(_definition uuid, _tenant uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE;
BEGIN
 IF auth.uid() IS NULL OR _definition IS NULL OR _tenant IS NULL THEN RETURN false; END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 IF NOT FOUND THEN RETURN false; END IF;
 IF d.access_mode='legacy_passthrough' THEN
   RETURN EXISTS(SELECT 1 FROM public.tenant_members
     WHERE tenant_id=_tenant AND user_id=auth.uid() AND active=true)
     OR private.is_platform_admin(auth.uid());
 END IF;
 RETURN private.recon_authoritative_access_decision_as(auth.uid(),d.id,'read');
END $function$

CREATE OR REPLACE FUNCTION private.recon_child_effective_read_allowed(_run uuid, _tenant uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE r public.recon_runs%ROWTYPE;
BEGIN
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant;
 IF NOT FOUND THEN RETURN false; END IF;
 RETURN private.recon_run_effective_read_allowed(r.definition_id,_tenant);
END $function$

CREATE OR REPLACE FUNCTION private.rs_prior(_tenant uuid, _definition uuid, _key uuid, _intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;a uuid:=private.rs_actor(_tenant,_definition,'run');r public.recon_runs%ROWTYPE;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE tenant_id=_tenant AND definition_id=_definition AND actor_id=a AND request_key=_key;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF q.intent IS DISTINCT FROM _intent THEN RAISE EXCEPTION 'rs.request_key_conflict' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=q.run_id AND tenant_id=_tenant AND run_by=a;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.owned_receipt_unavailable' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('actor_id',q.actor_id,'run_id',q.run_id,'run_uid',r.run_uid,'tenant_id',q.tenant_id,'definition_id',q.definition_id,'input_manifest',q.manifest,
 'request_key',_key,'execution_kind','request_replay','status',r.status,'phase',q.phase,'input_fingerprint',q.input_fingerprint,
 'attachment_receipt',q.attachment_receipt,'completion',q.completion,'stats',r.stats,
 'matched_count',r.matched_count,'exception_count',r.exception_count,'total_rows',r.total_rows,
 'matched_records',CASE WHEN q.phase='completed' THEN r.stats->'matched_records' ELSE NULL END,
 'exception_items',CASE WHEN q.phase='completed' THEN r.stats->'exception_items' ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION private.rs_claim(_tenant uuid, _run uuid, _claim uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;a uuid;r public.recon_runs%ROWTYPE;p jsonb;uploads jsonb;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE run_id=_run AND tenant_id=_tenant AND actor_id=auth.uid() FOR UPDATE;
 IF NOT FOUND OR _claim IS NULL THEN RAISE EXCEPTION 'rs.owned_request_required' USING ERRCODE='42501';END IF;
 a:=private.rs_actor(_tenant,q.definition_id,'run');PERFORM private.recon_atomic_admit(_tenant,_run);
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND run_by=a;
 IF q.phase<>'queued' THEN RETURN jsonb_build_object('actor_id',a,'tenant_id',q.tenant_id,'definition_id',q.definition_id,'request_key',q.request_key,
 'run_uid',r.run_uid,'status',r.status,'input_manifest',q.manifest,'claimed',false,'phase',q.phase,'run_id',_run,'execution_kind','request_replay');END IF;
 PERFORM private.rs_validate_prepared_execution(_tenant,_run);
 IF EXISTS(SELECT 1 FROM public.recon_runs WHERE tenant_id=_tenant AND definition_id=q.definition_id AND status='running' AND id<>_run)
 OR EXISTS(SELECT 1 FROM private.rs_requests WHERE tenant_id=_tenant AND definition_id=q.definition_id AND phase IN('queued','running')
   AND (created_at,run_id)<(q.created_at,q.run_id)) THEN RETURN jsonb_build_object('actor_id',a,'tenant_id',q.tenant_id,'definition_id',q.definition_id,
 'request_key',q.request_key,'run_uid',r.run_uid,'status',r.status,'input_manifest',q.manifest,'claimed',false,'phase',q.phase,'run_id',_run,'execution_kind','fresh');END IF;
 IF private.rs_artifact_read_state(_tenant,_run,NULL)->'available' IS DISTINCT FROM 'true'::jsonb
 THEN RAISE EXCEPTION 'rs.attachment_availability_expired_or_tombstoned_metadata_retained' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND run_by=a;
 IF r.status<>'queued' OR r.definition_snapshot IS NULL THEN RAISE EXCEPTION 'rs.run_state_conflict' USING ERRCODE='PT409';END IF;
 FOR p IN SELECT value FROM jsonb_array_elements(q.manifest) LOOP
  IF private.data_source_child_allows(a,_tenant,(p->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'rs.current_source_denied' USING ERRCODE='42501';END IF;
 END LOOP;
 UPDATE private.rs_requests SET phase='running',claim_id=_claim WHERE run_id=_run;
 SELECT payload->'policy' INTO p FROM private.rs_events WHERE run_id=_run AND kind='request_admitted';
 SELECT jsonb_agg(jsonb_build_object('side_id',side_id,'data_source_id',data_source_id,'upload_id',upload_id,'arrival_at',arrival_at,'rows',rows,'row_lineage',row_lineage,'submitted_rows',submitted_rows,'carried_rows',carried_rows,
 'native_cohort',CASE WHEN p->>'policy_kind' IN('approved_native_input_binding','ordinary_native_snapshot') THEN jsonb_build_object('qualified_native_binding',true,'business_date',p->>'business_date',
  'binding_kind',CASE WHEN p->>'policy_kind'='ordinary_native_snapshot' THEN 'fixed_upload' ELSE (SELECT m->'prepared_binding'->>'binding_kind' FROM jsonb_array_elements(q.manifest) m WHERE m->>'side_id'=side_id) END) ELSE NULL END,
 'native_timing',jsonb_build_object('qualified_native_observation',true,'policy_id',p->>'policy_id','policy_version',p->>'version',
  'calendar_id',p->'calendar'->>'id','calendar_version',p->'calendar'->>'version','arrival_at',arrival_at,
  'timing',CASE WHEN arrival_at<(p->>'expected_window_opens_at')::timestamptz THEN 'early' WHEN arrival_at>(p->>'expected_window_closes_at')::timestamptz THEN 'late' ELSE 'on_time' END,
  'within_arrival_cutoff',arrival_at<=(p->>'arrival_cutoff')::timestamptz)) ORDER BY side_id) INTO uploads FROM private.rs_attachments WHERE run_id=_run;
 INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,a,'execution_claimed',jsonb_build_object('claim_id',_claim,'input_fingerprint',q.input_fingerprint));
 RETURN jsonb_build_object('actor_id',a,'claimed',true,'phase','running','execution_kind','fresh','run_id',_run,'run_uid',r.run_uid,'tenant_id',_tenant,
 'definition_id',q.definition_id,'claim_id',_claim,'input_fingerprint',q.input_fingerprint,'manifest',q.manifest,'policy',p,'uploads',uploads,
 'attachment_receipt',q.attachment_receipt,'definition_snapshot',r.definition_snapshot,'approved_revision_id',r.approved_revision_id,
 'approved_revision_number',r.approved_revision_number,'approved_revision_sha256',r.approved_revision_sha256);
END $function$

CREATE OR REPLACE FUNCTION private.rs_finalize(_tenant uuid, _run uuid, _claim uuid, _completion jsonb, _groups jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;r public.recon_runs%ROWTYPE;a uuid;g jsonb;i jsonb;manifest_item jsonb;member jsonb;actual jsonb;expected jsonb;
 group_count integer;match_rows integer;break_rows integer;selected_count integer;matched_count integer;unmatched_count integer;native_rule text;native_reason text;native_identity jsonb;first_seen timestamptz;lineage jsonb;effective_ordinal integer;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE run_id=_run AND tenant_id=_tenant AND actor_id=auth.uid() FOR UPDATE;
 IF NOT FOUND OR q.phase<>'running' OR q.claim_id IS DISTINCT FROM _claim THEN RAISE EXCEPTION 'rs.current_claim_required' USING ERRCODE='PT409';END IF;
 a:=private.rs_actor(_tenant,q.definition_id,'run');PERFORM private.recon_atomic_admit(_tenant,_run);
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND run_by=a;
 IF r.status<>'completed' OR r.stats->'_atomic_completion' IS DISTINCT FROM _completion THEN RAISE EXCEPTION 'rs.native_complete_receipt_required' USING ERRCODE='PT409';END IF;
 IF jsonb_typeof(_groups) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'rs.complete_groups_required' USING ERRCODE='22023';END IF;
 SELECT count(*) FILTER(WHERE value->>'match_status'='matched'),count(*) FILTER(WHERE value->>'match_status'='break') INTO match_rows,break_rows FROM jsonb_array_elements(_groups);
 IF match_rows<>r.matched_count OR break_rows<>r.exception_count OR match_rows+break_rows<>jsonb_array_length(_groups)
 THEN RAISE EXCEPTION 'rs.group_count_mismatch' USING ERRCODE='22023';END IF;
 FOR g IN SELECT value FROM jsonb_array_elements(_groups) LOOP
  IF g->>'match_status' NOT IN('matched','break') OR g->>'identity_key' IS NULL OR g->>'native_id' IS NULL
  OR jsonb_typeof(g->'source_rows') IS DISTINCT FROM 'array' OR jsonb_array_length(g->'source_rows')=0
  THEN RAISE EXCEPTION 'rs.group_shape_invalid' USING ERRCODE='22023';END IF;
  expected:='[]';
  FOR i IN SELECT value FROM jsonb_array_elements(g->'source_rows') LOOP
   SELECT value INTO manifest_item FROM jsonb_array_elements(q.manifest) WHERE value->>'side_id'=i->>'side_id';
   effective_ordinal:=coalesce((i->>'effective_ordinal')::integer,(i->>'ordinal')::integer);
   SELECT row_lineage->effective_ordinal INTO lineage FROM private.rs_attachments WHERE run_id=_run AND side_id=i->>'side_id';
   IF manifest_item IS NULL OR manifest_item->>'data_source_id' IS DISTINCT FROM i->>'data_source_id'
   OR lineage->>'upload_id' IS DISTINCT FROM i->>'upload_id' OR lineage->>'ordinal' IS DISTINCT FROM i->>'ordinal'
   OR lineage->>'economic_record_id' IS DISTINCT FROM i->>'economic_record_id' OR NOT (manifest_item->'selected_ordinals' @> jsonb_build_array(effective_ordinal))
   OR i->>'source_row_id' IS DISTINCT FROM replace(jsonb_build_array(i->>'data_source_id',i->>'upload_id',(i->>'ordinal')::integer)::text,', ', ',')
   THEN RAISE EXCEPTION 'rs.unobserved_source_identity' USING ERRCODE='22023';END IF;
   SELECT rows->effective_ordinal INTO member FROM private.rs_attachments WHERE run_id=_run AND side_id=i->>'side_id';
   expected:=expected||jsonb_build_array(jsonb_build_object('side',i->>'side_id','row',member));
  END LOOP;
  IF g->>'match_status'='matched' THEN
   SELECT rule_id,NULL::text INTO native_rule,native_reason FROM public.recon_matches WHERE id=(g->>'native_id')::uuid AND run_id=_run AND tenant_id=_tenant;
   SELECT coalesce(jsonb_agg(jsonb_build_object('side',kv.key,'row',v.value) ORDER BY kv.key,v.value::text),'[]') INTO actual
   FROM public.recon_matches x CROSS JOIN LATERAL jsonb_each(x.members) kv CROSS JOIN LATERAL jsonb_array_elements(kv.value) v
   WHERE x.id=(g->>'native_id')::uuid AND x.run_id=_run AND x.tenant_id=_tenant;
  ELSE
   SELECT payload->>'rule_id',reason INTO native_rule,native_reason FROM public.recon_exceptions WHERE id=(g->>'native_id')::uuid AND run_id=_run AND tenant_id=_tenant;
   SELECT payload INTO actual FROM public.recon_exceptions WHERE id=(g->>'native_id')::uuid AND run_id=_run AND tenant_id=_tenant;
   IF actual ? 'members' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('side',kv.key,'row',v.value) ORDER BY kv.key,v.value::text),'[]') INTO actual
    FROM jsonb_each(actual->'members') kv CROSS JOIN LATERAL jsonb_array_elements(kv.value) v;
   ELSIF actual ? 'row' THEN SELECT jsonb_build_array(jsonb_build_object('side',side,'row',payload->'row')) INTO actual FROM public.recon_exceptions WHERE id=(g->>'native_id')::uuid;
   ELSE RAISE EXCEPTION 'rs.native_membership_shape_unavailable' USING ERRCODE='22023';END IF;
  END IF;
  SELECT coalesce(jsonb_agg(v ORDER BY v->>'side',(v->'row')::text),'[]') INTO expected FROM jsonb_array_elements(expected) v;
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'rs.native_member_projection_mismatch' USING ERRCODE='22023';END IF;
  SELECT jsonb_build_array(g->>'match_status',native_rule,native_reason,jsonb_agg(jsonb_build_array(v->>'side_id',coalesce(v->>'economic_record_id',v->>'source_row_id')) ORDER BY v->>'side_id',coalesce(v->>'economic_record_id',v->>'source_row_id'))) INTO native_identity FROM jsonb_array_elements(g->'source_rows') v;
  IF ((g->>'identity_key')::jsonb->0) IS DISTINCT FROM native_identity->0
  OR ((g->>'identity_key')::jsonb->1) IS DISTINCT FROM native_identity->1 OR ((g->>'identity_key')::jsonb->2) IS DISTINCT FROM native_identity->2
  OR jsonb_array_length((g->>'identity_key')::jsonb->3)<>jsonb_array_length(native_identity->3)
  OR NOT((((g->>'identity_key')::jsonb)->3) @> (native_identity->3) AND (native_identity->3) @> (((g->>'identity_key')::jsonb)->3))
  THEN RAISE EXCEPTION 'rs.native_identity_key_mismatch' USING ERRCODE='22023';END IF;
  SELECT min(oldg.first_seen_at) INTO first_seen FROM private.rs_groups oldg JOIN private.rs_requests oldq ON oldq.run_id=oldg.run_id
  WHERE oldq.tenant_id=q.tenant_id AND oldq.definition_id=q.definition_id AND oldq.phase='completed'
  AND oldg.identity_key=native_identity::text AND oldg.match_status=g->>'match_status';
  SELECT least(first_seen,min((att.row_lineage->coalesce((v->>'effective_ordinal')::integer,(v->>'ordinal')::integer)->>'first_seen_at')::timestamptz))
  INTO first_seen FROM jsonb_array_elements(g->'source_rows') v JOIN private.rs_attachments att ON att.run_id=_run AND att.side_id=v->>'side_id';
  INSERT INTO private.rs_groups(run_id,match_status,ordinal,identity_key,source_rows,native_id,first_seen_at,carry_forward)
  VALUES(_run,g->>'match_status',(g->>'ordinal')::integer,native_identity::text,g->'source_rows',(g->>'native_id')::uuid,coalesce(first_seen,q.created_at),first_seen IS NOT NULL);
 END LOOP;
 SELECT sum(jsonb_array_length(v->'selected_ordinals')) INTO selected_count FROM jsonb_array_elements(q.manifest) v;
 SELECT count(DISTINCT (v->>'side_id',v->>'source_row_id')) INTO matched_count FROM private.rs_groups g CROSS JOIN LATERAL jsonb_array_elements(g.source_rows) v WHERE g.run_id=_run AND g.match_status='matched';
 SELECT count(DISTINCT (v->>'side_id',v->>'source_row_id')) INTO unmatched_count FROM private.rs_groups g CROSS JOIN LATERAL jsonb_array_elements(g.source_rows) v WHERE g.run_id=_run AND g.match_status='break';
 IF selected_count<>r.total_rows OR matched_count IS DISTINCT FROM (r.stats->>'matched_records')::integer
 OR matched_count+unmatched_count<>selected_count OR EXISTS(
  SELECT 1 FROM private.rs_groups m CROSS JOIN LATERAL jsonb_array_elements(m.source_rows) mi
  JOIN private.rs_groups b ON b.run_id=m.run_id AND b.match_status='break'
  CROSS JOIN LATERAL jsonb_array_elements(b.source_rows) bi
  WHERE m.run_id=_run AND m.match_status='matched' AND (mi->>'side_id',mi->>'source_row_id')=(bi->>'side_id',bi->>'source_row_id'))
 THEN RAISE EXCEPTION 'rs.incomplete_membership_waterfall' USING ERRCODE='22023';END IF;
 IF r.stats->'control_waterfall'->>'input_rows' IS DISTINCT FROM (SELECT sum((v->>'input_rows')::integer)::text FROM jsonb_array_elements(q.manifest) v)
 OR r.stats->'control_waterfall'->>'cohort_excluded_rows' IS DISTINCT FROM (SELECT (sum((v->>'input_rows')::integer)-selected_count)::text FROM jsonb_array_elements(q.manifest) v)
 OR r.stats->'control_waterfall'->>'selected_rows' IS DISTINCT FROM selected_count::text
 OR r.stats->'control_waterfall'->>'matched_memberships' IS DISTINCT FROM matched_count::text
 OR r.stats->'control_waterfall'->>'unmatched_memberships' IS DISTINCT FROM unmatched_count::text
 OR r.stats->'control_waterfall'->>'match_groups' IS DISTINCT FROM r.matched_count::text
 OR r.stats->'control_waterfall'->>'exception_items' IS DISTINCT FROM r.exception_count::text
 THEN RAISE EXCEPTION 'rs.persisted_controls_mismatch' USING ERRCODE='22023';END IF;
 UPDATE private.rs_requests SET phase='completed',completion=_completion||jsonb_build_object('phase','completed','actor_id',a,'input_manifest',q.manifest,'execution_kind','fresh',
  'input_fingerprint',q.input_fingerprint,'execution_fingerprint',encode(sha256(convert_to(jsonb_build_object('input_fingerprint',q.input_fingerprint,'reference_versions',r.stats->'reference_versions')::text,'UTF8')),'hex')) WHERE run_id=_run;
 INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,a,'execution_completed',jsonb_build_object('claim_id',_claim,'receipt',_completion,'control_waterfall',r.stats->'control_waterfall'));
 PERFORM private.rs_signal_head(_tenant,q.definition_id);
END $function$

CREATE OR REPLACE FUNCTION private.rs_population(_tenant uuid, _definition uuid, _side text, _source uuid, _upload uuid, _policy jsonb, _selected_indexes integer[] DEFAULT NULL::integer[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE a uuid:=private.rs_actor(_tenant,_definition,'run');u public.workspace_data_source_uploads%ROWTYPE;
 b private.rs_attachments%ROWTYPE;fp jsonb:=_policy->'feed_policies'->_side;q private.rs_requests%ROWTYPE;
 population jsonb:='{}';entry jsonb;item jsonb;lineage jsonb;record_key text;key_field text;operation_field text;operation text;ordinal bigint;
 effective_rows jsonb;effective_lineage jsonb;carried integer:=0;raw_rows jsonb;raw_ordinals jsonb;
BEGIN
 IF private.data_source_child_allows(a,_tenant,_source,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'rs.current_source_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=_upload AND tenant_id=_tenant AND data_source_id=_source;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.exact_population_upload_required' USING ERRCODE='42501';END IF;
 IF _selected_indexes IS NOT NULL AND (cardinality(_selected_indexes)=0 OR (SELECT count(DISTINCT i) FROM unnest(_selected_indexes) i)<>cardinality(_selected_indexes)
 OR EXISTS(SELECT 1 FROM unnest(_selected_indexes) i WHERE i IS NULL OR i<0 OR i>=jsonb_array_length(u.rows))) THEN RAISE EXCEPTION 'rs.prepared_logical_side_indexes_invalid' USING ERRCODE='22023';END IF;
 SELECT coalesce(jsonb_agg(u.rows->i ORDER BY pos),'[]'),coalesce(jsonb_agg(i ORDER BY pos),'[]') INTO raw_rows,raw_ordinals
 FROM unnest(coalesce(_selected_indexes,ARRAY(SELECT generate_series(0,jsonb_array_length(u.rows)-1)))) WITH ORDINALITY x(i,pos);
 IF fp->>'mode'='full_snapshot' THEN
  IF fp->>'identity_field' IS NOT NULL AND ((SELECT count(DISTINCT value->>(fp->>'identity_field')) FROM jsonb_array_elements(raw_rows))<>jsonb_array_length(raw_rows)
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(raw_rows) x WHERE coalesce(x->>(fp->>'identity_field'),'')='')) THEN RAISE EXCEPTION 'rs.snapshot_economic_identity_ambiguous' USING ERRCODE='22023';END IF;
  SELECT coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('upload_id',_upload,'ordinal',raw_ordinals->(ordinality-1)::integer,'first_seen_at',u.created_at,
   'economic_record_id',CASE WHEN fp->>'identity_field' IS NOT NULL THEN value->>(fp->>'identity_field') END)) ORDER BY ordinality),'[]') INTO effective_lineage
  FROM jsonb_array_elements(raw_rows) WITH ORDINALITY;
  RETURN jsonb_build_object('rows',raw_rows,'row_lineage',effective_lineage,'submitted_rows',jsonb_array_length(raw_rows),'carried_rows',0,'amended_rows',0,'cancelled_rows',0);
 END IF;
 IF fp->>'mode' IS DISTINCT FROM 'delta' OR fp->>'identity_field' IS NULL OR fp->>'operation_field' IS NULL
 OR (fp->>'eligible_base' IN('full_population','open_breaks')) IS DISTINCT FROM true OR fp->>'base_run_id' IS NULL
 THEN RAISE EXCEPTION 'rs.explicit_feed_policy_required' USING ERRCODE='42501';END IF;
 key_field:=fp->>'identity_field';operation_field:=fp->>'operation_field';
 IF (SELECT count(DISTINCT value->>key_field) FROM jsonb_array_elements(raw_rows))<>jsonb_array_length(raw_rows)
 THEN RAISE EXCEPTION 'rs.delta_duplicate_operations_ambiguous' USING ERRCODE='22023';END IF;
 SELECT * INTO q FROM private.rs_requests WHERE run_id=(fp->>'base_run_id')::uuid AND tenant_id=_tenant AND definition_id=_definition AND phase='completed';
 IF NOT FOUND OR private.rs_actor(_tenant,_definition,'read') IS NULL THEN RAISE EXCEPTION 'rs.exact_delta_base_unavailable' USING ERRCODE='42501';END IF;
 SELECT * INTO b FROM private.rs_attachments WHERE run_id=q.run_id AND side_id=_side AND data_source_id=_source;
 IF NOT FOUND OR jsonb_array_length(b.rows)<>jsonb_array_length(b.row_lineage) THEN RAISE EXCEPTION 'rs.delta_base_lineage_unavailable' USING ERRCODE='42501';END IF;
 FOR item,ordinal IN SELECT value,ordinality-1 FROM jsonb_array_elements(b.rows) WITH ORDINALITY LOOP
  lineage:=b.row_lineage->ordinal::integer;record_key:=item->>key_field;
  IF lineage->>'economic_record_id' IS DISTINCT FROM record_key THEN RAISE EXCEPTION 'rs.delta_base_record_tracking_unqualified' USING ERRCODE='42501';END IF;
  IF record_key IS NULL OR record_key='' OR population ? record_key THEN RAISE EXCEPTION 'rs.delta_economic_identity_ambiguous' USING ERRCODE='22023';END IF;
  IF fp->>'eligible_base'='open_breaks' AND NOT EXISTS(
   SELECT 1 FROM private.rs_groups g CROSS JOIN LATERAL jsonb_array_elements(g.source_rows) sr
   JOIN public.recon_exceptions e ON e.id=g.native_id AND e.run_id=g.run_id AND e.tenant_id=_tenant
   WHERE g.run_id=q.run_id AND g.match_status='break' AND sr->>'side_id'=_side
    AND sr->>'upload_id'=lineage->>'upload_id' AND sr->>'ordinal'=lineage->>'ordinal'
    AND e.status NOT IN('resolved','wont_fix') AND e.lifecycle_state NOT IN('resolved','written_off')) THEN CONTINUE;END IF;
  population:=population||jsonb_build_object(record_key,jsonb_build_object('row',item,'lineage',lineage||jsonb_build_object('economic_record_id',record_key,'carried',true)));
 END LOOP;
 FOR item,ordinal IN SELECT value,(raw_ordinals->>(ordinality-1)::integer)::bigint FROM jsonb_array_elements(raw_rows) WITH ORDINALITY LOOP
  record_key:=item->>key_field;operation:=item->>operation_field;
  IF record_key IS NULL OR record_key='' OR (operation IN('insert','update','delete')) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'rs.delta_operation_or_identity_invalid' USING ERRCODE='22023';END IF;
  IF operation='insert' AND population ? record_key OR operation IN('update','delete') AND NOT(population ? record_key)
  THEN RAISE EXCEPTION 'rs.delta_population_conflict' USING ERRCODE='PT409';END IF;
  IF operation='delete' THEN population:=population-record_key;CONTINUE;END IF;
  entry:=population->record_key;
  lineage:=jsonb_build_object('upload_id',_upload,'ordinal',ordinal,'economic_record_id',record_key,'first_seen_at',coalesce(entry->'lineage'->>'first_seen_at',u.created_at::text),
    'previous_origin',entry->'lineage','carried',false);
  population:=population||jsonb_build_object(record_key,jsonb_build_object('row',CASE WHEN fp->'strip_operation_field'='true'::jsonb THEN item-operation_field ELSE item END,'lineage',lineage));
 END LOOP;
 SELECT coalesce(jsonb_agg(value->'row' ORDER BY key),'[]'),coalesce(jsonb_agg(value->'lineage' ORDER BY key),'[]'),
 count(*) FILTER(WHERE value->'lineage'->'carried'='true'::jsonb) INTO effective_rows,effective_lineage,carried FROM jsonb_each(population);
 RETURN jsonb_build_object('rows',effective_rows,'row_lineage',effective_lineage,'submitted_rows',jsonb_array_length(raw_rows),'carried_rows',carried,
  'amended_rows',(SELECT count(*) FROM jsonb_array_elements(raw_rows) x WHERE x->>operation_field='update'),
  'cancelled_rows',(SELECT count(*) FROM jsonb_array_elements(raw_rows) x WHERE x->>operation_field='delete'));
END $function$

CREATE OR REPLACE FUNCTION public.mkt_llm_usage_stats(_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  pii_reader boolean := public.has_mkt_pii_read_access();
  since_at timestamptz;
  calls_count bigint;
  ok_count bigint;
  token_count bigint;
  cost_total numeric;
  latency_total bigint;
  result jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT (
    public.has_mkt_role(auth.uid(), 'super_admin'::public.mkt_admin_role)
    OR public.has_mkt_role(auth.uid(), 'ai_admin'::public.mkt_admin_role)
  ) THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;
  IF _days IS NULL OR _days NOT IN (7, 30, 90) THEN
    RAISE EXCEPTION 'unsupported range' USING ERRCODE = '22023';
  END IF;
  since_at := now() - make_interval(days => _days);

  SELECT count(*), count(*) FILTER (WHERE ok),
         coalesce(sum(tokens_in + tokens_out), 0), coalesce(sum(cost_usd), 0),
         coalesce(sum(latency_ms), 0)
  INTO calls_count, ok_count, token_count, cost_total, latency_total
  FROM public.mkt_llm_usage
  WHERE created_at >= since_at;

  SELECT jsonb_build_object(
    'restricted', NOT pii_reader,
    'totals', jsonb_build_object(
      'calls', CASE WHEN pii_reader OR calls_count >= 5 THEN calls_count ELSE NULL END,
      'ok_rate', CASE WHEN pii_reader OR calls_count >= 5
        THEN CASE WHEN calls_count = 0 THEN 1 ELSE ok_count::numeric / calls_count END ELSE NULL END,
      'tokens', CASE WHEN pii_reader OR calls_count >= 5 THEN token_count ELSE NULL END,
      'cost_usd', CASE WHEN pii_reader OR calls_count >= 5 THEN cost_total ELSE NULL END,
      'avg_latency_ms', CASE WHEN pii_reader OR calls_count >= 5
        THEN CASE WHEN calls_count = 0 THEN 0 ELSE round(latency_total::numeric / calls_count)::bigint END ELSE NULL END
    ),
    'byProvider', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', coalesce(provider_id::text, 'unknown'),
        'name', coalesce(display_name, 'Unknown'),
        'provider', coalesce(provider, 'unknown'),
        'calls', calls,
        'ok', ok_calls,
        'tokens_in', tokens_in,
        'tokens_out', tokens_out,
        'cost_usd', cost_usd,
        'latency_sum', latency_sum
      ) ORDER BY cost_usd DESC), '[]'::jsonb)
      FROM (
        SELECT u.provider_id, p.display_name, p.provider,
               count(*) AS calls,
               count(*) FILTER (WHERE u.ok) AS ok_calls,
               coalesce(sum(u.tokens_in), 0) AS tokens_in,
               coalesce(sum(u.tokens_out), 0) AS tokens_out,
               coalesce(sum(u.cost_usd), 0) AS cost_usd,
               coalesce(sum(u.latency_ms), 0) AS latency_sum
        FROM public.mkt_llm_usage u
        LEFT JOIN public.mkt_llm_providers p ON p.id = u.provider_id
        WHERE u.created_at >= since_at
        GROUP BY u.provider_id, p.display_name, p.provider
      ) AS provider_totals
      WHERE pii_reader OR calls >= 5
    ),
    'byDay', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'day', day, 'cost_usd', cost_usd, 'tokens', tokens, 'calls', calls
      ) ORDER BY day), '[]'::jsonb)
      FROM (
        SELECT to_char(created_at AT TIME ZONE 'UTC', 'YYYY-MM-DD') AS day,
               coalesce(sum(cost_usd), 0) AS cost_usd,
               coalesce(sum(tokens_in + tokens_out), 0) AS tokens,
               count(*) AS calls
        FROM public.mkt_llm_usage
        WHERE created_at >= since_at
        GROUP BY 1
      ) AS day_totals
      WHERE pii_reader OR calls >= 5
    )
  ) INTO result;

  RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_api_token_principal_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.created_by IS DISTINCT FROM OLD.created_by
      OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
      OR NEW.token_hash IS DISTINCT FROM OLD.token_hash) THEN
    RAISE EXCEPTION 'immutable_api_token_identity' USING ERRCODE = '23514';
  END IF;
  IF current_user NOT IN ('service_role', 'postgres') THEN
    IF TG_OP = 'INSERT' AND (NEW.created_by IS DISTINCT FROM auth.uid()
        OR NEW.principal_kind <> 'unclassified'
        OR NEW.subject_user_id IS NOT NULL OR NEW.service_principal_id IS NOT NULL) THEN
      RAISE EXCEPTION 'api_token_principal_requires_service_role' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' AND (NEW.principal_kind IS DISTINCT FROM OLD.principal_kind
        OR NEW.subject_user_id IS DISTINCT FROM OLD.subject_user_id
        OR NEW.service_principal_id IS DISTINCT FROM OLD.service_principal_id) THEN
      RAISE EXCEPTION 'api_token_principal_requires_service_role' USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.classify_mcp_oauth_access_token()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE token_row public.api_tokens%ROWTYPE;
BEGIN
  SELECT * INTO token_row FROM public.api_tokens WHERE id = NEW.api_token_id FOR UPDATE;
  IF NOT FOUND OR token_row.tenant_id <> NEW.tenant_id
     OR token_row.created_by IS DISTINCT FROM NEW.user_id
     OR token_row.principal_kind <> 'unclassified' THEN
    RAISE EXCEPTION 'invalid_mcp_token_principal' USING ERRCODE = '23514';
  END IF;
  UPDATE public.api_tokens
  SET principal_kind = 'user_delegated', subject_user_id = NEW.user_id
  WHERE id = NEW.api_token_id;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.rs_carry_event(_tenant uuid, _run uuid, _case uuid, _prior_case uuid, _labels jsonb, _comments jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;old_run uuid;a uuid;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE run_id=_run AND tenant_id=_tenant AND actor_id=auth.uid();
 IF NOT FOUND OR q.phase<>'completed' THEN RAISE EXCEPTION 'rs.owned_completed_claim_required' USING ERRCODE='42501';END IF;
 a:=private.rs_actor(_tenant,q.definition_id,'edit');
 SELECT o.run_id INTO old_run FROM private.rs_groups n JOIN private.rs_groups o ON o.identity_key=n.identity_key AND o.match_status='break' AND o.run_id<>n.run_id
 JOIN private.rs_requests oq ON oq.run_id=o.run_id AND oq.tenant_id=q.tenant_id AND oq.definition_id=q.definition_id AND oq.phase='completed'
 WHERE n.run_id=_run AND n.native_id=_case AND o.native_id=_prior_case AND n.match_status='break';
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.exact_carry_provenance_required' USING ERRCODE='42501';END IF;
 INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,a,'break_metadata_carried',jsonb_build_object('new_case_id',_case,
   'source_case_id',_prior_case,'source_run_id',old_run,'labels',_labels,'comment_references',_comments,
   'workflow_status_carried',false,'approvals_carried',false));
END $function$

CREATE OR REPLACE FUNCTION private.rs_fail(_tenant uuid, _run uuid, _claim uuid, _code text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;a uuid;r public.recon_runs%ROWTYPE;
BEGIN SELECT * INTO q FROM private.rs_requests WHERE run_id=_run AND tenant_id=_tenant AND actor_id=auth.uid() FOR UPDATE;
 IF NOT FOUND OR q.phase<>'running' OR q.claim_id IS DISTINCT FROM _claim OR _code NOT IN('evaluation_failed','evaluation_budget_exceeded') THEN RAISE EXCEPTION 'rs.claim_failure_conflict' USING ERRCODE='PT409';END IF;
 a:=private.rs_actor(_tenant,q.definition_id,'run');SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant;
 IF r.status<>'failed' OR r.stats ? '_atomic_completion' THEN RAISE EXCEPTION 'rs.native_failure_required' USING ERRCODE='PT409';END IF;
 UPDATE private.rs_requests SET phase='failed',completion=jsonb_build_object('status','failed','error_code',_code) WHERE run_id=_run;
 INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,a,'execution_failed',jsonb_build_object('claim_id',_claim,'error_code',_code));
 PERFORM private.rs_signal_head(_tenant,q.definition_id);
END $function$

CREATE OR REPLACE FUNCTION public.request_recon_execution(_tenant_id uuid, _definition_id uuid, _request_key uuid, _policy_id uuid, _policy_version text, _pins jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE intent jsonb;prior jsonb;r public.recon_runs%ROWTYPE;d public.recon_definitions%ROWTYPE;pin jsonb;s jsonb;
BEGIN
 IF _request_key IS NULL OR _policy_id IS NULL OR _policy_version IS NULL OR length(_policy_version) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'rs.intent_required' USING ERRCODE='22023';END IF;
 PERFORM private.rs_actor(_tenant_id,_definition_id,'run');
 PERFORM pg_advisory_xact_lock(hashtextextended('rs:'||_tenant_id::text||':'||_definition_id::text,0));
 intent:=jsonb_build_object('policy_id',_policy_id,'policy_version',_policy_version,'pins',_pins);
 prior:=private.rs_prior(_tenant_id,_definition_id,_request_key,intent);IF prior IS NOT NULL THEN RETURN prior;END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_definition_required' USING ERRCODE='42501';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(d.sides) LOOP
  SELECT value INTO pin FROM jsonb_array_elements(_pins) WHERE value->>'side_id'=s->>'side_id';
  PERFORM 1 FROM public.workspace_data_sources WHERE id=(s->>'data_source_id')::uuid AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_source_required' USING ERRCODE='42501';END IF;
  PERFORM 1 FROM public.workspace_data_source_uploads WHERE id=(pin->>'upload_id')::uuid AND data_source_id=(s->>'data_source_id')::uuid AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_exact_upload_required' USING ERRCODE='42501';END IF;
 END LOOP;
 -- Existing native INSERT triggers produce run_uid and immutable config/revision.
 INSERT INTO public.recon_runs(tenant_id,definition_id,status,run_by) VALUES(_tenant_id,_definition_id,'queued',auth.uid()) RETURNING * INTO r;
 RETURN private.rs_store(_tenant_id,r.id,_request_key,intent);
END $function$

CREATE OR REPLACE FUNCTION public.tg_recon_run_not_retired()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE;
BEGIN
  SELECT * INTO d FROM public.recon_definitions WHERE id=NEW.definition_id AND tenant_id=NEW.tenant_id FOR SHARE;
  IF NOT FOUND OR d.retired_at IS NOT NULL OR d.status='archived' THEN
    RAISE EXCEPTION 'reconciliation is unavailable for execution' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.claim_recon_schedule_run(_schedule_id uuid, _trigger text, _scheduled_for timestamp with time zone, _occurrence_key text, _attempt integer DEFAULT 1, _actor_user_id uuid DEFAULT NULL::uuid, _parent_run_id bigint DEFAULT NULL::bigint)
 RETURNS TABLE(schedule_run_id bigint, disposition text, run_attempt integer, allowed_attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  sched public.recon_schedules%ROWTYPE;
  existing_run public.recon_schedule_runs%ROWTYPE;
  active_run public.recon_schedule_runs%ROWTYPE;
  expired_run public.recon_schedule_runs%ROWTYPE;
  new_run public.recon_schedule_runs%ROWTYPE;
  effective_max integer;
  next_retry timestamptz;
BEGIN
  IF _trigger NOT IN ('cron', 'manual', 'watcher', 'retry', 'once') THEN
    RAISE EXCEPTION 'invalid orchestrator trigger' USING ERRCODE = '22023';
  END IF;
  IF _scheduled_for IS NULL OR NULLIF(btrim(_occurrence_key), '') IS NULL OR length(_occurrence_key) > 180 THEN
    RAISE EXCEPTION 'invalid orchestrator occurrence' USING ERRCODE = '22023';
  END IF;
  IF _attempt NOT BETWEEN 1 AND 5 THEN
    RAISE EXCEPTION 'invalid orchestrator attempt' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO sched FROM public.recon_schedules WHERE id = _schedule_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'schedule not found' USING ERRCODE = 'P0002'; END IF;

  IF EXISTS (SELECT 1 FROM public.recon_definitions d WHERE d.id=sched.definition_id
      AND (d.retired_at IS NOT NULL OR d.status='archived')) THEN
    RAISE EXCEPTION 'retired reconciliation cannot be run' USING ERRCODE='23514';
  END IF;
  IF _trigger='once' AND (sched.schedule_kind<>'one_time' OR _scheduled_for IS DISTINCT FROM sched.one_time_at
      OR _scheduled_for > now() OR date_trunc('minute',_scheduled_for)<>_scheduled_for
      OR _occurrence_key IS DISTINCT FROM 'once:'||to_char(_scheduled_for AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) THEN
    RAISE EXCEPTION 'one-time occurrence no longer matches schedule' USING ERRCODE='23514';
  END IF;
  IF _trigger='cron' AND sched.schedule_kind<>'recurring' THEN
    RAISE EXCEPTION 'recurring occurrence no longer matches schedule' USING ERRCODE='23514';
  END IF;
  IF _trigger='retry' AND NOT EXISTS (SELECT 1 FROM public.recon_schedule_runs p
    WHERE p.id=_parent_run_id AND p.schedule_id=sched.id AND p.tenant_id=sched.tenant_id
      AND p.status='failed' AND (p.superseded_by_id IS NULL OR p.superseded_by_id=(SELECT duplicate.id FROM public.recon_schedule_runs duplicate
        WHERE duplicate.schedule_id=sched.id AND duplicate.occurrence_key=_occurrence_key AND duplicate.attempt=_attempt)) AND p.attempt+1=_attempt
      AND p.occurrence_key=_occurrence_key AND p.scheduled_for=_scheduled_for
      AND p.schedule_revision=sched.schedule_revision AND p.retry_after<=now()) THEN
    RAISE EXCEPTION 'retry occurrence is stale or not due' USING ERRCODE='23514';
  END IF;

  effective_max := CASE WHEN _trigger = 'manual' THEN 1 ELSE sched.max_attempts END;
  IF _attempt > effective_max THEN
    RAISE EXCEPTION 'attempt exceeds schedule retry policy' USING ERRCODE = '22023';
  END IF;

  IF _trigger NOT IN ('manual','once') AND NOT sched.enabled THEN
    IF _parent_run_id IS NOT NULL THEN
      UPDATE public.recon_schedule_runs
      SET retry_after = NULL, retry_claimed_at = now()
      WHERE id = _parent_run_id AND schedule_id = sched.id AND superseded_by_id IS NULL;
    END IF;
    INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (_actor_user_id, sched.tenant_id, 'workspace',
      CASE WHEN _actor_user_id IS NULL THEN 'system.recon.schedule.run.disabled' ELSE 'recon.schedule.run.disabled' END,
      'recon_schedule', sched.id,
      jsonb_build_object('trigger', _trigger, 'scheduled_for', _scheduled_for, 'occurrence_key', _occurrence_key));
    RETURN QUERY SELECT NULL::bigint, 'disabled'::text, _attempt, effective_max;
    RETURN;
  END IF;
  IF _trigger = 'once' AND NOT sched.enabled THEN
    INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (_actor_user_id, sched.tenant_id, 'workspace',
      CASE WHEN _actor_user_id IS NULL THEN 'system.recon.schedule.run.disabled' ELSE 'recon.schedule.run.disabled' END,
      'recon_schedule', sched.id,
      jsonb_build_object('trigger', _trigger, 'scheduled_for', _scheduled_for, 'occurrence_key', _occurrence_key));
    RETURN QUERY SELECT NULL::bigint, 'disabled'::text, _attempt, effective_max;
    RETURN;
  END IF;

  SELECT * INTO existing_run
  FROM public.recon_schedule_runs
  WHERE schedule_id = sched.id AND occurrence_key = _occurrence_key AND attempt = _attempt;
  IF FOUND THEN
    IF _parent_run_id IS NOT NULL THEN
      UPDATE public.recon_schedule_runs SET superseded_by_id = existing_run.id, retry_claimed_at = now()
      WHERE id = _parent_run_id AND schedule_id = sched.id AND superseded_by_id IS NULL;
    END IF;
    RETURN QUERY SELECT existing_run.id, 'duplicate'::text, existing_run.attempt::integer, existing_run.max_attempts::integer;
    RETURN;
  END IF;

  UPDATE public.recon_schedule_runs
  SET status = 'failed', finished_at = now(), error = 'lease_expired', lease_expires_at = NULL,
      retry_after = CASE WHEN attempt < max_attempts THEN now() + make_interval(secs => sched.retry_backoff_seconds * (2 ^ (attempt - 1))::integer) END
  WHERE schedule_id = sched.id AND status = 'running' AND lease_expires_at <= now()
  RETURNING * INTO expired_run;
  IF FOUND THEN
    UPDATE public.recon_runs SET status='failed',error='Schedule execution lease expired',completed_at=now()
      WHERE id=expired_run.recon_run_id AND tenant_id=sched.tenant_id AND status='running';
    INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (NULL, sched.tenant_id, 'workspace', 'system.recon.schedule.run.lease_expired', 'recon_schedule', sched.id,
      jsonb_build_object('schedule_run_id', expired_run.id, 'attempt', expired_run.attempt));
  END IF;

  SELECT * INTO active_run
  FROM public.recon_schedule_runs
  WHERE schedule_id = sched.id AND status = 'running'
  ORDER BY started_at DESC, id DESC LIMIT 1;

  IF FOUND THEN
    next_retry := CASE WHEN _attempt < effective_max
      THEN now() + make_interval(secs => sched.retry_backoff_seconds * (2 ^ (_attempt - 1))::integer)
      ELSE NULL END;
    INSERT INTO public.recon_schedule_runs(
      schedule_id, tenant_id, trigger, status, scheduled_for, occurrence_key,
      attempt, max_attempts, retry_after, actor_user_id, finished_at, error, schedule_revision
    ) VALUES (
      sched.id, sched.tenant_id, _trigger, 'failed', _scheduled_for, _occurrence_key,
      _attempt, effective_max, next_retry, _actor_user_id, now(), 'overlap_prevented', sched.schedule_revision
    ) RETURNING * INTO new_run;
    IF _parent_run_id IS NOT NULL THEN
      UPDATE public.recon_schedule_runs SET superseded_by_id = new_run.id, retry_claimed_at = now()
      WHERE id = _parent_run_id AND schedule_id = sched.id AND superseded_by_id IS NULL;
    END IF;
    IF _trigger IN ('cron','once') THEN
      UPDATE public.recon_schedules SET last_dispatched_for = GREATEST(last_dispatched_for, _scheduled_for)
      WHERE id = sched.id;
    END IF;
    INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (_actor_user_id, sched.tenant_id, 'workspace',
      CASE WHEN _actor_user_id IS NULL THEN 'system.recon.schedule.run.overlap_prevented' ELSE 'recon.schedule.run.overlap_prevented' END,
      'recon_schedule', sched.id,
      jsonb_build_object('schedule_run_id', new_run.id, 'active_schedule_run_id', active_run.id,
        'attempt', _attempt, 'retry_after', next_retry, 'scheduled_for', _scheduled_for));
    RETURN QUERY SELECT new_run.id, 'overlap'::text, _attempt, effective_max;
    RETURN;
  END IF;

  INSERT INTO public.recon_schedule_runs(
    schedule_id, tenant_id, trigger, status, scheduled_for, occurrence_key,
    attempt, max_attempts, actor_user_id, lease_expires_at, schedule_revision
  ) VALUES (
    sched.id, sched.tenant_id, _trigger, 'running', _scheduled_for, _occurrence_key,
    _attempt, effective_max, _actor_user_id, now() + interval '2 hours', sched.schedule_revision
  ) RETURNING * INTO new_run;

  IF _parent_run_id IS NOT NULL THEN
    UPDATE public.recon_schedule_runs SET superseded_by_id = new_run.id, retry_claimed_at = now()
    WHERE id = _parent_run_id AND schedule_id = sched.id AND superseded_by_id IS NULL;
  END IF;
  IF _trigger IN ('cron','once') THEN
    UPDATE public.recon_schedules SET last_dispatched_for = GREATEST(last_dispatched_for, _scheduled_for)
    WHERE id = sched.id;
  END IF;
  INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
  VALUES (_actor_user_id, sched.tenant_id, 'workspace',
    CASE WHEN _actor_user_id IS NULL THEN 'system.recon.schedule.run.started' ELSE 'recon.schedule.run.started' END,
    'recon_schedule', sched.id,
    jsonb_build_object('schedule_run_id', new_run.id, 'trigger', _trigger, 'attempt', _attempt,
      'max_attempts', effective_max, 'scheduled_for', _scheduled_for, 'occurrence_key', _occurrence_key));
  RETURN QUERY SELECT new_run.id, 'claimed'::text, _attempt, effective_max;
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_recon_schedule_run(_schedule_run_id bigint, _status text, _recon_run_id uuid DEFAULT NULL::uuid, _matched_count integer DEFAULT 0, _exception_count integer DEFAULT 0, _total_rows integer DEFAULT 0, _error text DEFAULT NULL::text, _context jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(final_status text, next_retry_at timestamp with time zone, run_attempt integer, allowed_attempts integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  run_row public.recon_schedule_runs%ROWTYPE;
  schedule_id_value uuid;
  sched public.recon_schedules%ROWTYPE;
  retry_at timestamptz;
  stored_error text;
BEGIN
  IF _status NOT IN ('completed', 'failed') THEN
    RAISE EXCEPTION 'invalid terminal orchestrator status' USING ERRCODE = '22023';
  END IF;
  SELECT schedule_id INTO schedule_id_value FROM public.recon_schedule_runs WHERE id=_schedule_run_id;
  SELECT * INTO sched FROM public.recon_schedules WHERE id=schedule_id_value FOR UPDATE;
  SELECT * INTO run_row FROM public.recon_schedule_runs WHERE id = _schedule_run_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'schedule run not found' USING ERRCODE = 'P0002'; END IF;
  IF run_row.status <> 'running' THEN
    RAISE EXCEPTION 'schedule run is not active' USING ERRCODE = 'P0001';
  END IF;
  IF run_row.lease_expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'schedule lease expired' USING ERRCODE='23514';
  END IF;
  IF run_row.recon_run_id IS NOT NULL AND run_row.recon_run_id IS DISTINCT FROM _recon_run_id THEN
    RAISE EXCEPTION 'schedule completion run mismatch' USING ERRCODE='23514';
  END IF;
  stored_error := CASE WHEN _status = 'failed' THEN left(COALESCE(_error, 'reconciliation_failed'), 1000) ELSE NULL END;
  retry_at := CASE WHEN _status = 'failed' AND run_row.attempt < run_row.max_attempts AND sched.enabled AND run_row.schedule_revision=sched.schedule_revision
    THEN now() + make_interval(secs => sched.retry_backoff_seconds * (2 ^ (run_row.attempt - 1))::integer)
    ELSE NULL END;

  -- Commit processing and orchestration terminal state together. A crash must
  -- never leave a completed reconciliation behind an expired schedule lease.
  IF _recon_run_id IS NOT NULL THEN
    UPDATE public.recon_runs SET status=_status,completed_at=now(),error=stored_error,
      matched_count=_matched_count,exception_count=_exception_count,total_rows=_total_rows,
      stats=CASE WHEN _status='completed' AND jsonb_typeof(_context->'stats')='object' THEN _context->'stats' ELSE stats END
      WHERE id=_recon_run_id AND tenant_id=run_row.tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'schedule processing run scope mismatch' USING ERRCODE='23514'; END IF;
  END IF;

  UPDATE public.recon_schedule_runs
  SET status = _status, recon_run_id = _recon_run_id, finished_at = now(), lease_expires_at = NULL,
      matched_count = _matched_count, exception_count = _exception_count, total_rows = _total_rows,
      error = stored_error, retry_after = retry_at
  WHERE id = run_row.id;

  UPDATE public.recon_schedules
  SET last_run_at = now(),
      last_status = CASE WHEN retry_at IS NOT NULL THEN 'retry_scheduled' ELSE _status END,
      last_run_id = _recon_run_id,
      last_error = stored_error
  WHERE id = sched.id;

  INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
  VALUES (run_row.actor_user_id, run_row.tenant_id, 'workspace',
    CASE
      WHEN _status = 'completed' AND run_row.actor_user_id IS NULL THEN 'system.recon.schedule.run.complete'
      WHEN _status = 'completed' THEN 'recon.schedule.run.complete'
      WHEN retry_at IS NOT NULL AND run_row.actor_user_id IS NULL THEN 'system.recon.schedule.run.retry_scheduled'
      WHEN retry_at IS NOT NULL THEN 'recon.schedule.run.retry_scheduled'
      WHEN run_row.actor_user_id IS NULL THEN 'system.recon.schedule.run.failed'
      ELSE 'recon.schedule.run.failed'
    END,
    'recon_schedule', run_row.schedule_id,
    COALESCE(_context, '{}'::jsonb) || jsonb_build_object(
      'schedule_run_id', run_row.id, 'recon_run_id', _recon_run_id,
      'trigger', run_row.trigger, 'attempt', run_row.attempt,
      'max_attempts', run_row.max_attempts, 'retry_after', retry_at,
      'matched', _matched_count, 'exceptions', _exception_count, 'total_rows', _total_rows,
      'error', stored_error));

  RETURN QUERY SELECT _status, retry_at, run_row.attempt::integer, run_row.max_attempts::integer;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_recon_execution(_tenant_id uuid, _run_id uuid, _claim_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE r public.recon_runs%ROWTYPE;receipt jsonb;changed integer;m jsonb;
BEGIN
 SELECT * INTO r FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND run_by=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_owned_run_required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rs:'||_tenant_id::text||':'||r.definition_id::text,0));
 PERFORM 1 FROM public.recon_definitions WHERE id=r.definition_id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_visible_definition_required' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND run_by=auth.uid() FOR UPDATE;
 receipt:=private.rs_claim(_tenant_id,_run_id,_claim_id);
 IF receipt->'claimed'='true'::jsonb THEN
  FOR m IN SELECT value FROM jsonb_array_elements(receipt->'manifest') LOOP
   PERFORM 1 FROM public.workspace_data_sources WHERE id=(m->>'data_source_id')::uuid AND tenant_id=_tenant_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_visible_source_required' USING ERRCODE='42501';END IF;
   PERFORM 1 FROM public.workspace_data_source_uploads WHERE id=(m->>'upload_id')::uuid AND tenant_id=_tenant_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_visible_upload_required' USING ERRCODE='42501';END IF;
  END LOOP;
  UPDATE public.recon_runs SET status='running',started_at=clock_timestamp() WHERE id=_run_id AND tenant_id=_tenant_id AND run_by=auth.uid() AND status='queued';
  GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'rs.current_run_update_denied' USING ERRCODE='42501';END IF;
 END IF;RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION public.start_recon_schedule_execution(_tenant_id uuid, _definition_id uuid, _schedule_id uuid, _expected_revision bigint, _enforce boolean, _trigger text, _scheduled_for timestamp with time zone, _occurrence_key text, _attempt integer, _actor_user_id uuid, _parent_run_id bigint)
 RETURNS TABLE(schedule_run_id bigint, disposition text, recon_run_id uuid, execution_snapshot jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE s public.recon_schedules%ROWTYPE; d public.recon_definitions%ROWTYPE;
  v public.recon_definition_approved_versions%ROWTYPE; c record; r public.recon_runs%ROWTYPE; actor uuid; created_run_id uuid; prior_run public.recon_runs%ROWTYPE;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' OR _enforce IS NULL OR _expected_revision IS NULL THEN
    RAISE EXCEPTION 'service execution and revision required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO s FROM public.recon_schedules WHERE id=_schedule_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'schedule not found' USING ERRCODE='P0002'; END IF;
  IF s.definition_id IS DISTINCT FROM _definition_id OR s.schedule_revision IS DISTINCT FROM _expected_revision THEN
    RETURN QUERY SELECT NULL::bigint,'stale'::text,NULL::uuid,NULL::jsonb; RETURN;
  END IF;
  SELECT * INTO d FROM public.recon_definitions WHERE id=s.definition_id AND tenant_id=s.tenant_id FOR SHARE;
  IF NOT FOUND OR d.status='archived' OR d.retired_at IS NOT NULL THEN
    RETURN QUERY SELECT NULL::bigint,'blocked'::text,NULL::uuid,NULL::jsonb; RETURN;
  END IF;
  actor:=coalesce(_actor_user_id,s.created_by);
  IF _enforce THEN
    IF NOT public.service_recon_actor_access_decision(actor,d.id,'run') THEN
      RETURN QUERY SELECT NULL::bigint,'blocked'::text,NULL::uuid,NULL::jsonb; RETURN;
    END IF;
  ELSIF d.access_mode IS DISTINCT FROM 'legacy_passthrough' THEN
    RAISE EXCEPTION 'legacy path cannot execute governed definitions' USING ERRCODE='42501';
  END IF;
  IF d.access_mode IS DISTINCT FROM 'legacy_passthrough' THEN
    SELECT * INTO v FROM public.recon_definition_approved_versions WHERE tenant_id=d.tenant_id AND parent_definition_id=d.id
      ORDER BY version_number DESC LIMIT 1;
    IF NOT FOUND OR v.snapshot IS DISTINCT FROM private.recon_definition_config_snapshot(d)
      OR v.snapshot_sha256<>encode(extensions.digest(convert_to(v.snapshot::text,'UTF8'),'sha256'),'hex') THEN
      RAISE EXCEPTION 'definition configuration is not the published approved revision' USING ERRCODE='23514';
    END IF;
  END IF;
  IF _trigger='retry' THEN
    SELECT processing.* INTO prior_run FROM public.recon_schedule_runs attempt
      JOIN public.recon_runs processing ON processing.id=attempt.recon_run_id AND processing.tenant_id=attempt.tenant_id
      WHERE attempt.id=_parent_run_id AND attempt.schedule_id=s.id AND attempt.tenant_id=s.tenant_id;
    IF NOT FOUND OR prior_run.approved_revision_id IS DISTINCT FROM v.id
      OR prior_run.definition_snapshot->'rules' IS DISTINCT FROM d.rules
      OR prior_run.definition_snapshot->'sides' IS DISTINCT FROM d.sides
      OR prior_run.definition_snapshot->>'recon_type' IS DISTINCT FROM d.recon_type THEN
      UPDATE public.recon_schedule_runs SET retry_after=NULL,retry_claimed_at=now()
        WHERE id=_parent_run_id AND schedule_id=s.id AND tenant_id=s.tenant_id AND superseded_by_id IS NULL;
      INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
        VALUES(NULL,s.tenant_id,'workspace','system.recon.schedule.retry.cancelled','recon_schedule',s.id,
          jsonb_build_object('schedule_run_id',_parent_run_id,'reason','execution_configuration_changed'));
      RETURN QUERY SELECT NULL::bigint,'stale'::text,NULL::uuid,NULL::jsonb; RETURN;
    END IF;
  END IF;
  SELECT * INTO c FROM public.claim_recon_schedule_run(s.id,_trigger,_scheduled_for,_occurrence_key,_attempt,actor,_parent_run_id);
  IF c.disposition<>'claimed' THEN
    RETURN QUERY SELECT c.schedule_run_id,c.disposition,NULL::uuid,NULL::jsonb; RETURN;
  END IF;
  IF _enforce THEN
    -- Advance the command snapshot after the volatile creation RPC; an outer
    -- SELECT cannot reliably see a row inserted by its own nested subquery.
    SELECT created.id INTO created_run_id FROM public.create_recon_run_for_actor(s.tenant_id,d.id,actor) created;
    SELECT * INTO r FROM public.recon_runs WHERE id=created_run_id;
  ELSE
    INSERT INTO public.recon_runs(tenant_id,definition_id,status,run_by) VALUES(s.tenant_id,d.id,'running',actor) RETURNING * INTO r;
  END IF;
  IF r.id IS NULL OR r.definition_snapshot IS NULL THEN RAISE EXCEPTION 'immutable run snapshot required' USING ERRCODE='23514'; END IF;
  IF v.id IS NOT NULL AND (r.approved_revision_id IS DISTINCT FROM v.id OR r.approved_revision_sha256 IS DISTINCT FROM v.snapshot_sha256) THEN
    RAISE EXCEPTION 'run approved revision binding mismatch' USING ERRCODE='23514';
  END IF;
  UPDATE public.recon_schedule_runs SET recon_run_id=r.id WHERE id=c.schedule_run_id;
  RETURN QUERY SELECT c.schedule_run_id,'claimed'::text,r.id,
    CASE WHEN v.id IS NOT NULL THEN v.snapshot ELSE r.definition_snapshot END;
END $function$

CREATE OR REPLACE FUNCTION private.dpdi_reviewer_frame(_tenant uuid, _kind text, _request uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r jsonb:=private.dpdi_reviewer_reference(_tenant,_kind,_request);j private.dpdi_jobs%ROWTYPE;c public.data_prep_configuration_revisions%ROWTYPE;p public.data_prep_pipelines%ROWTYPE;e private.dpdi_job_events%ROWTYPE;run public.data_prep_delivery_runs%ROWTYPE;expired boolean;stale boolean;complete boolean;
BEGIN
 IF private.dpdi_reviewer_visible(_tenant,_kind,_request,_actor) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.current_independent_selected_checker_required' USING ERRCODE='42501';END IF;
 SELECT * INTO j FROM private.dpdi_jobs WHERE id=(r->>'job_id')::uuid;j:=private.dpdi_authorize(_tenant,j.setup_id,j.id,_actor,false);e:=private.dpdi_head(j.id);
 SELECT * INTO c FROM public.data_prep_configuration_revisions WHERE id=(j.snapshot->>'configuration_id')::uuid AND tenant_id=_tenant;SELECT * INTO p FROM public.data_prep_pipelines WHERE id=c.pipeline_id AND tenant_id=_tenant;
 expired:=EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND NOT private.dpd_original_viewable(i.original_file_id));
 stale:=c.id IS NULL OR p.id IS NULL OR p.version IS DISTINCT FROM c.pipeline_version OR c.payload_sha256 IS DISTINCT FROM j.snapshot->>'configuration_sha256' OR private.dpw_hash(c.payload) IS DISTINCT FROM c.payload_sha256 OR private.dpw_hash(j.snapshot) IS DISTINCT FROM j.snapshot_sha256 OR (r->>'draft_version')::integer IS DISTINCT FROM j.draft_version OR (SELECT max(version) FROM private.dpd_versions WHERE setup_id=j.setup_id) IS DISTINCT FROM j.draft_version OR (_kind='setup' AND r->>'snapshot_sha256' IS DISTINCT FROM j.snapshot_sha256) OR (_kind='publication' AND r->>'output_root_sha256' IS DISTINCT FROM e.output_root_sha256);
 SELECT * INTO run FROM public.data_prep_delivery_runs WHERE id=j.reserved_run_id AND tenant_id=_tenant;
 complete:=run.id IS NOT NULL AND run.finished_at IS NOT NULL AND run.state='success' AND run.started_by=j.actor_id AND run.snapshot_sha256=j.snapshot_sha256 AND private.dpw_hash(run.snapshot)=j.snapshot_sha256 AND private.dpw_hash(run.result)=run.result_sha256 AND (run.result->>'full_final_ack')::boolean IS TRUE AND e.phase='success' AND e.blocking_records=0 AND ((_kind='setup' AND j.snapshot->>'mode'='preview') OR (_kind='publication' AND j.snapshot->>'mode'='prepare' AND j.snapshot->>'approval_origin'='dpdi_setup_review_v1'));
 RETURN jsonb_build_object('reference',r,'job_id',j.id,'configuration_id',c.id,'availability',CASE WHEN expired THEN 'expired' WHEN stale THEN 'stale' WHEN NOT complete THEN 'incomplete' ELSE 'available' END,'can_decide',NOT expired AND NOT stale AND complete AND r->>'status'='pending','reason',CASE WHEN expired THEN 'Original evidence availability expired or tombstoned.' WHEN stale THEN 'Request/configuration/version evidence is no longer current.' WHEN NOT complete THEN 'Complete successful zero-blocking evidence is required.' ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION public.decide_api_token_principal_classification(_request_id uuid, _approve boolean, _decision_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_actor uuid:=auth.uid(); v_request public.api_token_principal_requests%ROWTYPE;
  v_token public.api_tokens%ROWTYPE; v_token_id uuid; v_tenant uuid;
  v_receipt uuid; v_event text;
BEGIN
  IF v_actor IS NULL OR _request_id IS NULL OR _approve IS NULL
    OR _decision_reason IS NULL OR char_length(btrim(_decision_reason)) NOT BETWEEN 10 AND 500
  THEN RAISE EXCEPTION 'invalid classification decision' USING ERRCODE='22023'; END IF;
  SELECT token_id,tenant_id INTO v_token_id,v_tenant
    FROM public.api_token_principal_requests WHERE id=_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'classification request not found' USING ERRCODE='42501'; END IF;
  -- Keep the lock order token then request, the same as request creation.
  SELECT * INTO v_token FROM public.api_tokens t
    WHERE t.id=v_token_id AND t.tenant_id=v_tenant FOR UPDATE;
  SELECT * INTO v_request FROM public.api_token_principal_requests r
    WHERE r.id=_request_id FOR UPDATE;
  IF NOT FOUND OR v_request.status<>'pending' OR v_actor=v_request.requested_by
    OR v_actor IS NOT DISTINCT FROM v_request.subject_user_id
    OR NOT EXISTS (SELECT 1 FROM public.tenant_members m
      WHERE m.tenant_id=v_request.tenant_id AND m.user_id=v_actor AND m.active
        AND m.role='tenant_admin'::public.tenant_role)
  THEN RAISE EXCEPTION 'independent active checker required' USING ERRCODE='42501'; END IF;
  IF v_token.id IS NULL OR v_token.tenant_id IS DISTINCT FROM v_request.tenant_id THEN
    RAISE EXCEPTION 'token changed before decision' USING ERRCODE='42501'; END IF;
  IF _approve AND (v_token.principal_kind<>'unclassified' OR v_token.revoked_at IS NOT NULL
    OR (v_token.expires_at IS NOT NULL AND v_token.expires_at<=now()))
  THEN RAISE EXCEPTION 'token changed before decision' USING ERRCODE='42501'; END IF;
  IF _approve AND (
    (v_request.requested_kind='user_delegated' AND NOT EXISTS (
      SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=v_request.tenant_id
        AND m.user_id=v_request.subject_user_id AND m.active))
    OR (v_request.requested_kind='tenant_machine' AND NOT EXISTS (
      SELECT 1 FROM public.api_service_principals p WHERE p.id=v_request.service_principal_id
        AND p.tenant_id=v_request.tenant_id AND p.active)))
  THEN RAISE EXCEPTION 'designated subject is no longer active' USING ERRCODE='42501'; END IF;
  v_event:=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END;
  IF _approve THEN
    UPDATE public.api_tokens SET principal_kind=v_request.requested_kind,
      subject_user_id=v_request.subject_user_id,
      service_principal_id=v_request.service_principal_id
    WHERE id=v_request.token_id AND tenant_id=v_request.tenant_id;
  END IF;
  UPDATE public.api_token_principal_requests
    SET status=v_event,decided_by=v_actor,decided_at=now(),decision_reason=btrim(_decision_reason)
    WHERE id=v_request.id;
  INSERT INTO public.api_token_principal_decision_audit(
    request_id,tenant_id,token_id,event,actor_id,principal_kind,
    subject_user_id,service_principal_id,owner_approval_ref,evidence_ref)
  VALUES (v_request.id,v_request.tenant_id,v_request.token_id,v_event,v_actor,v_request.requested_kind,
    v_request.subject_user_id,v_request.service_principal_id,v_request.owner_approval_ref,v_request.evidence_ref)
  RETURNING id INTO v_receipt;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (v_actor,v_request.tenant_id,'tenant','api_token.principal.'||v_event,'api_token',v_request.token_id::text,
    jsonb_build_object('request_id',v_request.id,'decision_receipt_id',v_receipt,
      'kind',v_request.requested_kind,'owner_approval_ref',v_request.owner_approval_ref));
  RETURN jsonb_build_object('request_id',v_request.id,'status',v_event,'decision_receipt_id',v_receipt);
END
$function$

CREATE OR REPLACE FUNCTION public.tg_recon_result_active_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.recon_runs%ROWTYPE;
BEGIN
  SELECT * INTO r FROM public.recon_runs WHERE id=NEW.run_id AND tenant_id=NEW.tenant_id FOR SHARE;
  IF NOT FOUND OR EXISTS (SELECT 1 FROM public.recon_schedule_runs a WHERE a.recon_run_id=r.id
    AND (a.status='failed' OR (a.status='running' AND (r.status<>'running' OR a.lease_expires_at<=clock_timestamp())))) THEN
    RAISE EXCEPTION 'run is no longer accepting processing results' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.complete_recon_execution(_tenant_id uuid, _run_id uuid, _claim_id uuid, _commit_id uuid, _matches jsonb, _exceptions jsonb, _stats jsonb, _groups jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE r public.recon_runs%ROWTYPE;receipt jsonb;g jsonb;native uuid;used uuid[]:=ARRAY[]::uuid[];bound jsonb:='[]';item jsonb;
 predecessor public.recon_exceptions%ROWTYPE;comments jsonb;carried jsonb;
BEGIN
 SELECT * INTO r FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND run_by=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_owned_run_required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rs:'||_tenant_id::text||':'||r.definition_id::text,0));
 -- Serialize before result submission; existing ef8 admission/hash/commit receipt
 -- remains the authoritative writer and lost-ACK provenance, unchanged.
 PERFORM private.rs_validate_prepared_execution(_tenant_id,_run_id);
 receipt:=public.complete_recon_run_atomic(_tenant_id,_run_id,_commit_id,r.definition_snapshot,
  r.approved_revision_id,r.approved_revision_number,r.approved_revision_sha256,_matches,_exceptions,_stats);
 FOR g IN SELECT value FROM jsonb_array_elements(_groups) LOOP
  native:=NULL;
  IF g->>'match_status'='matched' THEN
   item:=_matches->((g->>'ordinal')::integer);
   SELECT id INTO native FROM public.recon_matches WHERE run_id=_run_id AND tenant_id=_tenant_id AND NOT(id=ANY(used))
   AND members=item->'members' AND rule_id IS NOT DISTINCT FROM item->>'rule_id' AND cardinality=item->>'cardinality'
   ORDER BY id LIMIT 1;
  ELSIF g->>'match_status'='break' THEN
   item:=_exceptions->((g->>'ordinal')::integer);
   SELECT id INTO native FROM public.recon_exceptions WHERE run_id=_run_id AND tenant_id=_tenant_id AND NOT(id=ANY(used))
   AND payload=item->'payload' AND reason=item->>'reason' AND side IS NOT DISTINCT FROM item->>'side'
   ORDER BY id LIMIT 1;
  END IF;
  IF native IS NULL THEN RAISE EXCEPTION 'rs.native_group_binding_unavailable' USING ERRCODE='PT409';END IF;
  used:=array_append(used,native);bound:=bound||jsonb_build_array(g||jsonb_build_object('native_id',native));
 END LOOP;
 PERFORM private.rs_finalize(_tenant_id,_run_id,_claim_id,receipt,bound);
 -- Only metadata is inherited. Matching failures, workflow closure, assignment,
 -- approval, financial write-off and resolution are NEVER inferred/carried.
 FOR carried IN SELECT value FROM jsonb_array_elements(private.rs_carry_candidates(_tenant_id,_run_id)) LOOP
  SELECT * INTO predecessor FROM public.recon_exceptions WHERE id=(carried->>'source_case_id')::uuid
   AND tenant_id=_tenant_id AND run_id=(carried->>'source_run_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_predecessor_read_required' USING ERRCODE='42501';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'author_id',author_id,'internal',internal) ORDER BY created_at,id),'[]') INTO comments
   FROM public.break_comments WHERE tenant_id=_tenant_id AND exception_id=predecessor.id;
  IF cardinality(predecessor.labels)>0 THEN
   PERFORM public.apply_exception_workflow_atomic(_tenant_id,ARRAY[(carried->>'new_case_id')::uuid],jsonb_build_object('labels',to_jsonb(predecessor.labels)),NULL,true);
  END IF;
  PERFORM private.rs_carry_event(_tenant_id,_run_id,(carried->>'new_case_id')::uuid,predecessor.id,to_jsonb(predecessor.labels),comments);
 END LOOP;
 RETURN receipt||jsonb_build_object('phase','completed','actor_id',auth.uid(),'input_manifest',private.rs_receipt(_tenant_id,_run_id)->'manifest','execution_kind','fresh','execution',private.rs_receipt(_tenant_id,_run_id));
END $function$

CREATE OR REPLACE FUNCTION public.get_recon_execution_workspace(_tenant_id uuid, _definition_id uuid, _page integer DEFAULT 0, _page_size integer DEFAULT 50, _run_id uuid DEFAULT NULL::uuid, _search text DEFAULT NULL::text, _status text DEFAULT 'all'::text, _bu_id uuid DEFAULT NULL::uuid, _expected_read_context_signature text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE rows jsonb;current_run jsonb;total bigint;selected public.recon_runs%ROWTYPE;read_context jsonb;
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'read');
 read_context:=public.read_recon_authorized_context(_tenant_id,_definition_id,_bu_id);
 IF _expected_read_context_signature IS NOT NULL AND read_context->>'read_context_signature' IS DISTINCT FROM _expected_read_context_signature
 THEN RAISE EXCEPTION 'rs.authorized_read_context_changed' USING ERRCODE='PT409';END IF;
 IF _page IS NULL OR _page_size IS NULL OR _page NOT BETWEEN 0 AND 1000000 OR _page_size NOT BETWEEN 1 AND 100
 OR length(coalesce(_search,''))>120 OR (_status IN('all','queued','running','completed','failed')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'rs.invalid_history_page' USING ERRCODE='22023';END IF;
 PERFORM 1 FROM public.recon_definitions WHERE tenant_id=_tenant_id AND id=_definition_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_definition_required' USING ERRCODE='42501';END IF;
 SELECT count(*) INTO total FROM public.recon_runs WHERE tenant_id=_tenant_id AND definition_id=_definition_id AND (_status='all' OR status=_status)
 AND (_search IS NULL OR position(lower(_search) IN lower(coalesce(run_uid,'')||' '||id::text))>0);
 -- No rolling 90-day truncation. All retained historical runs remain pageable.
 SELECT coalesce(jsonb_agg(jsonb_build_object('run',to_jsonb(h),'execution',private.rs_receipt(_tenant_id,h.id)) ORDER BY h.started_at DESC,h.id),'[]') INTO rows
 FROM(SELECT * FROM public.recon_runs WHERE tenant_id=_tenant_id AND definition_id=_definition_id AND (_status='all' OR status=_status)
 AND (_search IS NULL OR position(lower(_search) IN lower(coalesce(run_uid,'')||' '||id::text))>0) ORDER BY started_at DESC,id
 LIMIT _page_size OFFSET (_page::bigint*_page_size)) h;
 SELECT * INTO selected FROM public.recon_runs WHERE tenant_id=_tenant_id AND definition_id=_definition_id AND (_run_id IS NULL OR id=_run_id)
 ORDER BY started_at DESC,id LIMIT 1;
 IF _run_id IS NOT NULL AND NOT FOUND THEN RAISE EXCEPTION 'rs.historical_run_not_visible' USING ERRCODE='42501';END IF;
 IF selected.id IS NOT NULL THEN current_run:=jsonb_build_object('run',to_jsonb(selected),'execution',private.rs_receipt(_tenant_id,selected.id),
 'groups',coalesce((SELECT jsonb_agg(g||jsonb_build_object('workflow_status',e.status,'lifecycle_state',e.lifecycle_state,
    'id',g->>'native_id','public_case_id',e.public_case_id,'labels',e.labels,'assignee',e.assignee,
    'allowed_actions',CASE WHEN read_context->'edit_allowed'='true'::jsonb AND NOT EXISTS(
      SELECT 1 FROM jsonb_array_elements(g->'source_rows') sr WHERE private.data_source_child_allows(auth.uid(),_tenant_id,(sr.value->>'data_source_id')::uuid,'view') IS DISTINCT FROM true)
      THEN '["comment","label","accept","rematch","carry_forward","exclude_request"]'::jsonb ELSE '[]'::jsonb END,
    'action_requests',private.rs_read_group_intents(_tenant_id,_definition_id,selected.id,(g->>'native_id')::uuid),
    'match_score',m.score,'confidence',m.confidence,'confidence_model',m.confidence_model,'rule_id',m.rule_id,
    'settlement_status',NULL,'settlement_status_available',false,
    'source_lifecycle',private.rs_lifecycle_source(_tenant_id,selected.id,g->'source_rows')) ORDER BY g->>'match_status',(g->>'ordinal')::integer)
 FROM jsonb_array_elements(private.rs_result_groups(_tenant_id,selected.id)) g
 LEFT JOIN public.recon_exceptions e ON e.id=(g->>'native_id')::uuid AND e.run_id=selected.id AND e.tenant_id=_tenant_id AND g->>'match_status'='break'
 LEFT JOIN public.recon_matches m ON m.id=(g->>'native_id')::uuid AND m.run_id=selected.id AND m.tenant_id=_tenant_id AND g->>'match_status'='matched'),'[]'));END IF;
 RETURN jsonb_build_object('tenant_id',_tenant_id,'definition_id',_definition_id,'authorized_read_context',read_context,'selected_run_id',selected.id,'current',current_run,
 'history',rows,'history_count',total::text,'page',_page,'page_size',_page_size,'has_next',((_page::bigint+1)*_page_size<total),
 'history_complete',((_page::bigint+1)*_page_size>=total),'evidence_tier','persisted_native');
END $function$

CREATE OR REPLACE FUNCTION public.tg_guard_recon_run_approved_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE v public.recon_definition_approved_versions%ROWTYPE;
BEGIN
 v:=private.recon_run_bound_approved_version(NEW.tenant_id,NEW.definition_id,NEW.run_by);
 NEW.approved_revision_id:=v.id;
 NEW.approved_revision_number:=v.version_number;
 NEW.approved_revision_sha256:=v.snapshot_sha256;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.recon_run_bound_approved_version(_tenant uuid, _definition uuid, _actor uuid)
 RETURNS recon_definition_approved_versions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth', 'extensions'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE; v public.recon_definition_approved_versions%ROWTYPE;
 q public.recon_definition_governance_requests%ROWTYPE;
BEGIN
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Reconciliation scope unavailable' USING ERRCODE='23503'; END IF;
 IF d.retired_at IS NOT NULL OR d.status='archived' THEN
   RAISE EXCEPTION 'Reconciliation is not executable' USING ERRCODE='23514';
 END IF;
 IF auth.role()='authenticated' AND (_actor IS NULL OR _actor IS DISTINCT FROM auth.uid()) THEN
   RAISE EXCEPTION 'Run actor must match caller' USING ERRCODE='42501';
 END IF;
 IF d.access_mode='legacy_passthrough' AND d.governance_state='legacy_unreviewed' THEN RETURN NULL; END IF;
 IF auth.role() NOT IN ('authenticated','service_role') OR auth.role() IS NULL
    OR _actor IS NULL OR _actor IS DISTINCT FROM auth.uid()
    OR NOT private.recon_authoritative_access_decision_as(_actor,d.id,'run') THEN
   RAISE EXCEPTION 'Reconciliation run not authorized' USING ERRCODE='42501';
 END IF;
 IF (d.governance_state='development_draft' AND d.environment='development')
    OR (d.governance_state='staging_copy' AND d.environment IN ('development','staging'))
    OR (d.governance_state='legacy_mapped' AND d.access_mode='mapped_exact') THEN
   -- Development and governed historical mapping are not fabricated approvals.
   RETURN NULL;
 END IF;
 IF d.governance_state NOT IN ('approved_locked','edit_request_pending')
    OR d.environment<>'production' OR d.status<>'active' THEN
   RAISE EXCEPTION 'Reconciliation is not executable' USING ERRCODE='23514';
 END IF;
 SELECT * INTO v FROM public.recon_definition_approved_versions
 WHERE tenant_id=_tenant AND parent_definition_id=_definition ORDER BY version_number DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'Approved revision unavailable' USING ERRCODE='23514'; END IF;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=v.request_id;
 IF NOT FOUND OR q.tenant_id IS DISTINCT FROM _tenant OR q.parent_definition_id IS DISTINCT FROM _definition
    OR q.request_kind IS DISTINCT FROM 'promotion' OR q.status IS DISTINCT FROM 'approved'
    OR q.requested_by=v.approved_by OR q.decided_by IS DISTINCT FROM v.approved_by
    OR q.snapshot IS DISTINCT FROM v.snapshot OR q.snapshot_sha256 IS DISTINCT FROM v.snapshot_sha256
    OR v.snapshot IS DISTINCT FROM private.recon_definition_config_snapshot(d)
    OR v.snapshot_sha256 IS DISTINCT FROM encode(extensions.digest(convert_to(v.snapshot::text,'UTF8'),'sha256'),'hex') THEN
   RAISE EXCEPTION 'Approved revision integrity unavailable' USING ERRCODE='23514';
 END IF;
 IF _actor=v.approved_by THEN RAISE EXCEPTION 'Independent run actor required' USING ERRCODE='42501'; END IF;
 RETURN v;
END $function$

CREATE OR REPLACE FUNCTION public.tg_log_recon_run_approval_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v public.recon_definition_approved_versions%ROWTYPE; state text;
BEGIN
 IF NEW.approved_revision_id IS NULL THEN
   SELECT governance_state INTO state FROM public.recon_definitions WHERE id=NEW.definition_id AND tenant_id=NEW.tenant_id;
   INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
   VALUES(NEW.run_by,NEW.tenant_id,'workspace','recon.run.created.unapproved','recon_run',NEW.id::text,
     jsonb_build_object('definition_id',NEW.definition_id,'governance_state',state));
   RETURN NEW;
 END IF;
 SELECT * INTO v FROM public.recon_definition_approved_versions
 WHERE id=NEW.approved_revision_id AND tenant_id=NEW.tenant_id AND parent_definition_id=NEW.definition_id;
 IF NOT FOUND OR v.version_number IS DISTINCT FROM NEW.approved_revision_number
   OR v.snapshot_sha256 IS DISTINCT FROM NEW.approved_revision_sha256 THEN
   RAISE EXCEPTION 'Run approval binding unavailable' USING ERRCODE='23514';
 END IF;
 INSERT INTO public.recon_definition_run_version_snapshots(tenant_id,recon_definition_id,recon_run_id,
   approved_version_number,approved_snapshot_sha256,approved_request_id,approved_by)
 VALUES(NEW.tenant_id,NEW.definition_id,NEW.id,v.version_number,v.snapshot_sha256,v.request_id,v.approved_by);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(NEW.run_by,NEW.tenant_id,'workspace','recon.run.created.approved','recon_run',NEW.id::text,
   jsonb_build_object('definition_id',NEW.definition_id,'approved_version',v.version_number,
   'approved_sha256',v.snapshot_sha256,'approved_by',v.approved_by,'request_id',v.request_id));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fail_recon_execution(_tenant_id uuid, _run_id uuid, _claim_id uuid, _error_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE r public.recon_runs%ROWTYPE;changed integer;
BEGIN
 SELECT * INTO r FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND run_by=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_owned_run_required' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rs:'||_tenant_id::text||':'||r.definition_id::text,0));
 PERFORM private.recon_atomic_admit(_tenant_id,_run_id);PERFORM private.rs_actor(_tenant_id,r.definition_id,'run');
 UPDATE public.recon_runs SET status='failed',error=_error_code,completed_at=clock_timestamp()
 WHERE id=_run_id AND tenant_id=_tenant_id AND run_by=auth.uid() AND status='running' AND NOT(stats ? '_atomic_completion');
 GET DIAGNOSTICS changed=ROW_COUNT;IF changed<>1 THEN RAISE EXCEPTION 'rs.failure_state_not_confirmed' USING ERRCODE='PT409';END IF;
 PERFORM private.rs_fail(_tenant_id,_run_id,_claim_id,_error_code);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(auth.uid(),_tenant_id,'workspace','recon.execution.failed','recon_run',_run_id::text,jsonb_build_object('claim_id',_claim_id,'error_code',_error_code,'result_complete',false));
 RETURN jsonb_build_object('run_id',_run_id,'status','failed');
END $function$

CREATE OR REPLACE FUNCTION private.rs_record_lifecycle(_tenant uuid, _run uuid, _side text, _ordinal integer, _facet text, _proof uuid, _key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;a uuid;b private.rs_source_bindings%ROWTYPE;proof private.rs_source_attestations%ROWTYPE;
 att private.rs_attachments%ROWTYPE;prior private.rs_lifecycle_requests%ROWTYPE;event private.rs_lifecycle_events%ROWTYPE;
 lineage jsonb;u public.workspace_data_source_uploads%ROWTYPE;row_item jsonb;profile jsonb;state text;ack text;evidence_at timestamptz;intent jsonb;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE run_id=_run AND tenant_id=_tenant;
 IF NOT FOUND OR _ordinal IS NULL OR _ordinal<0 OR _key IS NULL OR (_facet IN('affirmation','settlement')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'rs.lifecycle_scope_invalid' USING ERRCODE='22023';END IF;
 a:=private.rs_actor(_tenant,q.definition_id,'edit');
 PERFORM pg_advisory_xact_lock(hashtextextended('rs-lifecycle:'||_tenant::text||':'||a::text||':'||_key::text,0));
 intent:=jsonb_build_object('run_id',_run,'side_id',_side,'ordinal',_ordinal,'facet',_facet,'proof_id',_proof);
 SELECT * INTO prior FROM private.rs_lifecycle_requests WHERE tenant_id=_tenant AND actor_id=a AND request_key=_key;
 IF FOUND THEN IF prior.intent IS DISTINCT FROM intent THEN RAISE EXCEPTION 'rs.lifecycle_request_key_conflict' USING ERRCODE='PT409';END IF;
  SELECT * INTO event FROM private.rs_lifecycle_events WHERE id=prior.event_id;
  RETURN to_jsonb(event)||jsonb_build_object('authenticated_source',true,'request_replay',true,'request_actor_id',a);END IF;
 SELECT * INTO att FROM private.rs_attachments WHERE run_id=_run AND side_id=_side;
 IF NOT FOUND OR NOT(att.selected_ordinals @> jsonb_build_array(_ordinal)) THEN RAISE EXCEPTION 'rs.lifecycle_input_membership_unavailable' USING ERRCODE='42501';END IF;
 lineage:=att.row_lineage->_ordinal;
 SELECT * INTO proof FROM private.rs_source_attestations WHERE proof_id=_proof AND upload_id=(lineage->>'upload_id')::uuid;
 IF NOT FOUND OR proof.provenance->>'state' IS DISTINCT FROM 'authenticated_native_source'
 OR (proof.provenance->>'producer_source_sha256' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'rs.authenticated_source_proof_required' USING ERRCODE='42501';END IF;
 SELECT * INTO b FROM private.rs_source_bindings WHERE binding_id=proof.binding_id AND tenant_id=_tenant AND definition_id=q.definition_id AND side_id=_side AND data_source_id=att.data_source_id;
 IF NOT FOUND OR b.qualification->>'state' IS DISTINCT FROM 'native_qualified'
 OR (b.qualification->>'producer_source_sha256' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'rs.lifecycle_binding_unqualified' USING ERRCODE='42501';END IF;
 SELECT payload->'policy'->'lifecycle_profiles'->_side INTO profile FROM private.rs_events WHERE run_id=_run AND kind='request_admitted';
 IF profile IS NULL OR profile='null'::jsonb THEN SELECT payload->'profile' INTO profile FROM private.rs_events WHERE run_id=_run
  AND kind='original_source_attested' AND payload->>'proof_id'=_proof::text;END IF;
 IF profile->>'id' IS DISTINCT FROM b.profile_id OR profile->>'version' IS DISTINCT FROM b.profile_version
 OR private.data_source_child_allows(a,_tenant,att.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'rs.pinned_lifecycle_profile_or_source_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=proof.upload_id AND tenant_id=_tenant AND data_source_id=att.data_source_id;
 IF NOT FOUND OR proof.rows_sha256 IS DISTINCT FROM encode(sha256(convert_to(u.rows::text,'UTF8')),'hex')
 THEN RAISE EXCEPTION 'rs.source_acknowledgement_hash_mismatch' USING ERRCODE='PT409';END IF;
 row_item:=u.rows->((lineage->>'ordinal')::integer);
 state:=row_item->>(b.fields->_facet->>'state_field');ack:=row_item->>(b.fields->_facet->>'ack_id_field');
 evidence_at:=(row_item->>(b.fields->_facet->>'ack_at_field'))::timestamptz;
 IF (_facet='affirmation' AND state IN('affirmed','rejected') OR _facet='settlement' AND state IN('settled','failed')) IS DISTINCT FROM true
 OR ack IS NULL OR length(ack) NOT BETWEEN 1 AND 200 OR evidence_at IS NULL OR evidence_at>proof.authenticated_at OR evidence_at>clock_timestamp()
 THEN RAISE EXCEPTION 'rs.positive_authenticated_acknowledgement_required' USING ERRCODE='42501';END IF;
 -- No deadline can select state='failed'. State comes only from the authenticated
 -- immutable source row. Manual workflow closure/matching has no setter here.
 INSERT INTO private.rs_lifecycle_events(run_id,tenant_id,side_id,effective_ordinal,facet,state,source_binding_id,proof_id,source_ack_id,evidence_at,actor_id)
 VALUES(_run,_tenant,_side,_ordinal,_facet,state,b.binding_id,_proof,ack,evidence_at,a)
 ON CONFLICT(run_id,side_id,effective_ordinal,facet,proof_id) DO NOTHING;
 SELECT * INTO event FROM private.rs_lifecycle_events WHERE run_id=_run AND side_id=_side AND effective_ordinal=_ordinal AND facet=_facet AND proof_id=_proof;
 INSERT INTO private.rs_lifecycle_requests VALUES(_tenant,a,_key,intent,event.id);
 INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,a,'lifecycle_source_acknowledged',jsonb_build_object('event_id',event.id,'facet',_facet,'state',state,
   'source_binding_id',b.binding_id,'source_ack_id',ack,'proof_id',_proof,'profile_id',b.profile_id,'profile_version',b.profile_version));
 RETURN to_jsonb(event)||jsonb_build_object('authenticated_source',true,'request_replay',false,'request_actor_id',a);
END $function$

CREATE OR REPLACE FUNCTION public.recover_expired_recon_schedule_leases(_limit integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE s public.recon_schedules%ROWTYPE; a public.recon_schedule_runs%ROWTYPE; recovered integer:=0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' OR _limit IS NULL OR _limit NOT BETWEEN 1 AND 100 THEN
    RAISE EXCEPTION 'bounded service recovery required' USING ERRCODE='42501';
  END IF;
  FOR s IN SELECT schedule.* FROM public.recon_schedules schedule WHERE EXISTS (
    SELECT 1 FROM public.recon_schedule_runs attempt WHERE attempt.schedule_id=schedule.id
      AND attempt.status='running' AND attempt.lease_expires_at<=clock_timestamp())
    ORDER BY schedule.id LIMIT _limit FOR UPDATE SKIP LOCKED LOOP
    FOR a IN SELECT * FROM public.recon_schedule_runs WHERE schedule_id=s.id AND status='running'
      AND lease_expires_at<=clock_timestamp() FOR UPDATE LOOP
      UPDATE public.recon_schedule_runs SET status='failed',finished_at=now(),error='lease_expired',lease_expires_at=NULL,
        retry_after=CASE WHEN a.attempt<a.max_attempts AND s.enabled AND a.schedule_revision=s.schedule_revision
          THEN now()+make_interval(secs=>s.retry_backoff_seconds*(2^(a.attempt-1))::integer) END WHERE id=a.id;
      UPDATE public.recon_runs SET status='failed',error='Schedule execution lease expired',completed_at=now()
        WHERE id=a.recon_run_id AND tenant_id=a.tenant_id AND status='running';
      INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
        VALUES(NULL,a.tenant_id,'workspace','system.recon.schedule.run.lease_expired','recon_schedule',s.id,
          jsonb_build_object('schedule_run_id',a.id,'recon_run_id',a.recon_run_id,'attempt',a.attempt));
      recovered:=recovered+1;
    END LOOP;
  END LOOP;
  RETURN recovered;
END $function$

CREATE OR REPLACE FUNCTION public.defer_recon_schedule_retry(_run_id bigint, _tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE s public.recon_schedules%ROWTYPE; a public.recon_schedule_runs%ROWTYPE; schedule_id_value uuid; cancel_retry boolean;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'service retry required' USING ERRCODE='42501'; END IF;
  SELECT schedule_id INTO schedule_id_value FROM public.recon_schedule_runs WHERE id=_run_id AND tenant_id=_tenant_id;
  SELECT * INTO s FROM public.recon_schedules WHERE id=schedule_id_value AND tenant_id=_tenant_id FOR UPDATE;
  SELECT * INTO a FROM public.recon_schedule_runs WHERE id=_run_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND OR a.status<>'failed' OR a.superseded_by_id IS NOT NULL OR a.retry_after IS NULL THEN RETURN; END IF;
  cancel_retry:=NOT s.enabled OR a.schedule_revision IS DISTINCT FROM s.schedule_revision OR EXISTS (
    SELECT 1 FROM public.recon_definitions d WHERE d.id=s.definition_id AND (d.retired_at IS NOT NULL OR d.status='archived'));
  UPDATE public.recon_schedule_runs SET retry_claimed_at=now(),retry_after=CASE WHEN NOT cancel_retry THEN now()+interval '5 minutes' END WHERE id=a.id;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(NULL,_tenant_id,'workspace',CASE WHEN cancel_retry THEN 'system.recon.schedule.retry.cancelled' ELSE 'system.recon.schedule.retry.deferred' END,
      'recon_schedule',s.id,jsonb_build_object('schedule_run_id',a.id));
END $function$

CREATE OR REPLACE FUNCTION public.get_recon_run_result_status_counts(_tenant_id uuid, _run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
 SET row_security TO 'on'
AS $function$
DECLARE
  definition_id uuid;
  match_groups bigint;
  exception_items bigint;
  buckets jsonb;
BEGIN
  IF _tenant_id IS NULL OR _run_id IS NULL THEN
    RAISE EXCEPTION 'tenant and run are required' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_members m
    WHERE m.tenant_id=_tenant_id AND m.user_id=auth.uid() AND m.active) THEN RETURN NULL; END IF;
  SELECT r.definition_id INTO definition_id
  FROM public.recon_runs r WHERE r.tenant_id = _tenant_id AND r.id = _run_id;
  IF definition_id IS NULL OR NOT public.user_can_access_recon(auth.uid(), definition_id, 'read') THEN
    RETURN NULL;
  END IF;
  SELECT count(*) INTO match_groups FROM public.recon_matches m
    WHERE m.tenant_id = _tenant_id AND m.run_id = _run_id;
  WITH categorized AS (
    SELECT CASE
      WHEN e.payload->>'disposition' = 'keyless_input' THEN 'invalid_key'
      WHEN CASE WHEN jsonb_typeof(private.recon_result_missing_sides(e.payload)) = 'array' THEN jsonb_array_length(private.recon_result_missing_sides(e.payload)) > 0 ELSE false END THEN 'missing'
      WHEN e.payload->>'rule_kind' = 'unique' THEN 'duplicate'
      WHEN jsonb_typeof(e.payload->'key') = 'string' AND jsonb_typeof(e.payload->'sides') = 'object' THEN 'partial'
      WHEN e.payload IS NULL OR e.payload = '{}'::jsonb THEN 'unavailable'
      ELSE 'other' END AS status_bucket
    FROM public.recon_exceptions e WHERE e.tenant_id = _tenant_id AND e.run_id = _run_id
  ), totals AS (
    SELECT status_bucket,count(*) AS item_count FROM categorized GROUP BY status_bucket
  )
  SELECT (SELECT count(*) FROM categorized), jsonb_build_object(
    'partial',COALESCE((SELECT item_count FROM totals WHERE status_bucket='partial'),0),
    'missing',COALESCE((SELECT item_count FROM totals WHERE status_bucket='missing'),0),
    'duplicate',COALESCE((SELECT item_count FROM totals WHERE status_bucket='duplicate'),0),
    'invalid_key',COALESCE((SELECT item_count FROM totals WHERE status_bucket='invalid_key'),0),
    'other',COALESCE((SELECT item_count FROM totals WHERE status_bucket='other'),0),
    'unavailable',COALESCE((SELECT item_count FROM totals WHERE status_bucket='unavailable'),0)
  ) INTO exception_items,buckets;
  RETURN jsonb_build_object('run_id', _run_id, 'match_groups', match_groups,
    'exception_items', exception_items, 'exception_buckets', buckets,
    'semantics', jsonb_build_object('match','persisted recon_matches groups',
      'partial','exception items with persisted key and sides, excluding missing, duplicate and keyless markers',
      'missing','exception items with a non-empty persisted missing_sides array',
      'duplicate','exception items with persisted rule_kind unique',
      'invalid_key','exception items with persisted disposition keyless_input',
      'other','non-empty legacy payload not classified by the markers above',
      'unavailable','exception items with no usable payload', 'workflow_status_is_separate',true));
END;
$function$

CREATE OR REPLACE FUNCTION private.rs_lifecycle_source(_tenant uuid, _run uuid, _source_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;profile jsonb;policy jsonb;v jsonb;att private.rs_attachments%ROWTYPE;row_item jsonb;ordinal integer;
 result jsonb:='[]';events jsonb;fields jsonb;observed timestamptz:=clock_timestamp();native_timing jsonb;artifact_state jsonb;arrival timestamptz;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE run_id=_run AND tenant_id=_tenant;IF NOT FOUND THEN RETURN '[]';END IF;
 PERFORM private.rs_actor(_tenant,q.definition_id,'read');
 SELECT payload->'policy' INTO policy FROM private.rs_events WHERE run_id=_run AND kind='request_admitted';
 FOR v IN SELECT value FROM jsonb_array_elements(_source_rows) LOOP
  ordinal:=coalesce((v->>'effective_ordinal')::integer,(v->>'ordinal')::integer);
  artifact_state:=private.rs_artifact_read_state(_tenant,_run,v->>'side_id');
  row_item:=NULL;arrival:=NULL;
  IF artifact_state->'available'='true'::jsonb THEN
   SELECT * INTO att FROM private.rs_attachments WHERE run_id=_run AND side_id=v->>'side_id';row_item:=att.rows->ordinal;arrival:=att.arrival_at;
  ELSE
   SELECT arrival_at INTO arrival FROM private.rs_attachments WHERE run_id=_run AND side_id=v->>'side_id';
  END IF;
  profile:=policy->'lifecycle_profiles'->(v->>'side_id');
  IF profile IS NULL OR profile='null'::jsonb THEN SELECT payload->'profile' INTO profile FROM private.rs_events WHERE run_id=_run
   AND kind='original_source_attested' AND payload->'profile'->>'id'='approved-mapping-lifecycle:'||(v->>'side_id') ORDER BY occurred_at DESC LIMIT 1;END IF;
  fields:=profile->'date_fields';
  SELECT coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('authenticated_source',true) ORDER BY e.recorded_at,e.id),'[]') INTO events
   FROM private.rs_lifecycle_events e WHERE e.run_id=_run AND e.side_id=v->>'side_id' AND e.effective_ordinal=ordinal;
  native_timing:=NULL;
  IF profile->>'id' IS NOT NULL AND profile->>'version' IS NOT NULL AND profile->>'affirmation_cutoff_at' IS NOT NULL AND profile->>'settlement_due_at' IS NOT NULL THEN
   native_timing:=jsonb_build_object('profile_id',profile->>'id','profile_version',profile->>'version','observed_at',observed,'qualified_native_observation',true,
    'affirmation_deadline',CASE WHEN observed<(profile->>'affirmation_cutoff_at')::timestamptz THEN 'not_due' WHEN observed=(profile->>'affirmation_cutoff_at')::timestamptz THEN 'at_cutoff' ELSE 'past_due' END,
    'settlement_deadline',CASE WHEN observed<(profile->>'settlement_due_at')::timestamptz THEN 'not_due' WHEN observed=(profile->>'settlement_due_at')::timestamptz THEN 'at_cutoff' ELSE 'past_due' END,
    'evidence_timings',coalesce((SELECT jsonb_object_agg(id::text,CASE WHEN evidence_at>(profile->>'affirmation_cutoff_at')::timestamptz THEN 'late' ELSE 'on_time' END)
     FROM private.rs_lifecycle_events WHERE run_id=_run AND side_id=v->>'side_id' AND effective_ordinal=ordinal AND facet='affirmation'),'{}'));
  END IF;
  result:=result||jsonb_build_array(jsonb_build_object('side_id',v->>'side_id','source_row_id',v->>'source_row_id',
   'profile',CASE WHEN profile->>'id' IS NOT NULL AND profile->>'version' IS NOT NULL THEN profile ELSE NULL END,
   'observed_at',observed,'native_timing',native_timing,'events',events,'trade_date',row_item->>(fields->>'trade_date'),'value_date',row_item->>(fields->>'value_date'),
   'business_date',coalesce(row_item->>(fields->>'business_date'),row_item->>(policy->'date_fields'->(v->>'side_id')->>(policy->>'date_basis'))),
   'original_source_record',row_item,'artifact_read',artifact_state,'arrival_at',arrival));
 END LOOP;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.record_recon_lifecycle_evidence(_tenant_id uuid, _run_id uuid, _side_id text, _effective_ordinal integer, _facet text, _proof_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE result jsonb;upload uuid;
BEGIN
 PERFORM 1 FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_lifecycle_run_required' USING ERRCODE='42501';END IF;
 result:=private.rs_record_lifecycle(_tenant_id,_run_id,_side_id,_effective_ordinal,_facet,_proof_id,_request_key);
 -- The purpose returns only an event, never provider secrets or arbitrary state.
 IF result->'request_replay' IS DISTINCT FROM 'true'::jsonb THEN
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(auth.uid(),_tenant_id,'workspace','recon.lifecycle.source_evidence','recon_run',_run_id::text,result);
 END IF;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.decide_public_break_write_off(_tenant_id uuid, _request_id uuid, _exception_id uuid, _recon_id uuid, _approver_id uuid, _decision text, _decision_note text, _token_id uuid, _idempotency_key text, _request_hash text)
 RETURNS TABLE(request_id uuid, exception_id uuid, decision_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  req public.break_write_off_requests%ROWTYPE;
  decision record;
  token public.api_tokens%ROWTYPE;
  body jsonb;
  changed integer;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'break_target_mismatch'; END IF;
  SELECT * INTO token FROM public.api_tokens WHERE id=_token_id AND tenant_id=_tenant_id FOR SHARE;
  IF NOT FOUND OR token.revoked_at IS NOT NULL OR (token.expires_at IS NOT NULL AND token.expires_at<=now())
    OR token.scopes IS NULL OR (token.principal_kind='user_delegated' AND token.service_principal_id IS NOT NULL)
    OR NOT ('breaks.write'=ANY(token.scopes) OR '*'=ANY(token.scopes))
    OR (CASE WHEN token.principal_kind='user_delegated' THEN token.subject_user_id ELSE token.created_by END) IS DISTINCT FROM _approver_id THEN
    RAISE EXCEPTION 'break_target_mismatch';
  END IF;
  SELECT * INTO req FROM public.break_write_off_requests WHERE id=_request_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND OR req.exception_id IS DISTINCT FROM _exception_id THEN RAISE EXCEPTION 'break_target_mismatch'; END IF;
  PERFORM 1 FROM public.recon_exceptions e JOIN public.recon_runs r ON r.id=e.run_id AND r.tenant_id=e.tenant_id
    WHERE e.id=_exception_id AND e.tenant_id=_tenant_id AND r.definition_id=_recon_id FOR UPDATE OF e,r;
  IF NOT FOUND OR NOT private.recon_authoritative_access_decision_as(_approver_id,_recon_id,'approve') THEN
    RAISE EXCEPTION 'break_target_mismatch';
  END IF;
  SELECT * INTO decision FROM public.decide_break_write_off(_tenant_id,_request_id,_approver_id,_decision,_decision_note);
  IF NOT FOUND OR decision.request_id IS DISTINCT FROM _request_id OR decision.exception_id IS DISTINCT FROM _exception_id
    OR decision.decision_status IS DISTINCT FROM _decision OR NOT EXISTS(SELECT 1 FROM public.break_write_off_requests stored
      WHERE stored.id=_request_id AND stored.tenant_id=_tenant_id AND stored.exception_id=_exception_id AND stored.status=_decision AND stored.decided_by=_approver_id)
    OR (_decision='approved' AND NOT EXISTS(SELECT 1 FROM public.recon_exceptions WHERE id=_exception_id AND tenant_id=_tenant_id
      AND lifecycle_state='written_off' AND status='resolved' AND write_off_amount=req.amount AND write_off_currency=req.currency
      AND write_off_gl_account=req.gl_account AND write_off_reason=req.reason AND write_off_approved_by=_approver_id AND resolved_by=_approver_id)) THEN
    RAISE EXCEPTION 'break_target_mismatch';
  END IF;
  body:=jsonb_build_object('data',jsonb_build_object('request_id',decision.request_id,'exception_id',decision.exception_id,'decision_status',decision.decision_status));
  INSERT INTO public.audit_log(tenant_id,actor_user_id,scope,action,resource_type,resource_id,context)
    VALUES(_tenant_id,_approver_id,'api','api.break.approve_write_off','recon_exception',_exception_id::text,
      jsonb_build_object('recon_id',_recon_id,'request_id',_request_id,'api_token_id',_token_id,'idempotency_key',_idempotency_key));
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'break_target_mismatch'; END IF;
  PERFORM public.complete_public_api_idempotency(_tenant_id,_token_id,'break:'||_exception_id::text||':approve_write_off',_idempotency_key,_request_hash,200,body);
  RETURN QUERY SELECT decision.request_id,decision.exception_id,decision.decision_status;
END;
$function$

CREATE OR REPLACE FUNCTION public.read_recon_authorized_context(_tenant_id uuid, _definition_id uuid, _bu_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid;definition public.recon_definitions%ROWTYPE;binding jsonb;observed timestamptz:=statement_timestamp();
BEGIN
 actor:=private.rs_actor(_tenant_id,_definition_id,'read');
 SELECT * INTO definition FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_visible_read_definition_required' USING ERRCODE='42501';END IF;
 IF _bu_id IS NOT NULL THEN
  PERFORM 1 FROM public.business_units WHERE id=_bu_id AND tenant_id=_tenant_id AND is_archived IS NOT TRUE;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_visible_bu_context_required' USING ERRCODE='42501';END IF;
 END IF;
 binding:=jsonb_build_object('actor_id',actor,'tenant_id',definition.tenant_id,'definition_id',definition.id,'bu_id',_bu_id,
  'read_allowed',private.recon_run_read_allowed(definition.id,definition.tenant_id) AND private.recon_run_effective_read_allowed(definition.id,definition.tenant_id),
  'run_allowed',private.recon_root_write_allowed(definition.id,definition.tenant_id,'run'),
  'edit_allowed',private.recon_root_write_allowed(definition.id,definition.tenant_id,'edit'),
  'definition_access_mode',definition.access_mode,'governance_state',definition.governance_state,
  'environment',definition.environment,'definition_status',definition.status);
 IF binding->'read_allowed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'rs.current_native_read_denied' USING ERRCODE='42501';END IF;
 RETURN binding||jsonb_build_object('protocol','recon_authorized_read_context_v1','read_context_id',gen_random_uuid(),
  'observed_at',observed,'read_context_signature',encode(sha256(convert_to(binding::text,'UTF8')),'hex'),
  'authority','current_native_reconciliation_read','permission_epoch_available',false,'control_epoch_used_as_permission_epoch',false);
END $function$

CREATE OR REPLACE FUNCTION public.guard_break_write_off_binding()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE changed boolean;
BEGIN
  IF NEW.lifecycle_state IS DISTINCT FROM 'written_off' THEN RETURN NEW; END IF;
  IF TG_OP='INSERT' THEN changed:=true;
  ELSE changed:=OLD.lifecycle_state IS DISTINCT FROM NEW.lifecycle_state
    OR (OLD.write_off_amount,OLD.write_off_currency,OLD.write_off_gl_account,OLD.write_off_reason,
      OLD.write_off_approved_by,OLD.write_off_approved_at)
      IS DISTINCT FROM (NEW.write_off_amount,NEW.write_off_currency,NEW.write_off_gl_account,NEW.write_off_reason,
      NEW.write_off_approved_by,NEW.write_off_approved_at);
  END IF;
  IF changed AND NOT EXISTS(
    SELECT 1 FROM public.break_write_off_requests req WHERE req.tenant_id=NEW.tenant_id
      AND req.exception_id=NEW.id AND req.status='approved'
      AND req.xmin::text::bigint=(txid_current()%4294967296)
      AND req.decided_by IS DISTINCT FROM req.requested_by
      AND req.decided_by=NEW.write_off_approved_by AND req.decided_at=NEW.write_off_approved_at
      AND req.amount=NEW.write_off_amount AND req.currency=NEW.write_off_currency
      AND req.gl_account=NEW.write_off_gl_account AND req.reason=NEW.write_off_reason
      AND req.decided_by=NEW.resolved_by AND NEW.status='resolved'
      AND (auth.role()='service_role' OR auth.uid()=req.decided_by)
  ) THEN RAISE EXCEPTION 'Governed write-off approval required' USING ERRCODE='42501'; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.rs_next_owned(_tenant uuid, _definition uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;a uuid:=auth.uid();r public.recon_runs%ROWTYPE;
BEGIN
 IF a IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR private.rlnext_account_allowed(a,NULL) IS DISTINCT FROM true
 OR private.rlnext_account_allowed(a,_tenant) IS DISTINCT FROM true THEN RAISE EXCEPTION 'rs.current_authenticated_dispatch_actor_required' USING ERRCODE='42501';END IF;
 SELECT own.* INTO q FROM private.rs_requests own WHERE own.tenant_id=_tenant AND own.actor_id=a AND own.phase='queued'
 AND (_definition IS NULL OR own.definition_id=_definition)
 AND NOT EXISTS(SELECT 1 FROM private.rs_requests beforeq WHERE beforeq.tenant_id=own.tenant_id AND beforeq.definition_id=own.definition_id
  AND beforeq.phase IN('queued','running') AND (beforeq.created_at,beforeq.run_id)<(own.created_at,own.run_id))
 AND NOT EXISTS(SELECT 1 FROM public.recon_runs active WHERE active.tenant_id=own.tenant_id AND active.definition_id=own.definition_id AND active.status='running')
 ORDER BY own.created_at,own.run_id LIMIT 1;
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',a,'tenant_id',_tenant,'state','no_owned_ready_head');END IF;
 PERFORM private.rs_actor(_tenant,q.definition_id,'run');PERFORM private.recon_atomic_admit(_tenant,q.run_id);
 SELECT * INTO r FROM public.recon_runs WHERE id=q.run_id AND tenant_id=_tenant AND run_by=a;
 RETURN jsonb_build_object('actor_id',a,'tenant_id',q.tenant_id,'definition_id',q.definition_id,'state','owned_ready_head','run_id',r.id,
  'run_uid',r.run_uid,'status',r.status,'phase',q.phase,'input_manifest',q.manifest);
END $function$

CREATE OR REPLACE FUNCTION private.validate_tenant_directory_patch(t tenants, p jsonb)
 RETURNS tenants
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v public.tenants%ROWTYPE; k text;
BEGIN
 IF p IS NULL OR jsonb_typeof(p)<>'object' OR p='{}'::jsonb THEN
   RAISE EXCEPTION 'Invalid tenant change' USING ERRCODE='23514';
 END IF;
 FOR k IN SELECT jsonb_object_keys(p) LOOP
   IF k NOT IN ('name','slug','plan_code','seats','region','term','owner_user_id','custom_domain','ai_enabled') THEN
     RAISE EXCEPTION 'Invalid tenant change' USING ERRCODE='23514';
   END IF;
   IF k IN ('name','slug','plan_code','region','term','owner_user_id','custom_domain')
      AND jsonb_typeof(p->k) NOT IN ('string','null') THEN
     RAISE EXCEPTION 'Invalid tenant change' USING ERRCODE='23514';
   END IF;
 END LOOP;
 IF (p ? 'ai_enabled' AND jsonb_typeof(p->'ai_enabled')<>'boolean')
    OR (p ? 'seats' AND jsonb_typeof(p->'seats') NOT IN ('number','null')) THEN
   RAISE EXCEPTION 'Invalid tenant change' USING ERRCODE='23514';
 END IF;
 v:=jsonb_populate_record(t,p);
 IF (p ? 'name' AND (v.name IS NULL OR length(btrim(v.name)) NOT BETWEEN 2 AND 80))
    OR (p ? 'slug' AND (v.slug IS NULL OR length(v.slug)>40 OR v.slug::text !~ '^[a-z0-9][a-z0-9-]*[a-z0-9]$'))
    OR (p ? 'seats' AND v.seats IS NOT NULL AND (v.seats NOT BETWEEN 1 AND 100000 OR (p->>'seats')::numeric<>v.seats))
    OR (p ? 'term' AND v.term IS NOT NULL AND v.term NOT IN ('monthly','annual','custom'))
    OR (p ? 'plan_code' AND v.plan_code IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.pricing_tiers WHERE code=v.plan_code))
    OR (p ? 'region' AND (v.region IS NULL OR length(btrim(v.region)) NOT BETWEEN 1 AND 40))
    OR (p ? 'region' AND t.residency_locked AND v.region IS DISTINCT FROM t.region)
    OR (p ? 'region' AND cardinality(t.allowed_regions)>0 AND NOT (v.region=ANY(t.allowed_regions)))
    OR (p ? 'custom_domain' AND v.custom_domain IS NOT NULL AND
      (length(v.custom_domain)>120 OR v.custom_domain::text !~ '^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$')) THEN
   RAISE EXCEPTION 'Invalid tenant change' USING ERRCODE='23514';
 END IF;
 IF p ? 'owner_user_id' AND v.owner_user_id IS NOT NULL AND NOT EXISTS(
   SELECT 1 FROM public.tenant_members WHERE tenant_id=t.id AND user_id=v.owner_user_id AND active=true
 ) THEN RAISE EXCEPTION 'Active tenant owner required' USING ERRCODE='23514'; END IF;
 RETURN v;
END $function$

CREATE OR REPLACE FUNCTION public.tg_tenant_directory_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF ROW(NEW.name,NEW.slug,NEW.plan_code,NEW.seats,NEW.region,NEW.term,NEW.owner_user_id,NEW.custom_domain,NEW.ai_enabled)
    IS DISTINCT FROM ROW(OLD.name,OLD.slug,OLD.plan_code,OLD.seats,OLD.region,OLD.term,OLD.owner_user_id,OLD.custom_domain,OLD.ai_enabled) THEN
   NEW.directory_version:=OLD.directory_version+1;
 ELSE NEW.directory_version:=OLD.directory_version;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.decide_tenant_directory_change(_request_id uuid, _decision text, _comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); b private.tenant_directory_change_bindings%ROWTYPE;
 q public.config_change_requests%ROWTYPE; t public.tenants%ROWTYPE; v public.tenants%ROWTYPE; n integer;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR actor IS NULL THEN
   RAISE EXCEPTION 'Tenant change not authorized' USING ERRCODE='42501';
 END IF;
 IF _decision IS NULL OR _decision NOT IN ('approved','rejected') OR length(_comment)>2000 THEN
   RAISE EXCEPTION 'Invalid decision' USING ERRCODE='23514';
 END IF;
 SELECT * INTO b FROM private.tenant_directory_change_bindings WHERE request_id=_request_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Governed request unavailable' USING ERRCODE='42501'; END IF;
 IF actor=b.proposer OR NOT (public.is_platform_admin(actor) OR EXISTS(
   SELECT 1 FROM public.tenant_members WHERE tenant_id=b.tenant_id AND user_id=actor AND active=true AND role='tenant_admin'
 )) THEN RAISE EXCEPTION 'Independent checker required' USING ERRCODE='42501'; END IF;
 -- Same lock order as proposal, and shared serialization for concurrent decisions.
 SELECT * INTO t FROM public.tenants WHERE id=b.tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Tenant unavailable' USING ERRCODE='42501'; END IF;
 SELECT * INTO q FROM public.config_change_requests WHERE id=_request_id FOR UPDATE;
 IF NOT FOUND OR q.status IS DISTINCT FROM 'pending' OR q.resource_type IS DISTINCT FROM 'tenant_directory_change'
   OR q.change_type IS DISTINCT FROM 'update' OR q.tenant_id IS DISTINCT FROM b.tenant_id
   OR q.resource_id IS DISTINCT FROM b.tenant_id OR q.requested_by IS DISTINCT FROM b.proposer
   OR q.after_state IS DISTINCT FROM b.patch OR q.before_state IS DISTINCT FROM b.before_state THEN
   RAISE EXCEPTION 'Governed request unavailable' USING ERRCODE='42501';
 END IF;
 IF _decision='approved' THEN
   IF t.directory_version<>b.base_version THEN RAISE EXCEPTION 'Tenant version changed' USING ERRCODE='40001'; END IF;
   v:=private.validate_tenant_directory_patch(t,b.patch);
   UPDATE public.tenants SET name=v.name,slug=v.slug,plan_code=v.plan_code,seats=v.seats,region=v.region,term=v.term,
     owner_user_id=v.owner_user_id,custom_domain=v.custom_domain,ai_enabled=v.ai_enabled,
     domain_verified_at=CASE WHEN t.custom_domain IS DISTINCT FROM v.custom_domain THEN NULL ELSE t.domain_verified_at END
   WHERE id=b.tenant_id AND directory_version=b.base_version;
   GET DIAGNOSTICS n=ROW_COUNT;
   IF n<>1 THEN RAISE EXCEPTION 'Tenant version changed' USING ERRCODE='40001'; END IF;

   -- Invalidate the current hash-only challenge only when its domain target changes.
   -- Name/plan/other edits preserve the existing challenge byte-for-byte.
   IF t.custom_domain IS DISTINCT FROM v.custom_domain THEN
     DELETE FROM public.tenant_domain_verification WHERE tenant_id=b.tenant_id;
   END IF;
 END IF;
 UPDATE public.config_change_requests SET status=_decision,decided_by=actor,decided_at=now(),decision_reason=_comment,
   applied_at=CASE WHEN _decision='approved' THEN now() ELSE NULL END
 WHERE id=q.id AND status='pending' AND tenant_id=b.tenant_id AND resource_id=b.tenant_id
   AND requested_by=b.proposer AND resource_type='tenant_directory_change';
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Governed request unavailable' USING ERRCODE='42501'; END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,b.tenant_id,'platform',CASE WHEN _decision='approved' THEN 'tenant.change.promoted' ELSE 'tenant.change.rejected' END,
   'tenant',b.tenant_id::text,jsonb_build_object('request_id',q.id,'base_version',b.base_version,'patch',b.patch,'comment',_comment));
 GET DIAGNOSTICS n=ROW_COUNT;
 IF n<>1 THEN RAISE EXCEPTION 'Tenant audit unavailable' USING ERRCODE='23514'; END IF;
 RETURN jsonb_build_object('status',_decision,'applied',CASE WHEN _decision='approved' THEN b.patch ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION public.next_owned_recon_execution(_tenant_id uuid, _definition_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE result jsonb;
BEGIN result:=private.rs_next_owned(_tenant_id,_definition_id);
 IF result->>'run_id' IS NOT NULL THEN PERFORM 1 FROM public.recon_runs WHERE id=(result->>'run_id')::uuid AND tenant_id=_tenant_id AND run_by=auth.uid();
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_dispatch_rlp_denied' USING ERRCODE='42501';END IF;END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.rs_approved_rule_contracts(_snapshot jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s jsonb;r jsonb;name text;domain text;fields jsonb;old jsonb;outv jsonb:='[]';k text;nrl jsonb;ref jsonb;refs jsonb;
BEGIN
 IF jsonb_typeof(_snapshot->'sides') IS DISTINCT FROM 'array' OR jsonb_typeof(_snapshot->'rules') IS DISTINCT FROM 'array'
 THEN RAISE EXCEPTION 'rs.actual_approved_rules_required' USING ERRCODE='22023';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(_snapshot->'sides') LOOP
  fields:='{}';
  FOR r IN SELECT value FROM jsonb_array_elements(_snapshot->'rules') LOOP
   k:=r->>'kind';name:=r->'fields'->>(s->>'side_id');
   IF k='nrl_rule' THEN
    nrl:=r->'params'->'nrl_rule';
    IF jsonb_typeof(nrl) IS DISTINCT FROM 'object' OR (nrl->>'kind' IN('match','rollup')) IS DISTINCT FROM true
    THEN RAISE EXCEPTION 'rs.actual_approved_nrl_ast_required' USING ERRCODE='42501';END IF;
    SELECT coalesce(jsonb_agg(jsonb_build_object('column',x->>'column','domain',CASE WHEN nrl->'match'->'tolerance' IS NOT NULL
      AND (x=nrl->'match'->'left' OR x=nrl->'match'->'right') THEN 'numeric' ELSE 'primitive' END)),'[]') INTO refs
     FROM jsonb_path_query(nrl,'$.** ? (@.side == $side && exists (@.column))',jsonb_build_object('side',s->>'side_id')) x;
    IF nrl->>'kind'='rollup' AND nrl->>'side'=s->>'side_id' THEN refs:=refs||jsonb_build_array(
      jsonb_build_object('column',nrl->>'groupBy','domain','primitive'),jsonb_build_object('column',nrl->'aggregate'->>'column','domain',CASE WHEN nrl->'aggregate'->>'fn'='count' THEN 'primitive' ELSE 'numeric' END));END IF;
    FOR ref IN SELECT value FROM jsonb_array_elements(refs) LOOP
     name:=ref->>'column';IF name IS NULL OR name='' THEN RAISE EXCEPTION 'rs.nrl_expected_field_unavailable' USING ERRCODE='42501';END IF;old:=fields->name;
     fields:=fields||jsonb_build_object(name,jsonb_build_object('name',name,'required',true,'domains',coalesce(old->'domains','[]')||jsonb_build_array(ref->>'domain'),
      'rule_ids',coalesce(old->'rule_ids','[]')||jsonb_build_array(r->>'id'),'rule_kinds',coalesce(old->'rule_kinds','[]')||jsonb_build_array(k),
      'numeric_representation','number_or_exact_decimal_string','date_representation','iso_calendar_date_or_offset_timestamp'));
    END LOOP;
    CONTINUE;
   END IF;
   IF name IS NULL OR name='' THEN CONTINUE;END IF;
   domain:=CASE WHEN k IN('numeric_equals','numeric_tolerance_abs','numeric_tolerance_pct','amount_sign_flip','sum_to_match','many_to_one_sum','one_to_many_sum','roll_up','multiply','value_range') THEN 'numeric'
    WHEN k IN('date_equals','date_tolerance_days','date_within_range','date_age_days','ignore_day_portion') THEN 'date'
    WHEN k IN('case_insensitive_match','trimmed_match','string_contains','string_starts_with','string_ends_with','regex_match','fuzzy_levenshtein','phonetic_soundex','currency_equals') THEN 'string'
    WHEN k='boolean_equals' THEN 'boolean' WHEN k IN('non_null','reference_lookup','conditional_set','multi_pass','quick_fix') THEN 'any'
    WHEN k IN('exact_match','unique','in_set','nrl_rule') THEN 'primitive' ELSE NULL END;
   IF domain IS NULL THEN RAISE EXCEPTION 'rs.approved_rule_registry_semantics_unqualified: %',k USING ERRCODE='42501';END IF;
   old:=fields->name;
   fields:=fields||jsonb_build_object(name,jsonb_build_object('name',name,'required',true,'domains',coalesce(old->'domains','[]')||jsonb_build_array(domain),
    'rule_ids',coalesce(old->'rule_ids','[]')||jsonb_build_array(r->>'id'),'rule_kinds',coalesce(old->'rule_kinds','[]')||jsonb_build_array(k),
    'numeric_representation','number_or_exact_decimal_string','date_representation','iso_calendar_date_or_offset_timestamp'));
  END LOOP;
  outv:=outv||jsonb_build_array(jsonb_build_object('side_id',s->>'side_id','data_source_id',s->>'data_source_id',
   'provenance','approved_rule_contract','contract_version','approved_rule_contract_v1',
   'rules_sha256',encode(sha256(convert_to((_snapshot->'rules')::text,'UTF8')),'hex'),
   'logical_side',s->>'logical_side','logical_side_resolution',CASE WHEN s->>'logical_side' IS NULL THEN 'unique_native_compatible_cohort' ELSE 'approved_explicit' END,
   'fields',coalesce((SELECT jsonb_agg(value ORDER BY key) FROM jsonb_each(fields)),'[]')));
 END LOOP;RETURN outv;
END $function$

CREATE OR REPLACE FUNCTION private.rs_contract_row_allowed(_row jsonb, _contract jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f jsonb;value jsonb;domain text;text_value text;parts text[];parsed timestamptz;day date;
BEGIN
 IF jsonb_typeof(_row) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 FOR f IN SELECT x.value FROM jsonb_array_elements(coalesce(_contract->'fields','[]')) x UNION ALL
  SELECT x.value FROM jsonb_array_elements(coalesce(_contract->'source_declared_fields','[]')) x LOOP
  value:=_row->(f->>'name');
  IF f->'required'='true'::jsonb AND (value IS NULL OR value='null'::jsonb OR value='""'::jsonb) THEN RETURN false;END IF;
  IF value IS NULL OR value='null'::jsonb THEN CONTINUE;END IF;
  IF f->>'json_type' IS NOT NULL AND jsonb_typeof(value) IS DISTINCT FROM f->>'json_type' THEN RETURN false;END IF;
  FOR domain IN SELECT jsonb_array_elements_text(coalesce(f->'domains','[]')) LOOP
   IF domain='any' THEN CONTINUE;
   ELSIF domain='primitive' THEN IF jsonb_typeof(value) NOT IN('string','number','boolean') THEN RETURN false;END IF;
   ELSIF domain='string' THEN IF jsonb_typeof(value) NOT IN('string','number','boolean') THEN RETURN false;END IF;
   ELSIF domain='boolean' THEN IF jsonb_typeof(value) NOT IN('boolean','string','number') THEN RETURN false;END IF;
   ELSIF domain='numeric' THEN
    IF jsonb_typeof(value) NOT IN('string','number') THEN RETURN false;END IF;
    IF jsonb_typeof(value)='number' AND abs((value::text)::numeric)>9007199254740991 THEN RETURN false;END IF;
    text_value:=replace(replace(value#>>'{}',',',''),' ','');
    IF length(text_value)>200 THEN RETURN false;END IF;
    parts:=regexp_match(text_value,'^[+-]?(?:([0-9]+)(?:\.([0-9]*))?|\.([0-9]+))(?:[eE]([+-]?[0-9]+))?$');
    IF parts IS NULL OR length(coalesce(parts[2],parts[3],''))>100 OR length(coalesce(parts[4],''))>4 OR abs(coalesce(parts[4],'0')::integer)>100 THEN RETURN false;END IF;
   ELSIF domain='date' THEN
    IF jsonb_typeof(value)<>'string' THEN RETURN false;END IF;text_value:=value#>>'{}';
    IF text_value !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([Tt][0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?([Zz]|[+-][0-9]{2}:[0-9]{2}))?$' THEN RETURN false;END IF;
    BEGIN day:=substr(text_value,1,10)::date;IF day::text<>substr(text_value,1,10) THEN RETURN false;END IF;
     IF length(text_value)>10 THEN parsed:=text_value::timestamptz;END IF;
    EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN RETURN false;END;
   ELSE RETURN false;END IF;
  END LOOP;
 END LOOP;RETURN true;
END $function$

CREATE OR REPLACE FUNCTION private.rs_select_compatible_logical_side(_tenant uuid, _dataset uuid, _contract jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE d public.data_prep_prepared_datasets%ROWTYPE;u public.workspace_data_source_uploads%ROWTYPE;r public.data_prep_delivery_runs%ROWTYPE;
 actor uuid:=private.dpw_actor(_tenant);side text;indexes integer[];accepted text[]:=ARRAY[]::text[];
BEGIN
 SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=_dataset AND tenant_id=_tenant;
 IF NOT FOUND OR private.dpw_source_allows(actor,_tenant,d.data_source_id,'view') IS DISTINCT FROM true
 OR private.data_prep_pipeline_scope_allows(actor,_tenant,d.pipeline_id,'view') IS DISTINCT FROM true
 OR private.dpw_run_payload_available(d.run_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'rs.current_dataset_scope_required' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=d.run_id AND tenant_id=_tenant;
 SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=d.upload_id AND tenant_id=_tenant AND data_source_id=d.data_source_id;
 IF NOT FOUND OR private.dpw_hash(u.rows) IS DISTINCT FROM d.content_sha256 THEN RAISE EXCEPTION 'rs.dataset_native_hash_changed' USING ERRCODE='42501';END IF;
 FOR side IN SELECT DISTINCT value->>'business_side' FROM jsonb_array_elements(r.snapshot->'feeds') WHERE value->>'business_side' IS NOT NULL LOOP
  indexes:=private.dpw_dataset_indexes(d.id,side);
  IF cardinality(indexes)>0 AND NOT EXISTS(SELECT 1 FROM unnest(indexes) i WHERE NOT private.rs_contract_row_allowed(u.rows->i,_contract))
  THEN accepted:=array_append(accepted,side);END IF;
 END LOOP;
 IF cardinality(accepted)<>1 THEN RAISE EXCEPTION 'rs.unique_approved_rule_compatible_logical_side_required' USING ERRCODE='42501';END IF;
 RETURN accepted[1];
END $function$

CREATE OR REPLACE FUNCTION public.guard_atomic_data_prep_run()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_context text; v_pipeline public.data_prep_pipelines%ROWTYPE;
BEGIN
  GET DIAGNOSTICS v_context = PG_CONTEXT;
  IF TG_OP='INSERT' THEN
    IF current_setting('fvi.data_prep_start',true)='atomic_v1'
      AND v_context ~ 'PL/pgSQL function (public\.)?start_atomic_data_prep_run\(uuid,uuid\) line [0-9]+ at SQL statement'
      AND auth.uid() IS NOT NULL AND NEW.triggered_by=auth.uid() THEN
      SELECT * INTO v_pipeline FROM public.data_prep_pipelines
        WHERE id=NEW.pipeline_id AND tenant_id=NEW.tenant_id FOR UPDATE;
      IF NOT FOUND OR public.can_start_data_prep_run(NEW.tenant_id,NEW.pipeline_id) IS DISTINCT FROM true
        OR NEW.status IS DISTINCT FROM 'running' OR NEW.finished_at IS NOT NULL
      THEN RAISE EXCEPTION 'Pipeline start access is unavailable.' USING ERRCODE='42501'; END IF;
      NEW.execution_protocol := 'atomic_v1';
      NEW.execution_snapshot := jsonb_build_object(
        'source_data_source_id',v_pipeline.source_data_source_id,
        'output_data_source_id',v_pipeline.output_data_source_id,'steps',v_pipeline.steps,
        'dq_rules',v_pipeline.dq_rules,'on_failure',v_pipeline.on_failure);
    ELSE
      NEW.execution_protocol := 'legacy'; NEW.execution_snapshot := NULL;
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.execution_protocol='atomic_v1' THEN
    IF ROW(NEW.id,NEW.tenant_id,NEW.pipeline_id,NEW.triggered_by,NEW.run_uid,NEW.started_at,
      NEW.execution_protocol,NEW.execution_snapshot,NEW.trigger)
      IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.pipeline_id,OLD.triggered_by,OLD.run_uid,OLD.started_at,
      OLD.execution_protocol,OLD.execution_snapshot,OLD.trigger)
      OR OLD.status IS DISTINCT FROM 'running' OR OLD.finished_at IS NOT NULL
      OR NEW.status NOT IN ('success','warn','failed') OR NEW.finished_at IS NULL
      OR auth.uid() IS DISTINCT FROM OLD.triggered_by
      OR current_setting('fvi.data_prep_finish',true) IS DISTINCT FROM OLD.id::text
      OR v_context !~ 'PL/pgSQL function (public\.)?(finalize_data_prep_run\(uuid,uuid,jsonb,integer,jsonb,jsonb,text,jsonb,text,bigint\)|finish_atomic_data_prep_run_failure\(uuid,uuid,text\)) line [0-9]+ at SQL statement'
    THEN RAISE EXCEPTION 'Pipeline run transition is unavailable.' USING ERRCODE='42501'; END IF;
  ELSIF NEW.execution_protocol IS DISTINCT FROM OLD.execution_protocol
    OR NEW.execution_snapshot IS DISTINCT FROM OLD.execution_snapshot THEN
    RAISE EXCEPTION 'Pipeline execution protocol is immutable.' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.start_atomic_data_prep_run(_tenant_id uuid, _pipeline_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_pipeline public.data_prep_pipelines%ROWTYPE; v_run public.data_prep_runs%ROWTYPE;
BEGIN
  SELECT * INTO v_pipeline FROM public.data_prep_pipelines
    WHERE id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL
    OR public.can_start_data_prep_run(_tenant_id,_pipeline_id) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'Pipeline start access is unavailable.' USING ERRCODE='42501'; END IF;
  PERFORM set_config('fvi.data_prep_start','atomic_v1',true);
  INSERT INTO public.data_prep_runs(tenant_id,pipeline_id,triggered_by)
    VALUES(_tenant_id,_pipeline_id,auth.uid()) RETURNING * INTO v_run;
  PERFORM set_config('fvi.data_prep_start','',true);
  RETURN jsonb_build_object('id',v_run.id,'run_uid',v_run.run_uid);
END $function$

CREATE OR REPLACE FUNCTION public.finish_atomic_data_prep_run_failure(_tenant_id uuid, _run_id uuid, _kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_pipeline public.data_prep_pipelines%ROWTYPE; v_run public.data_prep_runs%ROWTYPE;
  v_error text; v_cancel text := 'Run stopped by requester before output publication.';
BEGIN
  IF _kind IS NULL OR _kind NOT IN ('precision','processing','cancel') THEN
    RAISE EXCEPTION 'Pipeline recovery is unavailable.' USING ERRCODE='22023'; END IF;
  SELECT p.* INTO v_pipeline FROM public.data_prep_pipelines p
    JOIN public.data_prep_runs r ON r.pipeline_id=p.id AND r.tenant_id=p.tenant_id
    WHERE r.id=_run_id AND r.tenant_id=_tenant_id FOR UPDATE OF p;
  IF NOT FOUND THEN RAISE EXCEPTION 'Pipeline recovery access is unavailable.' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_run FROM public.data_prep_runs WHERE id=_run_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND OR auth.uid() IS NULL OR v_run.triggered_by IS DISTINCT FROM auth.uid()
    OR public.can_start_data_prep_run(_tenant_id,v_pipeline.id) IS DISTINCT FROM true
    OR v_run.execution_protocol IS DISTINCT FROM 'atomic_v1' THEN
    RAISE EXCEPTION 'Pipeline recovery access is unavailable.' USING ERRCODE='42501'; END IF;
  IF v_run.finished_at IS NULL THEN
    IF v_run.status IS DISTINCT FROM 'running' THEN
      RAISE EXCEPTION 'Pipeline recovery is unavailable.' USING ERRCODE='40001'; END IF;
    v_error := CASE _kind
      WHEN 'precision' THEN 'This numeric transform cannot preserve the value''s precision. Keep the source value as text or reduce its precision explicitly before retrying.'
      WHEN 'cancel' THEN v_cancel ELSE 'Pipeline processing failed. Review the source and configuration before retrying.' END;
    PERFORM set_config('fvi.data_prep_finish',v_run.id::text,true);
    UPDATE public.data_prep_runs SET status='failed',error=v_error,finished_at=now()
      WHERE id=v_run.id AND tenant_id=_tenant_id RETURNING * INTO v_run;
    IF NOT FOUND THEN RAISE EXCEPTION 'Pipeline run update is unavailable.' USING ERRCODE='42501'; END IF;
    PERFORM set_config('fvi.data_prep_finish','',true);
    IF _kind <> 'cancel' AND NOT EXISTS(SELECT 1 FROM public.data_prep_runs r
      WHERE r.tenant_id=_tenant_id AND r.pipeline_id=v_pipeline.id AND r.id<>v_run.id
        AND (r.started_at >= v_run.started_at)) THEN
      UPDATE public.data_prep_pipelines SET last_run_at=now(),last_status='failed',last_error=v_error
        WHERE id=v_pipeline.id AND tenant_id=_tenant_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'Pipeline state update is unavailable.' USING ERRCODE='42501'; END IF;
    END IF;
    INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
      VALUES(auth.uid(),_tenant_id,'workspace',CASE WHEN _kind='cancel' THEN 'data_prep.run.cancelled' ELSE 'data_prep.run' END,
        'data_prep_run',v_run.id::text,jsonb_build_object('pipeline_id',v_pipeline.id,
          'run_uid',v_run.run_uid,'status',v_run.status,'kind',_kind));
  END IF;
  RETURN jsonb_build_object('run_id',v_run.id,'run_uid',v_run.run_uid,'status',v_run.status,
    'rows_in',v_run.rows_in,'rows_out',v_run.rows_out,'dq',v_run.dq_results,'error',v_run.error,
    'cancelled',coalesce(v_run.status='failed' AND v_run.error=v_cancel,false));
END $function$

CREATE OR REPLACE FUNCTION public.guard_tenant_template_marketplace_origin()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE call_context text; install_owner name;
BEGIN
 IF TG_OP='INSERT' AND NEW.source_version_id IS NOT NULL THEN
  GET DIAGNOSTICS call_context = PG_CONTEXT;
  SELECT pg_get_userbyid(proowner) INTO install_owner FROM pg_proc
  WHERE oid='public.install_marketplace_template_atomic(uuid,uuid,uuid,boolean)'::regprocedure;
  IF auth.uid() IS NULL OR NEW.created_by IS DISTINCT FROM auth.uid()
   OR current_user IS DISTINCT FROM install_owner
   OR call_context !~ '(^|\n)PL/pgSQL function public\.install_marketplace_template_atomic\(uuid,uuid,uuid,boolean\) line [0-9]+ at SQL statement(\n|$)' THEN
   RAISE EXCEPTION 'Marketplace origin requires trusted installation' USING ERRCODE='42501';
  END IF;
 ELSIF TG_OP='UPDATE' AND (OLD.source_version_id IS NOT NULL OR NEW.source_version_id IS NOT NULL) THEN
  IF NEW.source_version_id IS DISTINCT FROM OLD.source_version_id
   OR NEW.source_template_id IS DISTINCT FROM OLD.source_template_id
   OR NEW.source_install_id IS DISTINCT FROM OLD.source_install_id
   OR NEW.tenant_id IS DISTINCT FROM OLD.tenant_id
   OR NEW.created_by IS DISTINCT FROM OLD.created_by THEN
   RAISE EXCEPTION 'Marketplace origin cannot be changed' USING ERRCODE='42501';
  END IF;
 END IF;
 -- Draft content is still customizable under the existing lifecycle contract.
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.start_atomic_data_prep_run(_tenant_id uuid, _pipeline_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid(); run_row public.data_prep_runs%ROWTYPE; started jsonb;
BEGIN
 IF actor IS NULL OR _request_key IS NULL THEN
  RAISE EXCEPTION 'An authenticated pipeline request key is required.' USING ERRCODE='22023';
 END IF;
 -- Same pipeline lock/order as original trusted start. Duplicate callers wait;
 -- after a rollback they may start once, after commit they must replay.
 PERFORM 1 FROM public.data_prep_pipelines WHERE id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR public.can_start_data_prep_run(_tenant_id,_pipeline_id) IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'Pipeline start access is unavailable.' USING ERRCODE='42501';
 END IF;
 SELECT * INTO run_row FROM public.data_prep_runs WHERE tenant_id=_tenant_id
 AND pipeline_id=_pipeline_id AND triggered_by=actor AND request_key=_request_key;
 IF FOUND THEN
  IF run_row.execution_protocol IS DISTINCT FROM 'atomic_v1' THEN
   RAISE EXCEPTION 'Pipeline request correlation is unavailable.' USING ERRCODE='42501';
  END IF;
  RETURN jsonb_build_object('id',run_row.id,'run_id',run_row.id,'run_uid',run_row.run_uid,
   'status',run_row.status,'is_new',false,'cancelled',coalesce(run_row.status='failed' AND run_row.finished_at IS NOT NULL AND run_row.error='Run stopped by requester before output publication.',false));
 END IF;
 PERFORM set_config('fvi.data_prep_request_key',_request_key::text,true);
 -- The original two-argument PG_CONTEXT identity establishes protocol/actor.
 started:=public.start_atomic_data_prep_run(_tenant_id,_pipeline_id);
 PERFORM set_config('fvi.data_prep_request_key','',true);
 SELECT * INTO run_row FROM public.data_prep_runs WHERE id=(started->>'id')::uuid
 AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id AND triggered_by=actor
 AND request_key=_request_key AND execution_protocol='atomic_v1';
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Pipeline request correlation was not established.' USING ERRCODE='42501';
 END IF;
 RETURN jsonb_build_object('id',run_row.id,'run_id',run_row.id,'run_uid',run_row.run_uid,
  'status',run_row.status,'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.get_atomic_data_prep_run_by_request(_tenant_id uuid, _pipeline_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE run_row public.data_prep_runs%ROWTYPE; actor uuid:=auth.uid();
BEGIN
 IF actor IS NULL OR _request_key IS NULL THEN
  RAISE EXCEPTION 'An authenticated pipeline request key is required.' USING ERRCODE='22023';
 END IF;
 IF public.can_start_data_prep_run(_tenant_id,_pipeline_id) IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'Pipeline outcome access is unavailable.' USING ERRCODE='42501';
 END IF;
 SELECT * INTO run_row FROM public.data_prep_runs WHERE tenant_id=_tenant_id
 AND pipeline_id=_pipeline_id AND triggered_by=actor AND request_key=_request_key
 AND execution_protocol='atomic_v1';
 IF NOT FOUND THEN RETURN jsonb_build_object('found',false,'is_new',false); END IF;
 RETURN jsonb_build_object('found',true,'id',run_row.id,'run_id',run_row.id,'run_uid',run_row.run_uid,
  'status',run_row.status,'is_new',false,'cancelled',coalesce(run_row.status='failed' AND run_row.finished_at IS NOT NULL AND run_row.error='Run stopped by requester before output publication.',false));
END $function$

CREATE OR REPLACE FUNCTION public.install_marketplace_template_atomic(_tenant_id uuid, _template_id uuid, _version_id uuid, _auto_update boolean DEFAULT false)
 RETURNS tenant_template_installs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
 actor uuid := auth.uid();
 source_row public.mkt_templates%ROWTYPE;
 version_row public.mkt_template_versions%ROWTYPE;
 install_row public.tenant_template_installs%ROWTYPE;
 draft_id uuid;
BEGIN
 IF actor IS NULL OR NOT public.mkt_is_tenant_admin(_tenant_id) THEN
  RAISE EXCEPTION 'Tenant template installation denied' USING ERRCODE='42501';
 END IF;
 -- Match existing marketplace SELECT visibility, including platform-only private access.
 SELECT * INTO source_row FROM public.mkt_templates WHERE id=_template_id FOR UPDATE;
 IF NOT FOUND OR source_row.retired_at IS NOT NULL OR source_row.certification NOT IN ('approved','certified')
 OR (source_row.visibility NOT IN ('public','restricted') AND NOT public.is_platform_admin(actor)) THEN
  RAISE EXCEPTION 'Approved template unavailable' USING ERRCODE='42501';
 END IF;
 IF _version_id IS NULL OR source_row.current_version_id IS DISTINCT FROM _version_id THEN
  RAISE EXCEPTION 'Template version changed; refresh before installing' USING ERRCODE='40001';
 END IF;
 SELECT * INTO version_row FROM public.mkt_template_versions
 WHERE id=_version_id AND template_id=_template_id FOR SHARE;
 IF NOT FOUND OR version_row.status <> 'published' THEN
  RAISE EXCEPTION 'Published template version unavailable' USING ERRCODE='42501';
 END IF;
 INSERT INTO public.tenant_template_installs(tenant_id,template_id,installed_version_id,state,auto_update,installed_by)
 VALUES (_tenant_id,_template_id,_version_id,'installed',_auto_update,actor)
 ON CONFLICT (tenant_id,template_id) DO UPDATE SET
 installed_version_id=EXCLUDED.installed_version_id,state=EXCLUDED.state,
 auto_update=EXCLUDED.auto_update,installed_by=EXCLUDED.installed_by
 RETURNING * INTO install_row;
 INSERT INTO public.tenant_templates(tenant_id,source_install_id,source_template_id,source_version_id,title,spec,status,created_by)
 VALUES (_tenant_id,install_row.id,_template_id,_version_id,source_row.title,version_row.spec,'draft',actor)
 RETURNING id INTO draft_id;
 UPDATE public.mkt_templates SET install_count=install_count+1 WHERE id=_template_id;
 INSERT INTO public.mkt_audit_log(actor_id,tenant_id,entity_type,entity_id,action,after)
 VALUES (actor,_tenant_id,'tenant_template_install',install_row.id,'install',
 jsonb_build_object('template_id',_template_id,'source_version_id',_version_id,'tenant_template_id',draft_id));
 RETURN install_row;
END $function$

CREATE OR REPLACE FUNCTION public.guard_data_prep_run_request_key()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE call_context text; key_text text;
BEGIN
 IF TG_OP='DELETE' THEN
  IF OLD.request_key IS NOT NULL THEN
   RAISE EXCEPTION 'Correlated pipeline runs must be retained.' USING ERRCODE='42501';
  END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' THEN
  IF NEW.request_key IS DISTINCT FROM OLD.request_key THEN
   RAISE EXCEPTION 'Pipeline request correlation is immutable.' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
 END IF;
 GET DIAGNOSTICS call_context=PG_CONTEXT;
 key_text:=current_setting('fvi.data_prep_request_key',true);
 IF key_text IS NOT NULL AND key_text<>''
 AND call_context ~ '(^|\n)PL/pgSQL function public\.start_atomic_data_prep_run\(uuid,uuid,uuid\) line [0-9]+ at assignment(\n|$)'
 AND call_context ~ 'PL/pgSQL function (public\.)?start_atomic_data_prep_run\(uuid,uuid\) line [0-9]+ at SQL statement'
 AND auth.uid() IS NOT NULL AND NEW.triggered_by=auth.uid()
 AND NEW.execution_protocol='atomic_v1' AND NEW.execution_snapshot IS NOT NULL THEN
  IF NEW.request_key IS NOT NULL AND NEW.request_key::text IS DISTINCT FROM key_text THEN
   RAISE EXCEPTION 'Pipeline request correlation is unavailable.' USING ERRCODE='42501';
  END IF;
  NEW.request_key:=key_text::uuid;
 ELSIF NEW.request_key IS NOT NULL THEN
  RAISE EXCEPTION 'Pipeline request correlation requires trusted start.' USING ERRCODE='42501';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.settle_copilot_dispatch(_attempt_id uuid, _tokens_in integer, _tokens_out integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid(); r public.copilot_spend_reservations%ROWTYPE; actual_c numeric; actual_t numeric;
BEGIN
 IF actor IS NULL OR _tokens_in IS NULL OR _tokens_out IS NULL OR _tokens_in<0 OR _tokens_out<0 THEN RAISE EXCEPTION 'copilot.usage_unavailable'; END IF;
 PERFORM pg_advisory_xact_lock(61000,1);
 SELECT * INTO r FROM public.copilot_spend_reservations WHERE id=_attempt_id::text FOR UPDATE;
 IF NOT FOUND OR r.actor_id<>actor OR r.llm_provider_id IS NULL THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 IF r.state='settled' AND r.tokens_in=_tokens_in AND r.tokens_out=_tokens_out THEN RETURN jsonb_build_object('settled',true); END IF;
 IF r.state<>'dispatched' THEN RAISE EXCEPTION 'copilot.settlement_conflict'; END IF;
 actual_t:=_tokens_in::numeric+_tokens_out;
 actual_c:=ceil(_tokens_in::numeric*r.input_rate+_tokens_out::numeric*r.output_rate);
 IF actual_t=0 OR actual_c<=0 THEN RAISE EXCEPTION 'copilot.usage_unavailable'; END IF;
 -- Authenticated reports are NOT a trusted provider attestation. Keep a bound
 -- floor in enforcement, so forged zero/small counters cannot release money.
 UPDATE public.copilot_spend_reservations SET state='settled',tokens_in=_tokens_in,tokens_out=_tokens_out,
   actual_tokens=actual_t,actual_micro_usd=actual_c,accounted_tokens=greatest(bound_tokens,actual_t),
   accounted_micro_usd=greatest(bound_micro_usd,actual_c) WHERE id=r.id;
 IF r.tenant_id IS NOT NULL THEN
   INSERT INTO public.ai_usage_events(tenant_id,user_id,scope,model,tokens_in,tokens_out,cost_usd,meta)
   VALUES(r.tenant_id,actor,'copilot',r.model_key,_tokens_in,_tokens_out,actual_c/1000000,
     jsonb_build_object('copilot_reservation_id',r.id,'pricing_basis',r.pricing_basis,'usage_source','authenticated_report',
       'budget_enforcement','catalog_bound_floor'));
 END IF;
 RETURN jsonb_build_object('settled',true);
END $function$

CREATE OR REPLACE FUNCTION private.fence_copilot_usage()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r public.copilot_spend_reservations%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(61000,1);
 IF TG_OP<>'INSERT' THEN
   IF OLD.scope='copilot' OR OLD.meta ? 'copilot_reservation_id' THEN RAISE EXCEPTION 'copilot.usage_immutable'; END IF;
   IF TG_OP='DELETE' THEN RETURN OLD; END IF;
   IF NEW.scope='copilot' OR NEW.meta ? 'copilot_reservation_id' THEN RAISE EXCEPTION 'copilot.usage_immutable'; END IF;
 END IF;
 IF NEW.meta ? 'copilot_reservation_id' THEN
   IF TG_OP<>'INSERT' OR NEW.meta->>'copilot_reservation_id' IS NULL OR NEW.scope IS DISTINCT FROM 'copilot' THEN
     RAISE EXCEPTION 'copilot.reservation_required'; END IF;
   SELECT * INTO r FROM public.copilot_spend_reservations WHERE id=NEW.meta->>'copilot_reservation_id';
   IF NOT FOUND OR r.state<>'settled' OR r.llm_provider_id IS NULL OR (r.actor_id IS DISTINCT FROM auth.uid() AND NOT (
       auth.role()='service_role' AND current_setting('role',true)='service_role'
       AND EXISTS(SELECT 1 FROM private.public_ai_inference_requests a
         WHERE a.id::text=NEW.meta->>'public_request_id' AND a.id::text=r.id
           AND a.subject_user_id=r.actor_id AND a.tenant_id=r.tenant_id
           AND a.model_catalog_id=r.catalog_id AND a.state='recorded'))) 
     OR NEW.user_id IS DISTINCT FROM r.actor_id OR NEW.tenant_id IS DISTINCT FROM r.tenant_id OR NEW.model IS DISTINCT FROM r.model_key
     OR NEW.tokens_in IS DISTINCT FROM r.tokens_in OR NEW.tokens_out IS DISTINCT FROM r.tokens_out
     OR NEW.cost_usd IS DISTINCT FROM r.actual_micro_usd/1000000 THEN RAISE EXCEPTION 'copilot.reservation_required'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.rs_recon_input_contracts(_tenant uuid, _definition uuid, _revision uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE v public.recon_definition_approved_versions%ROWTYPE;s jsonb;c jsonb;p private.rs_schema_profiles%ROWTYPE;contracts jsonb:='[]';missing jsonb:='[]';expected jsonb;rules_contracts jsonb;rule_contract jsonb;
BEGIN
 PERFORM private.rs_actor(_tenant,_definition,'read');
 SELECT * INTO v FROM public.recon_definition_approved_versions WHERE id=_revision AND tenant_id=_tenant AND parent_definition_id=_definition;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.actual_approved_revision_required' USING ERRCODE='42501';END IF;
 rules_contracts:=private.rs_approved_rule_contracts(v.snapshot);
 FOR s IN SELECT value FROM jsonb_array_elements(v.snapshot->'sides') LOOP
  SELECT value INTO rule_contract FROM jsonb_array_elements(rules_contracts) WHERE value->>'side_id'=s->>'side_id';
  c:=s->'input_contract';
  IF c IS NULL OR c='null'::jsonb THEN
   SELECT x->'input_contract' INTO c FROM jsonb_array_elements(coalesce(v.snapshot->'sources','[]')) x
    WHERE x->>'side_id'=s->>'side_id' AND x->>'data_source_id'=s->>'data_source_id';
  END IF;
  IF c->>'provenance'='approved_rule_contract' THEN
   IF c->>'rules_sha256' IS DISTINCT FROM rule_contract->>'rules_sha256' THEN RAISE EXCEPTION 'rs.frozen_rule_declaration_mismatch' USING ERRCODE='PT409';END IF;
   IF c->'source_schema_profile' IS NOT NULL THEN c:=c->'source_schema_profile';ELSE c:=NULL;END IF;
  END IF;
  IF c IS NULL OR c='null'::jsonb THEN
   contracts:=contracts||jsonb_build_array(rule_contract||jsonb_build_object('approval_bound',true,'approved_revision_id',v.id,'upload_id',s->>'upload_id'));
   CONTINUE;
  END IF;
  SELECT * INTO p FROM private.rs_schema_profiles WHERE tenant_id=_tenant AND data_source_id=(s->>'data_source_id')::uuid
   AND profile_id=(c->>'profile_id')::uuid AND version=c->>'profile_version';
  IF NOT FOUND OR p.qualification->>'state' IS DISTINCT FROM 'native_qualified' OR p.qualification->>'kind' IS DISTINCT FROM 'authoritative_schema_configuration'
   OR (p.qualification->>'producer_source_sha256' ~ '^[0-9a-f]{64}$') IS DISTINCT FROM true THEN RAISE EXCEPTION 'rs.approved_schema_profile_unqualified' USING ERRCODE='42501';END IF;
  expected:=jsonb_build_object('profile_id',p.profile_id,'profile_version',p.version,'logical_side',p.logical_side,'fields',p.fields,'column_mapping',p.column_mapping,
   'schema_sha256',encode(sha256(convert_to(jsonb_build_object('logical_side',p.logical_side,'fields',p.fields,'column_mapping',p.column_mapping)::text,'UTF8')),'hex'));
  IF expected IS DISTINCT FROM c THEN RAISE EXCEPTION 'rs.approved_schema_changed_or_forged' USING ERRCODE='PT409';END IF;
  contracts:=contracts||jsonb_build_array(rule_contract||jsonb_build_object('approval_bound',true,'approved_revision_id',v.id,
   'logical_side',c->'logical_side','logical_side_resolution','approved_explicit','source_declared_fields',c->'fields','source_schema_profile',c,'upload_id',s->>'upload_id'));
 END LOOP;
 RETURN jsonb_build_object('input_contracts',contracts,'missing_contract_sides',missing,'contract_available',jsonb_array_length(missing)=0,
  'reconciliation_feature_enabled',true,'revision_id',v.id,'snapshot_sha256',v.snapshot_sha256);
END $function$

CREATE OR REPLACE FUNCTION public.capture_recon_creation_contracts(_tenant_id uuid, _sides jsonb, _mappings jsonb, _rules jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE s jsonb;mapping jsonb;contract jsonb;declared jsonb;rule_contracts jsonb;result jsonb:='[]';complete boolean:=true;
BEGIN
 PERFORM private.wfm_assert_enabled(_tenant_id,'recons');
 IF jsonb_typeof(_sides) IS DISTINCT FROM 'array' OR jsonb_array_length(_sides) NOT BETWEEN 1 AND 3 OR jsonb_typeof(_mappings) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'rs.creation_schema_scope_invalid' USING ERRCODE='22023';END IF;
 rule_contracts:=private.rs_approved_rule_contracts(jsonb_build_object('sides',_sides,'rules',_rules));
 FOR s IN SELECT value FROM jsonb_array_elements(_sides) LOOP
  PERFORM 1 FROM public.workspace_data_sources WHERE id=(s->>'data_source_id')::uuid AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_creation_source_required' USING ERRCODE='42501';END IF;
  SELECT coalesce(jsonb_object_agg(key,value->>(s->>'side_id')) FILTER(WHERE coalesce(value->>(s->>'side_id'),'')<>''),'{}') INTO mapping FROM jsonb_each(_mappings);
  declared:=private.rs_schema_profile(_tenant_id,(s->>'data_source_id')::uuid,mapping);
  SELECT value INTO contract FROM jsonb_array_elements(rule_contracts) WHERE value->>'side_id'=s->>'side_id';
  IF declared IS NOT NULL THEN contract:=contract||jsonb_build_object('source_declared_fields',declared->'fields','source_schema_profile',declared,
   'logical_side',declared->'logical_side','logical_side_resolution','approved_explicit');END IF;
  contract:=contract||jsonb_build_object('approval_bound',false,'column_mapping',mapping);
  result:=result||jsonb_build_array((s-'input_contract')||jsonb_build_object('column_mapping',mapping,'input_contract',contract,
    'input_contract_state','declared_from_selected_rules'));
 END LOOP;RETURN jsonb_build_object('tenant_id',_tenant_id,'sides',result,'all_contracts_qualified',complete,
 'schema_source','selected_mapping_and_rule_registry_declaration','incoming_rows_used_to_define_expected_schema',false);
END $function$

CREATE OR REPLACE FUNCTION public.read_recon_contract(_tenant_id uuid, _definition_id uuid, _revision_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE;v public.recon_definition_approved_versions%ROWTYPE;contracts jsonb;current_sha text;
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'read');
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_contract_definition_required' USING ERRCODE='42501';END IF;
 SELECT * INTO v FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=_definition_id
 AND (_revision_id IS NULL OR id=_revision_id) ORDER BY version_number DESC LIMIT 1;
 current_sha:=private.rs_current_definition_sha(_tenant_id,_definition_id);
 IF v.id IS NULL THEN RETURN jsonb_build_object('tenant_id',_tenant_id,'definition_id',_definition_id,'approved',false,
 'contract_available',false,'snapshot_sha256',NULL,'expected_definition_sha256',NULL,'current_definition_sha256',current_sha,
 'sides',d.sides,'pins',(SELECT jsonb_agg(jsonb_build_object('side_id',x->>'side_id','upload_id',x->>'upload_id')) FROM jsonb_array_elements(d.sides) x),
 'input_contracts','[]'::jsonb,'reason','approved_revision_unavailable','native_hash_algorithm','sha256_pg_jsonb_text');END IF;
 contracts:=private.rs_recon_input_contracts(_tenant_id,_definition_id,v.id);
 RETURN contracts||jsonb_build_object('tenant_id',_tenant_id,'definition_id',_definition_id,'approved',true,'revision_id',v.id,'revision_number',v.version_number,
 'snapshot_sha256',v.snapshot_sha256,'expected_definition_sha256',v.snapshot_sha256,'current_definition_sha256',current_sha,
 'current_revision',current_sha=v.snapshot_sha256,'approved_snapshot',v.snapshot,'sides',v.snapshot->'sides',
 'pins',(SELECT jsonb_agg(jsonb_build_object('side_id',x->>'side_id','upload_id',x->>'upload_id')) FROM jsonb_array_elements(v.snapshot->'sides') x),
 'native_hash_algorithm','sha256_pg_jsonb_text','historical_approved_snapshot_rewritten',false);
END $function$

CREATE OR REPLACE FUNCTION public.configure_copilot_binding(_tenant_id uuid, _provider_id uuid, _model_catalog_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE l public.llm_providers%ROWTYPE; c public.ai_model_catalog%ROWTYPE; i public.ai_provider_instances%ROWTYPE;
 old_binding jsonb; actor uuid:=auth.uid();
BEGIN
 IF NOT coalesce(private.can_configure_copilot_binding(actor,_tenant_id),false) THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 PERFORM pg_advisory_xact_lock(61000,1);
 SELECT * INTO l FROM public.llm_providers WHERE id=_provider_id FOR UPDATE;
 IF NOT FOUND OR l.tenant_id IS DISTINCT FROM _tenant_id OR l.is_active IS DISTINCT FROM true
   OR l.scope::text IS DISTINCT FROM (CASE WHEN _tenant_id IS NULL THEN 'platform' ELSE 'tenant' END) THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 SELECT * INTO c FROM public.ai_model_catalog WHERE id=_model_catalog_id FOR SHARE;
 IF NOT FOUND OR c.model_key IS DISTINCT FROM l.model OR c.approval_status IS DISTINCT FROM 'approved'
   OR c.availability_status IS NULL OR c.availability_status NOT IN ('available','limited')
   OR c.max_input_tokens IS NULL OR c.max_input_tokens<=0 OR c.max_output_tokens IS NULL OR c.max_output_tokens<=0
   OR c.context_window IS NULL OR c.context_window<=c.max_output_tokens THEN RAISE EXCEPTION 'copilot.binding_required'; END IF;
 SELECT * INTO i FROM public.ai_provider_instances WHERE id=c.provider_instance_id FOR SHARE;
 IF NOT FOUND OR i.tenant_id IS DISTINCT FROM _tenant_id OR i.status IS DISTINCT FROM 'active'
   OR NOT EXISTS(SELECT 1 FROM public.ai_provider_registry WHERE code=i.provider_code AND enabled)
   OR NOT EXISTS(SELECT 1 FROM public.ai_model_pricing WHERE provider_code=i.provider_code AND model_key=c.model_key
     AND active AND currency='USD' AND effective_at<=clock_timestamp() AND (expires_at IS NULL OR expires_at>clock_timestamp())
     AND input_usd_per_1m>0 AND output_usd_per_1m>0
     AND input_usd_per_1m::text NOT IN ('NaN','Infinity','-Infinity') AND output_usd_per_1m::text NOT IN ('NaN','Infinity','-Infinity')) THEN
   RAISE EXCEPTION 'copilot.pricing_unavailable'; END IF;
 IF l.provider_instance_id IS NOT DISTINCT FROM i.id AND l.model_catalog_id IS NOT DISTINCT FROM c.id THEN
   RETURN jsonb_build_object('configured',true,'model_catalog_id',c.id); END IF;
 old_binding:=jsonb_build_object('provider_instance_id',l.provider_instance_id,'model_catalog_id',l.model_catalog_id);
 UPDATE public.llm_providers SET provider_instance_id=i.id,model_catalog_id=c.id WHERE id=l.id;
 INSERT INTO public.security_events(tenant_id,user_id,event_type,severity,context)
 VALUES(_tenant_id,actor,'copilot.provider_binding_configured','info',jsonb_build_object('llm_provider_id',l.id,'before',old_binding,
   'provider_instance_id',i.id,'model_catalog_id',c.id,'model_key',c.model_key));
 RETURN jsonb_build_object('configured',true,'model_catalog_id',c.id);
END $function$

CREATE OR REPLACE FUNCTION public.install_marketplace_template_atomic(_tenant_id uuid, _template_id uuid, _version_id uuid, _auto_update boolean, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
 actor uuid:=auth.uid();
 request_row public.marketplace_install_requests%ROWTYPE;
 install_row public.tenant_template_installs%ROWTYPE;
 execution_version uuid;
BEGIN
 IF actor IS NULL OR public.mkt_is_tenant_admin(_tenant_id) IS DISTINCT FROM true THEN
  RAISE EXCEPTION 'Tenant template installation denied' USING ERRCODE='42501';
 END IF;
 IF _request_key IS NULL OR _tenant_id IS NULL OR _template_id IS NULL OR _auto_update IS NULL THEN
  RAISE EXCEPTION 'An installation request key and exact payload are required' USING ERRCODE='22023';
 END IF;
 -- Unique insertion waits for a concurrent transaction claiming the same UUID.
 -- If that transaction fails, its claim rolls back and this caller can proceed.
 INSERT INTO public.marketplace_install_requests(request_id,actor_id,tenant_id,template_id,auto_update)
 VALUES (_request_key,actor,_tenant_id,_template_id,_auto_update)
 ON CONFLICT (request_id) DO NOTHING;
 SELECT * INTO STRICT request_row FROM public.marketplace_install_requests
 WHERE request_id=_request_key FOR UPDATE;
 IF request_row.actor_id IS DISTINCT FROM actor OR request_row.tenant_id IS DISTINCT FROM _tenant_id THEN
  RAISE EXCEPTION 'Installation request is unavailable for this caller' USING ERRCODE='42501';
 END IF;
 IF request_row.template_id IS DISTINCT FROM _template_id
 OR request_row.auto_update IS DISTINCT FROM _auto_update THEN
  RAISE EXCEPTION 'Installation request key belongs to a different payload' USING ERRCODE='22023';
 END IF;
 IF request_row.result IS NOT NULL THEN
  -- Reauthorize caller above, but never rerun mutable source selection on replay.
  RETURN request_row.result;
 END IF;
 -- Version is server-derived execution detail, never part of replay intent.
 -- Derive under the same source lock held by the legacy RPC through completion.
 SELECT current_version_id INTO execution_version FROM public.mkt_templates
 WHERE id=_template_id FOR UPDATE;
 IF NOT FOUND THEN
  RAISE EXCEPTION 'Approved template unavailable' USING ERRCODE='42501';
 END IF;
 execution_version:=COALESCE(_version_id,execution_version);
 -- Preserve the exact trusted four-argument origin frame; no duplicated writes.
 install_row:=public.install_marketplace_template_atomic(_tenant_id,_template_id,execution_version,_auto_update);
 UPDATE public.marketplace_install_requests SET version_id=install_row.installed_version_id,result=to_jsonb(install_row),completed_at=now()
 WHERE request_id=_request_key;
 RETURN to_jsonb(install_row);
END $function$

CREATE OR REPLACE FUNCTION public.assert_recon_document_exception_link_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  document_tenant uuid;
  exception_tenant uuid;
BEGIN
  SELECT d.tenant_id INTO document_tenant
  FROM public.aidp_documents d WHERE d.id = NEW.document_id;
  SELECT e.tenant_id INTO exception_tenant
  FROM public.recon_exceptions e WHERE e.id = NEW.exception_id;

  IF document_tenant IS NULL OR exception_tenant IS NULL
     OR document_tenant <> NEW.tenant_id OR exception_tenant <> NEW.tenant_id THEN
    RAISE EXCEPTION 'document and exception must exist and belong to the selected tenant'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION private.connector_worker_scope_allows_actor_v1(_actor uuid, _schedule uuid, _action text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE v_schedule public.data_source_schedules%ROWTYPE; v_role text; v_registry uuid;
BEGIN
  IF _actor IS NULL OR _schedule IS NULL
     OR _action NOT IN ('run','view') THEN RETURN false; END IF;
  SELECT * INTO v_schedule FROM public.data_source_schedules WHERE id=_schedule;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT tm.role::text INTO v_role FROM public.tenant_members tm
    WHERE tm.tenant_id=v_schedule.tenant_id AND tm.user_id=_actor AND tm.active=true;
  IF v_role IS NULL THEN RETURN false; END IF;
  IF v_schedule.access_mode='legacy_passthrough' THEN
    RETURN _action='view' OR v_role IN ('tenant_admin','tenant_analyst'); END IF;
  IF v_schedule.access_mode='unmapped_pending' THEN RETURN v_role='tenant_admin'; END IF;
  IF v_schedule.access_mode<>'mapped_exact' THEN RETURN false; END IF;
  SELECT id INTO v_registry FROM public.data_resource_registry
    WHERE tenant_id=v_schedule.tenant_id AND resource_type='data_source_schedule'
      AND data_source_schedule_id=_schedule;
  RETURN v_registry IS NOT NULL AND private.data_resource_shadow_allows_actor(_actor,v_registry,_action);
END $function$

CREATE OR REPLACE FUNCTION public.create_recon_execution_from_prepared(_tenant_id uuid, _definition_id uuid, _business_date date, _bindings jsonb, _request_key uuid, _expected_definition_sha256 text, _policy_id uuid, _policy_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE intent jsonb;prior jsonb;created jsonb;r public.recon_runs%ROWTYPE;pins jsonb;
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'run');
 PERFORM pg_advisory_xact_lock(hashtextextended('rs:'||_tenant_id::text||':'||_definition_id::text,0));
 SELECT jsonb_agg(jsonb_build_object('side_id',value->>'side_id','upload_id',value->>'upload_id') ORDER BY value->>'side_id') INTO pins FROM jsonb_array_elements(_bindings);
 intent:=jsonb_build_object('input_kind','prepared_bound','policy_id',_policy_id,'policy_version',_policy_version,'pins',pins,
  'bindings',_bindings,'business_date',_business_date,'expected_definition_sha256',_expected_definition_sha256);
 prior:=private.rs_prior(_tenant_id,_definition_id,_request_key,intent);IF prior IS NOT NULL THEN RETURN prior;END IF;
 created:=public.dpw_create_recon_run(_tenant_id,_definition_id,_business_date,_bindings,_request_key,_expected_definition_sha256);
 IF created->'is_new' IS DISTINCT FROM 'true'::jsonb OR created->>'actor_id' IS DISTINCT FROM auth.uid()::text OR created->>'tenant_id' IS DISTINCT FROM _tenant_id::text
 THEN RAISE EXCEPTION 'rs.new_native_prepared_request_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=(created->>'run_id')::uuid AND tenant_id=_tenant_id AND definition_id=_definition_id AND run_by=auth.uid();
 IF NOT FOUND OR r.status<>'queued' OR r.started_at<transaction_timestamp() OR r.completed_at IS NOT NULL
 OR r.approved_revision_sha256 IS DISTINCT FROM _expected_definition_sha256 THEN RAISE EXCEPTION 'rs.queued_same_transaction_prepared_creator_required' USING ERRCODE='PT409';END IF;
 -- Stores the SAME native Run ID/UID and exact native logical-side output indexes.
 RETURN private.rs_store(_tenant_id,r.id,_request_key,intent);
END $function$

CREATE OR REPLACE FUNCTION private.connector_worker_grant_v1(_worker_token text, _schedule_id uuid)
 RETURNS connector_worker_vault_grants_v1
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE t public.api_tokens%ROWTYPE; g public.connector_worker_vault_grants_v1%ROWTYPE;
 s public.data_source_schedules%ROWTYPE; v public.app_vault_secrets%ROWTYPE; digest text;
BEGIN
 IF _worker_token IS NULL OR length(_worker_token)<24 OR length(_worker_token)>4096 OR _worker_token LIKE 'sb_secret_%'
   OR _worker_token ~ '^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$' THEN RAISE EXCEPTION 'connector.worker_denied'; END IF;
 SELECT * INTO t FROM public.api_tokens WHERE token_hash=encode(extensions.digest(convert_to(_worker_token,'UTF8'),'sha256'),'hex') FOR SHARE;
 IF NOT FOUND OR t.principal_kind<>'tenant_machine' OR t.subject_user_id IS NOT NULL OR t.service_principal_id IS NULL
   OR t.revoked_at IS NOT NULL OR (t.expires_at IS NOT NULL AND t.expires_at<=clock_timestamp())
   OR NOT coalesce('connectors.run'=ANY(t.scopes),false) THEN RAISE EXCEPTION 'connector.worker_denied'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.api_service_principals WHERE id=t.service_principal_id AND tenant_id=t.tenant_id AND active) THEN RAISE EXCEPTION 'connector.worker_denied'; END IF;
 SELECT * INTO g FROM public.connector_worker_vault_grants_v1 WHERE service_principal_id=t.service_principal_id AND schedule_id=_schedule_id
   AND tenant_id=t.tenant_id AND active AND purpose='connector.pull.v1' AND expires_at>clock_timestamp() FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'connector.grant_unavailable'; END IF;
 SELECT * INTO s FROM public.data_source_schedules WHERE id=g.schedule_id AND tenant_id=g.tenant_id FOR SHARE;
 IF NOT FOUND OR NOT s.enabled THEN RAISE EXCEPTION 'connector.grant_stale'; END IF;
 SELECT * INTO v FROM public.app_vault_secrets WHERE id=g.secret_id FOR SHARE;
 digest:=encode(extensions.digest(convert_to(jsonb_build_object('config',s.config,'transformation',s.transformation,'type',s.connector_type,'source',s.data_source_id)::text,'UTF8'),'sha256'),'hex');
 IF (g.secret_id IS NULL AND s.config->>'credential_secret_name' IS NOT NULL) OR (g.secret_id IS NOT NULL AND (v.id IS NULL OR v.scope::text<>'tenant' OR v.tenant_id IS DISTINCT FROM g.tenant_id OR v.secret_class::text<>'integration_token'
   OR v.name IS DISTINCT FROM s.config->>'credential_secret_name' OR v.version IS DISTINCT FROM g.secret_version
   OR v.fingerprint_sha256 IS DISTINCT FROM g.secret_fingerprint)) OR digest<>g.config_sha256
   OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=g.tenant_id AND user_id=g.authorized_by AND active AND role::text='tenant_admin')
   OR NOT coalesce(private.connector_worker_scope_allows_actor_v1(g.authorized_by,s.id,'run'),false) THEN RAISE EXCEPTION 'connector.grant_stale'; END IF;
 RETURN g;
END $function$

CREATE OR REPLACE FUNCTION private.rs_resolve_prepared_bindings(_tenant uuid, _definition uuid, _business_date date, _datasets jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');d public.recon_definitions%ROWTYPE;v public.recon_definition_approved_versions%ROWTYPE;
 contracts jsonb;s jsonb;c jsonb;dataset public.data_prep_prepared_datasets%ROWTYPE;bindings jsonb:='[]';approved jsonb;chosen_policy private.rs_policies%ROWTYPE;policies integer;logical_side text;
BEGIN
 IF _business_date IS NULL OR jsonb_typeof(_datasets) IS DISTINCT FROM 'object' OR _datasets='{}'::jsonb
 THEN RAISE EXCEPTION 'rs.explicit_prepared_side_selection_required' USING ERRCODE='22023';END IF;
 v:=private.recon_run_bound_approved_version(_tenant,_definition,actor);
 IF v.id IS NULL THEN RAISE EXCEPTION 'rs.actual_native_approved_snapshot_required' USING ERRCODE='42501';END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 contracts:=private.rs_recon_input_contracts(_tenant,_definition,v.id);
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(_datasets) k WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v.snapshot->'sides') x WHERE x->>'side_id'=k))
 THEN RAISE EXCEPTION 'rs.unconfigured_prepared_side' USING ERRCODE='22023';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(v.snapshot->'sides') LOOP
  IF _datasets ? (s->>'side_id') THEN
   SELECT value INTO c FROM jsonb_array_elements(contracts->'input_contracts') WHERE value->>'side_id'=s->>'side_id';
   IF c IS NULL OR jsonb_typeof(c->'fields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'rs.approved_prepared_side_domains_unavailable' USING ERRCODE='42501';END IF;
   SELECT * INTO dataset FROM public.data_prep_prepared_datasets WHERE id=(_datasets->>(s->>'side_id'))::uuid AND tenant_id=_tenant;
   IF NOT FOUND OR dataset.data_source_id::text IS DISTINCT FROM s->>'data_source_id'
    OR (s ? 'upload_id' AND s->>'upload_id' IS NOT NULL AND s->>'upload_id' IS DISTINCT FROM dataset.upload_id::text)
   THEN RAISE EXCEPTION 'rs.prepared_source_or_approved_pin_conflict' USING ERRCODE='42501';END IF;
   logical_side:=coalesce(c->>'logical_side',private.rs_select_compatible_logical_side(_tenant,dataset.id,c));
   bindings:=bindings||jsonb_build_array(jsonb_build_object('kind','prepared_dataset','side_id',s->>'side_id','data_source_id',s->>'data_source_id','dataset_id',dataset.id,
    'pipeline_id',dataset.pipeline_id,'pipeline_version',dataset.pipeline_version,'upload_id',dataset.upload_id,'logical_side',logical_side));
  ELSE
   IF s->>'upload_id' IS NULL THEN RAISE EXCEPTION 'rs.required_counterpart_unpinned_no_latest_fallback' USING ERRCODE='42501';END IF;
   bindings:=bindings||jsonb_build_array(jsonb_build_object('kind','fixed_upload','side_id',s->>'side_id','data_source_id',s->>'data_source_id','upload_id',s->>'upload_id'));
  END IF;
 END LOOP;
 -- Exact authoritative intersection: current published dataset, pipeline version,
 -- independent release, source RLP, logical-side output indexes and typed row hash.
 approved:=private.dpw_recon_preflight(_tenant,_definition,_business_date,bindings,v.snapshot_sha256);
 IF approved->>'snapshot_sha256' IS DISTINCT FROM v.snapshot_sha256 OR approved->'reconciliation_feature_enabled' IS DISTINCT FROM 'true'::jsonb
 THEN RAISE EXCEPTION 'rs.actual_native_preflight_required' USING ERRCODE='42501';END IF;
 SELECT count(*) INTO policies FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=_definition
 AND policy->>'business_date'=_business_date::text AND qualification->>'state'='native_qualified'
 AND qualification->>'approved_definition_sha256'=v.snapshot_sha256;
 IF policies>1 THEN RAISE EXCEPTION 'rs.unambiguous_approved_native_execution_policy_required' USING ERRCODE='42501';END IF;
 IF policies=1 THEN SELECT * INTO chosen_policy FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=_definition AND policy->>'business_date'=_business_date::text
 AND qualification->>'state'='native_qualified' AND qualification->>'approved_definition_sha256'=v.snapshot_sha256;
 ELSE chosen_policy.policy_id:=v.id;chosen_policy.version:=v.version_number::text;chosen_policy.policy:=jsonb_build_object('business_date',_business_date,'policy_kind','approved_native_input_binding');END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',d.id,'business_date',_business_date,'revision_id',v.id,'revision_number',v.version_number,
 'expected_definition_sha256',v.snapshot_sha256,'approved_snapshot_sha256',v.snapshot_sha256,'input_bindings',bindings,
 'execution_policy',jsonb_build_object('policy_id',chosen_policy.policy_id,'policy_version',chosen_policy.version,'business_date',chosen_policy.policy->>'business_date','policy_kind',chosen_policy.policy->>'policy_kind'),
 'compatibility','native_current_published_contract_hash_checked','approved_snapshot',approved->'snapshot');
END $function$

CREATE OR REPLACE FUNCTION public.enroll_connector_worker_grant_v1(_service_principal_id uuid, _schedule_id uuid, _secret_id uuid, _expires_at timestamp with time zone, _owner_approval_ref text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid(); s public.data_source_schedules%ROWTYPE; v public.app_vault_secrets%ROWTYPE; g uuid;
BEGIN
 IF actor IS NULL OR length(btrim(_owner_approval_ref))<8 OR _expires_at<=clock_timestamp() OR NOT isfinite(_expires_at) THEN RAISE EXCEPTION 'connector.capability_denied'; END IF;
 SELECT * INTO s FROM public.data_source_schedules WHERE id=_schedule_id FOR SHARE;
 IF NOT FOUND OR NOT s.enabled OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=s.tenant_id AND user_id=actor AND active AND role::text='tenant_admin')
   OR NOT coalesce(private.connector_worker_scope_allows_actor_v1(actor,s.id,'run'),false) THEN RAISE EXCEPTION 'connector.capability_denied'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.api_service_principals WHERE id=_service_principal_id AND tenant_id=s.tenant_id AND active) THEN RAISE EXCEPTION 'connector.capability_denied'; END IF;
 SELECT * INTO v FROM public.app_vault_secrets WHERE id=_secret_id FOR SHARE;
 IF (_secret_id IS NULL AND s.config->>'credential_secret_name' IS NOT NULL) OR (_secret_id IS NOT NULL AND (v.id IS NULL OR v.scope::text<>'tenant' OR v.tenant_id IS DISTINCT FROM s.tenant_id OR v.secret_class::text<>'integration_token'
   OR v.name IS DISTINCT FROM s.config->>'credential_secret_name')) THEN RAISE EXCEPTION 'connector.capability_denied'; END IF;
 INSERT INTO public.connector_worker_vault_grants_v1(tenant_id,service_principal_id,schedule_id,secret_id,purpose,config_sha256,secret_version,
   secret_fingerprint,authorized_by,owner_approval_ref,active,expires_at)
 VALUES(s.tenant_id,_service_principal_id,s.id,v.id,'connector.pull.v1',encode(extensions.digest(convert_to(jsonb_build_object('config',s.config,'transformation',s.transformation,'type',s.connector_type,'source',s.data_source_id)::text,'UTF8'),'sha256'),'hex'),
   v.version,v.fingerprint_sha256,actor,_owner_approval_ref,true,_expires_at) RETURNING id INTO g;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,s.tenant_id,'tenant','connector.worker.grant.enrolled','connector_worker_grant',g::text,jsonb_build_object('purpose','connector.pull.v1','service_principal_id',_service_principal_id,'schedule_id',s.id,'owner_approval_ref',_owner_approval_ref));
 RETURN g;
END $function$

CREATE OR REPLACE FUNCTION public.revoke_connector_worker_grant_v1(_grant_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid(); g public.connector_worker_vault_grants_v1%ROWTYPE;
BEGIN
 SELECT * INTO g FROM public.connector_worker_vault_grants_v1 WHERE id=_grant_id FOR UPDATE;
 IF NOT FOUND OR actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=g.tenant_id AND user_id=actor AND active AND role::text='tenant_admin') THEN RAISE EXCEPTION 'connector.capability_denied'; END IF;
 UPDATE public.connector_worker_vault_grants_v1 SET active=false WHERE id=g.id;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,g.tenant_id,'tenant','connector.worker.grant.revoked','connector_worker_grant',g.id::text,jsonb_build_object('service_principal_id',g.service_principal_id));
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.claim_connector_background_v1(_worker_token text, _schedule_id uuid, _occurrence text, _job_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE g public.connector_worker_vault_grants_v1%ROWTYPE; a public.connector_worker_attempts_v1%ROWTYPE;
 s public.data_source_schedules%ROWTYPE; v public.app_vault_secrets%ROWTYPE; j public.workflow_api_jobs%ROWTYPE;
 t public.api_tokens%ROWTYPE; actor uuid; snapshot jsonb;
BEGIN
 g:=private.connector_worker_grant_v1(_worker_token,_schedule_id);
 PERFORM pg_advisory_xact_lock(hashtextextended('connector.worker.v1:'||g.id::text,0));
 SELECT * INTO a FROM public.connector_worker_attempts_v1 WHERE grant_id=g.id AND occurrence=_occurrence FOR UPDATE;
 IF FOUND THEN
   IF a.job_id IS DISTINCT FROM _job_id THEN RAISE EXCEPTION 'connector.replay_conflict'; END IF;
   IF _job_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.workflow_api_jobs job_check JOIN public.api_tokens token_check ON token_check.id=job_check.token_id
     JOIN public.tenant_members member_check ON member_check.user_id=job_check.actor_user_id AND member_check.tenant_id=job_check.tenant_id AND member_check.active
     WHERE job_check.id=_job_id AND job_check.tenant_id=g.tenant_id AND job_check.resource_id=g.schedule_id AND job_check.actor_user_id=a.actor_user_id
       AND token_check.principal_kind='user_delegated' AND token_check.subject_user_id=job_check.actor_user_id AND token_check.revoked_at IS NULL
       AND (token_check.expires_at IS NULL OR token_check.expires_at>clock_timestamp()) AND coalesce('connectors.run'=ANY(token_check.scopes),false)
       AND coalesce(private.connector_worker_scope_allows_actor_v1(job_check.actor_user_id,g.schedule_id,'run'),false)) THEN RAISE EXCEPTION 'connector.job_denied'; END IF;
   IF a.state='completed' THEN RETURN jsonb_build_object('state','completed','result',a.result); END IF;
   RAISE EXCEPTION 'connector.outcome_uncertain';
 END IF;
 IF _job_id IS NOT NULL THEN
   SELECT * INTO j FROM public.workflow_api_jobs WHERE id=_job_id AND tenant_id=g.tenant_id AND resource_id=_schedule_id FOR SHARE;
   IF NOT FOUND OR j.status<>'running' OR j.job_kind<>'connector_run' OR j.token_id IS NULL OR j.actor_user_id IS NULL THEN RAISE EXCEPTION 'connector.job_denied'; END IF;
   SELECT * INTO t FROM public.api_tokens WHERE id=j.token_id FOR SHARE;
   IF NOT FOUND OR t.tenant_id<>g.tenant_id OR t.principal_kind<>'user_delegated' OR t.subject_user_id IS DISTINCT FROM j.actor_user_id
     OR t.revoked_at IS NOT NULL OR (t.expires_at IS NOT NULL AND t.expires_at<=clock_timestamp())
     OR NOT coalesce('connectors.run'=ANY(t.scopes),false)
     OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=g.tenant_id AND user_id=j.actor_user_id AND active)
     OR NOT coalesce(private.connector_worker_scope_allows_actor_v1(j.actor_user_id,_schedule_id,'run'),false) THEN RAISE EXCEPTION 'connector.job_denied'; END IF;
   IF EXISTS(SELECT 1 FROM public.connector_worker_attempts_v1 WHERE job_id=j.id AND state='dispatched') THEN RAISE EXCEPTION 'connector.outcome_uncertain'; END IF;
   actor:=j.actor_user_id;
 END IF;
 SELECT * INTO s FROM public.data_source_schedules WHERE id=_schedule_id;
 SELECT * INTO v FROM public.app_vault_secrets WHERE id=g.secret_id;
 snapshot:=jsonb_build_object('grant_id',g.id,'service_principal_id',g.service_principal_id,'tenant_id',g.tenant_id,
   'schedule_id',g.schedule_id,'secret_id',g.secret_id,'purpose','connector.pull.v1','config_sha256',g.config_sha256,
   'authorized_by',g.authorized_by,'actor_user_id',actor,'job_id',_job_id,'secret_version',g.secret_version);
 INSERT INTO public.connector_worker_attempts_v1(grant_id,occurrence,job_id,actor_user_id,state,grant_snapshot)
 VALUES(g.id,_occurrence,_job_id,actor,'dispatched',snapshot) RETURNING * INTO a;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,g.tenant_id,'tenant',CASE WHEN actor IS NULL THEN 'cron.connector.worker.dispatch.claimed' ELSE 'connector.worker.dispatch.claimed' END,'connector_worker_attempt',a.id::text,snapshot);
 RETURN jsonb_build_object('state','dispatched','attempt_id',a.id,'snapshot',snapshot,'connector_type',s.connector_type,
   'config',s.config,'transformation',s.transformation,'encrypted_secret',CASE WHEN g.secret_id IS NULL THEN NULL ELSE jsonb_build_object('ciphertext',v.ciphertext,'iv',v.iv,
   'auth_tag',v.auth_tag,'wrapped_dek',v.wrapped_dek,'kek_provider',v.kek_provider,'kek_ref',v.kek_ref) END);
END $function$

CREATE OR REPLACE FUNCTION private.rs_prepared_replay(_tenant uuid, _definition uuid, _key uuid, _business_date date, _datasets jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'read');q private.rs_requests%ROWTYPE;r public.recon_runs%ROWTYPE;selected jsonb;m jsonb;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE tenant_id=_tenant AND definition_id=_definition AND actor_id=actor AND request_key=_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',_definition,'state','absent');END IF;
 SELECT coalesce(jsonb_object_agg(value->>'side_id',value->>'dataset_id'),'{}') INTO selected FROM jsonb_array_elements(q.intent->'bindings') WHERE value->>'kind'='prepared_dataset';
 IF q.intent->>'input_kind' IS DISTINCT FROM 'prepared_bound' OR q.intent->>'business_date' IS DISTINCT FROM _business_date::text OR selected IS DISTINCT FROM _datasets
 THEN RAISE EXCEPTION 'rs.prepared_request_key_conflict' USING ERRCODE='PT409';END IF;
 FOR m IN SELECT value FROM jsonb_array_elements(q.manifest) LOOP
  IF private.data_source_child_allows(actor,_tenant,(m->>'data_source_id')::uuid,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'rs.current_replay_source_denied' USING ERRCODE='42501';END IF;
 END LOOP;
 SELECT * INTO r FROM public.recon_runs WHERE id=q.run_id AND tenant_id=_tenant AND run_by=actor;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.original_native_run_unavailable' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',q.tenant_id,'definition_id',q.definition_id,'run_id',r.id,'run_uid',r.run_uid,
  'request_key',q.request_key,'status',r.status,'phase',q.phase,'input_manifest',q.manifest,'execution_kind','request_replay','state','recorded',
  'attachment_receipt',q.attachment_receipt,'input_fingerprint',q.input_fingerprint,'completion',q.completion);
END $function$

CREATE OR REPLACE FUNCTION public.read_prepared_execution_request(_tenant_id uuid, _definition_id uuid, _request_key uuid, _business_date date, _prepared_dataset_by_side jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE receipt jsonb;
BEGIN
 receipt:=private.rs_prepared_replay(_tenant_id,_definition_id,_request_key,_business_date,_prepared_dataset_by_side);
 IF receipt->>'run_id' IS NOT NULL THEN PERFORM 1 FROM public.recon_runs WHERE id=(receipt->>'run_id')::uuid AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.original_run_current_rlp_denied' USING ERRCODE='42501';END IF;
 END IF;RETURN receipt;
END $function$

CREATE OR REPLACE FUNCTION private.rs_attest_original(_tenant uuid, _run uuid, _side text, _key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;r public.recon_runs%ROWTYPE;v public.recon_definition_approved_versions%ROWTYPE;
 actor uuid;side jsonb;mapping jsonb;fields jsonb:='{}';facet text;u public.workspace_data_source_uploads%ROWTYPE;
 att private.rs_attachments%ROWTYPE;binding uuid;profile_label text;profile jsonb;digest text;proof private.rs_source_attestations%ROWTYPE;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE run_id=_run AND tenant_id=_tenant;
 IF NOT FOUND OR _key IS NULL THEN RAISE EXCEPTION 'rs.native_source_run_required' USING ERRCODE='42501';END IF;
 actor:=private.rs_actor(_tenant,q.definition_id,'edit');
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant;
 SELECT * INTO v FROM public.recon_definition_approved_versions WHERE id=r.approved_revision_id AND tenant_id=_tenant AND parent_definition_id=q.definition_id;
 IF NOT FOUND OR v.snapshot_sha256 IS DISTINCT FROM r.approved_revision_sha256 THEN RAISE EXCEPTION 'rs.independent_approved_source_mapping_required' USING ERRCODE='42501';END IF;
 SELECT value INTO side FROM jsonb_array_elements(v.snapshot->'sides') WHERE value->>'side_id'=_side;
 mapping:=coalesce(side->'column_mapping',side->'input_contract'->'column_mapping');
 FOR facet IN SELECT unnest(ARRAY['affirmation','settlement']) LOOP
  IF mapping->>(facet||'_state') IS NOT NULL AND mapping->>(facet||'_ack_id') IS NOT NULL AND mapping->>(facet||'_ack_at') IS NOT NULL THEN
   fields:=fields||jsonb_build_object(facet,jsonb_build_object('state_field',mapping->>(facet||'_state'),'ack_id_field',mapping->>(facet||'_ack_id'),'ack_at_field',mapping->>(facet||'_ack_at')));
  END IF;
 END LOOP;
 IF fields='{}' THEN RAISE EXCEPTION 'rs.confirmed_affirmation_settlement_field_mapping_required' USING ERRCODE='42501';END IF;
 SELECT * INTO att FROM private.rs_attachments WHERE run_id=_run AND side_id=_side;
 IF NOT FOUND OR private.data_source_child_allows(actor,_tenant,att.data_source_id,'manage') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'rs.actual_source_attestation_permission_required' USING ERRCODE='42501';END IF;
 SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=att.upload_id AND tenant_id=_tenant AND data_source_id=att.data_source_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.original_authenticated_upload_unavailable' USING ERRCODE='42501';END IF;
 profile_label:='approved-mapping-lifecycle:'||_side;
 profile:=jsonb_build_object('id',profile_label,'version',v.snapshot_sha256,'confirmation_kind','authenticated_actor_attestation','fields',fields,
  'date_fields',jsonb_build_object('trade_date',mapping->>'trade_date','value_date',mapping->>'value_date','business_date',mapping->>'business_date'));
 digest:=encode(sha256(convert_to(u.rows::text,'UTF8')),'hex');
 SELECT * INTO proof FROM private.rs_source_attestations WHERE proof_id=_key;
 IF FOUND THEN
  IF proof.upload_id<>u.id OR proof.rows_sha256<>digest OR proof.authenticated_actor<>actor THEN RAISE EXCEPTION 'rs.source_attestation_request_conflict' USING ERRCODE='PT409';END IF;
  RETURN to_jsonb(proof)||jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'confirmation_kind','authenticated_actor_attestation','request_replay',true);
 END IF;
 SELECT binding_id INTO binding FROM private.rs_source_bindings WHERE tenant_id=_tenant AND definition_id=q.definition_id AND side_id=_side
 AND data_source_id=u.data_source_id AND profile_id=profile_label AND profile_version=v.snapshot_sha256;
 IF binding IS NULL THEN
  INSERT INTO private.rs_source_bindings(binding_id,tenant_id,definition_id,side_id,data_source_id,profile_id,profile_version,fields,qualification)
  VALUES(gen_random_uuid(),_tenant,q.definition_id,_side,u.data_source_id,profile_label,v.snapshot_sha256,fields,jsonb_build_object('state','native_qualified',
   'kind','independently_approved_mapping','approved_revision_id',v.id,'producer_source_sha256',encode(sha256(convert_to(pg_get_functiondef('private.rs_attest_original(uuid,uuid,text,uuid)'::regprocedure),'UTF8')),'hex')))
  RETURNING binding_id INTO binding;
 END IF;
 INSERT INTO private.rs_source_attestations(proof_id,binding_id,upload_id,rows_sha256,authenticated_actor,authenticated_at,provenance)
 VALUES(_key,binding,u.id,digest,actor,clock_timestamp(),jsonb_build_object('state','authenticated_native_source','kind','authenticated_actor_attestation',
  'original_uploaded_by',u.uploaded_by,'original_arrival_at',u.created_at,'approved_revision_id',v.id,'approved_snapshot_sha256',v.snapshot_sha256,
  'profile',profile,'producer_source_sha256',encode(sha256(convert_to(pg_get_functiondef('private.rs_attest_original(uuid,uuid,text,uuid)'::regprocedure),'UTF8')),'hex')))
 RETURNING * INTO proof;
 INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,actor,'original_source_attested',jsonb_build_object('proof_id',proof.proof_id,
  'source_binding_id',binding,'source_upload_id',u.id,'source_rows_sha256',digest,'profile',profile,'confirmation_kind','authenticated_actor_attestation'));
 RETURN to_jsonb(proof)||jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'confirmation_kind','authenticated_actor_attestation','request_replay',false);
END $function$

CREATE OR REPLACE FUNCTION public.attest_recon_lifecycle_original(_tenant_id uuid, _run_id uuid, _side_id text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE result jsonb;
BEGIN
 PERFORM 1 FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_source_run_rlp_required' USING ERRCODE='42501';END IF;
 result:=private.rs_attest_original(_tenant_id,_run_id,_side_id,_request_key);
 PERFORM 1 FROM public.workspace_data_source_uploads WHERE id=(result->>'upload_id')::uuid AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_original_source_rlp_required' USING ERRCODE='42501';END IF;
 IF result->'request_replay' IS DISTINCT FROM 'true'::jsonb THEN INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(auth.uid(),_tenant_id,'workspace','recon.source.original_attestation','recon_run',_run_id::text,result-'provenance');END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.dprt_authorize(_tenant uuid, _pipeline uuid, _action text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant,_pipeline,_action);
BEGIN
 IF _action='manage' THEN
  PERFORM public.assert_data_prep_actor(_tenant,actor,true);
  IF public.user_has_permission(actor,_tenant,'compliance.retention.manage',NULL) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'dprt.retention_permission_required' USING ERRCODE='42501'; END IF;
 END IF;
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=actor AND active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'dprt.current_membership_required' USING ERRCODE='42501'; END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.dprt_begin_job(_tenant uuid, _pipeline uuid, _job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dprt_authorize(_tenant,_pipeline,'manage');j private.dprt_jobs%ROWTYPE; files uuid[];
 day date:=(clock_timestamp() AT TIME ZONE 'UTC')::date;
BEGIN
 IF _job IS NULL THEN RAISE EXCEPTION 'dprt.job_id_required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('dprt-job:'||_job::text,0));
 SELECT * INTO j FROM private.dprt_jobs WHERE id=_job;
 IF FOUND THEN
  IF j.tenant_id<>_tenant OR j.pipeline_id<>_pipeline OR j.actor_id<>actor THEN RAISE EXCEPTION 'dprt.job_conflict'; END IF;
  RETURN to_jsonb(j);
 END IF;
 SELECT coalesce(array_agg(file_id ORDER BY file_id),'{}'::uuid[]) INTO files
 FROM public.data_prep_attachment_retention a WHERE tenant_id=_tenant AND pipeline_id=_pipeline
 AND expires_at<=(day::timestamp AT TIME ZONE 'UTC')
 AND NOT EXISTS(SELECT 1 FROM public.data_prep_attachment_tombstones t WHERE t.file_id=a.file_id);
 INSERT INTO private.dprt_jobs(id,tenant_id,pipeline_id,actor_id,day_utc,candidate_files)
 VALUES(_job,_tenant,_pipeline,actor,day,files) RETURNING * INTO j;
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION public.dprt_claim_attachment(_tenant uuid, _pipeline uuid, _file uuid, _job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dprt_authorize(_tenant,_pipeline,'manage');a public.data_prep_attachment_retention%ROWTYPE;
 j private.dprt_jobs%ROWTYPE;c private.dprt_claims%ROWTYPE;o storage.objects%ROWTYPE;f public.data_prep_delivery_files%ROWTYPE;refs jsonb;descriptor jsonb;
BEGIN
 PERFORM private.dprt_native_fences();
 SELECT * INTO j FROM private.dprt_jobs WHERE id=_job FOR UPDATE;
 IF NOT FOUND OR j.tenant_id<>_tenant OR j.pipeline_id<>_pipeline OR j.actor_id<>actor
 OR NOT (_file=ANY(j.candidate_files)) OR EXISTS(SELECT 1 FROM private.dprt_certificates WHERE job_id=_job)
 THEN RAISE EXCEPTION 'dprt.job_scope_or_frozen_certificate'; END IF;
 a:=private.dprt_lock_attachment(_file);
 PERFORM private.dprt_assert_global_hold(a);
 IF a.tenant_id<>_tenant OR a.pipeline_id<>_pipeline THEN RAISE EXCEPTION 'dprt.tenant_mismatch'; END IF;
 IF a.expires_at>clock_timestamp() OR private.dpw_attachment_has_hold(_file)
 THEN RAISE EXCEPTION 'dprt.expiry_or_hold_denied'; END IF;
 refs:=private.dprt_reference_check(_file);
 IF (refs->>'shared')::boolean THEN RAISE EXCEPTION 'dprt.shared_reference_denied'; END IF;
 SELECT * INTO c FROM private.dprt_claims WHERE file_id=_file AND job_id=_job;
 IF FOUND THEN RETURN to_jsonb(c); END IF;
 IF EXISTS(SELECT 1 FROM private.dprt_claims old WHERE file_id=_file
  AND NOT EXISTS(SELECT 1 FROM private.dprt_events e WHERE e.claim_id=old.id AND e.event='cancelled'))
 THEN RAISE EXCEPTION 'dprt.previous_claim_requires_readback'; END IF;
 IF EXISTS(SELECT 1 FROM public.data_prep_attachment_tombstones WHERE file_id=_file)
 THEN RAISE EXCEPTION 'dprt.already_tombstoned'; END IF;
 SELECT * INTO f FROM public.data_prep_delivery_files WHERE id=_file;
 SELECT * INTO o FROM storage.objects WHERE bucket_id=a.bucket_id AND name=a.original_path
 AND archived_at IS NULL AND NOT is_delete_marker FOR UPDATE;
 IF NOT FOUND OR coalesce(o.owner_id,o.owner::text) IS DISTINCT FROM f.created_by::text
 OR (o.metadata->>'size')::bigint IS DISTINCT FROM a.original_size_bytes
 OR NOT EXISTS(SELECT 1 FROM storage.buckets WHERE id=o.bucket_id AND public IS FALSE)
 THEN RAISE EXCEPTION 'dprt.object_owner_version_size_required'; END IF;
 descriptor:=jsonb_build_object('retention',to_jsonb(a),'object_id',o.id,'bucket_id',o.bucket_id,'name',o.name,
  'version',o.version,'owner_id',coalesce(o.owner_id,o.owner::text),'references',refs);
 INSERT INTO private.dprt_claims(job_id,file_id,actor_id,descriptor,descriptor_sha256)
 VALUES(_job,_file,actor,descriptor,private.dprt_hash(descriptor)) RETURNING * INTO c;
 INSERT INTO private.dprt_events(claim_id,job_id,file_id,actor_id,event,context)
 VALUES(c.id,_job,_file,actor,'claimed',jsonb_build_object('descriptor_sha256',c.descriptor_sha256));
 PERFORM private.dpw_audit(actor,_tenant,'dprt.artifact.claim',_file,jsonb_build_object('claim_id',c.id,'job_id',_job,'descriptor_sha256',c.descriptor_sha256));
 RETURN to_jsonb(c)||jsonb_build_object('physical_delete_operation',NULL,'activation','closed_until_parent_storage_and_hold_qualification');
END $function$

CREATE OR REPLACE FUNCTION private.dprt_effective_policy(_tenant uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE p private.dpw_attachment_retention_defaults%ROWTYPE;
 t private.dpw_attachment_retention_overrides%ROWTYPE; selected jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('dpw_attachment_retention:platform',0));
 SELECT * INTO p FROM private.dpw_attachment_retention_defaults WHERE singleton=true;
 IF NOT FOUND OR p.period_days<1 THEN RAISE EXCEPTION 'dprt.platform_policy_unqualified'; END IF;
 SELECT * INTO t FROM private.dpw_attachment_retention_overrides WHERE tenant_id=_tenant;
 selected:=CASE WHEN t.period_days IS NOT NULL AND t.period_days>=p.period_days THEN
  jsonb_build_object('policy_id',t.policy_id,'version',t.version::text,'period_days',t.period_days,'source','tenant',
   'effective_at',greatest(p.effective_at,t.effective_at))
 ELSE jsonb_build_object('policy_id',p.policy_id,'version',p.version::text,'period_days',p.period_days,'source','platform','effective_at',p.effective_at) END;
 RETURN selected||jsonb_build_object('platform_version',p.version::text,'tenant_override_version',t.version::text,
  'configured_tenant_days',t.period_days,'policy_snapshot_sha256',private.dprt_hash(selected));
END $function$

CREATE OR REPLACE FUNCTION public.dprt_finalize_attachment(_tenant uuid, _pipeline uuid, _claim uuid, _receipt uuid, _subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_processor_actor(_tenant,_pipeline,_subject,'manage');
 c private.dprt_claims%ROWTYPE;a public.data_prep_attachment_retention%ROWTYPE;
 r private.dprt_receipts%ROWTYPE;t public.data_prep_attachment_tombstones%ROWTYPE;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant,actor,true);
 IF public.user_has_permission(actor,_tenant,'compliance.retention.manage',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dprt.retention_permission_required'; END IF;
 PERFORM private.dprt_native_fences();
 SELECT * INTO c FROM private.dprt_claims WHERE id=_claim FOR UPDATE;
 IF NOT FOUND OR c.actor_id<>actor THEN RAISE EXCEPTION 'dprt.claim_actor_required'; END IF;
 a:=private.dprt_lock_attachment(c.file_id);
 PERFORM private.dprt_assert_global_hold(a);
 IF a.tenant_id<>_tenant OR a.pipeline_id<>_pipeline OR a.expires_at>clock_timestamp()
 OR private.dpw_attachment_has_hold(c.file_id) OR (private.dprt_reference_check(c.file_id)->>'shared')::boolean
 OR EXISTS(SELECT 1 FROM private.dprt_events WHERE claim_id=c.id AND event='cancelled') THEN RAISE EXCEPTION 'dprt.current_fences_denied'; END IF;
 SELECT * INTO r FROM private.dprt_receipts WHERE id=_receipt AND claim_id=c.id;
 IF NOT FOUND OR r.descriptor_sha256<>c.descriptor_sha256 THEN RAISE EXCEPTION 'dprt.verified_receipt_required'; END IF;
 IF private.dprt_storage_receipt_attest(c.id,r.verified_receipt) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dprt.verified_provider_signature_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO t FROM public.data_prep_attachment_tombstones WHERE file_id=c.file_id;
 IF FOUND THEN IF t.job_id<>c.job_id THEN RAISE EXCEPTION 'dprt.tombstone_job_conflict'; END IF; RETURN to_jsonb(t)||jsonb_build_object('retention',to_jsonb(a)); END IF;
 IF c.lease_expires_at<=clock_timestamp() OR EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id=a.bucket_id AND name=a.original_path AND NOT is_delete_marker)
 THEN RAISE EXCEPTION 'dprt.fresh_claim_and_absence_required'; END IF;
 INSERT INTO public.data_prep_attachment_tombstones(file_id,job_id,transport_role,purged_at,object_absence_verified,original_file_bytes_sha256,original_size_bytes)
 VALUES(c.file_id,c.job_id,'service_role',(r.verified_receipt->>'deleted_at')::timestamptz,true,a.original_file_bytes_sha256,a.original_size_bytes) RETURNING * INTO t;
 INSERT INTO private.dprt_events(claim_id,job_id,file_id,actor_id,event,context)
 VALUES(c.id,c.job_id,c.file_id,actor,'completed',jsonb_build_object('receipt_id',r.id,'tombstone_sha256',private.dprt_hash(to_jsonb(t)||jsonb_build_object('retention',to_jsonb(a)))));
 PERFORM private.dpw_audit(actor,_tenant,'dprt.artifact.finalized',c.file_id,jsonb_build_object('claim_id',c.id,'receipt_id',r.id,'tombstone',to_jsonb(t),'retention',to_jsonb(a)));
 RETURN to_jsonb(t)||jsonb_build_object('retention',to_jsonb(a));
END $function$

CREATE OR REPLACE FUNCTION public.dprt_finish_job(_tenant uuid, _pipeline uuid, _job uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dprt_authorize(_tenant,_pipeline,'manage');j private.dprt_jobs%ROWTYPE;c private.dprt_certificates%ROWTYPE;
 manifest jsonb;counts jsonb;
BEGIN
 SELECT * INTO j FROM private.dprt_jobs WHERE id=_job FOR UPDATE;
 IF NOT FOUND OR j.tenant_id<>_tenant OR j.pipeline_id<>_pipeline OR j.actor_id<>actor THEN RAISE EXCEPTION 'dprt.job_scope_required'; END IF;
 SELECT * INTO c FROM private.dprt_certificates WHERE job_id=_job;
 IF FOUND THEN RETURN to_jsonb(c); END IF;
 IF EXISTS(SELECT 1 FROM private.dprt_claims x WHERE job_id=_job AND NOT EXISTS(SELECT 1 FROM private.dprt_events e
  WHERE e.claim_id=x.id AND e.event IN('completed','cancelled'))) THEN RAISE EXCEPTION 'dprt.pending_claims'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('file_id',t.file_id,'tombstone_sha256',
  private.dprt_hash(to_jsonb(t)||jsonb_build_object('retention',to_jsonb(a)))) ORDER BY t.file_id),'[]'::jsonb)
 INTO manifest FROM public.data_prep_attachment_tombstones t JOIN public.data_prep_attachment_retention a ON a.file_id=t.file_id WHERE t.job_id=_job;
 counts:=jsonb_build_object('candidate_count',cardinality(j.candidate_files),'claim_count',(SELECT count(*) FROM private.dprt_claims WHERE job_id=_job),
  'purged_count',jsonb_array_length(manifest),'unpurged_count',cardinality(j.candidate_files)-jsonb_array_length(manifest));
 INSERT INTO private.dprt_certificates(job_id,actor_id,counts,tombstone_manifest,tombstone_manifest_sha256)
 VALUES(_job,actor,counts,manifest,private.dprt_hash(manifest)) RETURNING * INTO c;
 PERFORM private.dpw_audit(actor,_tenant,'dprt.job.certificate',_job,to_jsonb(c));
 RETURN to_jsonb(c);
END $function$

CREATE OR REPLACE FUNCTION public.dprt_get_attachment(_tenant uuid, _pipeline uuid, _file uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dprt_authorize(_tenant,_pipeline,'view');a public.data_prep_attachment_retention%ROWTYPE;f public.data_prep_delivery_files%ROWTYPE;t jsonb;
BEGIN
 SELECT * INTO a FROM public.data_prep_attachment_retention WHERE file_id=_file AND tenant_id=_tenant AND pipeline_id=_pipeline;
 IF NOT FOUND THEN RAISE EXCEPTION 'dprt.attachment_unknown'; END IF;
 SELECT * INTO f FROM public.data_prep_delivery_files WHERE id=_file;
 IF private.dpw_source_allows(actor,_tenant,f.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dprt.source_read_denied'; END IF;
 SELECT to_jsonb(x) INTO t FROM public.data_prep_attachment_tombstones x WHERE x.file_id=_file;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'retention',to_jsonb(a),'run_id',a.run_id,'filename',f.descriptor->>'filename',
  'view_available',a.expires_at>clock_timestamp() AND t IS NULL,'legal_hold',private.dpw_attachment_has_hold(_file),'tombstone',t,
  'original_path',CASE WHEN a.expires_at>clock_timestamp() AND t IS NULL THEN a.original_path ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION private.dprt_lock_attachment(_file uuid)
 RETURNS data_prep_attachment_retention
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a public.data_prep_attachment_retention%ROWTYPE; f public.data_prep_delivery_files%ROWTYPE;
BEGIN
 SELECT * INTO a FROM public.data_prep_attachment_retention WHERE file_id=_file FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'dprt.attachment_unknown'; END IF;
 SELECT * INTO f FROM public.data_prep_delivery_files WHERE id=_file FOR UPDATE;
 IF NOT FOUND OR f.state IS DISTINCT FROM 'received' OR f.upload_id IS NULL
 OR f.tenant_id<>a.tenant_id OR f.pipeline_id<>a.pipeline_id
 OR f.original_path<>a.original_path OR f.content_sha256<>a.original_file_bytes_sha256
 OR (f.descriptor->>'size_bytes')::bigint IS DISTINCT FROM a.original_size_bytes
 THEN RAISE EXCEPTION 'dprt.exact_attachment_binding_required'; END IF;
 PERFORM 1 FROM public.data_prep_delivery_runs WHERE id=a.run_id AND tenant_id=a.tenant_id
 AND pipeline_id=a.pipeline_id AND finished_at=a.attached_at FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'dprt.immutable_completion_clock_required'; END IF;
 -- Upload row locks conflict with FK consumers. Published dataset rows are also
 -- locked below. Legacy JSON-only consumers still require main's fence capture.
 PERFORM 1 FROM public.workspace_data_source_uploads WHERE id=f.upload_id FOR UPDATE;
 PERFORM 1 FROM public.data_prep_prepared_datasets WHERE run_id=a.run_id FOR UPDATE;
 RETURN a;
END $function$

CREATE OR REPLACE FUNCTION public.dprt_record_verified_receipt(_tenant uuid, _pipeline uuid, _claim uuid, _receipt uuid, _subject jsonb, _proof jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_processor_actor(_tenant,_pipeline,_subject,'manage');
 c private.dprt_claims%ROWTYPE; a public.data_prep_attachment_retention%ROWTYPE;r private.dprt_receipts%ROWTYPE;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant,actor,true);
 IF public.user_has_permission(actor,_tenant,'compliance.retention.manage',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dprt.retention_permission_required'; END IF;
 PERFORM private.dprt_native_fences();
 SELECT * INTO c FROM private.dprt_claims WHERE id=_claim FOR UPDATE;
 IF NOT FOUND OR c.actor_id<>actor THEN RAISE EXCEPTION 'dprt.claim_actor_required'; END IF;
 a:=private.dprt_lock_attachment(c.file_id);
 PERFORM private.dprt_assert_global_hold(a);
 IF a.tenant_id<>_tenant OR a.pipeline_id<>_pipeline OR a.expires_at>clock_timestamp()
 OR private.dpw_attachment_has_hold(c.file_id) OR (private.dprt_reference_check(c.file_id)->>'shared')::boolean
 OR EXISTS(SELECT 1 FROM private.dprt_events WHERE claim_id=c.id AND event='cancelled')
 THEN RAISE EXCEPTION 'dprt.current_fences_denied'; END IF;
 IF _receipt IS NULL OR _proof->>'descriptor_sha256' IS DISTINCT FROM c.descriptor_sha256
 OR _proof->>'provider_receipt_id' IS NULL OR _proof->>'evidence_sha256' !~ '^[a-f0-9]{64}$'
 OR _proof->>'evidence_sha256' IS NULL OR (_proof->>'deleted_at')::timestamptz IS NULL
 OR (_proof->>'deleted_at')::timestamptz<a.expires_at OR (_proof->>'deleted_at')::timestamptz>clock_timestamp()
 THEN RAISE EXCEPTION 'dprt.exact_verified_provider_receipt_required'; END IF;
 IF private.dprt_storage_receipt_attest(c.id,_proof) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dprt.verified_provider_signature_required' USING ERRCODE='42501'; END IF;
 -- The preserved closed native attestor above is REQUIRED to verify real provider
 -- evidence; a caller boolean or catalog absence alone never qualifies bytes.
 SELECT * INTO r FROM private.dprt_receipts WHERE claim_id=_claim;
 IF FOUND THEN IF r.id<>_receipt OR r.verified_receipt IS DISTINCT FROM _proof THEN RAISE EXCEPTION 'dprt.receipt_conflict'; END IF;RETURN to_jsonb(r); END IF;
 IF EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id=a.bucket_id AND name=a.original_path AND NOT is_delete_marker)
 THEN RAISE EXCEPTION 'dprt.object_still_present'; END IF;
 INSERT INTO private.dprt_receipts(id,claim_id,actor_id,descriptor_sha256,verified_receipt,evidence_sha256)
 VALUES(_receipt,c.id,actor,c.descriptor_sha256,_proof,_proof->>'evidence_sha256') RETURNING * INTO r;
 RETURN to_jsonb(r);
END $function$

CREATE OR REPLACE FUNCTION private.dprt_reference_check(_file uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a public.data_prep_attachment_retention%ROWTYPE; f public.data_prep_delivery_files%ROWTYPE;
 shared_count bigint; recon_count bigint;
BEGIN
 SELECT * INTO a FROM public.data_prep_attachment_retention WHERE file_id=_file;
 SELECT * INTO f FROM public.data_prep_delivery_files WHERE id=_file;
 SELECT count(*) INTO shared_count FROM public.data_prep_run_inputs
 WHERE (file_id=f.id OR upload_id=f.upload_id) AND run_id<>a.run_id;
 SELECT count(*) INTO recon_count FROM public.data_prep_recon_run_inputs i
 WHERE i.upload_id=f.upload_id OR i.preparation_run_id=a.run_id
 OR i.dataset_id IN(SELECT id FROM public.data_prep_prepared_datasets WHERE run_id=a.run_id);
 -- Conservative metadata-only check of old JSON-backed reconciliation pins.
 SELECT recon_count+count(*) INTO recon_count FROM public.recon_runs r
 WHERE r.tenant_id=a.tenant_id AND (
  jsonb_path_exists(coalesce(r.definition_snapshot,'{}'), '$.** ? (@.upload_id == $uid)', jsonb_build_object('uid',f.upload_id::text))
  OR EXISTS(SELECT 1 FROM public.data_prep_prepared_datasets d WHERE d.run_id=a.run_id AND
    jsonb_path_exists(coalesce(r.definition_snapshot,'{}'), '$.** ? (@.upload_id == $uid)', jsonb_build_object('uid',d.upload_id::text)))
 );
 RETURN jsonb_build_object('other_preparation_references',shared_count,'reconciliation_references',recon_count,
  'shared',shared_count>0 OR recon_count>0);
END $function$

CREATE OR REPLACE FUNCTION public.dprt_register_attachment(_tenant uuid, _pipeline uuid, _file uuid, _run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dprt_authorize(_tenant,_pipeline,'manage');
 f public.data_prep_delivery_files%ROWTYPE;r public.data_prep_delivery_runs%ROWTYPE;
 policy jsonb;a public.data_prep_attachment_retention%ROWTYPE; days integer;
BEGIN
 SELECT * INTO f FROM public.data_prep_delivery_files WHERE id=_file AND tenant_id=_tenant AND pipeline_id=_pipeline FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'dprt.file_binding_required'; END IF;
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run AND tenant_id=_tenant AND pipeline_id=_pipeline FOR UPDATE;
 IF NOT FOUND OR r.finished_at IS NULL OR NOT EXISTS(SELECT 1 FROM public.data_prep_run_inputs WHERE run_id=_run AND file_id=_file)
 THEN RAISE EXCEPTION 'dprt.completed_run_binding_required'; END IF;
 SELECT * INTO a FROM public.data_prep_attachment_retention WHERE file_id=_file;
 IF FOUND THEN
  IF a.run_id<>_run THEN RAISE EXCEPTION 'dprt.shared_original_clock_cannot_be_rewritten'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'retention',to_jsonb(a),'is_new',false);
 END IF;
 policy:=private.dprt_effective_policy(_tenant);days:=(policy->>'period_days')::integer;
 IF r.finished_at<(policy->>'effective_at')::timestamptz OR f.state<>'received' THEN
  RAISE EXCEPTION 'dprt.no_historical_enrollment'; END IF;
 INSERT INTO public.data_prep_attachment_retention(file_id,tenant_id,pipeline_id,bucket_id,original_path,original_file_bytes_sha256,
  original_size_bytes,run_id,attached_at,expires_at,policy_id,policy_version,period_days,policy_source,notice_30_at,notice_10_at,notice)
 VALUES(f.id,_tenant,_pipeline,'data-prep-inputs',f.original_path,f.content_sha256,(f.descriptor->>'size_bytes')::bigint,
  r.id,r.finished_at,r.finished_at+days*interval '1 day',(policy->>'policy_id')::uuid,policy->>'version',days,policy->>'source',
  r.finished_at+(days-30)*interval '1 day',r.finished_at+(days-10)*interval '1 day','Execution attachment bytes follow the recorded policy; run/config/audit metadata remain retained')
 RETURNING * INTO a;
 PERFORM private.dpw_audit(actor,_tenant,'dprt.policy.snapshot',f.id,jsonb_build_object('run_id',r.id,'policy',policy,'expires_at',a.expires_at));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'retention',to_jsonb(a),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.dprt_set_hold(_tenant uuid, _pipeline uuid, _file uuid, _hold boolean, _hold_id uuid, _reason text, _request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dprt_authorize(_tenant,_pipeline,'manage');a public.data_prep_attachment_retention%ROWTYPE;
 h public.data_prep_attachment_holds%ROWTYPE;payload jsonb;prior private.dprt_hold_requests%ROWTYPE;result jsonb;
BEGIN
 IF _hold IS NULL OR _request IS NULL OR length(coalesce(btrim(_reason),'')) NOT BETWEEN 3 AND 1000
 OR private.dpw_legal_hold_attest(actor,_tenant) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dprt.hold_authority_required'; END IF;
 a:=private.dprt_lock_attachment(_file);
 IF a.tenant_id<>_tenant OR a.pipeline_id<>_pipeline THEN RAISE EXCEPTION 'dprt.tenant_mismatch'; END IF;
 payload:=jsonb_build_object('file_id',_file,'hold',_hold,'hold_id',_hold_id,'reason',btrim(_reason));
 SELECT * INTO prior FROM private.dprt_hold_requests WHERE tenant_id=_tenant AND actor_id=actor AND request_key=_request;
 IF FOUND THEN IF prior.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'dprt.hold_request_conflict'; END IF;RETURN prior.result; END IF;
 IF EXISTS(SELECT 1 FROM public.data_prep_attachment_tombstones WHERE file_id=_file) THEN RAISE EXCEPTION 'dprt.already_tombstoned'; END IF;
 IF NOT _hold AND NOT EXISTS(SELECT 1 FROM public.data_prep_attachment_holds WHERE id=_hold_id AND file_id=_file AND operation='hold'
  AND NOT EXISTS(SELECT 1 FROM public.data_prep_attachment_holds x WHERE x.hold_id=_hold_id AND x.operation='release'))
 THEN RAISE EXCEPTION 'dprt.active_hold_required'; END IF;
 INSERT INTO public.data_prep_attachment_holds(file_id,operation,hold_id,actor_id,reason)
 VALUES(_file,CASE WHEN _hold THEN 'hold' ELSE 'release' END,CASE WHEN _hold THEN NULL ELSE _hold_id END,actor,btrim(_reason)) RETURNING * INTO h;
 IF _hold THEN
  INSERT INTO private.dprt_events(claim_id,job_id,file_id,actor_id,event,context)
  SELECT c.id,c.job_id,c.file_id,actor,'cancelled',jsonb_build_object('hold_id',h.id)
  FROM private.dprt_claims c WHERE c.file_id=_file AND NOT EXISTS(
   SELECT 1 FROM private.dprt_events e WHERE e.claim_id=c.id AND e.event IN('cancelled','completed'));
 END IF;
 result:=jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'hold',to_jsonb(h));
 INSERT INTO private.dprt_hold_requests VALUES(_tenant,actor,_request,payload,result);
 PERFORM private.dpw_audit(actor,_tenant,'dprt.artifact.hold',_file,jsonb_build_object('hold',to_jsonb(h)));
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.rs_actor(_tenant uuid, _definition uuid, _action text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE a uuid:=auth.uid();d public.recon_definitions%ROWTYPE;
BEGIN
 IF a IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR _action NOT IN('read','run','edit')
 OR private.rlnext_account_allowed(a,NULL) IS DISTINCT FROM true OR private.rlnext_account_allowed(a,_tenant) IS DISTINCT FROM true
 OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=a AND active)
 THEN RAISE EXCEPTION 'rs.current_actor_denied' USING ERRCODE='42501';END IF;
 PERFORM private.wfm_actor(_tenant);
 PERFORM private.wfm_assert_enabled(_tenant,'recons');
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.scope_denied' USING ERRCODE='42501';END IF;
 IF (_action='read' AND (private.recon_run_read_allowed(d.id,_tenant) IS DISTINCT FROM true
   OR private.recon_run_effective_read_allowed(d.id,_tenant) IS DISTINCT FROM true))
 OR (_action IN('run','edit') AND private.recon_root_write_allowed(d.id,_tenant,_action) IS DISTINCT FROM true) THEN
  -- Reuse current native read/write predicates including their exact legacy
  -- ancestry rules. No role reinterpretation, alias, override or new authority.
  RAISE EXCEPTION 'rs.current_resource_action_denied' USING ERRCODE='42501';END IF;
 IF _action='run' AND d.governance_state='approved_locked' AND d.environment='production'
 AND NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=a AND active AND role='tenant_admin'::public.tenant_role)
 THEN RAISE EXCEPTION 'rs.production_admission_denied' USING ERRCODE='42501';END IF;
 RETURN a;
END $function$

CREATE OR REPLACE FUNCTION private.rs_artifact_read_state(_tenant uuid, _run uuid, _side text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;expiry timestamptz;held boolean;tombstoned boolean;available boolean;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE run_id=_run AND tenant_id=_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.exact_artifact_run_unavailable' USING ERRCODE='42501';END IF;
 PERFORM private.rs_actor(_tenant,q.definition_id,'read');
 expiry:=(q.attachment_receipt->>'expires_at')::timestamptz;
 held:=EXISTS(SELECT 1 FROM private.rs_attachment_holds WHERE run_id=_run);
 tombstoned:=q.attachment_receipt->'tombstoned'='true'::jsonb OR EXISTS(
  SELECT 1 FROM private.rs_events WHERE run_id=_run AND kind IN('attachment_tombstoned','artifact_tombstoned')
  AND (payload->>'side_id' IS NULL OR _side IS NULL OR payload->>'side_id'=_side));
 tombstoned:=coalesce(tombstoned,false);
 available:=NOT tombstoned AND expiry IS NOT NULL AND statement_timestamp()<expiry;
 RETURN jsonb_build_object('available',available,'state',CASE WHEN tombstoned THEN 'tombstoned' WHEN available THEN 'available' ELSE 'expired' END,
  'run_id',q.run_id,'side_id',_side,'expires_at',expiry,'legal_hold',held,'metadata_retained',true,
  'physical_purge_performed',false,'reason',CASE WHEN tombstoned THEN 'Original execution attachment is tombstoned; retained run and event metadata remain.'
   WHEN NOT available THEN 'Original execution attachment availability expired; retained run and event metadata remain.' ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION private.wfm_actor(_tenant uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid();claims jsonb:=auth.jwt();expires timestamptz;
BEGIN
 IF _tenant IS NULL OR actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
 OR claims->>'exp' IS NULL OR claims->>'exp' !~ '^[0-9]{1,20}$'
 OR public.rlnext_actor_allowed() IS DISTINCT FROM true OR private.rlnext_account_allowed(actor,NULL) IS DISTINCT FROM true
 OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=actor AND deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=clock_timestamp()))
 OR NOT EXISTS(SELECT 1 FROM public.tenants WHERE id=_tenant) THEN RAISE EXCEPTION 'wfm.current_account_denied' USING ERRCODE='42501';END IF;
 BEGIN expires:=to_timestamp((claims->>'exp')::double precision);EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'wfm.current_account_denied' USING ERRCODE='42501';END;
 IF expires<=clock_timestamp() THEN RAISE EXCEPTION 'wfm.current_account_denied' USING ERRCODE='42501';END IF;
 IF public.is_platform_admin(actor) IS TRUE THEN
  IF private.wfm_platform_factor_attest() IS DISTINCT FROM true THEN RAISE EXCEPTION 'wfm.platform_factor_denied' USING ERRCODE='42501';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=actor AND active IS TRUE)
  OR private.dpw_native_factor_attest(actor,_tenant,claims->>'aal',expires) IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'wfm.current_membership_or_factor_denied' USING ERRCODE='42501';END IF;
 END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION private.dpw_mode_attest(_actor uuid, _tenant uuid, _pipeline uuid, _mode text, _human_in_loop boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE p public.platform_ai_settings%ROWTYPE;t public.tenant_ai_settings%ROWTYPE;cfg jsonb;
BEGIN
 -- Peer-safe translation of reviewed wfm_mode_allowed; no service auth.uid()
 -- substitution. Platform/tenant/workspace ceilings and kill switches remain.
 IF private.dpw_workspace_feature_attest(_actor,_tenant) IS DISTINCT FROM true OR _mode IS NULL THEN RETURN false; END IF;
 IF _actor IS NULL OR _tenant IS NULL OR _pipeline IS NULL OR _human_in_loop IS NULL THEN RETURN false;END IF;
 IF _mode='assisted' AND _human_in_loop IS DISTINCT FROM true THEN RETURN false;END IF;
 IF _mode='manual' THEN RETURN true; END IF;
 IF _mode NOT IN('assisted','agentic') OR _human_in_loop IS NULL THEN RETURN false; END IF;
 SELECT * INTO p FROM public.platform_ai_settings WHERE id=true;IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO t FROM public.tenant_ai_settings WHERE tenant_id=_tenant;IF NOT FOUND THEN RETURN false;END IF;
 SELECT config INTO cfg FROM public.tenant_feature_flags WHERE tenant_id=_tenant AND feature_key='data_prep';
 IF p.ai_enabled IS DISTINCT FROM true OR t.ai_enabled IS DISTINCT FROM true OR cfg->'ai_enabled' IS DISTINCT FROM 'true'::jsonb
 OR NOT EXISTS(SELECT 1 FROM public.tenants WHERE id=_tenant AND ai_enabled IS TRUE)
 OR EXISTS(SELECT 1 FROM public.ai_governance_kill_switches WHERE engaged IS TRUE AND (tenant_id=_tenant OR tenant_id IS NULL)) THEN RETURN false;END IF;
 IF _mode='assisted' THEN RETURN cfg->'assisted_enabled'='true'::jsonb AND p.allow_copilot_global AND t.allow_copilot
 AND private.wfm_feature_enabled(_tenant,'copilot') AND public.user_has_permission(_actor,_tenant,'ai.copilot.use',NULL) IS TRUE;END IF;
 RETURN cfg->'agentic_enabled'='true'::jsonb AND p.allow_agent_global AND t.allow_agent AND private.wfm_feature_enabled(_tenant,'agent')
 AND p.default_autonomy_ceiling IN('assist','auto') AND t.default_autonomy IN('supervised','autonomous')
 AND public.user_has_permission(_actor,_tenant,'ai.agent.run',NULL) IS TRUE;
END $function$

CREATE OR REPLACE FUNCTION public.dpw_set_execution_mode(_tenant_id uuid, _pipeline_id uuid, _mode text, _human_in_loop boolean, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid; choice public.data_prep_mode_choices%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('wfm:'||_tenant_id::text,0));
 actor:=private.dpw_authorize(_tenant_id,_pipeline_id,'edit');
 IF _mode IS NULL OR _mode NOT IN('manual','assisted','agentic') OR _human_in_loop IS NULL OR _request_key IS NULL
 OR private.dpw_mode_attest(actor,_tenant_id,_pipeline_id,_mode,_human_in_loop) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.mode_denied'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||actor::text||_request_key::text,61));
 SELECT * INTO choice FROM public.data_prep_mode_choices WHERE tenant_id=_tenant_id AND chosen_by=actor AND request_key=_request_key;
 IF FOUND THEN
  IF choice.pipeline_id<>_pipeline_id OR choice.mode<>_mode OR choice.human_in_loop<>_human_in_loop THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'choice',to_jsonb(choice),'is_new',false);
 END IF;
 INSERT INTO public.data_prep_mode_choices(tenant_id,pipeline_id,chosen_by,mode,human_in_loop,request_key)
 VALUES(_tenant_id,_pipeline_id,actor,_mode,_human_in_loop,_request_key) RETURNING * INTO choice;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.mode.choose',choice.id,jsonb_build_object('mode',_mode,'human_in_loop',_human_in_loop,'final_human_approval_required',true));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'choice',to_jsonb(choice),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_commit_input_file(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _file_id uuid, _rows jsonb, _request_key uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_processor_actor(_tenant_id,_pipeline_id,_verified_subject,'run'); b public.data_prep_delivery_batches%ROWTYPE;
 f public.data_prep_delivery_files%ROWTYPE; up uuid; profile jsonb;
BEGIN
 PERFORM private.wfm_assert_enabled(_tenant_id,'data');
 b:=private.dpw_lock_batch(_tenant_id,_pipeline_id,_batch_id,actor,false);
 SELECT * INTO f FROM public.data_prep_delivery_files WHERE id=_file_id AND batch_id=b.id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR NOT EXISTS(SELECT 1 FROM public.data_prep_file_requests WHERE batch_id=b.id AND file_id=f.id AND request_key=_request_key)
 OR private.dpw_source_allows(actor,_tenant_id,f.data_source_id,'ingest') IS DISTINCT FROM true
 OR jsonb_typeof(_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(_rows)<>(f.descriptor->>'row_count')::integer
 OR octet_length(_rows::text)>52428800
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_rows) WHERE jsonb_typeof(value)<>'object')
 THEN RAISE EXCEPTION 'dpw.complete_input_mismatch'; END IF;
 IF f.state='received' THEN
  IF NOT EXISTS(SELECT 1 FROM public.workspace_data_source_uploads WHERE id=f.upload_id AND rows=_rows AND row_count=jsonb_array_length(_rows))
  THEN RAISE EXCEPTION 'dpw.immutable_upload_mismatch'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'file',to_jsonb(f),'is_new',false);
 END IF;
 IF f.state<>'uploading' OR b.state<>'collecting' THEN RAISE EXCEPTION 'dpw.intake_closed'; END IF;
 SELECT value INTO profile FROM jsonb_array_elements(b.configuration_snapshot->'feeds') WHERE value->>'key'=f.feed_key;
 IF jsonb_array_length(_rows)=0 AND (profile->>'allow_empty')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.empty_input_denied'; END IF;
 IF NOT EXISTS(SELECT 1 FROM storage.objects o WHERE o.bucket_id='data-prep-inputs' AND o.name=f.original_path
 AND (o.metadata->>'size')::bigint=(f.descriptor->>'size_bytes')::bigint)
 THEN RAISE EXCEPTION 'dpw.original_object_unconfirmed'; END IF;
 INSERT INTO public.workspace_data_source_uploads(data_source_id,tenant_id,filename,mime_type,size_bytes,row_count,columns,sample_rows,content_sha256,uploaded_by,rows)
 VALUES(f.data_source_id,_tenant_id,f.descriptor->>'filename',f.descriptor->>'mime_type',(f.descriptor->>'size_bytes')::bigint,
 jsonb_array_length(_rows),f.descriptor->'columns','[]'::jsonb,f.content_sha256,actor,_rows) RETURNING id INTO up;
 UPDATE public.data_prep_delivery_files SET state='received',upload_id=up,received_at=now(),structured_rows_sha256=private.dpw_hash(_rows) WHERE id=f.id RETURNING * INTO f;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.input.received',f.id,jsonb_build_object('batch_id',b.id,'upload_id',up,'row_count',jsonb_array_length(_rows),'sha256',f.content_sha256));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'file',to_jsonb(f),'transport_role','service_role','is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.search_reference_scope_groups(_tenant_id uuid, _owner_bu_ids uuid[], _search text DEFAULT ''::text, _offset integer DEFAULT 0, _limit integer DEFAULT 50, _selected_ids uuid[] DEFAULT ARRAY[]::uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE v_rows jsonb; v_items jsonb; v_metadata jsonb := '[]'::jsonb;
  v_group uuid; v_name text; v_bu_ids uuid[]; v_pattern text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  IF public.wfm_workspace_row_allowed(_tenant_id,'reference') IS DISTINCT FROM true THEN RAISE EXCEPTION 'Workspace section is disabled or current access denied' USING ERRCODE='42501';END IF;

  IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
    OR current_setting('role', true) IS DISTINCT FROM 'authenticated'
    OR NOT EXISTS (SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id = _tenant_id
      AND tm.user_id = auth.uid() AND tm.active AND tm.role = 'tenant_admin'::public.tenant_role) THEN
    RAISE EXCEPTION 'Reference scope search is not authorized' USING ERRCODE = '42501';
  END IF;
  IF _tenant_id IS NULL OR _limit IS NULL OR _limit NOT BETWEEN 1 AND 50 OR _offset IS NULL OR _offset NOT BETWEEN 0 AND 1000000
    OR length(coalesce(_search, '')) > 100 OR coalesce(cardinality(_owner_bu_ids), 0) > 20
    OR coalesce(cardinality(_selected_ids), 0) > 20
    OR array_position(_owner_bu_ids, NULL) IS NOT NULL OR array_position(_selected_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid bounded Reference group search' USING ERRCODE = '22023';
  END IF;
  IF EXISTS (SELECT 1 FROM unnest(_owner_bu_ids) AS requested(bu_id) WHERE NOT EXISTS (
    SELECT 1 FROM public.business_units b WHERE b.id = requested.bu_id AND b.tenant_id = _tenant_id AND NOT b.is_archived)) THEN
    RAISE EXCEPTION 'Reference search owner scope changed' USING ERRCODE = '23514';
  END IF;
  v_pattern := '%' || replace(replace(replace(coalesce(_search, ''), chr(92), chr(92)||chr(92)), '%', chr(92)||'%'), '_', chr(92)||'_') || '%';
  SELECT coalesce(jsonb_agg(jsonb_build_object('id', page.id, 'name', page.name) ORDER BY page.name, page.id), '[]'::jsonb) INTO v_rows
  FROM (SELECT g.id, g.name FROM public.tenant_groups g WHERE g.tenant_id = _tenant_id AND g.name ILIKE v_pattern
    AND EXISTS (SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned
      ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
      JOIN public.business_units target ON target.id = ANY(_owner_bu_ids) AND target.tenant_id = _tenant_id AND NOT target.is_archived
      WHERE ga.group_id = g.id AND ga.tenant_id = _tenant_id
        AND (assigned.id = target.id OR (ga.inherit_descendants AND target.path <@ assigned.path)))
    ORDER BY g.name, g.id OFFSET _offset LIMIT _limit + 1) page;
  SELECT coalesce(jsonb_agg(item.value ORDER BY item.ordinality), '[]'::jsonb) INTO v_items
    FROM jsonb_array_elements(v_rows) WITH ORDINALITY item(value, ordinality) WHERE item.ordinality <= _limit;
  FOREACH v_group IN ARRAY coalesce(_selected_ids, ARRAY[]::uuid[]) LOOP
    v_name := NULL; v_bu_ids := ARRAY[]::uuid[];
    SELECT g.name, array_agg(DISTINCT target.id ORDER BY target.id) INTO v_name, v_bu_ids
    FROM public.tenant_groups g JOIN public.bu_group_assignments ga ON ga.group_id = g.id AND ga.tenant_id = g.tenant_id
      JOIN public.business_units assigned ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
      JOIN public.business_units target ON target.id = ANY(_owner_bu_ids) AND target.tenant_id = _tenant_id AND NOT target.is_archived
      AND (assigned.id = target.id OR (ga.inherit_descendants AND target.path <@ assigned.path))
    WHERE g.id = v_group AND g.tenant_id = _tenant_id GROUP BY g.id, g.name;
    v_bu_ids := coalesce(v_bu_ids, ARRAY[]::uuid[]);
    v_metadata := v_metadata || jsonb_build_array(jsonb_build_object('id', v_group, 'name', v_name,
      'eligible', cardinality(v_bu_ids) > 0, 'business_unit_ids', v_bu_ids));
  END LOOP;
  RETURN jsonb_build_object('groups', jsonb_build_object('items', v_items, 'has_more', jsonb_array_length(v_rows) > _limit,
    'next_offset', _offset + _limit), 'selected_groups', v_metadata);
END $function$

CREATE OR REPLACE FUNCTION private.dpw_storage_allows(_name text, _write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid; f public.data_prep_delivery_files%ROWTYPE; b public.data_prep_delivery_batches%ROWTYPE;
BEGIN
 SELECT * INTO f FROM public.data_prep_delivery_files WHERE original_path=_name;
 IF NOT FOUND THEN RETURN false; END IF;
 actor:=private.dpw_actor(f.tenant_id);
 IF _write THEN PERFORM private.wfm_assert_enabled(f.tenant_id,'data');END IF;
 SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=f.batch_id;
 RETURN (NOT _write OR f.created_by=actor) AND private.dpw_attachment_viewable(f.id) IS TRUE
 AND private.data_prep_pipeline_scope_allows(actor,f.tenant_id,f.pipeline_id,'run') IS TRUE
 AND private.dpw_source_allows(actor,f.tenant_id,f.data_source_id,CASE WHEN _write THEN 'ingest' ELSE 'view' END) IS TRUE
 AND (NOT _write OR (f.state='uploading' AND b.state='collecting'));
END $function$

CREATE OR REPLACE FUNCTION private.wfm_mode_choice_recorded()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE previous_mode text;actor uuid:=private.wfm_actor(NEW.tenant_id);
BEGIN
 IF actor IS DISTINCT FROM NEW.chosen_by OR private.dpw_mode_attest(actor,NEW.tenant_id,NEW.pipeline_id,NEW.mode,NEW.human_in_loop) IS DISTINCT FROM true THEN RAISE EXCEPTION 'wfm.mode_choice_denied' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('wfm:'||NEW.tenant_id::text,0));
 SELECT mode INTO previous_mode FROM private.wfm_pipeline_modes WHERE tenant_id=NEW.tenant_id AND pipeline_id=NEW.pipeline_id;
 INSERT INTO private.wfm_pipeline_modes(tenant_id,pipeline_id,mode) VALUES(NEW.tenant_id,NEW.pipeline_id,NEW.mode) ON CONFLICT(tenant_id,pipeline_id) DO UPDATE SET mode=EXCLUDED.mode;
 PERFORM private.wfm_record(NEW.tenant_id,'pipeline-mode',NEW.pipeline_id::text,jsonb_build_object('mode',coalesce(previous_mode,'manual')),jsonb_build_object('mode',NEW.mode,'choice_id',NEW.id));
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.rs_resolve_ordinary_policy(_tenant uuid, _definition uuid, _business_date date, _pins jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');contract jsonb;s jsonb;pin jsonb;c jsonb;approved public.recon_definition_approved_versions%ROWTYPE;
 d public.recon_definitions%ROWTYPE;snapshot jsonb;configuration_sha text;authority text;declared jsonb;
 u public.workspace_data_source_uploads%ROWTYPE;pins jsonb:='[]';proofs jsonb:='[]';identity jsonb;v_policy jsonb;qualification jsonb;hash text;v_policy_id uuid;
BEGIN
 IF _business_date IS NULL OR _business_date::text !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'rs.explicit_business_date_required' USING ERRCODE='22023';END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_configuration_required' USING ERRCODE='42501';END IF;
 approved:=private.recon_run_bound_approved_version(_tenant,_definition,actor);
 IF approved.id IS NOT NULL THEN
  contract:=public.read_recon_contract(_tenant,_definition,approved.id);authority:='native_approved_revision';
  IF contract->'approved' IS DISTINCT FROM 'true'::jsonb OR contract->'current_revision' IS DISTINCT FROM 'true'::jsonb
  OR contract->'contract_available' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'rs.current_approved_contract_required' USING ERRCODE='42501';END IF;
 ELSE
  -- Existing native helper permits these governed non-production configurations.
  -- Do not invent a checker, approval hash or historical revision for them.
  IF NOT ((d.environment='development' AND d.governance_state='development_draft')
   OR (d.environment IN('development','staging') AND d.governance_state='staging_copy')
   OR (d.access_mode='mapped_exact' AND d.governance_state='legacy_mapped'))
  THEN RAISE EXCEPTION 'rs.native_configuration_not_executable' USING ERRCODE='42501';END IF;
  snapshot:=private.recon_definition_config_snapshot(d);configuration_sha:=encode(sha256(convert_to(snapshot::text,'UTF8')),'hex');
  contract:=jsonb_build_object('sides',snapshot->'sides','input_contracts',private.rs_approved_rule_contracts(snapshot),
   'revision_id',NULL,'expected_definition_sha256',configuration_sha);authority:='native_current_configuration';
 END IF;
 IF _pins IS NOT NULL AND (jsonb_typeof(_pins) IS DISTINCT FROM 'array' OR jsonb_array_length(_pins)<>jsonb_array_length(contract->'sides')
 OR (SELECT count(DISTINCT x->>'side_id') FROM jsonb_array_elements(_pins) x)<>jsonb_array_length(_pins))
 THEN RAISE EXCEPTION 'rs.complete_distinct_pins_required' USING ERRCODE='22023';END IF;
 FOR s IN SELECT x.value FROM jsonb_array_elements(contract->'sides') x ORDER BY x.value->>'side_id' LOOP
  IF _pins IS NULL THEN pin:=jsonb_build_object('side_id',s->>'side_id','upload_id',s->>'upload_id');
  ELSE SELECT x.value INTO pin FROM jsonb_array_elements(_pins) x WHERE x.value->>'side_id'=s->>'side_id';END IF;
  IF pin->>'upload_id' IS NULL OR s->>'upload_id' IS NOT NULL AND s->>'upload_id' IS DISTINCT FROM pin->>'upload_id'
  THEN RAISE EXCEPTION 'rs.explicit_input_selection_required_no_latest_fallback' USING ERRCODE='PT409';END IF;
  IF private.data_source_child_allows(actor,_tenant,(s->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'rs.current_source_denied' USING ERRCODE='42501';END IF;
  SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(pin->>'upload_id')::uuid AND tenant_id=_tenant AND data_source_id=(s->>'data_source_id')::uuid;
  IF NOT FOUND OR jsonb_typeof(u.rows) IS DISTINCT FROM 'array' OR u.row_count<>jsonb_array_length(u.rows) OR u.row_count=0
  THEN RAISE EXCEPTION 'rs.exact_nonempty_input_required' USING ERRCODE='42501';END IF;
  IF s->>'upload_id' IS NULL AND (EXISTS(SELECT 1 FROM public.data_prep_prepared_datasets x WHERE x.tenant_id=_tenant AND x.upload_id=u.id)
   OR EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.tenant_id=_tenant AND p.output_data_source_id=u.data_source_id))
  THEN RAISE EXCEPTION 'rs.prepared_source_requires_native_per_run_binding' USING ERRCODE='42501';END IF;
  SELECT x.value INTO c FROM jsonb_array_elements(contract->'input_contracts') x WHERE x.value->>'side_id'=s->>'side_id';
  IF authority='native_current_configuration' THEN
   declared:=private.rs_schema_profile(_tenant,(s->>'data_source_id')::uuid,coalesce(s->'column_mapping','{}'));
   c:=c||jsonb_build_object('provenance','configured_rule_contract','approval_bound',false,'source_declared_fields',coalesce(declared->'fields','[]'));
  END IF;
  IF c IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(u.rows) x WHERE private.rs_contract_row_allowed(x.value,c) IS DISTINCT FROM true)
  THEN RAISE EXCEPTION 'rs.approved_input_domain_refused' USING ERRCODE='22023';END IF;
  pins:=pins||jsonb_build_array(jsonb_build_object('side_id',s->>'side_id','upload_id',u.id));
  proofs:=proofs||jsonb_build_array(jsonb_build_object('side_id',s->>'side_id','data_source_id',u.data_source_id,'upload_id',u.id,
   'rows_sha256',encode(sha256(convert_to(u.rows::text,'UTF8')),'hex'),'arrival_at',u.created_at,'input_rows',u.row_count));
 END LOOP;
 identity:=jsonb_build_object('tenant_id',_tenant,'definition_id',_definition,'approved_revision_id',contract->>'revision_id',
  'configuration_sha256',contract->>'expected_definition_sha256','configuration_authority',authority,'business_date',_business_date,'pins',pins,'input_proofs',proofs,'cohort_mode','explicit_snapshot_selection','version','ordinary_snapshot_v1');
 hash:=encode(sha256(convert_to(identity::text,'UTF8')),'hex');v_policy_id:=substr(hash,1,32)::uuid;
 v_policy:=identity||jsonb_build_object('policy_id',v_policy_id,'version','ordinary_snapshot_v1','policy_kind','ordinary_native_snapshot',
  'date_basis','user_selected_business_date','as_of',_business_date::text||'T00:00:00Z','market_calendar_available',false,
  'feed_timing_available',false,'no_market_cutoff_inferred',true,'source_business_dates_inferred',false);
 qualification:=jsonb_build_object('state','native_qualified','kind','ordinary_native_snapshot','producer','resolve_recon_ordinary_cohort',
  'actor_id',actor,'approved_revision_id',contract->>'revision_id','configuration_authority',authority,'configuration_sha256',contract->>'expected_definition_sha256','identity_sha256',hash);
 INSERT INTO private.rs_policies(tenant_id,definition_id,policy_id,version,policy,qualification)
 VALUES(_tenant,_definition,v_policy_id,'ordinary_snapshot_v1',v_policy,qualification) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM private.rs_policies p WHERE p.tenant_id=_tenant AND p.definition_id=_definition AND p.policy_id=v_policy_id
  AND p.version='ordinary_snapshot_v1' AND p.policy=v_policy) THEN RAISE EXCEPTION 'rs.immutable_cohort_policy_conflict' USING ERRCODE='PT409';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',_definition,'business_date',_business_date,'policy_id',v_policy_id,
  'policy_version','ordinary_snapshot_v1','pins',pins,'input_proofs',proofs,'expected_definition_sha256',contract->>'expected_definition_sha256',
  'approved_revision_id',contract->>'revision_id','configuration_authority',authority,'cohort_mode','explicit_snapshot_selection','market_calendar_available',false,'feed_timing_available',false);
END $function$

CREATE OR REPLACE FUNCTION public.exception_assignment_member_allowed(_tenant_id uuid, _exception_id uuid, _recipient uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE definition uuid; actor uuid:=auth.uid();
BEGIN
 IF actor IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active) OR NOT(public.has_tenant_role(actor,_tenant_id,'tenant_admin') OR public.user_has_permission(actor,_tenant_id,'break.assign',NULL)) THEN RETURN false; END IF;
 SELECT r.definition_id INTO definition FROM public.recon_exceptions e JOIN public.recon_runs r ON r.id=e.run_id AND r.tenant_id=e.tenant_id WHERE e.id=_exception_id AND e.tenant_id=_tenant_id;
 IF NOT FOUND OR NOT public.recon_authoritative_access_decision(definition,'edit') THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=_recipient AND active) AND private.recon_authoritative_access_decision_as(_recipient,definition,'view');
END $function$

CREATE OR REPLACE FUNCTION public.apply_exception_workflow_atomic(_tenant_id uuid, _exception_ids uuid[], _patch jsonb, _comment text DEFAULT NULL::text, _internal boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); target uuid; prior public.recon_exceptions%ROWTYPE; next_row public.recon_exceptions%ROWTYPE; definition uuid; capability text; comment_id uuid; changed_ids uuid[]:=ARRAY[]::uuid[]; actual_changes integer:=0;
BEGIN
 IF actor IS NULL OR _exception_ids IS NULL OR cardinality(_exception_ids) NOT BETWEEN 1 AND 500 OR (SELECT count(DISTINCT id) FROM unnest(_exception_ids) ids(id))<>cardinality(_exception_ids) THEN RAISE EXCEPTION 'Unique selected cases required' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(_patch) IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_object_keys(_patch) k WHERE k NOT IN ('status','lifecycle_state','priority','assignee','due_date','root_cause','tags','labels','review_state','resolution_note','close_reason','reopen_reason')) THEN RAISE EXCEPTION 'Unsupported exception update'; END IF;
 IF _comment IS NOT NULL AND (length(btrim(_comment)) NOT BETWEEN 1 AND 4000 OR cardinality(_exception_ids)<>1) THEN RAISE EXCEPTION 'One case and a comment of 1 to 4000 characters required'; END IF;
 IF _patch='{}'::jsonb AND _comment IS NULL THEN RAISE EXCEPTION 'An action is required'; END IF;
 capability:=CASE WHEN _patch ? 'assignee' THEN 'break.assign' WHEN _patch->>'status'='open' OR _patch ? 'reopen_reason' THEN 'break.reopen' WHEN _patch->>'status' IN ('resolved','wont_fix') OR _patch->>'lifecycle_state'='resolved' THEN 'break.resolve' ELSE 'break.update' END;
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant_id AND m.user_id=actor AND m.active)
   OR NOT(public.has_tenant_role(actor,_tenant_id,'tenant_admin') OR public.user_has_permission(actor,_tenant_id,capability,NULL)) THEN RAISE EXCEPTION 'Current action permission required' USING ERRCODE='42501'; END IF;
 FOR target IN SELECT id FROM unnest(_exception_ids) ids(id) ORDER BY id LOOP
  SELECT * INTO prior FROM public.recon_exceptions WHERE id=target AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Selected case unavailable' USING ERRCODE='42501'; END IF;
  SELECT r.definition_id INTO definition FROM public.recon_runs r WHERE r.id=prior.run_id AND r.tenant_id=_tenant_id;
  IF NOT FOUND OR NOT public.recon_authoritative_access_decision(definition,'edit') THEN RAISE EXCEPTION 'Current reconciliation edit access required' USING ERRCODE='42501'; END IF;
  next_row:=jsonb_populate_record(prior,_patch);
  IF _patch ? 'status' THEN
   next_row.lifecycle_state:=CASE next_row.status WHEN 'open' THEN 'new' WHEN 'investigating' THEN 'investigating' WHEN 'resolved' THEN 'resolved' WHEN 'wont_fix' THEN 'resolved' ELSE NULL END;
  ELSIF _patch ? 'lifecycle_state' THEN
   next_row.status:=CASE next_row.lifecycle_state WHEN 'resolved' THEN 'resolved' WHEN 'investigating' THEN 'investigating' ELSE 'open' END;
  END IF;
  IF next_row.lifecycle_state IS NULL OR next_row.lifecycle_state NOT IN ('new','assigned','investigating','pending_counterparty','resolved','written_off') OR next_row.status NOT IN ('open','investigating','resolved','wont_fix') THEN RAISE EXCEPTION 'Invalid transition' USING ERRCODE='23514'; END IF;
  IF prior.lifecycle_state='written_off' AND (next_row.lifecycle_state<>prior.lifecycle_state OR next_row.status<>prior.status OR _patch ? 'assignee') THEN RAISE EXCEPTION 'Governed write-off workflow required' USING ERRCODE='23514'; END IF;
  IF prior.status IN ('resolved','wont_fix') AND next_row.status NOT IN ('resolved','wont_fix') AND length(coalesce(_patch->>'reopen_reason',''))<3 THEN RAISE EXCEPTION 'Reopen reason required' USING ERRCODE='23514'; END IF;
  IF _patch ? 'assignee' THEN
   IF prior.status IN ('resolved','wont_fix') THEN RAISE EXCEPTION 'Reopen the case before assignment' USING ERRCODE='23514'; END IF;
   IF next_row.assignee IS NOT NULL AND NOT public.exception_assignment_member_allowed(_tenant_id,prior.id,next_row.assignee) THEN RAISE EXCEPTION 'Assignee must have current scoped access' USING ERRCODE='42501'; END IF;
   IF next_row.assignee IS DISTINCT FROM prior.assignee THEN
   next_row.assigned_by:=CASE WHEN next_row.assignee IS NULL THEN NULL ELSE actor END; next_row.assigned_at:=CASE WHEN next_row.assignee IS NULL THEN NULL ELSE now() END;
   IF prior.lifecycle_state IN ('new','assigned') THEN next_row.lifecycle_state:=CASE WHEN next_row.assignee IS NULL THEN 'new' ELSE 'assigned' END; END IF;
   END IF;
  END IF;
  IF next_row.lifecycle_state='assigned' AND next_row.assignee IS NULL THEN RAISE EXCEPTION 'Select a verified assignee before moving to Assigned' USING ERRCODE='23514'; END IF;
  IF next_row.status IN ('resolved','wont_fix') AND (prior.status NOT IN ('resolved','wont_fix') OR next_row.status<>prior.status) THEN next_row.resolved_by:=actor; next_row.resolved_at:=now(); next_row.closed_at:=now();
  ELSIF prior.status IN ('resolved','wont_fix') AND next_row.status NOT IN ('resolved','wont_fix') THEN next_row.resolved_by:=NULL; next_row.resolved_at:=NULL; next_row.closed_at:=NULL; next_row.reopened_at:=now(); END IF;
  IF to_jsonb(next_row)=to_jsonb(prior) AND _comment IS NULL THEN changed_ids:=array_append(changed_ids,prior.id);CONTINUE;END IF;
  IF _patch<>'{}'::jsonb THEN
   UPDATE public.recon_exceptions SET status=next_row.status,lifecycle_state=next_row.lifecycle_state,priority=next_row.priority,assignee=next_row.assignee,assigned_by=next_row.assigned_by,assigned_at=next_row.assigned_at,due_date=next_row.due_date,root_cause=next_row.root_cause,tags=next_row.tags,labels=next_row.labels,review_state=next_row.review_state,resolution_note=next_row.resolution_note,close_reason=next_row.close_reason,reopen_reason=next_row.reopen_reason,closed_at=next_row.closed_at,reopened_at=next_row.reopened_at,resolved_by=next_row.resolved_by,resolved_at=next_row.resolved_at WHERE id=prior.id AND tenant_id=_tenant_id;
   IF NOT FOUND THEN RAISE EXCEPTION 'Selected case was not updated' USING ERRCODE='42501'; END IF;
  END IF;
  IF _comment IS NOT NULL THEN INSERT INTO public.break_comments(tenant_id,exception_id,author_id,body,internal) VALUES(_tenant_id,prior.id,actor,btrim(_comment),_internal) RETURNING id INTO comment_id; END IF;
  INSERT INTO public.recon_exception_transitions(tenant_id,exception_id,actor_user_id,from_state,to_state,transition_type,reason,context) VALUES(_tenant_id,prior.id,actor,prior.lifecycle_state,next_row.lifecycle_state,CASE WHEN _comment IS NULL THEN 'workflow_update' ELSE 'comment' END,coalesce(_patch->>'reopen_reason',_patch->>'close_reason',_patch->>'resolution_note'),jsonb_build_object('run_id',prior.run_id,'patch',_patch));
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace',CASE WHEN _comment IS NULL THEN 'exception.workflow_update' ELSE 'break.comment.create' END,'recon_exception',prior.id::text,jsonb_build_object('run_id',prior.run_id,'patch',_patch,'comment_id',comment_id));
  changed_ids:=array_append(changed_ids,prior.id);actual_changes:=actual_changes+1;
 END LOOP;
 RETURN jsonb_build_object('ok',true,'ids',to_jsonb(changed_ids),'count',cardinality(changed_ids),'comment_id',comment_id,'changed_count',actual_changes,'noop_count',cardinality(changed_ids)-actual_changes);
END $function$

CREATE OR REPLACE FUNCTION public.save_nrl_rule_atomic(_tenant_id uuid, _definition_id uuid, _rule_id uuid, _config jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); rule_id uuid; fields public.recon_nrl_rules%ROWTYPE;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.recon_definitions d WHERE d.id=_definition_id AND d.tenant_id=_tenant_id) OR NOT public.recon_authoritative_access_decision(_definition_id,'edit') THEN RAISE EXCEPTION 'Current reconciliation edit access required' USING ERRCODE='42501'; END IF;
 fields:=jsonb_populate_record(NULL::public.recon_nrl_rules,_config);
 IF fields.name IS NULL OR length(fields.name) NOT BETWEEN 2 AND 120 OR fields.nrl_source IS NULL OR jsonb_typeof(fields.compiled_rule)<>'object' OR fields.pass_order NOT BETWEEN 1 AND 50 OR fields.enabled IS NULL THEN RAISE EXCEPTION 'Invalid NRL draft'; END IF;
 IF _rule_id IS NULL THEN
  INSERT INTO public.recon_nrl_rules(tenant_id,definition_id,name,description,nrl_source,compiled_rule,pass_order,enabled,validation_errors,created_by) VALUES(_tenant_id,_definition_id,fields.name,fields.description,fields.nrl_source,fields.compiled_rule,fields.pass_order,fields.enabled,'[]',actor) RETURNING id INTO rule_id;
 ELSE
  UPDATE public.recon_nrl_rules SET name=fields.name,description=CASE WHEN _config ? 'description' THEN fields.description ELSE description END,nrl_source=fields.nrl_source,compiled_rule=fields.compiled_rule,pass_order=fields.pass_order,enabled=fields.enabled,validation_errors='[]' WHERE id=_rule_id AND tenant_id=_tenant_id AND definition_id=_definition_id RETURNING id INTO rule_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Rule not in selected reconciliation' USING ERRCODE='42501'; END IF;
 END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','nrl.draft.saved','recon_nrl_rule',rule_id::text,jsonb_build_object('definition_id',_definition_id,'pass_order',fields.pass_order,'source_sha256',encode(extensions.digest(fields.nrl_source,'sha256'),'hex')));
 RETURN rule_id;
END $function$

CREATE OR REPLACE FUNCTION public.list_recon_ordinary_inputs(_tenant_id uuid, _definition_id uuid, _side_id text, _page integer DEFAULT 0, _page_size integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant_id,_definition_id,'run');d public.recon_definitions%ROWTYPE;s jsonb;items jsonb;total bigint;
BEGIN
 IF _page NOT BETWEEN 0 AND 1000000 OR _page_size NOT BETWEEN 1 AND 100 OR _page IS NULL OR _page_size IS NULL
 THEN RAISE EXCEPTION 'rs.finite_input_page_required' USING ERRCODE='22023';END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_definition_required' USING ERRCODE='42501';END IF;
 PERFORM private.recon_run_bound_approved_version(_tenant_id,_definition_id,actor);
 SELECT x.value INTO s FROM jsonb_array_elements(d.sides) x WHERE x.value->>'side_id'=_side_id;
 IF s IS NULL OR private.data_source_child_allows(actor,_tenant_id,(s->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'rs.exact_configured_source_required' USING ERRCODE='42501';END IF;
 SELECT count(*) INTO total FROM public.workspace_data_source_uploads u WHERE u.tenant_id=_tenant_id AND u.data_source_id=(s->>'data_source_id')::uuid
 AND (s->>'upload_id' IS NULL OR u.id::text=s->>'upload_id');
 SELECT coalesce(jsonb_agg(jsonb_build_object('upload_id',u.id,'data_source_id',u.data_source_id,'arrival_at',u.created_at,'row_count',u.row_count,
  'fixed_approved_or_configured_pin',s->>'upload_id' IS NOT NULL) ORDER BY u.created_at DESC,u.id DESC),'[]') INTO items
 FROM (SELECT u.id,u.data_source_id,u.created_at,u.row_count FROM public.workspace_data_source_uploads u WHERE u.tenant_id=_tenant_id
  AND u.data_source_id=(s->>'data_source_id')::uuid AND (s->>'upload_id' IS NULL OR u.id::text=s->>'upload_id') ORDER BY u.created_at DESC,u.id DESC
  OFFSET _page*_page_size LIMIT _page_size) u;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'definition_id',_definition_id,'side_id',_side_id,
  'input_options',items,'total',total::text,'page',_page,'page_size',_page_size,'has_next',((_page::bigint+1)*_page_size)<total,
  'automatic_latest_selection',false,'original_source_rows_returned',false);
END $function$

CREATE OR REPLACE FUNCTION public.review_proposed_match_scoped(_tenant_id uuid, _match_id uuid, _decision text, _note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE proposal public.proposed_matches%ROWTYPE; run public.recon_runs%ROWTYPE; actor uuid:=auth.uid();
BEGIN
 SELECT * INTO proposal FROM public.proposed_matches WHERE id=_match_id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Proposal unavailable in current scope' USING ERRCODE='42501'; END IF;
 SELECT * INTO run FROM public.recon_runs WHERE id=proposal.run_id AND tenant_id=_tenant_id;
 IF NOT FOUND OR proposal.definition_id IS DISTINCT FROM run.definition_id OR NOT public.recon_authoritative_access_decision(run.definition_id,'approve') THEN RAISE EXCEPTION 'Current scoped approval required' USING ERRCODE='42501'; END IF;
 IF run.run_by IS NULL OR run.run_by=actor THEN RAISE EXCEPTION 'Independent reviewer and known run provenance required' USING ERRCODE='42501'; END IF;
 IF _decision='accepted' AND (jsonb_typeof(proposal.members)<>'object' OR NOT EXISTS(SELECT 1 FROM jsonb_each(proposal.members)) OR EXISTS(SELECT 1 FROM jsonb_each(proposal.members) WHERE key NOT IN ('A','B','C') OR jsonb_typeof(value)<>'array' OR value='[]')) THEN RAISE EXCEPTION 'Source members unavailable; use governed manual matching'; END IF;
 RETURN public.review_proposed_match_atomic(_tenant_id,_match_id,_decision,_note);
END $function$

CREATE OR REPLACE FUNCTION private.rs_prior_ordinary_policy(_tenant uuid, _definition uuid, _business_date date, _pins jsonb, _key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');q private.rs_requests%ROWTYPE;p jsonb;normalized jsonb;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE tenant_id=_tenant AND definition_id=_definition AND actor_id=actor AND request_key=_key;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT policy INTO p FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=_definition AND policy_id=(q.intent->>'policy_id')::uuid AND version=q.intent->>'policy_version';
 IF _pins IS NOT NULL THEN SELECT jsonb_agg(x.value ORDER BY x.value->>'side_id') INTO normalized FROM jsonb_array_elements(_pins) x;END IF;
 IF p->>'policy_kind' IS DISTINCT FROM 'ordinary_native_snapshot' OR p->>'business_date' IS DISTINCT FROM _business_date::text
 OR _pins IS NOT NULL AND normalized IS DISTINCT FROM p->'pins' THEN RAISE EXCEPTION 'rs.request_key_conflict' USING ERRCODE='PT409';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',_definition,'business_date',p->>'business_date',
  'policy_id',p->>'policy_id','policy_version',p->>'version','pins',p->'pins','input_proofs',p->'input_proofs',
  'expected_definition_sha256',p->>'configuration_sha256','approved_revision_id',p->>'approved_revision_id','configuration_authority',p->>'configuration_authority',
  'cohort_mode','explicit_snapshot_selection','market_calendar_available',false,'feed_timing_available',false,'replayed_policy',true);
END $function$

CREATE OR REPLACE FUNCTION public.review_proposed_matches_scoped(_tenant_id uuid, _match_ids uuid[], _decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE item uuid; n integer:=0;
BEGIN
 IF _match_ids IS NULL OR cardinality(_match_ids) NOT BETWEEN 1 AND 100 OR (SELECT count(DISTINCT id) FROM unnest(_match_ids) x(id))<>cardinality(_match_ids) THEN RAISE EXCEPTION 'Select 1 to 100 distinct proposals'; END IF;
 FOR item IN SELECT id FROM unnest(_match_ids) x(id) ORDER BY id LOOP PERFORM public.review_proposed_match_scoped(_tenant_id,item,_decision,NULL);n:=n+1; END LOOP;
 RETURN jsonb_build_object('ok',true,'count',n);
END $function$

CREATE OR REPLACE FUNCTION public.resolve_recon_ordinary_cohort(_tenant_id uuid, _definition_id uuid, _business_date date, _pins jsonb, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE result jsonb;p jsonb;
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'run');
 PERFORM 1 FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_definition_required' USING ERRCODE='42501';END IF;
 IF _request_key IS NULL THEN RAISE EXCEPTION 'rs.explicit_request_key_required' USING ERRCODE='22023';END IF;
 result:=private.rs_prior_ordinary_policy(_tenant_id,_definition_id,_business_date,_pins,_request_key);
 IF result IS NOT NULL THEN RETURN result;END IF;
 result:=private.rs_resolve_ordinary_policy(_tenant_id,_definition_id,_business_date,_pins);
 FOR p IN SELECT x.value FROM jsonb_array_elements(result->'input_proofs') x LOOP
  PERFORM 1 FROM public.workspace_data_sources WHERE id=(p->>'data_source_id')::uuid AND tenant_id=_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_source_required' USING ERRCODE='42501';END IF;
  PERFORM 1 FROM public.workspace_data_source_uploads WHERE id=(p->>'upload_id')::uuid AND tenant_id=_tenant_id AND data_source_id=(p->>'data_source_id')::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_exact_upload_required' USING ERRCODE='42501';END IF;
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.request_task_eod_signoff_atomic(_tenant_id uuid, _period date, _run_ids uuid[], _note text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); snapshot jsonb; old public.eod_signoffs%ROWTYPE; new_id uuid; input_hash text; ids uuid[];
BEGIN
 IF actor IS NULL OR _request_key IS NULL OR _period IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active AND role::text IN ('tenant_admin','tenant_analyst')) THEN RAISE EXCEPTION 'Active preparer required' USING ERRCODE='42501'; END IF;
 SELECT array_agg(x ORDER BY x) INTO ids FROM (SELECT DISTINCT unnest(_run_ids) x) s;
 IF ids IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 100 OR cardinality(ids)<>cardinality(_run_ids) OR array_position(ids,NULL) IS NOT NULL OR (SELECT count(*) FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids))<>cardinality(ids) OR EXISTS(SELECT 1 FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) AND NOT public.recon_authoritative_access_decision(definition_id,'view')) THEN RAISE EXCEPTION 'Current retained Run scope required' USING ERRCODE='42501'; END IF;
 input_hash:=encode(extensions.digest(jsonb_build_object('period',_period,'runs',ids,'note',coalesce(_note,''))::text,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':'||actor::text||':'||_request_key::text,0));
 SELECT * INTO old FROM public.eod_signoffs WHERE tenant_id=_tenant_id AND prepared_by=actor AND request_key=_request_key FOR UPDATE;
 IF FOUND THEN IF old.request_hash IS DISTINCT FROM input_hash THEN RAISE EXCEPTION 'Request key changed' USING ERRCODE='22023'; END IF; RETURN jsonb_build_object('id',old.id,'replayed',true); END IF;
 PERFORM 1 FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) ORDER BY id FOR SHARE;
 snapshot:=private.task_eod_snapshot(_tenant_id,_run_ids);
 IF EXISTS(SELECT 1 FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) AND started_at>=((_period+1)::timestamp AT TIME ZONE 'UTC')) THEN RAISE EXCEPTION 'Selected Run is after the closing date' USING ERRCODE='22023'; END IF;
 IF coalesce(length(_note),0)>2000 THEN RAISE EXCEPTION 'Closing note is too long' USING ERRCODE='22023'; END IF;
 IF NOT (snapshot->'checks'->>'manual_reviews_clear')::boolean OR (((snapshot->>'open_exceptions')::int+(snapshot->>'waived_exceptions')::int)>0 AND length(btrim(coalesce(_note,'')))<10) THEN RAISE EXCEPTION 'Complete manual reviews and explain open exceptions' USING ERRCODE='22023'; END IF;
 INSERT INTO public.eod_signoffs(tenant_id,period_date,scope,status,prepared_by,prepared_at,metrics,note,request_key,request_hash,retained_run_refs,checks_snapshot,scope_snapshot_hash)
 VALUES(_tenant_id,_period,'selected_runs','prepared',actor,now(),jsonb_build_object('open_at_signoff',(snapshot->>'open_exceptions')::int,'waived_at_signoff',(snapshot->>'waived_exceptions')::int,'run_count',(snapshot->>'run_count')::int),_note,_request_key,input_hash,snapshot->'run_refs',snapshot->'checks',snapshot->>'snapshot_hash') RETURNING id INTO new_id;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','eod.prepare','eod_signoffs',new_id::text,jsonb_build_object('period',_period,'run_refs',snapshot->'run_refs','checks',snapshot->'checks','scope_hash',snapshot->>'snapshot_hash','request_key',_request_key));
 RETURN jsonb_build_object('id',new_id,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION private.ticket_message_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE t public.support_tickets%ROWTYPE; actor uuid:=auth.uid(); manager boolean;
BEGIN
 SELECT * INTO t FROM public.support_tickets WHERE id=NEW.ticket_id FOR UPDATE;
 PERFORM id FROM public.tenant_members WHERE user_id=actor AND tenant_id=t.tenant_id FOR SHARE;
 manager:=private.ticket_manager(actor,t.tenant_id);
 IF actor IS NULL OR t.id IS NULL OR NEW.author_id<>actor OR
    NOT (manager OR (private.ticket_active_member(actor,t.tenant_id) AND (t.created_by=actor OR private.ticket_responder(actor,t.tenant_id)))) OR
    (NEW.internal_note AND NOT manager) THEN RAISE EXCEPTION 'Current ticket reply permission required' USING ERRCODE='42501'; END IF;
 IF length(NEW.body) NOT BETWEEN 1 AND 50000 THEN RAISE EXCEPTION 'Bounded ticket message required' USING ERRCODE='22023'; END IF;
 NEW.created_at:=statement_timestamp();
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.apply_nrl_rule_to_draft_atomic(_tenant_id uuid, _definition_id uuid, _rule_id uuid, _compiled jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE def public.recon_definitions%ROWTYPE; saved public.recon_nrl_rules%ROWTYPE; rule jsonb; fields jsonb; ref jsonb; binding jsonb; cols jsonb;
BEGIN
 SELECT * INTO def FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR NOT public.recon_authoritative_access_decision(def.id,'edit') THEN RAISE EXCEPTION 'Current edit scope required' USING ERRCODE='42501'; END IF;
 IF def.environment NOT IN ('development','staging') OR def.governance_state NOT IN ('development_draft','staging_copy') THEN RAISE EXCEPTION 'Governed editable copy required' USING ERRCODE='42501'; END IF;
 SELECT * INTO saved FROM public.recon_nrl_rules WHERE id=_rule_id AND tenant_id=_tenant_id AND definition_id=def.id AND enabled;
 IF NOT FOUND OR saved.compiled_rule IS DISTINCT FROM _compiled OR _compiled->>'kind'<>'match' OR _compiled ? 'lookup' THEN RAISE EXCEPTION 'Saved executable rule preimage changed'; END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(jsonb_build_array(_compiled#>'{match,left}',_compiled#>'{match,right}')||coalesce((SELECT jsonb_agg(x) FROM (SELECT value->'left' x FROM jsonb_array_elements(coalesce(_compiled->'where','[]')) UNION ALL SELECT value->'right' FROM jsonb_array_elements(coalesce(_compiled->'where','[]')) WHERE jsonb_typeof(value->'right')='object') refs),'[]')) LOOP
  SELECT value INTO binding FROM jsonb_array_elements(def.sides) WHERE value->>'side_id'=ref->>'side';
  IF NOT FOUND THEN RAISE EXCEPTION 'Rule side not bound'; END IF;
  SELECT to_jsonb(u.columns) INTO cols FROM public.workspace_data_source_uploads u WHERE u.tenant_id=_tenant_id AND u.data_source_id=(binding->>'data_source_id')::uuid AND (binding->>'upload_id' IS NULL OR u.id=(binding->>'upload_id')::uuid) ORDER BY u.created_at DESC,u.id DESC LIMIT 1;
  IF cols IS NULL OR jsonb_typeof(cols)<>'array' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(cols) c WHERE (jsonb_typeof(c)='string' AND c#>>'{}'=ref->>'column') OR c->>'name'=ref->>'column') THEN RAISE EXCEPTION 'Current source field binding unavailable'; END IF;
 END LOOP;
 fields:=jsonb_build_object(_compiled#>>'{match,left,side}',_compiled#>>'{match,left,column}',_compiled#>>'{match,right,side}',_compiled#>>'{match,right,column}');
 rule:=jsonb_build_object('id','nrl:'||saved.id::text,'kind','nrl_rule','description',saved.name,'fields',fields,'params',jsonb_build_object('nrl_rule',_compiled));
 UPDATE public.recon_definitions SET rules=coalesce((SELECT jsonb_agg(value) FROM jsonb_array_elements(def.rules) WHERE value->>'id'<>'nrl:'||saved.id::text),'[]'::jsonb)||jsonb_build_array(rule) WHERE id=def.id AND tenant_id=_tenant_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Definition not updated' USING ERRCODE='42501'; END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(auth.uid(),_tenant_id,'workspace','nrl.draft.applied','recon_definition',def.id::text,jsonb_build_object('rule_id',saved.id,'pass',saved.pass_order));
 RETURN jsonb_build_object('ok',true,'definition_id',def.id);
END $function$

CREATE OR REPLACE FUNCTION public.disable_exception_assignment_rule(_tenant_id uuid, _rule_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE row_id uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=auth.uid() AND active AND role='tenant_admin') THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';END IF;
 UPDATE public.exception_assignment_rules SET enabled=false,updated_at=now() WHERE id=_rule_id AND tenant_id=_tenant_id RETURNING id INTO row_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Assignment rule unavailable' USING ERRCODE='42501';END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(auth.uid(),_tenant_id,'tenant','assignment_rule.disabled','exception_assignment_rule',row_id::text,'{"history_retained":true}');
 RETURN jsonb_build_object('ok',true,'id',row_id,'enabled',false);
END $function$

CREATE OR REPLACE FUNCTION private.manual_match_group_evidence(_tenant uuid, _run uuid, _exceptions uuid[], _action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE r public.recon_runs%ROWTYPE; d public.recon_definitions%ROWTYPE; e record; member_map jsonb; ids uuid[]; expected integer; source_json jsonb; cardinality_text text;
BEGIN
 IF auth.uid() IS NULL OR _exceptions IS NULL OR cardinality(_exceptions) NOT BETWEEN 1 AND 100 OR array_position(_exceptions,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Select current exception groups' USING ERRCODE='22023'; END IF;
 SELECT array_agg(x ORDER BY x) INTO ids FROM (SELECT DISTINCT unnest(_exceptions) x) s;
 IF cardinality(ids)<>cardinality(_exceptions) THEN RAISE EXCEPTION 'Duplicate exception group' USING ERRCODE='22023'; END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant;
 SELECT * INTO d FROM public.recon_definitions WHERE id=r.definition_id AND tenant_id=_tenant;
 IF r.id IS NULL OR d.id IS NULL OR r.status::text<>'completed' OR NOT public.recon_authoritative_access_decision(d.id,_action) THEN RAISE EXCEPTION 'Completed Run access required' USING ERRCODE='42501'; END IF;
 expected:=CASE d.recon_type::text WHEN 'two_sided' THEN 2 WHEN 'three_sided' THEN 3 ELSE 0 END;
 IF expected=0 THEN RAISE EXCEPTION 'Manual matching needs two or three sources' USING ERRCODE='22023'; END IF;
 IF (SELECT count(*) FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=_run AND id=ANY(ids) AND status::text IN ('open','investigating'))<>cardinality(ids) THEN RAISE EXCEPTION 'Exception group is unavailable or already resolved' USING ERRCODE='42501'; END IF;
 FOR e IN SELECT payload FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=_run AND id=ANY(ids) LOOP
  IF jsonb_typeof(e.payload->'members') IS DISTINCT FROM 'object' OR EXISTS(SELECT 1 FROM jsonb_each(e.payload->'members') m WHERE m.key NOT IN ('SOURCE_A','SOURCE_B','SOURCE_C') OR jsonb_typeof(m.value)<>'array') THEN RAISE EXCEPTION 'Persisted source members unavailable' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_each(e.payload->'members') m CROSS JOIN LATERAL jsonb_array_elements(m.value) v WHERE jsonb_typeof(v.value)<>'object') THEN RAISE EXCEPTION 'Persisted member rows must be objects' USING ERRCODE='22023'; END IF;
 END LOOP;
 WITH groups AS (SELECT id,payload->'members' members FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=_run AND id=ANY(ids)),
 parts AS (SELECT g.id,s.key,a.value,a.ordinality FROM groups g CROSS JOIN LATERAL jsonb_each(g.members) s CROSS JOIN LATERAL jsonb_array_elements(s.value) WITH ORDINALITY a),
 sides AS (SELECT key,jsonb_agg(value ORDER BY id,ordinality) rows FROM parts GROUP BY key)
 SELECT jsonb_object_agg(key,rows),string_agg(jsonb_array_length(rows)::text,':' ORDER BY key) INTO member_map,cardinality_text FROM sides;
 IF (SELECT count(*) FROM jsonb_object_keys(coalesce(member_map,'{}')))<>expected OR EXISTS(SELECT 1 FROM jsonb_each(member_map) m WHERE jsonb_array_length(m.value)=0 OR (expected=2 AND m.key='SOURCE_C')) THEN RAISE EXCEPTION 'Select complete source groups; no missing counterpart is invented' USING ERRCODE='22023'; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',id,'members',payload->'members') ORDER BY id) INTO source_json FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=_run AND id=ANY(ids);
 RETURN jsonb_build_object('definition_id',d.id,'recon_name',d.name,'recon_code',d.recon_code,'run_uid',r.run_uid,'exception_ids',ids,'members',member_map,'cardinality',cardinality_text,'source_hash',encode(extensions.digest(source_json::text,'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION public.propose_manual_match_atomic(_tenant_id uuid, _run_id uuid, _exception_ids uuid[], _rationale text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); r public.recon_runs%ROWTYPE; old public.manual_match_approvals%ROWTYPE; ids uuid[]; evidence jsonb; input_hash text; new_id uuid;
BEGIN
 IF actor IS NULL OR _request_key IS NULL OR length(btrim(coalesce(_rationale,''))) NOT BETWEEN 10 AND 2000 OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active AND role::text IN ('tenant_admin','tenant_analyst')) THEN RAISE EXCEPTION 'Active maker and explanation required' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id FOR UPDATE;
 IF r.id IS NULL OR NOT public.recon_authoritative_access_decision(r.definition_id,'edit') THEN RAISE EXCEPTION 'Run edit access required' USING ERRCODE='42501'; END IF;
 SELECT array_agg(x ORDER BY x) INTO ids FROM (SELECT DISTINCT unnest(_exception_ids) x) s;
 IF ids IS NULL OR cardinality(ids)<>cardinality(_exception_ids) THEN RAISE EXCEPTION 'Select distinct exception groups' USING ERRCODE='22023'; END IF;
 input_hash:=encode(extensions.digest(jsonb_build_object('run',_run_id,'exceptions',ids,'rationale',btrim(_rationale))::text,'sha256'),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':'||actor::text||':'||_request_key::text,0));
 SELECT * INTO old FROM public.manual_match_approvals WHERE tenant_id=_tenant_id AND proposed_by=actor AND request_key=_request_key FOR UPDATE;
 IF FOUND THEN IF old.request_hash IS DISTINCT FROM input_hash THEN RAISE EXCEPTION 'Request key reused with changed evidence' USING ERRCODE='22023'; END IF; RETURN jsonb_build_object('id',old.id,'replayed',true); END IF;
 PERFORM 1 FROM public.recon_exceptions WHERE tenant_id=_tenant_id AND run_id=_run_id AND id=ANY(ids) ORDER BY id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.manual_match_approvals WHERE tenant_id=_tenant_id AND run_id=_run_id AND status='pending' AND exception_ids&&ids) THEN RAISE EXCEPTION 'Selected group already has a pending request' USING ERRCODE='23505'; END IF;
 evidence:=private.manual_match_group_evidence(_tenant_id,_run_id,ids,'edit');
 INSERT INTO public.manual_match_approvals(tenant_id,run_id,exception_ids,members,cardinality,rationale,proposed_by,request_key,request_hash)
 VALUES(_tenant_id,_run_id,ids,evidence->'members',evidence->>'cardinality',btrim(_rationale),actor,_request_key,input_hash) RETURNING id INTO new_id;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,_tenant_id,'workspace','manual_match.propose','manual_match_approvals',new_id::text,jsonb_build_object('run_id',_run_id,'run_uid',r.run_uid,'definition_id',r.definition_id,'request_key',_request_key,'source_hash',evidence->>'source_hash'));
 RETURN jsonb_build_object('id',new_id,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION private.task_eod_snapshot(_tenant uuid, _runs uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE ids uuid[]; r record; refs jsonb; states jsonb; pending jsonb; body jsonb; open_count integer; waived_count integer;
BEGIN
 IF auth.uid() IS NULL OR _runs IS NULL OR cardinality(_runs) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Select retained Runs' USING ERRCODE='22023'; END IF;
 SELECT array_agg(x ORDER BY x) INTO ids FROM (SELECT DISTINCT unnest(_runs) x) s;
 IF cardinality(ids)<>cardinality(_runs) OR array_position(ids,NULL) IS NOT NULL OR (SELECT count(*) FROM public.recon_runs WHERE tenant_id=_tenant AND id=ANY(ids))<>cardinality(ids) THEN RAISE EXCEPTION 'Run scope unavailable' USING ERRCODE='42501'; END IF;
 FOR r IN SELECT * FROM public.recon_runs WHERE tenant_id=_tenant AND id=ANY(ids) LOOP
  IF NOT public.recon_authoritative_access_decision(r.definition_id,'view') OR r.run_uid IS NULL OR r.status::text<>'completed' OR r.started_at IS NULL OR r.completed_at IS NULL OR jsonb_typeof(r.stats->'total_rows') IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Completed, counted Run evidence required' USING ERRCODE='42501'; END IF;
 END LOOP;
 SELECT jsonb_agg(jsonb_build_object('run_id',rr.id,'run_uid',rr.run_uid,'definition_id',rr.definition_id,'recon_name',d.name,'recon_code',d.recon_code,'stats',rr.stats,'started_at',rr.started_at,'completed_at',rr.completed_at) ORDER BY rr.id) INTO refs FROM public.recon_runs rr JOIN public.recon_definitions d ON d.id=rr.definition_id AND d.tenant_id=rr.tenant_id WHERE rr.tenant_id=_tenant AND rr.id=ANY(ids);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'run_id',run_id,'status',status,'updated_at',updated_at) ORDER BY id),'[]'::jsonb),count(*) FILTER(WHERE status::text IN ('open','investigating')),count(*) FILTER(WHERE status::text='wont_fix') INTO states,open_count,waived_count FROM public.recon_exceptions WHERE tenant_id=_tenant AND run_id=ANY(ids);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'run_id',run_id) ORDER BY id),'[]'::jsonb) INTO pending FROM public.manual_match_approvals WHERE tenant_id=_tenant AND run_id=ANY(ids) AND status='pending';
 body:=jsonb_build_object('run_refs',refs,'exception_state',states,'pending_manual',pending,'open_exceptions',open_count,'waived_exceptions',waived_count,'run_count',cardinality(ids));
 RETURN body||jsonb_build_object('snapshot_hash',encode(extensions.digest(body::text,'sha256'),'hex'),'checks',jsonb_build_object('completed_runs',true,'counted_evidence',true,'manual_reviews_clear',jsonb_array_length(pending)=0,'exceptions_clear',open_count=0 AND waived_count=0));
END $function$

CREATE OR REPLACE FUNCTION private.rs_read_group_intents(_tenant uuid, _definition uuid, _run uuid, _group uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'read');g private.rs_groups%ROWTYPE;result jsonb;
BEGIN
 SELECT * INTO g FROM private.rs_groups WHERE run_id=_run AND native_id=_group;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND definition_id=_definition)
 THEN RAISE EXCEPTION 'rs.exact_group_history_required' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'actor_id',e.actor_id,'occurred_at',e.occurred_at,'payload',e.payload) ORDER BY e.occurred_at,e.id),'[]') INTO result
 FROM private.rs_events e WHERE e.run_id=_run AND e.kind='group_action_requested' AND e.payload->>'group_id'=_group::text;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.request_recon_group_action(_tenant_id uuid, _definition_id uuid, _run_id uuid, _group_id uuid, _action text, _detail text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'edit');
 PERFORM 1 FROM public.recon_runs WHERE id=_run_id AND tenant_id=_tenant_id AND definition_id=_definition_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_group_run_required' USING ERRCODE='42501';END IF;
 RETURN private.rs_record_group_intent(_tenant_id,_definition_id,_run_id,_group_id,_action,_detail,_request_key);
END $function$

CREATE OR REPLACE FUNCTION public.decide_task_eod_signoff_atomic(_tenant_id uuid, _id uuid, _decision text, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); row public.eod_signoffs%ROWTYPE; snapshot jsonb; ids uuid[]; prior_flag text; r record;
BEGIN
 IF actor IS NULL OR _decision NOT IN ('approved','rejected') OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 10 AND 2000 OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active AND role::text='tenant_admin') THEN RAISE EXCEPTION 'Independent administrator and decision note required' USING ERRCODE='42501'; END IF;
 SELECT * INTO row FROM public.eod_signoffs WHERE id=_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR row.prepared_by=actor OR row.status<>'prepared' OR row.locked OR row.request_key IS NULL OR row.retained_run_refs IS NULL THEN RAISE EXCEPTION 'Current independent scoped request required' USING ERRCODE='42501'; END IF;
 IF row.version IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'Request version changed; request a fresh sign-off' USING ERRCODE='22023'; END IF;
 IF (SELECT count(*) FROM public.audit_log WHERE tenant_id=_tenant_id AND resource_id=_id::text AND action='eod.prepare' AND actor_user_id=row.prepared_by)<>1 THEN RAISE EXCEPTION 'Retained preparer request audit required' USING ERRCODE='42501'; END IF;
 SELECT array_agg((v->>'run_id')::uuid ORDER BY v->>'run_id') INTO ids FROM jsonb_array_elements(row.retained_run_refs) v;
 PERFORM 1 FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) ORDER BY id FOR UPDATE;
 FOR r IN SELECT definition_id FROM public.recon_runs WHERE tenant_id=_tenant_id AND id=ANY(ids) LOOP IF NOT public.recon_authoritative_access_decision(r.definition_id,'approve') THEN RAISE EXCEPTION 'Run reviewer scope required' USING ERRCODE='42501'; END IF; END LOOP;
 IF _decision='approved' THEN
  PERFORM 1 FROM public.recon_exceptions WHERE tenant_id=_tenant_id AND run_id=ANY(ids) ORDER BY id FOR SHARE;
  snapshot:=private.task_eod_snapshot(_tenant_id,ids);
  IF snapshot->>'snapshot_hash' IS DISTINCT FROM row.scope_snapshot_hash OR NOT (snapshot->'checks'->>'manual_reviews_clear')::boolean THEN RAISE EXCEPTION 'Evidence changed; request a fresh sign-off' USING ERRCODE='22023'; END IF;
 END IF;
 prior_flag:=current_setting('app.signoff_advance_ok',true); PERFORM set_config('app.signoff_advance_ok','on',true);
 UPDATE public.eod_signoffs SET status=_decision,approved_by=actor,approved_at=now(),decision_note=btrim(_reason),locked=(_decision='approved'),version=coalesce(version,0)+1,updated_at=now() WHERE id=_id AND tenant_id=_tenant_id;
 PERFORM set_config('app.signoff_advance_ok',coalesce(prior_flag,'off'),true);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','eod.'||_decision,'eod_signoffs',_id::text,jsonb_build_object('period',row.period_date,'run_refs',row.retained_run_refs,'checks',row.checks_snapshot,'scope_hash',row.scope_snapshot_hash,'reason',btrim(_reason)));
 RETURN jsonb_build_object('ok',true,'id',_id,'status',_decision);
END $function$

CREATE OR REPLACE FUNCTION private.ticket_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid := auth.uid(); manager boolean; assigned boolean; p public.sla_policies%ROWTYPE;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'Authenticated ticket actor required' USING ERRCODE='42501'; END IF;
 PERFORM id FROM public.tenant_members WHERE user_id=actor AND tenant_id=NEW.tenant_id FOR SHARE;
 PERFORM id FROM public.platform_roles WHERE user_id=actor AND role='platform_admin' FOR SHARE;
 IF TG_OP='INSERT' THEN
   IF NEW.created_by<>actor OR NEW.status<>'open' OR NEW.first_response_at IS NOT NULL
      OR NEW.resolved_at IS NOT NULL OR NEW.closed_at IS NOT NULL THEN
     RAISE EXCEPTION 'New ticket identity/state must belong to requester' USING ERRCODE='42501';
   END IF;
   IF (NEW.scope='platform' AND (NEW.tenant_id IS NOT NULL OR NOT private.is_platform_admin(actor)))
      OR (NEW.scope<>'platform' AND NOT private.ticket_active_member(actor,NEW.tenant_id)) THEN
     RAISE EXCEPTION 'Current active ticket scope required' USING ERRCODE='42501';
   END IF;
   NEW.ref := 'FVI-'||upper(replace(NEW.id::text,'-',''));
   NEW.created_at := statement_timestamp();
   NEW.sla_revision := 0;
 ELSE
   IF ROW(NEW.id,NEW.ref,NEW.tenant_id,NEW.scope,NEW.created_by,NEW.created_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.ref,OLD.tenant_id,OLD.scope,OLD.created_by,OLD.created_at) THEN
     RAISE EXCEPTION 'Ticket identity/scope is immutable' USING ERRCODE='42501';
   END IF;
   manager := private.ticket_manager(actor,OLD.tenant_id);
   assigned := coalesce(OLD.assignee_id=actor AND private.ticket_responder(actor,OLD.tenant_id),false);
   IF NOT manager AND NOT assigned AND NOT (OLD.created_by=actor AND private.ticket_active_member(actor,OLD.tenant_id)) THEN
     RAISE EXCEPTION 'Current ticket update permission required' USING ERRCODE='42501';
   END IF;
   IF NOT manager AND (to_jsonb(NEW)-ARRAY['status','updated_at','first_response_at','resolved_at','closed_at','csat_score','csat_comment'])
       IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','updated_at','first_response_at','resolved_at','closed_at','csat_score','csat_comment']) THEN
     RAISE EXCEPTION 'Only managers may change ticket assignment/configuration' USING ERRCODE='42501';
   END IF;
   IF ROW(NEW.csat_score,NEW.csat_comment) IS DISTINCT FROM ROW(OLD.csat_score,OLD.csat_comment) AND (actor<>OLD.created_by OR NOT private.ticket_active_member(actor,OLD.tenant_id)) THEN RAISE EXCEPTION 'Only current requester records customer feedback' USING ERRCODE='42501'; END IF;
   IF length(NEW.csat_comment)>1000 THEN RAISE EXCEPTION 'Bounded customer feedback required' USING ERRCODE='22023'; END IF;
   IF NEW.first_response_at IS DISTINCT FROM OLD.first_response_at AND pg_trigger_depth()<2 THEN
     RAISE EXCEPTION 'First response is recorded by the actual public message' USING ERRCODE='42501';
   END IF;
   IF ROW(NEW.sla_snapshot,NEW.sla_started_at,NEW.first_response_due_at,NEW.resolution_due_at)
      IS DISTINCT FROM ROW(OLD.sla_snapshot,OLD.sla_started_at,OLD.first_response_due_at,OLD.resolution_due_at) THEN
     RAISE EXCEPTION 'SLA deadlines are generated from configured policy' USING ERRCODE='42501';
   END IF;
   IF NEW.sla_revision<>OLD.sla_revision AND (NOT manager OR NEW.sla_revision<>OLD.sla_revision+1) THEN
     RAISE EXCEPTION 'SLA revision requires a manager policy decision' USING ERRCODE='42501';
   END IF;
   -- Completion events come from this transition, never requester-supplied dates.
   IF NEW.status IS DISTINCT FROM OLD.status THEN
     IF NEW.status='resolved' THEN NEW.resolved_at:=statement_timestamp(); NEW.closed_at:=NULL;
     ELSIF NEW.status='closed' THEN NEW.closed_at:=statement_timestamp();
     ELSE NEW.resolved_at:=NULL; NEW.closed_at:=NULL; END IF;
   ELSE NEW.resolved_at:=OLD.resolved_at; NEW.closed_at:=OLD.closed_at; END IF;
 END IF;
 manager := private.ticket_manager(actor,NEW.tenant_id);
 IF TG_OP='INSERT' OR NEW.assignee_id IS DISTINCT FROM OLD.assignee_id THEN
   IF NEW.assignee_id IS NOT NULL THEN
     PERFORM id FROM public.tenant_members WHERE user_id=NEW.assignee_id AND tenant_id=NEW.tenant_id FOR SHARE;
     IF NOT manager THEN RAISE EXCEPTION 'Only managers assign tickets' USING ERRCODE='42501'; END IF;
     IF (NEW.scope='platform' AND NOT private.is_platform_admin(NEW.assignee_id))
        OR (NEW.scope<>'platform' AND NOT (private.ticket_active_member(NEW.assignee_id,NEW.tenant_id)
          AND (private.ticket_manager(NEW.assignee_id,NEW.tenant_id) OR private.ticket_responder(NEW.assignee_id,NEW.tenant_id)))) THEN
       RAISE EXCEPTION 'Assignee must be current permitted member of ticket scope' USING ERRCODE='42501';
     END IF;
   END IF;
 END IF;
 IF NEW.category NOT IN ('general_question','bug','feature_request','design_feedback','data_quality','integration',
    'access_permissions','billing','security_concern','compliance','performance','training','documentation','incident','other') THEN
   RAISE EXCEPTION 'Unsupported ticket category' USING ERRCODE='22023';
 END IF;
 IF TG_OP='INSERT' THEN
   IF NEW.sla_policy_id IS NULL AND NEW.tenant_id IS NOT NULL THEN
     SELECT * INTO p FROM public.sla_policies WHERE tenant_id=NEW.tenant_id AND priority=NEW.priority;
     NEW.sla_policy_id:=p.id;
   END IF;
 END IF;
 IF TG_OP='INSERT' OR NEW.sla_policy_id IS DISTINCT FROM OLD.sla_policy_id OR NEW.sla_revision<>OLD.sla_revision THEN
   IF TG_OP='UPDATE' AND NOT manager THEN RAISE EXCEPTION 'Manager SLA decision required' USING ERRCODE='42501'; END IF;
   IF NEW.sla_policy_id IS NULL THEN
     NEW.sla_snapshot:=NULL; NEW.sla_started_at:=NULL; NEW.first_response_due_at:=NULL; NEW.resolution_due_at:=NULL;
   ELSE
     SELECT * INTO p FROM public.sla_policies WHERE id=NEW.sla_policy_id FOR SHARE;
     IF NEW.status IN ('resolved','closed') THEN RAISE EXCEPTION 'No new SLA baseline for a completed case' USING ERRCODE='22023'; END IF;
     IF p.id IS NULL OR p.tenant_id IS DISTINCT FROM NEW.tenant_id OR p.priority<>NEW.priority
        OR p.first_response_mins<=0 OR p.resolution_mins<=0 THEN
       RAISE EXCEPTION 'Valid configured policy for ticket tenant/priority required' USING ERRCODE='22023';
     END IF;
     NEW.sla_started_at:=statement_timestamp();
     NEW.sla_snapshot:=jsonb_build_object('policy_id',p.id,'name',p.name,'priority',p.priority,
       'first_response_mins',p.first_response_mins,'resolution_mins',p.resolution_mins,'started_at',NEW.sla_started_at);
     NEW.first_response_due_at:=NEW.sla_started_at+make_interval(mins=>p.first_response_mins);
     NEW.resolution_due_at:=NEW.sla_started_at+make_interval(mins=>p.resolution_mins);
   END IF;
 END IF;
 IF NEW.recon_id IS NOT NULL AND (TG_OP='INSERT' OR NEW.recon_id IS DISTINCT FROM OLD.recon_id) AND NOT EXISTS(SELECT FROM public.recon_definitions WHERE id=NEW.recon_id AND tenant_id=NEW.tenant_id) THEN RAISE EXCEPTION 'Reconciliation association outside ticket tenant' USING ERRCODE='42501'; END IF;
 IF (TG_OP='INSERT' OR NEW.attachments IS DISTINCT FROM OLD.attachments OR NEW.body IS DISTINCT FROM OLD.body) AND (length(trim(NEW.subject))<3 OR length(NEW.subject)>160 OR length(NEW.body)>50000
    OR jsonb_typeof(NEW.attachments)<>'array' OR jsonb_array_length(NEW.attachments)>5) THEN
   RAISE EXCEPTION 'Invalid bounded ticket content' USING ERRCODE='22023';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.read_recon_execution_queue(_tenant_id uuid, _definition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE result jsonb;item jsonb;
BEGIN
 PERFORM private.rs_actor(_tenant_id,_definition_id,'read');result:=private.rs_queue_snapshot(_tenant_id,_definition_id);
 FOR item IN SELECT x.value FROM jsonb_array_elements(result->'queue') x LOOP
  PERFORM 1 FROM public.recon_runs WHERE id=(item->>'id')::uuid AND tenant_id=_tenant_id AND definition_id=_definition_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.queue_rlp_scope_changed' USING ERRCODE='42501';END IF;
 END LOOP;RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.rs_record_group_intent(_tenant uuid, _definition uuid, _run uuid, _group uuid, _action text, _detail text, _key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'edit');g private.rs_groups%ROWTYPE;e private.rs_events%ROWTYPE;intent jsonb;
BEGIN
 IF _key IS NULL OR (_action IN('comment','label','accept','rematch','carry_forward','exclude_request')) IS DISTINCT FROM true
 OR length(btrim(coalesce(_detail,''))) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'rs.explicit_group_intent_required' USING ERRCODE='22023';END IF;
 SELECT * INTO g FROM private.rs_groups WHERE run_id=_run AND native_id=_group;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND definition_id=_definition AND status='completed')
 THEN RAISE EXCEPTION 'rs.exact_completed_group_required' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(g.source_rows) x WHERE private.data_source_child_allows(actor,_tenant,(x.value->>'data_source_id')::uuid,'view') IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'rs.current_group_source_denied' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rs-group:'||_run::text||':'||actor::text||':'||_key::text,0));
 intent:=jsonb_build_object('request_key',_key,'group_id',_group,'match_status',g.match_status,'action',_action,'detail',btrim(_detail),
  'disposition',CASE WHEN _action='comment' THEN 'recorded' ELSE 'requested' END,'business_effect_applied',false,'ai_authority','Suggest');
 SELECT * INTO e FROM private.rs_events WHERE run_id=_run AND actor_id=actor AND kind='group_action_requested' AND payload->>'request_key'=_key::text;
 IF FOUND AND e.payload IS DISTINCT FROM intent THEN RAISE EXCEPTION 'rs.group_request_key_conflict' USING ERRCODE='PT409';END IF;
 IF NOT FOUND THEN INSERT INTO private.rs_events(run_id,actor_id,kind,payload) VALUES(_run,actor,'group_action_requested',intent) RETURNING * INTO e;END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',_definition,'run_id',_run,'group_id',_group,
  'action',_action,'audit_event_id',e.id,'occurred_at',e.occurred_at,'request_key',_key,'disposition',intent->>'disposition',
  'business_effect_applied',false,'matching_outcome_changed',false,'settlement_state_changed',false);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_check_current_ip_access(_tenant_id uuid, _ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);enabled boolean;allowed boolean:=false;available boolean;
BEGIN
 IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'dpw.ip_actor_denied' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;
 available:=FOUND AND enabled IS NOT NULL;
 IF available AND enabled=false THEN allowed:=true;
 ELSIF available AND _ip IS NOT NULL AND btrim(_ip)<>'' THEN allowed:=public.ip_in_tenant_allowlist(_tenant_id,_ip) IS TRUE;END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'policy_available',available,'enabled',CASE WHEN available THEN enabled ELSE NULL END,'allowed',allowed);
END $function$

CREATE OR REPLACE FUNCTION private.rs_mixed_preflight(_tenant uuid, _definition uuid, _business_date date, _bindings jsonb, _expected_definition_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant); approved jsonb; side jsonb; input jsonb;
 d public.data_prep_prepared_datasets%ROWTYPE; u public.workspace_data_source_uploads%ROWTYPE; contract jsonb; field jsonb; indexes integer[]; row_value jsonb;resolved_logical_side text;
BEGIN
 approved:=private.dpw_recon_approved_attest(actor,_tenant,_definition);
 IF (approved->>'reconciliation_feature_enabled')::boolean IS DISTINCT FROM true
 OR _business_date IS NULL OR approved->>'snapshot_sha256' IS DISTINCT FROM _expected_definition_sha256
 OR jsonb_typeof(approved->'snapshot'->'sides') IS DISTINCT FROM 'array' OR jsonb_typeof(_bindings) IS DISTINCT FROM 'array'
 OR jsonb_array_length(_bindings)<>jsonb_array_length(approved->'snapshot'->'sides')
 OR (SELECT count(DISTINCT value->>'side_id') FROM jsonb_array_elements(_bindings))<>jsonb_array_length(_bindings)
 THEN RAISE EXCEPTION 'dpw.recon_approved_input_mismatch'; END IF;
 FOR side IN SELECT value FROM jsonb_array_elements(approved->'snapshot'->'sides') LOOP
  SELECT value INTO input FROM jsonb_array_elements(_bindings) WHERE value->>'side_id'=side->>'side_id';
  IF input IS NULL OR input->>'data_source_id' IS DISTINCT FROM side->>'data_source_id'
  OR private.dpw_source_allows(actor,_tenant,(side->>'data_source_id')::uuid,'view') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'dpw.recon_source_binding_denied'; END IF;
  IF nullif(side->>'upload_id','') IS NOT NULL OR input->>'kind'='fixed_upload' THEN
   IF input->>'kind' IS DISTINCT FROM 'fixed_upload' OR (side->>'upload_id' IS NOT NULL AND input->>'upload_id' IS DISTINCT FROM side->>'upload_id')
   OR input ? 'dataset_id' THEN RAISE EXCEPTION 'dpw.fixed_definition_pin_cannot_be_overridden'; END IF;
   SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(input->>'upload_id')::uuid
   AND tenant_id=_tenant AND data_source_id=(side->>'data_source_id')::uuid;
   IF NOT FOUND OR jsonb_typeof(u.rows)<>'array' OR u.row_count<>jsonb_array_length(u.rows) THEN RAISE EXCEPTION 'dpw.fixed_input_unavailable'; END IF;
   SELECT x.value INTO contract FROM jsonb_array_elements(approved->'input_contracts') x WHERE x.value->>'side_id'=side->>'side_id';
   IF contract IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(u.rows) x WHERE private.rs_contract_row_allowed(x.value,contract) IS DISTINCT FROM true)
   THEN RAISE EXCEPTION 'rs.mixed_raw_approved_domain_refused' USING ERRCODE='22023';END IF;
   IF side->>'upload_id' IS NULL AND (EXISTS(SELECT 1 FROM public.data_prep_prepared_datasets x WHERE x.tenant_id=_tenant AND x.upload_id=u.id)
    OR EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.tenant_id=_tenant AND p.output_data_source_id=u.data_source_id))
   THEN RAISE EXCEPTION 'rs.prepared_source_requires_dataset_identity' USING ERRCODE='42501';END IF;
  ELSE
   SELECT value INTO contract FROM jsonb_array_elements(coalesce(approved->'input_contracts','[]'::jsonb)) WHERE value->>'side_id'=side->>'side_id';
   IF contract IS NULL OR (contract->>'logical_side' IS NOT NULL AND contract->>'logical_side' IS DISTINCT FROM input->>'logical_side')
   OR jsonb_typeof(contract->'fields') IS DISTINCT FROM 'array'
   THEN RAISE EXCEPTION 'dpw.recon_authoritative_schema_missing_governed_revision_required'; END IF;
   SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=(input->>'dataset_id')::uuid AND tenant_id=_tenant;
   IF NOT FOUND THEN RAISE EXCEPTION 'dpw.current_ready_dataset_required';END IF;
   resolved_logical_side:=coalesce(contract->>'logical_side',private.rs_select_compatible_logical_side(_tenant,d.id,contract));
   IF resolved_logical_side IS DISTINCT FROM input->>'logical_side' THEN RAISE EXCEPTION 'dpw.unique_approved_rule_compatible_cohort_required';END IF;
   IF NOT FOUND OR input->>'kind' IS DISTINCT FROM 'prepared_dataset' OR d.business_date<>_business_date
   OR input->>'pipeline_id' IS DISTINCT FROM d.pipeline_id::text OR (input->>'pipeline_version')::integer IS DISTINCT FROM d.pipeline_version
   OR input->>'upload_id' IS DISTINCT FROM d.upload_id::text OR d.data_source_id::text IS DISTINCT FROM side->>'data_source_id'
   OR private.data_prep_pipeline_scope_allows(actor,_tenant,d.pipeline_id,'view') IS DISTINCT FROM true
   OR private.dpw_run_payload_available(d.run_id) IS DISTINCT FROM true
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.id=d.pipeline_id AND p.tenant_id=_tenant AND p.status='approved'
   AND p.lifecycle_state='production' AND p.version=d.pipeline_version AND p.output_data_source_id=d.data_source_id)
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_runs r,jsonb_array_elements(r.snapshot->'feeds') f
   WHERE r.id=d.run_id AND f.value->>'business_side'=resolved_logical_side)
   OR NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_batches b JOIN public.data_prep_delivery_runs r ON r.id=d.run_id AND r.batch_id=b.id
   WHERE b.id=d.batch_id AND b.mode='prepare' AND b.state='published' AND r.pipeline_version=d.pipeline_version
   AND r.finished_at IS NOT NULL AND r.state IN('success','warn') AND (r.result->>'publication_eligible')::boolean IS TRUE)
   THEN RAISE EXCEPTION 'dpw.current_ready_dataset_required'; END IF;
   SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=d.upload_id AND tenant_id=_tenant AND data_source_id=d.data_source_id;
   IF NOT FOUND OR u.content_sha256 IS DISTINCT FROM d.content_sha256 OR u.row_count<>d.rows
   OR jsonb_typeof(u.rows)<>'array' OR jsonb_array_length(u.rows)<>d.rows OR private.dpw_hash(u.rows) IS DISTINCT FROM d.content_sha256
   THEN RAISE EXCEPTION 'dpw.prepared_upload_lineage_mismatch'; END IF;
   indexes:=private.dpw_dataset_indexes(d.id,resolved_logical_side);
   FOR row_value IN SELECT u.rows->x FROM unnest(indexes) x LOOP
    IF private.rs_contract_row_allowed(row_value,contract) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.recon_approved_field_domain_incompatible';END IF;
   END LOOP;
  END IF;
 END LOOP;
 RETURN approved;
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_publish_dataset(_tenant_id uuid, _setup_id uuid, _job_id uuid, _publication_decision_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.perform',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);r private.dpdi_publication_requests%ROWTYPE;dec private.dpdi_publication_decisions%ROWTYPE;d private.dpdi_published_datasets%ROWTYPE;src uuid;
BEGIN
 SELECT * INTO dec FROM private.dpdi_publication_decisions WHERE id=_publication_decision_id AND decision='approved';SELECT * INTO r FROM private.dpdi_publication_requests WHERE id=dec.request_id AND tenant_id=_tenant_id AND setup_id=_setup_id AND job_id=j.id;
 src:=(j.snapshot->'pipeline_configuration'->>'output_data_source_id')::uuid;
 IF j.snapshot->>'mode' IS DISTINCT FROM 'prepare' OR j.snapshot->>'approval_origin' IS DISTINCT FROM 'dpdi_setup_review_v1' OR e.phase<>'success' OR e.blocking_records<>0 OR r.id IS NULL OR dec.decided_by=r.requested_by OR dec.decided_by=j.actor_id OR dec.output_root_sha256<>e.output_root_sha256 OR _request_key IS NULL OR private.dpw_source_allows(actor,_tenant_id,src,'edit') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,src,'ingest') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.actual_final_human_publication_required_zero_on_failure' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM private.dpdi_jobs WHERE id=j.id FOR UPDATE;SELECT * INTO d FROM private.dpdi_published_datasets WHERE job_id=j.id;
 IF FOUND THEN IF d.request_key<>_request_key OR d.publication_decision_id<>dec.id THEN RAISE EXCEPTION 'dpdi.immutable_publication_request_conflict' USING ERRCODE='PT409';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset',private.dpdi_dataset_dto(d),'request_replay',true);END IF;
 INSERT INTO private.dpdi_published_datasets(tenant_id,setup_id,draft_version,pipeline_id,pipeline_version,configuration_id,job_id,run_id,business_date,data_source_id,rows,content_sha256,output_schema_sha256,publication_decision_id,request_key,published_by)
 VALUES(_tenant_id,_setup_id,j.draft_version,(j.snapshot->>'pipeline_id')::uuid,(j.snapshot->>'pipeline_version')::integer,(j.snapshot->>'configuration_id')::uuid,j.id,j.reserved_run_id,(j.snapshot->>'business_date')::date,src,e.source_records,e.output_root_sha256,private.dpw_hash(j.snapshot->'confirmed_mapping'->'output_schema'),dec.id,_request_key,actor) RETURNING * INTO d;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'dataset.published',d.id,jsonb_build_object('manifest_id',d.manifest_id,'rows',d.rows::text,'content_sha256',d.content_sha256,'publication_decision_id',dec.id,'representation','dpdi_approved_prepare_v1','upload_id',NULL));RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset',private.dpdi_dataset_dto(d),'request_replay',false);
END $function$

CREATE OR REPLACE FUNCTION public.submit_governance_membership_request(_tenant_id uuid, _bu_id uuid, _workspace_id uuid, _group_id uuid, _environment text, _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); payload jsonb; op private.governance_membership_operations; r public.governance_membership_requests; snapshot jsonb; result jsonb; aid bigint;
BEGIN
  IF _request_key IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Reason and request key required' USING ERRCODE='22023'; END IF;
  IF NOT private.governance_membership_active(_tenant_id,actor) THEN RAISE EXCEPTION 'Active tenant membership required' USING ERRCODE='42501'; END IF;
  payload:=jsonb_build_object('operation','submit','bu_id',_bu_id,'workspace_id',_workspace_id,'group_id',_group_id,'environment',_environment,'reason',btrim(_reason));
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||_request_key::text,0));
  SELECT * INTO op FROM private.governance_membership_operations WHERE tenant_id=_tenant_id AND request_key=_request_key;
  IF FOUND THEN
    IF op.actor_id<>actor OR op.payload<>payload THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
    PERFORM private.governance_membership_scope(_tenant_id,_bu_id,_workspace_id,_group_id,_environment,actor);
    RETURN op.result;
  END IF;
  PERFORM private.governance_membership_lock_scope();
  snapshot:=private.governance_membership_scope(_tenant_id,_bu_id,_workspace_id,_group_id,_environment,actor);
  IF EXISTS(SELECT 1 FROM public.tenant_group_members WHERE group_id=_group_id AND user_id=actor) THEN RAISE EXCEPTION 'Already a group member' USING ERRCODE='23505'; END IF;
  INSERT INTO public.governance_membership_requests(tenant_id,requested_by,bu_id,workspace_id,environment,group_id,requested_rights,scope_snapshot,request_reason)
  VALUES(_tenant_id,actor,_bu_id,_workspace_id,_environment,_group_id,ARRAY(SELECT jsonb_array_elements_text(snapshot->'requested_rights')),snapshot,btrim(_reason)) RETURNING * INTO r;
  aid:=private.governance_membership_record(r,'governance.membership.request',actor,btrim(_reason),'pending');
  result:=jsonb_build_object('id',r.id,'status',r.status,'version',r.version,'correlation_id',r.correlation_id,'audit_id',aid::text,'outcome','pending');
  INSERT INTO private.governance_membership_operations VALUES(_tenant_id,_request_key,actor,payload,result);
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.dps_save_configuration(_tenant_id uuid, _pipeline_id uuid, _payload jsonb, _owning_business_unit_ids uuid[], _sharing_user_group_ids uuid[], _request_key uuid, _request_context_id uuid DEFAULT NULL::uuid, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE v private.dpd_versions%ROWTYPE;operation text;expected jsonb;feeds jsonb;
BEGIN
 IF _payload ?| ARRAY['_draft_scope','owning_business_unit_ids','sharing_user_group_ids','requested_owning_business_unit_ids','shared_scope_contract'] THEN RAISE EXCEPTION 'dps.reserved_scope_metadata' USING ERRCODE='22023';END IF;
 SELECT c.operation INTO operation FROM private.dpd_request_contexts c WHERE c.id=_request_context_id;
 IF operation NOT IN('scope.save','preview.bind') OR operation IS NULL THEN RAISE EXCEPTION 'dps.configuration_operation_required' USING ERRCODE='42501';END IF;
 PERFORM private.dps_context_actor(_tenant_id,_setup_id,operation,_request_context_id);
 SELECT * INTO v FROM private.dpd_versions WHERE setup_id=_setup_id ORDER BY version DESC LIMIT 1;
 IF v.version IS NULL OR private.dps_ids(v.owner_bu_ids,100,true) IS DISTINCT FROM private.dps_ids(_owning_business_unit_ids,100,true) OR private.dps_ids(v.group_ids,100,false) IS DISTINCT FROM private.dps_ids(_sharing_user_group_ids,100,false)
 THEN RAISE EXCEPTION 'dps.exact_saved_draft_scope_required' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(f.value||jsonb_build_object('data_source_id',mapped.value->>'data_source_id') ORDER BY f.ordinality),'[]') INTO feeds
 FROM jsonb_array_elements(v.payload->'feeds') WITH ORDINALITY f(value,ordinality)
 JOIN LATERAL(SELECT x.value FROM jsonb_array_elements(v.payload->'confirmed_mapping'->'feeds') x(value) WHERE x.value->>'key'=f.value->>'key') mapped ON true;
 expected:=private.dpd_pipeline_payload(v.payload)||jsonb_build_object('feeds',feeds);
 IF expected IS DISTINCT FROM _payload THEN RAISE EXCEPTION 'dps.exact_saved_mapping_payload_required' USING ERRCODE='42501';END IF;
 IF _pipeline_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private.dpd_preview_links WHERE setup_id=_setup_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id) THEN RAISE EXCEPTION 'dps.setup_pipeline_binding_required' USING ERRCODE='42501';END IF;
 RETURN private.dps_save_configuration_core(_tenant_id,_pipeline_id,_payload,_owning_business_unit_ids,_sharing_user_group_ids,_request_key);
END $function$

CREATE OR REPLACE FUNCTION public.decide_governance_membership_request(_tenant_id uuid, _request_id uuid, _expected_version integer, _decision text, _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); payload jsonb; op private.governance_membership_operations; r public.governance_membership_requests; result jsonb; aid bigint; outcome text;
BEGIN
  IF _request_key IS NULL OR _expected_version IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 OR _decision IS NULL OR _decision NOT IN ('approve','reject') THEN RAISE EXCEPTION 'Decision, current version, reason and request key required' USING ERRCODE='22023'; END IF;
  PERFORM private.governance_membership_lock_scope();
  IF NOT private.governance_membership_active(_tenant_id,actor,true) THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501'; END IF;
  payload:=jsonb_build_object('operation','decide','request_id',_request_id,'expected_version',_expected_version,'decision',_decision,'reason',btrim(_reason));
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||_request_key::text,0));
  SELECT * INTO op FROM private.governance_membership_operations WHERE tenant_id=_tenant_id AND request_key=_request_key;
  IF FOUND THEN
    IF op.actor_id<>actor OR op.payload<>payload THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
    RETURN op.result;
  END IF;
  SELECT * INTO r FROM public.governance_membership_requests WHERE tenant_id=_tenant_id AND id=_request_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request not found in current tenant' USING ERRCODE='42501'; END IF;
  IF actor=r.requested_by THEN RAISE EXCEPTION 'Independent checker required' USING ERRCODE='42501'; END IF;
  IF r.version<>_expected_version OR r.status<>'pending' THEN RAISE EXCEPTION 'Stale request version or closed request' USING ERRCODE='PT409'; END IF;
  IF _decision='approve' THEN
    IF private.governance_membership_scope(r.tenant_id,r.bu_id,r.workspace_id,r.group_id,r.environment,r.requested_by)<>r.scope_snapshot THEN RAISE EXCEPTION 'Group rights or association changed; renewed request required' USING ERRCODE='PT409'; END IF;
    -- Do not re-grant after an unrelated manual grant/revocation. Require this exact insert.
    INSERT INTO public.tenant_group_members(group_id,user_id,added_by) VALUES(r.group_id,r.requested_by,actor);
    outcome:='grant_confirmed';
  ELSE outcome:='no_access_granted'; END IF;
  UPDATE public.governance_membership_requests SET status=CASE WHEN _decision='approve' THEN 'approved' ELSE 'rejected' END,
    version=version+1,approved_by=actor,decided_at=now(),decision_reason=btrim(_reason) WHERE id=r.id RETURNING * INTO r;
  aid:=private.governance_membership_record(r,'governance.membership.'||_decision,actor,btrim(_reason),outcome);
  result:=jsonb_build_object('id',r.id,'status',r.status,'version',r.version,'correlation_id',r.correlation_id,'audit_id',aid::text,'outcome',outcome);
  INSERT INTO private.governance_membership_operations VALUES(_tenant_id,_request_key,actor,payload,result);
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.rs_persist_mixed_binding(_tenant uuid, _definition uuid, _run uuid, _business_date date, _bindings jsonb, _request_key uuid, _expected_definition_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant); approved jsonb; r public.recon_runs%ROWTYPE; input jsonb;
 d public.data_prep_prepared_datasets%ROWTYPE; u public.workspace_data_source_uploads%ROWTYPE; indexes integer[]; selected_rows jsonb;
BEGIN
 -- No adoption of old/failed/partial runs and no status rewrite to hide errors.
 SELECT * INTO r FROM public.recon_runs WHERE id=_run AND tenant_id=_tenant AND definition_id=_definition FOR UPDATE;
 IF NOT FOUND OR r.run_by IS DISTINCT FROM actor OR r.status<>'queued' OR r.completed_at IS NOT NULL
 OR r.started_at<transaction_timestamp() OR r.matched_count<>0 OR r.exception_count<>0
 OR EXISTS(SELECT 1 FROM public.recon_matches WHERE run_id=r.id) OR EXISTS(SELECT 1 FROM public.recon_exceptions WHERE run_id=r.id)
 THEN RAISE EXCEPTION 'dpw.new_owned_recon_run_required'; END IF;
 approved:=private.rs_mixed_preflight(_tenant,_definition,_business_date,_bindings,_expected_definition_sha256);
 IF r.definition_snapshot IS DISTINCT FROM approved->'snapshot'
 OR r.approved_revision_id IS DISTINCT FROM (approved->>'revision_id')::uuid
 OR r.approved_revision_number IS DISTINCT FROM (approved->>'revision_number')::integer
 OR r.approved_revision_sha256 IS DISTINCT FROM approved->>'snapshot_sha256'
 THEN RAISE EXCEPTION 'dpw.recon_native_approval_snapshot_mismatch'; END IF;
 INSERT INTO public.data_prep_recon_run_requests(recon_run_id,tenant_id,definition_id,created_by,request_key,approved_snapshot,approved_snapshot_sha256,approved_revision_id,approved_revision_number,input_bindings,business_date)
 VALUES(r.id,_tenant,_definition,actor,_request_key,approved->'snapshot',approved->>'snapshot_sha256',(approved->>'revision_id')::uuid,
 (approved->>'revision_number')::integer,_bindings,_business_date);
 FOR input IN SELECT value FROM jsonb_array_elements(_bindings) LOOP
  SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=(input->>'upload_id')::uuid;
  IF input->>'kind'='prepared_dataset' THEN
   SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=(input->>'dataset_id')::uuid;
   indexes:=private.dpw_dataset_indexes(d.id,input->>'logical_side');
   SELECT coalesce(jsonb_agg(u.rows->i ORDER BY i),'[]'::jsonb) INTO selected_rows FROM unnest(indexes) i;
   INSERT INTO public.data_prep_recon_run_inputs VALUES(r.id,input->>'side_id',_tenant,_definition,d.data_source_id,d.upload_id,
   d.id,d.batch_id,d.run_id,d.pipeline_id,d.pipeline_version,d.business_date,'prepared_dataset',d.content_sha256,cardinality(indexes),input->>'logical_side',indexes,private.dpw_hash(selected_rows));
  ELSE
   INSERT INTO public.data_prep_recon_run_inputs VALUES(r.id,input->>'side_id',_tenant,_definition,u.data_source_id,u.id,
   NULL,NULL,NULL,NULL,NULL,NULL,'fixed_upload',u.content_sha256,u.row_count,NULL,NULL,private.dpw_hash(u.rows));
  END IF;
 END LOOP;
 PERFORM private.dpw_audit(actor,_tenant,'dpw.recon.inputs.bind',r.id,jsonb_build_object('definition_id',_definition,'bindings',_bindings,'approved_sha256',_expected_definition_sha256));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'run_id',r.id,'run_uid',r.run_uid,'input_bindings',_bindings,'approved_snapshot',approved->'snapshot','is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.withdraw_governance_membership_request(_tenant_id uuid, _request_id uuid, _expected_version integer, _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE actor uuid:=auth.uid(); payload jsonb; op private.governance_membership_operations; r public.governance_membership_requests; result jsonb; aid bigint;
BEGIN
  IF _request_key IS NULL OR _expected_version IS NULL OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Current version, reason and request key required' USING ERRCODE='22023'; END IF;
  PERFORM private.governance_membership_lock_scope();
  IF NOT private.governance_membership_active(_tenant_id,actor) THEN RAISE EXCEPTION 'Active tenant membership required' USING ERRCODE='42501'; END IF;
  payload:=jsonb_build_object('operation','withdraw','request_id',_request_id,'expected_version',_expected_version,'reason',btrim(_reason));
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||_request_key::text,0));
  SELECT * INTO op FROM private.governance_membership_operations WHERE tenant_id=_tenant_id AND request_key=_request_key;
  IF FOUND THEN
    IF op.actor_id<>actor OR op.payload<>payload THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
    RETURN op.result;
  END IF;
  SELECT * INTO r FROM public.governance_membership_requests WHERE tenant_id=_tenant_id AND id=_request_id FOR UPDATE;
  IF NOT FOUND OR r.requested_by<>actor THEN RAISE EXCEPTION 'Current requester required' USING ERRCODE='42501'; END IF;
  IF r.version<>_expected_version OR r.status<>'pending' THEN RAISE EXCEPTION 'Stale request version or closed request' USING ERRCODE='PT409'; END IF;
  UPDATE public.governance_membership_requests SET status='withdrawn',version=version+1,approved_by=actor,decided_at=now(),decision_reason=btrim(_reason) WHERE id=r.id RETURNING * INTO r;
  aid:=private.governance_membership_record(r,'governance.membership.withdraw',actor,btrim(_reason),'no_access_granted');
  result:=jsonb_build_object('id',r.id,'status',r.status,'version',r.version,'correlation_id',r.correlation_id,'audit_id',aid::text,'outcome','no_access_granted');
  INSERT INTO private.governance_membership_operations VALUES(_tenant_id,_request_key,actor,payload,result);
  RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.rs_resolve_mixed_bindings(_tenant uuid, _definition uuid, _business_date date, _datasets jsonb, _raw_uploads jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');d public.recon_definitions%ROWTYPE;v public.recon_definition_approved_versions%ROWTYPE;
 contracts jsonb;s jsonb;c jsonb;dataset public.data_prep_prepared_datasets%ROWTYPE;bindings jsonb:='[]';approved jsonb;chosen_policy private.rs_policies%ROWTYPE;policies integer;logical_side text;
BEGIN
 IF _business_date IS NULL OR jsonb_typeof(_datasets) IS DISTINCT FROM 'object' OR _datasets='{}'::jsonb OR jsonb_typeof(_raw_uploads) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'rs.explicit_prepared_side_selection_required' USING ERRCODE='22023';END IF;
 v:=private.recon_run_bound_approved_version(_tenant,_definition,actor);
 IF v.id IS NULL THEN RAISE EXCEPTION 'rs.actual_native_approved_snapshot_required' USING ERRCODE='42501';END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 contracts:=private.rs_recon_input_contracts(_tenant,_definition,v.id);
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(_datasets||_raw_uploads) k WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v.snapshot->'sides') x WHERE x->>'side_id'=k))
 THEN RAISE EXCEPTION 'rs.unconfigured_prepared_side' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(_raw_uploads) k WHERE _datasets ? k)
 THEN RAISE EXCEPTION 'rs.mixed_side_selection_overlap' USING ERRCODE='22023';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(v.snapshot->'sides') LOOP
  IF _datasets ? (s->>'side_id') THEN
   SELECT value INTO c FROM jsonb_array_elements(contracts->'input_contracts') WHERE value->>'side_id'=s->>'side_id';
   IF c IS NULL OR jsonb_typeof(c->'fields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'rs.approved_prepared_side_domains_unavailable' USING ERRCODE='42501';END IF;
   SELECT * INTO dataset FROM public.data_prep_prepared_datasets WHERE id=(_datasets->>(s->>'side_id'))::uuid AND tenant_id=_tenant;
   IF NOT FOUND OR dataset.data_source_id::text IS DISTINCT FROM s->>'data_source_id'
    OR (s ? 'upload_id' AND s->>'upload_id' IS NOT NULL AND s->>'upload_id' IS DISTINCT FROM dataset.upload_id::text)
   THEN RAISE EXCEPTION 'rs.prepared_source_or_approved_pin_conflict' USING ERRCODE='42501';END IF;
   logical_side:=coalesce(c->>'logical_side',private.rs_select_compatible_logical_side(_tenant,dataset.id,c));
   bindings:=bindings||jsonb_build_array(jsonb_build_object('kind','prepared_dataset','side_id',s->>'side_id','data_source_id',s->>'data_source_id','dataset_id',dataset.id,
    'pipeline_id',dataset.pipeline_id,'pipeline_version',dataset.pipeline_version,'upload_id',dataset.upload_id,'logical_side',logical_side));
  ELSE
   IF coalesce(s->>'upload_id',_raw_uploads->>(s->>'side_id')) IS NULL THEN RAISE EXCEPTION 'rs.required_counterpart_unpinned_no_latest_fallback' USING ERRCODE='42501';END IF;
   IF s->>'upload_id' IS NOT NULL AND _raw_uploads ? (s->>'side_id') AND _raw_uploads->>(s->>'side_id') IS DISTINCT FROM s->>'upload_id'
   THEN RAISE EXCEPTION 'rs.fixed_approved_pin_override_refused' USING ERRCODE='42501';END IF;
   bindings:=bindings||jsonb_build_array(jsonb_build_object('kind','fixed_upload','side_id',s->>'side_id','data_source_id',s->>'data_source_id','upload_id',coalesce(s->>'upload_id',_raw_uploads->>(s->>'side_id'))));
  END IF;
 END LOOP;
 -- Exact authoritative intersection: current published dataset, pipeline version,
 -- independent release, source RLP, logical-side output indexes and typed row hash.
 approved:=private.rs_mixed_preflight(_tenant,_definition,_business_date,bindings,v.snapshot_sha256);
 IF approved->>'snapshot_sha256' IS DISTINCT FROM v.snapshot_sha256 OR approved->'reconciliation_feature_enabled' IS DISTINCT FROM 'true'::jsonb
 THEN RAISE EXCEPTION 'rs.actual_native_preflight_required' USING ERRCODE='42501';END IF;
 SELECT count(*) INTO policies FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=_definition
 AND policy->>'business_date'=_business_date::text AND qualification->>'state'='native_qualified'
 AND qualification->>'approved_definition_sha256'=v.snapshot_sha256;
 IF policies>1 THEN RAISE EXCEPTION 'rs.unambiguous_approved_native_execution_policy_required' USING ERRCODE='42501';END IF;
 IF policies=1 THEN SELECT * INTO chosen_policy FROM private.rs_policies WHERE tenant_id=_tenant AND definition_id=_definition AND policy->>'business_date'=_business_date::text
 AND qualification->>'state'='native_qualified' AND qualification->>'approved_definition_sha256'=v.snapshot_sha256;
 ELSE chosen_policy.policy_id:=v.id;chosen_policy.version:=v.version_number::text;chosen_policy.policy:=jsonb_build_object('business_date',_business_date,'policy_kind','approved_native_input_binding');END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'definition_id',d.id,'business_date',_business_date,'revision_id',v.id,'revision_number',v.version_number,
 'expected_definition_sha256',v.snapshot_sha256,'approved_snapshot_sha256',v.snapshot_sha256,'input_bindings',bindings,
 'execution_policy',jsonb_build_object('policy_id',chosen_policy.policy_id,'policy_version',chosen_policy.version,'business_date',chosen_policy.policy->>'business_date','policy_kind',chosen_policy.policy->>'policy_kind'),
 'compatibility','native_current_published_contract_hash_checked','approved_snapshot',approved->'snapshot');
END $function$

CREATE OR REPLACE FUNCTION private.rs_validate_prepared_execution(_tenant uuid, _run uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE q private.rs_requests%ROWTYPE;actor uuid;actual jsonb;
BEGIN
 SELECT * INTO q FROM private.rs_requests WHERE tenant_id=_tenant AND run_id=_run AND actor_id=auth.uid();
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.owned_execution_input_required' USING ERRCODE='42501';END IF;
 actor:=private.rs_actor(_tenant,q.definition_id,'run');
 IF q.intent->>'input_kind'='prepared_bound' THEN
  IF q.intent ? 'mixed_selection' THEN actual:=private.rs_mixed_preflight(_tenant,q.definition_id,(q.intent->>'business_date')::date,q.intent->'bindings',q.intent->>'expected_definition_sha256');
  ELSE actual:=private.dpw_recon_preflight(_tenant,q.definition_id,(q.intent->>'business_date')::date,q.intent->'bindings',q.intent->>'expected_definition_sha256');END IF;
  IF actual->>'snapshot_sha256' IS DISTINCT FROM q.intent->>'expected_definition_sha256'
  THEN RAISE EXCEPTION 'rs.current_prepared_execution_contract_changed' USING ERRCODE='42501';END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION private.rs_prior_mixed(_tenant uuid, _definition uuid, _date date, _datasets jsonb, _raw jsonb, _key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant,_definition,'run');q private.rs_requests%ROWTYPE;selection jsonb;
BEGIN
 selection:=jsonb_build_object('business_date',_date,'prepared_dataset_by_side',_datasets,'raw_upload_by_side',_raw);
 SELECT * INTO q FROM private.rs_requests WHERE tenant_id=_tenant AND definition_id=_definition AND actor_id=actor AND request_key=_key;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF q.intent->'mixed_selection' IS DISTINCT FROM selection THEN RAISE EXCEPTION 'rs.mixed_request_key_conflict' USING ERRCODE='PT409';END IF;
 RETURN private.rs_prior(_tenant,_definition,_key,q.intent);
END $function$

CREATE OR REPLACE FUNCTION public.request_recon_mixed_execution(_tenant_id uuid, _definition_id uuid, _business_date date, _prepared_dataset_by_side jsonb, _raw_upload_by_side jsonb, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=private.rs_actor(_tenant_id,_definition_id,'run');prior jsonb;resolved jsonb;bindings jsonb;intent jsonb;pins jsonb;r public.recon_runs%ROWTYPE;persisted jsonb;
BEGIN
 IF _request_key IS NULL OR _business_date IS NULL OR jsonb_typeof(_prepared_dataset_by_side) IS DISTINCT FROM 'object'
 OR _prepared_dataset_by_side='{}'::jsonb OR jsonb_typeof(_raw_upload_by_side) IS DISTINCT FROM 'object'
 THEN RAISE EXCEPTION 'rs.explicit_mixed_selection_required' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('rs:'||_tenant_id::text||':'||_definition_id::text,0));
 PERFORM 1 FROM public.recon_definitions WHERE id=_definition_id AND tenant_id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_mixed_definition_required' USING ERRCODE='42501';END IF;
 prior:=private.rs_prior_mixed(_tenant_id,_definition_id,_business_date,_prepared_dataset_by_side,_raw_upload_by_side,_request_key);
 IF prior IS NOT NULL THEN
  PERFORM 1 FROM public.recon_runs WHERE id=(prior->>'run_id')::uuid AND tenant_id=_tenant_id AND run_by=actor;
  IF NOT FOUND THEN RAISE EXCEPTION 'rs.current_original_run_rlp_required' USING ERRCODE='42501';END IF;
  RETURN prior;
 END IF;
 resolved:=private.rs_resolve_mixed_bindings(_tenant_id,_definition_id,_business_date,_prepared_dataset_by_side,_raw_upload_by_side);
 bindings:=resolved->'input_bindings';
 -- Invoker visibility is checked before the same-transaction native INSERT.
 PERFORM 1 FROM public.workspace_data_source_uploads u JOIN jsonb_array_elements(bindings) b ON u.id=(b->>'upload_id')::uuid
 WHERE u.tenant_id=_tenant_id AND u.data_source_id=(b->>'data_source_id')::uuid;
 IF (SELECT count(*) FROM public.workspace_data_source_uploads u JOIN jsonb_array_elements(bindings) b ON u.id=(b->>'upload_id')::uuid
  WHERE u.tenant_id=_tenant_id AND u.data_source_id=(b->>'data_source_id')::uuid)<>jsonb_array_length(bindings)
 THEN RAISE EXCEPTION 'rs.current_mixed_upload_rlp_required' USING ERRCODE='42501';END IF;
 INSERT INTO public.recon_runs(tenant_id,definition_id,status,run_by) VALUES(_tenant_id,_definition_id,'queued',actor) RETURNING * INTO r;
 persisted:=private.rs_persist_mixed_binding(_tenant_id,_definition_id,r.id,_business_date,bindings,_request_key,resolved->>'expected_definition_sha256');
 IF persisted->>'run_id' IS DISTINCT FROM r.id::text OR persisted->>'actor_id' IS DISTINCT FROM actor::text
 THEN RAISE EXCEPTION 'rs.actual_mixed_binding_receipt_required' USING ERRCODE='PT409';END IF;
 SELECT jsonb_agg(jsonb_build_object('side_id',b->>'side_id','upload_id',b->>'upload_id') ORDER BY b->>'side_id') INTO pins FROM jsonb_array_elements(bindings) b;
 intent:=jsonb_build_object('input_kind','prepared_bound','bindings',bindings,'pins',pins,'business_date',_business_date,
  'policy_id',resolved->'execution_policy'->>'policy_id','policy_version',resolved->'execution_policy'->>'policy_version',
  'expected_definition_sha256',resolved->>'expected_definition_sha256','mixed_selection',jsonb_build_object('business_date',_business_date,
   'prepared_dataset_by_side',_prepared_dataset_by_side,'raw_upload_by_side',_raw_upload_by_side));
 RETURN private.rs_store(_tenant_id,r.id,_request_key,intent);
END $function$

CREATE OR REPLACE FUNCTION public.governance_access_review_decide(_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '30s'
AS $function$
DECLARE t uuid:=(_input->>'tenant_id')::uuid; actor uuid:=auth.uid(); k uuid:=(_input->>'request_key')::uuid;
 d text:=_input->>'decision'; note text:=btrim(_input->>'reason'); h text;
 receipt public.governance_access_review_receipts%ROWTYPE; i public.access_review_items%ROWTYPE;
 c public.access_review_campaigns%ROWTYPE; snap jsonb; result jsonb; affected int; audit_id bigint;
 correlation uuid:=gen_random_uuid(); event text; outcome text; history jsonb;
BEGIN
 PERFORM private.governance_review_assert_member(t);
 IF k IS NULL OR d IS NULL OR d NOT IN ('retain','request_change','revoke') OR note IS NULL OR length(note) NOT BETWEEN 1 AND 2000
   OR coalesce((_input->>'expected_version')::int,0)<1 OR coalesce(_input->>'snapshot_hash','') !~ '^[a-f0-9]{64}$' THEN
   RAISE EXCEPTION 'Invalid decision' USING ERRCODE='22023'; END IF;
 h:=private.governance_review_hash(jsonb_build_object('operation','decision','input',_input));
 PERFORM pg_advisory_xact_lock(hashtextextended('governance.access_review.'||t::text||k::text,0));
 PERFORM private.governance_review_lock_sources();
 PERFORM private.governance_review_assert_member(t,d<>'request_change');
 SELECT * INTO i FROM public.access_review_items WHERE id=(_input->>'id')::uuid AND tenant_id=t FOR UPDATE;
 SELECT * INTO c FROM public.access_review_campaigns WHERE id=i.campaign_id AND tenant_id=t FOR UPDATE;
 IF i.id IS NULL OR c.id IS NULL OR NOT private.governance_review_can_read(i) OR i.reviewer_id IS DISTINCT FROM actor
   OR c.created_by IS NULL OR c.created_by=actor OR i.subject_user_id=actor THEN
   RAISE EXCEPTION 'Independent current assigned reviewer required' USING ERRCODE='42501'; END IF;
 SELECT * INTO receipt FROM public.governance_access_review_receipts WHERE tenant_id=t AND request_key=k;
 IF FOUND THEN
   IF receipt.actor_id<>actor OR receipt.payload_hash<>h THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
   RETURN receipt.result;
 END IF;
 IF c.status<>'active' OR i.governance_snapshot IS NULL OR i.governance_outcome NOT IN ('pending','change_requested')
   OR i.governance_version<>(_input->>'expected_version')::int OR i.governance_snapshot_hash<>_input->>'snapshot_hash' THEN
   RAISE EXCEPTION 'Review version/snapshot is stale or not actionable' USING ERRCODE='PT409'; END IF;
 snap:=private.governance_review_snapshot(t,i.subject_user_id,(i.subject_scope->>'group_id')::uuid,(i.subject_scope->>'workspace_id')::uuid);
 IF private.governance_review_hash(snap)<>i.governance_snapshot_hash THEN
   RAISE EXCEPTION 'Current access changed; create a fresh review snapshot' USING ERRCODE='PT409'; END IF;
 IF d='revoke' THEN
   DELETE FROM public.tenant_group_members WHERE group_id=(i.subject_scope->>'group_id')::uuid AND user_id=i.subject_user_id;
   GET DIAGNOSTICS affected=ROW_COUNT;
   IF affected<>1 OR EXISTS(SELECT 1 FROM public.tenant_group_members WHERE group_id=(i.subject_scope->>'group_id')::uuid AND user_id=i.subject_user_id)
     OR EXISTS(SELECT 1 FROM public.effective_user_permissions(i.subject_user_id,t,NULL) p WHERE p.group_id=(i.subject_scope->>'group_id')::uuid) THEN
     RAISE EXCEPTION 'Reviewed membership revocation did not take effect' USING ERRCODE='PT409'; END IF;
 END IF;
 outcome:=CASE d WHEN 'retain' THEN 'retained' WHEN 'revoke' THEN 'revoked' ELSE 'change_requested' END;
 event:=CASE d WHEN 'retain' THEN 'governance.access_review.retain' WHEN 'revoke' THEN 'governance.access_review.revoke' ELSE 'governance.access_review.change_requested' END;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,t,'tenant',event,'access_review_items',i.id::text,jsonb_build_object(
   'review_id',i.id,'campaign_id',c.id,'correlation_id',correlation,'actor_role',CASE WHEN private.governance_review_is_admin(t) THEN 'tenant_admin' ELSE 'assigned_reviewer' END,
   'reason',note,'version',i.governance_version+1,'reviewed_version',i.governance_version,'snapshot_hash',i.governance_snapshot_hash,
   'group_id',i.subject_scope->>'group_id','subject_user_id',i.subject_user_id,'outcome',outcome,'membership_revoked',d='revoke')) RETURNING id INTO audit_id;
 history:=coalesce(i.evidence->'governance_history','[]')||jsonb_build_array(jsonb_build_object(
   'actor_user_id',actor,'action',event,'outcome',outcome,'reason',note,'occurred_at',now(),'version',i.governance_version+1,'audit_id',audit_id,'correlation_id',correlation));
 UPDATE public.access_review_items SET decision=CASE d WHEN 'retain' THEN 'approved' WHEN 'revoke' THEN 'revoked' ELSE 'pending' END,
   governance_outcome=outcome,decision_note=note,decided_at=CASE WHEN d='request_change' THEN NULL ELSE now() END,
   governance_decided_by=actor,governance_correlation_id=correlation,governance_version=governance_version+1,
   evidence=evidence||jsonb_build_object('governance_history',history) WHERE id=i.id RETURNING * INTO i;
 result:=private.governance_review_row(i)||jsonb_build_object('history',history,'snapshot_current',d='request_change',
   'permitted_actions','[]'::jsonb,'membership_revoked',d='revoke',
   'remaining_effective_permissions',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.permission_id,p.source,p.role_id,p.group_id,p.bu_id),'[]') FROM public.effective_user_permissions(i.subject_user_id,t,NULL) p));
 INSERT INTO public.governance_access_review_receipts VALUES(t,k,actor,h,result,now());
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.governance_access_review_campaign_create(_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
 SET lock_timeout TO '5s'
 SET statement_timeout TO '30s'
AS $function$
DECLARE t uuid:=(_input->>'tenant_id')::uuid; actor uuid:=auth.uid(); k uuid:=(_input->>'request_key')::uuid;
 h text; receipt public.governance_access_review_receipts%ROWTYPE; campaign uuid; item uuid;
 entry jsonb; snap jsonb; ids jsonb:='[]'; result jsonb; correlation uuid:=gen_random_uuid();
BEGIN
 PERFORM private.governance_review_assert_member(t,true);
 IF k IS NULL OR length(btrim(coalesce(_input->>'name',''))) NOT BETWEEN 1 AND 160
   OR length(coalesce(_input->>'description',''))>1000 OR jsonb_typeof(_input->'memberships') IS DISTINCT FROM 'array'
   OR jsonb_array_length(_input->'memberships') NOT BETWEEN 1 AND 200 OR _input->>'due_at' IS NULL THEN
   RAISE EXCEPTION 'Invalid campaign' USING ERRCODE='22023'; END IF;
 h:=private.governance_review_hash(jsonb_build_object('operation','campaign.create','input',_input));
 PERFORM pg_advisory_xact_lock(hashtextextended('governance.access_review.'||t::text||k::text,0));
 SELECT * INTO receipt FROM public.governance_access_review_receipts WHERE tenant_id=t AND request_key=k;
 IF FOUND THEN
   IF receipt.actor_id<>actor OR receipt.payload_hash<>h THEN RAISE EXCEPTION 'Request key collision' USING ERRCODE='23505'; END IF;
   RETURN receipt.result;
 END IF;
 IF (_input->>'due_at')::timestamptz<=now() THEN RAISE EXCEPTION 'Due date must be in the future' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(_input->'memberships') e GROUP BY e->>'subject_user_id',e->>'group_id' HAVING count(*)>1) THEN
   RAISE EXCEPTION 'Duplicate membership' USING ERRCODE='22023'; END IF;
 PERFORM private.governance_review_lock_sources();
 PERFORM private.governance_review_assert_member(t,true);
 INSERT INTO public.access_review_campaigns(tenant_id,name,description,scope,status,starts_at,due_at,created_by,metadata)
 VALUES(t,btrim(_input->>'name'),_input->>'description','tenant','active',now(),(_input->>'due_at')::timestamptz,actor,
   jsonb_build_object('governance_schema_version',1,'correlation_id',correlation)) RETURNING id INTO campaign;
 FOR entry IN SELECT value FROM jsonb_array_elements(_input->'memberships') LOOP
   IF (entry->>'reviewer_id')::uuid IS NULL OR (entry->>'reviewer_id')::uuid IN (actor,(entry->>'subject_user_id')::uuid)
     OR NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=t AND user_id=(entry->>'reviewer_id')::uuid AND active AND role::text='tenant_admin') THEN
     RAISE EXCEPTION 'An independent active tenant-admin reviewer is required' USING ERRCODE='42501'; END IF;
   snap:=private.governance_review_snapshot(t,(entry->>'subject_user_id')::uuid,(entry->>'group_id')::uuid,(entry->>'workspace_id')::uuid);
   IF entry->>'snapshot_hash' IS NOT NULL AND entry->>'snapshot_hash' IS DISTINCT FROM private.governance_review_hash(snap) THEN
     RAISE EXCEPTION 'Selected membership rights changed; refresh the option snapshot' USING ERRCODE='PT409'; END IF;
   INSERT INTO public.access_review_items(campaign_id,tenant_id,subject_user_id,subject_role,subject_scope,reviewer_id,
     decision,governance_snapshot,governance_snapshot_hash,governance_outcome,governance_correlation_id)
   VALUES(campaign,t,(entry->>'subject_user_id')::uuid,'tenant_group_member',
     jsonb_build_object('group_id',entry->>'group_id','workspace_id',entry->>'workspace_id'),(entry->>'reviewer_id')::uuid,
     'pending',snap,private.governance_review_hash(snap),'pending',correlation) RETURNING id INTO item;
   IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=t AND user_id=(entry->>'reviewer_id')::uuid AND active AND role::text='tenant_admin')
     AND NOT EXISTS(SELECT 1 FROM public.tenant_group_members WHERE user_id=(entry->>'reviewer_id')::uuid AND group_id=(entry->>'group_id')::uuid) THEN
     RAISE EXCEPTION 'Reviewer lacks current group scope' USING ERRCODE='42501'; END IF;
   ids:=ids||jsonb_build_array(item);
 END LOOP;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,t,'tenant','governance.access_review.campaign.create','access_review_campaigns',campaign::text,
   jsonb_build_object('correlation_id',correlation,'actor_role','tenant_admin','outcome','active','version',1,'item_ids',ids,'due_at',_input->>'due_at'));
 result:=jsonb_build_object('campaign_id',campaign,'item_ids',ids,'correlation_id',correlation);
 INSERT INTO public.governance_access_review_receipts VALUES(t,k,actor,h,result,now());
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.governance_access_review_get(_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE t uuid:=(_input->>'tenant_id')::uuid; i public.access_review_items%ROWTYPE;
 c public.access_review_campaigns%ROWTYPE; fresh boolean:=false; actions jsonb:='[]';
BEGIN
 PERFORM private.governance_review_assert_member(t);
 SELECT * INTO i FROM public.access_review_items WHERE id=(_input->>'id')::uuid AND tenant_id=t;
 IF i.id IS NULL OR NOT private.governance_review_can_read(i) THEN RAISE EXCEPTION 'Review unavailable in current scope' USING ERRCODE='42501'; END IF;
 SELECT * INTO c FROM public.access_review_campaigns WHERE id=i.campaign_id AND tenant_id=t;
 IF i.governance_snapshot IS NOT NULL AND i.governance_outcome IN ('pending','change_requested') THEN
   BEGIN
     fresh:=private.governance_review_hash(private.governance_review_snapshot(t,i.subject_user_id,(i.subject_scope->>'group_id')::uuid,(i.subject_scope->>'workspace_id')::uuid))=i.governance_snapshot_hash;
   EXCEPTION WHEN SQLSTATE 'PT409' THEN fresh:=false; END;
 END IF;
 IF fresh AND c.status='active' AND i.reviewer_id=auth.uid() AND c.created_by<>auth.uid() AND i.subject_user_id<>auth.uid() THEN
   actions:=CASE WHEN private.governance_review_is_admin(t) THEN '["retain","request_change","revoke"]'::jsonb ELSE '["request_change"]'::jsonb END;
 END IF;
 RETURN private.governance_review_row(i)||jsonb_build_object('history',coalesce(i.evidence->'governance_history','[]'),
   'snapshot_current',fresh,'permitted_actions',actions);
END $function$

CREATE OR REPLACE FUNCTION private.dps_manifest(_tenant uuid, _pipeline uuid, _configuration uuid, _owners uuid[], _groups uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant);cfg public.data_prep_configuration_revisions%ROWTYPE;p public.data_prep_pipelines%ROWTYPE;source uuid;g uuid;registry uuid;result jsonb:='[]';item jsonb;
BEGIN
 PERFORM private.dpw_authorize(_tenant,_pipeline,'edit');PERFORM private.dps_selections(_tenant,_owners,_groups);
 SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=_configuration AND tenant_id=_tenant AND pipeline_id=_pipeline;
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=_pipeline AND tenant_id=_tenant;
 IF cfg.id IS NULL OR p.id IS NULL OR p.version<>cfg.pipeline_version OR p.lifecycle_state='archived' OR p.status='archived'
 OR NOT EXISTS(SELECT 1 FROM private.dpw_configuration_heads WHERE pipeline_id=p.id AND configuration_id=cfg.id)
 THEN RAISE EXCEPTION 'dps.configuration_not_current' USING ERRCODE='42501';END IF;
 FOR source IN SELECT DISTINCT (value->>'data_source_id')::uuid FROM jsonb_array_elements(cfg.payload->'feeds') LOOP
  IF private.dpw_source_allows(actor,_tenant,source,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant,source,'ingest') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'dps.creator_source_denied' USING ERRCODE='42501';END IF;
  SELECT id INTO registry FROM public.data_resource_registry WHERE tenant_id=_tenant AND resource_type='data_source' AND data_source_id=source;
  IF registry IS NULL THEN RAISE EXCEPTION 'dps.registered_input_scope_required' USING ERRCODE='42501';END IF;
  FOREACH g IN ARRAY _groups LOOP
   IF NOT EXISTS(SELECT 1 FROM public.data_resource_registry_grants grant_row
    JOIN public.data_resource_registry_owner_bu owner ON owner.tenant_id=grant_row.tenant_id AND owner.registry_id=grant_row.registry_id AND owner.bu_id=grant_row.bu_id
    WHERE grant_row.registry_id=registry AND grant_row.tenant_id=_tenant AND grant_row.action='view' AND grant_row.principal_type='group' AND grant_row.principal_group_id=g
    AND cardinality(private.dps_group_bus(_tenant,g,ARRAY[owner.bu_id]))>0)
   THEN
    IF private.dps_owned_draft_input(_tenant,source,cfg.id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dps.group_input_view_ceiling_denied' USING ERRCODE='42501';END IF;
    IF NOT EXISTS(SELECT 1 FROM public.data_resource_registry_owner_bu o WHERE o.registry_id=registry AND o.tenant_id=_tenant AND cardinality(private.dps_group_bus(_tenant,g,ARRAY[o.bu_id]))>0) THEN RAISE EXCEPTION 'dps.owned_input_group_bu_denied' USING ERRCODE='42501';END IF;
   END IF;
  END LOOP;
  SELECT jsonb_build_object('kind','input','source_id',source,'registry_id',registry,'owned_draft_input',private.dps_owned_draft_input(_tenant,source,cfg.id),'owned_originals',coalesce((SELECT jsonb_agg(jsonb_build_object('file_id',original.id,'setup_id',original.setup_id,'content_sha256',original.content_sha256,'verified_original_sha256',receipt.verified_original_sha256,'verified_size_bytes',receipt.verified_size_bytes::text,'source_request_key',raw.source_request_key,'ownership_request_key',raw.ownership_request_key) ORDER BY original.id) FROM private.dpd_raw_source_links raw JOIN private.dpd_original_intents original ON original.id=raw.file_id JOIN private.dpd_original_receipts receipt ON receipt.file_id=original.id WHERE raw.data_source_id=source AND raw.tenant_id=_tenant),'[]'),
   'owners',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.bu_id) FROM public.data_resource_registry_owner_bu o WHERE o.registry_id=registry AND o.tenant_id=_tenant),'[]'),
   'group_view_grants',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM public.data_resource_registry_grants v WHERE v.registry_id=registry AND v.tenant_id=_tenant AND v.principal_group_id=ANY(_groups) AND v.action='view'),'[]')) INTO item;
  result:=result||jsonb_build_array(item);
 END LOOP;
 IF private.dpw_source_allows(actor,_tenant,p.output_data_source_id,'edit') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant,p.output_data_source_id,'ingest') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dps.output_writer_ceiling_denied' USING ERRCODE='42501';END IF;
 FOR registry IN SELECT id FROM public.data_resource_registry WHERE tenant_id=_tenant AND (data_prep_pipeline_id=p.id OR data_source_id=p.output_data_source_id) ORDER BY id LOOP
  SELECT jsonb_build_object('kind',CASE WHEN r.data_prep_pipeline_id IS NOT NULL THEN 'pipeline' ELSE 'output' END,'registry_id',r.id,
   'owners',coalesce((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.bu_id) FROM public.data_resource_registry_owner_bu o WHERE o.registry_id=r.id AND o.tenant_id=_tenant),'[]'),
   'grants',coalesce((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM public.data_resource_registry_grants v WHERE v.registry_id=r.id AND v.tenant_id=_tenant),'[]')) INTO item
  FROM public.data_resource_registry r WHERE r.id=registry;
  result:=result||jsonb_build_array(item);
 END LOOP;
 IF (SELECT count(*) FROM jsonb_array_elements(result) x WHERE x->>'kind' IN('pipeline','output'))<>2 THEN RAISE EXCEPTION 'dps.pipeline_output_registry_required' USING ERRCODE='42501';END IF;
 RETURN result||jsonb_build_array(jsonb_build_object('kind','selection_catalog',
 'groups',coalesce((SELECT jsonb_agg(to_jsonb(group_header) ORDER BY group_header.id) FROM public.tenant_groups group_header WHERE group_header.tenant_id=_tenant AND group_header.id=ANY(_groups)),'[]'),
 'group_bu_assignments',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.group_id,a.bu_id) FROM public.bu_group_assignments a WHERE a.tenant_id=_tenant AND a.group_id=ANY(_groups)),'[]'),
 'business_units',coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY b.id) FROM public.business_units b WHERE b.tenant_id=_tenant),'[]')));
END $function$

CREATE OR REPLACE FUNCTION public.ssb_create_source(_tenant_id uuid, _bu_id uuid, _name text, _description text, _source_type text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,_bu_id,true);r private.ssb_create_receipts%ROWTYPE;s public.workspace_data_sources%ROWTYPE;
 canonical jsonb;aid bigint;
BEGIN
 IF _request_key IS NULL OR length(coalesce(btrim(_name),'')) NOT BETWEEN 2 AND 80 OR length(coalesce(_description,''))>500
 OR _source_type IS NULL OR _source_type NOT IN('csv','xlsx','json','api','database','manual') THEN RAISE EXCEPTION 'ssb.invalid_source_request' USING ERRCODE='22023';END IF;
 canonical:=jsonb_build_object('tenant_id',_tenant_id,'bu_id',_bu_id,'name',btrim(_name),'description',_description,'source_type',_source_type);
 PERFORM pg_advisory_xact_lock(hashtextextended('ssb:'||_tenant_id::text||':'||actor::text||':'||_request_key::text,0));
 SELECT * INTO r FROM private.ssb_create_receipts WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN
  IF r.input IS DISTINCT FROM canonical OR r.input_sha256 IS DISTINCT FROM private.dpw_hash(canonical) THEN RAISE EXCEPTION 'ssb.request_conflict' USING ERRCODE='PT409';END IF;
  RETURN private.ssb_status(actor,_tenant_id,r.source_id)||jsonb_build_object('is_new',false);
 END IF;
 INSERT INTO public.workspace_data_sources(tenant_id,bu_id,name,description,source_type,connection_config,inferred_schema,sample_rows,row_count,status,created_by)
 VALUES(_tenant_id,_bu_id,btrim(_name),_description,_source_type,'{}','[]','[]',0,'draft',actor) RETURNING * INTO s;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,_tenant_id,'workspace','data_source.bootstrap.create','workspace_data_source',s.id::text,
 jsonb_build_object('request_key',_request_key,'bu_id',_bu_id,'name',s.name,'source_type',s.source_type,'ownership_policy','actual_active_tenant_admin')) RETURNING id INTO aid;
 INSERT INTO private.ssb_create_receipts(tenant_id,actor_id,request_key,source_id,bu_id,input,input_sha256,audit_event_id)
 VALUES(_tenant_id,actor,_request_key,s.id,_bu_id,canonical,private.dpw_hash(canonical),aid);
 RETURN private.ssb_status(actor,_tenant_id,s.id)||jsonb_build_object('is_new',true);
END $function$

CREATE OR REPLACE FUNCTION private.fvi_structure_write_context(_tenant uuid, _actor uuid, _executor name, _depth integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
 IF _actor IS DISTINCT FROM auth.uid() THEN RETURN false;END IF;
 IF private.fvi_active_structure_admin(_tenant,_actor) THEN RETURN true;END IF;
 IF auth.role()='service_role' AND _executor IN ('service_role','postgres','supabase_admin') THEN RETURN true;END IF;
 IF auth.role() IS NULL AND _executor IN ('postgres','supabase_admin') THEN RETURN true;END IF;
 -- Only the existing nested new-tenant bootstrap, not a caller-controlled GUC.
 IF auth.role()='authenticated' AND _executor IN ('postgres','supabase_admin') AND _depth>1
   AND public.is_platform_admin(_actor) IS TRUE
   AND EXISTS(SELECT 1 FROM public.tenants t WHERE t.id=_tenant AND t.xmin=pg_current_xact_id()::xid)
 THEN RETURN true;END IF;
 RETURN false;
END $function$

CREATE OR REPLACE FUNCTION private.fvi_bu_structure_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
 IF NOT private.fvi_structure_write_context(NEW.tenant_id,auth.uid(),current_user,pg_trigger_depth()) THEN
   RAISE EXCEPTION 'Active tenant administrator required for business-unit writes' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND NEW.tenant_id=OLD.tenant_id AND NEW.parent_id IS NOT DISTINCT FROM OLD.parent_id THEN RETURN NEW;END IF;
 IF NEW.parent_id IS NOT NULL THEN
   PERFORM 1 FROM public.business_units b WHERE b.id=NEW.parent_id AND b.tenant_id=NEW.tenant_id AND NOT b.is_archived FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION 'Parent business unit must be active in this tenant' USING ERRCODE='22023';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.fvi_group_structure_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
 IF NOT private.fvi_structure_write_context(NEW.tenant_id,auth.uid(),current_user,pg_trigger_depth()) THEN
   RAISE EXCEPTION 'Active tenant administrator required for group writes' USING ERRCODE='42501';END IF;
 IF TG_OP='UPDATE' AND NEW.tenant_id=OLD.tenant_id AND NEW.bu_id IS NOT DISTINCT FROM OLD.bu_id THEN RETURN NEW;END IF;
 IF NEW.bu_id IS NULL THEN RAISE EXCEPTION 'Every new or reassociated group requires a business unit' USING ERRCODE='22023';END IF;
 PERFORM 1 FROM public.business_units b WHERE b.id=NEW.bu_id AND b.tenant_id=NEW.tenant_id AND NOT b.is_archived FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Group business unit must be active in this tenant' USING ERRCODE='22023';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.ssb_get_create_request(_tenant_id uuid, _bu_id uuid, _request_key uuid, _expected_input jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,_bu_id,true);r private.ssb_create_receipts%ROWTYPE;
BEGIN
 IF _request_key IS NULL OR jsonb_typeof(_expected_input) IS DISTINCT FROM 'object' OR _expected_input->>'tenant_id' IS DISTINCT FROM _tenant_id::text
 OR _expected_input->>'bu_id' IS DISTINCT FROM _bu_id::text THEN RAISE EXCEPTION 'ssb.lookup_scope_mismatch' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM private.ssb_create_receipts WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_key',_request_key,'lookup_state','absent');END IF;
 IF r.input IS DISTINCT FROM _expected_input OR r.input_sha256 IS DISTINCT FROM private.dpw_hash(_expected_input) THEN RAISE EXCEPTION 'ssb.request_conflict' USING ERRCODE='PT409';END IF;
 RETURN private.ssb_status(actor,_tenant_id,r.source_id)||jsonb_build_object('lookup_state','found','is_new',false);
END $function$

CREATE OR REPLACE FUNCTION public.ssb_get_ownership_request(_tenant_id uuid, _source_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);r private.ssb_ownership_receipts%ROWTYPE;state jsonb;
BEGIN
 IF private.ssb_is_admin(actor,_tenant_id) IS DISTINCT FROM true OR _request_key IS NULL THEN RAISE EXCEPTION 'ssb.actual_tenant_admin_ownership_required' USING ERRCODE='42501';END IF;
 state:=private.ssb_status(actor,_tenant_id,_source_id);
 SELECT * INTO r FROM private.ssb_ownership_receipts WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF NOT FOUND THEN RETURN state||jsonb_build_object('lookup_state','absent','request_key',_request_key);END IF;
 IF r.source_id IS DISTINCT FROM _source_id THEN RAISE EXCEPTION 'ssb.request_conflict' USING ERRCODE='PT409';END IF;
 RETURN state||jsonb_build_object('lookup_state','found','request_key',_request_key,'recorded_ownership',r.actual_editor,
 'ownership',public.get_typed_data_resource_editor(_tenant_id,'data_source',_source_id));
END $function$

CREATE OR REPLACE FUNCTION public.ssb_read_ownership(_tenant_id uuid, _source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);state jsonb;editor jsonb;registry uuid;
BEGIN
 state:=private.ssb_status(actor,_tenant_id,_source_id);
 IF private.ssb_is_admin(actor,_tenant_id) THEN
  editor:=public.get_typed_data_resource_editor(_tenant_id,'data_source',_source_id);
 ELSE
  -- Read actual mappings, not the administrator's full tenant/group catalog.
  SELECT id INTO registry FROM public.data_resource_registry WHERE tenant_id=_tenant_id AND resource_type='data_source' AND data_source_id=_source_id;
  editor:=jsonb_build_object('registered',private.ssb_is_mapped(_tenant_id,_source_id),
   'owner_bu_ids',coalesce((SELECT jsonb_agg(bu_id ORDER BY bu_id) FROM public.data_resource_registry_owner_bu WHERE tenant_id=_tenant_id AND registry_id=registry),'[]'),
   'group_ids',coalesce((SELECT jsonb_agg(gid ORDER BY gid) FROM(SELECT DISTINCT principal_group_id gid FROM public.data_resource_registry_grants WHERE tenant_id=_tenant_id AND registry_id=registry AND principal_type='group' AND action='view') g),'[]'),
   'business_units','[]'::jsonb,'user_groups','[]'::jsonb,'read_only',true);
 END IF;
 RETURN state||jsonb_build_object('ownership',editor);
END $function$

CREATE OR REPLACE FUNCTION public.ssb_read_source(_tenant_id uuid, _source_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);state jsonb;
BEGIN state:=private.ssb_status(actor,_tenant_id,_source_id);
 IF state->'can_bind' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'ssb.registered_current_source_view_required' USING ERRCODE='42501';END IF;
 RETURN state;END $function$

CREATE OR REPLACE FUNCTION public.ssb_save_ownership(_tenant_id uuid, _source_id uuid, _owner_bu_ids uuid[], _group_ids uuid[], _reason text, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.ssb_actor(_tenant_id,NULL,false);before_state jsonb;saved jsonb;after_state jsonb;canonical jsonb;r private.ssb_ownership_receipts%ROWTYPE;aid bigint;
BEGIN
 IF private.ssb_is_admin(actor,_tenant_id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'ssb.actual_tenant_admin_ownership_required' USING ERRCODE='42501';END IF;
 IF _request_key IS NULL OR length(coalesce(btrim(_reason),'')) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'ssb.invalid_ownership_request' USING ERRCODE='22023';END IF;
 canonical:=jsonb_build_object('source_id',_source_id,'owner_bu_ids',(SELECT jsonb_agg(x ORDER BY x) FROM(SELECT DISTINCT unnest(_owner_bu_ids) x) ids),
 'group_ids',coalesce((SELECT jsonb_agg(x ORDER BY x) FROM(SELECT DISTINCT unnest(_group_ids) x) ids),'[]'),'reason',btrim(_reason));
 PERFORM pg_advisory_xact_lock(hashtextextended('ssb-ownership:'||_tenant_id::text||':'||actor::text||':'||_request_key::text,0));
 before_state:=private.ssb_status(actor,_tenant_id,_source_id);
 SELECT * INTO r FROM private.ssb_ownership_receipts WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN
  IF r.source_id IS DISTINCT FROM _source_id OR r.input IS DISTINCT FROM canonical OR r.input_sha256 IS DISTINCT FROM private.dpw_hash(canonical)
  THEN RAISE EXCEPTION 'ssb.request_conflict' USING ERRCODE='PT409';END IF;
  RETURN before_state||jsonb_build_object('ownership',public.get_typed_data_resource_editor(_tenant_id,'data_source',_source_id),
  'recorded_ownership',r.actual_editor,'is_new',false,'request_key',_request_key);
 END IF;
 -- Exact existing ordinary administrator producer; all genuine tenant/BU/group
 -- assignment/current grants and registration/audit checks remain inside it.
 saved:=public.save_typed_data_resource_access(_tenant_id,'data_source',_source_id,_owner_bu_ids,_group_ids,_reason);
 after_state:=public.get_typed_data_resource_editor(_tenant_id,'data_source',_source_id);
 IF saved->'registered' IS DISTINCT FROM 'true'::jsonb OR after_state->'registered' IS DISTINCT FROM 'true'::jsonb
 OR (SELECT coalesce(array_agg(x ORDER BY x),'{}'::uuid[]) FROM(SELECT DISTINCT unnest(_owner_bu_ids) x) ids)
 IS DISTINCT FROM (SELECT coalesce(array_agg(x::uuid ORDER BY x::uuid),'{}'::uuid[]) FROM jsonb_array_elements_text(after_state->'owner_bu_ids') x)
 OR (SELECT coalesce(array_agg(x ORDER BY x),'{}'::uuid[]) FROM(SELECT DISTINCT unnest(_group_ids) x) ids)
 IS DISTINCT FROM (SELECT coalesce(array_agg(x::uuid ORDER BY x::uuid),'{}'::uuid[]) FROM jsonb_array_elements_text(after_state->'group_ids') x)
 THEN RAISE EXCEPTION 'ssb.ownership_readback_mismatch' USING ERRCODE='PT409';END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
 VALUES(actor,_tenant_id,'workspace','data_source.bootstrap.ownership','workspace_data_source',_source_id::text,
 canonical||jsonb_build_object('request_key',_request_key,'actual_editor',after_state)) RETURNING id INTO aid;
 INSERT INTO private.ssb_ownership_receipts(tenant_id,actor_id,request_key,source_id,input,input_sha256,actual_editor,audit_event_id)
 VALUES(_tenant_id,actor,_request_key,_source_id,canonical,private.dpw_hash(canonical),after_state,aid);
 RETURN private.ssb_status(actor,_tenant_id,_source_id)||jsonb_build_object('ownership',after_state,'saved',saved,'is_new',true,'request_key',_request_key);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_lookup_file_intent(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _feed_key text, _identity jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE authority jsonb:=public.dpw_authorize_file_intake(_tenant_id,_pipeline_id,_batch_id,_feed_key,'intake');
 f public.data_prep_delivery_files%ROWTYPE;
BEGIN
 IF NOT (_identity ? 'correction_of') OR (jsonb_typeof(_identity->'correction_of') IS DISTINCT FROM 'null' AND (jsonb_typeof(_identity->'correction_of') IS DISTINCT FROM 'string' OR (_identity->>'correction_of') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')) THEN RAISE EXCEPTION 'dpw.lookup_correction_identity_required';END IF;
 IF _identity->>'data_source_id' IS DISTINCT FROM authority->>'data_source_id'
 OR (_identity->>'pipeline_version')::integer IS DISTINCT FROM (authority->>'pipeline_version')::integer
 OR _identity->>'content_sha256' IS NULL OR _identity->>'content_sha256' !~ '^[a-f0-9]{64}$'
 OR _identity->>'request_key' IS NULL THEN RAISE EXCEPTION 'dpw.lookup_identity_mismatch'; END IF;
 SELECT x.* INTO f FROM public.data_prep_delivery_files x JOIN public.data_prep_file_requests a ON a.file_id=x.id
 WHERE a.batch_id=_batch_id AND a.feed_key=_feed_key AND a.request_key=(_identity->>'request_key')::uuid;
 IF FOUND AND (f.correction_of IS DISTINCT FROM nullif(_identity->>'correction_of','')::uuid OR f.content_sha256<>_identity->>'content_sha256' OR f.descriptor->'selected_sheet' IS DISTINCT FROM coalesce(_identity->'selected_sheet','null'::jsonb))
 THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
 IF f.id IS NULL THEN
  SELECT * INTO f FROM public.data_prep_delivery_files WHERE batch_id=_batch_id AND feed_key=_feed_key AND content_sha256=_identity->>'content_sha256';
  IF FOUND AND (f.correction_of IS DISTINCT FROM nullif(_identity->>'correction_of','')::uuid OR f.descriptor->'selected_sheet' IS DISTINCT FROM coalesce(_identity->'selected_sheet','null'::jsonb)) THEN RAISE EXCEPTION 'dpw.sheet_binding_conflict'; END IF;
 END IF;
 RETURN authority||jsonb_build_object('state',CASE WHEN f.id IS NULL THEN 'absent' ELSE 'found' END,'intent',CASE WHEN f.id IS NULL THEN NULL ELSE private.dpw_file_metadata(f) END);
END $function$

CREATE OR REPLACE FUNCTION private.dpd_request_actor(_tenant uuid, _setup uuid, _operation text, _request_context_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c private.dpd_request_contexts%ROWTYPE;actor uuid:=auth.uid();enabled boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' OR actor IS NULL OR _request_context_id IS NULL THEN RAISE EXCEPTION 'dpd.original_authenticated_context_required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM private.dpd_request_contexts WHERE id=_request_context_id AND tenant_id=_tenant AND actor_id=actor AND setup_id IS NOT DISTINCT FROM _setup AND operation=_operation;
 IF NOT FOUND OR c.expires_at<=clock_timestamp() OR c.verified_subject->>'sub' IS DISTINCT FROM actor::text OR c.verified_subject->>'aal' IS DISTINCT FROM auth.jwt()->>'aal' OR c.verified_subject->>'exp' IS DISTINCT FROM auth.jwt()->>'exp' THEN RAISE EXCEPTION 'dpd.fresh_original_request_context_required' USING ERRCODE='42501';END IF;
 PERFORM private.dpd_peer_actor(_tenant,c.verified_subject);IF private.wfm_actor(_tenant) IS DISTINCT FROM actor OR public.user_has_permission(actor,_tenant,CASE WHEN _operation IN('setup.create','setup.save','original.authorize','original.claim','source.register','preview.bind','parser.enqueue','review.shared.decide','preview.job.enqueue','preview.job.claim','review.setup.request','review.setup.decide','prepare.job.enqueue','publication.request','publication.decide','publication.perform') THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.actual_current_actor_denied' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant;
 IF NOT FOUND OR enabled IS NULL OR (enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(_tenant,host(c.request_ip)) IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'dpd.current_bound_network_denied' USING ERRCODE='42501';END IF;
 IF _operation IN('setup.create','setup.save','original.authorize','original.claim','source.register','preview.bind','parser.enqueue','review.shared.decide','preview.job.enqueue','preview.job.claim','review.setup.request','review.setup.decide','prepare.job.enqueue','publication.request','publication.decide','publication.perform') THEN PERFORM public.assert_data_prep_actor(_tenant,actor,false);END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.dpw_open_file_intent(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _feed_key text, _descriptor jsonb, _request_key uuid, _correction_of uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); b public.data_prep_delivery_batches%ROWTYPE;
 f public.data_prep_delivery_files%ROWTYPE; profile jsonb; fid uuid:=gen_random_uuid(); newfile boolean:=true;
BEGIN
 PERFORM private.wfm_assert_enabled(_tenant_id,'data');
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 b:=private.dpw_lock_batch(_tenant_id,_pipeline_id,_batch_id,actor,false);
 SELECT value INTO profile FROM jsonb_array_elements(b.configuration_snapshot->'feeds') WHERE value->>'key'=_feed_key;
 IF profile IS NULL OR private.dpw_source_allows(actor,_tenant_id,(profile->>'data_source_id')::uuid,'ingest') IS DISTINCT FROM true
 OR _request_key IS NULL OR jsonb_typeof(_descriptor) IS DISTINCT FROM 'object'
 OR (_descriptor->>'content_sha256') IS NULL OR (_descriptor->>'content_sha256') !~ '^[a-f0-9]{64}$'
 OR (_descriptor->>'parsed_sha256') IS NULL OR (_descriptor->>'parsed_sha256') !~ '^[a-f0-9]{64}$'
 OR (_descriptor->>'size_bytes') IS NULL OR (_descriptor->>'size_bytes')::bigint NOT BETWEEN 1 AND 52428800
 OR (_descriptor->>'parsed_bytes') IS NULL OR (_descriptor->>'parsed_bytes')::bigint NOT BETWEEN 2 AND 52428800
 OR (_descriptor->>'row_count') IS NULL OR (_descriptor->>'row_count')::integer NOT BETWEEN 0 AND 50000
 OR jsonb_typeof(_descriptor->'columns') IS DISTINCT FROM 'array' OR jsonb_array_length(_descriptor->'columns') NOT BETWEEN 1 AND 500
 OR length(coalesce(_descriptor->>'filename','')) NOT BETWEEN 1 AND 255 OR length(coalesce(_descriptor->>'mime_type','')) NOT BETWEEN 1 AND 255
 THEN RAISE EXCEPTION 'dpw.invalid_file_intent'; END IF;
 SELECT x.* INTO f FROM public.data_prep_delivery_files x JOIN public.data_prep_file_requests a ON a.file_id=x.id
 WHERE a.batch_id=b.id AND a.feed_key=_feed_key AND a.request_key=_request_key;
 IF FOUND THEN
  IF f.descriptor IS DISTINCT FROM _descriptor OR f.correction_of IS DISTINCT FROM _correction_of THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  newfile:=false;
 ELSE
  SELECT * INTO f FROM public.data_prep_delivery_files WHERE batch_id=b.id AND feed_key=_feed_key AND content_sha256=_descriptor->>'content_sha256';
  IF FOUND THEN
   IF f.descriptor IS DISTINCT FROM _descriptor OR f.correction_of IS DISTINCT FROM _correction_of THEN RAISE EXCEPTION 'dpw.same_file_descriptor_conflict'; END IF;
   newfile:=false;
  ELSE
   IF b.state<>'collecting' THEN RAISE EXCEPTION 'dpw.late_file_requires_correction'; END IF;
   IF _correction_of IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_files
   WHERE id=_correction_of AND batch_id=b.correction_of AND feed_key=_feed_key AND tenant_id=_tenant_id)
   THEN RAISE EXCEPTION 'dpw.file_correction_mismatch'; END IF;
   INSERT INTO public.data_prep_delivery_files(id,tenant_id,pipeline_id,batch_id,pipeline_version,feed_key,data_source_id,created_by,descriptor,request_key,content_sha256,original_path,correction_of)
   VALUES(fid,_tenant_id,_pipeline_id,b.id,b.pipeline_version,_feed_key,(profile->>'data_source_id')::uuid,actor,_descriptor,_request_key,
   _descriptor->>'content_sha256',_tenant_id::text||'/'||b.id::text||'/'||fid::text||'/original',_correction_of) RETURNING * INTO f;
  END IF;
 END IF;
 INSERT INTO public.data_prep_file_requests(batch_id,feed_key,request_key,file_id,requested_descriptor,created_by)
 VALUES(b.id,_feed_key,_request_key,f.id,_descriptor,actor) ON CONFLICT(batch_id,feed_key,request_key) DO NOTHING;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'file',private.dpw_file_metadata(f),'intent',private.dpw_file_metadata(f),'created',newfile,
 'storage_capability',jsonb_build_object('bucket_id','data-prep-inputs','public',false,'max_original_bytes',52428800,
 'max_expanded_bytes',52428800,'max_parsed_bytes',52428800,'max_rows',50000,'max_columns',500));
END $function$

CREATE OR REPLACE FUNCTION public.wfm_assert_recon_scope(_resource_id uuid, _kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE tenant uuid; actor uuid; receipt jsonb;
BEGIN
 IF _kind='definition' THEN SELECT r.tenant_id INTO tenant FROM public.recon_definitions r WHERE r.id=_resource_id;
 ELSIF _kind='governance_request' THEN SELECT r.tenant_id INTO tenant FROM public.recon_definition_governance_requests r WHERE r.id=_resource_id;
 ELSE RAISE EXCEPTION 'Invalid reconciliation scope' USING ERRCODE='22023';END IF;
 IF tenant IS NULL THEN RAISE EXCEPTION 'Current reconciliation scope is unavailable' USING ERRCODE='42501';END IF;
 receipt:=public.wfm_assert_current_section(tenant,'recons');
 RETURN receipt||jsonb_build_object('resource_id',_resource_id,'kind',_kind);
END $function$

CREATE OR REPLACE FUNCTION public.wfm_workspace_row_allowed(_tenant_id uuid, _page_key text)
 RETURNS boolean
 LANGUAGE plpgsql
