CREATE OR REPLACE FUNCTION private.wfm_workspace_write_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') THEN
  IF current_setting('role',true)='authenticated' THEN PERFORM private.wfm_actor(OLD.tenant_id);END IF;
  PERFORM private.wfm_assert_enabled(OLD.tenant_id,TG_ARGV[0]);END IF;
 IF TG_OP IN ('INSERT','UPDATE') THEN
  IF current_setting('role',true)='authenticated' THEN PERFORM private.wfm_actor(NEW.tenant_id);END IF;
  PERFORM private.wfm_assert_enabled(NEW.tenant_id,TG_ARGV[0]);END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END $function$

CREATE OR REPLACE FUNCTION public.assign_exceptions_from_rule(_tenant_id uuid, _rule_id uuid, _exception_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor_id uuid := auth.uid();
  rule_row public.exception_assignment_rules%ROWTYPE;
  exception_id uuid;
  exception_row public.recon_exceptions%ROWTYPE;
  candidate uuid;
  affected integer;
  assigned_count integer := 0;
  skipped_count integer := 0;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'assignment');

  IF actor_id IS NULL OR NOT (
    public.has_tenant_role(actor_id,_tenant_id,'tenant_admin')
    OR public.user_has_permission(actor_id,_tenant_id,'break.assign',NULL)
  ) THEN
    RAISE EXCEPTION 'forbidden: break.assign permission required';
  END IF;
  IF _exception_ids IS NULL OR cardinality(_exception_ids) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'assignment batch must contain 1 to 500 exception IDs';
  END IF;
  IF (SELECT count(DISTINCT selected.id) FROM unnest(_exception_ids) AS selected(id))
     <> cardinality(_exception_ids) THEN
    RAISE EXCEPTION 'assignment batch IDs must be non-null and unique';
  END IF;
  SELECT * INTO rule_row FROM public.exception_assignment_rules
  WHERE id=_rule_id AND tenant_id=_tenant_id AND enabled=true;
  IF NOT FOUND THEN RAISE EXCEPTION 'assignment rule not found'; END IF;

  FOREACH exception_id IN ARRAY _exception_ids LOOP
    SELECT * INTO exception_row FROM public.recon_exceptions
    WHERE id=exception_id AND tenant_id=_tenant_id FOR UPDATE;
    IF NOT FOUND OR exception_row.status<>'open' OR exception_row.assignee IS NOT NULL
       OR exception_row.lifecycle_state IN ('resolved','written_off')
       OR (rule_row.recon_id IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.recon_runs run
         WHERE run.id=exception_row.run_id AND run.tenant_id=_tenant_id
           AND run.definition_id=rule_row.recon_id
       )) THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;
    candidate := public.pick_next_assignee(
      _rule_id,
      exception_row.severity,
      exception_row.tags
    );
    IF candidate IS NULL THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;
    UPDATE public.recon_exceptions
    SET assignee=candidate, assigned_by=actor_id, assigned_at=now()
    WHERE id=exception_row.id AND tenant_id=_tenant_id
      AND status='open' AND assignee IS NULL
      AND lifecycle_state NOT IN ('resolved','written_off');
    GET DIAGNOSTICS affected = ROW_COUNT;
    IF affected<>1 THEN
      skipped_count := skipped_count + 1;
      CONTINUE;
    END IF;
    INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (actor_id,_tenant_id,'workspace','exception.auto_assigned','recon_exception',exception_row.id::text,
      jsonb_build_object('rule_id',_rule_id,'assignee_id',candidate));
    assigned_count := assigned_count + 1;
  END LOOP;
  RETURN jsonb_build_object('assigned',assigned_count,'skipped',skipped_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.collateral_qa_vm_create(_tenant uuid, _schedule uuid, _valuation_at timestamp with time zone, _exposure_reference text, _gross numeric, _assets jsonb, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_schedule public.collateral_schedules%ROWTYPE;
  v_id uuid;
  v_collateral numeric(20,4);
  v_net numeric(20,4);
  v_proposed numeric(20,4);
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant,'collateral');

  IF v_actor IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.collateral_qa_tenants scope
    JOIN public.tenant_members tm ON tm.tenant_id = scope.tenant_id
    WHERE scope.tenant_id = _tenant AND scope.enabled AND tm.user_id = v_actor
      AND tm.active AND tm.role::text IN ('tenant_admin','tenant_analyst')
  ) THEN RAISE EXCEPTION 'collateral_qa_access_denied' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_schedule FROM public.collateral_schedules
    WHERE id = _schedule AND tenant_id = _tenant AND schedule_type = 'VM';
  IF NOT FOUND OR _valuation_at IS NULL OR _gross IS NULL OR _gross < 0
     OR length(coalesce(_exposure_reference,'')) NOT BETWEEN 3 AND 120
     OR length(coalesce(_reason,'')) NOT BETWEEN 3 AND 1000
     OR jsonb_typeof(_assets) IS DISTINCT FROM 'array'
     OR jsonb_array_length(_assets) NOT BETWEEN 1 AND 20 THEN
    RAISE EXCEPTION 'invalid_synthetic_vm_inputs' USING ERRCODE='23514';
  END IF;
  IF (v_schedule.effective_from IS NOT NULL AND _valuation_at::date < v_schedule.effective_from)
     OR (v_schedule.effective_to IS NOT NULL AND _valuation_at::date > v_schedule.effective_to) THEN
    RAISE EXCEPTION 'vm_valuation_outside_agreement_period' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM jsonb_to_recordset(_assets) AS a(
      asset_type text, description text, provenance_reference text, market_value numeric, haircut_bps integer)
    WHERE length(coalesce(a.asset_type,'')) NOT BETWEEN 2 AND 80
      OR length(coalesce(a.description,'')) NOT BETWEEN 2 AND 160
      OR length(coalesce(a.provenance_reference,'')) NOT BETWEEN 3 AND 120
      OR a.market_value IS NULL OR a.market_value < 0
      OR a.haircut_bps IS NULL OR a.haircut_bps NOT BETWEEN 0 AND 10000
  ) THEN RAISE EXCEPTION 'invalid_synthetic_vm_asset' USING ERRCODE='23514'; END IF;
  SELECT sum(round(a.market_value * (10000 - a.haircut_bps) / 10000, 4))
    INTO v_collateral
  FROM jsonb_to_recordset(_assets) AS a(
    asset_type text, description text, provenance_reference text, market_value numeric, haircut_bps integer);
  v_net := greatest(_gross - v_collateral - v_schedule.threshold_amount, 0);
  v_proposed := CASE WHEN v_net < v_schedule.minimum_transfer THEN 0
    WHEN v_schedule.rounding > 0 THEN round(v_net / v_schedule.rounding) * v_schedule.rounding
    ELSE v_net END;
  INSERT INTO public.collateral_qa_vm_calls(
    tenant_id,schedule_id,valuation_at,exposure_reference,gross_exposure,
    eligible_collateral,threshold_snapshot,mta_snapshot,rounding_snapshot,
    proposed_vm,maker_id,maker_reason
  ) VALUES (_tenant,_schedule,_valuation_at,_exposure_reference,_gross,
    v_collateral,v_schedule.threshold_amount,v_schedule.minimum_transfer,
    v_schedule.rounding,v_proposed,v_actor,_reason) RETURNING id INTO v_id;
  INSERT INTO public.collateral_qa_vm_assets(
    call_id,asset_type,description,provenance_reference,market_value,haircut_bps)
  SELECT v_id,a.asset_type,a.description,a.provenance_reference,a.market_value,a.haircut_bps
  FROM jsonb_to_recordset(_assets) AS a(
    asset_type text, description text, provenance_reference text, market_value numeric, haircut_bps integer);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(v_actor,_tenant,'tenant','collateral.qa_vm.created','collateral_qa_vm_call',v_id::text,
    jsonb_build_object('schedule_id',_schedule,'proposed_vm',v_proposed,'synthetic',true));
  RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.collateral_qa_vm_transition(_tenant uuid, _call uuid, _action text, _reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_role text;
  v_call public.collateral_qa_vm_calls%ROWTYPE;
  v_status text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant,'collateral');

  SELECT tm.role::text INTO v_role FROM public.collateral_qa_tenants scope
  JOIN public.tenant_members tm ON tm.tenant_id=scope.tenant_id
  WHERE scope.tenant_id=_tenant AND scope.enabled AND tm.user_id=v_actor AND tm.active;
  IF v_role IS NULL OR length(coalesce(_reason,'')) NOT BETWEEN 3 AND 1000 THEN
    RAISE EXCEPTION 'collateral_qa_access_denied' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_call FROM public.collateral_qa_vm_calls
    WHERE id=_call AND tenant_id=_tenant FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'collateral_qa_call_not_found' USING ERRCODE='02000'; END IF;
  IF _action='submit' AND v_call.status='draft' AND v_call.maker_id=v_actor THEN
    v_status := 'pending_checker';
    UPDATE public.collateral_qa_vm_calls SET status=v_status,updated_at=now() WHERE id=_call;
  ELSIF _action IN ('approve','reject') AND v_call.status='pending_checker'
      AND v_role='tenant_admin' AND v_call.maker_id<>v_actor THEN
    v_status := CASE WHEN _action='approve' THEN 'approved' ELSE 'rejected' END;
    UPDATE public.collateral_qa_vm_calls SET status=v_status,checker_id=v_actor,
      checker_reason=_reason,updated_at=now() WHERE id=_call;
  ELSIF _action='record_settlement' AND v_call.status='approved'
      AND v_role IN ('tenant_admin','tenant_analyst') AND v_call.maker_id=v_actor THEN
    v_status := 'settlement_recorded';
    UPDATE public.collateral_qa_vm_calls SET status=v_status,
      internal_settlement_reference=_reason,settlement_recorded_at=now(),updated_at=now() WHERE id=_call;
  ELSE RAISE EXCEPTION 'invalid_collateral_qa_transition' USING ERRCODE='42501'; END IF;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(v_actor,_tenant,'tenant','collateral.qa_vm.'||_action,'collateral_qa_vm_call',_call::text,
    jsonb_build_object('from',v_call.status,'to',v_status,'synthetic',true));
  RETURN v_status;
END $function$

CREATE OR REPLACE FUNCTION public.create_collateral_csa_draft(_tenant_id uuid, _agreement_id uuid, _agreement_key text, _own_legal_entity text, _counterparty text, _currency text, _threshold_amount numeric, _minimum_transfer numeric, _rounding_increment numeric, _effective_from date, _effective_to date, _terms_snapshot jsonb, _idempotency_key text)
 RETURNS TABLE(agreement_id uuid, version_id uuid, version_no integer, replayed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  actor uuid := auth.uid();
  agreement_row public.collateral_csa_agreements%ROWTYPE;
  version_row public.collateral_csa_versions%ROWTYPE;
  request_digest text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'collateral');

  IF NOT public.csa_assurance_actor(_tenant_id,actor) THEN
    RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';
  END IF;
  IF _threshold_amount < 0 OR _minimum_transfer < 0 OR _rounding_increment < 0
     OR _effective_to IS NOT NULL AND _effective_to < _effective_from
     OR _currency !~ '^[A-Z]{3}$' OR _terms_snapshot IS NULL OR jsonb_typeof(_terms_snapshot) <> 'object' THEN
    RAISE EXCEPTION 'Invalid bilateral VM agreement terms' USING ERRCODE='22023';
  END IF;
  request_digest := encode(extensions.digest(jsonb_build_object(
    'agreement_id',_agreement_id,'agreement_key',_agreement_key,'own_legal_entity',_own_legal_entity,
    'counterparty',_counterparty,'currency',_currency,'threshold_amount',_threshold_amount,
    'minimum_transfer',_minimum_transfer,'rounding_increment',_rounding_increment,
    'effective_from',_effective_from,'effective_to',_effective_to,'terms_snapshot',_terms_snapshot
  )::text,'sha256'),'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||':'||actor::text||':'||_idempotency_key,0));
  SELECT * INTO version_row FROM public.collateral_csa_versions
    WHERE tenant_id=_tenant_id AND created_by=actor AND idempotency_key=_idempotency_key;
  IF FOUND THEN
    IF version_row.request_hash <> request_digest THEN RAISE EXCEPTION 'Idempotency key reused with different agreement terms' USING ERRCODE='22023'; END IF;
    RETURN QUERY SELECT version_row.agreement_id,version_row.id,version_row.version_no,true; RETURN;
  END IF;
  IF _agreement_id IS NULL THEN
    IF _agreement_key IS NULL OR _own_legal_entity IS NULL OR _counterparty IS NULL THEN
      RAISE EXCEPTION 'New agreement identity is required' USING ERRCODE='22023';
    END IF;
    INSERT INTO public.collateral_csa_agreements(tenant_id,agreement_key,own_legal_entity,counterparty,currency,created_by)
    VALUES (_tenant_id,_agreement_key,_own_legal_entity,_counterparty,_currency,actor) RETURNING * INTO agreement_row;
  ELSE
    SELECT * INTO agreement_row FROM public.collateral_csa_agreements
      WHERE id=_agreement_id AND tenant_id=_tenant_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Agreement is unavailable in this tenant' USING ERRCODE='42501'; END IF;
    IF agreement_row.currency IS DISTINCT FROM _currency OR agreement_row.agreement_key IS DISTINCT FROM _agreement_key
       OR agreement_row.own_legal_entity IS DISTINCT FROM _own_legal_entity OR agreement_row.counterparty IS DISTINCT FROM _counterparty THEN
      RAISE EXCEPTION 'Agreement identity is immutable' USING ERRCODE='22023';
    END IF;
  END IF;
  INSERT INTO public.collateral_csa_versions(tenant_id,agreement_id,version_no,threshold_amount,minimum_transfer,
    rounding_increment,effective_from,effective_to,terms_snapshot,created_by,idempotency_key,request_hash)
  SELECT _tenant_id,agreement_row.id,coalesce(max(v.version_no),0)+1,_threshold_amount,_minimum_transfer,
    _rounding_increment,_effective_from,_effective_to,coalesce(_terms_snapshot,'{}'::jsonb),actor,_idempotency_key,request_digest
  FROM public.collateral_csa_versions v WHERE v.tenant_id=_tenant_id AND v.agreement_id=agreement_row.id
  RETURNING * INTO version_row;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(actor,_tenant_id,'tenant','collateral.csa.version.draft','collateral_csa_version',version_row.id::text,
    jsonb_build_object('agreement_id',agreement_row.id,'version_no',version_row.version_no,'currency',_currency));
  RETURN QUERY SELECT agreement_row.id,version_row.id,version_row.version_no,false;
END $function$

CREATE OR REPLACE FUNCTION public.create_recon_definition_with_owners(_tenant_id uuid, _name text, _description text, _recon_type text, _sides jsonb, _rules jsonb, _owner_bu_ids uuid[])
 RETURNS TABLE(id uuid, recon_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean;
  v_bu_ids uuid[];
  v_source_ids uuid[];
  v_source_count integer;
  v_side_count integer;
  v_definition_id uuid;
  v_recon_code text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF v_actor IS NULL OR _tenant_id IS NULL OR length(btrim(coalesce(_name,''))) NOT BETWEEN 1 AND 200
     OR _recon_type IS NULL OR _recon_type NOT IN ('one_sided','two_sided','three_sided')
     OR jsonb_typeof(coalesce(_sides,'[]'::jsonb)) <> 'array'
     OR jsonb_typeof(coalesce(_rules,'[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'invalid reconciliation creation request' USING ERRCODE='22023';
  END IF;
  v_side_count := jsonb_array_length(coalesce(_sides,'[]'::jsonb));
  IF v_side_count <> (CASE _recon_type WHEN 'one_sided' THEN 1 WHEN 'two_sided' THEN 2 ELSE 3 END)
     OR EXISTS (
       SELECT 1 FROM jsonb_array_elements(coalesce(_sides,'[]'::jsonb)) side
       WHERE nullif(side->>'data_source_id','') IS NULL
          OR (nullif(side->>'upload_id','') IS NOT NULL
            AND NOT EXISTS (
              SELECT 1 FROM public.workspace_data_source_uploads upload_row
              WHERE upload_row.id=(side->>'upload_id')::uuid
                AND upload_row.tenant_id=_tenant_id
                AND upload_row.data_source_id=(side->>'data_source_id')::uuid
            ))
     ) THEN
    RAISE EXCEPTION 'source bindings must be complete and belong to this workspace' USING ERRCODE='42501';
  END IF;
  SELECT coalesce(array_agg(DISTINCT nullif(side->>'data_source_id','')::uuid
                            ORDER BY nullif(side->>'data_source_id','')::uuid),ARRAY[]::uuid[])
  INTO v_source_ids
  FROM jsonb_array_elements(coalesce(_sides,'[]'::jsonb)) side;
  SELECT count(DISTINCT source_row.id) INTO v_source_count
  FROM public.workspace_data_sources source_row
  WHERE source_row.tenant_id=_tenant_id AND source_row.id=ANY(v_source_ids);
  IF v_source_count <> cardinality(v_source_ids) THEN
    RAISE EXCEPTION 'one or more reconciliation sources are unavailable in this workspace' USING ERRCODE='42501';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_members member_row
    WHERE member_row.tenant_id=_tenant_id AND member_row.user_id=v_actor
      AND member_row.active AND member_row.role::text='tenant_admin'
  ) INTO v_is_admin;
  IF NOT v_is_admin AND NOT private.recon_governance_is_active_analyst(_tenant_id,v_actor) THEN
    RAISE EXCEPTION 'active tenant administrator or analyst required' USING ERRCODE='42501';
  END IF;

  SELECT coalesce(array_agg(DISTINCT bu_id ORDER BY bu_id), ARRAY[]::uuid[])
  INTO v_bu_ids FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) AS bu_id;
  IF cardinality(v_bu_ids)=0 THEN
    RAISE EXCEPTION 'at least one owning business unit is required' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_bu_ids) requested(bu_id)
    LEFT JOIN public.business_units bu
      ON bu.id=requested.bu_id AND bu.tenant_id=_tenant_id
    WHERE bu.id IS NULL OR bu.is_archived
  ) THEN
    RAISE EXCEPTION 'owning business units must be active and belong to the reconciliation tenant' USING ERRCODE='22023';
  END IF;
  IF NOT v_is_admin AND EXISTS (
    SELECT 1 FROM unnest(v_bu_ids) requested(bu_id)
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.bu_user_assignments assignment
      JOIN public.business_units assigned_bu
        ON assigned_bu.id=assignment.bu_id AND assigned_bu.tenant_id=assignment.tenant_id
        AND NOT assigned_bu.is_archived
      JOIN public.business_units owner_bu
        ON owner_bu.id=requested.bu_id AND owner_bu.tenant_id=assignment.tenant_id
        AND NOT owner_bu.is_archived
      WHERE assignment.tenant_id=_tenant_id AND assignment.user_id=v_actor
        AND (owner_bu.id=assigned_bu.id
          OR (assignment.inherit_descendants AND owner_bu.path <@ assigned_bu.path))
    )
  ) THEN
    RAISE EXCEPTION 'analyst must be assigned to every selected owning business unit' USING ERRCODE='42501';
  END IF;

  INSERT INTO public.recon_definitions(
    tenant_id,name,description,recon_type,sides,rules,status,created_by,
    governance_state,access_mode,multi_bu_governed
  ) VALUES (
    _tenant_id,btrim(_name),nullif(btrim(coalesce(_description,'')),''),_recon_type,
    coalesce(_sides,'[]'::jsonb),coalesce(_rules,'[]'::jsonb),'draft',v_actor,
    'development_draft','unmapped_pending',false
  ) RETURNING recon_definitions.id,recon_definitions.recon_code
    INTO v_definition_id,v_recon_code;

  INSERT INTO public.recon_definition_business_units(tenant_id,recon_id,bu_id,created_by)
  SELECT _tenant_id,v_definition_id,owner_id,v_actor FROM unnest(v_bu_ids) owner_id;

  INSERT INTO public.recon_definition_bu_admin_audit(
    tenant_id,recon_id,operation,actor_id,reason,details
  ) VALUES (
    _tenant_id,v_definition_id,'replace_owners',v_actor,
    'Atomic definition creation owner binding',
    jsonb_build_object('previous_bu_ids',ARRAY[]::uuid[],'new_bu_ids',v_bu_ids,'source','atomic_create')
  );

  -- Active tenant admins have the authoritative in-tenant override and may
  -- not have per-BU assignments. Analysts were checked above for every owner
  -- BU, so grant only their explicit draft capabilities.
  IF NOT v_is_admin THEN
    INSERT INTO public.recon_definition_bu_grants(
      tenant_id,recon_id,bu_id,principal_type,principal_id,action,granted_by
    )
    SELECT _tenant_id,v_definition_id,owner_id,'user',v_actor,action_name,v_actor
    FROM unnest(v_bu_ids) owner_id
    CROSS JOIN unnest(ARRAY['view','edit','run']::text[]) action_name;
  END IF;

  UPDATE public.recon_definitions
  SET access_mode='mapped_exact',multi_bu_governed=true
  WHERE recon_definitions.id=v_definition_id AND recon_definitions.tenant_id=_tenant_id;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (
    v_actor,_tenant_id,'workspace','recon.create','recon_definition',v_definition_id::text,
    jsonb_build_object('recon_code',v_recon_code,'name',btrim(_name),'type',_recon_type,
      'owner_bu_ids',v_bu_ids)
  );

  RETURN QUERY SELECT v_definition_id,v_recon_code;
END
$function$

CREATE OR REPLACE FUNCTION public.decide_collateral_csa_version(_tenant_id uuid, _version_id uuid, _approve boolean, _reason text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid := auth.uid(); version_row public.collateral_csa_versions%ROWTYPE; other_active public.collateral_csa_versions%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'collateral');

  IF NOT public.csa_assurance_actor(_tenant_id,actor) THEN
    RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO version_row FROM public.collateral_csa_versions WHERE tenant_id=_tenant_id AND id=_version_id FOR UPDATE;
  IF NOT FOUND OR version_row.status<>'pending_approval' THEN RAISE EXCEPTION 'Version is not awaiting approval' USING ERRCODE='22023'; END IF;
  IF actor=version_row.created_by OR actor=version_row.submitted_by THEN RAISE EXCEPTION 'Maker and checker must be different users' USING ERRCODE='42501'; END IF;
  IF _approve THEN
    PERFORM 1 FROM public.collateral_csa_agreements WHERE tenant_id=_tenant_id AND id=version_row.agreement_id FOR UPDATE;
    IF EXISTS (SELECT 1 FROM public.collateral_csa_versions v WHERE v.tenant_id=_tenant_id AND v.agreement_id=version_row.agreement_id
      AND v.status IN ('active','superseded') AND daterange(v.effective_from,v.effective_to,'[]')
        && daterange(version_row.effective_from,version_row.effective_to,'[]')) THEN
      RAISE EXCEPTION 'Effective period overlaps the current active agreement version' USING ERRCODE='22023';
    END IF;
    SELECT * INTO other_active FROM public.collateral_csa_versions WHERE tenant_id=_tenant_id AND agreement_id=version_row.agreement_id AND id<>_version_id AND status='active';
    IF FOUND THEN UPDATE public.collateral_csa_versions SET status='superseded' WHERE id=other_active.id; END IF;
    UPDATE public.collateral_csa_versions SET status='active',approved_by=actor,approved_at=now() WHERE id=_version_id;
  ELSE
    UPDATE public.collateral_csa_versions SET status='rejected' WHERE id=_version_id;
  END IF;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(actor,_tenant_id,'tenant',CASE WHEN _approve THEN 'collateral.csa.version.activate' ELSE 'collateral.csa.version.reject' END,
    'collateral_csa_version',_version_id::text,jsonb_build_object('version_no',version_row.version_no,'reason',left(coalesce(_reason,''),1000)));
  RETURN CASE WHEN _approve THEN 'active' ELSE 'rejected' END;
END $function$

CREATE OR REPLACE FUNCTION public.decide_reference_data_version(_tenant_id uuid, _version_id uuid, _approve boolean, _reason text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  actor uuid := auth.uid();
  v_version public.reference_data_versions%ROWTYPE;
  v_prior public.reference_data_versions%ROWTYPE;
  v_is_effective_now boolean;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  SELECT * INTO v_version
  FROM public.reference_data_versions
  WHERE id = _version_id AND tenant_id = _tenant_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reference version not found'; END IF;
  IF actor IS NULL OR NOT (
    EXISTS (
      SELECT 1 FROM public.tenant_members tm
      WHERE tm.user_id = actor AND tm.tenant_id = _tenant_id
        AND tm.role = 'tenant_admin' AND tm.active
    ) OR public.is_platform_admin(actor)
  ) THEN
    RAISE EXCEPTION 'Forbidden: active tenant administrator required' USING ERRCODE = '42501';
  END IF;
  IF actor = v_version.created_by OR actor = v_version.submitted_by THEN
    RAISE EXCEPTION 'Maker cannot approve or reject their own version' USING ERRCODE = '42501';
  END IF;
  IF v_version.status <> 'pending_approval' THEN
    RAISE EXCEPTION 'Only a pending version may be decided';
  END IF;
  IF NOT _approve AND length(btrim(coalesce(_reason, ''))) < 3 THEN
    RAISE EXCEPTION 'Rejection reason must contain at least 3 characters';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_version.table_id::text, 0));
  IF NOT _approve THEN
    UPDATE public.reference_data_versions
    SET status = 'rejected', decided_by = actor, decided_at = now(),
        decision_reason = btrim(_reason)
    WHERE id = _version_id;
    INSERT INTO public.audit_log(
      actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
    ) VALUES (
      actor, _tenant_id, 'tenant', 'reference_data.version.reject',
      'reference_data_versions', _version_id::text,
      jsonb_build_object('table_id', v_version.table_id, 'version', v_version.version_number,
        'reason', btrim(_reason), 'content_sha256', v_version.content_sha256)
    );
    RETURN 'rejected';
  END IF;

  SELECT * INTO v_prior
  FROM public.reference_data_versions rdv
  WHERE rdv.table_id = v_version.table_id
    AND rdv.status IN ('published','superseded')
  ORDER BY rdv.effective_from DESC, rdv.version_number DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND AND v_version.effective_from <= v_prior.effective_from THEN
    RAISE EXCEPTION 'Approved versions must advance the effective date';
  END IF;
  IF FOUND AND (v_prior.effective_to IS NULL OR v_prior.effective_to >= v_version.effective_from) THEN
    UPDATE public.reference_data_versions
    SET effective_to = v_version.effective_from - 1
    WHERE id = v_prior.id;
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.reference_data_versions rdv
    WHERE rdv.table_id = v_version.table_id
      AND rdv.id <> v_version.id
      AND rdv.id <> v_prior.id
      AND rdv.status IN ('published','superseded')
      AND daterange(rdv.effective_from, coalesce(rdv.effective_to, 'infinity'::date), '[]')
          && daterange(v_version.effective_from, coalesce(v_version.effective_to, 'infinity'::date), '[]')
  ) THEN
    RAISE EXCEPTION 'Published reference version effective dates overlap';
  END IF;

  UPDATE public.reference_data_versions
  SET status = 'published', decided_by = actor, decided_at = now(),
      decision_reason = nullif(btrim(coalesce(_reason, '')), ''), published_at = now()
  WHERE id = _version_id;

  v_is_effective_now := v_version.effective_from <= current_date
    AND (v_version.effective_to IS NULL OR v_version.effective_to >= current_date);
  IF v_is_effective_now THEN
    UPDATE public.reference_data_versions
    SET status = 'superseded'
    WHERE table_id = v_version.table_id AND id <> v_version.id AND status = 'published'
      AND effective_from <= current_date
      AND (effective_to IS NULL OR effective_to >= current_date);

    DELETE FROM public.reference_data_rows
    WHERE table_id = v_version.table_id AND tenant_id = _tenant_id;
    INSERT INTO public.reference_data_rows(table_id, tenant_id, row_data, version_id)
    SELECT v_version.table_id, _tenant_id, r.row_data, v_version.id
    FROM public.reference_data_version_rows r
    WHERE r.version_id = v_version.id;
    UPDATE public.reference_data_tables
    SET row_count = v_version.row_count, published_version_id = v_version.id
    WHERE id = v_version.table_id AND tenant_id = _tenant_id;
  END IF;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    actor, _tenant_id, 'tenant', 'reference_data.version.publish',
    'reference_data_versions', _version_id::text,
    jsonb_build_object('table_id', v_version.table_id, 'version', v_version.version_number,
      'rows', v_version.row_count, 'content_sha256', v_version.content_sha256,
      'effective_from', v_version.effective_from, 'effective_to', v_version.effective_to,
      'projection_updated', v_is_effective_now)
  );
  RETURN 'published';
END;
$function$

CREATE OR REPLACE FUNCTION public.import_recon_definitions_with_owners(_tenant_id uuid, _definitions jsonb, _owner_bu_ids uuid[], _mode text DEFAULT 'skip'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_is_admin boolean;
  v_owner_ids uuid[];
  v_existing_owner_ids uuid[];
  v_item jsonb;
  v_name text;
  v_description text;
  v_recon_type text;
  v_sides jsonb;
  v_rules jsonb;
  v_side_count integer;
  v_source_count integer;
  v_distinct_source_count integer;
  v_existing_id uuid;
  v_existing_status text;
  v_existing_state text;
  v_existing_access text;
  v_existing_environment text;
  v_existing_multi_bu boolean;
  v_inserted integer := 0;
  v_updated integer := 0;
  v_skipped integer := 0;
  v_created record;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF v_actor IS NULL OR _tenant_id IS NULL OR _mode IS NULL OR _mode NOT IN ('skip','overwrite')
     OR jsonb_typeof(_definitions) IS DISTINCT FROM 'array'
     OR jsonb_array_length(_definitions) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'invalid reconciliation import request' USING ERRCODE='22023';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.tenant_members member_row
    WHERE member_row.tenant_id=_tenant_id AND member_row.user_id=v_actor
      AND member_row.active AND member_row.role::text='tenant_admin'
  ) INTO v_is_admin;
  IF NOT v_is_admin AND NOT private.recon_governance_is_active_analyst(_tenant_id,v_actor) THEN
    RAISE EXCEPTION 'active tenant administrator or analyst required' USING ERRCODE='42501';
  END IF;

  SELECT coalesce(array_agg(DISTINCT bu_id ORDER BY bu_id),ARRAY[]::uuid[])
  INTO v_owner_ids FROM unnest(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) AS bu_id;
  IF cardinality(v_owner_ids)=0 OR cardinality(v_owner_ids)<>cardinality(coalesce(_owner_bu_ids,ARRAY[]::uuid[])) THEN
    RAISE EXCEPTION 'choose one or more distinct owning business units' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM unnest(v_owner_ids) requested(bu_id)
    LEFT JOIN public.business_units bu ON bu.id=requested.bu_id AND bu.tenant_id=_tenant_id
    WHERE bu.id IS NULL OR bu.is_archived
  ) THEN
    RAISE EXCEPTION 'owning business units must be active and belong to this tenant' USING ERRCODE='42501';
  END IF;
  IF NOT v_is_admin AND EXISTS (
    SELECT 1 FROM unnest(v_owner_ids) requested(bu_id)
    WHERE NOT EXISTS (
      SELECT 1 FROM public.bu_user_assignments assignment
      JOIN public.business_units assigned_bu
        ON assigned_bu.id=assignment.bu_id AND assigned_bu.tenant_id=assignment.tenant_id
        AND NOT assigned_bu.is_archived
      JOIN public.business_units owner_bu
        ON owner_bu.id=requested.bu_id AND owner_bu.tenant_id=assignment.tenant_id
        AND NOT owner_bu.is_archived
      WHERE assignment.tenant_id=_tenant_id AND assignment.user_id=v_actor
        AND (owner_bu.id=assigned_bu.id OR (assignment.inherit_descendants AND owner_bu.path <@ assigned_bu.path))
    )
  ) THEN
    RAISE EXCEPTION 'analyst must be assigned to every selected owning business unit' USING ERRCODE='42501';
  END IF;

  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_definitions) item
    GROUP BY lower(btrim(coalesce(item->>'name','')))
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'import file contains duplicate definition names' USING ERRCODE='22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(_definitions) AS items(value)
  LOOP
    v_name := btrim(coalesce(v_item->>'name',''));
    v_description := nullif(btrim(coalesce(v_item->>'description','')),'');
    v_recon_type := v_item->>'recon_type';
    v_sides := v_item->'sides';
    v_rules := v_item->'rules';
    IF jsonb_typeof(v_item) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_item->'name') IS DISTINCT FROM 'string'
       OR (v_item ? 'description' AND jsonb_typeof(v_item->'description') NOT IN ('string','null'))
       OR length(v_name) NOT BETWEEN 1 AND 120
       OR length(coalesce(v_description,'')) > 2000
       OR v_recon_type IS NULL OR v_recon_type NOT IN ('one_sided','two_sided','three_sided')
       OR jsonb_typeof(v_sides) IS DISTINCT FROM 'array'
       OR jsonb_typeof(v_rules) IS DISTINCT FROM 'array'
       OR jsonb_array_length(v_sides) > 3
       OR jsonb_array_length(v_rules) > 100
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_sides) side WHERE jsonb_typeof(side) IS DISTINCT FROM 'object')
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(v_rules) rule WHERE jsonb_typeof(rule) IS DISTINCT FROM 'object') THEN
      RAISE EXCEPTION 'an imported definition has invalid fields' USING ERRCODE='22023';
    END IF;
    v_side_count := jsonb_array_length(v_sides);
    IF v_side_count <> (CASE v_recon_type WHEN 'one_sided' THEN 1 WHEN 'two_sided' THEN 2 ELSE 3 END)
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(v_sides) side
         WHERE coalesce(side->>'data_source_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       ) THEN
      RAISE EXCEPTION 'an imported definition has incomplete source bindings' USING ERRCODE='22023';
    END IF;
    SELECT count(*) INTO v_distinct_source_count
    FROM (
      SELECT DISTINCT (side->>'data_source_id')::uuid AS id
      FROM jsonb_array_elements(v_sides) side
    ) imported_ids;
    SELECT count(DISTINCT source_row.id) INTO v_source_count
    FROM public.workspace_data_sources source_row
    JOIN (
      SELECT DISTINCT (side->>'data_source_id')::uuid AS id
      FROM jsonb_array_elements(v_sides) side
    ) imported_source ON imported_source.id=source_row.id
    WHERE source_row.tenant_id=_tenant_id;
    IF v_source_count <> v_distinct_source_count THEN
      RAISE EXCEPTION 'every imported source must belong to this tenant' USING ERRCODE='42501';
    END IF;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_sides) side
      WHERE nullif(side->>'upload_id','') IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.workspace_data_source_uploads upload_row
          WHERE upload_row.id=(side->>'upload_id')::uuid AND upload_row.tenant_id=_tenant_id
            AND upload_row.data_source_id=(side->>'data_source_id')::uuid
        )
    ) THEN
      RAISE EXCEPTION 'every imported upload must belong to its same-tenant source' USING ERRCODE='42501';
    END IF;

    SELECT definition_row.id, definition_row.status, definition_row.governance_state,
           definition_row.access_mode, definition_row.environment, definition_row.multi_bu_governed
    INTO v_existing_id, v_existing_status, v_existing_state, v_existing_access,
         v_existing_environment, v_existing_multi_bu
    FROM public.recon_definitions definition_row
    WHERE definition_row.tenant_id=_tenant_id AND lower(definition_row.name)=lower(v_name)
    ORDER BY definition_row.created_at, definition_row.id
    LIMIT 1 FOR UPDATE;

    IF v_existing_id IS NOT NULL THEN
      IF _mode='skip' THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;
      IF v_existing_status IS DISTINCT FROM 'draft'
         OR v_existing_state IS DISTINCT FROM 'development_draft'
         OR v_existing_access IS DISTINCT FROM 'mapped_exact'
         OR v_existing_environment IS DISTINCT FROM 'development'
         OR v_existing_multi_bu IS DISTINCT FROM true
         OR NOT private.recon_authoritative_access_decision(v_existing_id,'read')
         OR NOT private.recon_authoritative_access_decision(v_existing_id,'edit') THEN
        RAISE EXCEPTION 'only an editable development draft can be overwritten; the batch was not applied' USING ERRCODE='42501';
      END IF;
      SELECT coalesce(array_agg(owner_row.bu_id ORDER BY owner_row.bu_id),ARRAY[]::uuid[])
      INTO v_existing_owner_ids
      FROM public.recon_definition_business_units owner_row
      WHERE owner_row.tenant_id=_tenant_id AND owner_row.recon_id=v_existing_id;
      IF v_existing_owner_ids IS DISTINCT FROM v_owner_ids THEN
        RAISE EXCEPTION 'overwrite owner units must match the existing definition exactly' USING ERRCODE='42501';
      END IF;
      UPDATE public.recon_definitions
      SET description=v_description, recon_type=v_recon_type, sides=v_sides, rules=v_rules
      WHERE id=v_existing_id AND tenant_id=_tenant_id;
      IF NOT FOUND THEN RAISE EXCEPTION 'an imported definition could not be updated'; END IF;
      INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
      VALUES (v_actor,_tenant_id,'workspace','recon.bulk_import.overwrite','recon_definition',v_existing_id::text,
        jsonb_build_object('name',v_name,'owner_bu_ids',v_owner_ids,'mode',_mode));
      v_updated := v_updated + 1;
    ELSE
      SELECT * INTO v_created
      FROM public.create_recon_definition_with_owners(
        _tenant_id,v_name,v_description,v_recon_type,v_sides,v_rules,v_owner_ids
      );
      IF v_created.id IS NULL THEN RAISE EXCEPTION 'an imported definition was not created'; END IF;
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,context)
  VALUES (v_actor,_tenant_id,'workspace','recon.bulk_import','recon_definitions',
    jsonb_build_object('inserted',v_inserted,'updated',v_updated,'skipped',v_skipped,'mode',_mode,
      'owner_bu_ids',v_owner_ids,'definition_count',jsonb_array_length(_definitions)));
  RETURN jsonb_build_object('inserted',v_inserted,'updated',v_updated,'skipped',v_skipped);
END
$function$

CREATE OR REPLACE FUNCTION public.install_recon_starter_template_atomic(_tenant_id uuid, _template_id uuid, _name text, _sides jsonb, _rules jsonb)
 RETURNS TABLE(recon_definition_id uuid, recon_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  template_row public.recon_definition_templates%ROWTYPE;
  new_definition public.recon_definitions%ROWTYPE;
  leg_count integer;
  valid_source_count integer;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'templates');
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT (
    public.is_platform_admin(actor)
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_admin')
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_analyst')
  ) THEN
    RAISE EXCEPTION 'analyst or admin role required' USING ERRCODE='42501';
  END IF;
  IF length(btrim(COALESCE(_name,''))) NOT BETWEEN 2 AND 80 THEN
    RAISE EXCEPTION 'invalid reconciliation name' USING ERRCODE='22023';
  END IF;

  SELECT * INTO template_row
  FROM public.recon_definition_templates
  WHERE id = _template_id AND status = 'published'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'published template not found' USING ERRCODE='P0002'; END IF;

  leg_count := jsonb_array_length(template_row.legs);
  IF jsonb_typeof(_sides) <> 'array' OR jsonb_array_length(_sides) <> leg_count OR leg_count NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'every template leg requires one source binding' USING ERRCODE='22023';
  END IF;
  IF jsonb_typeof(_rules) <> 'array' OR jsonb_array_length(_rules) < 1 OR jsonb_array_length(_rules) > 50 THEN
    RAISE EXCEPTION 'compiled template rules are invalid' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_sides) side
    WHERE COALESCE(side->>'side_id','') NOT IN ('A','B','C')
      OR NULLIF(side->>'data_source_id','') IS NULL
  ) OR (
    SELECT count(DISTINCT side->>'side_id') FROM jsonb_array_elements(_sides) side
  ) <> leg_count OR (
    SELECT count(DISTINCT side->>'data_source_id') FROM jsonb_array_elements(_sides) side
  ) <> leg_count THEN
    RAISE EXCEPTION 'template side bindings are invalid or duplicated' USING ERRCODE='22023';
  END IF;

  SELECT count(*) INTO valid_source_count
  FROM jsonb_array_elements(_sides) side
  JOIN public.workspace_data_sources source
    ON source.id = (side->>'data_source_id')::uuid
   AND source.tenant_id = _tenant_id;
  IF valid_source_count <> leg_count THEN
    RAISE EXCEPTION 'template source does not belong to tenant' USING ERRCODE='42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_rules) rule
    WHERE COALESCE(rule->>'kind','') NOT IN (
      'exact_match','case_insensitive_match','trimmed_match','numeric_equals',
      'numeric_tolerance_abs','numeric_tolerance_pct','amount_sign_flip','date_equals',
      'date_tolerance_days','date_within_range','date_age_days','string_contains','string_starts_with',
      'string_ends_with','regex_match','fuzzy_levenshtein','phonetic_soundex',
      'currency_equals','boolean_equals','non_null','unique','in_set','sum_to_match',
      'many_to_one_sum','one_to_many_sum','value_range','multiply','ignore_day_portion',
      'conditional_set','roll_up','reference_lookup','multi_pass','quick_fix'
    ) OR jsonb_typeof(rule->'fields') <> 'object'
  ) THEN
    RAISE EXCEPTION 'template compiled an unsupported rule' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.recon_definitions(
    tenant_id,name,description,recon_type,sides,rules,status,created_by,
    starter_template_id,starter_template_code,starter_template_snapshot
  ) VALUES (
    _tenant_id,btrim(_name),template_row.summary,
    CASE leg_count WHEN 1 THEN 'one_sided' WHEN 2 THEN 'two_sided' ELSE 'three_sided' END,
    _sides,_rules,'draft',actor,template_row.id,template_row.code,
    jsonb_build_object(
      'template_code',template_row.code,'asset_class',template_row.asset_class,
      'legs',template_row.legs,'keys',template_row.keys,'rules',template_row.rules,
      'tolerances',template_row.tolerances,'sample_fields',template_row.sample_fields,
      'installed_at',now()
    )
  ) RETURNING * INTO new_definition;

  UPDATE public.recon_definition_templates
  SET install_count = install_count + 1
  WHERE id = template_row.id;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (actor,_tenant_id,'workspace','recon.template.install','recon_definition',new_definition.id,
    jsonb_build_object(
      'recon_code',new_definition.recon_code,'template_id',template_row.id,
      'template_code',template_row.code,'asset_class',template_row.asset_class,
      'source_ids',(SELECT jsonb_agg(side->>'data_source_id') FROM jsonb_array_elements(_sides) side),
      'rule_count',jsonb_array_length(_rules)
    ));

  RETURN QUERY SELECT new_definition.id,new_definition.recon_code;
END;
$function$

CREATE OR REPLACE FUNCTION public.install_recon_starter_template_atomic(_tenant_id uuid, _template_id uuid, _name text, _sides jsonb, _rules jsonb, _owner_bu_ids uuid[])
 RETURNS TABLE(recon_definition_id uuid, recon_code text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  actor uuid := auth.uid();
  template_row public.recon_definition_templates%ROWTYPE;
  definition_row public.recon_definitions%ROWTYPE;
  leg_count integer;
  valid_source_count integer;
  definition_type text;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'templates');
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF actor IS NULL THEN RAISE EXCEPTION 'authentication required' USING ERRCODE='42501'; END IF;
  IF NOT (
    public.is_platform_admin(actor)
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_admin')
    OR public.has_tenant_role(actor, _tenant_id, 'tenant_analyst')
  ) THEN
    RAISE EXCEPTION 'analyst or admin role required' USING ERRCODE='42501';
  END IF;
  IF length(btrim(COALESCE(_name,''))) NOT BETWEEN 2 AND 80 THEN
    RAISE EXCEPTION 'invalid reconciliation name' USING ERRCODE='22023';
  END IF;
  IF coalesce(cardinality(_owner_bu_ids), 0) = 0 THEN
    RAISE EXCEPTION 'select at least one owning business unit' USING ERRCODE='22023';
  END IF;

  SELECT * INTO template_row
  FROM public.recon_definition_templates
  WHERE id = _template_id AND status = 'published'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'published template not found' USING ERRCODE='P0002'; END IF;

  IF jsonb_typeof(template_row.legs) <> 'array' THEN
    RAISE EXCEPTION 'published template legs are invalid' USING ERRCODE='22023';
  END IF;
  leg_count := jsonb_array_length(template_row.legs);
  IF jsonb_typeof(_sides) <> 'array' OR jsonb_array_length(_sides) <> leg_count OR leg_count NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'every template leg requires one source binding' USING ERRCODE='22023';
  END IF;
  IF jsonb_typeof(_rules) <> 'array' OR jsonb_array_length(_rules) < 1 OR jsonb_array_length(_rules) > 50 THEN
    RAISE EXCEPTION 'compiled template rules are invalid' USING ERRCODE='22023';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_sides) side
    WHERE COALESCE(side->>'side_id','') NOT IN ('A','B','C')
      OR NULLIF(side->>'data_source_id','') IS NULL
  ) OR (
    SELECT count(DISTINCT side->>'side_id') FROM jsonb_array_elements(_sides) side
  ) <> leg_count OR (
    SELECT count(DISTINCT side->>'data_source_id') FROM jsonb_array_elements(_sides) side
  ) <> leg_count THEN
    RAISE EXCEPTION 'template side bindings are invalid or duplicated' USING ERRCODE='22023';
  END IF;

  SELECT count(*) INTO valid_source_count
  FROM jsonb_array_elements(_sides) side
  JOIN public.workspace_data_sources source
    ON source.id = (side->>'data_source_id')::uuid
   AND source.tenant_id = _tenant_id;
  IF valid_source_count <> leg_count THEN
    RAISE EXCEPTION 'template source does not belong to tenant' USING ERRCODE='42501';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_array_elements(_rules) rule
    WHERE COALESCE(rule->>'kind','') NOT IN (
      'exact_match','case_insensitive_match','trimmed_match','numeric_equals',
      'numeric_tolerance_abs','numeric_tolerance_pct','amount_sign_flip','date_equals',
      'date_tolerance_days','date_within_range','date_age_days','string_contains','string_starts_with',
      'string_ends_with','regex_match','fuzzy_levenshtein','phonetic_soundex',
      'currency_equals','boolean_equals','non_null','unique','in_set','sum_to_match',
      'many_to_one_sum','one_to_many_sum','value_range','multiply','ignore_day_portion',
      'conditional_set','roll_up','reference_lookup','multi_pass','quick_fix'
    ) OR jsonb_typeof(rule->'fields') <> 'object'
  ) THEN
    RAISE EXCEPTION 'template compiled an unsupported rule' USING ERRCODE='22023';
  END IF;

  definition_type := CASE leg_count WHEN 1 THEN 'one_sided' WHEN 2 THEN 'two_sided' ELSE 'three_sided' END;
  SELECT created.id, created.recon_code INTO definition_row.id, definition_row.recon_code
  FROM public.create_recon_definition_with_owners(
    _tenant_id, btrim(_name), template_row.summary, definition_type, _sides, _rules, _owner_bu_ids
  ) AS created;
  IF definition_row.id IS NULL THEN RAISE EXCEPTION 'owner-bound creation returned no reconciliation'; END IF;

  UPDATE public.recon_definitions
  SET starter_template_id = template_row.id,
      starter_template_code = template_row.code,
      starter_template_snapshot = jsonb_build_object(
        'template_code',template_row.code,'asset_class',template_row.asset_class,
        'legs',template_row.legs,'keys',template_row.keys,'rules',template_row.rules,
        'tolerances',template_row.tolerances,'sample_fields',template_row.sample_fields,
        'installed_at',now()
      )
  WHERE id = definition_row.id AND tenant_id = _tenant_id
  RETURNING * INTO definition_row;
  IF NOT FOUND THEN RAISE EXCEPTION 'created reconciliation was not readable in tenant'; END IF;

  UPDATE public.recon_definition_templates
  SET install_count = install_count + 1
  WHERE id = template_row.id;

  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (actor,_tenant_id,'workspace','recon.template.install','recon_definition',definition_row.id::text,
    jsonb_build_object(
      'recon_code',definition_row.recon_code,'template_id',template_row.id,
      'template_code',template_row.code,'asset_class',template_row.asset_class,
      'owner_bu_ids',_owner_bu_ids,
      'source_ids',(SELECT jsonb_agg(side->>'data_source_id') FROM jsonb_array_elements(_sides) side),
      'rule_count',jsonb_array_length(_rules)
    ));

  RETURN QUERY SELECT definition_row.id,definition_row.recon_code;
END
$function$

CREATE OR REPLACE FUNCTION public.request_recon_retirement(_tenant_id uuid, _recon_id uuid, _reason text)
 RETURNS TABLE(request_id uuid, status text, tenant_id uuid, recon_id uuid, retired_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE actor uuid:=auth.uid(); definition_row public.recon_definitions%ROWTYPE; request_row public.recon_retirement_requests%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

  IF actor IS NULL OR _tenant_id IS NULL OR _recon_id IS NULL
     OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION 'valid authenticated actor, scope, and reason required' USING ERRCODE='22023';
  END IF;
  SELECT * INTO definition_row FROM public.recon_definitions d
    WHERE d.id=_recon_id AND d.tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'reconciliation not found in tenant' USING ERRCODE='P0002'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.tenant_members m
    WHERE m.tenant_id=_tenant_id AND m.user_id=actor AND m.active=true)
     OR NOT private.user_can_govern_recon_retirement(actor,_recon_id,'edit') THEN
    RAISE EXCEPTION 'reconciliation edit and approval access required' USING ERRCODE='42501';
  END IF;
  IF definition_row.status='draft' THEN
    RAISE EXCEPTION 'unrun draft may use permission-governed physical delete' USING ERRCODE='22023';
  END IF;
  IF definition_row.retired_at IS NOT NULL THEN RAISE EXCEPTION 'reconciliation already retired' USING ERRCODE='23505'; END IF;
  IF EXISTS (SELECT 1 FROM public.recon_retirement_requests q
    WHERE q.recon_id=_recon_id AND q.status='pending') THEN
    RAISE EXCEPTION 'a retirement request is already pending' USING ERRCODE='23505';
  END IF;

  INSERT INTO public.recon_retirement_requests(tenant_id,recon_id,reason,requested_by)
    VALUES (_tenant_id,_recon_id,btrim(_reason),actor) RETURNING * INTO request_row;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (actor,_tenant_id,'workspace','recon.retirement.requested','recon_retirement_request',request_row.id::text,
      jsonb_build_object('recon_id',_recon_id,'reason',btrim(_reason),'requested_at',request_row.requested_at));
  RETURN QUERY SELECT request_row.id,request_row.status,request_row.tenant_id,request_row.recon_id,NULL::timestamptz;
END $function$

CREATE OR REPLACE FUNCTION public.request_reference_data_rollback(_tenant_id uuid, _table_id uuid, _source_version_id uuid, _effective_from date, _reason text)
 RETURNS TABLE(version_id uuid, version_number integer, row_count integer, content_sha256 text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  source_version public.reference_data_versions%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  IF actor IS NULL OR NOT (
    EXISTS (
      SELECT 1 FROM public.tenant_members tm
      WHERE tm.user_id = actor AND tm.tenant_id = _tenant_id
        AND tm.role = 'tenant_admin' AND tm.active
    ) OR public.is_platform_admin(actor)
  ) THEN
    RAISE EXCEPTION 'Forbidden: active tenant administrator required' USING ERRCODE = '42501';
  END IF;
  IF length(btrim(coalesce(_reason, ''))) < 3 THEN
    RAISE EXCEPTION 'Rollback reason must contain at least 3 characters';
  END IF;
  SELECT * INTO source_version
  FROM public.reference_data_versions
  WHERE id = _source_version_id AND table_id = _table_id AND tenant_id = _tenant_id
    AND status IN ('published','superseded');
  IF NOT FOUND THEN RAISE EXCEPTION 'Published source version not found'; END IF;

  RETURN QUERY
  SELECT staged.version_id, staged.version_number, staged.row_count, staged.content_sha256
  FROM public.stage_reference_data_version(
    _tenant_id,
    _table_id,
    (SELECT jsonb_agg(r.row_data ORDER BY r.key_hash)
     FROM public.reference_data_version_rows r WHERE r.version_id = _source_version_id),
    _effective_from,
    NULL,
    format('Rollback to version %s: %s', source_version.version_number, btrim(_reason))
  ) staged;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    actor, _tenant_id, 'tenant', 'reference_data.version.rollback_requested',
    'reference_data_versions', _source_version_id::text,
    jsonb_build_object('table_id', _table_id, 'source_version', source_version.version_number,
      'effective_from', _effective_from, 'reason', btrim(_reason))
  );
END;
$function$

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_stage_insert(_new recon_definitions)
 RETURNS recon_definitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE q public.recon_definition_governance_requests%ROWTYPE; p public.recon_definitions%ROWTYPE; marker uuid;
BEGIN
 marker:=nullif(current_setting('fvi.recon_governance_request_id',true),'')::uuid;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=marker;
 IF NOT FOUND OR NOT private.mapped_recon_governance_transition(q.id,'edit_decision')
 OR q.request_kind<>'edit' OR q.status<>'approved' OR q.mapped_governance_version IS DISTINCT FROM 1
 OR q.decided_by IS DISTINCT FROM auth.uid() OR q.requested_by=auth.uid() OR q.staging_definition_id IS NOT NULL THEN
  PERFORM private.mapped_recon_governance_conflict('native_stage_authorization_required');
 END IF;
 SELECT * INTO p FROM public.recon_definitions WHERE tenant_id=q.tenant_id AND id=q.parent_definition_id;
 PERFORM private.mapped_recon_governance_actor(q.tenant_id,p.id,'approve',true);
 PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,p.id,q.requested_by);
 IF _new.id=p.id OR _new.tenant_id IS DISTINCT FROM p.tenant_id OR _new.created_by IS DISTINCT FROM q.requested_by
 OR _new.governance_parent_id IS DISTINCT FROM p.id OR _new.access_mode<>'mapped_exact'
 OR _new.governance_state<>'staging_copy' OR _new.environment<>'staging' OR _new.status<>'draft'
 OR _new.multi_bu_governed IS DISTINCT FROM p.multi_bu_governed OR NOT _new.multi_bu_governed
 OR _new.bu_id IS DISTINCT FROM p.bu_id OR _new.visibility IS DISTINCT FROM p.visibility
 OR _new.starter_template_id IS DISTINCT FROM p.starter_template_id OR _new.starter_template_code IS DISTINCT FROM p.starter_template_code
 OR _new.starter_template_snapshot IS DISTINCT FROM p.starter_template_snapshot OR _new.tenant_template_id IS DISTINCT FROM p.tenant_template_id
 OR _new.retired_at IS NOT NULL OR _new.retirement_request_id IS NOT NULL
 OR _new.staging_original_name IS DISTINCT FROM p.name OR _new.staging_generated_name IS DISTINCT FROM _new.name
 OR private.mapped_recon_governance_effective_config(_new) IS DISTINCT FROM private.recon_definition_config_snapshot(p)
 OR private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(p)) IS DISTINCT FROM q.parent_config_fingerprint
 OR private.mapped_recon_governance_mapping(q.tenant_id,p.id) IS DISTINCT FROM q.parent_mapping_snapshot THEN
  PERFORM private.mapped_recon_governance_conflict('native_stage_snapshot_mismatch');
 END IF;
 RETURN _new;
END $function$

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_update(_old recon_definitions, _new recon_definitions)
 RETURNS recon_definitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE q public.recon_definition_governance_requests%ROWTYPE; marker uuid; purpose text; permitted boolean:=false;
BEGIN
 IF (to_jsonb(_old)-ARRAY['name','description','recon_type','sides','rules','extension','governance_state','environment','status','updated_at'])
 IS DISTINCT FROM (to_jsonb(_new)-ARRAY['name','description','recon_type','sides','rules','extension','governance_state','environment','status','updated_at']) THEN
  PERFORM private.mapped_recon_governance_conflict('native_identity_or_scope_immutable');
 END IF;
 IF _old.governance_state=_new.governance_state AND _old.governance_state IN ('development_draft','staging_copy') THEN
  IF _new.environment IS DISTINCT FROM _old.environment OR _new.status IS DISTINCT FROM _old.status THEN
   PERFORM private.mapped_recon_governance_conflict('native_draft_lifecycle_immutable');
  END IF;
  PERFORM private.mapped_recon_governance_actor(_old.tenant_id,_old.id,'edit',false);
  IF NOT private.recon_authoritative_access_decision_as(auth.uid(),_old.id,'read') THEN
   PERFORM private.mapped_recon_governance_conflict('native_current_read_required');
  END IF;
  RETURN _new;
 END IF;
 -- Pure trigger timestamps on a locked row do not change its configuration.
 IF to_jsonb(_old)-'updated_at'=to_jsonb(_new)-'updated_at' THEN RETURN _new; END IF;
 marker:=nullif(current_setting('fvi.recon_governance_request_id',true),'')::uuid;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=marker AND tenant_id=_old.tenant_id;
 IF NOT FOUND OR q.mapped_governance_version IS DISTINCT FROM 1 THEN
  PERFORM private.mapped_recon_governance_conflict('native_workflow_receipt_required');
 END IF;
 purpose:=CASE WHEN q.request_kind='edit' AND q.status='pending' THEN 'edit_request'
 WHEN q.request_kind='edit' THEN 'edit_decision' WHEN q.status='pending' THEN 'promotion_submit' ELSE 'promotion_decision' END;
 IF NOT private.mapped_recon_governance_transition(q.id,purpose) THEN
  PERFORM private.mapped_recon_governance_conflict('native_workflow_receipt_required');
 END IF;
 IF q.status='pending' THEN
  IF q.requested_by IS DISTINCT FROM auth.uid() THEN PERFORM private.mapped_recon_governance_conflict('native_requester_mismatch'); END IF;
  PERFORM private.mapped_recon_governance_actor(q.tenant_id,_old.id,'edit',false);
 ELSE
  IF q.decided_by IS DISTINCT FROM auth.uid() OR q.requested_by=auth.uid() THEN PERFORM private.mapped_recon_governance_conflict('independent_checker_required'); END IF;
  PERFORM private.mapped_recon_governance_actor(q.tenant_id,q.parent_definition_id,'approve',true);
  PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,q.parent_definition_id,q.requested_by);
 END IF;
 IF q.request_kind='edit' AND q.parent_definition_id=_old.id THEN
  permitted:=(q.status='pending' AND _old.governance_state='approved_locked' AND _new.governance_state='edit_request_pending')
   OR (q.status IN ('approved','rejected') AND _old.governance_state='edit_request_pending' AND _new.governance_state='approved_locked');
 ELSIF q.request_kind='promotion' THEN
  permitted:=(q.status='pending' AND q.staging_definition_id=_old.id AND _old.governance_state IN ('development_draft','staging_copy') AND _new.governance_state='promotion_request_pending')
   OR (q.status='rejected' AND q.staging_definition_id=_old.id AND _old.governance_state='promotion_request_pending' AND _new.governance_state=CASE WHEN q.parent_definition_id=_old.id THEN 'development_draft' ELSE 'staging_copy' END)
   OR (q.status='approved' AND q.parent_definition_id=_old.id AND _old.governance_state IN ('approved_locked','promotion_request_pending') AND _new.governance_state='approved_locked')
   OR (q.status='approved' AND q.staging_definition_id=_old.id AND q.parent_definition_id<>_old.id AND _old.governance_state='promotion_request_pending' AND _new.governance_state='promoted');
 END IF;
 IF NOT coalesce(permitted,false) THEN PERFORM private.mapped_recon_governance_conflict('native_invalid_transition'); END IF;
 IF q.request_kind='promotion' AND q.status='approved' AND q.parent_definition_id=_old.id THEN
  IF _new.environment<>'production' OR _new.status<>'active'
  OR private.recon_definition_config_snapshot(_new) IS DISTINCT FROM q.snapshot
  OR private.mapped_recon_governance_hash(q.snapshot) IS DISTINCT FROM q.snapshot_sha256
  OR private.mapped_recon_governance_mapping(q.tenant_id,_old.id) IS DISTINCT FROM q.parent_mapping_snapshot THEN
   PERFORM private.mapped_recon_governance_conflict('native_approved_snapshot_mismatch');
  END IF;
 ELSIF private.recon_definition_config_snapshot(_old) IS DISTINCT FROM private.recon_definition_config_snapshot(_new)
 OR _old.environment IS DISTINCT FROM _new.environment OR _old.status IS DISTINCT FROM _new.status THEN
  PERFORM private.mapped_recon_governance_conflict('native_transition_config_immutable');
 END IF;
 RETURN _new;
END $function$

CREATE OR REPLACE FUNCTION public.save_reference_table_atomic(_tenant_id uuid, _request_key uuid, _name text, _description text, _key_columns text[], _value_columns text[], _is_active boolean, _owner_bu_ids uuid[], _group_ids uuid[], _id uuid DEFAULT NULL::uuid, _expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone, _expected_scope_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth', 'extensions'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_owners uuid[]; v_groups uuid[]; v_pairs jsonb;
  v_hash text; v_saved public.reference_table_save_requests%ROWTYPE;
  v_table public.reference_data_tables%ROWTYPE; v_registry uuid; v_before_scope text;
  v_group uuid; v_pair record; v_grant record; v_reply jsonb; v_audit_id bigint;
  v_reason text := 'Reference table atomic save'; v_changed boolean;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  IF v_actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
    OR current_setting('role', true) IS DISTINCT FROM 'authenticated'
    OR _tenant_id IS NULL OR _request_key IS NULL THEN
    RAISE EXCEPTION 'Reference save requires an authenticated tenant administrator' USING ERRCODE = '42501';
  END IF;
  PERFORM 1 FROM public.tenant_members tm WHERE tm.tenant_id = _tenant_id
    AND tm.user_id = v_actor AND tm.active AND tm.role = 'tenant_admin'::public.tenant_role FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reference save is not authorized' USING ERRCODE = '42501'; END IF;
  IF _name IS NULL OR length(_name) > 80 OR length(btrim(_name)) < 2
    OR length(_description) > 500 OR _is_active IS NULL
    OR coalesce(cardinality(_key_columns), 0) NOT BETWEEN 1 AND 50
    OR coalesce(cardinality(_value_columns), 0) > 50
    OR coalesce(cardinality(_owner_bu_ids), 0) NOT BETWEEN 1 AND 20
    OR coalesce(cardinality(_group_ids), 0) > 20
    OR array_ndims(_key_columns) <> 1 OR array_ndims(_owner_bu_ids) <> 1
    OR (coalesce(cardinality(_value_columns), 0) > 0 AND array_ndims(_value_columns) <> 1)
    OR (coalesce(cardinality(_group_ids), 0) > 0 AND array_ndims(_group_ids) <> 1)
    OR EXISTS (SELECT 1 FROM unnest(_key_columns || coalesce(_value_columns, ARRAY[]::text[])) x
      WHERE x IS NULL OR length(btrim(x)) NOT BETWEEN 1 AND 80)
    OR (SELECT count(DISTINCT lower(btrim(x))) FROM unnest(_key_columns) x) <> cardinality(_key_columns)
    OR (SELECT count(DISTINCT lower(btrim(x))) FROM unnest(coalesce(_value_columns, ARRAY[]::text[])) x)
      <> coalesce(cardinality(_value_columns), 0)
    OR array_position(_owner_bu_ids, NULL) IS NOT NULL OR array_position(_group_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Invalid Reference table save fields or scope' USING ERRCODE = '22023';
  END IF;
  IF _expected_scope_hash IS NOT NULL AND _expected_scope_hash !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid Reference scope version' USING ERRCODE = '22023';
  END IF;
  SELECT array_agg(DISTINCT x ORDER BY x) INTO v_owners FROM unnest(_owner_bu_ids) x;
  SELECT coalesce(array_agg(DISTINCT x ORDER BY x), ARRAY[]::uuid[]) INTO v_groups FROM unnest(_group_ids) x;
  v_hash := encode(extensions.digest(jsonb_build_object('tenant_id', _tenant_id, 'id', _id,
    'name', _name, 'description', _description, 'keys', _key_columns,
    'values', coalesce(_value_columns, ARRAY[]::text[]), 'is_active', _is_active,
    'owners', v_owners, 'groups', v_groups, 'expected_updated_at', _expected_updated_at,
    'expected_scope_hash', _expected_scope_hash)::text, 'sha256'), 'hex');
  PERFORM pg_advisory_xact_lock(hashtextextended('fvi-reference-save:' || _tenant_id || ':' || v_actor || ':' || _request_key, 0));
  SELECT * INTO v_saved FROM public.reference_table_save_requests
    WHERE tenant_id = _tenant_id AND actor_id = v_actor AND request_key = _request_key;
  IF FOUND THEN
    IF v_saved.payload_hash <> v_hash THEN
      RAISE EXCEPTION 'Reference request key conflicts with another payload' USING ERRCODE = '23505';
    END IF;
    SELECT * INTO v_table FROM public.reference_data_tables
      WHERE id = v_saved.reference_table_id AND tenant_id = _tenant_id;
    v_changed := NOT FOUND OR v_table.updated_at IS DISTINCT FROM (v_saved.receipt->>'updated_at')::timestamptz;
    IF NOT v_changed THEN
      v_changed := private.reference_table_save_scope_hash(_tenant_id, (v_saved.receipt->>'registry_id')::uuid)
        IS DISTINCT FROM v_saved.receipt->>'scope_hash';
    END IF;
    IF NOT v_changed THEN
      v_changed := NOT public.reference_scope_allows(v_saved.reference_table_id, 'view')
        OR EXISTS (SELECT 1 FROM unnest(v_owners) AS requested(bu_id) WHERE NOT EXISTS (
          SELECT 1 FROM public.business_units b WHERE b.id = requested.bu_id AND b.tenant_id = _tenant_id AND NOT b.is_archived))
        OR EXISTS (SELECT 1 FROM jsonb_to_recordset(v_saved.receipt->'group_bu_pairs') AS pair(group_id uuid, bu_id uuid)
          WHERE NOT EXISTS (SELECT 1 FROM public.tenant_groups g JOIN public.bu_group_assignments ga
            ON ga.group_id = g.id AND ga.tenant_id = g.tenant_id
            JOIN public.business_units assigned ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
            JOIN public.business_units target ON target.id = pair.bu_id AND target.tenant_id = _tenant_id AND NOT target.is_archived
            WHERE g.id = pair.group_id AND g.tenant_id = _tenant_id
              AND (assigned.id = target.id OR (ga.inherit_descendants AND target.path <@ assigned.path))));
    END IF;
    RETURN v_saved.receipt || jsonb_build_object('replayed', true, 'current_state_changed', v_changed);
  END IF;

  IF _id IS NULL THEN
    IF _expected_updated_at IS NOT NULL OR _expected_scope_hash IS NOT NULL THEN
      RAISE EXCEPTION 'Creation has no prior version' USING ERRCODE = '22023';
    END IF;
  ELSE
    SELECT * INTO v_table FROM public.reference_data_tables WHERE id = _id AND tenant_id = _tenant_id FOR UPDATE;
    IF NOT FOUND OR NOT public.reference_scope_allows(_id, 'edit') THEN
      RAISE EXCEPTION 'Reference table edit is not authorized' USING ERRCODE = '42501';
    END IF;
    SELECT id INTO v_registry FROM public.data_resource_registry WHERE tenant_id = _tenant_id
      AND resource_type = 'reference_table' AND reference_table_id = _id FOR UPDATE;
    IF v_registry IS NULL OR v_table.access_mode <> 'mapped_exact' THEN
      RAISE EXCEPTION 'A mapped Reference table is required for governed update' USING ERRCODE = '23514';
    END IF;
    v_before_scope := private.reference_table_save_scope_hash(_tenant_id, v_registry);
    IF _expected_updated_at IS NULL OR _expected_scope_hash IS NULL
      OR v_table.updated_at IS DISTINCT FROM _expected_updated_at
      OR v_before_scope IS DISTINCT FROM _expected_scope_hash THEN
      RAISE EXCEPTION 'Reference table or access scope changed; refresh before saving' USING ERRCODE = '40001';
    END IF;
  END IF;

  -- Prevent assignment phantoms during pair validation/mutation; only a bounded
  -- save runs under this read lock. Selected group/BU rows are also locked.
  PERFORM set_config('lock_timeout', '5s', true);
  LOCK TABLE public.bu_group_assignments IN SHARE MODE;
  PERFORM 1 FROM public.business_units WHERE tenant_id = _tenant_id AND id = ANY(v_owners) AND NOT is_archived ORDER BY id FOR SHARE;
  IF EXISTS (SELECT 1 FROM unnest(v_owners) AS requested(bu_id) WHERE NOT EXISTS (
    SELECT 1 FROM public.business_units b WHERE b.id = requested.bu_id AND b.tenant_id = _tenant_id AND NOT b.is_archived)) THEN
    RAISE EXCEPTION 'Owner Business Units must be active in the same tenant' USING ERRCODE = '23514';
  END IF;
  FOREACH v_group IN ARRAY v_groups LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('fvi-principal-group:' || v_group::text, 0));
    PERFORM 1 FROM public.tenant_groups WHERE id = v_group AND tenant_id = _tenant_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Selected group is outside the tenant' USING ERRCODE = '23514'; END IF;
  END LOOP;
  PERFORM ga.id FROM public.bu_group_assignments ga JOIN public.business_units assigned
    ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
    WHERE ga.tenant_id = _tenant_id AND ga.group_id = ANY(v_groups) AND EXISTS (
      SELECT 1 FROM public.business_units target WHERE target.tenant_id = _tenant_id
        AND target.id = ANY(v_owners) AND NOT target.is_archived
        AND (assigned.id = target.id OR (ga.inherit_descendants AND target.path <@ assigned.path)))
    ORDER BY ga.group_id, ga.bu_id FOR SHARE OF ga, assigned;
  SELECT coalesce(jsonb_agg(jsonb_build_object('group_id', pair.group_id, 'bu_id', pair.bu_id)
    ORDER BY pair.group_id, pair.bu_id), '[]'::jsonb) INTO v_pairs
  FROM (SELECT g AS group_id, owner.id AS bu_id FROM unnest(v_groups) g
    JOIN public.business_units owner ON owner.tenant_id = _tenant_id AND owner.id = ANY(v_owners) AND NOT owner.is_archived
    WHERE EXISTS (SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned
      ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
      WHERE ga.tenant_id = _tenant_id AND ga.group_id = g
        AND (assigned.id = owner.id OR (ga.inherit_descendants AND owner.path <@ assigned.path)))) pair;
  IF EXISTS (SELECT 1 FROM unnest(v_groups) g WHERE NOT EXISTS (
    SELECT 1 FROM jsonb_to_recordset(v_pairs) AS pair(group_id uuid, bu_id uuid) WHERE pair.group_id = g)) THEN
    RAISE EXCEPTION 'Selected group has no legitimate owning BU assignment' USING ERRCODE = '23514';
  END IF;

  IF _id IS NULL THEN
    INSERT INTO public.reference_data_tables(tenant_id, name, description, key_columns, value_columns, is_active, created_by)
      VALUES (_tenant_id, _name, _description, _key_columns, coalesce(_value_columns, ARRAY[]::text[]), _is_active, v_actor)
      RETURNING * INTO v_table;
    v_registry := public.register_typed_data_resource('reference_table', v_table.id, v_owners, v_reason);
  ELSE
    UPDATE public.reference_data_tables SET name = _name, description = _description,
      key_columns = _key_columns, value_columns = coalesce(_value_columns, ARRAY[]::text[]), is_active = _is_active
      WHERE id = _id AND tenant_id = _tenant_id RETURNING * INTO v_table;
    -- Replace only group-view pairs managed by this workflow. Non-view/user
    -- grants are preserved; the existing owner helper refuses conflicting removals.
    FOR v_grant IN SELECT g.id FROM public.data_resource_registry_grants g WHERE g.registry_id = v_registry
      AND g.tenant_id = _tenant_id AND g.principal_type = 'group' AND g.action = 'view'
      AND NOT EXISTS (SELECT 1 FROM jsonb_to_recordset(v_pairs) AS pair(group_id uuid, bu_id uuid)
        WHERE pair.group_id = g.principal_group_id AND pair.bu_id = g.bu_id)
    LOOP PERFORM public.revoke_typed_data_resource_action(v_grant.id, v_reason); END LOOP;
    PERFORM public.set_typed_data_resource_owners(v_registry, v_owners, v_reason);
  END IF;
  FOR v_pair IN SELECT * FROM jsonb_to_recordset(v_pairs) AS pair(group_id uuid, bu_id uuid)
  LOOP
    IF NOT EXISTS (SELECT 1 FROM public.data_resource_registry_grants WHERE tenant_id = _tenant_id
      AND registry_id = v_registry AND bu_id = v_pair.bu_id AND principal_type = 'group'
      AND principal_group_id = v_pair.group_id AND action = 'view') THEN
      PERFORM public.grant_typed_data_resource_action(v_registry, v_pair.bu_id, 'group', v_pair.group_id, 'view', v_reason);
    END IF;
  END LOOP;
  SELECT * INTO v_table FROM public.reference_data_tables WHERE id = v_table.id AND tenant_id = _tenant_id;
  v_reply := jsonb_build_object('id', v_table.id, 'registry_id', v_registry, 'request_key', _request_key,
    'updated_at', v_table.updated_at, 'scope_hash', private.reference_table_save_scope_hash(_tenant_id, v_registry),
    'group_bu_pairs', v_pairs, 'is_new', _id IS NULL, 'replayed', false, 'current_state_changed', false);
  INSERT INTO public.audit_log(actor_user_id, tenant_id, scope, action, resource_type, resource_id, context)
    VALUES (v_actor, _tenant_id, 'tenant', CASE WHEN _id IS NULL THEN 'reference_data.table.create' ELSE 'reference_data.table.update' END,
      'reference_data_tables', v_table.id::text, jsonb_build_object('name', _name, 'request_key', _request_key,
        'owner_bu_ids', v_owners, 'group_ids', v_groups, 'group_bu_pairs', v_pairs,
        'previous_scope_hash', v_before_scope, 'scope_hash', v_reply->>'scope_hash')) RETURNING id INTO v_audit_id;
  v_reply := v_reply || jsonb_build_object('audit_id', v_audit_id::text);
  INSERT INTO public.reference_table_save_requests(tenant_id, actor_id, request_key, payload_hash, reference_table_id, receipt)
    VALUES (_tenant_id, v_actor, _request_key, v_hash, v_table.id, v_reply);
  RETURN v_reply;
END $function$

CREATE OR REPLACE FUNCTION public.submit_collateral_csa_version(_tenant_id uuid, _version_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE actor uuid := auth.uid(); version_row public.collateral_csa_versions%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'collateral');

  IF NOT public.csa_assurance_actor(_tenant_id,actor) THEN
    RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501';
  END IF;
  SELECT * INTO version_row FROM public.collateral_csa_versions WHERE tenant_id=_tenant_id AND id=_version_id FOR UPDATE;
  IF NOT FOUND OR version_row.created_by<>actor OR version_row.status<>'draft' THEN
    RAISE EXCEPTION 'Only the draft author can submit a draft version' USING ERRCODE='42501';
  END IF;
  UPDATE public.collateral_csa_versions SET status='pending_approval',submitted_by=actor,submitted_at=now() WHERE id=_version_id;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES(actor,_tenant_id,'tenant','collateral.csa.version.submit','collateral_csa_version',_version_id::text,jsonb_build_object('version_no',version_row.version_no));
  RETURN 'pending_approval';
END $function$

CREATE OR REPLACE FUNCTION public.submit_reference_data_version(_tenant_id uuid, _version_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  actor uuid := auth.uid();
  v_version public.reference_data_versions%ROWTYPE;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  SELECT * INTO v_version
  FROM public.reference_data_versions
  WHERE id = _version_id AND tenant_id = _tenant_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Reference version not found'; END IF;
  IF actor IS NULL OR actor <> v_version.created_by THEN
    RAISE EXCEPTION 'Only the version maker may submit it' USING ERRCODE = '42501';
  END IF;
  IF v_version.status <> 'draft' THEN RAISE EXCEPTION 'Only a draft may be submitted'; END IF;
  IF v_version.row_count < 1 OR v_version.content_sha256 IS NULL THEN
    RAISE EXCEPTION 'Reference version has no verified content';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_version.table_id::text, 0));
  UPDATE public.reference_data_versions
  SET status = 'pending_approval', submitted_by = actor, submitted_at = now()
  WHERE id = _version_id;

  INSERT INTO public.audit_log(
    actor_user_id, tenant_id, scope, action, resource_type, resource_id, context
  ) VALUES (
    actor, _tenant_id, 'tenant', 'reference_data.version.submit',
    'reference_data_versions', _version_id::text,
    jsonb_build_object('table_id', v_version.table_id, 'version', v_version.version_number,
      'content_sha256', v_version.content_sha256)
  );
  RETURN 'pending_approval';
END;
$function$

CREATE OR REPLACE FUNCTION private.wfm_collateral_asset_write_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
 DECLARE tenant uuid;
 BEGIN
  IF TG_OP IN('UPDATE','DELETE') THEN
   SELECT c.tenant_id INTO tenant FROM public.collateral_qa_vm_calls c WHERE c.id=OLD.call_id;
   IF tenant IS NULL THEN RAISE EXCEPTION 'Current collateral asset parent scope is unavailable' USING ERRCODE='42501';END IF;
   IF current_setting('role',true)='authenticated' THEN PERFORM private.wfm_actor(tenant);END IF;
   PERFORM private.wfm_assert_enabled(tenant,'collateral');
  END IF;
  IF TG_OP IN('INSERT','UPDATE') THEN
   SELECT c.tenant_id INTO tenant FROM public.collateral_qa_vm_calls c WHERE c.id=NEW.call_id;
   IF tenant IS NULL THEN RAISE EXCEPTION 'Current collateral asset parent scope is unavailable' USING ERRCODE='42501';END IF;
   IF current_setting('role',true)='authenticated' THEN PERFORM private.wfm_actor(tenant);END IF;
   PERFORM private.wfm_assert_enabled(tenant,'collateral');
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
 END $function$

CREATE OR REPLACE FUNCTION public.decide_recon_definition_promotion(_request_id uuid, _approve boolean, _reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE actor uuid; q public.recon_definition_governance_requests%ROWTYPE; parent public.recon_definitions%ROWTYPE; stage public.recon_definitions%ROWTYPE;
 next_version integer; current_version integer:=0; current_hash text; mapping jsonb; stage_map jsonb;
BEGIN
 IF _request_id IS NULL OR _approve IS NULL OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'invalid promotion decision' USING ERRCODE='22023'; END IF;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=_request_id AND request_kind='promotion';
 IF NOT FOUND THEN PERFORM private.mapped_recon_governance_conflict('request_missing_or_replayed'); END IF;
 -- Registered availability at the actual native tenant scope; original mapped authority/independent checker/audit program follows unchanged.
 PERFORM private.wfm_actor(q.tenant_id);
 PERFORM private.wfm_assert_enabled(q.tenant_id,'recons');

 PERFORM pg_advisory_xact_lock(hashtextextended('mapped-recon:'||q.tenant_id::text||':'||q.parent_definition_id::text,0));
 PERFORM private.mapped_recon_governance_lock_scope(q.tenant_id,q.parent_definition_id);
 IF q.staging_definition_id<>q.parent_definition_id THEN PERFORM private.mapped_recon_governance_lock_scope(q.tenant_id,q.staging_definition_id); END IF;
 SELECT * INTO q FROM public.recon_definition_governance_requests WHERE id=_request_id FOR UPDATE;
 SELECT * INTO parent FROM public.recon_definitions WHERE tenant_id=q.tenant_id AND id=q.parent_definition_id;
 SELECT * INTO stage FROM public.recon_definitions WHERE tenant_id=q.tenant_id AND id=q.staging_definition_id;
 actor:=private.mapped_recon_governance_actor(q.tenant_id,parent.id,'approve',true);
 IF actor=q.requested_by THEN PERFORM private.mapped_recon_governance_conflict('independent_checker_required'); END IF;
 IF q.status<>'pending' OR q.mapped_governance_version IS DISTINCT FROM 1 OR stage.governance_state<>'promotion_request_pending' THEN PERFORM private.mapped_recon_governance_conflict('request_stale_or_replayed'); END IF;
 IF NOT private.recon_authoritative_access_decision_as(actor,stage.id,'approve') THEN PERFORM private.mapped_recon_governance_conflict('current_stage_approve_authority_required'); END IF;
 PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,parent.id,q.requested_by);
 PERFORM private.mapped_recon_governance_requester_current(q.tenant_id,stage.id,q.requested_by);
 mapping:=private.mapped_recon_governance_mapping(q.tenant_id,parent.id);stage_map:=private.mapped_recon_governance_mapping(q.tenant_id,stage.id);
 IF private.mapped_recon_governance_effective_config(stage) IS DISTINCT FROM q.snapshot OR private.mapped_recon_governance_hash(q.snapshot) IS DISTINCT FROM q.snapshot_sha256
 OR private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(parent)) IS DISTINCT FROM q.parent_config_fingerprint
 OR mapping IS DISTINCT FROM q.parent_mapping_snapshot OR private.mapped_recon_governance_hash(mapping) IS DISTINCT FROM q.parent_mapping_fingerprint
 OR stage_map IS DISTINCT FROM q.staging_mapping_snapshot OR private.mapped_recon_governance_hash(stage_map) IS DISTINCT FROM q.staging_mapping_fingerprint THEN PERFORM private.mapped_recon_governance_conflict('frozen_config_or_mapping_changed'); END IF;
 IF parent.id<>stage.id THEN
  SELECT version_number,snapshot_sha256 INTO current_version,current_hash FROM public.recon_definition_approved_versions WHERE tenant_id=q.tenant_id AND parent_definition_id=parent.id ORDER BY version_number DESC LIMIT 1;
  IF current_version IS DISTINCT FROM q.source_version OR current_hash IS DISTINCT FROM q.source_sha256 OR parent.governance_state<>'approved_locked' OR parent.retired_at IS NOT NULL OR parent.status<>'active' OR parent.environment<>'production' THEN PERFORM private.mapped_recon_governance_conflict('parent_revision_changed'); END IF;
 ELSIF q.source_version<>0 OR q.source_sha256 IS NOT NULL OR EXISTS(SELECT 1 FROM public.recon_definition_approved_versions WHERE tenant_id=q.tenant_id AND parent_definition_id=parent.id) THEN
  PERFORM private.mapped_recon_governance_conflict('initial_version_already_exists');
 END IF;
 IF EXISTS(SELECT 1 FROM public.recon_retirement_requests WHERE tenant_id=q.tenant_id AND recon_id=parent.id AND status='pending') THEN PERFORM private.mapped_recon_governance_conflict('parent_retirement_pending'); END IF;
 INSERT INTO private.mapped_recon_governance_transitions(request_id,actor_id,purpose) VALUES(q.id,actor,'promotion_decision');
 UPDATE public.recon_definition_governance_requests SET status=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END,decision_reason=btrim(_reason),decided_by=actor,decided_at=clock_timestamp() WHERE id=q.id;
 PERFORM set_config('fvi.recon_governance_request_id',q.id::text,true);
 IF _approve THEN
  UPDATE public.recon_definitions SET name=q.snapshot->>'name',description=q.snapshot->>'description',recon_type=q.snapshot->>'recon_type',sides=q.snapshot->'sides',rules=q.snapshot->'rules',extension=q.snapshot->'extension',environment='production',status='active',governance_state='approved_locked' WHERE id=parent.id;
  IF parent.id<>stage.id THEN UPDATE public.recon_definitions SET governance_state='promoted' WHERE id=stage.id; END IF;
  SELECT coalesce(max(version_number),0)+1 INTO next_version FROM public.recon_definition_approved_versions WHERE tenant_id=q.tenant_id AND parent_definition_id=parent.id;
  INSERT INTO public.recon_definition_approved_versions(tenant_id,parent_definition_id,version_number,snapshot,snapshot_sha256,request_id,approved_by,approved_mapping_snapshot,approved_mapping_fingerprint) VALUES(q.tenant_id,parent.id,next_version,q.snapshot,q.snapshot_sha256,q.id,actor,q.parent_mapping_snapshot,q.parent_mapping_fingerprint);
 ELSE
  UPDATE public.recon_definitions SET governance_state=CASE WHEN id=parent.id THEN 'development_draft' ELSE 'staging_copy' END WHERE id=stage.id;
 END IF;
 INSERT INTO public.recon_definition_governance_audit(tenant_id,request_id,parent_definition_id,staging_definition_id,event_type,actor_id,reason,snapshot_sha256) VALUES(q.tenant_id,q.id,parent.id,stage.id,CASE WHEN _approve THEN 'promotion_approved' ELSE 'promotion_rejected' END,actor,btrim(_reason),q.snapshot_sha256);
 IF _approve THEN INSERT INTO public.recon_definition_governance_audit(tenant_id,request_id,parent_definition_id,staging_definition_id,event_type,actor_id,reason,snapshot_sha256) VALUES(q.tenant_id,q.id,parent.id,stage.id,'version_approved',actor,btrim(_reason),q.snapshot_sha256); END IF;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,q.tenant_id,'workspace',CASE WHEN _approve THEN 'recon.definition.promotion_approved' ELSE 'recon.definition.promotion_rejected' END,'recon_definition_governance_request',q.id::text,jsonb_build_object('parent_definition_id',parent.id,'staging_definition_id',stage.id,'version_number',next_version,'snapshot_sha256',q.snapshot_sha256,'mapping_fingerprint',q.parent_mapping_fingerprint));
 RETURN CASE WHEN _approve THEN next_version ELSE NULL END;
END $function$

CREATE OR REPLACE FUNCTION public.submit_recon_definition_promotion(_tenant_id uuid, _staging_id uuid, _reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
AS $function$
DECLARE actor uuid; d public.recon_definitions%ROWTYPE; parent public.recon_definitions%ROWTYPE; parent_id uuid;
 snap jsonb; snap_hash text; v_id uuid; source_version integer:=0; source_hash text; parent_mapping jsonb; stage_mapping jsonb;
BEGIN
 -- Registered availability at the actual native tenant scope; original mapped authority/independent checker/audit program follows unchanged.
 PERFORM private.wfm_actor(_tenant_id);
 PERFORM private.wfm_assert_enabled(_tenant_id,'recons');

 IF _tenant_id IS NULL OR _staging_id IS NULL OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'invalid promotion request' USING ERRCODE='22023'; END IF;
 SELECT coalesce(governance_parent_id,id) INTO parent_id FROM public.recon_definitions WHERE tenant_id=_tenant_id AND id=_staging_id;
 IF NOT FOUND THEN PERFORM private.mapped_recon_governance_conflict('draft_missing'); END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('mapped-recon:'||_tenant_id::text||':'||parent_id::text,0));
 PERFORM private.mapped_recon_governance_lock_scope(_tenant_id,parent_id);
 IF parent_id<>_staging_id THEN PERFORM private.mapped_recon_governance_lock_scope(_tenant_id,_staging_id); END IF;
 SELECT * INTO d FROM public.recon_definitions WHERE tenant_id=_tenant_id AND id=_staging_id;
 SELECT * INTO parent FROM public.recon_definitions WHERE tenant_id=_tenant_id AND id=parent_id;
 IF d.access_mode<>'mapped_exact' OR d.environment NOT IN ('development','staging') OR d.governance_state NOT IN ('development_draft','staging_copy') OR d.retired_at IS NOT NULL OR d.status='archived' THEN PERFORM private.mapped_recon_governance_conflict('editable_mapped_draft_required'); END IF;
 actor:=private.mapped_recon_governance_actor(_tenant_id,d.id,'edit',false);
 PERFORM private.mapped_recon_governance_requester_current(_tenant_id,parent.id,actor);
 IF parent.id<>d.id AND (parent.governance_state<>'approved_locked' OR parent.environment<>'production' OR parent.status<>'active' OR parent.retired_at IS NOT NULL) THEN PERFORM private.mapped_recon_governance_conflict('promotion_parent_not_eligible'); END IF;
 IF EXISTS(SELECT 1 FROM public.recon_retirement_requests WHERE tenant_id=_tenant_id AND recon_id=parent.id AND status='pending')
 OR EXISTS(SELECT 1 FROM public.recon_definition_governance_requests WHERE tenant_id=_tenant_id AND parent_definition_id=parent.id AND status='pending') THEN PERFORM private.mapped_recon_governance_conflict('pending_workflow_exists'); END IF;
 snap:=private.mapped_recon_governance_effective_config(d);snap_hash:=private.mapped_recon_governance_hash(snap);
 parent_mapping:=private.mapped_recon_governance_mapping(_tenant_id,parent.id);stage_mapping:=private.mapped_recon_governance_mapping(_tenant_id,d.id);
 IF parent.id<>d.id THEN
  SELECT version_number,snapshot_sha256 INTO source_version,source_hash FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=parent.id ORDER BY version_number DESC LIMIT 1;
  IF source_version IS NULL OR source_hash IS DISTINCT FROM private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(parent))
  OR NOT EXISTS(SELECT 1 FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=parent.id
   AND version_number=source_version AND snapshot=private.recon_definition_config_snapshot(parent)
   AND snapshot_sha256=private.mapped_recon_governance_hash(snapshot)
   AND EXISTS(SELECT 1 FROM public.recon_definition_governance_requests evidence_request
    JOIN public.recon_definition_governance_audit evidence_audit ON evidence_audit.request_id=evidence_request.id
    WHERE evidence_request.id=recon_definition_approved_versions.request_id AND evidence_request.tenant_id=_tenant_id
     AND evidence_request.parent_definition_id=parent.id AND evidence_request.request_kind='promotion' AND evidence_request.status='approved'
     AND evidence_request.decided_by=recon_definition_approved_versions.approved_by
     AND evidence_request.snapshot=recon_definition_approved_versions.snapshot AND evidence_request.snapshot_sha256=source_hash
     AND evidence_audit.tenant_id=_tenant_id AND evidence_audit.parent_definition_id=parent.id
     AND evidence_audit.event_type='version_approved' AND evidence_audit.actor_id=recon_definition_approved_versions.approved_by
     AND evidence_audit.snapshot_sha256=source_hash)) THEN
   PERFORM private.mapped_recon_governance_conflict('parent_version_evidence_required');
  END IF;
 ELSIF EXISTS(SELECT 1 FROM public.recon_definition_approved_versions WHERE tenant_id=_tenant_id AND parent_definition_id=parent.id) THEN
  PERFORM private.mapped_recon_governance_conflict('initial_version_already_exists');
 END IF;
 INSERT INTO public.recon_definition_governance_requests(tenant_id,parent_definition_id,staging_definition_id,request_kind,requested_by,reason,source_version,source_sha256,snapshot,snapshot_sha256,mapped_governance_version,parent_config_fingerprint,staging_config_fingerprint,parent_mapping_snapshot,parent_mapping_fingerprint,staging_mapping_snapshot,staging_mapping_fingerprint)
 VALUES(_tenant_id,parent.id,d.id,'promotion',actor,btrim(_reason),source_version,source_hash,snap,snap_hash,1,private.mapped_recon_governance_hash(private.recon_definition_config_snapshot(parent)),snap_hash,parent_mapping,private.mapped_recon_governance_hash(parent_mapping),stage_mapping,private.mapped_recon_governance_hash(stage_mapping)) RETURNING id INTO v_id;
 INSERT INTO private.mapped_recon_governance_transitions(request_id,actor_id,purpose) VALUES(v_id,actor,'promotion_submit');
 PERFORM set_config('fvi.recon_governance_request_id',v_id::text,true);
 UPDATE public.recon_definitions SET governance_state='promotion_request_pending' WHERE id=d.id;
 INSERT INTO public.recon_definition_governance_audit(tenant_id,request_id,parent_definition_id,staging_definition_id,event_type,actor_id,reason,snapshot_sha256) VALUES(_tenant_id,v_id,parent.id,d.id,'promotion_submitted',actor,btrim(_reason),snap_hash);
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','recon.definition.promotion_submitted','recon_definition_governance_request',v_id::text,jsonb_build_object('parent_definition_id',parent.id,'staging_definition_id',d.id,'snapshot_sha256',snap_hash,'source_version',source_version,'mapping_fingerprint',private.mapped_recon_governance_hash(stage_mapping)));
 RETURN v_id;
END $function$

CREATE OR REPLACE FUNCTION public.wfm_get_snapshot(_tenant_id uuid, _bu_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);p jsonb;t jsonb;perms jsonb;
BEGIN
 SELECT jsonb_build_object('ai_enabled',ai_enabled,'allow_copilot_global',allow_copilot_global,'allow_agent_global',allow_agent_global,'default_autonomy_ceiling',default_autonomy_ceiling) INTO p FROM public.platform_ai_settings WHERE id=true;
 SELECT jsonb_build_object('ai_enabled',ai_enabled,'allow_copilot',allow_copilot,'allow_agent',allow_agent,'default_autonomy',default_autonomy) INTO t FROM public.tenant_ai_settings WHERE tenant_id=_tenant_id;
 IF public.is_platform_admin(actor) IS TRUE THEN
  SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO perms FROM public.permissions;
 ELSE
 SELECT coalesce(jsonb_agg(id ORDER BY id),'[]') INTO perms FROM public.permissions WHERE public.user_has_permission(actor,_tenant_id,id,_bu_id) IS TRUE;
 END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'bu_id',_bu_id,'epoch',coalesce((SELECT epoch::text FROM private.wfm_epoch WHERE tenant_id=_tenant_id),'0'),
 'page_enabled',(SELECT jsonb_object_agg(c.key,coalesce(v.enabled,true)) FROM private.wfm_page_catalog c LEFT JOIN public.tenant_workspace_page_visibility v ON v.tenant_id=_tenant_id AND v.page_key=c.key),
 'feature_flags',(SELECT jsonb_object_agg(c.key,jsonb_build_object('enabled',coalesce(f.enabled,c.default_enabled),'config',CASE WHEN c.key='data_prep' THEN jsonb_strip_nulls(jsonb_build_object('ai_enabled',f.config->'ai_enabled','assisted_enabled',f.config->'assisted_enabled','agentic_enabled',f.config->'agentic_enabled')) ELSE '{}'::jsonb END)) FROM private.wfm_feature_catalog c LEFT JOIN public.tenant_feature_flags f ON f.tenant_id=_tenant_id AND f.feature_key=c.key),
 'workspace_features',(SELECT jsonb_object_agg(c.key,coalesce(f.enabled,false)) FROM private.wfm_ux_catalog c LEFT JOIN public.tenant_workspace_features f ON f.tenant_id=_tenant_id AND f.feature_key=c.key),
 'entitlements',(SELECT jsonb_object_agg(c.key,CASE WHEN e.feature_key IS NULL THEN true ELSE e.allowed IS TRUE END) FROM private.wfm_feature_catalog c LEFT JOIN public.tenant_feature_entitlements e ON e.feature_key=c.key AND e.tenant_id=_tenant_id),
 'permission_ids',perms,'platform_ai',p,'tenant_ai',t,'tenant_ai_enabled',coalesce((SELECT ai_enabled FROM public.tenants WHERE id=_tenant_id),false),
 'kill_switch_engaged',EXISTS(SELECT 1 FROM public.ai_governance_kill_switches WHERE tenant_id=_tenant_id AND engaged IS TRUE),'can_manage',private.wfm_can_manage(_tenant_id,false),'can_manage_ai',private.wfm_can_manage(_tenant_id,true));
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_decide_setup_review(_tenant_id uuid, _setup_id uuid, _request_id uuid, _decision text, _reason text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.setup.decide',_request_context_id);r private.dpdi_setup_review_requests%ROWTYPE;d private.dpdi_setup_review_decisions%ROWTYPE;j private.dpdi_jobs%ROWTYPE;e private.dpdi_job_events%ROWTYPE;cfg public.data_prep_configuration_revisions%ROWTYPE;scope_req private.dps_scope_requests%ROWTYPE;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);SELECT * INTO r FROM private.dpdi_setup_review_requests WHERE id=_request_id AND tenant_id=_tenant_id AND setup_id=_setup_id FOR UPDATE;
 IF NOT FOUND OR actor=r.requested_by OR NOT EXISTS(SELECT 1 FROM public.tenant_group_members WHERE group_id=r.approver_group_id AND user_id=actor) OR _decision NOT IN('approved','rejected') OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'dpdi.exact_independent_human_reviewer_required' USING ERRCODE='42501';END IF;
 SELECT * INTO j FROM private.dpdi_jobs WHERE id=r.job_id;e:=private.dpdi_head(j.id);SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=(j.snapshot->>'configuration_id')::uuid;
 IF e.phase<>'success' OR e.blocking_records<>0 OR cfg.payload_sha256 IS DISTINCT FROM j.snapshot->>'configuration_sha256' OR j.snapshot_sha256<>r.snapshot_sha256 OR (SELECT max(version) FROM private.dpd_versions WHERE setup_id=r.setup_id)<>r.draft_version OR private.data_prep_pipeline_scope_allows(actor,_tenant_id,cfg.pipeline_id,'view') IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND (NOT private.dpd_original_viewable(i.original_file_id) OR private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'dpdi.current_complete_review_evidence_required' USING ERRCODE='42501';END IF;
 SELECT * INTO d FROM private.dpdi_setup_review_decisions WHERE request_id=r.id;
 IF FOUND THEN IF d.decision<>_decision OR d.decided_by<>actor OR d.reason<>btrim(_reason) THEN RAISE EXCEPTION 'dpdi.review_decision_immutable' USING ERRCODE='PT409';END IF;RETURN private.dpdi_review_dto(r,actor);END IF;
 IF _decision='approved' THEN
  SELECT * INTO scope_req FROM private.dps_scope_requests WHERE configuration_id=cfg.id AND tenant_id=_tenant_id;
  IF scope_req.id IS NULL THEN RAISE EXCEPTION 'dpdi.actual_scope_review_required' USING ERRCODE='42501';END IF;
  IF NOT EXISTS(SELECT 1 FROM private.dps_scope_decisions WHERE request_id=scope_req.id AND decision='approved') THEN PERFORM private.dps_decide_scope_core(_tenant_id,scope_req.id,'approved',btrim(_reason));END IF;
  -- Existing public four-eyes approval performs the lifecycle transition and
  -- invokes existing snapshot/immutability/audit triggers. Never set its GUC here.
  PERFORM 1 FROM public.data_prep_pipelines p WHERE p.id=cfg.pipeline_id AND p.tenant_id=_tenant_id AND p.version=cfg.pipeline_version AND p.lifecycle_state='production' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'dpdi.current_production_pipeline_version_required' USING ERRCODE='PT409';END IF;
  IF EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.id=cfg.pipeline_id AND p.tenant_id=_tenant_id AND p.status='draft') THEN
   PERFORM 1 FROM public.approve_data_prep_pipeline(_tenant_id,cfg.pipeline_id);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines p JOIN public.data_prep_approved_configurations ac ON ac.tenant_id=p.tenant_id AND ac.pipeline_id=p.id AND ac.pipeline_version=p.version
   WHERE p.id=cfg.pipeline_id AND p.tenant_id=_tenant_id AND p.status='approved' AND p.lifecycle_state='production' AND p.version=cfg.pipeline_version
   AND p.approved_by IS NOT NULL AND p.approved_by<>r.requested_by AND ac.configuration_id=cfg.id AND ac.approved_by=p.approved_by) THEN
   RAISE EXCEPTION 'dpdi.actual_independent_approved_snapshot_required' USING ERRCODE='42501';
  END IF;

 END IF;
 INSERT INTO private.dpdi_setup_review_decisions(request_id,decision,decided_by,reason,snapshot_sha256) VALUES(r.id,_decision,actor,btrim(_reason),r.snapshot_sha256);
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'setup.review.decided',r.id,jsonb_build_object('decision',_decision,'snapshot_sha256',r.snapshot_sha256,'approval_origin','dpdi_setup_review_v1'));RETURN private.dpdi_review_dto(r,actor);
END $function$

CREATE OR REPLACE FUNCTION private.rs_current_definition_sha(_tenant uuid, _definition uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE;
BEGIN
 PERFORM private.rs_actor(_tenant,_definition,'read');
 SELECT * INTO d FROM public.recon_definitions WHERE id=_definition AND tenant_id=_tenant;
 IF NOT FOUND THEN RAISE EXCEPTION 'rs.visible_contract_definition_required' USING ERRCODE='42501';END IF;
 RETURN encode(sha256(convert_to(private.recon_definition_config_snapshot(d)::text,'UTF8')),'hex');
END $function$

CREATE OR REPLACE FUNCTION public.fvi_report_exception_rows(_tenant uuid, _ids uuid[], _since timestamp with time zone, _at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE rows jsonb; n integer;
BEGIN
 IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
 OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
 OR public.rlnext_actor_allowed() IS DISTINCT FROM true
 OR _tenant IS NULL OR _ids IS NULL OR array_position(_ids,NULL::uuid) IS NOT NULL OR cardinality(_ids)>100000
 OR _since IS NULL OR _at IS NULL OR _since>_at OR _at-_since>interval '360 days'
 OR NOT EXISTS(SELECT 1 FROM public.tenant_members m WHERE m.tenant_id=_tenant AND m.user_id=auth.uid() AND m.active)
 THEN RAISE EXCEPTION 'report.current_scope_unavailable' USING ERRCODE='42501';END IF;
 IF (_ids <@ public.get_recon_list_scope_ids(_tenant,'all',NULL)) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.definition_scope_unavailable' USING ERRCODE='42501';END IF;
 PERFORM public.wfm_assert_current_section(_tenant,'reports');
 IF public.is_platform_admin(auth.uid()) IS DISTINCT FROM true AND public.user_has_permission(auth.uid(),_tenant,'recon.definition.read',NULL) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.current_read_permission_required' USING ERRCODE='42501';END IF;

 IF public.is_platform_admin(auth.uid()) IS DISTINCT FROM true AND public.user_has_permission(auth.uid(),_tenant,'break.read',NULL) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.current_exception_permission_required' USING ERRCODE='42501';END IF;
 IF public.wfm_workspace_row_allowed(_tenant,'exceptions') IS DISTINCT FROM true AND public.wfm_workspace_row_allowed(_tenant,'breaks') IS DISTINCT FROM true
 AND public.wfm_workspace_row_allowed(_tenant,'exception-dashboard') IS DISTINCT FROM true AND public.wfm_workspace_row_allowed(_tenant,'ageing') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'report.exception_family_unavailable' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]'::jsonb),count(*)::integer INTO rows,n
 FROM (SELECT e.id,e.severity,e.priority,e.lifecycle_state,e.status,e.created_at,e.resolved_at,e.due_date,e.root_cause,jsonb_build_object('definition_id',r.definition_id) AS run
 FROM public.recon_exceptions e JOIN public.recon_runs r ON r.id=e.run_id
 WHERE e.tenant_id=_tenant AND r.definition_id=ANY(_ids) AND e.created_at>=_since AND e.created_at<=_at
 ORDER BY e.id LIMIT 100001) r;
 IF n>100000 THEN RAISE EXCEPTION 'report.interactive_row_limit' USING ERRCODE='54000';END IF;
 RETURN jsonb_build_object('contract','fvi-complete-report-rows-v1','source','recon_exceptions','tenant_id',_tenant,'actor_id',auth.uid(),'since',_since,'through',_at,'definition_ids',_ids,'complete',true,'count',n,'rows',rows);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_get_dataset(_tenant_id uuid, _pipeline_id uuid, _dataset_id uuid, _logical_side text DEFAULT NULL::text, _page integer DEFAULT 1, _page_size integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'view'); d public.data_prep_prepared_datasets%ROWTYPE;
 u public.workspace_data_source_uploads%ROWTYPE; indexes integer[]; off integer:=private.dpw_page(_page,_page_size); payload_state jsonb;
BEGIN
 SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE id=_dataset_id AND tenant_id=_tenant_id AND pipeline_id=_pipeline_id;
 IF NOT FOUND OR private.dpw_source_allows(actor,_tenant_id,d.data_source_id,'view') IS DISTINCT FROM true
 OR EXISTS(SELECT 1 FROM public.data_prep_run_inputs i JOIN public.data_prep_delivery_files f ON f.id=i.file_id
 WHERE i.run_id=d.run_id AND private.dpw_source_allows(actor,_tenant_id,f.data_source_id,'view') IS DISTINCT FROM true)
 THEN RAISE EXCEPTION 'dpw.dataset_read_denied'; END IF;
 PERFORM private.dps_assert_preparation_source_scope(_tenant_id,d.run_id,actor);
 payload_state:=CASE WHEN EXISTS(SELECT 1 FROM private.dpdi_public_output_links WHERE dataset_id=d.id) THEN private.dpdi_public_payload_state(_tenant_id,d.run_id,actor) ELSE private.dpw_run_payload_state(d.run_id) END;
 IF (payload_state->>'available')::boolean IS DISTINCT FROM true THEN
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'dataset',to_jsonb(d)||jsonb_build_object('hash_kind','structured_jsonb_sha256'),
  'payload',payload_state,'rows',NULL,'total',NULL,'page',_page,'page_size',_page_size);
 END IF;
 SELECT * INTO u FROM public.workspace_data_source_uploads WHERE id=d.upload_id AND tenant_id=_tenant_id AND data_source_id=d.data_source_id;
 IF u.id IS NULL OR u.row_count<>d.rows OR private.dpw_hash(u.rows) IS DISTINCT FROM d.content_sha256 THEN RAISE EXCEPTION 'dpw.dataset_upload_integrity_mismatch'; END IF;
 IF _logical_side IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.data_prep_delivery_runs r,jsonb_array_elements(r.snapshot->'feeds') f
 WHERE r.id=d.run_id AND f.value->>'business_side'=_logical_side) THEN RAISE EXCEPTION 'dpw.dataset_logical_side_incompatible'; END IF;
 indexes:=private.dpw_dataset_indexes(d.id,_logical_side);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'dataset',to_jsonb(d)||jsonb_build_object('hash_kind','structured_jsonb_sha256'),
 'logical_side',_logical_side,'rows',coalesce((SELECT jsonb_agg(u.rows->x.idx ORDER BY x.ord) FROM unnest(indexes) WITH ORDINALITY x(idx,ord)
 WHERE ord>off AND ord<=off+_page_size),'[]'::jsonb),'total',cardinality(indexes),'page',_page,'page_size',_page_size);
END $function$

CREATE OR REPLACE FUNCTION public.dpw_publish_dataset(_tenant_id uuid, _pipeline_id uuid, _batch_id uuid, _run_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant_id,_pipeline_id,'run'); b public.data_prep_delivery_batches%ROWTYPE;
 r public.data_prep_delivery_runs%ROWTYPE; d public.data_prep_prepared_datasets%ROWTYPE; up uuid; src uuid; f jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 b:=private.dpw_lock_batch(_tenant_id,_pipeline_id,_batch_id,actor,false);
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run_id AND batch_id=b.id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR r.started_by<>actor OR _request_key IS NULL THEN RAISE EXCEPTION 'dpw.publish_binding_denied'; END IF;
 PERFORM private.dps_assert_preparation_source_scope(_tenant_id,r.id,actor);
 SELECT * INTO d FROM public.data_prep_prepared_datasets WHERE run_id=r.id;
 IF FOUND THEN
  IF d.request_key<>_request_key THEN RAISE EXCEPTION 'dpw.request_conflict'; END IF;
  RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'dataset',to_jsonb(d),'is_new',false);
 END IF;
 IF b.mode<>'prepare' OR b.state<>'prepared' OR r.state NOT IN('success','warn') OR r.finished_at IS NULL
 OR private.dpw_run_payload_available(r.id) IS DISTINCT FROM true
 OR (r.result->>'publication_eligible')::boolean IS DISTINCT FROM true OR r.pipeline_version<>b.pipeline_version
 OR private.dpw_hash(r.result) IS DISTINCT FROM r.result_sha256 THEN RAISE EXCEPTION 'dpw.current_successful_dq_required'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.data_prep_release_requests a JOIN public.data_prep_release_decisions decision ON decision.request_id=a.id
 WHERE a.run_id=r.id AND a.result_sha256=r.result_sha256 AND a.pipeline_version=r.pipeline_version AND decision.decision='approved')
 THEN RAISE EXCEPTION 'dpw.human_release_approval_required'; END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(r.snapshot->'feeds') LOOP
  IF private.dpw_source_allows(actor,_tenant_id,(f->>'data_source_id')::uuid,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpw.source_revoked'; END IF;
 END LOOP;
 src:=(r.snapshot->>'output_data_source_id')::uuid;
 IF private.dpw_source_allows(actor,_tenant_id,src,'ingest') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,src,'edit') IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dpw.output_source_denied'; END IF;
 INSERT INTO public.workspace_data_source_uploads(data_source_id,tenant_id,filename,mime_type,size_bytes,row_count,columns,sample_rows,content_sha256,uploaded_by,rows)
 VALUES(src,_tenant_id,'prepared-'||r.id::text||'.json','application/json',octet_length((r.result->'acceptedRows')::text),
 jsonb_array_length(r.result->'acceptedRows'),coalesce(r.result->'profile'->'columns','[]'::jsonb),'[]'::jsonb,r.result->>'structured_data_sha256',actor,r.result->'acceptedRows') RETURNING id INTO up;
 INSERT INTO public.data_prep_prepared_datasets(tenant_id,pipeline_id,pipeline_version,batch_id,run_id,business_date,data_source_id,upload_id,rows,content_sha256,request_key,published_by)
 VALUES(_tenant_id,_pipeline_id,r.pipeline_version,b.id,r.id,b.business_date,src,up,jsonb_array_length(r.result->'acceptedRows'),r.result->>'structured_data_sha256',_request_key,actor) RETURNING * INTO d;
 UPDATE public.data_prep_delivery_batches SET state='published' WHERE id=b.id;
 PERFORM private.dpw_audit(actor,_tenant_id,'dpw.dataset.publish',d.id,jsonb_build_object('upload_id',up,'run_id',r.id,'version',r.pipeline_version));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'dataset',to_jsonb(d),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION private.dpdi_public_payload_state(_tenant uuid, _run uuid, _actor uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE d public.data_prep_prepared_datasets%ROWTYPE;expiry timestamptz;available boolean;
BEGIN
 SELECT p.* INTO d FROM public.data_prep_prepared_datasets p JOIN private.dpdi_public_output_links l ON l.dataset_id=p.id WHERE p.tenant_id=_tenant AND p.run_id=_run;
 IF d.id IS NULL THEN RAISE EXCEPTION 'dpdi.actual_public_output_link_required';END IF;
 SELECT min(o.expires_at) INTO expiry FROM private.dpdi_run_inputs i JOIN private.dpd_original_intents o ON o.id=i.original_file_id WHERE i.run_id=_run;
 available:=private.dpdi_public_dataset_current(_tenant,d.id,_actor) IS TRUE;
 RETURN jsonb_build_object('available',available,'state',CASE WHEN available THEN 'available' WHEN expiry<=clock_timestamp() THEN 'expired' ELSE 'unavailable' END,'expires_at',expiry,'representation','registered_dpdi_output_v1','original_input_upload_id',NULL);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_get_job_records(_tenant_id uuid, _setup_id uuid, _job_id uuid, _kind text, _page integer, _page_size integer, _search text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.result',_request_context_id);
 j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,false);
 e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);off bigint;amount bigint;records jsonb;proofs jsonb;cols jsonb;needle text;
BEGIN
 IF _kind NOT IN('rows','errors') OR _kind IS NULL OR _page IS NULL OR _page<1 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 100 OR _search IS NULL OR char_length(_search)>200 THEN RAISE EXCEPTION 'dpdi.bounded_record_page_required' USING ERRCODE='22023';END IF;
 off:=(_page::bigint-1)*_page_size;
 IF EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND NOT private.dpd_original_viewable(i.original_file_id)) THEN
  RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','unavailable','kind',_kind,'records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 IF e.phase NOT IN('success','blocked') THEN
  RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','pending','kind',_kind,'records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 IF e.phase='blocked' AND _kind='rows' THEN
  RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','blocked','kind',_kind,'records',NULL,'columns',NULL,'total','0','page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 SELECT CASE WHEN _kind='rows' THEN coalesce(jsonb_agg(v.value->>'name' ORDER BY v.ordinality),'[]')||jsonb_build_array('extras_json') ELSE ' ["input_id","original_file_id","record_index","source_row_ordinal","reasons","payload","extras_json"]'::jsonb END INTO cols
 FROM jsonb_array_elements(j.snapshot->'confirmed_mapping'->'output_schema') WITH ORDINALITY v(value,ordinality);
 needle:=lower(_search);
 IF needle='' THEN
  amount:=CASE WHEN _kind='rows' THEN e.source_records ELSE e.blocking_records END;
  -- Prefix sums cover at most the small page-metadata set, not all source records.
  WITH metadata AS(
   SELECT p.*,CASE WHEN _kind='rows' THEN p.row_count ELSE p.blocking_count END n,
    coalesce(sum(CASE WHEN _kind='rows' THEN p.row_count ELSE p.blocking_count END) OVER(ORDER BY p.sequence ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)::bigint first_index
   FROM private.dpdi_job_pages p WHERE p.job_id=j.id
  ), relevant AS(SELECT * FROM metadata WHERE first_index<off+_page_size AND first_index+n>off),
  decoded AS(SELECT p.*,x.ordinality,x.value::jsonb record FROM relevant p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY x(value,ordinality) WHERE x.value<>''),
  filtered AS(SELECT *,row_number() OVER(PARTITION BY sequence ORDER BY ordinality)-1 item_index FROM decoded WHERE _kind='rows' OR record->'blocking'='true'::jsonb),
  selected AS(SELECT * FROM filtered WHERE first_index+item_index>=off AND first_index+item_index<off+_page_size)
  SELECT coalesce(jsonb_agg(record ORDER BY sequence,ordinality),'[]'),coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',sequence,'row_count',row_count,'sha256',sha256) ORDER BY sequence) FROM relevant),'[]') INTO records,proofs FROM selected;
 ELSE
  -- Search is over the complete authorised collection. No client loaded-row subset.
  WITH decoded AS(SELECT p.sequence,p.row_count,p.sha256,x.ordinality,x.value::jsonb record FROM private.dpdi_job_pages p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY x(value,ordinality) WHERE p.job_id=j.id AND x.value<>''),
  matches AS(SELECT * FROM decoded WHERE (_kind='rows' OR record->'blocking'='true'::jsonb) AND strpos(lower(CASE WHEN _kind='rows' THEN ((record->'payload')||jsonb_build_object('extras_json',record->'extras_json'))::text ELSE record::text END),needle)>0),
  selected AS(SELECT * FROM matches ORDER BY sequence,ordinality LIMIT _page_size OFFSET off)
  SELECT (SELECT count(*) FROM matches),coalesce(jsonb_agg(record ORDER BY sequence,ordinality),'[]'),coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',p.sequence,'row_count',p.row_count,'sha256',p.sha256) ORDER BY p.sequence) FROM(SELECT DISTINCT sequence,row_count,sha256 FROM selected)p),'[]') INTO amount,records,proofs FROM selected;
 END IF;
 IF jsonb_array_length(records)>_page_size THEN RAISE EXCEPTION 'dpdi.record_page_overflow';END IF;
 RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','available','kind',_kind,'records',records,'columns',cols,'total',amount::text,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',proofs);
END $function$

CREATE OR REPLACE FUNCTION private.tgm_validate_bulk(_intent jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c jsonb;t jsonb;
BEGIN
 IF jsonb_typeof(_intent) IS DISTINCT FROM 'object' OR _intent->>'request_key' IS NULL OR _intent->>'reason' IS NULL OR length(trim(_intent->>'reason')) NOT BETWEEN 3 AND 500 OR jsonb_typeof(_intent->'targets') IS DISTINCT FROM 'array' OR jsonb_array_length(_intent->'targets') NOT BETWEEN 1 AND 50 OR jsonb_typeof(_intent->'changes') IS DISTINCT FROM 'array' OR jsonb_array_length(_intent->'changes') NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'tgm.invalid_batch' USING ERRCODE='22023';END IF;
 PERFORM (_intent->>'request_key')::uuid;
 IF (SELECT count(DISTINCT value->>'tenant_id') FROM jsonb_array_elements(_intent->'targets'))<>jsonb_array_length(_intent->'targets') OR (SELECT count(DISTINCT(value->>'kind',value->>'key')) FROM jsonb_array_elements(_intent->'changes'))<>jsonb_array_length(_intent->'changes') THEN RAISE EXCEPTION 'tgm.duplicate_target_or_key' USING ERRCODE='22023';END IF;
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') LOOP IF t->>'tenant_id' IS NULL OR t->>'expected_epoch' IS NULL OR t->>'expected_epoch'!~'^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'tgm.invalid_target' USING ERRCODE='22023';END IF;PERFORM(t->>'tenant_id')::uuid;END LOOP;
 FOR c IN SELECT value FROM jsonb_array_elements(_intent->'changes') LOOP
 IF jsonb_typeof(c->'enabled') IS DISTINCT FROM 'boolean' OR NOT((c->>'kind'='page' AND EXISTS(SELECT 1 FROM private.wfm_page_catalog WHERE key=c->>'key')) OR(c->>'kind'='feature' AND EXISTS(SELECT 1 FROM private.wfm_feature_catalog WHERE key=c->>'key')) OR(c->>'kind'='workspace-feature' AND EXISTS(SELECT 1 FROM private.wfm_ux_catalog WHERE key=c->>'key')) OR(c->>'kind'='mode' AND c->>'key' IN('ai_enabled','assisted_enabled','agentic_enabled'))) THEN RAISE EXCEPTION 'tgm.unknown_control' USING ERRCODE='22023';END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION private.tgm_bulk_actor(_intent jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;tenant uuid;
BEGIN
 PERFORM private.tgm_validate_bulk(_intent);
 IF jsonb_array_length(_intent->'targets')>1 THEN RETURN private.wfm_platform_actor();END IF;
 tenant:=(_intent->'targets'->0->>'tenant_id')::uuid;actor:=private.wfm_actor(tenant);
 IF private.wfm_can_manage(tenant,false) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.current_tenant_manager_required' USING ERRCODE='42501';END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION private.dps_admin(_tenant uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant);
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant,actor,true);
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=actor AND active IS TRUE AND role='tenant_admin')
 THEN RAISE EXCEPTION 'dps.active_tenant_admin_required' USING ERRCODE='42501';END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION private.dps_ids(_ids uuid[], _max integer, _nonempty boolean)
 RETURNS uuid[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE result uuid[];
BEGIN
 IF _ids IS NULL OR array_position(_ids,NULL) IS NOT NULL OR cardinality(_ids)>_max OR (_nonempty AND cardinality(_ids)=0)
 THEN RAISE EXCEPTION 'dps.invalid_selection' USING ERRCODE='22023';END IF;
 SELECT coalesce(array_agg(DISTINCT x ORDER BY x),'{}'::uuid[]) INTO result FROM unnest(_ids) x;
 IF cardinality(result)<>cardinality(_ids) THEN RAISE EXCEPTION 'dps.duplicate_selection' USING ERRCODE='22023';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION private.dps_save_configuration_core(_tenant_id uuid, _pipeline_id uuid, _payload jsonb, _owning_business_unit_ids uuid[], _sharing_user_group_ids uuid[], _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant_id);owners uuid[]:=private.dps_ids(_owning_business_unit_ids,100,true);groups uuid[]:=private.dps_ids(_sharing_user_group_ids,100,false);base_owners uuid[];saved jsonb;cfg public.data_prep_configuration_revisions%ROWTYPE;manifest jsonb;identity jsonb;req private.dps_scope_requests%ROWTYPE;
BEGIN
 IF _request_key IS NULL OR _payload IS NULL OR _payload ?| ARRAY['sharing_user_group_ids','requested_owning_business_unit_ids','shared_scope_contract'] THEN RAISE EXCEPTION 'dps.reserved_scope_metadata' USING ERRCODE='22023';END IF;
 PERFORM private.dps_selections(_tenant_id,owners,groups);
 base_owners:=owners;
 IF _pipeline_id IS NOT NULL THEN
  PERFORM private.dpw_authorize(_tenant_id,_pipeline_id,'edit');
  SELECT array_agg(o.bu_id ORDER BY o.bu_id) INTO base_owners FROM public.data_resource_registry r JOIN public.data_resource_registry_owner_bu o ON o.registry_id=r.id AND o.tenant_id=r.tenant_id WHERE r.tenant_id=_tenant_id AND r.data_prep_pipeline_id=_pipeline_id;
  IF base_owners IS NULL THEN RAISE EXCEPTION 'dps.existing_registered_scope_required' USING ERRCODE='42501';END IF;
 END IF;
 -- The baseline saves a draft and immutable revision. Existing ownership is retained until scope approval.
 saved:=public.dpw_save_configuration(_tenant_id,_pipeline_id,_payload||jsonb_build_object('sharing_user_group_ids',groups,'requested_owning_business_unit_ids',owners,'shared_scope_contract','dps-v1'),base_owners,_request_key);
 SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=(saved->>'configuration_id')::uuid AND tenant_id=_tenant_id;
 manifest:=private.dps_manifest(_tenant_id,cfg.pipeline_id,cfg.id,owners,groups);
 identity:=jsonb_build_object('configuration_id',cfg.id,'configuration_sha256',cfg.payload_sha256,'owners',owners,'groups',groups,'source_manifest',manifest);
 PERFORM pg_advisory_xact_lock(hashtextextended(_tenant_id::text||actor::text||_request_key::text,0));
 SELECT * INTO req FROM private.dps_scope_requests WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF FOUND THEN
  IF req.configuration_id<>cfg.id OR req.owning_business_unit_ids<>owners OR req.sharing_user_group_ids<>groups THEN RAISE EXCEPTION 'dps.request_conflict';END IF;
 ELSE
  INSERT INTO private.dps_scope_requests(tenant_id,pipeline_id,configuration_id,configuration_sha256,owning_business_unit_ids,sharing_user_group_ids,source_manifest,request_sha256,request_key,created_by)
  VALUES(_tenant_id,cfg.pipeline_id,cfg.id,cfg.payload_sha256,owners,groups,manifest,private.dpw_hash(identity),_request_key,actor) RETURNING * INTO req;
  PERFORM private.dpw_audit(actor,_tenant_id,'dps.scope.request',cfg.pipeline_id,jsonb_build_object('request_id',req.id,'request_sha256',req.request_sha256,'configuration_id',cfg.id));
 END IF;
 RETURN saved||jsonb_build_object('scope_request_id',req.id,'scope_request_sha256',req.request_sha256,'owning_business_unit_ids',req.owning_business_unit_ids,'sharing_user_group_ids',req.sharing_user_group_ids,'scope_status',coalesce((SELECT decision FROM private.dps_scope_decisions WHERE request_id=req.id),'pending'),'permission_grants_created',false);
END $function$

CREATE OR REPLACE FUNCTION private.dps_lookup_request_core(_tenant_id uuid, _request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant_id);req private.dps_scope_requests%ROWTYPE;pipeline jsonb;
BEGIN
 SELECT * INTO req FROM private.dps_scope_requests WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF req.id IS NULL THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_key',_request_key,'found',false);END IF;
 PERFORM private.dpw_authorize(_tenant_id,req.pipeline_id,'edit');
 SELECT to_jsonb(p) INTO pipeline FROM public.data_prep_pipelines p WHERE p.id=req.pipeline_id AND p.tenant_id=_tenant_id;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_key',_request_key,'found',true,'saved',jsonb_build_object(
 'actor_id',actor,'tenant_id',_tenant_id,'pipeline',pipeline,'configuration_id',req.configuration_id,'is_new',false,
 'scope_request_id',req.id,'scope_request_sha256',req.request_sha256,'owning_business_unit_ids',req.owning_business_unit_ids,'sharing_user_group_ids',req.sharing_user_group_ids,
 'scope_status',coalesce((SELECT decision FROM private.dps_scope_decisions WHERE request_id=req.id),'pending'),'permission_grants_created',false));
END $function$

CREATE OR REPLACE FUNCTION private.dps_decide_scope_core(_tenant_id uuid, _request_id uuid, _decision text, _reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dps_admin(_tenant_id);req private.dps_scope_requests%ROWTYPE;dec private.dps_scope_decisions%ROWTYPE;manifest jsonb;target jsonb;registry uuid;g uuid;b uuid;gid uuid;prior uuid;events jsonb:='[]';oldgrant record;
BEGIN
 IF _decision IS NULL OR _decision NOT IN('approved','rejected') OR length(btrim(coalesce(_reason,''))) NOT BETWEEN 3 AND 1000 THEN RAISE EXCEPTION 'dps.invalid_decision' USING ERRCODE='22023';END IF;
 SELECT * INTO req FROM private.dps_scope_requests WHERE id=_request_id AND tenant_id=_tenant_id FOR UPDATE;
 IF req.id IS NULL OR req.created_by=actor THEN RAISE EXCEPTION 'dps.independent_admin_required' USING ERRCODE='42501';END IF;
 SELECT * INTO dec FROM private.dps_scope_decisions WHERE request_id=req.id;
 IF FOUND THEN IF dec.decision<>_decision OR dec.decided_by<>actor OR dec.reason<>btrim(_reason) THEN RAISE EXCEPTION 'dps.decision_conflict';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_id',req.id,'decision',to_jsonb(dec),'is_new',false);END IF;
 IF _decision='approved' THEN
  manifest:=private.dps_manifest(_tenant_id,req.pipeline_id,req.configuration_id,req.owning_business_unit_ids,req.sharing_user_group_ids);
  IF manifest IS DISTINCT FROM req.source_manifest OR NOT EXISTS(SELECT 1 FROM public.data_prep_configuration_revisions WHERE id=req.configuration_id AND payload_sha256=req.configuration_sha256) THEN RAISE EXCEPTION 'dps.scope_binding_changed' USING ERRCODE='42501';END IF;
  FOR target IN SELECT value FROM jsonb_array_elements(manifest) WHERE value->>'kind' IN('pipeline','output') OR (value->>'kind'='input' AND (value->>'owned_draft_input')::boolean IS TRUE) LOOP
   registry:=(target->>'registry_id')::uuid;
   -- Revoke only grants created by an earlier independently approved SharedScope decision.
   FOR oldgrant IN SELECT v.* FROM public.data_resource_registry_grants v WHERE v.registry_id=registry AND v.tenant_id=_tenant_id AND v.action='view' AND v.principal_type='group'
    AND (NOT v.principal_group_id=ANY(req.sharing_user_group_ids) OR NOT v.bu_id=ANY(req.owning_business_unit_ids))
    AND EXISTS(SELECT 1 FROM private.dps_scope_decisions d, jsonb_array_elements(d.grant_events) e WHERE d.decision='approved' AND e->>'grant_id'=v.id::text AND e->>'created'='true')
   LOOP PERFORM public.revoke_typed_data_resource_action(oldgrant.id,btrim(_reason));events:=events||jsonb_build_array(jsonb_build_object('grant_id',oldgrant.id,'revoked',true));END LOOP;
   IF target->>'kind'='output' AND (SELECT array_agg((x->>'bu_id')::uuid ORDER BY (x->>'bu_id')::uuid) FROM jsonb_array_elements(target->'owners') x) IS DISTINCT FROM req.owning_business_unit_ids
   THEN RAISE EXCEPTION 'dps.output_owners_must_already_match_no_shared_source_remap' USING ERRCODE='42501';END IF;
   IF target->>'kind'='pipeline' THEN PERFORM public.set_typed_data_resource_owners(registry,req.owning_business_unit_ids,btrim(_reason));END IF;
   FOREACH g IN ARRAY req.sharing_user_group_ids LOOP
    FOREACH b IN ARRAY private.dps_group_bus(_tenant_id,g,CASE WHEN target->>'kind'='input' THEN ARRAY(SELECT (x->>'bu_id')::uuid FROM jsonb_array_elements(target->'owners') x) ELSE req.owning_business_unit_ids END) LOOP
     SELECT id INTO prior FROM public.data_resource_registry_grants WHERE registry_id=registry AND tenant_id=_tenant_id AND principal_type='group' AND principal_group_id=g AND bu_id=b AND action='view';
     gid:=public.grant_typed_data_resource_action(registry,b,'group',g,'view',btrim(_reason));
     events:=events||jsonb_build_array(jsonb_build_object('registry_id',registry,'bu_id',b,'group_id',g,'grant_id',gid,'created',prior IS NULL));
    END LOOP;
   END LOOP;
  END LOOP;
 END IF;
 INSERT INTO private.dps_scope_decisions(request_id,decision,decided_by,reason,grant_events) VALUES(req.id,_decision,actor,btrim(_reason),events) RETURNING * INTO dec;
 PERFORM private.dpw_audit(actor,_tenant_id,'dps.scope.decision',req.pipeline_id,jsonb_build_object('request_id',req.id,'decision_id',dec.id,'decision',_decision,'request_sha256',req.request_sha256,'grant_events',events));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'request_id',req.id,'decision',to_jsonb(dec),'is_new',true);
END $function$

CREATE OR REPLACE FUNCTION public.tgm_preview_controls(_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.tgm_bulk_actor(_intent);snapshots jsonb:='[]';t jsonb;tid uuid;s jsonb;c jsonb;
BEGIN
 PERFORM private.tgm_validate_bulk(_intent);
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') ORDER BY value->>'tenant_id' LOOP
  tid:=(t->>'tenant_id')::uuid;
  FOR c IN SELECT value FROM jsonb_array_elements(_intent->'changes') LOOP IF private.wfm_can_manage(tid,c->>'kind'='mode' OR(c->>'kind'='feature' AND c->>'key' IN('copilot','agent','aidp','auto_match_ai','auto_remediation','byo_llm','cost_metering'))) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.current_authority_denied' USING ERRCODE='42501';END IF;END LOOP;
  s:=public.wfm_get_snapshot(tid,NULL);IF s->>'epoch'<>t->>'expected_epoch' THEN RAISE EXCEPTION 'tgm.stale_preview' USING ERRCODE='PT409';END IF;snapshots:=snapshots||jsonb_build_array(s);
 END LOOP;
 RETURN jsonb_build_object('actor_id',actor,'intent',_intent,'snapshots',snapshots,'checked_at',clock_timestamp());
END $function$

CREATE OR REPLACE FUNCTION public.tgm_apply_controls(_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.tgm_bulk_actor(_intent);old private.tgm_requests%ROWTYPE;rk uuid;tid uuid;eid uuid;ep text;t jsonb;c jsonb;beforev jsonb;afterv jsonb;results jsonb:='[]';result jsonb;
BEGIN
 PERFORM private.tgm_validate_bulk(_intent);rk:=(_intent->>'request_key')::uuid;
 PERFORM pg_advisory_xact_lock(hashtextextended('tgm:'||actor::text||':'||rk::text,0));
 SELECT * INTO old FROM private.tgm_requests WHERE actor_id=actor AND request_key=rk;
 -- Recheck all CURRENT roles/factors even when a prior receipt exists.
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') ORDER BY value->>'tenant_id' LOOP
  tid:=(t->>'tenant_id')::uuid;PERFORM pg_advisory_xact_lock(hashtextextended('wfm:'||tid::text,0));
  FOR c IN SELECT value FROM jsonb_array_elements(_intent->'changes') LOOP IF private.wfm_can_manage(tid,c->>'kind'='mode' OR(c->>'kind'='feature' AND c->>'key' IN('copilot','agent','aidp','auto_match_ai','auto_remediation','byo_llm','cost_metering'))) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.current_authority_denied' USING ERRCODE='42501';END IF;END LOOP;
 END LOOP;
 IF old.request_key IS NOT NULL THEN IF old.kind<>'bulk' OR old.payload IS DISTINCT FROM _intent THEN RAISE EXCEPTION 'tgm.intent_conflict' USING ERRCODE='PT409';END IF;RETURN old.result;END IF;
 -- Prevalidate every version before the first update. Any exception rolls back the entire batch.
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') LOOP tid:=(t->>'tenant_id')::uuid;IF coalesce((SELECT epoch::text FROM private.wfm_epoch WHERE tenant_id=tid),'0')<>t->>'expected_epoch' THEN RAISE EXCEPTION 'tgm.epoch_conflict' USING ERRCODE='PT409';END IF;END LOOP;
 FOR t IN SELECT value FROM jsonb_array_elements(_intent->'targets') ORDER BY value->>'tenant_id' LOOP
  tid:=(t->>'tenant_id')::uuid;beforev:=public.wfm_get_snapshot(tid,NULL);
  FOR c IN SELECT value FROM jsonb_array_elements(_intent->'changes') ORDER BY value->>'kind',value->>'key' LOOP
   SELECT coalesce((SELECT epoch::text FROM private.wfm_epoch WHERE tenant_id=tid),'0') INTO ep;
   PERFORM public.wfm_set_control(tid,c->>'kind',c->>'key',(c->>'enabled')::boolean,ep,gen_random_uuid(),NULL);
  END LOOP;
  afterv:=public.wfm_get_snapshot(tid,NULL);
  INSERT INTO private.tgm_events(actor_id,tenant_id,kind,reason,request_key,before_value,after_value) VALUES(actor,tid,'bulk',trim(_intent->>'reason'),rk,beforev,afterv) RETURNING id INTO eid;
  results:=results||jsonb_build_array(jsonb_build_object('tenant_id',tid,'epoch',afterv->>'epoch','event_id',eid));
 END LOOP;
 result:=jsonb_build_object('actor_id',actor,'request_key',rk,'atomic',true,'results',results,'occurred_at',clock_timestamp());
 INSERT INTO private.tgm_requests(actor_id,request_key,kind,payload,result) VALUES(actor,rk,'bulk',_intent,result);RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.tgm_control_audit(_tenant_id uuid, _search text, _offset integer, _limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);events jsonb;total bigint;latest jsonb;
BEGIN
 IF private.wfm_can_manage(_tenant_id,false) IS DISTINCT FROM true THEN RAISE EXCEPTION 'tgm.audit_denied' USING ERRCODE='42501';END IF;
 IF _search IS NULL OR length(_search)>120 OR _offset IS NULL OR _offset<0 OR _offset>100000 OR _limit IS NULL OR _limit<1 OR _limit>100 THEN RAISE EXCEPTION 'tgm.invalid_query' USING ERRCODE='22023';END IF;
 SELECT jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'actor_id',e.actor_id,'occurred_at',e.occurred_at,'kind',e.kind,'key',e.key,'before_value',e.before_value,'after_value',e.after_value,'epoch',e.epoch::text,'reason',(SELECT b.reason FROM private.tgm_events b WHERE b.tenant_id=e.tenant_id AND b.actor_id=e.actor_id AND b.kind='bulk' AND e.epoch>(b.before_value->>'epoch')::bigint AND e.epoch<=(b.after_value->>'epoch')::bigint ORDER BY b.occurred_at DESC,b.id LIMIT 1)) INTO latest FROM private.wfm_events e WHERE e.tenant_id=_tenant_id ORDER BY e.epoch DESC,e.id LIMIT 1;
 SELECT count(*) INTO total FROM private.wfm_events WHERE tenant_id=_tenant_id AND(_search='' OR strpos(lower(key||' '||kind||' '||actor_id::text),lower(_search))>0);
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'tenant_id',e.tenant_id,'actor_id',e.actor_id,'occurred_at',e.occurred_at,'kind',e.kind,'key',e.key,'before_value',e.before_value,'after_value',e.after_value,'epoch',e.epoch::text,'reason',(SELECT b.reason FROM private.tgm_events b WHERE b.tenant_id=e.tenant_id AND b.actor_id=e.actor_id AND b.kind='bulk' AND e.epoch>(b.before_value->>'epoch')::bigint AND e.epoch<=(b.after_value->>'epoch')::bigint ORDER BY b.occurred_at DESC,b.id LIMIT 1)) ORDER BY e.epoch DESC),'[]') INTO events FROM(SELECT * FROM private.wfm_events WHERE tenant_id=_tenant_id AND(_search='' OR strpos(lower(key||' '||kind||' '||actor_id::text),lower(_search))>0) ORDER BY epoch DESC LIMIT _limit OFFSET _offset)e;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'search',_search,'offset',_offset,'limit',_limit,'total',total,'events',events,'latest_event',latest);
END $function$

CREATE OR REPLACE FUNCTION public.tgm_get_controls(_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.wfm_actor(_tenant_id);snapshot jsonb;
BEGIN
 snapshot:=public.wfm_get_snapshot(_tenant_id,NULL);
 IF snapshot->>'actor_id' IS DISTINCT FROM actor::text OR snapshot->>'tenant_id' IS DISTINCT FROM _tenant_id::text THEN RAISE EXCEPTION 'tgm.control_scope_changed' USING ERRCODE='42501';END IF;
 RETURN snapshot||jsonb_build_object('can_manage',private.wfm_can_manage(_tenant_id,false),'can_manage_ai',private.wfm_can_manage(_tenant_id,true));
END $function$

CREATE OR REPLACE FUNCTION private.dps_assert_configuration_scope(_configuration uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE cfg public.data_prep_configuration_revisions%ROWTYPE;req private.dps_scope_requests%ROWTYPE;
BEGIN
 SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=_configuration;
 IF cfg.id IS NULL THEN RAISE EXCEPTION 'dps.configuration_not_found' USING ERRCODE='42501';END IF;
 IF cfg.payload->>'shared_scope_contract' IS DISTINCT FROM 'dps-v1' THEN
  IF EXISTS(SELECT 1 FROM private.dps_scope_requests q WHERE q.pipeline_id=cfg.pipeline_id AND q.tenant_id=cfg.tenant_id AND q.created_at<=cfg.created_at)
  THEN RAISE EXCEPTION 'dps.shared_scope_contract_downgrade_refused' USING ERRCODE='42501';END IF;
  RETURN;
 END IF;
 SELECT * INTO req FROM private.dps_scope_requests WHERE configuration_id=cfg.id AND configuration_sha256=cfg.payload_sha256;
 IF req.id IS NULL OR NOT EXISTS(SELECT 1 FROM private.dps_scope_decisions WHERE request_id=req.id AND decision='approved') THEN RAISE EXCEPTION 'dps.approved_scope_required' USING ERRCODE='42501';END IF;
END $function$

CREATE OR REPLACE FUNCTION private.dps_assert_pipeline_sources_current(_tenant uuid, _pipeline uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_authorize(_tenant,_pipeline,'view');cfg public.data_prep_configuration_revisions%ROWTYPE;source uuid;
BEGIN
 SELECT c.* INTO cfg FROM public.data_prep_configuration_revisions c JOIN private.dpw_configuration_heads h ON h.configuration_id=c.id WHERE h.pipeline_id=_pipeline AND c.tenant_id=_tenant;
 IF cfg.id IS NULL THEN RETURN;END IF;
 PERFORM private.dps_assert_configuration_scope(cfg.id);
 IF cfg.payload->>'shared_scope_contract' IS DISTINCT FROM 'dps-v1' THEN RETURN;END IF;
 FOR source IN SELECT DISTINCT (value->>'data_source_id')::uuid FROM jsonb_array_elements(cfg.payload->'feeds') LOOP
  IF NOT EXISTS(SELECT 1 FROM public.data_resource_registry WHERE tenant_id=_tenant AND resource_type='data_source' AND data_source_id=source)
  OR private.dpw_source_allows(actor,_tenant,source,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dps.current_consumer_input_view_required' USING ERRCODE='42501';END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION private.dps_assert_preparation_source_scope(_tenant uuid, _run uuid, _actor uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE r public.data_prep_delivery_runs%ROWTYPE;cfg public.data_prep_configuration_revisions%ROWTYPE;source uuid;
BEGIN
 IF _actor IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'dps.current_consumer_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=_run AND tenant_id=_tenant;
 IF r.id IS NULL THEN RAISE EXCEPTION 'dps.preparation_binding_missing' USING ERRCODE='42501';END IF;
 SELECT * INTO cfg FROM public.data_prep_configuration_revisions WHERE id=nullif(r.snapshot->>'configuration_id','')::uuid AND tenant_id=_tenant AND pipeline_id=r.pipeline_id AND pipeline_version=r.pipeline_version;
 IF cfg.id IS NULL THEN
  IF EXISTS(SELECT 1 FROM private.dps_scope_requests q JOIN public.data_prep_configuration_revisions c ON c.id=q.configuration_id WHERE q.tenant_id=_tenant AND q.pipeline_id=r.pipeline_id AND c.pipeline_version=r.pipeline_version)
  THEN RAISE EXCEPTION 'dps.exact_configuration_snapshot_required' USING ERRCODE='42501';END IF;
  RETURN; -- truthful legacy absence, never reinterpret as a new approved scope
 END IF;
 PERFORM private.dps_assert_configuration_scope(cfg.id);
 IF cfg.payload->>'shared_scope_contract' IS DISTINCT FROM 'dps-v1' THEN RETURN;END IF;
 FOR source IN SELECT DISTINCT f.data_source_id FROM public.data_prep_run_inputs i JOIN public.data_prep_delivery_files f ON f.id=i.file_id AND f.tenant_id=_tenant WHERE i.run_id=r.id LOOP
  IF NOT EXISTS(SELECT 1 FROM public.data_resource_registry WHERE tenant_id=_tenant AND resource_type='data_source' AND data_source_id=source)
  OR private.dpw_source_allows(_actor,_tenant,source,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dps.current_original_input_view_required' USING ERRCODE='42501';END IF;
 END LOOP;
END $function$

CREATE OR REPLACE FUNCTION private.dpd_service_request_actor(_tenant uuid, _setup uuid, _operation text, _context uuid, _subject jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_peer_actor(_tenant,_subject);c private.dpd_request_contexts%ROWTYPE;enabled boolean;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant,actor,false);
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' OR _context IS NULL THEN RAISE EXCEPTION 'dpd.fixed_service_context_required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM private.dpd_request_contexts WHERE id=_context AND tenant_id=_tenant AND actor_id=actor AND setup_id=_setup AND operation=_operation;
 IF NOT FOUND OR c.expires_at<=clock_timestamp() OR c.verified_subject->>'sub' IS DISTINCT FROM _subject->>'sub' OR c.verified_subject->>'aal' IS DISTINCT FROM _subject->>'aal' OR c.verified_subject->>'exp' IS DISTINCT FROM _subject->>'exp' OR public.user_has_permission(actor,_tenant,'data.prep.author',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.fresh_verified_service_context_required' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant;
 IF NOT FOUND OR enabled IS NULL OR (enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(_tenant,host(c.request_ip)) IS DISTINCT FROM true)) OR NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant AND created_by=actor) THEN RAISE EXCEPTION 'dpd.current_service_network_scope_denied' USING ERRCODE='42501';END IF;RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION private.fvi_report_scope(_actor uuid, _tenant uuid, _spec jsonb)
 RETURNS uuid[]
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE ids uuid[]; recon uuid; bu uuid;
BEGIN
  IF NOT private.fvi_report_admin(_actor,_tenant) THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501'; END IF;
  recon:=nullif(_spec->>'reconciliation_id','')::uuid; bu:=nullif(_spec->>'bu_id','')::uuid;
  IF bu IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.business_units b WHERE b.id=bu AND b.tenant_id=_tenant AND NOT b.is_archived) THEN
    RAISE EXCEPTION 'Business unit unavailable' USING ERRCODE='42501'; END IF;
  SELECT coalesce(array_agg(d.id ORDER BY d.id),ARRAY[]::uuid[]) INTO ids FROM public.recon_definitions d
  WHERE d.tenant_id=_tenant AND private.user_can_access_recon(_actor,d.id,'read')
    AND (recon IS NULL OR d.id=recon) AND (bu IS NULL OR EXISTS(SELECT 1 FROM public.recon_definition_business_units o
      WHERE o.tenant_id=_tenant AND o.recon_id=d.id AND o.bu_id=bu));
  IF recon IS NOT NULL AND NOT recon=ANY(ids) THEN RAISE EXCEPTION 'Reconciliation unavailable in current scope' USING ERRCODE='42501'; END IF;
  RETURN ids;
END $function$

CREATE OR REPLACE FUNCTION private.fvi_report_cron_field(_field text, _value integer, _minimum integer, _maximum integer)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE item text; base text; step integer; low integer; high integer; matched boolean:=false;
BEGIN
  FOREACH item IN ARRAY string_to_array(_field,',') LOOP
    IF item !~ '^(\*|[0-9]+(-[0-9]+)?)(/[0-9]+)?$' THEN RAISE EXCEPTION 'Use a numeric five-field cron' USING ERRCODE='22023'; END IF;
    base:=split_part(item,'/',1); step:=CASE WHEN strpos(item,'/')>0 THEN split_part(item,'/',2)::integer ELSE 1 END;
    IF step<1 OR step>_maximum-_minimum+1 THEN RAISE EXCEPTION 'Invalid cron step' USING ERRCODE='22023'; END IF;
    IF base='*' THEN low:=_minimum;high:=_maximum;
    ELSIF strpos(base,'-')>0 THEN low:=split_part(base,'-',1)::integer;high:=split_part(base,'-',2)::integer;
    ELSE low:=base::integer;high:=CASE WHEN strpos(item,'/')>0 THEN _maximum ELSE low END; END IF;
    IF low<_minimum OR high>_maximum OR low>high THEN RAISE EXCEPTION 'Invalid cron range' USING ERRCODE='22023'; END IF;
    matched:=matched OR (_value BETWEEN low AND high AND mod(_value-low,step)=0);
  END LOOP;
  RETURN matched;
END $function$

CREATE OR REPLACE FUNCTION private.fvi_report_next_due(_spec jsonb, _after timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE kind text:=_spec->>'kind'; zone text:=_spec->>'timezone'; tm text:=_spec->>'time'; expr text; fields text[];
  date0 date; day date; wall timestamp; instants timestamptz[]; h integer; m integer; daymatch boolean; i integer; result timestamptz;
BEGIN
  IF jsonb_typeof(_spec)<>'object' OR kind IS NULL OR kind NOT IN ('daily','weekly','monthly','cron','once')
    OR zone IS NULL OR NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=zone)
    OR tm IS NULL OR tm !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(_spec) k WHERE k NOT IN ('kind','timezone','time','weekday','monthday','cron','once_date')) THEN
    RAISE EXCEPTION 'Invalid report schedule' USING ERRCODE='22023'; END IF;
  IF kind='once' THEN
    IF (_spec->>'once_date') IS NULL OR (_spec->>'once_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'Choose a one-time calendar date' USING ERRCODE='22023'; END IF;
    wall:=((_spec->>'once_date')||' '||tm)::timestamp; instants:=private.fvi_report_wall_instants(wall,zone);
    IF cardinality(instants)<>1 THEN RAISE EXCEPTION 'One-time schedule is ambiguous or nonexistent in this timezone' USING ERRCODE='22023'; END IF;
    IF instants[1]<_after+interval '1 minute' OR instants[1]>_after+interval '1 year' THEN RAISE EXCEPTION 'One-time schedule must be one minute to one year ahead' USING ERRCODE='22023'; END IF;
    RETURN instants[1];
  END IF;
  IF kind='weekly' AND ((_spec->>'weekday') IS NULL OR (_spec->>'weekday') !~ '^[0-6]$') THEN RAISE EXCEPTION 'Choose a weekday' USING ERRCODE='22023'; END IF;
  IF kind='monthly' AND ((_spec->>'monthday') IS NULL OR (_spec->>'monthday') !~ '^[0-9]{1,2}$' OR (_spec->>'monthday')::integer NOT BETWEEN 1 AND 31) THEN RAISE EXCEPTION 'Choose a day of month' USING ERRCODE='22023'; END IF;
  expr:=CASE WHEN kind='cron' THEN btrim(_spec->>'cron') ELSE split_part(tm,':',2)::integer::text||' '||split_part(tm,':',1)::integer::text||' '||
    CASE WHEN kind='monthly' THEN _spec->>'monthday' ELSE '*' END||' * '||CASE WHEN kind='weekly' THEN _spec->>'weekday' ELSE '*' END END;
  fields:=regexp_split_to_array(expr,'\s+'); IF expr IS NULL OR cardinality(fields)<>5 THEN RAISE EXCEPTION 'Use a numeric five-field cron' USING ERRCODE='22023'; END IF;
  PERFORM private.fvi_report_cron_field(fields[1],0,0,59),private.fvi_report_cron_field(fields[2],0,0,23),
    private.fvi_report_cron_field(fields[3],1,1,31),private.fvi_report_cron_field(fields[4],1,1,12),private.fvi_report_cron_field(fields[5],0,0,6);
  date0:=(_after AT TIME ZONE zone)::date;
  FOR i IN 0..1830 LOOP
    day:=date0+i;
    IF NOT private.fvi_report_cron_field(fields[4],extract(month FROM day)::integer,1,12) THEN CONTINUE; END IF;
    daymatch:=CASE WHEN fields[3]='*' OR fields[5]='*' THEN
      private.fvi_report_cron_field(fields[3],extract(day FROM day)::integer,1,31) AND private.fvi_report_cron_field(fields[5],extract(dow FROM day)::integer,0,6)
      ELSE private.fvi_report_cron_field(fields[3],extract(day FROM day)::integer,1,31) OR private.fvi_report_cron_field(fields[5],extract(dow FROM day)::integer,0,6) END;
    IF NOT daymatch THEN CONTINUE; END IF;
    result:=NULL;
    FOR h IN 0..23 LOOP
      IF NOT private.fvi_report_cron_field(fields[2],h,0,23) THEN CONTINUE; END IF;
      FOR m IN 0..59 LOOP
        IF NOT private.fvi_report_cron_field(fields[1],m,0,59) THEN CONTINUE; END IF;
        wall:=day::timestamp+make_interval(hours=>h,mins=>m);instants:=private.fvi_report_wall_instants(wall,zone);
        -- Skip nonexistent local times and run a repeated local minute only once, at its first instant.
        IF cardinality(instants)>0 AND instants[1]>_after AND (result IS NULL OR instants[1]<result) THEN result:=instants[1]; END IF;
      END LOOP;
    END LOOP;
    IF result IS NOT NULL THEN RETURN result; END IF;
  END LOOP;
  RAISE EXCEPTION 'No scheduled occurrence found in five years' USING ERRCODE='22023';
END $function$

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_stage_complete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE q public.recon_definition_governance_requests%ROWTYPE;
BEGIN
 IF NEW.access_mode='mapped_exact' AND NEW.governance_state='staging_copy' THEN
  SELECT * INTO q FROM public.recon_definition_governance_requests WHERE tenant_id=NEW.tenant_id
   AND staging_definition_id=NEW.id AND request_kind='edit' AND status='approved' AND mapped_governance_version=1;
  IF NOT FOUND OR private.mapped_recon_governance_scope_shape(NEW.tenant_id,NEW.id)
   IS DISTINCT FROM private.mapped_recon_governance_scope_shape(NEW.tenant_id,q.parent_definition_id) THEN
   PERFORM private.mapped_recon_governance_conflict('native_exact_copy_required');
  END IF;
  PERFORM private.mapped_recon_governance_mapping(NEW.tenant_id,NEW.id);
  PERFORM private.mapped_recon_governance_requester_current(NEW.tenant_id,NEW.id,q.requested_by);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION private.dpd_actor(_tenant uuid, _write boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpw_actor(_tenant);network_enabled boolean;
BEGIN
 PERFORM private.wfm_assert_enabled(_tenant,'prep');IF _write THEN PERFORM public.assert_data_prep_actor(_tenant,actor,false);END IF;
 IF public.user_has_permission(actor,_tenant,CASE WHEN _write THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.current_capability_denied' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO network_enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant;
 IF NOT FOUND OR network_enabled IS NULL THEN RAISE EXCEPTION 'dpd.current_network_policy_unavailable' USING ERRCODE='42501';END IF;
 -- Captured actual dpw_check_current_ip_access takes caller IP. It is not a
 -- trusted direct-native request binding; enabled policy cannot be bypassed.
 -- Network is enforced by fresh service-issued dpd_request_actor context in every public purpose. No caller IP/GUC use here.
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION private.dpd_setup_result(_tenant uuid, _setup uuid, _actor uuid, _replay boolean, _version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE;v private.dpd_versions%ROWTYPE;l private.dpd_preview_links%ROWTYPE;files jsonb;
BEGIN SELECT * INTO s FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id AND (_version IS NULL OR version=_version) ORDER BY version DESC LIMIT 1;SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=v.version;
 SELECT coalesce(jsonb_agg(jsonb_build_object('file_id',f.id,'feed_key',f.feed_key,'request_key',f.request_key,'content_sha256',f.content_sha256,'state',CASE WHEN r.file_id IS NULL THEN 'uploading' ELSE 'received' END,'parser_state',private.dpd_parser_state(f.id),'name',f.descriptor->>'filename','raw_row_count',sc.raw_row_count::text,'data_source_id',raw.data_source_id) ORDER BY f.created_at,f.id),'[]') INTO files FROM private.dpd_original_intents f LEFT JOIN private.dpd_original_receipts r ON r.file_id=f.id LEFT JOIN private.dpd_schema_receipts sc ON sc.file_id=f.id LEFT JOIN private.dpd_raw_source_links raw ON raw.file_id=f.id WHERE f.setup_id=s.id;
 RETURN jsonb_build_object('actor_id',_actor,'tenant_id',_tenant,'setup_id',s.id,'pipeline_id',l.pipeline_id,'batch_id',l.batch_id,'reserved_pipeline_id',s.reserved_pipeline_id,'draft_version',v.version,'head_draft_version',(SELECT max(head.version) FROM private.dpd_versions head WHERE head.setup_id=s.id),'is_current',v.version=(SELECT max(head.version) FROM private.dpd_versions head WHERE head.setup_id=s.id),'request_replay',_replay,'publish_allowed',false,'status','draft','request_key',s.request_key,'payload',v.payload,'payload_sha256',v.payload_sha256,'owner_bu_ids',v.owner_bu_ids,'group_ids',v.group_ids,'files',files,'can_submit',false,'configuration_id',l.configuration_id,'pipeline_version',l.pipeline_version);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_create_setup(_tenant_id uuid, _bu_id uuid, _owner_bu_ids uuid[], _group_ids uuid[], _title text, _business_date date, _execution_mode text, _human_in_loop boolean, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_actor(_tenant_id,true);s private.dpd_setups%ROWTYPE;input jsonb;reserved uuid:=gen_random_uuid();
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,NULL,'setup.create',_request_context_id);
 PERFORM private.dpd_scope_ids(_tenant_id,_owner_bu_ids,_group_ids);
 IF _request_key IS NULL OR length(btrim(coalesce(_title,''))) NOT BETWEEN 2 AND 120 OR _business_date IS NULL OR _execution_mode NOT IN('manual','assisted','agentic') OR _human_in_loop IS NULL OR (_bu_id IS NOT NULL AND NOT _bu_id=ANY(_owner_bu_ids)) THEN RAISE EXCEPTION 'dpd.invalid_setup' USING ERRCODE='22023';END IF;
 -- Current authorized modes are read separately by main; no assisted/agentic
 -- admission is inferred from a selected UI value before real pipeline exists.
 IF private.dpw_mode_attest(actor,_tenant_id,reserved,_execution_mode,_human_in_loop) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.current_draft_mode_policy_binding_required' USING ERRCODE='42501';END IF;
 input:=jsonb_build_object('bu_id',_bu_id,'owner_bu_ids',to_jsonb(_owner_bu_ids),'group_ids',to_jsonb(coalesce(_group_ids,'{}'::uuid[])),'title',btrim(_title),'business_date',_business_date,'execution_mode',_execution_mode,'human_in_loop',_human_in_loop);
 PERFORM pg_advisory_xact_lock(hashtextextended('dpd-create:'||_tenant_id::text||':'||actor::text||':'||_request_key::text,0));SELECT * INTO s FROM private.dpd_setups WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF FOUND THEN IF s.input IS DISTINCT FROM input THEN RAISE EXCEPTION 'dpd.request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_setup_result(_tenant_id,s.id,actor,true);END IF;
 INSERT INTO private.dpd_setups(tenant_id,created_by,reserved_pipeline_id,request_key,input,input_sha256) VALUES(_tenant_id,actor,reserved,_request_key,input,private.dpw_hash(input)) RETURNING * INTO s;
 INSERT INTO private.dpd_versions(setup_id,version,request_key,created_by,payload,payload_sha256,owner_bu_ids,group_ids) VALUES(s.id,1,_request_key,actor,input,private.dpw_hash(input),_owner_bu_ids,coalesce(_group_ids,'{}'::uuid[]));
 PERFORM private.dpd_event(_tenant_id,s.id,actor,'setup.created',s.id,jsonb_build_object('draft_version',1,'reserved_pipeline_id',s.reserved_pipeline_id,'public_pipeline_created',false));RETURN private.dpd_setup_result(_tenant_id,s.id,actor,false);
END $function$

CREATE OR REPLACE FUNCTION public.fvi_save_report_design(_tenant uuid, _request uuid, _id uuid, _expected integer, _name text, _spec jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); old public.fvi_report_designs; replay public.fvi_report_design_requests; version integer; body jsonb;
BEGIN
  PERFORM private.fvi_report_validate(_spec); PERFORM private.fvi_report_scope(actor,_tenant,_spec);
  IF _request IS NULL OR _id IS NULL OR _expected IS NULL OR _expected<0 OR length(btrim(_name)) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'Invalid design request' USING ERRCODE='22023'; END IF;
  body:=jsonb_build_object('id',_id,'expected',_expected,'name',btrim(_name),'spec',_spec);
  PERFORM pg_advisory_xact_lock(hashtextextended(_request::text,0));
  SELECT * INTO replay FROM public.fvi_report_design_requests WHERE request_id=_request;
  IF FOUND THEN
    IF replay.actor_id<>actor OR replay.tenant_id<>_tenant OR replay.request<>body THEN RAISE EXCEPTION 'Report request key conflict' USING ERRCODE='22023'; END IF;
    RETURN jsonb_build_object('id',replay.design_id,'version',replay.version,'replayed',true);
  END IF;
  SELECT * INTO old FROM public.fvi_report_designs WHERE id=_id FOR UPDATE;
  IF FOUND THEN
    IF old.tenant_id<>_tenant OR old.current_version<>_expected THEN RAISE EXCEPTION 'Report version changed; reload before saving' USING ERRCODE='40001'; END IF;
    version:=old.current_version+1;
    UPDATE public.fvi_report_designs SET name=btrim(_name),current_version=version,updated_at=clock_timestamp() WHERE id=_id;
  ELSE
    IF _expected<>0 THEN RAISE EXCEPTION 'Report design unavailable' USING ERRCODE='40001'; END IF;
    version:=1;
    INSERT INTO public.fvi_report_designs(id,tenant_id,name,current_version,created_by) VALUES(_id,_tenant,btrim(_name),version,actor);
  END IF;
  INSERT INTO public.fvi_report_design_versions(design_id,version,tenant_id,spec,created_by) VALUES(_id,version,_tenant,_spec,actor);
  INSERT INTO public.fvi_report_design_requests(request_id,tenant_id,actor_id,request,design_id,version) VALUES(_request,_tenant,actor,body,_id,version);
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(actor,_tenant,'tenant','report.design.save','fvi_report_designs',_id::text,jsonb_build_object('version',version,'request_id',_request));
  RETURN jsonb_build_object('id',_id,'version',version,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.fvi_preview_report_schedule(_tenant uuid, _spec jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE after_at timestamptz:=clock_timestamp(); due timestamptz; times jsonb:='[]'; i integer;
BEGIN
  IF NOT private.fvi_report_admin(auth.uid(),_tenant) THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501'; END IF;
  FOR i IN 1..5 LOOP
    due:=private.fvi_report_next_due(_spec,after_at); times:=times||jsonb_build_array(due); after_at:=due;
    IF _spec->>'kind'='once' THEN EXIT; END IF;
  END LOOP;
  RETURN jsonb_build_object('timezone',_spec->>'timezone','occurrences',times,'persisted',false,'recomputed_at_approval',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_lookup_setup_request(_tenant_id uuid, _request_key uuid, _expected_input jsonb, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_actor(_tenant_id,true);s private.dpd_setups%ROWTYPE;
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,NULL,'setup.lookup',_request_context_id); SELECT * INTO s FROM private.dpd_setups WHERE tenant_id=_tenant_id AND created_by=actor AND request_key=_request_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'state','absent','result',NULL);END IF;
 IF s.input IS DISTINCT FROM _expected_input THEN RAISE EXCEPTION 'dpd.lookup_request_conflict' USING ERRCODE='PT409';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'state','found','result',private.dpd_setup_result(_tenant_id,s.id,actor,true));END $function$

CREATE OR REPLACE FUNCTION public.fvi_request_report_schedule(_tenant uuid, _id uuid, _design uuid, _version integer, _spec jsonb, _formats text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); design jsonb; old public.fvi_report_schedules;
BEGIN
  SELECT spec INTO design FROM public.fvi_report_design_versions WHERE design_id=_design AND version=_version AND tenant_id=_tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report version unavailable' USING ERRCODE='42501'; END IF;
  PERFORM private.fvi_report_scope(actor,_tenant,design); PERFORM private.fvi_report_next_due(_spec,clock_timestamp());
  IF _id IS NULL OR _formats IS NULL OR cardinality(_formats) NOT BETWEEN 1 AND 5 OR NOT _formats <@ ARRAY['csv','json','xlsx','pdf','html']::text[]
    OR cardinality(_formats)<>(SELECT count(DISTINCT v) FROM unnest(_formats) v) THEN RAISE EXCEPTION 'Choose supported distinct formats' USING ERRCODE='22023'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(_id::text,0)); SELECT * INTO old FROM public.fvi_report_schedules WHERE id=_id;
  IF FOUND THEN
    IF old.tenant_id<>_tenant OR old.created_by<>actor OR old.design_id<>_design OR old.design_version<>_version OR old.schedule_spec<>_spec OR old.formats<>_formats THEN
      RAISE EXCEPTION 'Schedule request key conflict' USING ERRCODE='22023'; END IF;
    RETURN to_jsonb(old)||jsonb_build_object('replayed',true);
  END IF;
  INSERT INTO public.fvi_report_schedules(id,tenant_id,design_id,design_version,created_by,schedule_spec,formats)
    VALUES(_id,_tenant,_design,_version,actor,_spec,_formats) RETURNING * INTO old;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(actor,_tenant,'tenant','report.schedule.request','fvi_report_schedules',_id::text,jsonb_build_object('design_version',_version,'delivery','in_app'));
  RETURN to_jsonb(old)||jsonb_build_object('replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.fvi_decide_report_schedule(_tenant uuid, _id uuid, _revision integer, _decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); job public.fvi_report_schedules; design jsonb; due timestamptz;
BEGIN
  IF NOT private.fvi_report_admin(actor,_tenant) OR auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' THEN RAISE EXCEPTION 'Current MFA-verified tenant administrator required' USING ERRCODE='42501'; END IF;
  IF _decision NOT IN ('approve','reject') OR _decision IS NULL THEN RAISE EXCEPTION 'Invalid schedule decision' USING ERRCODE='22023'; END IF;
  SELECT * INTO job FROM public.fvi_report_schedules WHERE id=_id AND tenant_id=_tenant FOR UPDATE;
  IF NOT FOUND OR job.state<>'pending' OR job.revision<>_revision THEN RAISE EXCEPTION 'Schedule request changed; reload' USING ERRCODE='40001'; END IF;
  IF job.created_by=actor THEN RAISE EXCEPTION 'Independent checker required' USING ERRCODE='42501'; END IF;
  SELECT spec INTO design FROM public.fvi_report_design_versions WHERE design_id=job.design_id AND version=job.design_version AND tenant_id=_tenant;
  PERFORM private.fvi_report_scope(job.created_by,_tenant,design); PERFORM private.fvi_report_scope(actor,_tenant,design);
  due:=CASE WHEN _decision='approve' THEN private.fvi_report_next_due(job.schedule_spec,clock_timestamp()) ELSE NULL END;
  UPDATE public.fvi_report_schedules SET state=CASE WHEN _decision='approve' THEN 'approved' ELSE 'rejected' END,
    approved_by=actor,approved_at=clock_timestamp(),next_run_at=due,revision=revision+1 WHERE id=_id RETURNING * INTO job;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(actor,_tenant,'tenant','report.schedule.'||_decision,'fvi_report_schedules',_id::text,jsonb_build_object('revision',job.revision,'design_version',job.design_version));
  RETURN to_jsonb(job);
END $function$

CREATE OR REPLACE FUNCTION public.fvi_manage_report_schedule(_tenant uuid, _id uuid, _revision integer, _action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE job public.fvi_report_schedules;
BEGIN
  IF NOT private.fvi_report_admin(auth.uid(),_tenant) THEN RAISE EXCEPTION 'Active tenant administrator required' USING ERRCODE='42501'; END IF;
  SELECT * INTO job FROM public.fvi_report_schedules WHERE id=_id AND tenant_id=_tenant FOR UPDATE;
  IF NOT FOUND OR job.revision<>_revision OR _action NOT IN ('pause','request_resume') OR _action IS NULL
    OR (_action='pause' AND job.state<>'approved') OR (_action='request_resume' AND job.state<>'paused') THEN RAISE EXCEPTION 'Schedule changed or transition unavailable' USING ERRCODE='40001'; END IF;
  IF _action='request_resume' AND job.created_by<>auth.uid() THEN RAISE EXCEPTION 'Original maker must request resume' USING ERRCODE='42501'; END IF;
  UPDATE public.fvi_report_schedules SET state=CASE WHEN _action='pause' THEN 'paused' ELSE 'pending' END,revision=revision+1,
    approved_by=CASE WHEN _action='pause' THEN approved_by ELSE NULL END,approved_at=CASE WHEN _action='pause' THEN approved_at ELSE NULL END,
    next_run_at=NULL WHERE id=_id RETURNING * INTO job;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES(auth.uid(),_tenant,'tenant','report.schedule.'||_action,'fvi_report_schedules',_id::text,jsonb_build_object('revision',job.revision));
  RETURN to_jsonb(job);
END $function$

CREATE OR REPLACE FUNCTION public.fvi_generate_saved_report(_tenant uuid, _design uuid, _version integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE spec jsonb;
BEGIN
  SELECT v.spec INTO spec FROM public.fvi_report_design_versions v WHERE v.tenant_id=_tenant AND v.design_id=_design AND v.version=_version;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report version unavailable' USING ERRCODE='42501'; END IF;
  RETURN private.fvi_report_snapshot(auth.uid(),_tenant,spec);
END $function$

CREATE OR REPLACE FUNCTION public.fvi_get_report_schedule_run(_tenant uuid, _id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE r public.fvi_report_schedule_runs; spec jsonb; ids uuid[]; snapshot_ids uuid[];
BEGIN
  SELECT * INTO r FROM public.fvi_report_schedule_runs WHERE id=_id AND tenant_id=_tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'Report run unavailable' USING ERRCODE='42501'; END IF;
  SELECT v.spec INTO spec FROM public.fvi_report_design_versions v WHERE v.design_id=r.design_id AND v.version=r.design_version AND v.tenant_id=_tenant;
  ids:=private.fvi_report_scope(auth.uid(),_tenant,spec);
  IF r.state<>'completed' THEN RAISE EXCEPTION 'Report run has no completed downloadable artifact' USING ERRCODE='55000'; END IF;
  SELECT coalesce(array_agg(v::uuid),ARRAY[]::uuid[]) INTO snapshot_ids FROM jsonb_array_elements_text(r.result->'reconciliation_ids') v;
  IF NOT snapshot_ids <@ ids THEN RAISE EXCEPTION 'Report snapshot no longer lies in current authorized scope' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('run_id',r.id,'design_id',r.design_id,'version',r.design_version,'spec',spec,'snapshot',r.result,'due_at',r.due_at);
END $function$

CREATE OR REPLACE FUNCTION public.fvi_process_report_schedule_tick(_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE job public.fvi_report_schedules; design jsonb; ids uuid[]; checker_ids uuid[]; output jsonb; run_id uuid; code text; run_state text; total integer:=0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
    AND NOT (auth.role() IS NULL AND auth.uid() IS NULL AND session_user=current_user) THEN
    RAISE EXCEPTION 'Trusted report scheduler service or database-owned cron required' USING ERRCODE='42501'; END IF;
  IF _limit IS NULL OR _limit NOT BETWEEN 1 AND 20 THEN RAISE EXCEPTION 'Invalid tick limit' USING ERRCODE='22023'; END IF;
  FOR job IN SELECT s.* FROM public.fvi_report_schedules s WHERE s.state='approved' AND s.next_run_at<=clock_timestamp()
    ORDER BY s.next_run_at,s.id FOR UPDATE SKIP LOCKED LIMIT _limit LOOP
    SELECT spec INTO design FROM public.fvi_report_design_versions WHERE design_id=job.design_id AND version=job.design_version AND tenant_id=job.tenant_id;
    output:=NULL;code:=NULL;run_state:='completed';
    BEGIN
      IF job.approved_by=job.created_by OR NOT private.fvi_report_admin(job.approved_by,job.tenant_id) THEN RAISE EXCEPTION 'Current independent approval unavailable' USING ERRCODE='42501'; END IF;
      ids:=private.fvi_report_scope(job.created_by,job.tenant_id,design);checker_ids:=private.fvi_report_scope(job.approved_by,job.tenant_id,design);
      IF NOT ids <@ checker_ids THEN RAISE EXCEPTION 'Checker report scope changed' USING ERRCODE='42501'; END IF;
      output:=private.fvi_report_snapshot(job.created_by,job.tenant_id,design);
    EXCEPTION WHEN OTHERS THEN
      code:=SQLSTATE;run_state:=CASE WHEN code='42501' THEN 'blocked' ELSE 'failed' END;
    END;
    INSERT INTO public.fvi_report_schedule_runs(schedule_id,tenant_id,design_id,design_version,due_at,state,result,error_code)
      VALUES(job.id,job.tenant_id,job.design_id,job.design_version,job.next_run_at,run_state,output,code)
      ON CONFLICT(schedule_id,due_at) DO NOTHING RETURNING id INTO run_id;
    IF run_id IS NOT NULL THEN
      INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
        VALUES(NULL,job.tenant_id,'tenant','report.schedule.execute','fvi_report_schedule_runs',run_id::text,
          jsonb_build_object('schedule_id',job.id,'due_at',job.next_run_at,'state',run_state,'execution_identity','trusted report scheduler','maker_id',job.created_by,'checker_id',job.approved_by));
      total:=total+1;
    END IF;
    IF run_state<>'completed' THEN
      UPDATE public.fvi_report_schedules SET state='paused',next_run_at=NULL,revision=revision+1 WHERE id=job.id;
    ELSIF job.schedule_spec->>'kind'='once' THEN
      UPDATE public.fvi_report_schedules SET state='completed',next_run_at=NULL,revision=revision+1 WHERE id=job.id;
    ELSE
      UPDATE public.fvi_report_schedules SET next_run_at=private.fvi_report_next_due(job.schedule_spec,job.next_run_at),revision=revision+1 WHERE id=job.id;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('processed',total,'delivery','in_app','emails_sent',0);
END $function$

CREATE OR REPLACE FUNCTION public.get_reference_table_view_summary(_tenant_id uuid, _table_ids uuid[])
 RETURNS TABLE(resource_type text, resource_id uuid, public_id text, access_state text, business_unit_names text[], business_unit_count integer, user_group_names text[], user_group_count integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE
  v_actor uuid := auth.uid(); v_role text; v_ids uuid[]; v_id uuid;
  v_root public.reference_data_tables%ROWTYPE; v_registry uuid;
  v_owners text[]; v_groups text[]; v_has_owners boolean;
BEGIN
  -- Registered workspace availability; original authorization and entire body follow unchanged.
  PERFORM private.wfm_assert_enabled(_tenant_id,'reference');

  IF v_actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated'
    OR current_setting('role', true) IS DISTINCT FROM 'authenticated' THEN
    RAISE EXCEPTION 'Reference metadata requires an authenticated caller' USING ERRCODE = '42501';
  END IF;
  IF _tenant_id IS NULL OR _table_ids IS NULL OR cardinality(_table_ids) NOT BETWEEN 1 AND 100
    OR array_ndims(_table_ids) <> 1 OR array_position(_table_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'Reference metadata requires a tenant and 1 to 100 table IDs' USING ERRCODE = '22023';
  END IF;
  SELECT tm.role::text INTO v_role FROM public.tenant_members tm
    WHERE tm.tenant_id = _tenant_id AND tm.user_id = v_actor AND tm.active;
  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Reference metadata is not authorized' USING ERRCODE = '42501';
  END IF;
  SELECT array_agg(DISTINCT x ORDER BY x) INTO v_ids FROM unnest(_table_ids) AS x;
  FOREACH v_id IN ARRAY v_ids LOOP
    SELECT * INTO v_root FROM public.reference_data_tables r WHERE r.id = v_id AND r.tenant_id = _tenant_id;
    IF NOT FOUND OR public.reference_scope_allows(v_id, 'view') IS NOT TRUE THEN CONTINUE; END IF;
    v_registry := NULL; v_owners := ARRAY[]::text[]; v_groups := ARRAY[]::text[];
    SELECT r.id INTO v_registry FROM public.data_resource_registry r
      WHERE r.tenant_id = _tenant_id AND r.resource_type = 'reference_table' AND r.reference_table_id = v_id;
    SELECT EXISTS (SELECT 1 FROM public.data_resource_registry_owner_bu o
      WHERE o.tenant_id = _tenant_id AND o.registry_id = v_registry) INTO v_has_owners;
    IF v_role = 'tenant_admin' OR v_root.access_mode = 'legacy_passthrough' THEN
      -- Legacy root read is an existing active-member contract. Return only
      -- declared metadata for that root; it does not grant BU/group admin access.
      SELECT coalesce(array_agg(DISTINCT b.name ORDER BY b.name), ARRAY[]::text[]) INTO v_owners
        FROM public.data_resource_registry_owner_bu o JOIN public.business_units b
          ON b.id = o.bu_id AND b.tenant_id = o.tenant_id AND NOT b.is_archived
        WHERE o.tenant_id = _tenant_id AND o.registry_id = v_registry;
      SELECT coalesce(array_agg(DISTINCT g.name ORDER BY g.name), ARRAY[]::text[]) INTO v_groups
        FROM public.data_resource_registry_grants x JOIN public.tenant_groups g
          ON g.id = x.principal_group_id AND g.tenant_id = x.tenant_id
        JOIN public.data_resource_registry_owner_bu o
          ON o.tenant_id = x.tenant_id AND o.registry_id = x.registry_id AND o.bu_id = x.bu_id
        JOIN public.business_units b ON b.id = o.bu_id AND b.tenant_id = o.tenant_id AND NOT b.is_archived
        WHERE x.tenant_id = _tenant_id AND x.registry_id = v_registry AND x.principal_type = 'group'
          AND (v_role = 'tenant_admin' OR x.action = 'view');
    ELSE
      -- Mapped ordinary readers see only qualifying current view paths. Keep
      -- the captured direct/group/inherited-BU predicate, including active BUs.
      WITH qualifying AS (
        SELECT g.bu_id, g.principal_type, g.principal_group_id
        FROM public.data_resource_registry_grants g
        JOIN public.data_resource_registry_owner_bu o
          ON o.tenant_id = g.tenant_id AND o.registry_id = g.registry_id AND o.bu_id = g.bu_id
        JOIN public.business_units target ON target.id = o.bu_id AND target.tenant_id = o.tenant_id AND NOT target.is_archived
        WHERE g.tenant_id = _tenant_id AND g.registry_id = v_registry AND g.action = 'view' AND (
          (g.principal_type = 'user' AND g.principal_user_id = v_actor AND EXISTS (
            SELECT 1 FROM public.bu_user_assignments ua JOIN public.business_units assigned
              ON assigned.id = ua.bu_id AND assigned.tenant_id = ua.tenant_id AND NOT assigned.is_archived
            WHERE ua.tenant_id = _tenant_id AND ua.user_id = v_actor
              AND (assigned.id = target.id OR (ua.inherit_descendants AND target.path <@ assigned.path))))
          OR (g.principal_type = 'group' AND EXISTS (
            SELECT 1 FROM public.tenant_group_members gm JOIN public.tenant_groups tg
              ON tg.id = gm.group_id AND tg.tenant_id = _tenant_id
            WHERE gm.group_id = g.principal_group_id AND gm.user_id = v_actor)
            AND EXISTS (SELECT 1 FROM public.bu_group_assignments ga JOIN public.business_units assigned
              ON assigned.id = ga.bu_id AND assigned.tenant_id = ga.tenant_id AND NOT assigned.is_archived
              WHERE ga.tenant_id = _tenant_id AND ga.group_id = g.principal_group_id
                AND (assigned.id = target.id OR (ga.inherit_descendants AND target.path <@ assigned.path))))
        )
      ) SELECT
        coalesce((SELECT array_agg(DISTINCT b.name ORDER BY b.name) FROM qualifying q JOIN public.business_units b
          ON b.id = q.bu_id AND b.tenant_id = _tenant_id), ARRAY[]::text[]),
        coalesce((SELECT array_agg(DISTINCT g.name ORDER BY g.name) FROM qualifying q JOIN public.tenant_groups g
          ON g.id = q.principal_group_id AND g.tenant_id = _tenant_id WHERE q.principal_type = 'group'), ARRAY[]::text[])
        INTO v_owners, v_groups;
    END IF;
    resource_type := 'reference_table'; resource_id := v_id; public_id := v_root.public_id;
    access_state := CASE WHEN v_has_owners THEN 'mapped' ELSE 'unmapped' END;
    business_unit_names := v_owners; business_unit_count := cardinality(v_owners);
    user_group_names := v_groups; user_group_count := cardinality(v_groups);
    RETURN NEXT;
  END LOOP;
END $function$

CREATE OR REPLACE FUNCTION public.dpd_save_setup(_tenant_id uuid, _setup_id uuid, _expected_draft_version integer, _payload jsonb, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);v private.dpd_versions%ROWTYPE;head private.dpd_versions%ROWTYPE;f jsonb;file private.dpd_original_intents%ROWTYPE;schema private.dpd_schema_receipts%ROWTYPE;owners uuid[];groups uuid[];scope jsonb;
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'setup.save',_request_context_id);
 PERFORM private.dpd_assert_transform_configuration(_payload);
 IF _request_key IS NULL OR jsonb_typeof(_payload) IS DISTINCT FROM 'object' OR _payload->>'on_failure' IS DISTINCT FROM 'block' OR jsonb_typeof(_payload->'feeds') IS DISTINCT FROM 'array' OR jsonb_array_length(_payload->'feeds') NOT BETWEEN 1 AND 50 OR jsonb_typeof(_payload->'steps') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'dq_rules') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'business_fields') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'required_fields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.complete_current_configuration_required' USING ERRCODE='22023';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements((_payload->'steps')||(SELECT coalesce(jsonb_agg(step.value),'[]') FROM jsonb_array_elements(_payload->'feeds') AS feed(value) CROSS JOIN LATERAL jsonb_array_elements(coalesce(feed.value->'steps','[]')) AS step(value))) AS st(value) WHERE st.value->>'kind' IN('sort','dedupe','filter','filter_expr')) OR _payload ? 'approved_exclusions' THEN RAISE EXCEPTION 'dpdi.unsupported_transform_or_exclusion_choose_supported_before_save' USING ERRCODE='22023';END IF;
 PERFORM 1 FROM private.dpd_setups WHERE id=s.id FOR UPDATE;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id AND created_by=auth.uid() AND request_key=_request_key;
 IF FOUND THEN IF v.payload IS DISTINCT FROM _payload OR v.version IS DISTINCT FROM _expected_draft_version+1 THEN RAISE EXCEPTION 'dpd.configuration_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_setup_result(_tenant_id,s.id,auth.uid(),true,v.version);END IF;
 SELECT * INTO head FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;IF head.version<>_expected_draft_version THEN RAISE EXCEPTION 'dpd.stale_draft_configuration' USING ERRCODE='PT409';END IF;
 PERFORM private.dpd_validate_confirmed_mapping(_tenant_id,s.id,head.version+1,_payload->'confirmed_mapping');
 FOR f IN SELECT value FROM jsonb_array_elements(_payload->'feeds') LOOP
  IF f->'original_ref' IS NULL THEN CONTINUE;END IF;
 SELECT * INTO file FROM private.dpd_original_intents WHERE id=(f->'original_ref'->>'file_id')::uuid AND setup_id=s.id AND feed_key=f->>'key';SELECT * INTO schema FROM private.dpd_schema_receipts WHERE file_id=file.id;
  IF file.id IS NULL OR schema.file_id IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=file.id) OR schema.schema_sha256 IS DISTINCT FROM f->'original_ref'->>'schema_sha256' OR private.dpd_original_viewable(file.id) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.exact_received_original_schema_pin_required' USING ERRCODE='PT409';END IF;
 END LOOP;
 owners:=head.owner_bu_ids;groups:=head.group_ids;
 IF _payload ? '_draft_scope' THEN
  PERFORM private.dps_admin(_tenant_id);scope:=_payload->'_draft_scope';
  IF jsonb_typeof(scope) IS DISTINCT FROM 'object' OR scope-ARRAY['owner_bu_ids','group_ids']<>'{}'::jsonb OR jsonb_typeof(scope->'owner_bu_ids') IS DISTINCT FROM 'array' OR jsonb_typeof(scope->'group_ids') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.explicit_declared_scope_required' USING ERRCODE='22023';END IF;
  owners:=private.dps_ids(ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(scope->'owner_bu_ids')),100,true);groups:=private.dps_ids(ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(scope->'group_ids')),100,false);
  PERFORM private.dps_selections(_tenant_id,owners,groups);
 END IF;
 INSERT INTO private.dpd_versions(setup_id,version,request_key,created_by,payload,payload_sha256,owner_bu_ids,group_ids) VALUES(s.id,head.version+1,_request_key,auth.uid(),_payload,private.dpw_hash(_payload),owners,groups);
 PERFORM private.dpd_event(_tenant_id,s.id,auth.uid(),'configuration.versioned',s.id,jsonb_build_object('draft_version',head.version+1,'configuration_sha256',private.dpw_hash(_payload),'original_refs',_payload->'original_refs'));RETURN private.dpd_setup_result(_tenant_id,s.id,auth.uid(),false);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_authorize_draft_original_intake(_tenant_id uuid, _setup_id uuid, _feed_key text, _operation text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,_operation='intake');v private.dpd_versions%ROWTYPE;actor uuid:=auth.uid();policy jsonb;
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'original.authorize',_request_context_id);
 IF _operation NOT IN('intake','original.read') OR length(coalesce(_feed_key,'')) NOT BETWEEN 1 AND 120 OR _feed_key LIKE 'legacy:%' THEN RAISE EXCEPTION 'dpd.invalid_original_operation' USING ERRCODE='22023';END IF;
 IF _operation='intake' THEN PERFORM private.wfm_assert_enabled(_tenant_id,'data');IF public.user_has_permission(actor,_tenant_id,'data.source.create',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.original_source_create_denied' USING ERRCODE='42501';END IF;END IF;
 SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;policy:=private.dpw_effective_attachment_policy(_tenant_id);
 RETURN jsonb_build_object('actor_id',actor,'auth_role',auth.role(),'tenant_id',_tenant_id,'setup_id',s.id,'feed_key',_feed_key,'operation',_operation,'pipeline_id',NULL,'reserved_pipeline_id',s.reserved_pipeline_id,'draft_version',v.version,'can_upload',_operation='intake','allow_empty',false,
 'storage_capability',jsonb_build_object('bucket_id','data-prep-authoring-originals','public',false,'max_original_bytes',52428800,'max_expanded_bytes',52428800,'max_parsed_bytes',52428800,'max_rows',1000000,'max_columns',500,'chunk_max_rows',1000,'chunk_max_bytes',1048576),'retention_policy',policy,'worker_budget_qualification_required',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_claim_draft_original(_tenant_id uuid, _setup_id uuid, _feed_key text, _descriptor jsonb, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE admission jsonb;actor uuid:=auth.uid();f private.dpd_original_intents%ROWTYPE;policy jsonb;ctx uuid;
BEGIN
 PERFORM private.dpd_request_actor(_tenant_id,_setup_id,'original.claim',_request_context_id);
 admission:=jsonb_build_object('retention_policy',private.dpw_effective_attachment_policy(_tenant_id));
 PERFORM private.wfm_assert_enabled(_tenant_id,'data');IF public.user_has_permission(auth.uid(),_tenant_id,'data.source.create',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.original_source_create_denied' USING ERRCODE='42501';END IF;
 IF _request_key IS NULL OR jsonb_typeof(_descriptor) IS DISTINCT FROM 'object' OR coalesce(_descriptor->>'content_sha256','')!~'^[a-f0-9]{64}$' OR coalesce(_descriptor->>'size_bytes','')!~'^[1-9][0-9]*$' OR (_descriptor->>'size_bytes')::bigint NOT BETWEEN 1 AND 52428800 OR length(coalesce(_descriptor->>'filename','')) NOT BETWEEN 1 AND 255 OR (_descriptor->>'format' IN('csv','tsv','xlsx')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.exact_original_descriptor_required' USING ERRCODE='22023';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('dpd-original:'||_setup_id::text||':'||_feed_key||':'||actor::text||':'||_request_key::text,0));SELECT * INTO f FROM private.dpd_original_intents WHERE setup_id=_setup_id AND feed_key=_feed_key AND created_by=actor AND request_key=_request_key;
 IF FOUND THEN IF f.descriptor IS DISTINCT FROM _descriptor THEN RAISE EXCEPTION 'dpd.original_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_original_result(actor,f.id,true);END IF;
 policy:=admission->'retention_policy';IF coalesce((policy->>'period_days')::integer,0)<1 OR policy->>'policy_id' IS NULL OR policy->>'version' IS NULL THEN RAISE EXCEPTION 'dpd.actual_retention_policy_required' USING ERRCODE='42501';END IF;
 ctx:=_request_context_id;
 f.id:=gen_random_uuid();INSERT INTO private.dpd_original_intents(id,setup_id,tenant_id,feed_key,created_by,request_key,descriptor,descriptor_sha256,content_sha256,size_bytes,original_path,request_context_id,retention_policy,expires_at)
 VALUES(f.id,_setup_id,_tenant_id,_feed_key,actor,_request_key,_descriptor,private.dpw_hash(_descriptor),_descriptor->>'content_sha256',(_descriptor->>'size_bytes')::bigint,_tenant_id::text||'/'||_setup_id::text||'/'||f.id::text||'/original',ctx,policy,clock_timestamp()+((policy->>'period_days')::integer)*interval '1 day');
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'original.claimed',f.id,jsonb_build_object('request_key',_request_key,'content_sha256',_descriptor->>'content_sha256','descriptor_sha256',private.dpw_hash(_descriptor),'retention_policy',policy));RETURN private.dpd_original_result(actor,f.id,false);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_confirm_draft_original(_tenant_id uuid, _setup_id uuid, _file_id uuid, _request_key uuid, _verification jsonb, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'original.confirm',(_verification->>'request_context_id')::uuid,_verified_subject);f private.dpd_original_intents%ROWTYPE;r private.dpd_original_receipts%ROWTYPE;o storage.objects%ROWTYPE;inventory jsonb:=coalesce(_verification->'sheet_inventory','[]'::jsonb);
BEGIN
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR f.request_key<>_request_key OR private.dpd_original_viewable(f.id) IS DISTINCT FROM true OR _verification->>'verified_original_sha256' IS DISTINCT FROM f.content_sha256 OR (_verification->>'verified_original_size_bytes')::bigint IS DISTINCT FROM f.size_bytes OR _verification->>'storage_bucket' IS DISTINCT FROM f.storage_bucket OR _verification->>'storage_path' IS DISTINCT FROM f.original_path OR _verification->>'verification_source' IS DISTINCT FROM 'main_fixed_original_download_and_hash' OR jsonb_typeof(inventory) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.actual_original_attestation_mismatch' USING ERRCODE='PT409';END IF;
 SELECT * INTO o FROM storage.objects WHERE bucket_id=f.storage_bucket AND name=f.original_path AND is_delete_marker IS NOT TRUE AND archived_at IS NULL;
 IF NOT FOUND OR (o.metadata->>'size')::bigint IS DISTINCT FROM f.size_bytes OR coalesce(o.owner_id,o.owner::text) IS DISTINCT FROM actor::text THEN RAISE EXCEPTION 'dpd.original_storage_object_unconfirmed' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM private.dpd_original_receipts WHERE file_id=f.id;
 IF FOUND THEN IF r.verified_original_sha256<>f.content_sha256 OR r.storage_object_id<>o.id OR r.sheet_inventory IS DISTINCT FROM inventory THEN RAISE EXCEPTION 'dpd.original_receipt_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_original_result(actor,f.id,true)||jsonb_build_object('transport_role','service_role');END IF;
 INSERT INTO private.dpd_original_receipts(file_id,setup_id,tenant_id,created_by,verified_original_sha256,verified_size_bytes,storage_object_id,sheet_inventory,verification) VALUES(f.id,_setup_id,_tenant_id,actor,f.content_sha256,f.size_bytes,o.id,inventory,_verification||jsonb_build_object('request_context_id',(_verification->>'request_context_id')::uuid));
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'original.received',f.id,jsonb_build_object('content_sha256',f.content_sha256,'verified_size_bytes',f.size_bytes::text,'storage_object_id',o.id,'parser_state','unparsed','publish_allowed',false));RETURN private.dpd_original_result(actor,f.id,false)||jsonb_build_object('transport_role','service_role');
END $function$

CREATE OR REPLACE FUNCTION private.dpd_storage_allows(_name text, _write boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f private.dpd_original_intents%ROWTYPE;s private.dpd_setups%ROWTYPE;actor uuid;c private.dpd_request_contexts%ROWTYPE;enabled boolean;
BEGIN SELECT * INTO f FROM private.dpd_original_intents WHERE original_path=_name;IF NOT FOUND THEN RETURN false;END IF;
 s:=private.dpd_scope(f.tenant_id,f.setup_id,_write);actor:=auth.uid();
 IF f.created_by IS DISTINCT FROM actor OR NOT private.dpd_original_viewable(f.id) OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN RETURN false;END IF;
 -- Storage APIs cannot accept purpose RPC arguments. Require the actual current
 -- ordinary subject and a recent fixed-server authorization for this setup;
 -- never accept caller headers/GUC/IP as an attestation.
 SELECT * INTO c FROM private.dpd_request_contexts x WHERE x.tenant_id=f.tenant_id AND x.setup_id=f.setup_id AND x.actor_id=actor AND x.operation IN('original.claim','original.authorize','original.read') AND x.expires_at>clock_timestamp() AND x.verified_subject->>'exp'=auth.jwt()->>'exp' AND x.verified_subject->>'aal'=auth.jwt()->>'aal' ORDER BY x.created_at DESC,x.id DESC LIMIT 1;
 IF NOT FOUND THEN RETURN false;END IF;PERFORM private.dpd_peer_actor(f.tenant_id,c.verified_subject);
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=f.tenant_id;
 IF NOT FOUND OR enabled IS NULL OR (enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(f.tenant_id,host(c.request_ip)) IS DISTINCT FROM true)) THEN RETURN false;END IF;
 RETURN NOT _write OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id);
END $function$

CREATE OR REPLACE FUNCTION private.dpd_parser_state(_file uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE phase text;
BEGIN
 IF EXISTS(SELECT 1 FROM private.dpd_schema_receipts WHERE file_id=_file) THEN RETURN 'ready';END IF;
 SELECT e.phase INTO phase FROM private.dpd_parser_jobs j JOIN LATERAL(SELECT x.phase,x.created_at,x.id FROM private.dpd_parser_events x WHERE x.job_id=j.id ORDER BY x.created_at DESC,x.id DESC LIMIT 1) e ON true WHERE j.file_id=_file ORDER BY j.created_at DESC,j.id DESC LIMIT 1;
 RETURN CASE WHEN phase='queued' THEN 'queued' WHEN phase='running' THEN 'parsing' WHEN phase IN('failed','cancelled') THEN 'failed' ELSE 'unparsed' END;
END $function$

CREATE OR REPLACE FUNCTION public.dpd_enqueue_original_parser(_tenant_id uuid, _setup_id uuid, _file_id uuid, _parser_binding jsonb, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'parser.enqueue',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);f private.dpd_original_intents%ROWTYPE;j private.dpd_parser_jobs%ROWTYPE;
BEGIN
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=s.id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR _request_key IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) OR NOT private.dpd_original_viewable(f.id) OR jsonb_typeof(_parser_binding) IS DISTINCT FROM 'object' OR _parser_binding->>'original_sha256' IS DISTINCT FROM f.content_sha256 OR nullif(_parser_binding->>'parser_version','') IS NULL THEN RAISE EXCEPTION 'dpd.exact_received_original_parser_binding_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO j FROM private.dpd_parser_jobs WHERE file_id=f.id AND request_key=_request_key;
 IF FOUND THEN IF j.parser_binding IS DISTINCT FROM _parser_binding THEN RAISE EXCEPTION 'dpd.parser_request_conflict' USING ERRCODE='PT409';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'job_id',j.id,'state',(SELECT e.phase FROM private.dpd_parser_events e WHERE e.job_id=j.id ORDER BY e.created_at DESC,e.id DESC LIMIT 1),'request_replay',true);END IF;
 IF EXISTS(SELECT 1 FROM private.dpd_parser_jobs prior CROSS JOIN LATERAL(SELECT e.phase FROM private.dpd_parser_events e WHERE e.job_id=prior.id ORDER BY e.created_at DESC,e.id DESC LIMIT 1) head WHERE prior.file_id=f.id AND head.phase IN('queued','running')) THEN RAISE EXCEPTION 'dpd.original_parser_already_queued' USING ERRCODE='PT409';END IF;
 INSERT INTO private.dpd_parser_jobs(tenant_id,setup_id,file_id,request_key,created_by,parser_binding,parser_binding_sha256) VALUES(_tenant_id,s.id,f.id,_request_key,actor,_parser_binding,private.dpw_hash(_parser_binding)) RETURNING * INTO j;
 INSERT INTO private.dpd_parser_events(job_id,actor_id,phase,progress) VALUES(j.id,actor,'queued',jsonb_build_object('parsed_rows','0','actual_count_available',false));
 PERFORM private.dpd_event(_tenant_id,s.id,actor,'original.parser.queued',j.id,jsonb_build_object('file_id',f.id,'original_sha256',f.content_sha256,'parser_binding_sha256',j.parser_binding_sha256,'publish_allowed',false));
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'job_id',j.id,'state','queued','request_replay',false);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_claim_original_parser(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _lease_seconds integer, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'parser.claim',_request_context_id,_verified_subject);j private.dpd_parser_jobs%ROWTYPE;e private.dpd_parser_events%ROWTYPE;until_at timestamptz;
BEGIN
 SELECT * INTO j FROM private.dpd_parser_jobs WHERE id=_job_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR j.created_by<>actor OR _claim_key IS NULL OR _lease_seconds NOT BETWEEN 1 AND 60 OR NOT private.dpd_original_viewable(j.file_id) THEN RAISE EXCEPTION 'dpd.parser_current_owned_claim_required' USING ERRCODE='42501';END IF;
 SELECT * INTO e FROM private.dpd_parser_events WHERE job_id=j.id ORDER BY created_at DESC,id DESC LIMIT 1;
 IF e.phase IN('completed','failed','cancelled') OR (e.phase='running' AND e.lease_expires_at>clock_timestamp()) THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'job_id',j.id,'file_id',j.file_id,'claimed',false,'state',e.phase,'claim_key',e.claim_key,'lease_expires_at',e.lease_expires_at);END IF;
 until_at:=least(clock_timestamp()+_lease_seconds*interval '1 second',to_timestamp((_verified_subject->>'exp')::double precision));INSERT INTO private.dpd_parser_events(job_id,actor_id,phase,claim_key,lease_expires_at,progress) VALUES(j.id,actor,'running',_claim_key,until_at,e.progress);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'job_id',j.id,'file_id',j.file_id,'claimed',true,'state','running','claim_key',_claim_key,'lease_expires_at',until_at,'parser_binding',j.parser_binding,'original',private.dpd_original_result(actor,j.file_id,false));
END $function$

CREATE OR REPLACE FUNCTION public.dpd_record_parser_progress(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _phase text, _progress jsonb, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'parser.progress',_request_context_id,_verified_subject);j private.dpd_parser_jobs%ROWTYPE;e private.dpd_parser_events%ROWTYPE;
BEGIN SELECT * INTO j FROM private.dpd_parser_jobs WHERE id=_job_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;SELECT * INTO e FROM private.dpd_parser_events WHERE job_id=j.id ORDER BY created_at DESC,id DESC LIMIT 1;
 IF j.id IS NULL OR j.created_by<>actor OR e.phase<>'running' OR e.claim_key<>_claim_key OR e.lease_expires_at<=clock_timestamp() OR _phase NOT IN('running','completed','failed','cancelled') OR jsonb_typeof(_progress) IS DISTINCT FROM 'object' OR (_phase='completed' AND NOT EXISTS(SELECT 1 FROM private.dpd_schema_receipts WHERE file_id=j.file_id)) THEN RAISE EXCEPTION 'dpd.actual_parser_claim_outcome_required' USING ERRCODE='PT409';END IF;
 IF NOT private.dpd_original_viewable(j.file_id) THEN RAISE EXCEPTION 'dpd.parser_original_expired' USING ERRCODE='42501';END IF;
 INSERT INTO private.dpd_parser_events(job_id,actor_id,phase,claim_key,lease_expires_at,progress) VALUES(j.id,actor,_phase,_claim_key,CASE WHEN _phase='running' THEN least(clock_timestamp()+interval '60 seconds',to_timestamp((_verified_subject->>'exp')::double precision)) ELSE e.lease_expires_at END,_progress) RETURNING * INTO e;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'job_id',j.id,'file_id',j.file_id,'state',_phase,'progress',_progress,'claim_key',e.claim_key,'lease_expires_at',e.lease_expires_at,'publish_allowed',false);END $function$

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_actor(_tenant uuid, _recon uuid, _action text, _checker boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE actor uuid:=auth.uid(); m public.tenant_members%ROWTYPE; policy public.tenant_security_settings%ROWTYPE;
BEGIN
 IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN
  RAISE EXCEPTION 'authenticated ordinary actor required' USING ERRCODE='42501';
 END IF;
 SELECT * INTO m FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=actor AND active FOR SHARE;
 IF NOT FOUND THEN PERFORM private.mapped_recon_governance_conflict('current_membership_required'); END IF;
 IF _checker AND m.role::text<>'tenant_admin' THEN PERFORM private.mapped_recon_governance_conflict('current_checker_authority_required'); END IF;
 IF NOT private.recon_authoritative_access_decision_as(actor,_recon,_action) THEN
  PERFORM private.mapped_recon_governance_conflict(CASE WHEN _checker THEN 'current_approve_authority_required' ELSE 'current_edit_authority_required' END);
 END IF;
 SELECT * INTO policy FROM public.tenant_security_settings WHERE tenant_id=_tenant FOR SHARE;
 IF FOUND AND policy.mfa_required AND auth.jwt()->>'aal' IS DISTINCT FROM 'aal2' THEN
  PERFORM private.mapped_recon_governance_conflict('mfa_assurance_required');
 END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.dpd_append_original_chunk(_tenant_id uuid, _setup_id uuid, _file_id uuid, _sheet_key text, _chunk_index integer, _start_row bigint, _rows jsonb, _request_key uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'original.chunk',(_verified_subject->>'request_context_id')::uuid,_verified_subject);f private.dpd_original_intents%ROWTYPE;c private.dpd_original_chunks%ROWTYPE;expected bigint;
BEGIN
 PERFORM private.dpd_assert_parser_lease(_file_id,actor);
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) OR NOT private.dpd_original_viewable(f.id) OR _request_key IS NULL OR _sheet_key IS NULL OR _chunk_index<0 OR _start_row<0 OR jsonb_typeof(_rows) IS DISTINCT FROM 'array' OR jsonb_array_length(_rows) NOT BETWEEN 1 AND 1000 OR octet_length(_rows::text)>1048576 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_rows) row WHERE jsonb_typeof(row) IS DISTINCT FROM 'array' OR jsonb_array_length(row)>500 OR EXISTS(SELECT 1 FROM jsonb_array_elements(row) cell WHERE jsonb_typeof(cell) IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'dpd.bounded_actual_chunk_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO c FROM private.dpd_original_chunks WHERE file_id=f.id AND request_key=_request_key;
 IF FOUND THEN IF c.sheet_key<>_sheet_key OR c.chunk_index<>_chunk_index OR c.start_row<>_start_row OR c.rows IS DISTINCT FROM _rows THEN RAISE EXCEPTION 'dpd.chunk_request_conflict' USING ERRCODE='PT409';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'file_id',f.id,'sheet_key',c.sheet_key,'chunk_index',c.chunk_index,'start_row',c.start_row::text,'row_count',c.row_count,'rows_sha256',c.rows_sha256,'request_replay',true);END IF;
 IF EXISTS(SELECT 1 FROM private.dpd_schema_receipts WHERE file_id=f.id) THEN RAISE EXCEPTION 'dpd.immutable_schema_already_finished' USING ERRCODE='PT409';END IF;
 SELECT coalesce(max(start_row+row_count),0) INTO expected FROM private.dpd_original_chunks WHERE file_id=f.id AND sheet_key=_sheet_key;
 IF _start_row<>expected OR _chunk_index<>(SELECT count(*) FROM private.dpd_original_chunks WHERE file_id=f.id AND sheet_key=_sheet_key) OR (SELECT coalesce(sum(row_count),0) FROM private.dpd_original_chunks WHERE file_id=f.id)+jsonb_array_length(_rows)>1000200 OR (SELECT coalesce(sum(octet_length(rows::text)),0) FROM private.dpd_original_chunks WHERE file_id=f.id)+octet_length(_rows::text)>52428800 THEN RAISE EXCEPTION 'dpd.contiguous_bounded_source_ordinals_required' USING ERRCODE='PT409';END IF;
 INSERT INTO private.dpd_original_chunks(file_id,sheet_key,chunk_index,start_row,row_count,rows,rows_sha256,request_key,created_by) VALUES(f.id,_sheet_key,_chunk_index,_start_row,jsonb_array_length(_rows),_rows,private.dpw_hash(_rows),_request_key,actor) RETURNING * INTO c;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'file_id',f.id,'sheet_key',c.sheet_key,'chunk_index',c.chunk_index,'start_row',c.start_row::text,'row_count',c.row_count,'rows_sha256',c.rows_sha256,'request_replay',false);
END $function$

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_request_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE purpose text;
BEGIN
 IF OLD.mapped_governance_version IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='DELETE' THEN PERFORM private.mapped_recon_governance_conflict('native_request_history_immutable'); END IF;
 purpose:=CASE WHEN OLD.request_kind='edit' THEN 'edit_decision' ELSE 'promotion_decision' END;
 IF NOT private.mapped_recon_governance_transition(OLD.id,purpose)
 OR (to_jsonb(OLD)-ARRAY['status','decision_reason','decided_by','decided_at','staging_definition_id'])
 IS DISTINCT FROM (to_jsonb(NEW)-ARRAY['status','decision_reason','decided_by','decided_at','staging_definition_id']) THEN
  PERFORM private.mapped_recon_governance_conflict('native_request_snapshot_immutable');
 END IF;
 IF OLD.status='pending' THEN
  IF NEW.status NOT IN ('approved','rejected') OR NEW.decided_by IS DISTINCT FROM auth.uid()
   OR NEW.decided_by=OLD.requested_by OR NEW.staging_definition_id IS DISTINCT FROM OLD.staging_definition_id THEN
   PERFORM private.mapped_recon_governance_conflict('native_decision_shape_required');
  END IF;
 ELSIF NOT (OLD.status='approved' AND OLD.request_kind='edit' AND OLD.staging_definition_id IS NULL
  AND NEW.staging_definition_id IS NOT NULL AND to_jsonb(OLD)-'staging_definition_id'=to_jsonb(NEW)-'staging_definition_id') THEN
  PERFORM private.mapped_recon_governance_conflict('request_stale_or_replayed');
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.dpd_finish_original_schema(_tenant_id uuid, _setup_id uuid, _file_id uuid, _schema_manifest jsonb, _request_key uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'original.schema',(_verified_subject->>'request_context_id')::uuid,_verified_subject);f private.dpd_original_intents%ROWTYPE;r private.dpd_schema_receipts%ROWTYPE;sheet jsonb;actual bigint;total bigint:=0;columns integer;
BEGIN
 PERFORM private.dpd_assert_parser_lease(_file_id,actor);
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=_setup_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND OR f.created_by<>actor OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) OR NOT private.dpd_original_viewable(f.id) OR _request_key IS NULL OR jsonb_typeof(_schema_manifest) IS DISTINCT FROM 'object' OR _schema_manifest->>'content_sha256' IS DISTINCT FROM f.content_sha256 OR jsonb_typeof(_schema_manifest->'sheet_inventory') IS DISTINCT FROM 'array' OR jsonb_array_length(_schema_manifest->'sheet_inventory') NOT BETWEEN 1 AND 200 OR jsonb_typeof(_schema_manifest->'header_fields') IS DISTINCT FROM 'array' OR jsonb_array_length(_schema_manifest->'header_fields') NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'dpd.actual_original_schema_manifest_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO r FROM private.dpd_schema_receipts WHERE file_id=f.id;
 IF FOUND THEN IF r.schema_manifest IS DISTINCT FROM _schema_manifest OR r.request_key<>_request_key THEN RAISE EXCEPTION 'dpd.schema_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpd_original_result(actor,f.id,true);END IF;
 IF (SELECT count(DISTINCT value->>'sheet_key') FROM jsonb_array_elements(_schema_manifest->'sheet_inventory'))<>jsonb_array_length(_schema_manifest->'sheet_inventory') THEN RAISE EXCEPTION 'dpd.duplicate_sheet_key' USING ERRCODE='PT409';END IF;
 FOR sheet IN SELECT value FROM jsonb_array_elements(_schema_manifest->'sheet_inventory') LOOP
  SELECT coalesce(sum(row_count),0) INTO actual FROM private.dpd_original_chunks WHERE file_id=f.id AND sheet_key=sheet->>'sheet_key';
  IF coalesce(sheet->>'raw_row_count','')!~'^(0|[1-9][0-9]*)$' OR (sheet->>'raw_row_count')::bigint<>actual OR actual>1000200 OR jsonb_typeof(sheet->'header_fields') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.complete_sheet_count_header_required' USING ERRCODE='PT409';END IF;total:=total+actual;
 END LOOP;
 IF EXISTS(SELECT 1 FROM private.dpd_original_chunks c WHERE c.file_id=f.id AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_schema_manifest->'sheet_inventory') AS si(value) WHERE si.value->>'sheet_key'=c.sheet_key)) OR total>1000200 THEN RAISE EXCEPTION 'dpd.all_actual_sheet_chunks_required' USING ERRCODE='PT409';END IF;
 INSERT INTO private.dpd_schema_receipts(file_id,setup_id,tenant_id,created_by,schema_manifest,schema_sha256,raw_row_count,request_key) VALUES(f.id,_setup_id,_tenant_id,actor,_schema_manifest,private.dpw_hash(_schema_manifest),total,_request_key);
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'original.schema.complete',f.id,jsonb_build_object('schema_sha256',private.dpw_hash(_schema_manifest),'raw_row_count',total::text,'header_fields_provenance','actual_original_parser_inferred_not_human_strict_types'));RETURN private.dpd_original_result(actor,f.id,false);
END $function$

CREATE OR REPLACE FUNCTION private.mapped_recon_governance_run(_new recon_runs)
 RETURNS recon_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE d public.recon_definitions%ROWTYPE;
BEGIN
 SELECT * INTO d FROM public.recon_definitions WHERE tenant_id=_new.tenant_id AND id=_new.definition_id FOR SHARE;
 IF NOT FOUND OR _new.run_by IS DISTINCT FROM auth.uid() THEN PERFORM private.mapped_recon_governance_conflict('native_run_actor_or_tenant_mismatch'); END IF;
 PERFORM private.mapped_recon_governance_actor(d.tenant_id,d.id,'run',false);
 IF NOT private.recon_authoritative_access_decision_as(auth.uid(),d.id,'read') THEN PERFORM private.mapped_recon_governance_conflict('native_current_read_required'); END IF;
 IF NOT ((d.environment='production' AND d.status='active' AND d.governance_state IN ('approved_locked','edit_request_pending'))
 OR (d.environment='development' AND d.governance_state='development_draft')
 OR (d.environment='staging' AND d.governance_state='staging_copy')) THEN
  PERFORM private.mapped_recon_governance_conflict('native_run_governance_not_ready');
 END IF;
 -- Retain the actual native approved revision/independent runner contract.
 PERFORM private.recon_run_bound_approved_version(_new.tenant_id,_new.definition_id,_new.run_by);
 RETURN _new;
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_get_dataset(_tenant_id uuid, _setup_id uuid, _dataset_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.dataset.read',_request_context_id);d private.dpdi_published_datasets%ROWTYPE;
BEGIN
 SELECT * INTO d FROM private.dpdi_published_datasets WHERE id=_dataset_id AND tenant_id=_tenant_id AND setup_id=_setup_id;
 IF NOT FOUND OR private.data_prep_pipeline_scope_allows(actor,_tenant_id,d.pipeline_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,d.data_source_id,'view') IS DISTINCT FROM true OR EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=d.job_id AND private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dpdi.current_published_dataset_source_reader_required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'dataset',private.dpdi_dataset_dto(d),'payload_available',NOT EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=d.job_id AND NOT private.dpd_original_viewable(i.original_file_id)));
END $function$

CREATE OR REPLACE FUNCTION public.dpd_read_original_rows(_tenant_id uuid, _setup_id uuid, _file_id uuid, _sheet_key text, _start_row bigint, _page_size integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'original.rows',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;sheet jsonb;state text;rows jsonb;total bigint;header jsonb;inventory jsonb;
BEGIN
 IF _start_row<0 OR _page_size NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'dpd.invalid_original_page' USING ERRCODE='22023';END IF;
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=s.id AND tenant_id=_tenant_id;IF NOT FOUND THEN RAISE EXCEPTION 'dpd.original_row_scope_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT value INTO sheet FROM jsonb_array_elements(coalesce(sc.schema_manifest->'sheet_inventory','[]')) WHERE value->>'sheet_key'=_sheet_key;
 state:=CASE WHEN EXISTS(SELECT 1 FROM private.dpd_original_tombstones WHERE file_id=f.id) THEN 'tombstoned' WHEN f.expires_at<=clock_timestamp() THEN 'expired' WHEN NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) THEN 'unavailable' WHEN sc.file_id IS NULL THEN 'parser_pending' WHEN sheet IS NULL THEN 'schema_pending' ELSE 'available' END;
 IF state='available' THEN
  total:=(sheet->>'raw_row_count')::bigint;header:=sheet->'header_fields';inventory:=sc.schema_manifest->'sheet_inventory';
  SELECT coalesce(jsonb_agg(jsonb_build_object('source_row_ordinal',q.ordinal::text,'cells',q.cells,'row_sha256',private.dpw_hash(q.cells)) ORDER BY q.ordinal),'[]') INTO rows FROM(SELECT c.start_row+v.ordinality-1 ordinal,v.value cells FROM private.dpd_original_chunks c CROSS JOIN LATERAL jsonb_array_elements(c.rows) WITH ORDINALITY v WHERE c.file_id=f.id AND c.sheet_key=_sheet_key AND c.start_row<_start_row+_page_size AND c.start_row+c.row_count>_start_row AND c.start_row+v.ordinality-1>=_start_row AND c.start_row+v.ordinality-1<_start_row+_page_size ORDER BY ordinal) q;
 END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'content_sha256',f.content_sha256,'state',state,'rows',rows,'total_raw_rows',total::text,'header_fields',header,'sheet_inventory',coalesce(inventory,'[]'),
 'has_more',CASE WHEN state='available' THEN _start_row+_page_size<total ELSE NULL END,'start_row',_start_row::text,'page_size',_page_size,'retention',f.retention_policy||jsonb_build_object('expires_at',f.expires_at,'legal_hold',private.dpd_original_has_hold(f.id)));
END $function$

CREATE OR REPLACE FUNCTION private.dpd_selected_input(_file uuid, _selection jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;sheet jsonb;headers jsonb;start_at bigint;header_at bigint;cells jsonb;amount bigint;
BEGIN SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file;SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;
 IF NOT FOUND OR NOT private.dpd_original_viewable(f.id) OR _selection->>'schema_sha256' IS DISTINCT FROM sc.schema_sha256 THEN RAISE EXCEPTION 'dpd.current_received_schema_selection_required' USING ERRCODE='PT409';END IF;
 SELECT value INTO sheet FROM jsonb_array_elements(sc.schema_manifest->'sheet_inventory') WHERE value->>'sheet_key'=_selection->>'sheet_key';
 IF sheet IS NULL OR coalesce(_selection->>'header_row_index','')!~'^(0|[1-9][0-9]*)$' OR coalesce(_selection->>'data_start_row','')!~'^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'dpd.explicit_actual_header_selection_required' USING ERRCODE='PT409';END IF;
 header_at:=(_selection->>'header_row_index')::bigint;start_at:=(_selection->>'data_start_row')::bigint;
 SELECT c.rows->((header_at-c.start_row)::integer) INTO cells FROM private.dpd_original_chunks c WHERE c.file_id=f.id AND c.sheet_key=sheet->>'sheet_key' AND c.start_row<=header_at AND c.start_row+c.row_count>header_at;
 IF cells IS NULL OR jsonb_array_length(cells) NOT BETWEEN 1 AND 500 OR start_at<=header_at OR start_at>(sheet->>'raw_row_count')::bigint THEN RAISE EXCEPTION 'dpd.actual_data_range_required' USING ERRCODE='PT409';END IF;
 SELECT jsonb_agg(jsonb_build_object('ordinal',h.ordinality-1,'name',h.value,'observed_representation','text','strict_json_type_inferred',false) ORDER BY h.ordinality) INTO headers FROM jsonb_array_elements_text(cells) WITH ORDINALITY h;
 IF (SELECT count(DISTINCT value->>'name') FROM jsonb_array_elements(headers))<>jsonb_array_length(headers) OR EXISTS(SELECT 1 FROM jsonb_array_elements(headers) h WHERE coalesce(h->>'name','')='' OR coalesce(h->>'ordinal','')!~'^(0|[1-9][0-9]*)$') THEN RAISE EXCEPTION 'dpd.unique_confirmed_header_fields_required' USING ERRCODE='PT409';END IF;
 amount:=(sheet->>'raw_row_count')::bigint-start_at;IF amount>1000000 THEN RAISE EXCEPTION 'dpd.selected_data_row_budget_exceeded' USING ERRCODE='PT409';END IF;
 -- Metadata only: exact immutable original/schema/selection pins. Processing reads bounded pages. No whole-original JSON array or counterfeit upload rows.

 RETURN jsonb_build_object('file_id',f.id,'sheet_key',sheet->>'sheet_key','header_fields',headers,'data_start_row',start_at::text,'row_count',amount::text,'input_pin_sha256',private.dpw_hash(jsonb_build_object('original_sha256',f.content_sha256,'schema_sha256',sc.schema_sha256,'selection',_selection)),'schema_sha256',sc.schema_sha256,'selection_sha256',private.dpw_hash(_selection),'original_sha256',f.content_sha256,'size_bytes',f.size_bytes::text,'storage_bucket',f.storage_bucket,'original_path',f.original_path,'created_by',f.created_by);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_register_received_source(_tenant_id uuid, _setup_id uuid, _file_id uuid, _source_request_key uuid, _ownership_request_key uuid, _reason text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'source.register',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;v private.dpd_versions%ROWTYPE;l private.dpd_raw_source_links%ROWTYPE;source jsonb;selection jsonb;input jsonb;sheet jsonb;source_id uuid;
BEGIN
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=_file_id AND setup_id=s.id AND tenant_id=_tenant_id FOR UPDATE;SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 IF f.id IS NULL OR sc.file_id IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) OR NOT private.dpd_original_viewable(f.id) OR _source_request_key IS NULL OR _ownership_request_key IS NULL THEN RAISE EXCEPTION 'dpd.received_schema_before_raw_source_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO l FROM private.dpd_raw_source_links WHERE file_id=f.id;
 IF FOUND THEN IF l.source_request_key<>_source_request_key OR l.ownership_request_key<>_ownership_request_key THEN RAISE EXCEPTION 'dpd.source_request_conflict' USING ERRCODE='PT409';END IF;IF private.dpw_source_allows(actor,_tenant_id,l.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.current_raw_source_denied' USING ERRCODE='42501';END IF;RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'data_source_id',l.data_source_id,'request_replay',true);END IF;
 SELECT value INTO sheet FROM jsonb_array_elements(sc.schema_manifest->'sheet_inventory') WHERE value->>'sheet_key'=coalesce(f.descriptor->>'selected_sheet',sc.schema_manifest->'sheet_inventory'->0->>'sheet_key');
 IF sheet IS NULL THEN RAISE EXCEPTION 'dpd.actual_selected_sheet_required' USING ERRCODE='PT409';END IF;
 IF jsonb_typeof(sheet->'header_fields') IS DISTINCT FROM 'array' OR jsonb_array_length(sheet->'header_fields') NOT BETWEEN 1 AND 500 OR coalesce(sheet->>'raw_row_count','')!~'^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'dpd.actual_raw_schema_metadata_required' USING ERRCODE='PT409';END IF;
 input:=jsonb_build_object('header_fields',sheet->'header_fields','row_count',sheet->>'raw_row_count','row_count_basis','raw_records_including_headers');
 source:=public.ssb_create_source(_tenant_id,nullif(s.input->>'bu_id','')::uuid,left((s.input->>'title')||' '||f.feed_key,80),'Original received under authoring setup '||s.id::text,CASE WHEN f.descriptor->>'format'='xlsx' THEN 'xlsx' ELSE 'csv' END,_source_request_key);source_id:=(source->'source'->>'id')::uuid;IF (source->>'is_new')::boolean IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.new_raw_source_request_required_no_existing_source_rewrite' USING ERRCODE='PT409';END IF;
 -- Within this one transaction the newly created SSB draft gets its ACTUAL
 -- received schema/count. No observable fake empty received-source row.
 UPDATE public.workspace_data_sources SET inferred_schema=input->'header_fields',row_count=(input->>'row_count')::integer,status='ready',connection_config=connection_config||jsonb_build_object('authoring_original_file_id',f.id,'schema_sha256',sc.schema_sha256,'row_count_basis','raw_records_including_headers','schema_provenance','actual_parser_representation_hint_not_confirmed_output_types'),updated_at=clock_timestamp() WHERE id=source_id AND tenant_id=_tenant_id AND created_by=actor;
 PERFORM public.ssb_save_ownership(_tenant_id,source_id,v.owner_bu_ids,'{}'::uuid[],_reason,_ownership_request_key);
 IF private.dpw_source_allows(actor,_tenant_id,source_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,source_id,'ingest') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.actual_registered_source_binding_required' USING ERRCODE='42501';END IF;
 INSERT INTO private.dpd_raw_source_links(file_id,setup_id,tenant_id,data_source_id,source_request_key,ownership_request_key,created_by) VALUES(f.id,s.id,_tenant_id,source_id,_source_request_key,_ownership_request_key,actor);
 PERFORM private.dpd_event(_tenant_id,s.id,actor,'original.source.registered',source_id,jsonb_build_object('file_id',f.id,'original_sha256',f.content_sha256,'actual_rows',input->>'row_count','inferred_fields_not_human_strict_json_types',true));RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'file_id',f.id,'data_source_id',source_id,'request_replay',false);
END $function$

CREATE OR REPLACE FUNCTION private.dpd_preview_result(_actor uuid, _link private.dpd_preview_links)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE b public.data_prep_delivery_batches%ROWTYPE;
BEGIN SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=_link.batch_id;
 RETURN jsonb_build_object('actor_id',_actor,'tenant_id',_link.tenant_id,'setup_id',_link.setup_id,'draft_version',_link.draft_version,'pipeline_id',_link.pipeline_id,'configuration_id',_link.configuration_id,'pipeline_version',_link.pipeline_version,'batch_id',_link.batch_id,'mode','preview','execution_mode',b.execution_mode,'human_in_loop',b.human_in_loop,'input_manifest',_link.input_manifest,'input_manifest_sha256',_link.input_manifest_sha256,'source_reupload_performed',false,'publish_allowed',false,'input_binding_kind','authoring_original_pinned','existing_dpw_input_file_contract_reused',false,'confirmed_mapping',(SELECT v.payload->'confirmed_mapping' FROM private.dpd_versions v WHERE v.setup_id=_link.setup_id AND v.version=_link.draft_version),'confirmed_mapping_sha256',(SELECT private.dpw_hash(v.payload->'confirmed_mapping') FROM private.dpd_versions v WHERE v.setup_id=_link.setup_id AND v.version=_link.draft_version),'configuration_request_key',_link.configuration_request_key,'delivery_request_key',_link.delivery_request_key,'input_bindings',coalesce((SELECT jsonb_agg(jsonb_build_object('input_id',i.id,'original_file_id',i.original_file_id,'feed_key',i.feed_key,'data_source_id',i.data_source_id,'selection_sha256',i.selection_sha256,'rows_count',i.rows_count::text,'binding_kind','authoring_original_pinned','dpw_file_id',NULL,'upload_id',NULL) ORDER BY i.feed_key,i.id) FROM private.dpd_preview_file_links i WHERE i.setup_id=_link.setup_id AND i.draft_version=_link.draft_version),'[]'));
