CREATE OR REPLACE FUNCTION public.dpd_bind_setup_preview(_tenant_id uuid, _setup_id uuid, _draft_version integer, _configuration_request_key uuid, _delivery_request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.bind',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);v private.dpd_versions%ROWTYPE;l private.dpd_preview_links%ROWTYPE;prior private.dpd_preview_links%ROWTYPE;feed jsonb;linked private.dpd_raw_source_links%ROWTYPE;native jsonb;delivery jsonb;manifest jsonb:='[]';input jsonb;newfeeds jsonb:='[]';payload jsonb;amount bigint;item jsonb;bound private.dpd_preview_file_links%ROWTYPE;declared jsonb;ref jsonb;
BEGIN
 PERFORM 1 FROM private.dpd_setups WHERE id=s.id FOR UPDATE;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 IF v.version<>_draft_version OR _configuration_request_key IS NULL OR _delivery_request_key IS NULL THEN RAISE EXCEPTION 'dpd.current_draft_version_required' USING ERRCODE='PT409';END IF;
 PERFORM private.dpd_validate_confirmed_mapping(_tenant_id,s.id,v.version,v.payload->'confirmed_mapping');
 IF (v.payload ? 'sharing_user_group_ids' AND private.dps_ids(ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(v.payload->'sharing_user_group_ids')),100,false) IS DISTINCT FROM private.dps_ids(v.group_ids,100,false)) OR (v.payload ? 'owning_business_unit_ids' AND private.dps_ids(ARRAY(SELECT value::uuid FROM jsonb_array_elements_text(v.payload->'owning_business_unit_ids')),100,true) IS DISTINCT FROM private.dps_ids(v.owner_bu_ids,100,true)) THEN RAISE EXCEPTION 'dpd.authoritative_scope_revision_required_preserve_history' USING ERRCODE='PT409';END IF;

 SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=v.version;
 IF FOUND THEN IF l.configuration_request_key<>_configuration_request_key OR l.delivery_request_key<>_delivery_request_key THEN RAISE EXCEPTION 'dpd.preview_request_conflict' USING ERRCODE='PT409';END IF;PERFORM private.dpw_authorize(_tenant_id,l.pipeline_id,'run');RETURN private.dpd_preview_result(actor,l);END IF;
 IF jsonb_typeof(v.payload->'feeds') IS DISTINCT FROM 'array' OR jsonb_array_length(v.payload->'feeds')=0 THEN RAISE EXCEPTION 'dpd.full_received_feed_configuration_required' USING ERRCODE='PT409';END IF;
 FOR feed IN SELECT value FROM jsonb_array_elements(v.payload->'feeds') LOOP
  SELECT x.value INTO declared FROM jsonb_array_elements(v.payload->'confirmed_mapping'->'feeds') AS x(value) WHERE x.value->>'key'=feed->>'key';
  IF declared IS NULL OR feed->'mappings' IS DISTINCT FROM declared->'mappings' THEN RAISE EXCEPTION 'dpd.pipeline_feed_confirmed_mapping_conflict' USING ERRCODE='PT409';END IF;
  newfeeds:=newfeeds||jsonb_build_array(feed||jsonb_build_object('data_source_id',declared->>'data_source_id'));
  FOR ref IN SELECT value FROM jsonb_array_elements(declared->'original_refs') LOOP
   SELECT * INTO linked FROM private.dpd_raw_source_links WHERE file_id=(ref->>'file_id')::uuid AND setup_id=s.id;
   IF NOT FOUND OR linked.data_source_id::text IS DISTINCT FROM declared->>'data_source_id' OR private.dpw_source_allows(actor,_tenant_id,linked.data_source_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,linked.data_source_id,'ingest') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.registered_current_original_source_required' USING ERRCODE='42501';END IF;
   input:=private.dpd_selected_input(linked.file_id,ref);
   manifest:=manifest||jsonb_build_array(input||jsonb_build_object('original',ref,'feed_key',feed->>'key','data_source_id',linked.data_source_id,'original_ref',ref,'configuration_sha256',v.payload_sha256,'original_storage_reupload',false));
  END LOOP;
 END LOOP;
 SELECT sum((m.value->>'row_count')::bigint) INTO amount FROM jsonb_array_elements(manifest) AS m(value);IF amount>1000000 THEN RAISE EXCEPTION 'dpd.preview_selected_cohort_row_budget_exceeded' USING ERRCODE='PT409';END IF;
 SELECT * INTO prior FROM private.dpd_preview_links WHERE setup_id=s.id ORDER BY draft_version DESC LIMIT 1;payload:=private.dpd_pipeline_payload(v.payload)||jsonb_build_object('feeds',newfeeds);
 native:=public.dps_save_configuration(_tenant_id,prior.pipeline_id,payload,v.owner_bu_ids,v.group_ids,_configuration_request_key,_request_context_id,_setup_id);
 delivery:=public.dpw_create_delivery(_tenant_id,(native->'pipeline'->>'id')::uuid,(s.input->>'business_date')::date,_delivery_request_key,NULL,'preview',NULL,s.input->>'execution_mode',(s.input->>'human_in_loop')::boolean);
 INSERT INTO private.dpd_preview_links(setup_id,draft_version,tenant_id,created_by,pipeline_id,configuration_id,pipeline_version,batch_id,configuration_request_key,delivery_request_key,input_manifest,input_manifest_sha256)
 VALUES(s.id,v.version,_tenant_id,actor,(native->'pipeline'->>'id')::uuid,(native->>'configuration_id')::uuid,(native->'pipeline'->>'version')::integer,(delivery->'batch'->>'id')::uuid,_configuration_request_key,_delivery_request_key,manifest,private.dpw_hash(manifest)) RETURNING * INTO l;
 FOR item IN SELECT value FROM jsonb_array_elements(manifest) LOOP
 INSERT INTO private.dpd_preview_file_links(setup_id,draft_version,original_file_id,data_source_id,feed_key,selection,selection_sha256,rows_count) VALUES(s.id,v.version,(item->>'file_id')::uuid,(item->>'data_source_id')::uuid,item->>'feed_key',item->'original_ref',item->>'selection_sha256',(item->>'row_count')::bigint);
 END LOOP;
 PERFORM private.dpd_event(_tenant_id,s.id,actor,'preview.configuration.bound',l.batch_id,jsonb_build_object('configuration_id',l.configuration_id,'draft_version',v.version,'input_manifest_sha256',l.input_manifest_sha256,'original_reupload',false,'publish_allowed',false));RETURN private.dpd_preview_result(actor,l);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_read_preview_input(_tenant_id uuid, _setup_id uuid, _draft_version integer, _input_id uuid, _start_row bigint, _page_size integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.input',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);l private.dpd_preview_links%ROWTYPE;i private.dpd_preview_file_links%ROWTYPE;meta jsonb;cells jsonb;rows jsonb;first_at bigint;total bigint;
BEGIN
 IF _start_row IS NULL OR _start_row<0 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'dpd.bounded_preview_input_page_required' USING ERRCODE='22023';END IF;
 SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=_draft_version AND tenant_id=_tenant_id;
 SELECT * INTO i FROM private.dpd_preview_file_links WHERE id=_input_id AND setup_id=s.id AND draft_version=l.draft_version;
 IF i.id IS NULL OR private.dpw_authorize(_tenant_id,l.pipeline_id,'view') IS DISTINCT FROM actor OR private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.preview_current_input_scope_denied' USING ERRCODE='42501';END IF;
 IF NOT private.dpd_original_viewable(i.original_file_id) THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'input_id',i.id,'state','unavailable','rows',NULL,'total',NULL,'has_more',NULL,'publish_allowed',false);END IF;
 meta:=private.dpd_selected_input(i.original_file_id,i.selection);first_at:=(meta->>'data_start_row')::bigint;total:=i.rows_count;
 SELECT coalesce(jsonb_agg(jsonb_build_object('record_index',(q.ordinal-first_at)::text,'source_row_ordinal',q.ordinal::text,'input_id',i.id,'original_file_id',i.original_file_id,'source_row_id',jsonb_build_array(i.original_file_id,i.selection->>'sheet_key',q.ordinal::text)::text,'values',q.record,'raw_cells',q.cells,'raw_row_sha256',private.dpw_hash(q.cells)) ORDER BY q.ordinal),'[]') INTO rows FROM (
 SELECT c.start_row+x.ordinality-1 ordinal,x.value cells,(SELECT jsonb_object_agg(h.value->>'name',coalesce(x.value->>((h.value->>'ordinal')::integer),'')) FROM jsonb_array_elements(meta->'header_fields') AS h(value)) record
 FROM private.dpd_original_chunks c CROSS JOIN LATERAL jsonb_array_elements(c.rows) WITH ORDINALITY AS x(value,ordinality)
 WHERE c.file_id=i.original_file_id AND c.sheet_key=i.selection->>'sheet_key' AND c.start_row<first_at+_start_row+_page_size AND c.start_row+c.row_count>first_at+_start_row AND c.start_row+x.ordinality-1>=first_at+_start_row AND c.start_row+x.ordinality-1<first_at+least(_start_row+_page_size,total)) q;
 IF octet_length(rows::text)>1048576 THEN RAISE EXCEPTION 'dpd.preview_page_byte_budget_exceeded_reduce_page' USING ERRCODE='22023';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'draft_version',l.draft_version,'pipeline_id',l.pipeline_id,'configuration_id',l.configuration_id,'batch_id',l.batch_id,'input_id',i.id,'original_file_id',i.original_file_id,'input_binding_kind','authoring_original_pinned','state','available','rows',rows,'total',total::text,'has_more',_start_row+_page_size<total,'input_manifest_sha256',l.input_manifest_sha256,'selection_sha256',i.selection_sha256,'mode','preview','publish_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION private.dpd_original_schema_pin(_tenant uuid, _setup uuid, _feed text, _ref jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;raw private.dpd_raw_source_links%ROWTYPE;meta jsonb;fields jsonb;sheet jsonb;
BEGIN
 SELECT * INTO f FROM private.dpd_original_intents WHERE id=(_ref->>'file_id')::uuid AND tenant_id=_tenant AND setup_id=_setup AND feed_key=_feed;
 SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT * INTO raw FROM private.dpd_raw_source_links WHERE file_id=f.id;
 IF f.id IS NULL OR sc.file_id IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id) THEN RAISE EXCEPTION 'dpd.actual_received_original_schema_required' USING ERRCODE='PT409';END IF;
 meta:=private.dpd_selected_input(f.id,_ref);SELECT x.value INTO sheet FROM jsonb_array_elements(sc.schema_manifest->'sheet_inventory') AS x(value) WHERE x.value->>'sheet_key'=_ref->>'sheet_key';
 SELECT jsonb_agg(jsonb_build_object('ordinal',(h.value->>'ordinal')::integer,'name',h.value->>'name','inferred_type','string','nullable',false) ORDER BY (h.value->>'ordinal')::integer) INTO fields FROM jsonb_array_elements(meta->'header_fields') AS h(value);
 -- Representation hints describe stored raw string cells, never human-approved
 -- strict JSON output types. Those are separately declared in confirmed_mapping.
 RETURN jsonb_build_object('file_id',f.id,'feed_key',f.feed_key,'original_request_key',f.request_key,'content_sha256',f.content_sha256,'storage_bucket',f.storage_bucket,'original_path',f.original_path,'schema_sha256',sc.schema_sha256,'sheet_key',_ref->>'sheet_key','header_row_index',_ref->>'header_row_index','data_start_row',_ref->>'data_start_row','total_raw_rows',sheet->>'raw_row_count','header_fields',fields,'data_source_id',raw.data_source_id);
END $function$

CREATE OR REPLACE FUNCTION private.dpd_validate_confirmed_mapping(_tenant uuid, _setup uuid, _version integer, _mapping jsonb, _for_execution boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE feed jsonb;ref jsonb;pin jsonb;field jsonb;rule jsonb;catalog jsonb:='[]';seen uuid[]:='{}';targets text[];headers text[];actor uuid:=auth.uid();key text;target text;type_name text;rule_fields text[];
BEGIN
 IF jsonb_typeof(_mapping) IS DISTINCT FROM 'object' OR _mapping->>'protocol' IS DISTINCT FROM 'data_prep_draft_confirmed_mapping_v1' OR _mapping->>'tenant_id' IS DISTINCT FROM _tenant::text OR _mapping->>'setup_id' IS DISTINCT FROM _setup::text OR (_mapping->>'draft_version')::integer IS DISTINCT FROM _version OR _mapping->>'on_failure' IS DISTINCT FROM 'block' OR _mapping->'preserve_extras' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(_mapping->'feeds') IS DISTINCT FROM 'array' OR jsonb_array_length(_mapping->'feeds') NOT BETWEEN 1 AND 50 OR jsonb_typeof(_mapping->'output_schema') IS DISTINCT FROM 'array' OR jsonb_array_length(_mapping->'output_schema') NOT BETWEEN 1 AND 500 OR jsonb_typeof(_mapping->'quality_rules') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'dpd.full_explicit_confirmed_mapping_required' USING ERRCODE='PT409';END IF;
 IF (SELECT count(DISTINCT x.value->>'name') FROM jsonb_array_elements(_mapping->'output_schema') AS x(value))<>jsonb_array_length(_mapping->'output_schema') OR (SELECT count(DISTINCT x.value->>'key') FROM jsonb_array_elements(_mapping->'feeds') AS x(value))<>jsonb_array_length(_mapping->'feeds') THEN RAISE EXCEPTION 'dpd.duplicate_confirmed_field_feed' USING ERRCODE='PT409';END IF;
 FOR field IN SELECT value FROM jsonb_array_elements(_mapping->'output_schema') LOOP
  IF length(coalesce(field->>'name','')) NOT BETWEEN 1 AND 120 OR field->>'name' IN('extras_json','__proto__','constructor','prototype') OR field->>'name' IS DISTINCT FROM btrim(field->>'name') OR (field->>'type' IN('string','number','integer','date','boolean','json')) IS DISTINCT FROM true OR jsonb_typeof(field->'required') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'dpd.explicit_confirmed_output_field_required' USING ERRCODE='PT409';END IF;
 END LOOP;
 FOR feed IN SELECT value FROM jsonb_array_elements(_mapping->'feeds') LOOP
  IF length(coalesce(feed->>'key','')) NOT BETWEEN 1 AND 120 OR jsonb_typeof(feed->'original_refs') IS DISTINCT FROM 'array' OR jsonb_array_length(feed->'original_refs')=0 OR jsonb_typeof(feed->'mappings') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'dpd.complete_mapping_feed_required' USING ERRCODE='PT409';END IF;
  SELECT array_agg(x.value) INTO targets FROM jsonb_each_text(feed->'mappings') AS x(key,value);
  IF cardinality(targets) IS DISTINCT FROM (SELECT count(DISTINCT x) FROM unnest(targets) AS x) THEN RAISE EXCEPTION 'dpd.duplicate_mapping_target' USING ERRCODE='PT409';END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(feed->'original_refs') LOOP
   pin:=private.dpd_original_schema_pin(_tenant,_setup,feed->>'key',ref);
   IF ref IS DISTINCT FROM pin OR (ref->>'file_id')::uuid=ANY(seen) OR feed->>'data_source_id' IS DISTINCT FROM pin->>'data_source_id' THEN RAISE EXCEPTION 'dpd.confirmed_original_pin_conflict' USING ERRCODE='PT409';END IF;
   IF pin->>'data_source_id' IS NOT NULL AND (private.dpw_source_allows(actor,_tenant,(pin->>'data_source_id')::uuid,'view') IS DISTINCT FROM true OR (_for_execution AND private.dpw_source_allows(actor,_tenant,(pin->>'data_source_id')::uuid,'ingest') IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'dpd.current_confirmed_source_denied' USING ERRCODE='42501';END IF;
   seen:=array_append(seen,(ref->>'file_id')::uuid);catalog:=catalog||jsonb_build_array(pin);SELECT array_agg(h.value->>'name') INTO headers FROM jsonb_array_elements(pin->'header_fields') AS h(value);
   FOR key,target IN SELECT x.key,x.value FROM jsonb_each_text(feed->'mappings') AS x(key,value) LOOP
    IF key IN('extras_json','__proto__','constructor','prototype') OR NOT key=ANY(headers) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=target) THEN RAISE EXCEPTION 'dpd.mapping_actual_field_missing' USING ERRCODE='PT409';END IF;
   END LOOP;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE (x.value->>'required')::boolean AND NOT (x.value->>'name')=ANY(coalesce(targets,'{}'))) OR ((feed->>'allow_empty')::boolean IS DISTINCT FROM true AND (pin->>'data_start_row')::bigint=(pin->>'total_raw_rows')::bigint) THEN RAISE EXCEPTION 'dpd.required_mapping_or_nonempty_feed_missing' USING ERRCODE='PT409';END IF;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM private.dpd_original_intents f WHERE f.setup_id=_setup AND NOT f.id=ANY(seen)) THEN RAISE EXCEPTION 'dpd.all_received_originals_must_remain_bound' USING ERRCODE='PT409';END IF;
 IF jsonb_array_length(_mapping->'quality_rules')>50 OR (SELECT count(DISTINCT x.value->>'id') FROM jsonb_array_elements(_mapping->'quality_rules') AS x(value))<>jsonb_array_length(_mapping->'quality_rules') THEN RAISE EXCEPTION 'dpd.unique_quality_rule_ids_required' USING ERRCODE='PT409';END IF;
 FOR rule IN SELECT value FROM jsonb_array_elements(_mapping->'quality_rules') LOOP
  IF length(coalesce(rule->>'id','')) NOT BETWEEN 1 AND 120 OR (rule->>'kind' IN('required','unique_composite','bank_date_amount')) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.known_confirmed_quality_rule_required' USING ERRCODE='PT409';END IF;
  IF rule->>'kind'='required' THEN rule_fields:=ARRAY[rule->>'field'];ELSIF rule->>'kind'='unique_composite' THEN IF jsonb_typeof(rule->'fields') IS DISTINCT FROM 'array' OR jsonb_array_length(rule->'fields') NOT BETWEEN 1 AND 50 THEN RAISE EXCEPTION 'dpd.explicit_scalar_composite_fields_required' USING ERRCODE='PT409';END IF;SELECT array_agg(value) INTO rule_fields FROM jsonb_array_elements_text(rule->'fields');
  ELSE
   rule_fields:=ARRAY[rule->>'date_field',rule->>'amount_field'];IF rule->>'indicator_field' IS NOT NULL THEN rule_fields:=array_append(rule_fields,rule->>'indicator_field');END IF;
   IF (rule->>'date_format' IN('YYYY-MM-DD','DD/MM/YYYY','MM/DD/YYYY','YYYYMMDD')) IS DISTINCT FROM true OR (rule->>'amount_format' IN('decimal_dot','decimal_comma')) IS DISTINCT FROM true OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=rule->>'date_field' AND x.value->>'type'='date') OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=rule->>'amount_field' AND x.value->>'type'='number') THEN RAISE EXCEPTION 'dpd.explicit_bank_date_amount_contract_required' USING ERRCODE='PT409';END IF;
   IF rule->>'indicator_field' IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=rule->>'indicator_field' AND x.value->>'type'='string') OR jsonb_typeof(rule->'debit_values') IS DISTINCT FROM 'array' OR jsonb_typeof(rule->'credit_values') IS DISTINCT FROM 'array' OR jsonb_array_length(rule->'debit_values')=0 OR jsonb_array_length(rule->'credit_values')=0 OR jsonb_typeof(rule->'debit_negative') IS DISTINCT FROM 'boolean' OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(rule->'debit_values') AS d(value) JOIN jsonb_array_elements_text(rule->'credit_values') AS c(value) ON d.value=c.value)) THEN RAISE EXCEPTION 'dpd.explicit_bank_sign_convention_required' USING ERRCODE='PT409';END IF;
  END IF;
  IF array_position(rule_fields,NULL) IS NOT NULL OR cardinality(rule_fields)<>(SELECT count(DISTINCT x) FROM unnest(rule_fields) AS x) OR EXISTS(SELECT 1 FROM unnest(rule_fields) AS f(name) WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'output_schema') AS x(value) WHERE x.value->>'name'=f.name AND (rule->>'kind'<>'unique_composite' OR x.value->>'type'<>'json'))) OR EXISTS(SELECT 1 FROM jsonb_array_elements(_mapping->'feeds') AS f(value) CROSS JOIN unnest(rule_fields) AS r(name) WHERE NOT EXISTS(SELECT 1 FROM jsonb_each_text(f.value->'mappings') AS m(key,value) WHERE m.value=r.name)) THEN RAISE EXCEPTION 'dpd.quality_rule_confirmed_field_missing' USING ERRCODE='PT409';END IF;
 END LOOP;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant,'setup_id',_setup,'draft_version',_version,'state','available','complete',true,'originals',catalog);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_get_mapping_admission(_tenant_id uuid, _setup_id uuid, _draft_version integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'mapping.read',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);v private.dpd_versions%ROWTYPE;catalog jsonb;
BEGIN
 SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 IF v.version IS DISTINCT FROM _draft_version THEN RAISE EXCEPTION 'dpd.current_saved_mapping_version_required' USING ERRCODE='PT409';END IF;
 catalog:=private.dpd_validate_confirmed_mapping(_tenant_id,s.id,v.version,v.payload->'confirmed_mapping',false);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'draft_version',v.version,'catalog',catalog,'confirmed_mapping',v.payload->'confirmed_mapping','confirmed_mapping_sha256',private.dpw_hash(v.payload->'confirmed_mapping'),'publish_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION private.dps_setup_admission(_tenant uuid, _setup uuid, _actor uuid, _operation text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF _operation NOT IN('scope.groups','scope.save','scope.read','scope.lookup','scope.decide','preview.bind') THEN RAISE EXCEPTION 'dps.fixed_operation_required' USING ERRCODE='42501';END IF;
 IF _operation<>'scope.read' THEN
  PERFORM public.assert_data_prep_actor(_tenant,_actor,true);
  IF NOT EXISTS(SELECT 1 FROM public.tenant_members WHERE tenant_id=_tenant AND user_id=_actor AND active IS TRUE AND role='tenant_admin') THEN RAISE EXCEPTION 'dps.active_tenant_admin_required' USING ERRCODE='42501';END IF;
 END IF;
 IF _operation='scope.groups' AND _setup IS NULL THEN
  RETURN;
 END IF;
 IF _setup IS NULL OR NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant) THEN RAISE EXCEPTION 'dps.exact_setup_required' USING ERRCODE='42501';END IF;
 IF _operation='scope.decide' THEN
  IF NOT EXISTS(SELECT 1 FROM private.dpd_preview_links l JOIN private.dps_scope_requests q ON q.configuration_id=l.configuration_id AND q.pipeline_id=l.pipeline_id AND q.tenant_id=l.tenant_id
    JOIN private.dpd_setups s ON s.id=l.setup_id AND s.tenant_id=l.tenant_id AND s.created_by=q.created_by
    WHERE l.setup_id=_setup AND l.tenant_id=_tenant AND q.created_by<>_actor)
  THEN RAISE EXCEPTION 'dps.independent_setup_scope_required' USING ERRCODE='42501';END IF;
 ELSIF _operation='scope.read' THEN
  IF NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant AND created_by=_actor)
   AND NOT EXISTS(SELECT 1 FROM private.dpd_preview_links l WHERE l.setup_id=_setup AND l.tenant_id=_tenant AND private.data_prep_pipeline_scope_allows(_actor,_tenant,l.pipeline_id,'view') IS TRUE)
  THEN RAISE EXCEPTION 'dps.current_read_scope_required' USING ERRCODE='42501';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup AND tenant_id=_tenant AND created_by=_actor) THEN RAISE EXCEPTION 'dps.original_setup_creator_required' USING ERRCODE='42501';END IF;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.dps_issue_request_context(_tenant_id uuid, _verified_subject jsonb, _trusted_ip text, _ttl_seconds integer, _operation text, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;enabled boolean;ip inet;expires timestamptz;c private.dpd_request_contexts%ROWTYPE;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' OR _ttl_seconds NOT BETWEEN 1 AND 60 OR _ttl_seconds IS NULL
 OR _operation NOT IN('scope.groups','scope.save','scope.read','scope.lookup','scope.decide') OR _operation IS NULL THEN RAISE EXCEPTION 'dps.fixed_server_issuer_required' USING ERRCODE='42501';END IF;
 actor:=private.dpd_peer_actor(_tenant_id,_verified_subject);
 IF public.user_has_permission(actor,_tenant_id,CASE WHEN _operation IN('scope.save','scope.decide') THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true
 THEN RAISE EXCEPTION 'dps.current_capability_required' USING ERRCODE='42501';END IF;
 PERFORM private.dps_setup_admission(_tenant_id,_setup_id,actor,_operation);
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;
 IF NOT FOUND OR enabled IS NULL THEN RAISE EXCEPTION 'dps.current_network_unavailable' USING ERRCODE='42501';END IF;
 BEGIN ip:=nullif(_trusted_ip,'')::inet;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'dps.fixed_transport_ip_invalid' USING ERRCODE='42501';END;
 IF enabled AND (ip IS NULL OR public.ip_in_tenant_allowlist(_tenant_id,host(ip)) IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dps.current_bound_network_denied' USING ERRCODE='42501';END IF;
 expires:=least(clock_timestamp()+_ttl_seconds*interval '1 second',to_timestamp((_verified_subject->>'exp')::double precision));IF expires<=clock_timestamp() THEN RAISE EXCEPTION 'dps.subject_expired' USING ERRCODE='42501';END IF;
 c.id:=gen_random_uuid();INSERT INTO private.dpd_request_contexts(id,token_sha256,tenant_id,actor_id,verified_subject,operation,setup_id,intent_sha256,transport_kind,request_ip,transport_attestation_sha256,expires_at)
 VALUES(c.id,encode(sha256(convert_to(c.id::text,'UTF8')),'hex'),_tenant_id,actor,_verified_subject,_operation,_setup_id,private.dpw_hash(jsonb_build_object('operation',_operation,'setup_id',_setup_id)),
 'main_fixed_service_verified_middleware_CF_transport',ip,private.dpw_hash(jsonb_build_object('actor',actor,'tenant',_tenant_id,'operation',_operation,'setup',_setup_id,'issuer_role','service_role')),expires) RETURNING * INTO c;
 PERFORM private.dpw_audit(actor,_tenant_id,'dps.request_context.issued',c.id,jsonb_build_object('operation',_operation,'setup_id',_setup_id,'expires_at',expires,'browser_issuance_allowed',false));
 RETURN jsonb_build_object('request_context_id',c.id,'actor_id',actor,'tenant_id',_tenant_id,'operation',_operation,'setup_id',_setup_id,'expires_at',expires,
 'network_policy_available',true,'network_policy_enabled',enabled,'network_allowed',true,'issuer_transport','service_role','verified_subject_expires_at',to_timestamp((_verified_subject->>'exp')::double precision),'browser_issuance_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION private.dps_context_actor(_tenant uuid, _setup uuid, _operation text, _context uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=auth.uid();c private.dpd_request_contexts%ROWTYPE;enabled boolean;
BEGIN
 IF actor IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated' OR _context IS NULL THEN RAISE EXCEPTION 'dps.original_authenticated_context_required' USING ERRCODE='42501';END IF;
 SELECT * INTO c FROM private.dpd_request_contexts WHERE id=_context AND tenant_id=_tenant AND actor_id=actor AND operation=_operation AND setup_id IS NOT DISTINCT FROM _setup;
 IF NOT FOUND OR c.expires_at<=clock_timestamp() OR c.verified_subject->>'sub' IS DISTINCT FROM actor::text OR c.verified_subject->>'aal' IS DISTINCT FROM auth.jwt()->>'aal' OR c.verified_subject->>'exp' IS DISTINCT FROM auth.jwt()->>'exp'
 THEN RAISE EXCEPTION 'dps.fresh_same_subject_context_required' USING ERRCODE='42501';END IF;
 IF private.dpd_peer_actor(_tenant,c.verified_subject) IS DISTINCT FROM actor THEN RAISE EXCEPTION 'dps.current_subject_denied' USING ERRCODE='42501';END IF;
 IF public.user_has_permission(actor,_tenant,CASE WHEN _operation IN('scope.save','scope.decide','preview.bind') THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dps.current_capability_required' USING ERRCODE='42501';END IF;
 PERFORM private.dps_setup_admission(_tenant,_setup,actor,_operation);
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant;
 IF NOT FOUND OR enabled IS NULL OR (enabled AND (c.request_ip IS NULL OR public.ip_in_tenant_allowlist(_tenant,host(c.request_ip)) IS DISTINCT FROM true)) THEN RAISE EXCEPTION 'dps.current_bound_network_denied' USING ERRCODE='42501';END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION public.issue_user_delegated_api_token(_tenant_id uuid, _name text, _prefix text, _token_hash text, _scopes text[], _expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid := auth.uid(); token_id uuid; audit_id bigint; slug text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
   OR actor IS NULL THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 IF _tenant_id IS NULL OR _name IS NULL OR length(btrim(_name)) NOT BETWEEN 1 AND 120
   OR _prefix IS NULL OR _prefix !~ '^fvi_[0-9a-f]{8}$'
   OR _token_hash IS NULL OR _token_hash !~ '^[0-9a-f]{64}$'
   OR _scopes IS NULL OR cardinality(_scopes) NOT BETWEEN 1 AND 22
   OR array_position(_scopes,NULL) IS NOT NULL OR NOT (_scopes <@ ARRAY['recons.read','recons.run','breaks.write','connectors.read','connectors.run','connectors.agent','watchers.read','watchers.write','data-prep.read','data-prep.write','data-prep.run','data-prep.approve','data-prep.promote','reference-data.read','reference-data.write','reference-data.approve','reports.read','environment-changes.read','environment-changes.write','environment-changes.approve','ai.inference','aidp:extract']::text[])
   OR cardinality(_scopes)<>(SELECT count(DISTINCT s) FROM unnest(_scopes) s)
   OR (_expires_at IS NOT NULL AND (_expires_at<=clock_timestamp() OR _expires_at>clock_timestamp()+interval '730 days')) THEN
   RAISE EXCEPTION 'invalid token issuance input' USING ERRCODE='22023';
 END IF;
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active=true AND role='tenant_admin' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 SELECT t.slug INTO slug FROM public.tenants t WHERE t.id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 -- Reject hash reuse without printing any token/hash. Existing hash index is nonunique.
 PERFORM pg_advisory_xact_lock(hashtextextended(_token_hash,743301));
 IF EXISTS(SELECT 1 FROM public.api_tokens WHERE token_hash=_token_hash) THEN
   RAISE EXCEPTION 'token collision' USING ERRCODE='23505';
 END IF;
 INSERT INTO public.api_tokens(tenant_id,name,prefix,token_hash,scopes,expires_at,created_by,principal_kind,subject_user_id)
 VALUES(_tenant_id,btrim(_name),_prefix,_token_hash,_scopes,_expires_at,actor,'user_delegated',actor) RETURNING id INTO token_id;
 INSERT INTO public.audit_log(tenant_id,tenant_slug,actor_user_id,scope,action,resource_type,resource_id,context)
 VALUES(_tenant_id,slug,actor,'tenant','api.token.create','api_tokens',token_id::text,
   jsonb_build_object('name',btrim(_name),'scopes',_scopes,'principal_kind','user_delegated','subject_user_id',actor)) RETURNING id INTO audit_id;
 IF NOT EXISTS(SELECT 1 FROM public.audit_log a JOIN public.audit_chain_head h ON h.singleton=true
   AND h.last_audit_id=a.id AND h.last_hash=a.row_hash WHERE a.id=audit_id
   AND a.actor_user_id=actor AND a.tenant_id=_tenant_id AND a.resource_id=token_id::text AND octet_length(a.row_hash)=32) THEN
   RAISE EXCEPTION 'token issuance audit receipt absent';
 END IF;
 RETURN jsonb_build_object('id',token_id,'audit_id',audit_id::text);
END $function$

CREATE OR REPLACE FUNCTION public.revoke_user_delegated_api_token(_tenant_id uuid, _token_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid := auth.uid(); audit_id bigint; slug text;
BEGIN
 IF auth.role() IS DISTINCT FROM 'authenticated' OR current_setting('role',true) IS DISTINCT FROM 'authenticated'
   OR actor IS NULL THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.tenant_members WHERE tenant_id=_tenant_id AND user_id=actor AND active=true AND role='tenant_admin' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 SELECT t.slug INTO slug FROM public.tenants t WHERE t.id=_tenant_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.api_tokens WHERE id=_token_id AND tenant_id=_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'not permitted' USING ERRCODE='42501'; END IF;
 -- Idempotent repeat keeps the existing timestamp and creates an attributed receipt.
 UPDATE public.api_tokens SET revoked_at=coalesce(revoked_at,clock_timestamp()) WHERE id=_token_id AND tenant_id=_tenant_id;
 INSERT INTO public.audit_log(tenant_id,tenant_slug,actor_user_id,scope,action,resource_type,resource_id,context)
 VALUES(_tenant_id,slug,actor,'tenant','api.token.revoke','api_tokens',_token_id::text,'{}') RETURNING id INTO audit_id;
 IF NOT EXISTS(SELECT 1 FROM public.audit_log a JOIN public.audit_chain_head h ON h.singleton=true
   AND h.last_audit_id=a.id AND h.last_hash=a.row_hash WHERE a.id=audit_id
   AND a.actor_user_id=actor AND a.tenant_id=_tenant_id AND a.resource_id=_token_id::text AND octet_length(a.row_hash)=32) THEN
   RAISE EXCEPTION 'token revocation audit receipt absent';
 END IF;
 RETURN jsonb_build_object('id',_token_id,'audit_id',audit_id::text);
END $function$

CREATE OR REPLACE FUNCTION private.settle_public_ai_dispatch(_attempt_id uuid, _tokens_in integer, _tokens_out integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
 SET row_security TO 'on'
AS $function$
DECLARE actor uuid:=(SELECT subject_user_id FROM private.public_ai_inference_requests WHERE id=_attempt_id); r public.copilot_spend_reservations%ROWTYPE; actual_c numeric; actual_t numeric;
BEGIN
 IF actor IS NULL OR _tokens_in IS NULL OR _tokens_out IS NULL OR _tokens_in<0 OR _tokens_out<0 THEN RAISE EXCEPTION 'copilot.usage_unavailable'; END IF;
 PERFORM pg_advisory_xact_lock(61000,1);
 SELECT * INTO r FROM public.copilot_spend_reservations WHERE id=_attempt_id::text FOR UPDATE;
 IF NOT FOUND OR r.actor_id<>actor OR r.llm_provider_id IS NULL THEN RAISE EXCEPTION 'copilot.forbidden'; END IF;
 IF r.state='settled' AND r.tokens_in=_tokens_in AND r.tokens_out=_tokens_out THEN RETURN jsonb_build_object('settled',true); END IF;
 IF r.state<>'dispatched' THEN RAISE EXCEPTION 'copilot.settlement_conflict'; END IF;
 actual_t:=_tokens_in::numeric+_tokens_out;
 actual_c:=ceil(_tokens_in::numeric*r.input_rate+_tokens_out::numeric*r.output_rate);
 IF actual_t=0 OR actual_c<=0 THEN RAISE EXCEPTION 'copilot.usage_unavailable'; END IF;
 -- Authenticated reports are NOT a trusted provider attestation. Keep a bound
 -- floor in enforcement, so forged zero/small counters cannot release money.
 UPDATE public.copilot_spend_reservations SET state='settled',tokens_in=_tokens_in,tokens_out=_tokens_out,
   actual_tokens=actual_t,actual_micro_usd=actual_c,accounted_tokens=greatest(bound_tokens,actual_t),
   accounted_micro_usd=greatest(bound_micro_usd,actual_c) WHERE id=r.id;
 IF r.tenant_id IS NOT NULL THEN
   INSERT INTO public.ai_usage_events(tenant_id,user_id,scope,model,tokens_in,tokens_out,cost_usd,meta)
   VALUES(r.tenant_id,actor,'copilot',r.model_key,_tokens_in,_tokens_out,actual_c/1000000,
     jsonb_build_object('public_request_id',_attempt_id::text,'source','ai_inference_router.http','copilot_reservation_id',r.id,'pricing_basis',r.pricing_basis,'usage_source','server_upstream_response',
       'budget_enforcement','catalog_bound_floor'));
 END IF;
 RETURN jsonb_build_object('settled',true);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_get_authoring_shared_review(_tenant_id uuid, _setup_id uuid, _draft_version integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.shared.read',_request_context_id);l private.dpd_preview_links%ROWTYPE;review jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 SELECT * INTO l FROM private.dpd_preview_links WHERE tenant_id=_tenant_id AND setup_id=_setup_id AND draft_version=_draft_version;
 IF NOT FOUND THEN RAISE EXCEPTION 'dpd.actual_shared_review_binding_required' USING ERRCODE='PT409';END IF;
 review:=private.dps_get_scope_core(_tenant_id,l.pipeline_id);
 IF review->>'configuration_id' IS DISTINCT FROM l.configuration_id::text THEN RAISE EXCEPTION 'dpd.shared_review_configuration_changed' USING ERRCODE='PT409';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'draft_version',l.draft_version,'pipeline_id',l.pipeline_id,'configuration_id',l.configuration_id,'review',review,'publish_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION public.signup_invite_recovery(_action text, _attempt_id uuid, _email_hash text, _payload_hash text, _recovery_hash text, _lease_id uuid DEFAULT NULL::uuid, _outcome text DEFAULT NULL::text, _code text DEFAULT NULL::text, _status integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.signup_invitation_attempts; claimed boolean := false;
BEGIN
  IF _attempt_id IS NULL OR _email_hash IS NULL OR _payload_hash IS NULL OR _recovery_hash IS NULL
    OR _email_hash !~ '^[a-f0-9]{64}$' OR _payload_hash !~ '^[a-f0-9]{64}$' OR _recovery_hash !~ '^[a-f0-9]{64}$'
    OR _action NOT IN ('reserve','check','claim','defer','settle') OR _action IS NULL THEN
    RAISE EXCEPTION 'Invalid recovery request' USING ERRCODE='22023';
  END IF;
  IF _action IN ('reserve','check') THEN
    INSERT INTO public.signup_invitation_attempts(attempt_id,email_hash,payload_hash,recovery_hash)
      VALUES (_attempt_id,_email_hash,_payload_hash,_recovery_hash) ON CONFLICT DO NOTHING;
  END IF;
  SELECT * INTO r FROM public.signup_invitation_attempts WHERE attempt_id=_attempt_id
    AND email_hash=_email_hash AND payload_hash=_payload_hash AND recovery_hash=_recovery_hash FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('state','blocked');
  END IF;
  IF _action='claim' AND r.state IN ('reserved','not_sent') THEN
    BEGIN
      UPDATE public.signup_invitation_attempts SET state='sending',lease_id=pg_catalog.gen_random_uuid(),code=NULL,status=NULL,updated_at=now()
        WHERE attempt_id=r.attempt_id RETURNING * INTO r;
      claimed := true;
    EXCEPTION WHEN unique_violation THEN
      UPDATE public.signup_invitation_attempts SET state='blocked',updated_at=now()
        WHERE attempt_id=r.attempt_id RETURNING * INTO r;
    END;
  ELSIF _action='defer' AND r.state IN ('reserved','not_sent') THEN
    IF _code NOT IN ('SIGNUP_RATE_LIMITED','SIGNUP_NOT_STARTED') OR _status NOT IN (429,503) OR _code IS NULL OR _status IS NULL THEN
      RAISE EXCEPTION 'Invalid recovery result' USING ERRCODE='22023';
    END IF;
    UPDATE public.signup_invitation_attempts SET state='not_sent',code=_code,status=_status,updated_at=now()
      WHERE attempt_id=r.attempt_id RETURNING * INTO r;
  ELSIF _action='settle' THEN
    IF _outcome IS NULL OR _outcome NOT IN ('accepted','existing','unconfirmed') THEN
      RAISE EXCEPTION 'Invalid recovery result' USING ERRCODE='22023';
    END IF;
    IF r.state='sending' AND r.lease_id=_lease_id THEN
      UPDATE public.signup_invitation_attempts SET state=_outcome,updated_at=now()
        WHERE attempt_id=r.attempt_id RETURNING * INTO r;
    END IF;
  END IF;
  RETURN jsonb_build_object('state',r.state,'request_id',r.request_id,'code',r.code,'status',r.status,
    'claimed',claimed,'lease_id',CASE WHEN claimed THEN r.lease_id ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_decide_authoring_shared_review(_tenant_id uuid, _setup_id uuid, _draft_version integer, _request_id uuid, _decision text, _reason text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.shared.decide',_request_context_id);l private.dpd_preview_links%ROWTYPE;r private.dps_scope_requests%ROWTYPE;decision jsonb;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 SELECT * INTO l FROM private.dpd_preview_links WHERE tenant_id=_tenant_id AND setup_id=_setup_id AND draft_version=_draft_version;
 SELECT * INTO r FROM private.dps_scope_requests WHERE id=_request_id AND tenant_id=_tenant_id AND pipeline_id=l.pipeline_id AND configuration_id=l.configuration_id;
 IF l.setup_id IS NULL OR r.id IS NULL OR r.created_by=actor THEN RAISE EXCEPTION 'dpd.exact_independent_shared_scope_review_required' USING ERRCODE='42501';END IF;
 -- Native dps_decide_scope rechecks current admin/pipeline/input/group rights,
 -- its immutable original manifest, independent maker and exact grant/revoke set.
 decision:=private.dps_decide_scope_core(_tenant_id,r.id,_decision,_reason);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'draft_version',l.draft_version,'pipeline_id',l.pipeline_id,'configuration_id',l.configuration_id,'request_id',r.id,'decision',decision->'decision','is_new',(decision->>'is_new')::boolean,'publish_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION private.dpdi_authorize(_tenant uuid, _setup uuid, _job uuid, _actor uuid, _write boolean)
 RETURNS private.dpdi_jobs
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE j private.dpdi_jobs%ROWTYPE;l private.dpd_preview_links%ROWTYPE;p public.data_prep_pipelines%ROWTYPE;c public.data_prep_configuration_revisions%ROWTYPE;i private.dpd_preview_file_links%ROWTYPE;b public.data_prep_delivery_batches%ROWTYPE;
BEGIN
 SELECT * INTO j FROM private.dpdi_jobs WHERE id=_job AND tenant_id=_tenant AND setup_id=_setup AND (NOT _write OR actor_id=_actor);
 SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=j.setup_id AND draft_version=j.draft_version AND tenant_id=_tenant;
 SELECT * INTO p FROM public.data_prep_pipelines WHERE id=l.pipeline_id AND tenant_id=_tenant;SELECT * INTO c FROM public.data_prep_configuration_revisions WHERE id=l.configuration_id AND tenant_id=_tenant;
 SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=(j.snapshot->>'batch_id')::uuid AND tenant_id=_tenant;
 IF j.id IS NULL OR l.setup_id IS NULL OR p.id IS NULL OR c.id IS NULL OR p.lifecycle_state='archived' OR c.pipeline_version<>l.pipeline_version OR b.mode IS DISTINCT FROM j.snapshot->>'mode' OR j.snapshot->>'mode' NOT IN('preview','prepare') OR (j.snapshot->>'mode'='prepare' AND (j.snapshot->>'approval_origin' IS DISTINCT FROM 'dpdi_setup_review_v1' OR NOT EXISTS(SELECT 1 FROM private.dpdi_setup_review_decisions sd JOIN private.dpdi_setup_review_requests sr ON sr.id=sd.request_id WHERE sd.id=(j.snapshot->>'setup_review_decision_id')::uuid AND sd.decision='approved' AND sr.setup_id=j.setup_id AND sr.draft_version=j.draft_version AND sd.decided_by<>sr.requested_by)))
 OR private.dpw_mode_attest(_actor,_tenant,p.id,b.execution_mode,b.human_in_loop) IS DISTINCT FROM true
 OR private.data_prep_pipeline_scope_allows(_actor,_tenant,p.id,CASE WHEN _write THEN 'run' ELSE 'view' END) IS DISTINCT FROM true
 OR (_write AND (p.status NOT IN('draft','approved') OR p.version<>l.pipeline_version OR (SELECT max(v.version) FROM private.dpd_versions v WHERE v.setup_id=j.setup_id)<>j.draft_version OR c.payload_sha256 IS DISTINCT FROM j.snapshot->>'configuration_sha256'))
 THEN RAISE EXCEPTION 'dpdi.current_exact_preview_origin_required' USING ERRCODE='42501';END IF;
 FOR i IN SELECT * FROM private.dpd_preview_file_links WHERE setup_id=j.setup_id AND draft_version=j.draft_version LOOP
  IF private.dpw_source_allows(_actor,_tenant,i.data_source_id,'view') IS DISTINCT FROM true OR (_write AND (private.dpw_source_allows(_actor,_tenant,i.data_source_id,'ingest') IS DISTINCT FROM true OR NOT private.dpd_original_viewable(i.original_file_id))) THEN RAISE EXCEPTION 'dpdi.current_original_source_denied' USING ERRCODE='42501';END IF;
 END LOOP;RETURN j;
END $function$

CREATE OR REPLACE FUNCTION private.dpdi_dto(j private.dpdi_jobs)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);r public.data_prep_delivery_runs%ROWTYPE;
BEGIN SELECT * INTO r FROM public.data_prep_delivery_runs WHERE id=j.reserved_run_id;
 RETURN jsonb_build_object('actor_id',j.actor_id,'execution_actor_id',j.actor_id,'tenant_id',j.tenant_id,'setup_id',j.setup_id,'draft_version',j.draft_version,'job_id',j.id,'run_id',r.id,'reserved_run_id',j.reserved_run_id,'request_key',j.request_key,'mode',j.snapshot->>'mode','input_binding_kind','authoring_original_pinned','phase',e.phase,'input_index',e.input_index,'next_record',e.next_record::text,'source_records',e.source_records::text,'blocking_records',e.blocking_records::text,'output_pages',e.output_pages,'output_root_sha256',e.output_root_sha256,'last_page_sha256',e.last_page_sha256,'claim_key',e.claim_key,'lease_expires_at',e.lease_expires_at,'snapshot_sha256',j.snapshot_sha256,'full_final_ack',e.phase IN('success','blocked'),'released_rows','0','publication_eligible',false,'publish_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_claim_preview(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _lease_seconds integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.claim',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE;expires timestamptz;run public.data_prep_delivery_runs%ROWTYPE;firstidx integer;terminal jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('dpdi-preview:'||_tenant_id::text||':'||_setup_id::text,0));PERFORM 1 FROM private.dpdi_jobs WHERE id=j.id FOR UPDATE;e:=private.dpdi_head(j.id);
 IF _claim_key IS NULL OR _lease_seconds IS NULL OR _lease_seconds NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'dpdi.bounded_actual_claim_required' USING ERRCODE='22023';END IF;
 IF e.phase IN('success','blocked','cancelled') OR (e.phase='running' AND e.lease_expires_at>clock_timestamp()) THEN RETURN private.dpdi_dto(j)||jsonb_build_object('claimed',false);END IF;
 IF EXISTS(SELECT 1 FROM private.dpdi_jobs older CROSS JOIN LATERAL private.dpdi_head(older.id) head WHERE older.setup_id=j.setup_id AND older.id<>j.id AND (head.phase='running' AND head.lease_expires_at>clock_timestamp() OR head.phase IN('queued','running') AND (older.created_at,older.id)<(j.created_at,j.id))) THEN RETURN private.dpdi_dto(j)||jsonb_build_object('claimed',false,'queue_blocked',true);END IF;
 expires:=least(clock_timestamp()+_lease_seconds*interval '1 second',to_timestamp((auth.jwt()->>'exp')::double precision));
 SELECT * INTO run FROM public.data_prep_delivery_runs WHERE id=j.reserved_run_id;
 IF NOT FOUND THEN
  INSERT INTO public.data_prep_delivery_runs(id,tenant_id,pipeline_id,batch_id,pipeline_version,request_key,started_by,snapshot,snapshot_sha256,state) VALUES(j.reserved_run_id,_tenant_id,(j.snapshot->>'pipeline_id')::uuid,(j.snapshot->>'batch_id')::uuid,(j.snapshot->>'pipeline_version')::integer,j.request_key,actor,j.snapshot,j.snapshot_sha256,'running');
  IF j.snapshot->>'mode'='prepare' THEN UPDATE public.data_prep_delivery_batches SET state='processing' WHERE id=(j.snapshot->>'batch_id')::uuid AND state='collecting';END IF;
  INSERT INTO private.dpdi_run_inputs(run_id,job_id,input_id,original_file_id,data_source_id,rows_count,selection_sha256) SELECT j.reserved_run_id,j.id,i.id,i.original_file_id,i.data_source_id,i.rows_count,i.selection_sha256 FROM private.dpd_preview_file_links i WHERE i.setup_id=j.setup_id AND i.draft_version=j.draft_version;
 END IF;
 firstidx:=e.input_index;WHILE firstidx<jsonb_array_length(j.snapshot->'inputs') AND (j.snapshot->'inputs'->firstidx->>'rows_count')::bigint=0 LOOP firstidx:=firstidx+1;END LOOP;
 IF firstidx=jsonb_array_length(j.snapshot->'inputs') AND e.source_records=0 THEN
  terminal:=jsonb_build_object('representation','dpdi_authoring_pages_v1','mode',j.snapshot->>'mode','job_id',j.id,'status','success','publication_eligible',false,'source_records','0','blocking_records','0','preview_rows','0','full_final_ack',true,'zero_source_basis','actual_confirmed_allow_empty_selections');
  INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index) VALUES(j.id,actor,'success',_claim_key,expires,firstidx);
  UPDATE public.data_prep_delivery_runs SET state='success',result=terminal,result_sha256=private.dpw_hash(terminal),finished_at=clock_timestamp() WHERE id=j.reserved_run_id AND state='running';
 ELSE
  INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index,next_record,source_records,blocking_records,output_pages,output_root_sha256,last_page_sha256) VALUES(j.id,actor,'running',_claim_key,expires,firstidx,e.next_record,e.source_records,e.blocking_records,e.output_pages,e.output_root_sha256,e.last_page_sha256);
 END IF;
 RETURN private.dpdi_dto(j)||jsonb_build_object('claimed',true,'snapshot',j.snapshot);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_enqueue_preview(_tenant_id uuid, _setup_id uuid, _draft_version integer, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.enqueue',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,true);l private.dpd_preview_links%ROWTYPE;v private.dpd_versions%ROWTYPE;c public.data_prep_configuration_revisions%ROWTYPE;b public.data_prep_delivery_batches%ROWTYPE;j private.dpdi_jobs%ROWTYPE;snap jsonb;inputs jsonb;
BEGIN
 PERFORM 1 FROM private.dpd_setups WHERE id=s.id FOR UPDATE;SELECT * INTO l FROM private.dpd_preview_links WHERE setup_id=s.id AND draft_version=_draft_version;SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 SELECT * INTO c FROM public.data_prep_configuration_revisions WHERE id=l.configuration_id;SELECT * INTO b FROM public.data_prep_delivery_batches WHERE id=l.batch_id;
 IF l.setup_id IS NULL OR v.version<>_draft_version OR _request_key IS NULL OR b.mode IS DISTINCT FROM 'preview' THEN RAISE EXCEPTION 'dpdi.actual_current_authoring_preview_required' USING ERRCODE='PT409';END IF;
 PERFORM private.dpd_validate_confirmed_mapping(_tenant_id,s.id,v.version,v.payload->'confirmed_mapping');PERFORM private.dpw_authorize(_tenant_id,l.pipeline_id,'run');
 SELECT jsonb_agg(jsonb_build_object('input_id',i.id,'original_file_id',i.original_file_id,'data_source_id',i.data_source_id,'feed_key',i.feed_key,'selection',i.selection,'selection_sha256',i.selection_sha256,'rows_count',i.rows_count::text,'dpw_file_id',NULL,'upload_id',NULL) ORDER BY i.feed_key,i.id) INTO inputs FROM private.dpd_preview_file_links i WHERE i.setup_id=s.id AND i.draft_version=v.version;
 IF inputs IS NULL OR (SELECT sum((x.value->>'rows_count')::bigint) FROM jsonb_array_elements(inputs) AS x(value))>1000000 THEN RAISE EXCEPTION 'dpdi.complete_selected_input_budget_required';END IF;
 snap:=jsonb_build_object('tenant_id',_tenant_id,'setup_id',s.id,'draft_version',v.version,'pipeline_id',l.pipeline_id,'pipeline_version',l.pipeline_version,'configuration_id',l.configuration_id,'configuration_sha256',c.payload_sha256,'batch_id',l.batch_id,'business_date',b.business_date,'mode','preview','configuration_status',(SELECT p.status FROM public.data_prep_pipelines p WHERE p.id=l.pipeline_id),'input_binding_kind','authoring_original_pinned','inputs',inputs,'input_manifest_sha256',l.input_manifest_sha256,'confirmed_mapping',v.payload->'confirmed_mapping','confirmed_mapping_sha256',private.dpw_hash(v.payload->'confirmed_mapping'),'pipeline_configuration',c.payload,'feeds',c.payload->'feeds','publish_allowed',false);
 SELECT * INTO j FROM private.dpdi_jobs WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF j.setup_id<>s.id OR j.draft_version<>v.version OR j.snapshot IS DISTINCT FROM snap THEN RAISE EXCEPTION 'dpdi.preview_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpdi_dto(j)||jsonb_build_object('request_replay',true);END IF;
 PERFORM private.dpd_assert_transform_configuration(snap->'pipeline_configuration');
 INSERT INTO private.dpdi_jobs(tenant_id,setup_id,draft_version,actor_id,request_key,snapshot,snapshot_sha256) VALUES(_tenant_id,s.id,v.version,actor,_request_key,snap,private.dpw_hash(snap)) RETURNING * INTO j;
 PERFORM private.dpdi_authorize(_tenant_id,s.id,j.id,actor,true);INSERT INTO private.dpdi_job_events(job_id,actor_id,phase) VALUES(j.id,actor,'queued');PERFORM private.dpd_event(_tenant_id,s.id,actor,'preview.job.queued',j.id,jsonb_build_object('snapshot_sha256',j.snapshot_sha256,'mode','preview','publish_allowed',false));RETURN private.dpdi_dto(j)||jsonb_build_object('request_replay',false);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_preview_input_page(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _page_size integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.input',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE:=private.dpdi_live_lease(j,_claim_key);input jsonb:=j.snapshot->'inputs'->e.input_index;page jsonb;meta jsonb;rows jsonb;first_at bigint;fid uuid;sheet text;total bigint;
BEGIN
 IF input IS NULL THEN RETURN private.dpdi_dto(j)||jsonb_build_object('input_complete',true,'page',NULL);END IF;
 IF _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION 'dpdi.bounded_input_page_required';END IF;
 fid:=(input->>'original_file_id')::uuid;meta:=private.dpd_selected_input(fid,input->'selection');first_at:=(meta->>'data_start_row')::bigint;sheet:=input->'selection'->>'sheet_key';total:=(input->>'rows_count')::bigint;
 SELECT coalesce(jsonb_agg(jsonb_build_object('record_index',(q.ordinal-first_at)::text,'source_row_ordinal',q.ordinal::text,'input_id',input->>'input_id','original_file_id',fid,'source_row_id',jsonb_build_array(fid,sheet,q.ordinal::text)::text,'values',q.value,'raw_cells',q.cells,'raw_row_sha256',private.dpw_hash(q.cells)) ORDER BY q.ordinal),'[]') INTO rows FROM(
 SELECT c.start_row+x.ordinality-1 ordinal,x.value cells,(SELECT jsonb_object_agg(h.value->>'name',coalesce(x.value->>((h.value->>'ordinal')::integer),'')) FROM jsonb_array_elements(meta->'header_fields') AS h(value)) value FROM private.dpd_original_chunks c CROSS JOIN LATERAL jsonb_array_elements(c.rows) WITH ORDINALITY AS x(value,ordinality) WHERE c.file_id=fid AND c.sheet_key=sheet AND c.start_row<first_at+e.next_record+_page_size AND c.start_row+c.row_count>first_at+e.next_record AND c.start_row+x.ordinality-1>=first_at+e.next_record AND c.start_row+x.ordinality-1<first_at+least(e.next_record+_page_size,total)) q;
 IF octet_length(rows::text)>1048576 THEN RAISE EXCEPTION 'dpdi.input_page_byte_budget_reduce_explicit_page' USING ERRCODE='22023';END IF;
 RETURN private.dpdi_dto(j)||jsonb_build_object('input_complete',false,'input',input,'rows',rows,'total',total::text,'first_record',e.next_record::text,'has_more',e.next_record+jsonb_array_length(rows)<total,'snapshot',j.snapshot);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_preview_unique_page(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _keys jsonb, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'preview.job.unique',_request_context_id,_verified_subject);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE:=private.dpdi_live_lease(j,_claim_key);input uuid:=(j.snapshot->'inputs'->e.input_index->>'input_id')::uuid;answer jsonb;collision boolean;
BEGIN
 IF jsonb_typeof(_keys)IS DISTINCT FROM'array'OR jsonb_array_length(_keys)NOT BETWEEN 1 AND 4096 OR octet_length(_keys::text)>1048576 OR EXISTS(SELECT 1 FROM jsonb_array_elements(_keys)k WHERE k->>'input_id'IS DISTINCT FROM input::text OR coalesce(k->>'record_index','')!~'^(0|[1-9][0-9]*)$'OR(k->>'record_index')::bigint<e.next_record OR(k->>'record_index')::bigint>=e.next_record+1000 OR(k->>'record_index')::bigint>=(j.snapshot->'inputs'->e.input_index->>'rows_count')::bigint OR length(coalesce(k->>'rule_id',''))NOT BETWEEN 1 AND 255 OR jsonb_typeof(k->'key_canonical')IS DISTINCT FROM'string'OR octet_length(k->>'key_canonical')>32768 OR k->>'key_sha256'IS NULL OR k->>'key_sha256'!~'^[a-f0-9]{64}$'OR encode(sha256(convert_to(k->>'key_canonical','UTF8')),'hex')IS DISTINCT FROM k->>'key_sha256')THEN RAISE EXCEPTION 'dpdi.complete_canonical_key_sha_page_required';END IF;
 PERFORM 1 FROM private.dpdi_jobs WHERE id=j.id FOR UPDATE;
 WITH entries AS MATERIALIZED(SELECT k->>'rule_id'rule_id,substring(convert_to(k->>'key_canonical','UTF8')FROM 1 FOR 32)prefix,decode(k->>'key_sha256','hex')digest,k->>'key_canonical'canonical,input input_id,(k->>'record_index')::bigint record_index,ord FROM jsonb_array_elements(_keys)WITH ORDINALITY x(k,ord)),ins AS(INSERT INTO private.dpdi_optimized_unique_keys SELECT DISTINCT ON(rule_id,prefix,digest)j.id,rule_id,prefix,digest,canonical,input_id,record_index FROM entries ORDER BY rule_id,prefix,digest,ord ON CONFLICT DO NOTHING RETURNING *),matched AS(SELECT x.*,coalesce(n.input_id,old.input_id)first_input,coalesce(n.record_index,old.record_index)first_record,coalesce(n.key_canonical,old.key_canonical)first_canonical FROM entries x LEFT JOIN ins n ON n.rule_id=x.rule_id AND n.key_prefix=x.prefix AND n.key_sha256=x.digest LEFT JOIN private.dpdi_optimized_unique_keys old ON old.job_id=j.id AND old.rule_id=x.rule_id AND old.key_prefix=x.prefix AND old.key_sha256=x.digest AND n.rule_id IS NULL)
 SELECT jsonb_agg(input_id=first_input AND record_index=first_record ORDER BY ord),bool_or(first_canonical IS DISTINCT FROM canonical)INTO answer,collision FROM matched;
 IF collision IS DISTINCT FROM false OR answer@>'[null]'::jsonb OR jsonb_array_length(answer)<>jsonb_array_length(_keys)THEN RAISE EXCEPTION 'dpdi.canonical_collision_or_incomplete_verdict';END IF;RETURN private.dpdi_dto(j)||jsonb_build_object('unique',answer);
END$function$

CREATE OR REPLACE FUNCTION public.dpdi_commit_preview_page(_tenant_id uuid, _setup_id uuid, _job_id uuid, _claim_key uuid, _input_id uuid, _first_record bigint, _wire text, _sha256 text, _request_context_id uuid, _verified_subject jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_service_request_actor(_tenant_id,_setup_id,'preview.job.commit',_request_context_id,_verified_subject);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);e private.dpdi_job_events%ROWTYPE;prior private.dpdi_job_pages%ROWTYPE;input jsonb;row jsonb;line text;cells jsonb;n integer:=0;blocked integer:=0;total bigint;nextidx integer;nextrec bigint;root text;phase text;terminal_result jsonb;expires timestamptz;raword bigint;
BEGIN
 PERFORM 1 FROM private.dpdi_jobs WHERE id=j.id FOR UPDATE;SELECT * INTO prior FROM private.dpdi_job_pages WHERE job_id=j.id AND input_id=_input_id AND first_record=_first_record;
 IF FOUND THEN IF prior.wire IS DISTINCT FROM _wire OR prior.sha256 IS DISTINCT FROM _sha256 THEN RAISE EXCEPTION 'dpdi.immutable_page_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpdi_dto(j)||jsonb_build_object('page_replay',true);END IF;
 e:=private.dpdi_live_lease(j,_claim_key);input:=j.snapshot->'inputs'->e.input_index;total:=(input->>'rows_count')::bigint;
 IF input->>'input_id' IS DISTINCT FROM _input_id::text OR _first_record IS DISTINCT FROM e.next_record OR _wire IS NULL OR octet_length(_wire)>2097152 OR _sha256 IS DISTINCT FROM encode(sha256(convert_to(_wire,'UTF8')),'hex') THEN RAISE EXCEPTION 'dpdi.exact_bounded_page_required' USING ERRCODE='PT409';END IF;
 FOR line IN SELECT value FROM regexp_split_to_table(_wire,E'\n') AS l(value) WHERE value<>'' LOOP
  row:=line::jsonb;IF row->>'input_id' IS DISTINCT FROM _input_id::text OR row->>'original_file_id' IS DISTINCT FROM input->>'original_file_id' OR (row->>'record_index')::bigint IS DISTINCT FROM _first_record+n OR (row->>'source_row_ordinal')::bigint IS DISTINCT FROM (input->'selection'->>'data_start_row')::bigint+_first_record+n OR jsonb_typeof(row->'payload') IS DISTINCT FROM 'object' OR jsonb_typeof(row->'extras_json') IS DISTINCT FROM 'object' OR jsonb_typeof(row->'blocking') IS DISTINCT FROM 'boolean' OR jsonb_typeof(row->'reasons') IS DISTINCT FROM 'array' OR row->'excluded' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'dpdi.actual_original_lineage_and_strict_disposition_required' USING ERRCODE='PT409';END IF;
  raword:=(row->>'source_row_ordinal')::bigint;
  SELECT c.rows->((raword-c.start_row)::integer) INTO cells FROM private.dpd_original_chunks c WHERE c.file_id=(input->>'original_file_id')::uuid AND c.sheet_key=input->'selection'->>'sheet_key' AND c.start_row<=raword AND c.start_row+c.row_count>raword;
  IF cells IS NULL OR row->>'raw_row_sha256' IS DISTINCT FROM private.dpw_hash(cells) OR (row->>'source_row_id')::jsonb IS DISTINCT FROM jsonb_build_array(input->>'original_file_id',input->'selection'->>'sheet_key',raword::text) OR ((row->>'blocking')::boolean IS DISTINCT FROM (jsonb_array_length(row->'reasons')>0)) THEN RAISE EXCEPTION 'dpdi.exact_stored_raw_hash_identity_and_blocking_required' USING ERRCODE='PT409';END IF;
  n:=n+1;IF (row->>'blocking')::boolean THEN blocked:=blocked+1;END IF;
 END LOOP;
 IF n NOT BETWEEN 1 AND 1000 OR _first_record+n>total THEN RAISE EXCEPTION 'dpdi.complete_page_count_required';END IF;
 INSERT INTO private.dpdi_job_pages(job_id,sequence,input_id,first_record,row_count,blocking_count,wire,sha256) VALUES(j.id,e.output_pages+1,_input_id,_first_record,n,blocked,_wire,_sha256);
 nextidx:=e.input_index;nextrec:=e.next_record+n;IF nextrec=total THEN nextidx:=nextidx+1;nextrec:=0;END IF;
 WHILE nextidx<jsonb_array_length(j.snapshot->'inputs') AND (j.snapshot->'inputs'->nextidx->>'rows_count')::bigint=0 LOOP nextidx:=nextidx+1;END LOOP;
 root:=encode(sha256(convert_to(e.output_root_sha256||E'\t'||(e.output_pages+1)::text||E'\t'||n::text||E'\t'||_sha256||E'\n','UTF8')),'hex');phase:=CASE WHEN nextidx=jsonb_array_length(j.snapshot->'inputs') THEN CASE WHEN e.blocking_records+blocked>0 THEN 'blocked' ELSE 'success' END ELSE 'running' END;
 expires:=least(clock_timestamp()+interval '60 seconds',to_timestamp((_verified_subject->>'exp')::double precision));
 INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index,next_record,source_records,blocking_records,output_pages,output_root_sha256,last_page_sha256) VALUES(j.id,actor,phase,_claim_key,expires,nextidx,nextrec,e.source_records+n,e.blocking_records+blocked,e.output_pages+1,root,_sha256);
 IF phase IN('success','blocked') THEN
  IF e.source_records+n IS DISTINCT FROM (SELECT sum((x.value->>'rows_count')::bigint) FROM jsonb_array_elements(j.snapshot->'inputs') AS x(value)) THEN RAISE EXCEPTION 'dpdi.full_original_coverage_required';END IF;
  terminal_result:=jsonb_build_object('representation','dpdi_authoring_pages_v1','mode',j.snapshot->>'mode','job_id',j.id,'status',CASE WHEN phase='success' THEN 'success' ELSE 'failed' END,'publication_eligible',j.snapshot->>'mode'='prepare' AND phase='success','blocking_failure',phase='blocked','source_records',(e.source_records+n)::text,'blocking_records',(e.blocking_records+blocked)::text,'preview_rows',CASE WHEN phase='success' THEN (e.source_records+n)::text ELSE '0' END,'acceptedRows',NULL,'outputLineage',NULL,'structured_data_sha256',root,'hash_kind','immutable_page_prefix_sha256','page_count',e.output_pages+1,'full_final_ack',true);
  UPDATE public.data_prep_delivery_runs SET state=CASE WHEN phase='success' THEN 'success' ELSE 'failed' END,result=terminal_result,result_sha256=private.dpw_hash(terminal_result),finished_at=clock_timestamp() WHERE id=j.reserved_run_id AND state='running';
  IF j.snapshot->>'mode'='prepare' THEN UPDATE public.data_prep_delivery_batches SET state=CASE WHEN phase='success' THEN 'prepared' ELSE 'failed' END WHERE id=(j.snapshot->>'batch_id')::uuid AND state='processing';END IF;
  PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'preview.job.completed',j.id,jsonb_build_object('phase',phase,'source_records',(e.source_records+n)::text,'output_root_sha256',root,'publish_allowed',false));
 END IF;
 RETURN private.dpdi_dto(j)||jsonb_build_object('page_replay',false);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_preview_result_page(_tenant_id uuid, _setup_id uuid, _job_id uuid, _after_page integer, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.result',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,false);e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);p private.dpdi_job_pages%ROWTYPE;records jsonb;errors jsonb;
BEGIN
 IF _after_page IS NULL OR _after_page<0 THEN RAISE EXCEPTION 'dpdi.result_page_required';END IF;
 IF EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND NOT private.dpd_original_viewable(i.original_file_id)) THEN RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'execution_actor_id',j.actor_id,'state','unavailable','wire',NULL,'row_count',NULL,'preview_rows',NULL);END IF;
 IF e.phase NOT IN('success','blocked') THEN RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'execution_actor_id',j.actor_id,'state','pending','wire',NULL,'row_count',NULL,'preview_rows',NULL);END IF;
 SELECT * INTO p FROM private.dpdi_job_pages WHERE job_id=j.id AND sequence>_after_page ORDER BY sequence LIMIT 1;
 SELECT coalesce(jsonb_agg(x.value::jsonb ORDER BY x.ordinality),'[]'),coalesce(jsonb_agg(x.value::jsonb ORDER BY x.ordinality) FILTER(WHERE (x.value::jsonb->>'blocking')::boolean),'[]') INTO records,errors FROM regexp_split_to_table(coalesce(p.wire,''),E'\n') WITH ORDINALITY AS x(value,ordinality) WHERE x.value<>'';
 RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'execution_actor_id',j.actor_id,'state',CASE WHEN e.phase='blocked' THEN 'blocked' ELSE 'available' END,'page_sequence',p.sequence,'wire',CASE WHEN e.phase='success' THEN p.wire ELSE NULL END,'error_wire',CASE WHEN e.phase='blocked' THEN errors::text ELSE NULL END,'records',CASE WHEN e.phase='success' THEN records ELSE NULL END,'errors',errors,'error_count',jsonb_array_length(errors),'row_count',p.row_count,'sha256',p.sha256,'preview_rows',CASE WHEN e.phase='success' THEN e.source_records::text ELSE '0' END);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_next_owned_preview(_tenant_id uuid, _setup_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.next',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);j private.dpdi_jobs%ROWTYPE;e private.dpdi_job_events%ROWTYPE;
BEGIN
 SELECT q.* INTO j FROM private.dpdi_jobs q CROSS JOIN LATERAL private.dpdi_head(q.id) h WHERE q.tenant_id=_tenant_id AND q.setup_id=s.id AND h.phase IN('queued','running') ORDER BY q.created_at,q.id LIMIT 1;
 IF j.id IS NULL THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'mode','preview','publish_allowed',false,'state','no_pending_head','job',NULL);END IF;
 IF j.actor_id<>actor THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'mode','preview','publish_allowed',false,'state','other_actor_transport_required','job',NULL);END IF;
 PERFORM private.dpdi_authorize(_tenant_id,_setup_id,j.id,actor,false);e:=private.dpdi_head(j.id);
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'mode','preview','publish_allowed',false,'state',CASE WHEN e.phase='running' AND e.lease_expires_at>clock_timestamp() THEN 'owned_active' ELSE 'owned_ready_head' END,'job',private.dpdi_dto(j));
END $function$

CREATE OR REPLACE FUNCTION public.dpd_get_received_catalogue(_tenant_id uuid, _setup_id uuid, _draft_version integer, _selections jsonb, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'catalogue.read',_request_context_id);s private.dpd_setups%ROWTYPE:=private.dpd_scope(_tenant_id,_setup_id,false);v private.dpd_versions%ROWTYPE;f private.dpd_original_intents%ROWTYPE;sc private.dpd_schema_receipts%ROWTYPE;raw private.dpd_raw_source_links%ROWTYPE;selection jsonb;sheet jsonb;cells jsonb;headers jsonb;files jsonb:='[]';pins jsonb:='[]';state text:='available';file_state text;header_at bigint;start_at bigint;total bigint;selected integer:=0;catalog jsonb;
BEGIN
 SELECT * INTO v FROM private.dpd_versions WHERE setup_id=s.id ORDER BY version DESC LIMIT 1;
 IF v.version IS DISTINCT FROM _draft_version OR jsonb_typeof(_selections) IS DISTINCT FROM 'array' OR jsonb_array_length(_selections)>1000 OR (SELECT count(DISTINCT x.value->>'file_id') FROM jsonb_array_elements(_selections) AS x(value))<>jsonb_array_length(_selections) THEN RAISE EXCEPTION 'dpd.current_catalogue_version_selection_required' USING ERRCODE='PT409';END IF;
 FOR f IN SELECT * FROM private.dpd_original_intents WHERE setup_id=s.id AND tenant_id=_tenant_id ORDER BY created_at,id LOOP
  SELECT * INTO sc FROM private.dpd_schema_receipts WHERE file_id=f.id;SELECT * INTO raw FROM private.dpd_raw_source_links WHERE file_id=f.id;
  IF raw.data_source_id IS NOT NULL AND private.dpw_source_allows(actor,_tenant_id,raw.data_source_id,'view') IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpd.current_catalogue_source_read_denied' USING ERRCODE='42501';END IF;
  file_state:=CASE WHEN NOT private.dpd_original_viewable(f.id) THEN 'unavailable' WHEN NOT EXISTS(SELECT 1 FROM private.dpd_original_receipts WHERE file_id=f.id AND setup_id=s.id AND tenant_id=_tenant_id AND created_by=f.created_by) THEN 'receipt_pending' WHEN sc.file_id IS NULL THEN 'schema_pending' ELSE 'selection_required' END;
  SELECT x.value INTO selection FROM jsonb_array_elements(_selections) AS x(value) WHERE x.value->>'file_id'=f.id::text;
  IF file_state='selection_required' AND selection IS NOT NULL THEN
   IF selection->>'schema_sha256' IS DISTINCT FROM sc.schema_sha256 THEN RAISE EXCEPTION 'dpd.selected_schema_digest_changed_refresh_catalogue' USING ERRCODE='PT409';END IF;
   SELECT x.value INTO sheet FROM jsonb_array_elements(sc.schema_manifest->'sheet_inventory') AS x(value) WHERE x.value->>'sheet_key'=selection->>'sheet_key';
   IF sheet IS NULL OR coalesce(selection->>'header_row_index','')!~'^(0|[1-9][0-9]*)$' OR coalesce(selection->>'data_start_row','')!~'^(0|[1-9][0-9]*)$' THEN RAISE EXCEPTION 'dpd.explicit_actual_sheet_header_selection_required' USING ERRCODE='PT409';END IF;
   header_at:=(selection->>'header_row_index')::bigint;start_at:=(selection->>'data_start_row')::bigint;total:=(sheet->>'raw_row_count')::bigint;
   IF header_at>=total OR start_at<=header_at OR start_at>total THEN RAISE EXCEPTION 'dpd.actual_selected_source_range_required' USING ERRCODE='PT409';END IF;
   SELECT c.rows->((header_at-c.start_row)::integer) INTO cells FROM private.dpd_original_chunks c WHERE c.file_id=f.id AND c.sheet_key=sheet->>'sheet_key' AND c.start_row<=header_at AND c.start_row+c.row_count>header_at;
   IF cells IS NULL OR jsonb_typeof(cells) IS DISTINCT FROM 'array' OR jsonb_array_length(cells) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'dpd.actual_stored_header_cells_required' USING ERRCODE='PT409';END IF;
   IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(cells) AS h(value) WHERE btrim(h.value)='' OR h.value IS DISTINCT FROM btrim(h.value)) OR (SELECT count(DISTINCT h.value) FROM jsonb_array_elements_text(cells) AS h(value))<>jsonb_array_length(cells) THEN RAISE EXCEPTION 'dpd.explicit_unambiguous_nonblank_header_selection_required_choose_actual_header_row' USING ERRCODE='PT409';END IF;
   SELECT jsonb_agg(jsonb_build_object('ordinal',h.ordinality-1,'name',h.value,'inferred_type','string','nullable',false) ORDER BY h.ordinality) INTO headers FROM jsonb_array_elements_text(cells) WITH ORDINALITY AS h(value,ordinality);
   pins:=pins||jsonb_build_array(jsonb_build_object('file_id',f.id,'feed_key',f.feed_key,'original_request_key',f.request_key,'content_sha256',f.content_sha256,'storage_bucket',f.storage_bucket,'original_path',f.original_path,'schema_sha256',sc.schema_sha256,'sheet_key',sheet->>'sheet_key','header_row_index',header_at::text,'data_start_row',start_at::text,'total_raw_rows',total::text,'header_fields',headers,'data_source_id',raw.data_source_id));file_state:='available';selected:=selected+1;
  END IF;
  IF file_state<>'available' THEN state:=CASE WHEN file_state='unavailable' THEN 'unavailable' WHEN state='available' THEN file_state ELSE state END;END IF;
  files:=files||jsonb_build_array(jsonb_build_object('file_id',f.id,'feed_key',f.feed_key,'request_key',f.request_key,'content_sha256',f.content_sha256,'created_by',f.created_by,'state',file_state,'schema_sha256',sc.schema_sha256,'data_source_id',raw.data_source_id,'sheet_inventory',CASE WHEN private.dpd_original_viewable(f.id) THEN coalesce(sc.schema_manifest->'sheet_inventory','[]') ELSE NULL END,'selected_header_cells',CASE WHEN file_state='available' THEN cells ELSE NULL END,'source_type_provenance','actual_raw_string_cells_hint_not_declared_output_types'));
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(_selections) AS x(value) WHERE NOT EXISTS(SELECT 1 FROM private.dpd_original_intents original_row WHERE original_row.id=(x.value->>'file_id')::uuid AND original_row.setup_id=s.id AND original_row.tenant_id=_tenant_id)) THEN RAISE EXCEPTION 'dpd.catalogue_foreign_original_denied' USING ERRCODE='42501';END IF;
 IF jsonb_array_length(files)=0 THEN state:='receipt_pending';END IF;
 IF state='available' AND selected=jsonb_array_length(files) THEN catalog:=jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'draft_version',v.version,'state','available','complete',true,'originals',pins);END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',s.id,'draft_version',v.version,'state',state,'complete',catalog IS NOT NULL,'catalog',catalog,'catalog_sha256',CASE WHEN catalog IS NOT NULL THEN private.dpw_hash(catalog) ELSE NULL END,'files',files,'confirmed_mapping',NULL,'confirmed_mapping_required',false,'strict_output_types_inferred',false,'processor_capabilities',jsonb_build_object('unsupported_transform_kinds',jsonb_build_array('sort','dedupe','filter','filter_expr'),'independent_exclusions_supported',false,'reject_unsupported_before_save',true,'ordered_supported_transforms',true,'bounded_native_results',true),'publish_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_request_setup_review(_tenant_id uuid, _setup_id uuid, _draft_version integer, _job_id uuid, _approver_group_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.setup.request',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,true);head private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);r private.dpdi_setup_review_requests%ROWTYPE;
BEGIN
 IF j.draft_version<>_draft_version OR head.phase<>'success' OR head.blocking_records<>0 OR _request_key IS NULL OR NOT EXISTS(SELECT 1 FROM public.tenant_groups WHERE id=_approver_group_id AND tenant_id=_tenant_id) THEN RAISE EXCEPTION 'dpdi.full_current_successful_preview_review_required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM private.dpd_setups WHERE id=_setup_id FOR UPDATE;SELECT * INTO r FROM private.dpdi_setup_review_requests WHERE tenant_id=_tenant_id AND requested_by=actor AND request_key=_request_key;
 IF FOUND THEN IF r.setup_id<>_setup_id OR r.draft_version<>_draft_version OR r.job_id<>j.id OR r.approver_group_id<>_approver_group_id OR r.snapshot_sha256<>j.snapshot_sha256 THEN RAISE EXCEPTION 'dpdi.review_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpdi_review_dto(r,actor);END IF;
 INSERT INTO private.dpdi_setup_review_requests(tenant_id,setup_id,draft_version,job_id,approver_group_id,request_key,requested_by,snapshot,snapshot_sha256) VALUES(_tenant_id,_setup_id,_draft_version,j.id,_approver_group_id,_request_key,actor,j.snapshot,j.snapshot_sha256) RETURNING * INTO r;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'setup.review.requested',r.id,jsonb_build_object('job_id',j.id,'snapshot_sha256',j.snapshot_sha256,'approver_group_id',_approver_group_id));RETURN private.dpdi_review_dto(r,actor);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_get_setup_review(_tenant_id uuid, _setup_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'review.setup.read',_request_context_id);r private.dpdi_setup_review_requests%ROWTYPE;
BEGIN SELECT * INTO r FROM private.dpdi_setup_review_requests WHERE tenant_id=_tenant_id AND setup_id=_setup_id AND request_key=_request_key;
 IF r.id IS NULL THEN RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'state','absent','result',NULL,'publish_allowed',false);END IF;
 IF actor<>r.requested_by AND NOT EXISTS(SELECT 1 FROM public.tenant_group_members WHERE group_id=r.approver_group_id AND user_id=actor) THEN RAISE EXCEPTION 'dpdi.current_selected_reviewer_required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'state','found','result',private.dpdi_review_dto(r,actor),'publish_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION public.upsert_data_prep_pipeline_for_api(_tenant_id uuid, _pipeline_id uuid, _payload jsonb, _actor_user_id uuid)
 RETURNS TABLE(pipeline_id uuid, public_uid text, pipeline_status text, pipeline_version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target public.data_prep_pipelines%ROWTYPE;
  created public.data_prep_pipelines%ROWTYPE;
BEGIN
  PERFORM public.assert_data_prep_actor(_tenant_id,_actor_user_id,false);
  IF _payload IS NULL OR jsonb_typeof(_payload) <> 'object' THEN RAISE EXCEPTION 'Data Prep payload is required'; END IF;
  IF _pipeline_id IS NULL THEN
    INSERT INTO public.data_prep_pipelines(
      tenant_id,name,description,source_data_source_id,output_data_source_id,steps,dq_rules,
      on_failure,enabled,status,lifecycle_state,created_by
    ) VALUES (
      _tenant_id,_payload->>'name',nullif(_payload->>'description',''),
      nullif(_payload->>'source_data_source_id','')::uuid,nullif(_payload->>'output_data_source_id','')::uuid,
      coalesce(_payload->'steps','[]'::jsonb),coalesce(_payload->'dq_rules','[]'::jsonb),
      coalesce(_payload->>'on_failure','block'),coalesce((_payload->>'enabled')::boolean,true),
      'draft','production',_actor_user_id
    ) RETURNING * INTO created;
    INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
    VALUES (_actor_user_id,_tenant_id,'api','data_prep.create','data_prep_pipeline',created.id,
      jsonb_build_object('public_uid',created.public_uid,'version',created.version));
    RETURN QUERY SELECT created.id,created.public_uid,created.status,created.version;
    RETURN;
  END IF;
  SELECT * INTO target FROM public.data_prep_pipelines
  WHERE id=_pipeline_id AND tenant_id=_tenant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Data Prep pipeline not found'; END IF;
  -- Current registered scope remains authoritative after a group is revoked.
  IF EXISTS (
    SELECT 1 FROM public.data_resource_registry r
    WHERE r.tenant_id=_tenant_id AND r.data_prep_pipeline_id=_pipeline_id
  ) AND NOT EXISTS (
    SELECT 1 FROM public.data_resource_registry r
    WHERE r.tenant_id=_tenant_id AND r.data_prep_pipeline_id=_pipeline_id
      AND private.data_resource_shadow_allows_actor(_actor_user_id,r.id,'edit') IS TRUE
  ) THEN
    RAISE EXCEPTION 'Not authorized to edit this Data Prep pipeline' USING ERRCODE='42501';
  END IF;
  IF target.lifecycle_state='archived' THEN RAISE EXCEPTION 'Archived Data Prep pipeline cannot be edited'; END IF;
  IF target.promotion_status='pending' THEN RAISE EXCEPTION 'Pending promotion pipeline cannot be edited'; END IF;
  UPDATE public.data_prep_pipelines SET
    name=coalesce(_payload->>'name',target.name),
    description=CASE WHEN _payload ? 'description' THEN nullif(_payload->>'description','') ELSE target.description END,
    source_data_source_id=CASE WHEN _payload ? 'source_data_source_id' THEN nullif(_payload->>'source_data_source_id','')::uuid ELSE target.source_data_source_id END,
    output_data_source_id=CASE WHEN _payload ? 'output_data_source_id' THEN nullif(_payload->>'output_data_source_id','')::uuid ELSE target.output_data_source_id END,
    steps=coalesce(_payload->'steps',target.steps),dq_rules=coalesce(_payload->'dq_rules',target.dq_rules),
    on_failure=coalesce(_payload->>'on_failure',target.on_failure),
    enabled=coalesce((_payload->>'enabled')::boolean,target.enabled),
    status=CASE WHEN target.status='approved' THEN 'draft' ELSE target.status END,
    version=CASE WHEN target.status='approved' THEN coalesce(target.version,1)+1 ELSE target.version END,
    approved_at=CASE WHEN target.status='approved' THEN NULL ELSE target.approved_at END,
    approved_by=CASE WHEN target.status='approved' THEN NULL ELSE target.approved_by END
  WHERE id=_pipeline_id AND tenant_id=_tenant_id RETURNING * INTO created;
  INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context)
  VALUES (_actor_user_id,_tenant_id,'api','data_prep.update','data_prep_pipeline',created.id,
    jsonb_build_object('public_uid',created.public_uid,'version',created.version,'reapproval_required',target.status='approved'));
  RETURN QUERY SELECT created.id,created.public_uid,created.status,created.version;
END;
$function$

CREATE OR REPLACE FUNCTION public.dpdi_request_publication(_tenant_id uuid, _setup_id uuid, _job_id uuid, _setup_review_decision_id uuid, _approver_group_id uuid, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'publication.request',_request_context_id);j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,_job_id,actor,false);e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);r private.dpdi_publication_requests%ROWTYPE;
BEGIN
 IF j.snapshot->>'mode' IS DISTINCT FROM 'prepare' OR e.phase<>'success' OR e.blocking_records<>0 OR NOT EXISTS(SELECT 1 FROM private.dpdi_setup_review_decisions d JOIN private.dpdi_setup_review_requests q ON q.id=d.request_id WHERE d.id=_setup_review_decision_id AND d.decision='approved' AND q.tenant_id=_tenant_id AND q.setup_id=_setup_id AND q.draft_version=j.draft_version AND d.decided_by<>q.requested_by) OR NOT EXISTS(SELECT 1 FROM public.tenant_groups WHERE id=_approver_group_id AND tenant_id=_tenant_id) THEN RAISE EXCEPTION 'dpdi.actual_approved_prepare_origin_required_no_preview_publication' USING ERRCODE='42501';END IF;
 SELECT * INTO r FROM private.dpdi_publication_requests WHERE tenant_id=_tenant_id AND requested_by=actor AND request_key=_request_key;
 IF FOUND THEN IF r.job_id<>j.id OR r.setup_review_decision_id<>_setup_review_decision_id OR r.approver_group_id<>_approver_group_id OR r.output_root_sha256<>e.output_root_sha256 THEN RAISE EXCEPTION 'dpdi.publication_request_conflict' USING ERRCODE='PT409';END IF;ELSE INSERT INTO private.dpdi_publication_requests(tenant_id,setup_id,draft_version,job_id,setup_review_decision_id,approver_group_id,request_key,requested_by,output_root_sha256) VALUES(_tenant_id,_setup_id,j.draft_version,j.id,_setup_review_decision_id,_approver_group_id,_request_key,actor,e.output_root_sha256) RETURNING * INTO r;END IF;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'setup_id',_setup_id,'request_id',r.id,'status','pending','publication_performed',false);
END $function$

CREATE OR REPLACE FUNCTION private.fvi_seed_missing_group_presets(_tenant uuid, _bu uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
DECLARE p record;g uuid;r uuid;rk text;n integer:=0;
BEGIN
 PERFORM 1 FROM public.business_units b WHERE b.id=_bu AND b.tenant_id=_tenant AND NOT b.is_archived FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Select an active business unit in this tenant' USING ERRCODE='22023';END IF;
 FOR p IN SELECT * FROM public.tenant_group_presets WHERE is_default ORDER BY sort_order LOOP
   IF EXISTS(SELECT 1 FROM public.tenant_groups x WHERE x.tenant_id=_tenant AND x.preset_key=p.preset_key) THEN CONTINUE;END IF;
   INSERT INTO public.tenant_groups(tenant_id,name,description,is_system,preset_key,bu_id)
   VALUES(_tenant,p.name,p.description,true,p.preset_key,_bu)
   ON CONFLICT(tenant_id,preset_key) DO NOTHING RETURNING id INTO g;
   IF g IS NULL THEN CONTINUE;END IF;
   INSERT INTO public.bu_group_assignments(tenant_id,bu_id,group_id,role,inherit_descendants,created_by)
   VALUES(_tenant,_bu,g,'bu_member',false,auth.uid());
   FOREACH rk IN ARRAY p.role_keys LOOP
     SELECT id INTO r FROM public.rbac_roles WHERE key=rk AND is_system LIMIT 1;
     IF r IS NOT NULL THEN INSERT INTO public.tenant_group_roles(group_id,role_id) VALUES(g,r) ON CONFLICT DO NOTHING;END IF;
   END LOOP;
   n:=n+1;
 END LOOP;
 RETURN n;
END $function$

CREATE OR REPLACE FUNCTION public.seed_tenant_group_presets_for_bu(_tenant_id uuid, _bu_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'auth'
AS $function$
BEGIN
 IF NOT private.fvi_active_structure_admin(_tenant_id,auth.uid()) THEN
   RAISE EXCEPTION 'Active tenant administrator required for group presets' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM public.tenants WHERE id=_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Tenant not found' USING ERRCODE='22023';END IF;
 RETURN private.fvi_seed_missing_group_presets(_tenant_id,_bu_id);
END $function$

CREATE OR REPLACE FUNCTION public.seed_default_tenant_groups(_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_bu uuid;v_processed integer;
BEGIN
 PERFORM 1 FROM public.tenants WHERE id=_tenant_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Tenant not found' USING ERRCODE='22023';END IF;
 SELECT count(*) INTO v_processed FROM public.tenant_group_presets WHERE is_default;
 IF NOT EXISTS(SELECT 1 FROM public.tenant_group_presets p WHERE p.is_default AND NOT EXISTS(SELECT 1 FROM public.tenant_groups g WHERE g.tenant_id=_tenant_id AND g.preset_key=p.preset_key)) THEN RETURN v_processed;END IF;
 -- Explicit NEW foundation BU; no arbitrary old-BU selection or backfill.
 INSERT INTO public.business_units(tenant_id,name,code,description,created_by)
 VALUES(_tenant_id,'Preset groups business unit','FVI-PRESET-'||left(gen_random_uuid()::text,8),'Explicit foundation for newly seeded default groups',auth.uid()) RETURNING id INTO v_bu;
 PERFORM private.fvi_seed_missing_group_presets(_tenant_id,v_bu);
 RETURN v_processed;
END;
$function$

CREATE OR REPLACE FUNCTION public.dpdi_enqueue_approved_prepare(_tenant_id uuid, _setup_id uuid, _setup_review_decision_id uuid, _business_date date, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'prepare.job.enqueue',_request_context_id);r private.dpdi_setup_review_requests%ROWTYPE;d private.dpdi_setup_review_decisions%ROWTYPE;preview private.dpdi_jobs%ROWTYPE;j private.dpdi_jobs%ROWTYPE;batch public.data_prep_delivery_batches%ROWTYPE;snap jsonb;pipe uuid;
BEGIN
 PERFORM 1 FROM private.dpd_setups WHERE id=_setup_id AND tenant_id=_tenant_id AND created_by=actor FOR UPDATE;
 IF NOT FOUND OR _business_date IS NULL OR _request_key IS NULL THEN RAISE EXCEPTION 'dpdi.current_prepare_creator_and_explicit_business_date_required' USING ERRCODE='42501';END IF;
 SELECT * INTO d FROM private.dpdi_setup_review_decisions WHERE id=_setup_review_decision_id AND decision='approved';SELECT * INTO r FROM private.dpdi_setup_review_requests WHERE id=d.request_id AND tenant_id=_tenant_id AND setup_id=_setup_id;
 SELECT * INTO preview FROM private.dpdi_jobs WHERE id=r.job_id;
 IF r.id IS NULL OR d.decided_by=r.requested_by OR preview.snapshot_sha256<>d.snapshot_sha256 OR (SELECT max(version) FROM private.dpd_versions WHERE setup_id=_setup_id)<>r.draft_version THEN RAISE EXCEPTION 'dpdi.exact_current_human_approved_configuration_required' USING ERRCODE='42501';END IF;
 PERFORM private.dpdi_authorize(_tenant_id,_setup_id,preview.id,actor,true);pipe:=(preview.snapshot->>'pipeline_id')::uuid;
 IF NOT EXISTS(SELECT 1 FROM public.data_prep_pipelines p WHERE p.id=pipe AND p.tenant_id=_tenant_id AND p.status='approved' AND p.lifecycle_state='production' AND p.version=(preview.snapshot->>'pipeline_version')::integer) OR NOT EXISTS(SELECT 1 FROM public.data_prep_approved_configurations ac WHERE ac.tenant_id=_tenant_id AND ac.pipeline_id=pipe AND ac.pipeline_version=(preview.snapshot->>'pipeline_version')::integer AND ac.configuration_id=(preview.snapshot->>'configuration_id')::uuid AND ac.approved_by<>actor) THEN RAISE EXCEPTION 'dpdi.actual_governed_approved_production_transition_required_no_private_approval_waiver' USING ERRCODE='42501';END IF;
 SELECT * INTO j FROM private.dpdi_jobs WHERE tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key;
 IF FOUND THEN IF j.setup_id<>_setup_id OR j.snapshot->>'mode'<>'prepare' OR j.snapshot->>'setup_review_decision_id'<>d.id::text OR j.snapshot->>'business_date'<>_business_date::text THEN RAISE EXCEPTION 'dpdi.prepare_request_conflict' USING ERRCODE='PT409';END IF;RETURN private.dpdi_dto(j)||jsonb_build_object('request_replay',true);END IF;
 PERFORM private.dpd_assert_transform_configuration(preview.snapshot->'pipeline_configuration');
 INSERT INTO public.data_prep_delivery_batches(tenant_id,pipeline_id,pipeline_version,business_date,mode,execution_mode,human_in_loop,request_key,created_by,configuration_snapshot)
 VALUES(_tenant_id,pipe,(preview.snapshot->>'pipeline_version')::integer,_business_date,'prepare',(SELECT execution_mode FROM public.data_prep_delivery_batches WHERE id=(preview.snapshot->>'batch_id')::uuid),(SELECT human_in_loop FROM public.data_prep_delivery_batches WHERE id=(preview.snapshot->>'batch_id')::uuid),_request_key,actor,preview.snapshot||jsonb_build_object('approval_origin','dpdi_setup_review_v1','setup_review_decision_id',d.id)) RETURNING * INTO batch;
 snap:=preview.snapshot||jsonb_build_object('mode','prepare','business_date',_business_date,'batch_id',batch.id,'approval_origin','dpdi_setup_review_v1','setup_review_decision_id',d.id,'configuration_status','dpdi_review_approved','pipeline_status_actual',(SELECT status FROM public.data_prep_pipelines WHERE id=pipe),'publication_eligible',false);
 INSERT INTO private.dpdi_jobs(tenant_id,setup_id,draft_version,actor_id,request_key,snapshot,snapshot_sha256) VALUES(_tenant_id,_setup_id,r.draft_version,actor,_request_key,snap,private.dpw_hash(snap)) RETURNING * INTO j;
 INSERT INTO private.dpdi_job_events(job_id,actor_id,phase) VALUES(j.id,actor,'queued');PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'approved.prepare.queued',j.id,jsonb_build_object('approval_origin','dpdi_setup_review_v1','decision_id',d.id,'business_date',_business_date,'publish_allowed',false));RETURN private.dpdi_dto(j)||jsonb_build_object('request_replay',false);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_list_reviewer_requests(_tenant_id uuid, _kind text, _status text, _page integer, _page_size integer, _search text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,NULL,'review.queue.read',_request_context_id);amount bigint;items jsonb;ctx private.dpd_request_contexts%ROWTYPE;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 IF NOT EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=_tenant_id AND tm.user_id=actor AND tm.active AND tm.role='tenant_admin') THEN RAISE EXCEPTION 'dpdi.actual_tenant_admin_reviewer_required' USING ERRCODE='42501';END IF;
 IF _kind IS NULL OR _kind NOT IN('all','setup','publication') OR _status IS NULL OR _status NOT IN('all','pending','approved','rejected') OR _page IS NULL OR _page<1 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 100 OR _search IS NULL OR length(_search)>200 THEN RAISE EXCEPTION 'dpdi.bounded_reviewer_queue_required' USING ERRCODE='22023';END IF;
 WITH requests AS(SELECT 'setup'::text kind,r.id,r.created_at,r.job_id,r.request_key,coalesce(d.decision,'pending') status FROM private.dpdi_setup_review_requests r LEFT JOIN private.dpdi_setup_review_decisions d ON d.request_id=r.id WHERE r.tenant_id=_tenant_id UNION ALL SELECT 'publication',r.id,r.created_at,r.job_id,r.request_key,coalesce(d.decision,'pending') FROM private.dpdi_publication_requests r LEFT JOIN private.dpdi_publication_decisions d ON d.request_id=r.id WHERE r.tenant_id=_tenant_id),
 allowed AS MATERIALIZED(SELECT r.* FROM requests r JOIN private.dpdi_jobs j ON j.id=r.job_id JOIN public.data_prep_pipelines p ON p.id=(j.snapshot->>'pipeline_id')::uuid WHERE (_kind='all' OR r.kind=_kind) AND (_status='all' OR r.status=_status) AND (_search='' OR strpos(lower(p.name||' '||r.request_key::text),lower(_search))>0) AND private.dpdi_reviewer_visible(_tenant_id,r.kind,r.id,actor)),
 selected AS(SELECT * FROM allowed ORDER BY created_at DESC,id DESC LIMIT _page_size OFFSET (_page::bigint-1)*_page_size)
 SELECT (SELECT count(*) FROM allowed),coalesce(jsonb_agg(private.dpdi_reviewer_evidence(_tenant_id,kind,id,actor,_request_context_id,false) ORDER BY created_at DESC,id DESC),'[]') INTO amount,items FROM selected;
 SELECT * INTO ctx FROM private.dpd_request_contexts WHERE id=_request_context_id;
 RETURN jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'kind',_kind,'status_filter',_status,'page',_page,'page_size',_page_size,'search',_search,'total',amount::text,'requests',items,'current_context',jsonb_build_object('actor_id',actor,'tenant_id',_tenant_id,'operation','review.queue.read','issued_at',ctx.created_at,'expires_at',ctx.expires_at,'read_context_sha256',private.dpw_hash(jsonb_build_object('context',ctx.id,'actor',actor,'tenant',_tenant_id,'kind',_kind,'status',_status))));
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_read_reviewer_request(_tenant_id uuid, _setup_id uuid, _kind text, _request_id uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,CASE WHEN _kind='setup' THEN 'review.setup.read' WHEN _kind='publication' THEN 'publication.read' ELSE NULL END,_request_context_id);r jsonb:=private.dpdi_reviewer_reference(_tenant_id,_kind,_request_id);
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 IF r IS NULL OR r->>'setup_id' IS DISTINCT FROM _setup_id::text THEN RAISE EXCEPTION 'dpdi.actual_selected_reviewer_request_required' USING ERRCODE='42501';END IF;
 RETURN private.dpdi_reviewer_evidence(_tenant_id,_kind,_request_id,actor,_request_context_id);
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_read_reviewer_records(_tenant_id uuid, _setup_id uuid, _request_kind text, _request_id uuid, _kind text, _page integer, _page_size integer, _search text, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,CASE WHEN _request_kind='setup' THEN 'review.setup.read' WHEN _request_kind='publication' THEN 'publication.read' ELSE NULL END,_request_context_id);
 frame jsonb:=private.dpdi_reviewer_frame(_tenant_id,_request_kind,_request_id,actor);
 j private.dpdi_jobs%ROWTYPE:=private.dpdi_authorize(_tenant_id,_setup_id,(frame->>'job_id')::uuid,actor,false);
 e private.dpdi_job_events%ROWTYPE:=private.dpdi_head(j.id);off bigint;amount bigint;records jsonb;proofs jsonb;cols jsonb;needle text;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);
 IF frame->'reference'->>'setup_id' IS DISTINCT FROM _setup_id::text THEN RAISE EXCEPTION 'dpdi.actual_reviewer_setup_binding_required' USING ERRCODE='42501';END IF;
 IF frame->>'availability' IN('expired','stale') THEN RETURN private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false)||jsonb_build_object('state','unavailable','records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search);END IF;
 IF _kind NOT IN('rows','errors') OR _kind IS NULL OR _page IS NULL OR _page<1 OR _page_size IS NULL OR _page_size NOT BETWEEN 1 AND 100 OR _search IS NULL OR char_length(_search)>200 THEN RAISE EXCEPTION 'dpdi.bounded_record_page_required' USING ERRCODE='22023';END IF;
 off:=(_page::bigint-1)*_page_size;
 IF EXISTS(SELECT 1 FROM private.dpdi_run_inputs i WHERE i.job_id=j.id AND NOT private.dpd_original_viewable(i.original_file_id)) THEN
  RETURN jsonb_build_object('request_id',_request_id,'request_kind',_request_kind,'current_context',(private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false))->'current_context')||private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','unavailable','kind',_kind,'records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 IF e.phase NOT IN('success','blocked') THEN
  RETURN jsonb_build_object('request_id',_request_id,'request_kind',_request_kind,'current_context',(private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false))->'current_context')||private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','pending','kind',_kind,'records',NULL,'columns',NULL,'total',NULL,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 IF e.phase='blocked' AND _kind='rows' THEN
  RETURN jsonb_build_object('request_id',_request_id,'request_kind',_request_kind,'current_context',(private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false))->'current_context')||private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','blocked','kind',_kind,'records',NULL,'columns',NULL,'total','0','page',_page,'page_size',_page_size,'search',_search,'page_proofs',NULL);
 END IF;
 SELECT CASE WHEN _kind='rows' THEN coalesce(jsonb_agg(v.value->>'name' ORDER BY v.ordinality),'[]')||jsonb_build_array('extras_json') ELSE ' ["input_id","original_file_id","record_index","source_row_ordinal","reasons","payload","extras_json"]'::jsonb END INTO cols
 FROM jsonb_array_elements(j.snapshot->'confirmed_mapping'->'output_schema') WITH ORDINALITY v(value,ordinality);
 needle:=lower(_search);
 IF needle='' THEN
  amount:=CASE WHEN _kind='rows' THEN e.source_records ELSE e.blocking_records END;
  -- Prefix sums cover at most the small page-metadata set, not all source records.
  WITH metadata AS(
   SELECT p.*,CASE WHEN _kind='rows' THEN p.row_count ELSE p.blocking_count END n,
    coalesce(sum(CASE WHEN _kind='rows' THEN p.row_count ELSE p.blocking_count END) OVER(ORDER BY p.sequence ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0)::bigint first_index
   FROM private.dpdi_job_pages p WHERE p.job_id=j.id
  ), relevant AS(SELECT * FROM metadata WHERE first_index<off+_page_size AND first_index+n>off),
  decoded AS(SELECT p.*,x.ordinality,x.value::jsonb record FROM relevant p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY x(value,ordinality) WHERE x.value<>''),
  filtered AS(SELECT *,row_number() OVER(PARTITION BY sequence ORDER BY ordinality)-1 item_index FROM decoded WHERE _kind='rows' OR record->'blocking'='true'::jsonb),
  selected AS(SELECT * FROM filtered WHERE first_index+item_index>=off AND first_index+item_index<off+_page_size)
  SELECT coalesce(jsonb_agg(record ORDER BY sequence,ordinality),'[]'),coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',sequence,'row_count',row_count,'sha256',sha256) ORDER BY sequence) FROM relevant),'[]') INTO records,proofs FROM selected;
 ELSE
  -- Search is over the complete authorised collection. No client loaded-row subset.
  WITH decoded AS(SELECT p.sequence,p.row_count,p.sha256,x.ordinality,x.value::jsonb record FROM private.dpdi_job_pages p CROSS JOIN LATERAL regexp_split_to_table(p.wire,E'\n') WITH ORDINALITY x(value,ordinality) WHERE p.job_id=j.id AND x.value<>''),
  matches AS(SELECT * FROM decoded WHERE (_kind='rows' OR record->'blocking'='true'::jsonb) AND strpos(lower(CASE WHEN _kind='rows' THEN ((record->'payload')||jsonb_build_object('extras_json',record->'extras_json'))::text ELSE record::text END),needle)>0),
  selected AS(SELECT * FROM matches ORDER BY sequence,ordinality LIMIT _page_size OFFSET off)
  SELECT (SELECT count(*) FROM matches),coalesce(jsonb_agg(record ORDER BY sequence,ordinality),'[]'),coalesce((SELECT jsonb_agg(jsonb_build_object('sequence',p.sequence,'row_count',p.row_count,'sha256',p.sha256) ORDER BY p.sequence) FROM(SELECT DISTINCT sequence,row_count,sha256 FROM selected)p),'[]') INTO amount,records,proofs FROM selected;
 END IF;
 IF jsonb_array_length(records)>_page_size THEN RAISE EXCEPTION 'dpdi.record_page_overflow';END IF;
 RETURN jsonb_build_object('request_id',_request_id,'request_kind',_request_kind,'current_context',(private.dpdi_reviewer_evidence(_tenant_id,_request_kind,_request_id,actor,_request_context_id,false))->'current_context')||private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'state','available','kind',_kind,'records',records,'columns',cols,'total',amount::text,'page',_page,'page_size',_page_size,'search',_search,'page_proofs',proofs);
END $function$

CREATE OR REPLACE FUNCTION public.dpd_issue_request_context(_tenant_id uuid, _verified_subject jsonb, _trusted_ip text, _ttl_seconds integer, _operation text, _setup_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid;enabled boolean;ip inet;expires timestamptz;c private.dpd_request_contexts%ROWTYPE;write boolean;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR current_setting('role',true) IS DISTINCT FROM 'service_role' OR _ttl_seconds IS NULL OR _ttl_seconds NOT BETWEEN 1 AND 60
 OR (_operation IN('setup.create','setup.read','setup.lookup','setup.save','original.authorize','original.claim','original.lookup','original.read','original.rows','source.register','preview.bind','preview.lookup','audit.read','original.confirm','original.chunk','original.schema','parser.enqueue','parser.lookup','parser.claim','parser.progress','preview.input','mapping.read','review.shared.read','review.shared.decide','preview.job.enqueue','preview.job.claim','preview.job.input','preview.job.unique','preview.job.commit','preview.job.release','preview.job.cancel','preview.job.status','preview.job.result','preview.job.next','catalogue.read','review.setup.request','review.setup.read','review.setup.decide','prepare.job.enqueue','publication.request','publication.read','publication.decide','publication.perform','publication.dataset.read','review.queue.read')) IS DISTINCT FROM true
 OR (_setup_id IS NULL AND _operation NOT IN('setup.create','setup.lookup','review.queue.read')) THEN RAISE EXCEPTION 'dpd.fixed_closed_request_context_required' USING ERRCODE='42501';END IF;
 actor:=private.dpd_peer_actor(_tenant_id,_verified_subject);IF _operation='review.queue.read' AND NOT EXISTS(SELECT 1 FROM public.tenant_members tm WHERE tm.tenant_id=_tenant_id AND tm.user_id=actor AND tm.active AND tm.role='tenant_admin') THEN RAISE EXCEPTION 'dpdi.actual_tenant_admin_queue_required' USING ERRCODE='42501';END IF;IF _operation IN('review.shared.read','review.shared.decide','review.queue.read') THEN PERFORM public.assert_data_prep_actor(_tenant_id,actor,true);END IF;write:=_operation IN('setup.create','setup.save','original.authorize','original.claim','source.register','preview.bind','original.confirm','original.chunk','original.schema','parser.enqueue','parser.claim','parser.progress','review.shared.decide','preview.job.enqueue','preview.job.claim','preview.job.unique','preview.job.commit','preview.job.release','preview.job.cancel','review.setup.request','review.setup.decide','prepare.job.enqueue','publication.request','publication.decide','publication.perform');IF write THEN PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);END IF;
 IF public.user_has_permission(actor,_tenant_id,CASE WHEN write THEN 'data.prep.author' ELSE 'data.prep.read' END,NULL) IS DISTINCT FROM true
 OR (_setup_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private.dpd_setups WHERE id=_setup_id AND tenant_id=_tenant_id AND (created_by=actor OR (_operation IN('preview.job.status','preview.job.result') AND EXISTS(SELECT 1 FROM private.dpd_preview_links read_link WHERE read_link.setup_id=_setup_id AND read_link.tenant_id=_tenant_id AND private.data_prep_pipeline_scope_allows(actor,_tenant_id,read_link.pipeline_id,'view') IS TRUE)) OR _operation IN('review.shared.read','review.shared.decide') OR (_operation IN('review.setup.read','review.setup.decide','publication.read','publication.decide') AND private.dpdi_review_reader(_tenant_id,_setup_id,actor)) OR (_operation='publication.dataset.read' AND EXISTS(SELECT 1 FROM private.dpdi_published_datasets ds WHERE ds.setup_id=_setup_id AND ds.tenant_id=_tenant_id AND private.data_prep_pipeline_scope_allows(actor,_tenant_id,ds.pipeline_id,'view') IS TRUE))))) THEN RAISE EXCEPTION 'dpd.context_current_scope_denied' USING ERRCODE='42501';END IF;
 SELECT ip_allowlist_enabled INTO enabled FROM public.tenant_security_settings WHERE tenant_id=_tenant_id;IF NOT FOUND OR enabled IS NULL THEN RAISE EXCEPTION 'dpd.current_network_policy_unavailable' USING ERRCODE='42501';END IF;
 BEGIN ip:=nullif(_trusted_ip,'')::inet;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'dpd.trusted_transport_ip_invalid' USING ERRCODE='42501';END;
 IF enabled AND (ip IS NULL OR public.ip_in_tenant_allowlist(_tenant_id,host(ip)) IS DISTINCT FROM true) THEN RAISE EXCEPTION 'dpd.current_network_denied' USING ERRCODE='42501';END IF;
 expires:=least(clock_timestamp()+_ttl_seconds*interval '1 second',to_timestamp((_verified_subject->>'exp')::double precision));IF expires<=clock_timestamp() THEN RAISE EXCEPTION 'dpd.subject_expired' USING ERRCODE='42501';END IF;
 c.id:=gen_random_uuid();
 INSERT INTO private.dpd_request_contexts(id,token_sha256,tenant_id,actor_id,verified_subject,operation,setup_id,intent_sha256,transport_kind,request_ip,transport_attestation_sha256,expires_at)
 VALUES(c.id,encode(sha256(convert_to(c.id::text,'UTF8')),'hex'),_tenant_id,actor,_verified_subject,_operation,_setup_id,private.dpw_hash(jsonb_build_object('operation',_operation,'setup_id',_setup_id)),
 'main_fixed_service_verified_middleware_CF_transport',ip,private.dpw_hash(jsonb_build_object('actor',actor,'tenant',_tenant_id,'operation',_operation,'setup',_setup_id,'issuer_role','service_role')),expires) RETURNING * INTO c;
 INSERT INTO public.audit_log(actor_user_id,tenant_id,scope,action,resource_type,resource_id,context) VALUES(actor,_tenant_id,'workspace','dpd.request_context.issued','data_prep_authoring_context',c.id::text,jsonb_build_object('operation',_operation,'setup_id',_setup_id,'expires_at',expires,'network_policy_enabled',enabled,'issuer_transport','service_role','browser_issuance_allowed',false));
 RETURN jsonb_build_object('request_context_id',c.id,'actor_id',actor,'tenant_id',_tenant_id,'operation',_operation,'setup_id',_setup_id,'expires_at',expires,'network_policy_available',true,'network_policy_enabled',enabled,'network_allowed',true,'issuer_transport','service_role','verified_subject_expires_at',to_timestamp((_verified_subject->>'exp')::double precision),'browser_issuance_allowed',false);
END $function$

CREATE OR REPLACE FUNCTION private.dpd_transform_issues(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE entry record;step jsonb;definition jsonb;parameter jsonb;value jsonb;issues jsonb:='[]';location jsonb;
BEGIN
 IF jsonb_typeof(_payload->'steps') IS DISTINCT FROM 'array' OR jsonb_typeof(_payload->'feeds') IS DISTINCT FROM 'array' THEN
  RETURN jsonb_build_array(jsonb_build_object('path','[]'::jsonb,'code','configuration_step_arrays_required'));
 END IF;
 FOR entry IN
  SELECT x.value step,jsonb_build_array('steps',x.ordinality-1) path FROM jsonb_array_elements(_payload->'steps') WITH ORDINALITY x(value,ordinality)
  UNION ALL
  SELECT x.value,jsonb_build_array('feeds',f.ordinality-1,'steps',x.ordinality-1) FROM jsonb_array_elements(_payload->'feeds') WITH ORDINALITY f(value,ordinality)
   CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(f.value->'steps')='array' THEN f.value->'steps' ELSE '[]'::jsonb END) WITH ORDINALITY x(value,ordinality)
 LOOP
  step:=entry.step;location:=entry.path;definition:=private.dpd_canonical_transform_catalog()->(step->>'kind');
  IF jsonb_typeof(step) IS DISTINCT FROM 'object' OR definition IS NULL THEN
   issues:=issues||jsonb_build_array(jsonb_build_object('path',location||jsonb_build_array('kind'),'code','unknown_transform_kind','kind',step->>'kind'));CONTINUE;
  END IF;
  FOR parameter IN SELECT p.value FROM jsonb_array_elements(definition->'params') p(value) LOOP
   value:=step->(parameter->>'name');IF value IS NULL OR value='null'::jsonb THEN value:=step->'params'->(parameter->>'name');END IF;
   IF coalesce((parameter->>'required')::boolean,false) AND (value IS NULL OR value='null'::jsonb OR value='""'::jsonb OR value='[]'::jsonb) THEN
    issues:=issues||jsonb_build_array(jsonb_build_object('path',location||jsonb_build_array(parameter->>'name'),'code','required_transform_parameter'));CONTINUE;
   END IF;
   IF value IS NULL OR value='null'::jsonb OR value='""'::jsonb THEN CONTINUE;END IF;
   IF (parameter->>'kind'='csv' AND (jsonb_typeof(value)<>'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(value)='array' THEN value ELSE '[]'::jsonb END) v(cell) WHERE jsonb_typeof(v.cell)<>'string' OR btrim(v.cell#>>'{}')='')))
    OR (parameter->>'kind'='number' AND jsonb_typeof(value)<>'number')
    OR (parameter->>'kind'='select' AND (jsonb_typeof(value)<>'string' OR NOT(parameter->'options' @> jsonb_build_array(value)))) THEN
    issues:=issues||jsonb_build_array(jsonb_build_object('path',location||jsonb_build_array(parameter->>'name'),'code','transform_parameter_domain'));
   END IF;
  END LOOP;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(_payload->'feeds') f WHERE f ? 'steps' AND jsonb_typeof(f->'steps') IS DISTINCT FROM 'array') THEN
  issues:=issues||jsonb_build_array(jsonb_build_object('path',jsonb_build_array('feeds','steps'),'code','configuration_step_arrays_required'));
 END IF;
 RETURN issues;
END $function$

CREATE OR REPLACE FUNCTION public.dpdi_cancel_owned_job(_tenant_id uuid, _setup_id uuid, _job_id uuid, _expected_snapshot_sha256 text, _expected_head_event_id bigint, _claim_key uuid, _reason_code text, _request_key uuid, _request_context_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE actor uuid:=private.dpd_request_actor(_tenant_id,_setup_id,'preview.job.cancel',_request_context_id);
 j private.dpdi_jobs%ROWTYPE;e private.dpdi_job_events%ROWTYPE;t private.dpdi_terminal_intents%ROWTYPE;
 run public.data_prep_delivery_runs%ROWTYPE;issues jsonb;terminal_result jsonb;phase text;event_id bigint;
BEGIN
 PERFORM public.assert_data_prep_actor(_tenant_id,actor,false);
 IF public.user_has_permission(actor,_tenant_id,'data.prep.author',NULL) IS DISTINCT FROM true THEN RAISE EXCEPTION 'dpdi.current_author_required_for_owned_terminal_intent' USING ERRCODE='42501';END IF;
 SELECT * INTO j FROM private.dpdi_jobs WHERE id=_job_id AND tenant_id=_tenant_id AND setup_id=_setup_id AND actor_id=actor FOR UPDATE;
 IF j.id IS NULL THEN RAISE EXCEPTION 'dpdi.actual_owned_job_required' USING ERRCODE='42501';END IF;
 -- Read authorization retains the exact historical configuration without requiring
 -- the latest draft version. Cancellation adds current RUN and source INGEST gates.
 PERFORM private.dpdi_authorize(_tenant_id,_setup_id,j.id,actor,false);
 IF private.data_prep_pipeline_scope_allows(actor,_tenant_id,(j.snapshot->>'pipeline_id')::uuid,'run') IS DISTINCT FROM true
 OR EXISTS(SELECT 1 FROM private.dpd_preview_file_links i WHERE i.setup_id=j.setup_id AND i.draft_version=j.draft_version AND
  (private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'view') IS DISTINCT FROM true OR private.dpw_source_allows(actor,_tenant_id,i.data_source_id,'ingest') IS DISTINCT FROM true))
 OR EXISTS(SELECT 1 FROM jsonb_array_elements(j.snapshot->'inputs') pin(value) WHERE NOT EXISTS(
  SELECT 1 FROM private.dpd_preview_file_links i WHERE i.setup_id=j.setup_id AND i.draft_version=j.draft_version
   AND i.id::text=pin.value->>'input_id' AND i.data_source_id::text=pin.value->>'data_source_id'
   AND i.original_file_id::text=pin.value->>'original_file_id' AND i.selection_sha256 IS NOT DISTINCT FROM pin.value->>'selection_sha256'))
 THEN RAISE EXCEPTION 'dpdi.current_snapshot_source_run_authority_required' USING ERRCODE='42501';END IF;
 IF _request_key IS NULL OR _expected_head_event_id IS NULL OR _expected_snapshot_sha256 IS DISTINCT FROM j.snapshot_sha256
 OR private.dpw_hash(j.snapshot) IS DISTINCT FROM j.snapshot_sha256 OR _reason_code IS NULL OR _reason_code NOT IN('invalid_configuration','owner_cancelled')
 THEN RAISE EXCEPTION 'dpdi.exact_terminal_snapshot_intent_required' USING ERRCODE='PT409';END IF;
 SELECT * INTO t FROM private.dpdi_terminal_intents WHERE job_id=j.id OR (tenant_id=_tenant_id AND actor_id=actor AND request_key=_request_key);
 IF FOUND THEN
  IF t.job_id<>j.id OR t.request_key<>_request_key OR t.snapshot_sha256<>_expected_snapshot_sha256 OR t.previous_head_event_id<>_expected_head_event_id
   OR t.claim_key IS DISTINCT FROM _claim_key OR t.reason_code<>_reason_code THEN RAISE EXCEPTION 'dpdi.immutable_terminal_request_conflict' USING ERRCODE='PT409';END IF;
  RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'head_event_id',t.event_id::text,'terminal_intent',private.dpdi_terminal_intent_dto(t),'request_replay',true,'released_rows','0','publish_allowed',false);
 END IF;
 e:=private.dpdi_head(j.id);
 IF e.id<>_expected_head_event_id OR e.phase NOT IN('queued','running') THEN RAISE EXCEPTION 'dpdi.terminal_head_changed_status_first' USING ERRCODE='PT409';END IF;
 IF e.phase='running' AND e.lease_expires_at>clock_timestamp() AND (e.claim_key IS DISTINCT FROM _claim_key OR _claim_key IS NULL)
 THEN RAISE EXCEPTION 'dpdi.live_owned_claim_required_for_cancellation' USING ERRCODE='42501';END IF;
 issues:=private.dpd_transform_issues(j.snapshot->'pipeline_configuration');
 IF _reason_code='invalid_configuration' AND jsonb_array_length(issues)=0 THEN RAISE EXCEPTION 'dpdi.native_invalid_configuration_evidence_required' USING ERRCODE='22023';END IF;
 phase:=CASE WHEN _reason_code='invalid_configuration' THEN 'blocked' ELSE 'cancelled' END;
 SELECT * INTO run FROM public.data_prep_delivery_runs WHERE id=j.reserved_run_id AND tenant_id=_tenant_id FOR UPDATE;
 IF run.id IS NOT NULL AND run.state<>'running' THEN RAISE EXCEPTION 'dpdi.terminal_run_state_changed' USING ERRCODE='PT409';END IF;
 INSERT INTO private.dpdi_job_events(job_id,actor_id,phase,claim_key,lease_expires_at,input_index,next_record,source_records,blocking_records,output_pages,output_root_sha256,last_page_sha256)
 VALUES(j.id,actor,phase,e.claim_key,clock_timestamp(),e.input_index,e.next_record,e.source_records,e.blocking_records,e.output_pages,e.output_root_sha256,e.last_page_sha256) RETURNING id INTO event_id;
 INSERT INTO private.dpdi_terminal_intents(tenant_id,setup_id,job_id,actor_id,request_key,snapshot_sha256,previous_head_event_id,event_id,claim_key,reason_code,phase,validation_issues)
 VALUES(_tenant_id,_setup_id,j.id,actor,_request_key,j.snapshot_sha256,e.id,event_id,_claim_key,_reason_code,phase,issues) RETURNING * INTO t;
 terminal_result:=jsonb_build_object('representation','dpdi_configuration_terminal_v1','job_id',j.id,'status',CASE WHEN phase='blocked' THEN 'failed' ELSE 'cancelled' END,
  'terminal_reason_code',_reason_code,'validation_issues',issues,'snapshot_sha256',j.snapshot_sha256,'terminal_event_id',event_id::text,
  'full_final_ack',true,'full_original_rescan',false,'source_records',e.source_records::text,'blocking_records',e.blocking_records::text,
  'configuration_blocking_failure',phase='blocked','blocking_failure',true,'accepted_records','0','preview_rows','0','released_rows','0','publication_eligible',false,'acceptedRows',NULL,'outputLineage',NULL);
 IF run.id IS NOT NULL THEN UPDATE public.data_prep_delivery_runs SET state='failed',result=terminal_result,result_sha256=private.dpw_hash(terminal_result),finished_at=clock_timestamp() WHERE id=run.id;END IF;
 IF j.snapshot->>'mode'='prepare' THEN UPDATE public.data_prep_delivery_batches SET state='failed' WHERE id=(j.snapshot->>'batch_id')::uuid AND tenant_id=_tenant_id AND state='processing';END IF;
 PERFORM private.dpd_event(_tenant_id,_setup_id,actor,'job.terminal_intent.recorded',j.id,jsonb_build_object('intent_id',t.id,'request_key',t.request_key,'snapshot_sha256',j.snapshot_sha256,'previous_head_event_id',e.id::text,'event_id',event_id::text,'reason_code',_reason_code,'phase',phase,'validation_issues',issues,'publish_allowed',false));
 RETURN private.dpdi_dto(j)||jsonb_build_object('actor_id',actor,'head_event_id',event_id::text,'terminal_intent',private.dpdi_terminal_intent_dto(t),'request_replay',false,'released_rows','0','publish_allowed',false);
END $function$
